        private static string ModRoot => Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ".."));
        private static string ModsParentDir => Directory.GetParent(ModRoot)!.FullName;

        internal static readonly string[] SubModFolderNames =
        {
            "[GCF]Rathalos",
            "[GCF]Valstrax",
            "[GCF]Mech Colossus",
            "[GCF]Panzer IV",
            "[GCF]Protoss Carrier"
        };

        internal static IEnumerable<string> AllModRoots()
        {
            yield return ModRoot;
            for (int i = 0; i < SubModFolderNames.Length; i++)
            {
                yield return Path.Combine(ModsParentDir, SubModFolderNames[i]);
            }
        }

        internal static IEnumerable<string> AllMod17Roots()
        {
            foreach (string root in AllModRoots())
            {
                string p17 = Path.Combine(root, "1.7");
                if (Directory.Exists(p17))
                {
                    yield return p17;
                }
            }
        }

        internal static string[] EnumerateAllMod17Files(string subRelativeDir, string pattern, SearchOption opt = SearchOption.TopDirectoryOnly)
        {
            var results = new List<string>();
            foreach (string p17 in AllMod17Roots())
            {
                string dir = string.IsNullOrEmpty(subRelativeDir) ? p17 : Path.Combine(p17, subRelativeDir);
                if (Directory.Exists(dir))
                {
                    results.AddRange(Directory.GetFiles(dir, pattern, opt));
                }
            }
            return results.ToArray();
        }

        internal static Dictionary<string, string> LoadMergedKeyedMap(string lang)
        {
            var dict = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (string p17 in AllMod17Roots())
            {
                string keyedDir = Path.Combine(p17, "Languages", lang, "Keyed");
                if (!Directory.Exists(keyedDir)) continue;
                foreach (string xmlFile in Directory.GetFiles(keyedDir, "*.xml"))
                {
                    XDocument d = XDocument.Load(xmlFile);
                    if (d.Root == null) continue;
                    foreach (XElement el in d.Root.Elements())
                    {
                        dict[el.Name.LocalName] = el.Value;
                    }
                }
            }
            return dict;
        }

        internal static string ResolveMod17Path(params string[] relativeParts)
        {
            string rel = Path.Combine(relativeParts);
            string fwCandidate = Path.Combine(ModRoot, "1.7", rel);
            if (File.Exists(fwCandidate) || Directory.Exists(fwCandidate))
            {
                return fwCandidate;
            }
            for (int i = 0; i < SubModFolderNames.Length; i++)
            {
                string subCandidate = Path.Combine(ModsParentDir, SubModFolderNames[i], "1.7", rel);
                if (File.Exists(subCandidate) || Directory.Exists(subCandidate))
                {
                    return subCandidate;
                }
            }
            return fwCandidate;
        }

        private static string ReadCompGiantRigSource()
        {
            string componentsDir = Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Components");
            return string.Join(Environment.NewLine,
                Directory.EnumerateFiles(componentsDir, "CompGiantRig*.cs")
                    .OrderBy(path => path, StringComparer.Ordinal)
                    .Select(File.ReadAllText));
        }

        private static void EnsureHeadlessRimWorldStubsInitialized()
        {
            FieldInfo prefsDataField = typeof(Prefs).GetField("data", BindingFlags.Static | BindingFlags.NonPublic);
            if (prefsDataField != null && prefsDataField.GetValue(null) == null)
            {
                prefsDataField.SetValue(null, new PrefsData());
            }

            FieldInfo saveDataField = typeof(GenFilePaths).GetField("saveDataPath", BindingFlags.Static | BindingFlags.NonPublic);
            FieldInfo modsFolderField = typeof(GenFilePaths).GetField("modsFolderPath", BindingFlags.Static | BindingFlags.NonPublic);
            FieldInfo officialModsField = typeof(GenFilePaths).GetField("officialModsFolderPath", BindingFlags.Static | BindingFlags.NonPublic);

            if ((saveDataField != null && saveDataField.GetValue(null) == null)
                || (modsFolderField != null && modsFolderField.GetValue(null) == null)
                || (officialModsField != null && officialModsField.GetValue(null) == null))
            {
                string stubRoot = Path.Combine(Path.GetTempPath(), "GCF_HeadlessRwStub_" + Environment.ProcessId);
                string saveDir = Path.Combine(stubRoot, "SaveData");
                string configDir = Path.Combine(saveDir, "Config");
                string modsDir = Path.Combine(stubRoot, "Mods");
                string dataDir = Path.Combine(stubRoot, "Data");
                string coreAboutDir = Path.Combine(dataDir, "Core", "About");

                Directory.CreateDirectory(configDir);
                Directory.CreateDirectory(modsDir);
                Directory.CreateDirectory(coreAboutDir);

                string coreAboutXml = Path.Combine(coreAboutDir, "About.xml");
                if (!File.Exists(coreAboutXml))
                {
                    File.WriteAllText(
                        coreAboutXml,
                        "<?xml version=\"1.0\" encoding=\"utf-8\"?><ModMetaData><name>Core</name><packageId>ludeon.rimworld</packageId></ModMetaData>");
                }

                if (saveDataField != null && saveDataField.GetValue(null) == null)
                {
                    saveDataField.SetValue(null, saveDir);
                }
                if (modsFolderField != null && modsFolderField.GetValue(null) == null)
                {
                    modsFolderField.SetValue(null, modsDir);
                }
                if (officialModsField != null && officialModsField.GetValue(null) == null)
                {
                    officialModsField.SetValue(null, dataDir);
                }
            }
        }

