        private static void RunTest(string name, Action test)
        {
            if (!string.IsNullOrEmpty(testFilter) && name.IndexOf(testFilter, StringComparison.OrdinalIgnoreCase) < 0)
            {
                return;
            }
            try
            {
                test();
                passed++;
                Console.WriteLine($"[PASS] {name}");
            }
            catch (Exception ex)
            {
                failed++;
                Console.WriteLine($"[FAIL] {name}");
                Console.WriteLine($"       {ex}");
            }
        }

        private static void Assert(bool condition, string message)
        {
            if (!condition)
            {
                throw new InvalidOperationException($"Assertion failed: {message}");
            }
        }

        private static void AssertNear(float actual, float expected, float tol, string message)
        {
            if (MathF.Abs(actual - expected) > tol)
            {
                throw new InvalidOperationException($"{message} (expected {expected:F6}, got {actual:F6}, diff {MathF.Abs(actual - expected):E3})");
            }
        }

        private static (GiantRigDef rig, TextureAlphaMask[] masks, Dictionary<string, GiantAnimDef> anims) LoadMechScorpionFromXml()
        {
            return LoadRigFromXml("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml");
        }


        internal static (GiantRigDef rig, TextureAlphaMask[] masks, Dictionary<string, GiantAnimDef> anims) LoadRigFromXml(string rigFile, string animFile, string rigDefName = null)
        {
            string rigXmlPath = ResolveMod17Path("Defs", "GiantRigDefs", rigFile);
            string animXmlPath = ResolveMod17Path("Defs", "GiantAnimDefs", animFile);
            Assert(File.Exists(rigXmlPath), $"Missing {rigXmlPath}");
            Assert(File.Exists(animXmlPath), $"Missing {animXmlPath}");

            var anims = new Dictionary<string, GiantAnimDef>(StringComparer.Ordinal);
            XDocument animDoc = XDocument.Load(animXmlPath);
            foreach (XElement el in animDoc.Root.Elements("GiantCreatureFramework.GiantAnimDef"))
            {
                var anim = new GiantAnimDef
                {
                    defName = el.Element("defName")?.Value,
                    label = el.Element("label")?.Value,
                    durationTicks = ParseFloat(el.Element("durationTicks")?.Value, 60f),
                    loop = ParseBool(el.Element("loop")?.Value, true),
                    blendInTicks = (int)ParseFloat(el.Element("blendInTicks")?.Value, 8f),
                    triggerToolTag = el.Element("triggerToolTag")?.Value,
                    impactTick = ParseFloat(el.Element("impactTick")?.Value, -1f),
                    isolatedSubtreeRootBoneId = el.Element("isolatedSubtreeRootBoneId")?.Value,
                    actingSubtreeRootBoneId = el.Element("actingSubtreeRootBoneId")?.Value,
                    coupledBodyMotionFactor = ParseFloat(el.Element("coupledBodyMotionFactor")?.Value, -1f)
                };

                XElement tracksEl = el.Element("tracks");
                if (tracksEl != null)
                {
                    foreach (XElement trEl in tracksEl.Elements("li"))
                    {
                        var track = new BoneAnimTrack
                        {
                            nodeId = trEl.Element("nodeId")?.Value
                        };
                        XElement kfsEl = trEl.Element("keyframes");
                        if (kfsEl != null)
                        {
                            foreach (XElement kfEl in kfsEl.Elements("li"))
                            {
                                var kf = new BoneKeyframe
                                {
                                    tick = ParseFloat(kfEl.Element("tick")?.Value, 0f),
                                    angle = ParseFloat(kfEl.Element("angle")?.Value, 0f),
                                    sagittalPitch = ParseFloat(kfEl.Element("sagittalPitch")?.Value, 0f),
                                    coronalFlap = ParseFloat(kfEl.Element("coronalFlap")?.Value, 0f),
                                    offset = ParseVec2(kfEl.Element("offset")?.Value, Vector2.zero),
                                    scale = ParseVec2(kfEl.Element("scale")?.Value, Vector2.one),
                                    easing = kfEl.Element("easing") != null
                                        ? Enum.Parse<AnimEasing>(kfEl.Element("easing").Value, ignoreCase: true)
                                        : AnimEasing.SmoothStep
                                };
                                track.keyframes.Add(kf);
                            }
                        }
                        anim.tracks.Add(track);
                    }
                }
                XElement eventsEl = el.Element("events");
                if (eventsEl != null)
                {
                    foreach (XElement evEl in eventsEl.Elements("li"))
                    {
                        var ev = new GiantAnimEventDef
                        {
                            tick = ParseFloat(evEl.Element("tick")?.Value, 0f),
                            boneId = evEl.Element("boneId")?.Value,
                            socketId = evEl.Element("socketId")?.Value,
                            emitterId = evEl.Element("emitterId")?.Value,
                            useBoneMuzzle = ParseBool(evEl.Element("useBoneMuzzle")?.Value, false),
                            angleOffset = ParseFloat(evEl.Element("angleOffset")?.Value, 0f),
                            uv = ParseVec2(evEl.Element("uv")?.Value, new Vector2(0.5f, 0.5f)),
                            pixel = ParseVec2(evEl.Element("pixel")?.Value, new Vector2(-9999f, -9999f)),
                            scale = ParseFloat(evEl.Element("scale")?.Value, 1f),
                            cameraShake = ParseFloat(evEl.Element("cameraShake")?.Value, 0f)
                        };
                        string presetStr = evEl.Element("vfxPreset")?.Value;
                        if (!string.IsNullOrEmpty(presetStr) &&
                            Enum.TryParse(presetStr, true, out GiantAnimVfxPreset preset))
                        {
                            ev.vfxPreset = preset;
                        }
                        anim.events.Add(ev);
                    }
                }
                anims[anim.defName] = anim;
            }

            XDocument rigDoc = XDocument.Load(rigXmlPath);
            XElement rigEl = string.IsNullOrEmpty(rigDefName)
                ? rigDoc.Root.Element("GiantCreatureFramework.GiantRigDef")
                : rigDoc.Root.Elements("GiantCreatureFramework.GiantRigDef").FirstOrDefault(e => e.Element("defName")?.Value == rigDefName);
            Assert(rigEl != null, $"Missing GiantRigDef element {rigDefName ?? "(first)"} in XML");

            var rig = new GiantRigDef
            {
                defName = rigEl.Element("defName")?.Value,
                label = rigEl.Element("label")?.Value,
                turnSpeedDegPerTick = ParseFloat(rigEl.Element("turnSpeedDegPerTick")?.Value, 2.25f),
                enablePivotTurnBeforeMove = ParseBool(rigEl.Element("enablePivotTurnBeforeMove")?.Value, true),
                pivotTurnEnterAngleDeg = ParseFloat(rigEl.Element("pivotTurnEnterAngleDeg")?.Value, 32f),
                pivotTurnExitAngleDeg = ParseFloat(rigEl.Element("pivotTurnExitAngleDeg")?.Value, 9f),
                movingTurnSpeedFactor = ParseFloat(rigEl.Element("movingTurnSpeedFactor")?.Value, 0.65f),
                hitCoverageThreshold = ParseFloat(rigEl.Element("hitCoverageThreshold")?.Value, 0.08f),
                pawnExclusionCoverageThreshold = ParseFloat(rigEl.Element("pawnExclusionCoverageThreshold")?.Value, 0.16f),
                collisionCoverageThreshold = ParseFloat(rigEl.Element("collisionCoverageThreshold")?.Value, 0.45f),
                enableDynamicMeleeContactLunge = ParseBool(rigEl.Element("enableDynamicMeleeContactLunge")?.Value, true),
                maxDynamicMeleeContactLungeCells = ParseFloat(rigEl.Element("maxDynamicMeleeContactLungeCells")?.Value, 0.85f),
                collisionPathCost = (int)ParseFloat(rigEl.Element("collisionPathCost")?.Value, 10000f),
                coreClearanceRadius = (int)ParseFloat(rigEl.Element("coreClearanceRadius")?.Value, 1f),
                footprintUpdateIntervalTicks = (int)ParseFloat(rigEl.Element("footprintUpdateIntervalTicks")?.Value, 2f),
                walkCycleDistance = ParseFloat(rigEl.Element("walkCycleDistance")?.Value, 2.5f),
                runCycleDistance = ParseFloat(rigEl.Element("runCycleDistance")?.Value, 3.2f),
                turnCycleAngleDeg = ParseFloat(rigEl.Element("turnCycleAngleDeg")?.Value, 42f),
                turnCorneringBlendMax = ParseFloat(rigEl.Element("turnCorneringBlendMax")?.Value, 0.42f),
                portraitScaleFactor = ParseFloat(rigEl.Element("portraitScaleFactor")?.Value, 0.32f),
                useCoupledSagittalKinematics = ParseBool(rigEl.Element("useCoupledSagittalKinematics")?.Value, false),
                partAnimBodyCoupling = ParseFloat(rigEl.Element("partAnimBodyCoupling")?.Value, -1f),
                bodyCouplingRefBodySize = ParseFloat(rigEl.Element("bodyCouplingRefBodySize")?.Value, 2.0f),
                bodyCouplingSizeExponent = ParseFloat(rigEl.Element("bodyCouplingSizeExponent")?.Value, 0.85f),
                minAutoBodyCoupling = ParseFloat(rigEl.Element("minAutoBodyCoupling")?.Value, 0.08f),
                rushWhenEnemyFar = ParseBool(rigEl.Element("rushWhenEnemyFar")?.Value, true),
                rushStartDistance = ParseFloat(rigEl.Element("rushStartDistance")?.Value, 12f),
                rushStopDistance = ParseFloat(rigEl.Element("rushStopDistance")?.Value, 7f),
                rushMoveSpeedMultiplier = ParseFloat(rigEl.Element("rushMoveSpeedMultiplier")?.Value, 1.65f),
                crushBuildingsAndTerrain = ParseBool(rigEl.Element("crushBuildingsAndTerrain")?.Value, true),
                canCrushNaturalRock = ParseBool(rigEl.Element("canCrushNaturalRock")?.Value, true),
                canCrushConstructedBuildings = ParseBool(rigEl.Element("canCrushConstructedBuildings")?.Value, true),
                canCrushDestructibleTerrain = ParseBool(rigEl.Element("canCrushDestructibleTerrain")?.Value, true),
                crushDamagePerStep = (int)ParseFloat(rigEl.Element("crushDamagePerStep")?.Value, 450f),
                crushIntervalTicks = (int)ParseFloat(rigEl.Element("crushIntervalTicks")?.Value, 12f),
                meleeTouchRadius = ParseFloat(rigEl.Element("meleeTouchRadius")?.Value, 0f),
                useDirectionalMeleeTools = ParseBool(rigEl.Element("useDirectionalMeleeTools")?.Value, true),
                lateralViewHalfAngleDeg = ParseFloat(rigEl.Element("lateralViewHalfAngleDeg")?.Value, 45f),
                lateralViewHysteresisDeg = ParseFloat(rigEl.Element("lateralViewHysteresisDeg")?.Value, 6f),
                shadowTexPath = rigEl.Element("shadowTexPath")?.Value?.Trim(),
                shadowDrawSize = ParseVec2(rigEl.Element("shadowDrawSize")?.Value, Vector2.zero),
                shadowAlpha = ParseFloat(rigEl.Element("shadowAlpha")?.Value, 0.42f),
                shadowOffsetXZ = ParseVec2(rigEl.Element("shadowOffsetXZ")?.Value, new Vector2(0.36f, -0.42f)),
                renderGroundShadowWhenGrounded = ParseBool(rigEl.Element("renderGroundShadowWhenGrounded")?.Value, false),
                painImmune = ParseBool(rigEl.Element("painImmune")?.Value, false),
                painScaleFactor = ParseFloat(rigEl.Element("painScaleFactor")?.Value, 1f),
                painShockThresholdOverride = ParseFloat(rigEl.Element("painShockThresholdOverride")?.Value, -1f),
                minSeveredBonesForPainShock = (int)ParseFloat(rigEl.Element("minSeveredBonesForPainShock")?.Value, 1f),
                unseveredPainShockMaxHealthPct = ParseFloat(rigEl.Element("unseveredPainShockMaxHealthPct")?.Value, 0.25f),
                onlyDieWhenCoreDestroyed = ParseBool(rigEl.Element("onlyDieWhenCoreDestroyed")?.Value, false)
            };

            if (rigEl.Element("idleAnim") != null && anims.TryGetValue(rigEl.Element("idleAnim").Value, out var idle))
                rig.idleAnim = idle;
            if (rigEl.Element("walkAnim") != null && anims.TryGetValue(rigEl.Element("walkAnim").Value, out var walk))
                rig.walkAnim = walk;
            if (rigEl.Element("runAnim") != null && anims.TryGetValue(rigEl.Element("runAnim").Value, out var run))
                rig.runAnim = run;
            if (rigEl.Element("turnLeftAnim") != null && anims.TryGetValue(rigEl.Element("turnLeftAnim").Value, out var turnLeft))
                rig.turnLeftAnim = turnLeft;
            if (rigEl.Element("turnRightAnim") != null && anims.TryGetValue(rigEl.Element("turnRightAnim").Value, out var turnRight))
                rig.turnRightAnim = turnRight;
            if (rigEl.Element("rangedAttackAnim") != null && anims.TryGetValue(rigEl.Element("rangedAttackAnim").Value, out var ranged))
                rig.rangedAttackAnim = ranged;
            rig.rangedWeaponBoneId = rigEl.Element("rangedWeaponBoneId")?.Value;
            rig.healthBarTitleOverride = rigEl.Element("healthBarTitleOverride")?.Value;
            string hbDefName = rigEl.Element("healthBarDef")?.Value?.Trim();
            if (!string.IsNullOrEmpty(hbDefName))
            {
                var hbDefs = LoadHealthBarDefsFromXml();
                if (hbDefs.TryGetValue(hbDefName, out GiantHealthBarDef hbDef))
                {
                    rig.healthBarDef = hbDef;
                }
            }
            if (rigEl.Element("weaponEmitters") != null)
            {
                foreach (XElement emEl in rigEl.Element("weaponEmitters").Elements("li"))
                {
                    var em = new GiantWeaponEmitterDef
                    {
                        emitterId = emEl.Element("emitterId")?.Value,
                        weaponDefName = emEl.Element("weaponDefName")?.Value,
                        abilityDefName = emEl.Element("abilityDefName")?.Value,
                        verbTag = emEl.Element("verbTag")?.Value,
                        requireAllBonesIntact = ParseBool(emEl.Element("requireAllBonesIntact")?.Value, false),
                        replaceVanillaMuzzleFlash = ParseBool(emEl.Element("replaceVanillaMuzzleFlash")?.Value, true),
                        spawnMuzzleVfxOnLaunch = ParseBool(emEl.Element("spawnMuzzleVfxOnLaunch")?.Value, true),
                        vfxScale = ParseFloat(emEl.Element("vfxScale")?.Value, 1f)
                    };
                    if (Enum.TryParse(emEl.Element("fireMode")?.Value, true, out GiantEmitterFireMode fm))
                    {
                        em.fireMode = fm;
                    }
                    if (Enum.TryParse(emEl.Element("vfxPresetOverride")?.Value, true, out GiantAnimVfxPreset vp))
                    {
                        em.vfxPresetOverride = vp;
                    }
                    if (emEl.Element("barrels") != null)
                    {
                        foreach (XElement bEl in emEl.Element("barrels").Elements("li"))
                        {
                            em.barrels.Add(new GiantEmitterBarrelDef
                            {
                                boneId = bEl.Element("boneId")?.Value,
                                socketId = bEl.Element("socketId")?.Value,
                                uvOverride = ParseVec2(bEl.Element("uvOverride")?.Value, new Vector2(-9999f, -9999f)),
                                pixelOverride = ParseVec2(bEl.Element("pixelOverride")?.Value, new Vector2(-9999f, -9999f)),
                                angleOffsetOverride = ParseFloat(bEl.Element("angleOffsetOverride")?.Value, -9999f),
                                vfxScaleMultiplier = ParseFloat(bEl.Element("vfxScaleMultiplier")?.Value, 1f)
                            });
                        }
                    }
                    rig.weaponEmitters.Add(em);
                }
            }
            if (rigEl.Element("downedAnim") != null && anims.TryGetValue(rigEl.Element("downedAnim").Value, out var downed))
                rig.downedAnim = downed;
            if (rigEl.Element("deathAnim") != null && anims.TryGetValue(rigEl.Element("deathAnim").Value, out var death))
                rig.deathAnim = death;
            if (rigEl.Element("meleeAttackAnims") != null)
            {
                foreach (XElement mEl in rigEl.Element("meleeAttackAnims").Elements("li"))
                {
                    if (anims.TryGetValue(mEl.Value, out var ma))
                        rig.meleeAttackAnims.Add(ma);
                }
            }
            if (rigEl.Element("abilityAnims") != null)
            {
                foreach (XElement aEl in rigEl.Element("abilityAnims").Elements("li"))
                {
                    if (anims.TryGetValue(aEl.Value, out var aa))
                        rig.abilityAnims.Add(aa);
                }
            }

            foreach (XElement nEl in rigEl.Element("nodes").Elements("li"))
            {
                var node = new BoneNodeDef
                {
                    nodeId = nEl.Element("nodeId")?.Value,
                    label = nEl.Element("label")?.Value,
                    parentId = nEl.Element("parentId")?.Value,
                    texPath = nEl.Element("texPath")?.Value,
                    textureResolution = (int)ParseFloat(nEl.Element("textureResolution")?.Value, 512f),
                    drawSize = ParseVec2(nEl.Element("drawSize")?.Value, Vector2.one),
                    pivotPixel = ParseVec2(nEl.Element("pivotPixel")?.Value, new Vector2(-9999f, -9999f)),
                    parentSocketPixel = ParseVec2(nEl.Element("parentSocketPixel")?.Value, new Vector2(-9999f, -9999f)),
                    muzzleUV = ParseVec2(nEl.Element("muzzleUV")?.Value, new Vector2(0.5f, 0.88f)),
                    muzzlePixel = ParseVec2(nEl.Element("muzzlePixel")?.Value, new Vector2(-9999f, -9999f)),
                    muzzleAngleOffset = ParseFloat(nEl.Element("muzzleAngleOffset")?.Value, 0f),
                    baseAngle = ParseFloat(nEl.Element("baseAngle")?.Value, 0f),
                    continuousSpinDegPerTick = ParseFloat(nEl.Element("continuousSpinDegPerTick")?.Value, 0f),
                    isReactorCoreBone = ParseBool(nEl.Element("isReactorCoreBone")?.Value, false),
                    lethalWhenDestroyed = ParseBool(nEl.Element("lethalWhenDestroyed")?.Value, false),
                    glowTexPath = nEl.Element("glowTexPath")?.Value,
                    silhouetteTexPath = nEl.Element("silhouetteTexPath")?.Value,
                    silhouetteLayerOffset = ParseFloat(nEl.Element("silhouetteLayerOffset")?.Value, -9.2f),
                    layerOffset = ParseFloat(nEl.Element("layerOffset")?.Value, 0f),
                    hideWhenMissing = ParseBool(nEl.Element("hideWhenMissing")?.Value, true),
                    isRigid = ParseBool(nEl.Element("isRigid")?.Value, false),
                    sagittalDropCells = ParseFloat(nEl.Element("sagittalDropCells")?.Value, 0f),
                    isCoronalFlapHinge = ParseBool(nEl.Element("isCoronalFlapHinge")?.Value, false),
                    baseCoronalFlap = ParseFloat(nEl.Element("baseCoronalFlap")?.Value, 0f),
                    isTurret = ParseBool(nEl.Element("isTurret")?.Value, false),
                    maxTurretAimAngleDeg = ParseFloat(nEl.Element("maxTurretAimAngleDeg")?.Value, 180f),
                    isLocomotionDrivePart = ParseBool(nEl.Element("isLocomotionDrivePart")?.Value, false),
                    locomotionSideSign = ParseFloat(nEl.Element("locomotionSideSign")?.Value, 0f),
                    isFlightLiftPart = ParseBool(nEl.Element("isFlightLiftPart")?.Value, false),
                    contributesToHitbox = ParseBool(nEl.Element("contributesToHitbox")?.Value, true),
                    contributesToCollision = ParseBool(nEl.Element("contributesToCollision")?.Value, true),
                    alphaThreshold = (byte)ParseFloat(nEl.Element("alphaThreshold")?.Value, 32f),
                    linkedBodyPart = string.IsNullOrWhiteSpace(nEl.Element("linkedBodyPart")?.Value)
                        ? null
                        : new BodyPartDef { defName = nEl.Element("linkedBodyPart")!.Value.Trim(), label = nEl.Element("linkedBodyPart")!.Value.Trim() },
                    linkedBodyPartCustomLabel = string.IsNullOrWhiteSpace(nEl.Element("linkedBodyPartCustomLabel")?.Value)
                        ? null
                        : nEl.Element("linkedBodyPartCustomLabel")!.Value.Trim(),
                    linkedBodyPartIndex = (int)ParseFloat(nEl.Element("linkedBodyPartIndex")?.Value, -1f),
                    damageMultiplier = ParseFloat(nEl.Element("damageMultiplier")?.Value, 1f),
                    armorMultiplier = ParseFloat(nEl.Element("armorMultiplier")?.Value, 1f),
                    deflectChance = ParseFloat(nEl.Element("deflectChance")?.Value, 0f),
                    aimAtTargetWeight = ParseFloat(nEl.Element("aimAtTargetWeight")?.Value, 0f),
                    aimMaxAngle = ParseFloat(nEl.Element("aimMaxAngle")?.Value, 35f),
                    aimReferenceAngleOffset = ParseFloat(nEl.Element("aimReferenceAngleOffset")?.Value, 0f),
                    sectorSourceBoneId = string.IsNullOrWhiteSpace(nEl.Element("sectorSourceBoneId")?.Value) ? null : nEl.Element("sectorSourceBoneId")!.Value.Trim()
                };
                static List<GiantBoneEmitterSocketDef> ParseEmitterSockets(XElement container)
                {
                    var list = new List<GiantBoneEmitterSocketDef>();
                    if (container == null) return list;
                    foreach (XElement sEl in container.Elements("li"))
                    {
                        var sock = new GiantBoneEmitterSocketDef
                        {
                            socketId = sEl.Element("socketId")?.Value,
                            uv = ParseVec2(sEl.Element("uv")?.Value, new Vector2(0.5f, 0.88f)),
                            pixel = ParseVec2(sEl.Element("pixel")?.Value, new Vector2(-9999f, -9999f)),
                            angleOffset = ParseFloat(sEl.Element("angleOffset")?.Value, 0f),
                            vfxScale = ParseFloat(sEl.Element("vfxScale")?.Value, 1f)
                        };
                        if (Enum.TryParse(sEl.Element("vfxPreset")?.Value, true, out GiantAnimVfxPreset svp))
                        {
                            sock.vfxPreset = svp;
                        }
                        list.Add(sock);
                    }
                    return list;
                }
                static BoneDirectionalVariantDef ParseDirectionalVariant(XElement vEl)
                {
                    if (vEl == null) return null;
                    var v = new BoneDirectionalVariantDef
                    {
                        texPath = vEl.Element("texPath")?.Value,
                        glowTexPath = vEl.Element("glowTexPath")?.Value,
                        silhouetteTexPath = vEl.Element("silhouetteTexPath")?.Value
                    };
                    if (vEl.Element("drawSize") != null) v.drawSize = ParseVec2(vEl.Element("drawSize")?.Value, Vector2.one);
                    if (vEl.Element("pivotUV") != null) v.pivotUV = ParseVec2(vEl.Element("pivotUV")?.Value, new Vector2(0.5f, 0.5f));
                    if (vEl.Element("pivotPixel") != null) v.pivotPixel = ParseVec2(vEl.Element("pivotPixel")?.Value, new Vector2(-9999f, -9999f));
                    if (vEl.Element("parentSocketUV") != null) v.parentSocketUV = ParseVec2(vEl.Element("parentSocketUV")?.Value, new Vector2(0.5f, 0.5f));
                    if (vEl.Element("parentSocketPixel") != null) v.parentSocketPixel = ParseVec2(vEl.Element("parentSocketPixel")?.Value, new Vector2(-9999f, -9999f));
                    if (vEl.Element("layerOffset") != null) v.layerOffset = ParseFloat(vEl.Element("layerOffset")?.Value, 0f);
                    if (vEl.Element("muzzleUV") != null) v.muzzleUV = ParseVec2(vEl.Element("muzzleUV")?.Value, new Vector2(0.5f, 0.88f));
                    if (vEl.Element("muzzlePixel") != null) v.muzzlePixel = ParseVec2(vEl.Element("muzzlePixel")?.Value, new Vector2(-9999f, -9999f));
                    if (vEl.Element("muzzleAngleOffset") != null) v.muzzleAngleOffset = ParseFloat(vEl.Element("muzzleAngleOffset")?.Value, 0f);
                    if (vEl.Element("persistentVfxUV") != null) v.persistentVfxUV = ParseVec2(vEl.Element("persistentVfxUV")?.Value, new Vector2(0.5f, 0.5f));
                    if (vEl.Element("persistentVfxPixel") != null) v.persistentVfxPixel = ParseVec2(vEl.Element("persistentVfxPixel")?.Value, new Vector2(-9999f, -9999f));
                    if (vEl.Element("emitterSockets") != null) v.emitterSockets = ParseEmitterSockets(vEl.Element("emitterSockets"));
                    return v;
                }
                if (Enum.TryParse(nEl.Element("muzzleVfxPreset")?.Value, true, out GiantAnimVfxPreset mvp))
                {
                    node.muzzleVfxPreset = mvp;
                }
                if (nEl.Element("emitterSockets") != null)
                {
                    node.emitterSockets.AddRange(ParseEmitterSockets(nEl.Element("emitterSockets")));
                }
                if (nEl.Element("crewSeats") != null)
                {
                    foreach (XElement csEl in nEl.Element("crewSeats")!.Elements("li"))
                    {
                        var cs = new GiantBoneCrewSeatDef
                        {
                            seatId = csEl.Element("seatId")?.Value,
                            mountUV = ParseVec2(csEl.Element("mountUV")?.Value, new Vector2(-9999f, -9999f)),
                            mountPixel = ParseVec2(csEl.Element("mountPixel")?.Value, new Vector2(-9999f, -9999f)),
                            localOffset = ParseVec2(csEl.Element("localOffset")?.Value, Vector2.zero),
                            screenOffset = ParseVec2(csEl.Element("screenOffset")?.Value, Vector2.zero),
                            facingOffsetDeg = ParseFloat(csEl.Element("facingOffsetDeg")?.Value, 0f),
                            layerOffset = ParseFloat(csEl.Element("layerOffset")?.Value, 8.0f),
                            drawScale = ParseFloat(csEl.Element("drawScale")?.Value, 1.0f),
                            renderOccupant = ParseBool(csEl.Element("renderOccupant")?.Value, true),
                            renderAboveAllParts = ParseBool(csEl.Element("renderAboveAllParts")?.Value, true),
                            rotateSpriteWithBone = ParseBool(csEl.Element("rotateSpriteWithBone")?.Value, false),
                            renderOccupantWeapon = ParseBool(csEl.Element("renderOccupantWeapon")?.Value, false)
                        };
                        node.crewSeats.Add(cs);
                    }
                }
                if (nEl.Element("partAttacks") != null)
                {
                    foreach (XElement paEl in nEl.Element("partAttacks").Elements("li"))
                    {
                        var pa = new GiantPartAttackDef
                        {
                            attackId = paEl.Element("attackId")?.Value,
                            label = paEl.Element("label")?.Value,
                            warmupTime = ParseFloat(paEl.Element("warmupTime")?.Value, 0.45f),
                            cooldownTime = ParseFloat(paEl.Element("cooldownTime")?.Value, 2.2f),
                            initialPhaseOffset01 = ParseFloat(paEl.Element("initialPhaseOffset01")?.Value, 0f),
                            minRange = ParseFloat(paEl.Element("minRange")?.Value, 0f),
                            range = ParseFloat(paEl.Element("range")?.Value, 3.6f),
                            sectorCenterDeg = ParseFloat(paEl.Element("sectorCenterDeg")?.Value, 0f),
                            sectorHalfAngleDeg = ParseFloat(paEl.Element("sectorHalfAngleDeg")?.Value, 180f),
                            requireLineOfSight = ParseBool(paEl.Element("requireLineOfSight")?.Value, true),
                            socketId = paEl.Element("socketId")?.Value,
                            rangeOriginBoneId = paEl.Element("rangeOriginBoneId")?.Value,
                            independentOverlay = ParseBool(paEl.Element("independentOverlay")?.Value, false),
                            strikeUV = ParseVec2(paEl.Element("strikeUV")?.Value, new Vector2(0.5f, 0.85f)),
                            strikePixel = ParseVec2(paEl.Element("strikePixel")?.Value, new Vector2(-9999f, -9999f)),
                            useSoftWhipTip = ParseBool(paEl.Element("useSoftWhipTip")?.Value, false),
                            projectileDef = string.IsNullOrWhiteSpace(paEl.Element("projectileDef")?.Value)
                                ? null
                                : new ThingDef { defName = paEl.Element("projectileDef")!.Value.Trim() },
                            burstShotCount = (int)ParseFloat(paEl.Element("burstShotCount")?.Value, 1f),
                            ticksBetweenBurstShots = (int)ParseFloat(paEl.Element("ticksBetweenBurstShots")?.Value, 8f),
                            forcedMissRadius = ParseFloat(paEl.Element("forcedMissRadius")?.Value, 0f),
                            accuracyTouch = ParseFloat(paEl.Element("accuracyTouch")?.Value, 0.88f),
                            accuracyShort = ParseFloat(paEl.Element("accuracyShort")?.Value, 0.84f),
                            accuracyMedium = ParseFloat(paEl.Element("accuracyMedium")?.Value, 0.76f),
                            accuracyLong = ParseFloat(paEl.Element("accuracyLong")?.Value, 0.66f),
                            spawnMuzzleVfx = ParseBool(paEl.Element("spawnMuzzleVfx")?.Value, true),
                            vfxScale = ParseFloat(paEl.Element("vfxScale")?.Value, 1.0f),
                            damageDef = string.IsNullOrWhiteSpace(paEl.Element("damageDef")?.Value)
                                ? null
                                : new DamageDef { defName = paEl.Element("damageDef")!.Value.Trim() },
                            power = ParseFloat(paEl.Element("power")?.Value, 30f),
                            armorPenetration = ParseFloat(paEl.Element("armorPenetration")?.Value, 0.45f),
                            cleaveRadius = ParseFloat(paEl.Element("cleaveRadius")?.Value, 0f),
                            cleaveDamageFactor = ParseFloat(paEl.Element("cleaveDamageFactor")?.Value, 0.45f),
                            knockbackDistance = ParseFloat(paEl.Element("knockbackDistance")?.Value, 0f),
                            stunTicks = (int)ParseFloat(paEl.Element("stunTicks")?.Value, 0f),
                            selectionWeight = ParseFloat(paEl.Element("selectionWeight")?.Value, 1.0f),
                            recoilMultiplier = ParseFloat(paEl.Element("recoilMultiplier")?.Value, 1.0f),
                            requiresPrimaryWeaponOperator = ParseBool(paEl.Element("requiresPrimaryWeaponOperator")?.Value, true),
                            canStrikeGroundWhileFlying = ParseBool(paEl.Element("canStrikeGroundWhileFlying")?.Value, false)
                        };
                        if (Enum.TryParse(paEl.Element("kind")?.Value, true, out GiantPartAttackKind pak))
                        {
                            pa.kind = pak;
                        }
                        if (Enum.TryParse(paEl.Element("arcReference")?.Value, true, out GiantPartArcReference par))
                        {
                            pa.arcReference = par;
                        }
                        if (Enum.TryParse(paEl.Element("vfxPresetOverride")?.Value, true, out GiantAnimVfxPreset pavp))
                        {
                            pa.vfxPresetOverride = pavp;
                        }
                        string paAnimName = paEl.Element("attackAnim")?.Value?.Trim();
                        if (!string.IsNullOrEmpty(paAnimName) && anims.TryGetValue(paAnimName, out GiantAnimDef paAnim))
                        {
                            pa.attackAnim = paAnim;
                        }
                        node.partAttacks.Add(pa);
                    }
                }
                if (nEl.Element("turretRecoil") is XElement trEl)
                {
                    node.turretRecoil = new GiantTurretRecoilDef
                    {
                        distanceCells = ParseFloat(trEl.Element("distanceCells")?.Value, 0.28f),
                        kickTicks = (int)ParseFloat(trEl.Element("kickTicks")?.Value, 2f),
                        recoveryTicks = (int)ParseFloat(trEl.Element("recoveryTicks")?.Value, 12f),
                        maxAccumulatedCells = ParseFloat(trEl.Element("maxAccumulatedCells")?.Value, 0f),
                        recoilBoneId = string.IsNullOrWhiteSpace(trEl.Element("recoilBoneId")?.Value)
                            ? null
                            : trEl.Element("recoilBoneId")!.Value.Trim()
                    };
                }
                node.eastVariant = ParseDirectionalVariant(nEl.Element("eastVariant"));
                node.westVariant = ParseDirectionalVariant(nEl.Element("westVariant"));
                rig.nodes.Add(node);
            }

            if (rigEl.Element("steering") is XElement steerEl)
            {
                var stCfg = new SteeringConfigDef
                {
                    enabled = ParseBool(steerEl.Element("enabled")?.Value, true),
                    bodyTurnAccelDegPerTick2 = ParseFloat(steerEl.Element("bodyTurnAccelDegPerTick2")?.Value, 0.40f),
                    bodyPathLookAheadCells = (int)ParseFloat(steerEl.Element("bodyPathLookAheadCells")?.Value, 3f),
                    bodyPathLookAheadWeight = ParseFloat(steerEl.Element("bodyPathLookAheadWeight")?.Value, 0.35f),
                    gazePathLookAheadCells = (int)ParseFloat(steerEl.Element("gazePathLookAheadCells")?.Value, 6f),
                    headLeadGateAngleDeg = ParseFloat(steerEl.Element("headLeadGateAngleDeg")?.Value, 45f),
                    minBodyTurnScaleWhileHeadLeads = ParseFloat(steerEl.Element("minBodyTurnScaleWhileHeadLeads")?.Value, 0.42f)
                };

                if (steerEl.Element("lookChains") != null)
                {
                    foreach (XElement lcEl in steerEl.Element("lookChains").Elements("li"))
                    {
                        var lc = new SteeringLookChainDef
                        {
                            chainId = lcEl.Element("chainId")?.Value,
                            maxChainAngleDeg = ParseFloat(lcEl.Element("maxChainAngleDeg")?.Value, 68f),
                            maxBoneAngleDeg = ParseFloat(lcEl.Element("maxBoneAngleDeg")?.Value, 28f),
                            turnSpeedDegPerTick = ParseFloat(lcEl.Element("turnSpeedDegPerTick")?.Value, 7.5f),
                            responsiveness = ParseFloat(lcEl.Element("responsiveness")?.Value, 0.28f),
                            referenceAngleOffsetDeg = ParseFloat(lcEl.Element("referenceAngleOffsetDeg")?.Value, 0f),
