                            idlePoiGlanceMaxTicks = (int)ParseFloat(lcEl.Element("idlePoiGlanceMaxTicks")?.Value, 85f)
                        };
                        if (lcEl.Element("boneIds") != null)
                        {
                            foreach (XElement bEl in lcEl.Element("boneIds").Elements("li"))
                            {
                                lc.boneIds.Add(bEl.Value);
                            }
