                        p2Damping = ParseFloat(cEl.Element("p2Damping")?.Value, 0.36f),
                        p3Frequency = ParseFloat(cEl.Element("p3Frequency")?.Value, 0.095f),
                        p3Damping = ParseFloat(cEl.Element("p3Damping")?.Value, 0.25f),
                        whipCrackGain = ParseFloat(cEl.Element("whipCrackGain")?.Value, 0.42f),
                        waveLagCoupling = ParseFloat(cEl.Element("waveLagCoupling")?.Value, 0.45f),
                        maxJointBendDeg = ParseFloat(cEl.Element("maxJointBendDeg")?.Value, 58f),
                        idleWaveAmplitudeDeg = ParseFloat(cEl.Element("idleWaveAmplitudeDeg")?.Value, 0f),
                        idleWavePeriodTicks = ParseFloat(cEl.Element("idleWavePeriodTicks")?.Value, 60f),
                        velocityTrailingGain = ParseFloat(cEl.Element("velocityTrailingGain")?.Value, 0f),
                        trailingMaxOffsetCells = ParseFloat(cEl.Element("trailingMaxOffsetCells")?.Value, 7.5f),
                        trailingLateralSign = ParseFloat(cEl.Element("trailingLateralSign")?.Value, 0f),
                        trailingLateralRatio = ParseFloat(cEl.Element("trailingLateralRatio")?.Value, 0.22f),
                        moveSwayAmplitudeCells = ParseFloat(cEl.Element("moveSwayAmplitudeCells")?.Value, 0f),
                        moveSwayPeriodTicks = ParseFloat(cEl.Element("moveSwayPeriodTicks")?.Value, 54f),
                        moveRefSpeedCellsPerTick = ParseFloat(cEl.Element("moveRefSpeedCellsPerTick")?.Value, 0.05f),
                        strikeWindupEndNorm = ParseFloat(cEl.Element("strikeWindupEndNorm")?.Value, 0.26f),
