                        restNormalDrag = ParseFloat(wEl.Element("restNormalDrag")?.Value, 0.16f),
                        fastNormalDrag = ParseFloat(wEl.Element("fastNormalDrag")?.Value, 0.025f),
                        postSnapNormalDrag = ParseFloat(wEl.Element("postSnapNormalDrag")?.Value, 0.23f),
                        tangentialDrag = ParseFloat(wEl.Element("tangentialDrag")?.Value, 0.014f),
                        strikeDragSpeedRef = ParseFloat(wEl.Element("strikeDragSpeedRef")?.Value, 0.40f),
