                        restProximalGain = ParseFloat(wEl.Element("restProximalGain")?.Value, 0.75f),
                        strikeProximalCutoff = ParseFloat(wEl.Element("strikeProximalCutoff")?.Value, 1.42f),
                        strikeProximalGain = ParseFloat(wEl.Element("strikeProximalGain")?.Value, 2.80f),
                        windupEndNorm = ParseFloat(wEl.Element("windupEndNorm")?.Value, 0.14f),
                        snapEndNorm = ParseFloat(wEl.Element("snapEndNorm")?.Value, 0.40f),
                        checkBackEndNorm = ParseFloat(wEl.Element("checkBackEndNorm")?.Value, 0.56f),
                        defaultStrikeAzimuthDeg = ParseFloat(wEl.Element("defaultStrikeAzimuthDeg")?.Value, 18f),
                        defaultStrikeRangeFactor = ParseFloat(wEl.Element("defaultStrikeRangeFactor")?.Value, 0.78f),
                        contributesToHitbox = ParseBool(wEl.Element("contributesToHitbox")?.Value, true),
                        contributesToCollision = ParseBool(wEl.Element("contributesToCollision")?.Value, false),
