            if (rigEl.Element("rollingTracks") != null)
            {
                foreach (XElement rtEl in rigEl.Element("rollingTracks").Elements("li"))
                {
                    var rt = new GiantRollingTrackDef
                    {
                        trackId = rtEl.Element("trackId")?.Value,
                        parentBoneId = rtEl.Element("parentBoneId")?.Value,
