                        dorsalRibbonTexPath = rtEl.Element("dorsalRibbonTexPath")?.Value,
                        lateralRibbonTexPath = rtEl.Element("lateralRibbonTexPath")?.Value,
                        tileLengthCells = ParseFloat(rtEl.Element("tileLengthCells")?.Value, 2.60f),
