                        nearLayerOffset = ParseFloat(rtEl.Element("nearLayerOffset")?.Value, 1.45f),
                        farStartPixel = ParseVec2(rtEl.Element("farStartPixel")?.Value, new Vector2(256f, 470f)),
                        farEndPixel = ParseVec2(rtEl.Element("farEndPixel")?.Value, new Vector2(256f, 42f)),
