                    }
                    if (rtEl.Element("wheels") != null)
                    {
                        foreach (XElement wEl in rtEl.Element("wheels").Elements("li"))
                        {
                            rt.wheels.Add(new GiantTrackWheelDef
                            {
                                wheelId = wEl.Element("wheelId")?.Value,
                                texPath = wEl.Element("texPath")?.Value,
                                centerPixel = ParseVec2(wEl.Element("centerPixel")?.Value, new Vector2(256f, 256f)),
                                diameterCells = ParseFloat(wEl.Element("diameterCells")?.Value, 0.72f),
                                layerOffset = ParseFloat(wEl.Element("layerOffset")?.Value, 1.10f)
                            });
                        }
                    }
                    rig.rollingTracks.Add(rt);
                }
            }

            if (rigEl.Element("skinnedMeshes") != null)
            {
                foreach (XElement smEl in rigEl.Element("skinnedMeshes").Elements("li"))
                {
                    var sm = new GiantSkinnedMeshDef
                    {
                        meshId = smEl.Element("meshId")?.Value,
                        texPath = smEl.Element("texPath")?.Value,
                        silhouetteTexPath = smEl.Element("silhouetteTexPath")?.Value,
                        glowTexPath = smEl.Element("glowTexPath")?.Value,
                        anchorBoneId = smEl.Element("anchorBoneId")?.Value,
                        drawSize = ParseVec2(smEl.Element("drawSize")?.Value, Vector2.one),
                        worldMinXZ = ParseVec2(smEl.Element("worldMinXZ")?.Value, new Vector2(-9999f, -9999f)),
                        worldMaxXZ = ParseVec2(smEl.Element("worldMaxXZ")?.Value, new Vector2(-9999f, -9999f)),
                        pivotUV = ParseVec2(smEl.Element("pivotUV")?.Value, new Vector2(0.5f, 0.5f)),
                        parentSocketUV = ParseVec2(smEl.Element("parentSocketUV")?.Value, new Vector2(0.5f, 0.5f)),
                        pivotPixel = ParseVec2(smEl.Element("pivotPixel")?.Value, new Vector2(-1f, -1f)),
                        parentSocketPixel = ParseVec2(smEl.Element("parentSocketPixel")?.Value, new Vector2(-1f, -1f)),
                        baseAngle = ParseFloat(smEl.Element("baseAngle")?.Value, 0f),
                        layerOffset = ParseFloat(smEl.Element("layerOffset")?.Value, 0f),
                        silhouetteLayerOffset = ParseFloat(smEl.Element("silhouetteLayerOffset")?.Value, -9.2f),
                        glowLayerOffset = ParseFloat(smEl.Element("glowLayerOffset")?.Value, 0.05f),
                        textureResolution = (int)ParseFloat(smEl.Element("textureResolution")?.Value, 512f),
                        alphaThreshold = (byte)ParseFloat(smEl.Element("alphaThreshold")?.Value, 16f),
                        subdivisionsX = (int)ParseFloat(smEl.Element("subdivisionsX")?.Value, 20f),
                        subdivisionsY = (int)ParseFloat(smEl.Element("subdivisionsY")?.Value, 20f),
                        weightSharpness = ParseFloat(smEl.Element("weightSharpness")?.Value, 3.0f),
                        maxInfluences = (int)ParseFloat(smEl.Element("maxInfluences")?.Value, 4f),
                        cullSeveredBoneTriangles = ParseBool(smEl.Element("cullSeveredBoneTriangles")?.Value, true),
                        suppressMemberBoneSprites = ParseBool(smEl.Element("suppressMemberBoneSprites")?.Value, true),
                        rigidPinBoneId = smEl.Element("rigidPinBoneId")?.Value,
                        pinToSkinnedMeshId = smEl.Element("pinToSkinnedMeshId")?.Value
                    };
                    if (smEl.Element("boneIds") != null)
                    {
                        foreach (XElement bEl in smEl.Element("boneIds").Elements("li"))
                        {
                            sm.boneIds.Add(bEl.Value);
                        }
                    }
                    if (smEl.Element("memberBoneIds") != null)
                    {
                        foreach (XElement mbEl in smEl.Element("memberBoneIds").Elements("li"))
                        {
                            sm.memberBoneIds.Add(mbEl.Value);
                        }
                    }
                    if (smEl.Element("capsules") != null)
                    {
                        foreach (XElement cEl in smEl.Element("capsules").Elements("li"))
                        {
                            sm.capsules.Add(new GiantSkinCapsuleDef
                            {
                                boneId = cEl.Element("boneId")?.Value,
                                groupId = cEl.Element("groupId")?.Value,
                                startXZ = ParseVec2(cEl.Element("startXZ")?.Value, Vector2.zero),
                                endXZ = ParseVec2(cEl.Element("endXZ")?.Value, Vector2.zero),
                                radius = ParseFloat(cEl.Element("radius")?.Value, 0.40f),
                                weightMultiplier = ParseFloat(cEl.Element("weightMultiplier")?.Value, 1.0f)
                            });
                        }
                    }
                    rig.skinnedMeshes.Add(sm);
                }
            }

            rig.BuildTopology();

            BoneNodeDef[] sorted = rig.SortedNodes;
            var masks = new TextureAlphaMask[sorted.Length];
            for (int i = 0; i < sorted.Length; i++)
            {
                string pngPath = ResolveMod17Path("Textures", sorted[i].texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Assert(File.Exists(pngPath), $"Missing texture PNG at {pngPath}");
                masks[i] = TextureAlphaMask.FromPngFile(pngPath, sorted[i].alphaThreshold);
                Assert(masks[i] != null && masks[i].HasAnyOpaquePixels, $"Decoded empty alpha mask for {pngPath}");
            }

            return (rig, masks, anims);
        }

        internal static TextureAlphaMask[] LoadSoftWhipMasks(GiantRigDef rig)
        {
            if (rig?.softWhips == null || rig.softWhips.Count == 0)
            {
                return Array.Empty<TextureAlphaMask>();
            }
            var masks = new TextureAlphaMask[rig.softWhips.Count];
            for (int i = 0; i < rig.softWhips.Count; i++)
            {
                SoftWhipDef sw = rig.softWhips[i];
                string pngPath = ResolveMod17Path("Textures", sw.texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Assert(File.Exists(pngPath), $"Missing soft whip texture PNG at {pngPath}");
                masks[i] = TextureAlphaMask.FromPngFile(pngPath, sw.alphaThreshold);
                Assert(masks[i] != null && masks[i].HasAnyOpaquePixels, $"Decoded empty alpha mask for {pngPath}");
            }
            return masks;
        }

        internal static TextureAlphaMask[] LoadRigSectorMasks(GiantRigDef rig, GiantBoneViewSector sector)
        {
            BoneNodeDef[] sorted = rig.SortedNodes;
            var masks = new TextureAlphaMask[sorted.Length];
            for (int i = 0; i < sorted.Length; i++)
            {
                string texPath = sorted[i].GetTexPath(sector) ?? sorted[i].texPath;
                string pngPath = ResolveMod17Path("Textures", texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Assert(File.Exists(pngPath), $"Missing sector texture PNG at {pngPath}");
                masks[i] = TextureAlphaMask.FromPngFile(pngPath, sorted[i].alphaThreshold);
                Assert(masks[i] != null && masks[i].HasAnyOpaquePixels, $"Decoded empty alpha mask for {pngPath}");
            }
            return masks;
        }

        private static void TestPngAssetsAndAlphaMasks()
        {
            string[] partFiles =
            {
                "Carapace.png",
                "ClawLeft.png",
                "ClawRight.png",
                "TailSeg1.png",
                "TailSeg2.png",
                "TailSeg3.png",
                "TailSeg4.png",
                "TailSeg5.png",
                "TailSeg6.png",
                "TailStingerTip.png",
                "LegL1.png",
                "LegL2.png",
                "LegL3.png",
                "LegL4.png",
                "LegR1.png",
                "LegR2.png",
                "LegR3.png",
                "LegR4.png"
            };

            string[] obsoleteFiles =
            {
                "LegsLeft.png",
                "LegsRight.png",
                "LegFemurLeft.png",
                "LegFemurRight.png",
                "LegTibiaLeft.png",
                "LegTibiaRight.png",
                "TailStinger.png"
            };

            string dir = ResolveMod17Path("Textures", "Things", "Pawn", "GiantCreature", "MechScorpion");
            foreach (string obs in obsoleteFiles)
            {
                Assert(!File.Exists(Path.Combine(dir, obs)), $"Obsolete texture must be removed: {obs}");
            }

            foreach (string file in partFiles)
            {
                string full = Path.Combine(dir, file);
                Assert(File.Exists(full), $"Missing 512x512 part texture: {full}");

                TextureAlphaMask mask = TextureAlphaMask.FromPngFile(full, 32);
                Assert(mask != null, $"TextureAlphaMask.FromPngFile returned null for {file}");
                Assert(mask.width == 512 && mask.height == 512, $"{file} must be 512x512, got {mask.width}x{mask.height}");
                Assert(mask.HasAnyOpaquePixels, $"{file} alpha mask is empty");
                Assert(mask.minU >= 0f && mask.maxU <= 1f && mask.minU < mask.maxU, $"{file} invalid U bounds [{mask.minU}, {mask.maxU}]");
                Assert(mask.minV >= 0f && mask.maxV <= 1f && mask.minV < mask.maxV, $"{file} invalid V bounds [{mask.minV}, {mask.maxV}]");

                // Count opaque pixels to confirm substantial silhouette with transparent surroundings
                int opaqueCount = 0;
                for (int y = 0; y < 512; y++)
                {
                    for (int x = 0; x < 512; x++)
                    {
                        if (mask.IsOpaqueUV((x + 0.5f) / 512f, (y + 0.5f) / 512f))
                            opaqueCount++;
                    }
                }
                float fillRatio = opaqueCount / (512f * 512f);
                Assert(fillRatio > 0.05f && fillRatio < 0.75f, $"{file} unexpected alpha fill ratio {fillRatio:P1}");
                Console.WriteLine($"       -> {file}: 512x512 OK, fill={fillRatio:P1}, tightUV=({mask.minU:F2}..{mask.maxU:F2}, {mask.minV:F2}..{mask.maxV:F2})");
            }
        }

        private static void TestXmlRigAndTopology()
        {
            var (rig, _, anims) = LoadMechScorpionFromXml();
            List<string> errors = rig.ConfigErrors().ToList();
            Assert(errors.Count == 0, $"GiantRigDef ConfigErrors: {string.Join("; ", errors)}");
            Assert(rig.SortedNodes.Length == 18, $"Expected 18 rig nodes (carapace + 2 claws + 8 legs + 7 tail chain), got {rig.SortedNodes.Length}");
            Assert(rig.SortedNodes[0].nodeId == "carapace", $"Root node must be carapace, got {rig.SortedNodes[0].nodeId}");
            Assert(rig.SortedNodes[0].parentRuntimeIndex == -1, "Root node parentRuntimeIndex must be -1");

            var expectedParent = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["claw_left"] = "carapace",
                ["claw_right"] = "carapace",
                ["leg_l1"] = "carapace",
                ["leg_l2"] = "carapace",
                ["leg_l3"] = "carapace",
                ["leg_l4"] = "carapace",
                ["leg_r1"] = "carapace",
                ["leg_r2"] = "carapace",
                ["leg_r3"] = "carapace",
                ["leg_r4"] = "carapace",
                ["tail_seg1"] = "carapace",
                ["tail_seg2"] = "tail_seg1",
                ["tail_seg3"] = "tail_seg2",
                ["tail_seg4"] = "tail_seg3",
                ["tail_seg5"] = "tail_seg4",
                ["tail_seg6"] = "tail_seg5",
                ["tail_stinger"] = "tail_seg6",
            };

            for (int i = 1; i < rig.SortedNodes.Length; i++)
            {
                BoneNodeDef child = rig.SortedNodes[i];
                Assert(expectedParent.TryGetValue(child.nodeId, out string expParentId), $"Unexpected nodeId '{child.nodeId}'");
                Assert(rig.TryGetNodeIndex(expParentId, out int expParentIdx) && child.parentRuntimeIndex == expParentIdx,
                    $"Child {child.nodeId} must attach to {expParentId} ({expParentIdx}), got parentRuntimeIndex={child.parentRuntimeIndex}");
                Assert(child.parentRuntimeIndex < i, $"Topological sort invariant violated on {child.nodeId}");
                Assert(child.HasCustomPivotPixel, $"Child {child.nodeId} must specify pivotPixel");
                Assert(child.HasCustomParentSocketPixel, $"Child {child.nodeId} must specify parentSocketPixel");
            }

            Assert(anims.Count == 10, $"Expected 10 pure skeletal GiantAnimDefs for MechScorpion (including TurnLeft/TurnRight), got {anims.Count}");
            Assert(!anims.ContainsKey("GCF_Anim_MechScorpion_Idle"), "Idle breathing animation is globally prohibited and must not exist.");
            foreach (GiantAnimDef anim in anims.Values)
            {
                List<string> animErrors = anim.ConfigErrors().ToList();
                Assert(animErrors.Count == 0, $"GiantAnimDef '{anim.defName}' ConfigErrors: {string.Join("; ", animErrors)}");
            }
        }

        private static void TestKinematicsExactAlignment()
        {
            var (rig, _, anims) = LoadMechScorpionFromXml();
            int n = rig.SortedNodes.Length;
            var localPoses = new BoneLocalPose[n];
            var missing = new bool[n];
            var worldPoses = new BoneWorldPose[n];

            anims["GCF_Anim_MechScorpion_ClawLeft"].EvaluateInto(rig, 16f, localPoses);

            float[] testHeadings = { 0f, 37.5f, 90f, 142.3f, 180f, 270f, 359.1f };
            Vector2[] testUVs =
            {
                new Vector2(0.5f, 0.5f),
                new Vector2(0.15f, 0.82f),
                new Vector2(0.88f, 0.24f),
                new Vector2(0.5f, 0.95f)
            };

            foreach (float heading in testHeadings)
            {
                Vector2 rootXZ = new Vector2(52.5f, 78.5f);
                SkeletalKinematics.SolveWorldPoses(rig, rootXZ, heading, localPoses, missing, worldPoses);

                for (int i = 0; i < n; i++)
                {
                    ref readonly BoneWorldPose pose = ref worldPoses[i];
                    Matrix4x4 renderMat = pose.BuildRenderMatrix(1.25f);

                    // Verify every UV point transforms to the EXACT same world XZ via BuildRenderMatrix (GPU) and UVToWorldXZ (CPU)
                    foreach (Vector2 uv in testUVs)
                    {
                        Vector2 cpuXZ = pose.UVToWorldXZ(uv.x, uv.y);
                        Vector3 gpuWorld = renderMat.MultiplyPoint3x4(new Vector3(uv.x - 0.5f, 0f, uv.y - 0.5f));
                        AssertNear(cpuXZ.x, gpuWorld.x, 1e-4f, $"Bone {rig.SortedNodes[i].nodeId} @ {heading}deg X mismatch");
                        AssertNear(cpuXZ.y, gpuWorld.z, 1e-4f, $"Bone {rig.SortedNodes[i].nodeId} @ {heading}deg Z mismatch");

                        // Verify TryWorldToUV is exact inverse
                        bool inside = pose.TryWorldToUV(cpuXZ.x, cpuXZ.y, out float invU, out float invV);
                        Assert(inside, $"TryWorldToUV returned false for interior UV {uv}");
                        AssertNear(invU, uv.x, 1e-4f, $"Inverse U mismatch on {rig.SortedNodes[i].nodeId}");
                        AssertNear(invV, uv.y, 1e-4f, $"Inverse V mismatch on {rig.SortedNodes[i].nodeId}");
                    }
                }
            }

            // Also verify rest-pose socket attachment invariance across arbitrary heading
            for (int i = 0; i < n; i++) localPoses[i] = BoneLocalPose.Identity;
            SkeletalKinematics.SolveWorldPoses(rig, new Vector2(20.5f, 30.5f), 63f, localPoses, missing, worldPoses);
            for (int i = 1; i < n; i++)
            {
                BoneNodeDef childDef = rig.SortedNodes[i];
                int pIdx = childDef.parentRuntimeIndex;
                Vector2 parentSocketWorld = worldPoses[pIdx].UVToWorldXZ(childDef.resolvedParentSocketUV.x, childDef.resolvedParentSocketUV.y);
                AssertNear(worldPoses[i].jointWorldXZ.x, parentSocketWorld.x, 1e-4f, $"Socket X mismatch for {childDef.nodeId}");
                AssertNear(worldPoses[i].jointWorldXZ.y, parentSocketWorld.y, 1e-4f, $"Socket Z mismatch for {childDef.nodeId}");
            }

            // Exhaustive Zero-Socket-Drift & Zero-Breathing-Scale verification across ALL animations & ticks!
            float[] checkHeadings = { 0f, 37.5f, 142.3f, 270f };
            foreach (GiantAnimDef anim in anims.Values)
            {
                int maxTick = Mathf.CeilToInt(anim.durationTicks);
                for (int t = 0; t <= maxTick; t++)
                {
                    anim.EvaluateInto(rig, t, localPoses);
                    foreach (float heading in checkHeadings)
                    {
                        SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50.5f, 50.5f), heading, localPoses, missing, worldPoses);
                        for (int i = 0; i < n; i++)
                        {
                            BoneNodeDef bDef = rig.SortedNodes[i];
                            AssertNear(worldPoses[i].worldSize.x, bDef.drawSize.x, 1e-5f,
                                $"Scale X drift in {anim.defName}@{t} on {bDef.nodeId}");
                            AssertNear(worldPoses[i].worldSize.y, bDef.drawSize.y, 1e-5f,
                                $"Scale Y drift in {anim.defName}@{t} on {bDef.nodeId}");

                            if (i > 0)
                            {
                                int pIdx = bDef.parentRuntimeIndex;
                                Vector2 lockedSocketXZ = worldPoses[pIdx].UVToWorldXZ(bDef.resolvedParentSocketUV.x, bDef.resolvedParentSocketUV.y);
                                AssertNear(worldPoses[i].jointWorldXZ.x, lockedSocketXZ.x, 1e-5f,
                                    $"Socket X drift in {anim.defName}@{t} on {bDef.nodeId} @ {heading}deg");
                                AssertNear(worldPoses[i].jointWorldXZ.y, lockedSocketXZ.y, 1e-5f,
                                    $"Socket Z drift in {anim.defName}@{t} on {bDef.nodeId} @ {heading}deg");
                            }
                        }
                    }
                }
            }
        }

        private static void TestDynamicFootprintAndDestruction()
        {
            var (rig, masks, anims) = LoadMechScorpionFromXml();
            int n = rig.SortedNodes.Length;
            var localPoses = new BoneLocalPose[n];
            for (int i = 0; i < n; i++) localPoses[i] = BoneLocalPose.Identity;
            var missing = new bool[n];
            var worldPoses = new BoneWorldPose[n];
            var footprint = new GiantFootprintData();

            IntVec3 center = new IntVec3(50, 0, 50);
            Vector2 rootXZ = new Vector2(50.5f, 50.5f);
            IntVec3 mapSize = new IntVec3(150, 1, 150);

            // 1. North (0 deg) rest footprint
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            footprint.Rebuild(rig, worldPoses, masks, center, mapSize);

            int northHits = footprint.hitCells.Count;
            int northCols = footprint.collisionCells.Count;
            Console.WriteLine($"       -> Facing North (0 deg): HitCells={northHits}, CollisionCells={northCols}, TightBounds={footprint.tightHitBounds}");
            Assert(northHits >= 20 && northHits <= 52, $"Expected multi-cell scorpion HitCells in [20..52], got {northHits}");
            Assert(northCols >= 8 && northCols <= northHits, $"Expected CollisionCells subset [8..{northHits}], got {northCols}");
            foreach (IntVec3 cc in footprint.collisionCells)
            {
                Assert(footprint.hitCellSet.Contains(cc), $"Collision cell {cc} must also be in hitCellSet");
            }

            // Check North extent: pincers reach Z >= 52, extended 7-seg tail reaches Z <= 45
            int maxZNorth = footprint.hitCells.Max(c => c.cell.z);
            int minZNorth = footprint.hitCells.Min(c => c.cell.z);
            Assert(maxZNorth >= 52, $"Expected front pincers to reach Z >= 52 when facing North, got {maxZNorth}");
            Assert(minZNorth <= 45, $"Expected extended rear tail stinger to reach Z <= 45 when facing North, got {minZNorth}");

            // 2. Rotate 90 deg East: pincers must shift to X >= 52, extended tail to X <= 45!
            var eastFootprint = new GiantFootprintData();
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 90f, localPoses, missing, worldPoses);
            eastFootprint.Rebuild(rig, worldPoses, masks, center, mapSize);

            int maxXEast = eastFootprint.hitCells.Max(c => c.cell.x);
            int minXEast = eastFootprint.hitCells.Min(c => c.cell.x);
            Console.WriteLine($"       -> Facing East (90 deg): HitCells={eastFootprint.hitCells.Count}, X-span=[{minXEast}..{maxXEast}]");
            Assert(maxXEast >= 52, $"Expected front pincers to reach X >= 52 when facing East, got {maxXEast}");
            Assert(minXEast <= 45, $"Expected extended rear tail stinger to reach X <= 45 when facing East, got {minXEast}");
            AssertNear(eastFootprint.hitCells.Count, northHits, 2f, "90-deg orthogonal rotation should preserve cell count");

            // 3. Part destruction: severing tail_seg2 hierarchically hides tail_seg2..tail_stinger while leaving tail_seg1 intact!
            Assert(rig.TryGetNodeIndex("tail_seg1", out int tailSeg1Idx), "Missing tail_seg1 node");
            Assert(rig.TryGetNodeIndex("tail_seg2", out int tailSeg2Idx), "Missing tail_seg2 node");
            Assert(rig.TryGetNodeIndex("tail_stinger", out int tailIdx), "Missing tail_stinger node");
            Assert(rig.TryGetNodeIndex("claw_left", out int clawLeftIdx), "Missing claw_left node");
            missing[tailSeg2Idx] = true;
            missing[clawLeftIdx] = true;

            var damagedFootprint = new GiantFootprintData();
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            damagedFootprint.Rebuild(rig, worldPoses, masks, center, mapSize);
            Assert(worldPoses[tailSeg1Idx].visible, "tail_seg1 stump must remain visible when tail_seg2 is severed");
            foreach (string severedTailId in new[] { "tail_seg2", "tail_seg3", "tail_seg4", "tail_seg5", "tail_seg6", "tail_stinger" })
            {
                Assert(rig.TryGetNodeIndex(severedTailId, out int sIdx) && !worldPoses[sIdx].visible,
                    $"Downstream tail node {severedTailId} must auto-hide when tail_seg2 is severed");
            }
            Console.WriteLine($"       -> After severing claw_left + tail_seg2 chain: HitCells={damagedFootprint.hitCells.Count} (was {northHits})");
            Assert(damagedFootprint.hitCells.Count < northHits - 5, "Severing claw_left and 6-link tail chain must reduce HitCells");
            int minZWithoutTail = damagedFootprint.hitCells.Min(c => c.cell.z);
            Assert(minZWithoutTail >= 48 && minZWithoutTail > minZNorth, $"Severing tail_seg2 must retract rear Z bound to >= 48 ({minZWithoutTail} vs {minZNorth})");

            // 3b. Independent leg severing: losing leg_r2 hides ONLY leg_r2 while preserving the other 7 legs!
            Array.Clear(missing, 0, n);
            Assert(rig.TryGetNodeIndex("leg_r2", out int legR2Idx), "Missing leg_r2 node");
            missing[legR2Idx] = true;
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            Assert(!worldPoses[legR2Idx].visible, "Severed leg_r2 must not be visible");
            foreach (string otherLeg in new[] { "leg_l1", "leg_l2", "leg_l3", "leg_l4", "leg_r1", "leg_r3", "leg_r4" })
            {
                Assert(rig.TryGetNodeIndex(otherLeg, out int oIdx) && worldPoses[oIdx].visible, $"Remaining leg {otherLeg} must stay visible when leg_r2 is severed");
            }

            // 4. Curved overhead TailSting forward whip swings extended tail completely forward!
            Array.Clear(missing, 0, n);
            anims["GCF_Anim_MechScorpion_TailSting"].EvaluateInto(rig, 19f, localPoses);
            var strikeFootprint = new GiantFootprintData();
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            strikeFootprint.Rebuild(rig, worldPoses, masks, center, mapSize);
            int minZDuringOverheadStrike = strikeFootprint.hitCells.Min(c => c.cell.z);
            int maxZDuringOverheadStrike = strikeFootprint.hitCells.Max(c => c.cell.z);
            Assert(minZDuringOverheadStrike > minZNorth + 2, "Curved overhead tail sting lunge must swing extended tail forward from rear");
            Assert(maxZDuringOverheadStrike >= maxZNorth, "Curved overhead tail hook strike must reach at least as far forward as rest pincers");
        }

        private static void TestProjectileLimbHitDetection()
        {
            var (rig, masks, _) = LoadMechScorpionFromXml();
            int n = rig.SortedNodes.Length;
            var localPoses = new BoneLocalPose[n];
            for (int i = 0; i < n; i++) localPoses[i] = BoneLocalPose.Identity;
            var missing = new bool[n];
            var worldPoses = new BoneWorldPose[n];
            var fp = new GiantFootprintData();

            Vector2 rootXZ = new Vector2(50.5f, 50.5f);
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            fp.Rebuild(rig, worldPoses, masks, new IntVec3(50, 0, 50), new IntVec3(150, 1, 150));

            rig.TryGetNodeIndex("claw_left", out int clawLeftIdx);
            rig.TryGetNodeIndex("claw_right", out int clawRightIdx);
            rig.TryGetNodeIndex("tail_seg3", out int tailSeg3Idx);
            rig.TryGetNodeIndex("tail_stinger", out int tailIdx);
            rig.TryGetNodeIndex("leg_r2", out int legR2Idx);

            // Shot into Left Crusher Claw (front-left)
            Vector2 clawLeftSample = worldPoses[clawLeftIdx].UVToWorldXZ(0.45f, 0.55f);
            bool hitCL = fp.TryHitTestSegment(
                rig, masks,
                new Vector3(clawLeftSample.x - 2f, 0f, clawLeftSample.y + 2f),
                new Vector3(clawLeftSample.x, 0f, clawLeftSample.y),
                out int hitBoneCL, out _);
            Assert(hitCL && hitBoneCL == clawLeftIdx, $"Expected shot into front-left pincer to hit claw_left ({clawLeftIdx}), got hit={hitCL}, bone={hitBoneCL}");

            // Shot into Right Crusher Claw (front-right)
            Vector2 clawRightSample = worldPoses[clawRightIdx].UVToWorldXZ(0.55f, 0.55f);
            bool hitCR = fp.TryHitTestSegment(
                rig, masks,
                new Vector3(clawRightSample.x + 2f, 0f, clawRightSample.y + 2f),
                new Vector3(clawRightSample.x, 0f, clawRightSample.y),
                out int hitBoneCR, out _);
            Assert(hitCR && hitBoneCR == clawRightIdx, $"Expected shot into front-right pincer to hit claw_right ({clawRightIdx}), got hit={hitCR}, bone={hitBoneCR}");

            // Shot from directly behind (outside extended Z=44.81 stinger tip) into Plasma Tail Stinger
            bool hitTail = fp.TryHitTestSegment(
                rig, masks,
                new Vector3(50.5f, 0f, 43.0f),
                new Vector3(50.5f, 0f, 48.0f),
                out int hitBoneTail, out _);
            Assert(hitTail && hitBoneTail == tailIdx, $"Expected rear shot to hit tail_stinger ({tailIdx}), got hit={hitTail}, bone={hitBoneTail}");

            // Flank shot from West directly into Tail Segment 3
            Vector2 seg3Target = worldPoses[tailSeg3Idx].UVToWorldXZ(0.5f, 0.52f);
            bool hitSeg3 = fp.TryHitTestSegment(
                rig, masks,
                new Vector3(48.0f, 0f, seg3Target.y),
                new Vector3(seg3Target.x + 0.05f, 0f, seg3Target.y),
                out int hitBoneSeg3, out _);
            Assert(hitSeg3 && hitBoneSeg3 == tailSeg3Idx, $"Expected flank shot into mid-tail to hit tail_seg3 ({tailSeg3Idx}), got hit={hitSeg3}, bone={hitBoneSeg3}");

            // Shot from East into Right Mid-Front Walking Leg (leg_r2)
            Vector2 legR2TipUV = new Vector2(0.84f, 0.56f);
            for (int px = 490; px >= 320; px--)
            {
                float u = (px + 0.5f) / 512f;
                if (masks[legR2Idx].IsOpaqueUV(u, 0.56f))
                {
                    legR2TipUV = new Vector2(u - 0.04f, 0.56f);
                    break;
                }
            }
            Vector2 legR2Target = worldPoses[legR2Idx].UVToWorldXZ(legR2TipUV.x, legR2TipUV.y);
            bool hitLegsR = fp.TryHitTestSegment(
                rig, masks,
                new Vector3(legR2Target.x + 2.0f, 0f, legR2Target.y),
                new Vector3(legR2Target.x - 0.05f, 0f, legR2Target.y),
                out int hitBoneLR, out _);
            Assert(hitLegsR && hitBoneLR == legR2Idx, $"Expected right flank shot to hit leg_r2 ({legR2Idx}), got hit={hitLegsR}, bone={hitBoneLR}");

            // Shot passing through empty space outside silhouette (rear-left corner gap) must NOT hit!
            bool missCorner = fp.TryHitTestSegment(
                rig, masks,
                new Vector3(47.2f, 0f, 46.5f),
                new Vector3(47.8f, 0f, 46.5f),
                out _, out _);
            Assert(!missCorner, "Shot through transparent corner outside tail/legs must NOT trigger phantom hit");
        }

        private static void TestAnimationSamplingAndBlending()
        {
            var (rig, _, anims) = LoadMechScorpionFromXml();
            int n = rig.SortedNodes.Length;
            var posesA = new BoneLocalPose[n];
            var posesB = new BoneLocalPose[n];

            GiantAnimDef walk = anims["GCF_Anim_MechScorpion_Walk"];
            walk.EvaluateInto(rig, 0f, posesA);
            walk.EvaluateInto(rig, walk.durationTicks, posesB);
            for (int i = 0; i < n; i++)
            {
                AssertNear(posesA[i].angle, posesB[i].angle, 1e-3f, $"Looping walk seam mismatch on bone {rig.SortedNodes[i].nodeId}");
            }

            // Verify alternating tetrapod anti-phase walk gait:
            // 1) Adjacent same-side legs reach >= 9 deg separation (independent, not fused)
            // 2) Contralateral pair L3 vs R3 sweeps >= 10 deg out of forward-phase (anti-phase tetrapod)
            rig.TryGetNodeIndex("leg_l1", out int l1Idx);
            rig.TryGetNodeIndex("leg_l2", out int l2Idx);
            rig.TryGetNodeIndex("leg_l3", out int l3Idx);
            rig.TryGetNodeIndex("leg_l4", out int l4Idx);
            rig.TryGetNodeIndex("leg_r3", out int r3Idx);
            var legPoses = new BoneLocalPose[n];
            float maxSep12 = 0f, maxSep23 = 0f, maxSep34 = 0f, maxContra3 = 0f;
            for (int tick = 0; tick < 48; tick += 2)
            {
                walk.EvaluateInto(rig, tick, legPoses);
                maxSep12 = MathF.Max(maxSep12, MathF.Abs(legPoses[l1Idx].angle - legPoses[l2Idx].angle));
                maxSep23 = MathF.Max(maxSep23, MathF.Abs(legPoses[l2Idx].angle - legPoses[l3Idx].angle));
                maxSep34 = MathF.Max(maxSep34, MathF.Abs(legPoses[l3Idx].angle - legPoses[l4Idx].angle));
                // Left forward = +angle, Right forward = -angle
                maxContra3 = MathF.Max(maxContra3, MathF.Abs(legPoses[l3Idx].angle - (-legPoses[r3Idx].angle)));
            }
            Assert(maxSep12 >= 9f && maxSep23 >= 9f && maxSep34 >= 9f,
                $"Adjacent left legs must swing independently (peak separations L1-L2={maxSep12:F1}, L2-L3={maxSep23:F1}, L3-L4={maxSep34:F1})");
            Assert(maxContra3 >= 10f,
                $"Contralateral legs L3/R3 must walk in anti-phase (peak forward phase diff={maxContra3:F1})");

            // Verify multi-segment tail strike curvature (all 7 tail bones bend independently, not single-pivot rotation)
            var stingPoses = new BoneLocalPose[n];
            anims["GCF_Anim_MechScorpion_TailSting"].EvaluateInto(rig, 19f, stingPoses);
            foreach (string tailNode in new[] { "tail_seg1", "tail_seg2", "tail_seg3", "tail_seg4", "tail_seg5", "tail_seg6", "tail_stinger" })
            {
                Assert(rig.TryGetNodeIndex(tailNode, out int tIdx), $"Missing tail node {tailNode}");
                Assert(MathF.Abs(stingPoses[tIdx].angle) >= 10f,
                    $"TailSting@19 must bend {tailNode} independently (>= 10 deg), got {stingPoses[tIdx].angle:F1} deg");
            }

            // Shortest-arc angle Lerp across +-180 wrap
            var p1 = new BoneLocalPose(Vector2.zero, 170f, Vector2.one);
            var p2 = new BoneLocalPose(Vector2.zero, -170f, Vector2.one);
            BoneLocalPose mid = BoneLocalPose.Lerp(in p1, in p2, 0.5f);
            float wrapped = Mathf.Abs(Mathf.DeltaAngle(mid.angle, 180f));
            AssertNear(wrapped, 0f, 1e-3f, "BoneLocalPose.Lerp must take shortest angular arc across 180/-180");

            // Negative test: breathing/scale keyframe MUST trigger ConfigErrors AND SolveWorldPoses must still enforce zero child offset & unit scale
            var forbiddenScaleAnim = new GiantAnimDef
            {
                defName = "Test_ForbiddenScale",
                durationTicks = 20f,
                tracks = new List<BoneAnimTrack>
                {
                    new BoneAnimTrack
                    {
                        nodeId = "carapace",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f, scale = new Vector2(1.1f, 0.9f) }
                        }
                    }
                }
            };
            Assert(forbiddenScaleAnim.ConfigErrors().Any(), "GiantAnimDef.ConfigErrors must reject non-unit scale / breathing animations");

            var dirtyLocal = new BoneLocalPose[n];
            for (int i = 0; i < n; i++)
            {
                dirtyLocal[i] = new BoneLocalPose(new Vector2(2.5f, -3.5f), 25f, new Vector2(1.4f, 0.7f));
            }
            var dirtyWorld = new BoneWorldPose[n];
            SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50.5f, 50.5f), 0f, dirtyLocal, new bool[n], dirtyWorld);
            for (int i = 1; i < n; i++)
            {
                BoneNodeDef cDef = rig.SortedNodes[i];
                int pIdx = cDef.parentRuntimeIndex;
                AssertNear(dirtyWorld[i].worldSize.x, cDef.drawSize.x, 1e-5f, "SolveWorldPoses must enforce constant X size");
                AssertNear(dirtyWorld[i].worldSize.y, cDef.drawSize.y, 1e-5f, "SolveWorldPoses must enforce constant Y size");
                Vector2 expectedSocket = dirtyWorld[pIdx].UVToWorldXZ(cDef.resolvedParentSocketUV.x, cDef.resolvedParentSocketUV.y);
                AssertNear(dirtyWorld[i].jointWorldXZ.x, expectedSocket.x, 1e-5f, "SolveWorldPoses must ignore child anim.offset X");
                AssertNear(dirtyWorld[i].jointWorldXZ.y, expectedSocket.y, 1e-5f, "SolveWorldPoses must ignore child anim.offset Z");
            }
        }

        private static void TestWorldGiantProjection()
        {
            Vector3 origin = new Vector3(44f, -12f, 78f);
            Vector3 normal = new Vector3(2f, 1f, 3f).normalized;
            Vector3 center = origin + normal * 100f;
            const float scale = 0.08f;
            const float elevation = 0.03f;
            Matrix4x4 world = GiantWorldRenderer.BuildWorldMatrix(center, origin, scale, elevation);
            Vector3 root = world.MultiplyPoint3x4(Vector3.zero);
            Vector3 joint = world.MultiplyPoint3x4(new Vector3(1.4f, 0f, -2.3f));
            Vector3 tip = world.MultiplyPoint3x4(new Vector3(4.2f, 0f, 3.6f));
            Vector3 upperLayer = world.MultiplyPoint3x4(new Vector3(1.4f, 0.5f, -2.3f));

            AssertNear(Vector3.Distance(root, center), elevation, 1e-4f, "Root sits above its own planet layer");
            AssertNear(Vector3.Dot(joint - root, normal), 0f, 1e-4f, "Joint remains in the local tangent plane");
            AssertNear(Vector3.Distance(root, joint), new Vector2(1.4f, -2.3f).magnitude * scale, 1e-4f, "Root-to-joint spacing");
            AssertNear(Vector3.Distance(joint, tip), new Vector2(2.8f, 5.9f).magnitude * scale, 1e-4f, "Joint-to-tip spacing");
            AssertNear(Vector3.Dot(upperLayer - joint, normal), 0.5f * scale, 1e-4f, "Part layer separation remains outward");
            Vector3 width = world.MultiplyVector(new Vector3(6f, 0f, 0f));
            Vector3 length = world.MultiplyVector(new Vector3(0f, 0f, 2.5f));
            AssertNear(width.magnitude / length.magnitude, 6f / 2.5f, 1e-4f, "Whole-rig aspect ratio");
            AssertNear(Vector3.Cross(length, width).magnitude, 6f * 2.5f * scale * scale, 1e-4f, "Projected footprint area scales uniformly");

            // Anti-flicker world-map invariants:
            // 1. World-map entity base Y must NOT add map-space AltitudeLayer.Pawn (~8.415)
            float worldLocalBaseY = CompGiantRig.ComputeGiantEntityBaseWorldY(
                isPortrait: false, isDead: false, isDowned: false,
                rootColY: 0f, worldZ: 0f, thingIdNumber: 1001,
                isFlyingVisual: true, flightAltitudeBoost: 2.6f, isWorldMap: true);
            AssertNear(worldLocalBaseY, 0f, 1e-6f, "World-map giant base local Y must stay at 0 (zero parallax float-off)");

            // 2. Bone glow overlay matrix must apply BoneNodeDef.glowLayerOffset (zero coplanar Z-fighting)
            MethodInfo boneMatMethod = typeof(CompGiantRig).GetMethod("TryComputeBoneRenderMatrix", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            FieldInfo glowOffField = typeof(BoneNodeDef).GetField(nameof(BoneNodeDef.glowLayerOffset));
            Assert(boneMatMethod != null && HarmonyLib.PatchProcessor.GetOriginalInstructions(boneMatMethod).Any(ci => ci.LoadsField(glowOffField)),
                "TryComputeBoneRenderMatrix must load BoneNodeDef.glowLayerOffset to prevent bone glow Z-fighting");

            // 3. Camera-distance-aware layer step clears planet-radius float32 ULP (7.6e-6) and depth quantization across d=25..1100
            float stepCloseRZ = GiantWorldRenderer.ComputeWorldLayerStep(25f, usesReversedZBuffer: true);
            float stepMidRZ = GiantWorldRenderer.ComputeWorldLayerStep(160f, usesReversedZBuffer: true);
            float stepFarRZ = GiantWorldRenderer.ComputeWorldLayerStep(1000f, usesReversedZBuffer: true);
            float stepMid24 = GiantWorldRenderer.ComputeWorldLayerStep(160f, usesReversedZBuffer: false);
            Assert(stepCloseRZ >= 0.00075f && stepMidRZ >= stepCloseRZ && stepFarRZ > 0.005f,
                $"Reversed-Z world layer step must scale safely with camera distance: close={stepCloseRZ}, mid={stepMidRZ}, far={stepFarRZ}");
            Assert(stepMid24 >= (160f * 160f) / (2f * 16777216f) * 3f,
                $"24-bit world layer step must clear perspective depth quantum by >=3x: got {stepMid24}");

            // 4. Render queues sit strictly above WorldTerrain(3500)..FeatureName(3610) and strictly below Clouds(3700), strictly monotonic
            int prevQueue = RimWorld.Planet.WorldMaterials.FeatureNameRenderQueue;
            for (int r = 0; r < 64; r++)
            {
                int q = GiantWorldRenderer.ComputePartRenderQueue(r, 63);
                Assert(q > prevQueue && q < 3700, $"Part rank {r} queue {q} must strictly increase inside (3610, 3700)");
                prevQueue = q;
            }
            Assert(GiantWorldRenderer.ComputePartRenderQueue(120, 120) <= GiantWorldRenderer.WorldGiantMaxRenderQueue,
                "Overflow rank (>85 parts) must clamp below Clouds=3700");

            // 5. BuildPartWorldMatrix strips map-space local Y and enforces exact normal separation without XZ distortion
            Matrix4x4 localA = Matrix4x4.TRS(new Vector3(1.4f, 8.436f, -2.3f), Quaternion.identity, Vector3.one);
            Matrix4x4 localB = Matrix4x4.TRS(new Vector3(1.4f, 8.436125f, -2.3f), Quaternion.identity, Vector3.one);
            Matrix4x4 partWorldA = GiantWorldRenderer.BuildPartWorldMatrix(world, normal, 0f, localA);
            Matrix4x4 partWorldB = GiantWorldRenderer.BuildPartWorldMatrix(world, normal, stepCloseRZ, localB);
            Vector3 posA = partWorldA.MultiplyPoint3x4(Vector3.zero);
            Vector3 posB = partWorldB.MultiplyPoint3x4(Vector3.zero);
            AssertNear(Vector3.Dot(posA - center, normal), elevation, 1e-4f, "BuildPartWorldMatrix strips bogus +8.436 map Y");
            AssertNear(Vector3.Dot(posB - posA, normal), stepCloseRZ, 1e-5f, "Adjacent parts keep full unshrunk normal separation");
            AssertNear(Vector3.Distance(posA, root), new Vector2(1.4f, -2.3f).magnitude * scale, 1e-4f, "Part XZ tangent spacing preserved");

            // 6. Overlapping ground/flying giants occupy disjoint elevation bands
            float altG0 = GiantWorldRenderer.ComputeGiantBaseAltitude(worldObjectId: 0, isFlying: false, rankCount: 30, layerStep: stepCloseRZ);
            float altG1 = GiantWorldRenderer.ComputeGiantBaseAltitude(worldObjectId: 1, isFlying: false, rankCount: 30, layerStep: stepCloseRZ);
            float altF0 = GiantWorldRenderer.ComputeGiantBaseAltitude(worldObjectId: 0, isFlying: true, rankCount: 30, layerStep: stepCloseRZ);
            Assert(altG0 >= 0.050f && altG1 >= altG0 + 30 * stepCloseRZ + 0.005f,
                $"Adjacent entity IDs must occupy disjoint elevation bands: G0={altG0:F4}, G1={altG1:F4}");
            Assert(altF0 > altG1, $"Flying world giant band ({altF0:F4}) must sit above ground giant bands ({altG1:F4})");
        }

        private static void TestWorldGiantPicking()
        {
            Vector3 a = Vector3.zero;
            Vector3 b = new Vector3(3f, 0f, 0f);
            Vector3 c = new Vector3(0f, 0f, 2f);
            Vector2 point = new Vector2(0.75f, 0.5f);
            Assert(GiantWorldRenderer.TryTriangle(point, a, b, c, out Vector3 weights), "Point in visible triangle must hit");
            AssertNear(weights.x, 0.5f, 1e-6f, "Alpha lookup weight A");
            AssertNear(weights.y, 0.25f, 1e-6f, "Alpha lookup weight B");
            AssertNear(weights.z, 0.25f, 1e-6f, "Alpha lookup weight C");
            Assert(GiantWorldRenderer.TryTriangle(point, c, b, a, out _), "Reversing winding must not change picking");
            Assert(!GiantWorldRenderer.TryTriangle(new Vector2(2.9f, 1.9f), a, b, c, out _), "Empty corner of triangle bounds must not hit");
            Assert(!GiantWorldRenderer.TryTriangle(point, a, b, b, out _), "Degenerate triangles must not hit");
        }

        private static void TestHarmonyTargetsExistInRimWorld17()
        {
            Assembly modAsm = typeof(CompGiantRig).Assembly;
            var patchClasses = modAsm.GetTypes().Where(t => t.GetCustomAttribute<HarmonyPatch>() != null).ToList();
            Assert(patchClasses.Count >= 10, $"Expected at least 10 Harmony patch classes, found {patchClasses.Count}");

            int verifiedPatches = 0;
            foreach (Type patchType in patchClasses)
            {
                MethodInfo prepareMethod = patchType.GetMethod("Prepare", BindingFlags.Public | BindingFlags.Static);
                MethodInfo targetMethodFinder = patchType.GetMethod("TargetMethod", BindingFlags.Public | BindingFlags.Static);
                if (targetMethodFinder != null)
                {
                    if (prepareMethod != null)
                    {
                        bool prepared = (bool)prepareMethod.Invoke(null, null);
                        Assert(prepared, $"{patchType.Name}.Prepare() returned false!");
                    }
                    MethodBase dynamicTarget = (MethodBase)targetMethodFinder.Invoke(null, null);
                    Assert(dynamicTarget != null, $"{patchType.Name}.TargetMethod() returned null!");
                    verifiedPatches++;
                    Console.WriteLine($"       -> Verified dynamic Harmony target: {dynamicTarget.DeclaringType?.Name}.{dynamicTarget.Name} <- {patchType.Name}");
                }

                foreach (MethodInfo patchMethod in patchType.GetMethods(BindingFlags.Public | BindingFlags.Static))
                {
                    var attrs = patchMethod.GetCustomAttributes<HarmonyPatch>().ToList();
                    if (attrs.Count == 0) continue;

                    Type declType = null;
                    string methodName = null;
                    Type[] argTypes = null;
                    MethodType? methodType = null;
                    foreach (HarmonyPatch attr in attrs)
                    {
                        if (attr.info.declaringType != null) declType = attr.info.declaringType;
                        if (attr.info.methodName != null) methodName = attr.info.methodName;
                        if (attr.info.argumentTypes != null) argTypes = attr.info.argumentTypes;
                        if (attr.info.methodType.HasValue) methodType = attr.info.methodType;
                    }

                    Assert(declType != null && !string.IsNullOrEmpty(methodName),
                        $"Incomplete [HarmonyPatch] on {patchType.Name}.{patchMethod.Name}");

                    MethodInfo target = methodType == MethodType.Getter
                        ? AccessTools.PropertyGetter(declType, methodName)
                        : (methodType == MethodType.Setter
                            ? AccessTools.PropertySetter(declType, methodName)
                            : (argTypes != null
                                ? AccessTools.Method(declType, methodName, argTypes)
                                : AccessTools.Method(declType, methodName)));

                    Assert(target != null,
                        $"Harmony target {declType.FullName}.{methodName} NOT FOUND in RimWorld 1.7 Assembly-CSharp!");

                    // Verify any ___field injections exist on declaring type!
                    foreach (ParameterInfo p in patchMethod.GetParameters())
                    {
                        if (p.Name.StartsWith("___", StringComparison.Ordinal))
                        {
                            string fieldName = p.Name.Substring(3);
                            FieldInfo fi = AccessTools.Field(declType, fieldName);
                            Assert(fi != null,
                                $"Injected field '{fieldName}' on {declType.FullName} (used by {patchMethod.Name}) NOT FOUND!");
                        }
                    }

                    verifiedPatches++;
                    Console.WriteLine($"       -> Verified Harmony target: {declType.Name}.{target.Name} <- {patchMethod.Name}");
                }
            }

            Assert(verifiedPatches >= 17, $"Expected at least 17 Harmony patch methods verified, got {verifiedPatches}");

            // Also verify private reflection fields in HarmonyPatches_CombatAndHitbox
            foreach (FieldInfo rf in typeof(HarmonyPatches_CombatAndHitbox).GetFields(BindingFlags.NonPublic | BindingFlags.Static))
            {
                object val = rf.GetValue(null);
                Assert(val != null, $"Cached reflection member HarmonyPatches_CombatAndHitbox.{rf.Name} is null!");
            }
        }

        private static void TestBodyStatsBiotechAndTranslations()
        {
            // 1. Validate every XML file in the mod is well-formed (excluding .verify/bin/obj)
            int xmlCount = 0;
            var xmlEnumOpts = new EnumerationOptions
            {
                RecurseSubdirectories = true,
                AttributesToSkip = FileAttributes.ReparsePoint | FileAttributes.System
            };
            foreach (string xmlFile in Directory.EnumerateFiles(ModRoot, "*.xml", xmlEnumOpts))
            {
                if (xmlFile.Contains($"{Path.DirectorySeparatorChar}.verify{Path.DirectorySeparatorChar}") ||
                    xmlFile.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}") ||
                    xmlFile.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}"))
                {
                    continue;
                }
                XDocument.Load(xmlFile);
                xmlCount++;
            }
            Assert(xmlCount >= 12, $"Expected at least 12 well-formed XML files in mod, checked {xmlCount}");

            // 2. Validate LoadFolders.xml & About/About.xml
            XDocument loadFolders = XDocument.Load(Path.Combine(ModRoot, "LoadFolders.xml"));
            Assert(loadFolders.Root?.Name.LocalName == "loadFolders", "LoadFolders.xml root element must be <loadFolders>");
            List<XElement> v17Entries = loadFolders.Root.Element("v1.7")?.Elements("li").ToList() ?? new List<XElement>();
            Assert(v17Entries.Any(e => e.Value == "1.7"), "LoadFolders.xml <v1.7> must include '1.7'");
            Assert(v17Entries.Any(e => e.Value == "1.7/Biotech" && e.Attribute("IfModActive")?.Value == "Ludeon.RimWorld.Biotech"),
                "LoadFolders.xml <v1.7> must conditionally load '1.7/Biotech' on Ludeon.RimWorld.Biotech");

            XDocument aboutDoc = XDocument.Load(Path.Combine(ModRoot, "About", "About.xml"));
            Assert(aboutDoc.Root?.Element("packageId")?.Value == "sanguo.giantcreatureframework",
                "About.xml <packageId> must be 'sanguo.giantcreatureframework'");
            Assert(aboutDoc.Root?.Element("shortName")?.Value == "GCF",
                "About.xml <shortName> must be 'GCF'");
            Assert(aboutDoc.Root?.Element("modDependencies")?.Elements("li")
                .Any(e => e.Element("packageId")?.Value == "brrainz.harmony") == true,
                "About.xml <modDependencies> must declare brrainz.harmony");
            string aboutDesc = aboutDoc.Root?.Element("description")?.Value ?? "";
            Assert(!string.IsNullOrWhiteSpace(aboutDesc) &&
                   !aboutDesc.Contains("Behemoth", StringComparison.OrdinalIgnoreCase) &&
                   !aboutDesc.Contains("渊骸龙兽", StringComparison.Ordinal) &&
                   aboutDesc.Contains("重装机械巨蝎", StringComparison.Ordinal),
                "About.xml description must describe the lean framework + built-in MechScorpion and contain no legacy 'Behemoth'/'渊骸龙兽' naming");

            // 3. Parse Bodies_MechScorpion.xml & verify 15 concrete BodyPartDefs and 43-part tree
            XDocument bodyDoc = XDocument.Load(ResolveMod17Path("Defs", "Bodies", "Bodies_MechScorpion.xml"));
            var partHitPoints = new Dictionary<string, float>(StringComparer.Ordinal);
            foreach (XElement bpEl in bodyDoc.Root.Elements("BodyPartDef"))
            {
                if (bpEl.Attribute("Abstract")?.Value == "True")
                {
                    continue;
                }
                string defName = bpEl.Element("defName")?.Value;
                Assert(!string.IsNullOrEmpty(defName), "BodyPartDef missing defName");
                float hp = ParseFloat(bpEl.Element("hitPoints")?.Value, -1f);
                Assert(hp > 0f, $"BodyPartDef '{defName}' must have positive hitPoints");
                partHitPoints[defName] = hp;
            }
            Assert(partHitPoints.Count == 16, $"Expected 16 concrete custom BodyPartDefs, got {partHitPoints.Count}");

            // Verify 1.5x Diabolus in-game HP scaling with baseHealthScale = 6.75 (zero double-scaling!)
            float scale = 6.75f;
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechCarapace"] * scale) == 372, "Carapace HP must equal 372 (1.5x Diabolus 248)");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechCephalothorax"] * scale) == 203, "Cephalothorax HP must equal 203 (1.5x Diabolus 135)");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechCapacitor"] * scale) == 338, "Hypercapacitor HP must equal 338 (1.5x Diabolus 225)");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechCrusherClaw"] * scale) == 270, "CrusherClaw HP must equal 270 (1.5x 180)");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechWalkingLeg"] * scale) == 203, "WalkingLeg HP must equal 203 (1.5x 135)");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechWalkingFoot"] * scale) == 135, "WalkingFoot HP must equal 135 (1.5x 90)");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechTailRing1"] * scale) == 372, "TailRing1 HP must equal 372");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechTailRing6"] * scale) == 203, "TailRing6 HP must equal 203");
            Assert(Mathf.CeilToInt(partHitPoints["GCF_MechTailStinger"] * scale) == 270, "TailStinger HP must equal 270");

            XElement bodyDefEl = bodyDoc.Root.Elements("BodyDef").FirstOrDefault(e => e.Element("defName")?.Value == "GCF_Body_MechScorpion");
            Assert(bodyDefEl != null, "Missing BodyDef GCF_Body_MechScorpion");
            XElement corePartEl = bodyDefEl.Element("corePart");
            Assert(corePartEl != null, "GCF_Body_MechScorpion missing corePart");

            var flatParts = new List<(string def, string customLabel, string tkeyPath)>();
            void WalkParts(XElement partEl, string pathPrefix, bool isRoot)
            {
                string def = partEl.Element("def")?.Value;
                string customLabel = partEl.Element("customLabel")?.Value;
                string curTKey = pathPrefix;
                if (!isRoot)
                {
                    string seg = (!string.IsNullOrEmpty(customLabel) ? customLabel : def).Replace(' ', '_');
                    curTKey = $"{pathPrefix}.parts.{seg}";
                }
                flatParts.Add((def, customLabel, curTKey));

                XElement childrenEl = partEl.Element("parts");
                if (childrenEl != null)
                {
                    float sumCov = 0f;
                    foreach (XElement cEl in childrenEl.Elements("li"))
                    {
                        float cov = ParseFloat(cEl.Element("coverage")?.Value, 0f);
                        Assert(cov > 0f, $"Part '{cEl.Element("def")?.Value}' missing positive coverage");
                        sumCov += cov;
                        WalkParts(cEl, curTKey, false);
                    }
                    Assert(sumCov < 1.0f - 1e-4f, $"Parent '{def}' child coverage sum must be < 1.0, got {sumCov:F3}");
                }
            }
            WalkParts(corePartEl, "GCF_Body_MechScorpion.corePart", true);
            Assert(flatParts.Count == 43, $"Expected 43 anatomical BodyPartRecords in GCF_Body_MechScorpion, got {flatParts.Count}");

            // 4. Verify all 18 BoneNodeDefs in GiantRigDefs_MechScorpion.xml map 1-to-1 to distinct anatomical parts
            XDocument rigDoc = XDocument.Load(ResolveMod17Path("Defs", "GiantRigDefs", "GiantRigDefs_MechScorpion.xml"));
            XElement rigEl = rigDoc.Root.Element("GiantCreatureFramework.GiantRigDef");
            Assert(rigEl.Element("rangedWeaponBoneId")?.Value == "tail_stinger", "GiantRigDef must declare rangedWeaponBoneId = tail_stinger");
            var matchedPartIndices = new HashSet<int>();
            foreach (XElement nEl in rigEl.Element("nodes").Elements("li"))
            {
                string nodeId = nEl.Element("nodeId")?.Value;
                string linkedBp = nEl.Element("linkedBodyPart")?.Value;
                string linkedCustom = nEl.Element("linkedBodyPartCustomLabel")?.Value;
                int foundIdx = -1;
                for (int p = 0; p < flatParts.Count; p++)
                {
                    if (!string.Equals(flatParts[p].def, linkedBp, StringComparison.Ordinal)) continue;
                    if (!string.IsNullOrEmpty(linkedCustom) &&
                        !string.Equals(flatParts[p].customLabel, linkedCustom, StringComparison.OrdinalIgnoreCase)) continue;
                    foundIdx = p;
                    break;
                }
                Assert(foundIdx >= 0, $"Rig node '{nodeId}' failed to resolve linkedBodyPart='{linkedBp}' customLabel='{linkedCustom}'");
                Assert(matchedPartIndices.Add(foundIdx), $"Rig node '{nodeId}' collides on same BodyPartRecord index {foundIdx}");
            }
            Assert(matchedPartIndices.Count == 18, $"Expected 18 distinct anatomical bone-to-part bindings, got {matchedPartIndices.Count}");

            // 5. Verify 1.5x Vanilla Diabolus stats in Races_MechScorpion.xml
            XDocument raceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_MechScorpion.xml"));
            XElement bulletEl = raceDoc.Root.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_Bullet_PlasmaStinger").Element("projectile");
            AssertNear(ParseFloat(bulletEl.Element("damageAmountBase")?.Value, 0f), 23f, 0.01f, "PlasmaStinger damage must be 23");
            AssertNear(ParseFloat(bulletEl.Element("armorPenetrationBase")?.Value, 0f), 0.525f, 0.001f, "PlasmaStinger AP must be 0.525");

            Assert(!raceDoc.Root.Elements("ThingDef").Any(e => e.Attribute("ParentName")?.Value == "BaseGun"),
                "Races_MechScorpion.xml must not define any BaseGun ThingDef (all attacks migrated to BoneNodeDef.partAttacks)");
            var (scorpRigCheck, _, _) = LoadMechScorpionFromXml();
            BoneNodeDef stingerBone = scorpRigCheck.nodes.First(n => n.nodeId == "tail_stinger");
            GiantPartAttackDef stingerBarrage = stingerBone.partAttacks.First(a => a.attackId == "scorpion_plasma_barrage");
            Assert(stingerBone.partAttacks.Count == 1 && !stingerBone.partAttacks.Any(a => a.attackId == "scorpion_tail_sting"),
                "tail_stinger must only declare Ranged scorpion_plasma_barrage (no close-range melee tail sting)");
            Assert(stingerBarrage.kind == GiantPartAttackKind.Ranged && stingerBarrage.projectileDef?.defName == "GCF_Bullet_PlasmaStinger",
                "tail_stinger must declare Ranged partAttack firing GCF_Bullet_PlasmaStinger");
            Assert(stingerBarrage.rangeOriginBoneId == "carapace", "scorpion_plasma_barrage must anchor range checks to carapace");
            AssertNear(stingerBarrage.range, 28.4f, 0.01f, "TailPod partAttack range must be 28.4");
            Assert(stingerBarrage.burstShotCount == 4, "TailPod partAttack burstShotCount must be 4");

            XElement mechEl = raceDoc.Root.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_MechScorpion");
            XElement stats = mechEl.Element("statBases");
            AssertNear(ParseFloat(stats.Element("MarketValue")?.Value, 0f), 6800f, 0.01f, "MarketValue must be 6800");
            AssertNear(ParseFloat(stats.Element("MoveSpeed")?.Value, 0f), 3.6f, 0.01f, "MoveSpeed must be 3.6 (1.5x 2.4)");
            AssertNear(ParseFloat(stats.Element("ArmorRating_Blunt")?.Value, 0f), 0.375f, 0.001f, "ArmorRating_Blunt must be 0.375 (1.5x 0.25)");
            AssertNear(ParseFloat(stats.Element("ArmorRating_Sharp")?.Value, 0f), 1.125f, 0.001f, "ArmorRating_Sharp must be 1.125 (1.5x 0.75)");
            AssertNear(ParseFloat(stats.Element("ArmorRating_Heat")?.Value, 0f), 2.00f, 0.001f, "ArmorRating_Heat must respect StatDef maxValue=2.00");
            AssertNear(ParseFloat(stats.Element("PsychicSensitivity")?.Value, 0f), 1.125f, 0.001f, "PsychicSensitivity must be 1.125");
            AssertNear(ParseFloat(stats.Element("EMPResistance")?.Value, 0f), 0.90f, 0.001f, "EMPResistance must be 0.90 (1.5x 0.60)");
            float bw = ParseFloat(stats.Element("BandwidthCost")?.Value, 0f);
            float wp = ParseFloat(stats.Element("WastepacksPerRecharge")?.Value, 0f);
            AssertNear(bw, 8f, 0.01f, "BandwidthCost must be 8");
            AssertNear(ParseFloat(stats.Element("ControlTakingTime")?.Value, 0f), 45f, 0.01f, "ControlTakingTime must be 45 (1.5x 30)");
            AssertNear(bw * wp, 37.5f, 0.01f, "Effective WastepacksPerRecharge (Bandwidth * Base) must be 37.5 (1.5x 25)");

            XElement raceProps = mechEl.Element("race");
            AssertNear(ParseFloat(raceProps.Element("baseBodySize")?.Value, 0f), 6.0f, 0.01f, "baseBodySize must be 6.0 (1.5x 4.0)");
            AssertNear(ParseFloat(raceProps.Element("baseHealthScale")?.Value, 0f), 6.75f, 0.01f, "baseHealthScale must be 6.75 (1.5x 4.5)");
            Assert(raceProps.Element("mechWeightClass")?.Value == "UltraHeavy", "mechWeightClass must be UltraHeavy");
            Assert(mechEl.Element("butcherProducts")?.Element("Steel")?.Value == "150", "butcherProducts Steel must be 150");
            Assert(mechEl.Element("butcherProducts")?.Element("Plasteel")?.Value == "80", "butcherProducts Plasteel must be 80");
            Assert(mechEl.Element("butcherProducts")?.Element("ComponentSpacer")?.Value == "3", "butcherProducts ComponentSpacer must be 3");

            XElement kindEl = raceDoc.Root.Elements("PawnKindDef").First(e => e.Element("defName")?.Value == "GCF_MechScorpion");
            AssertNear(ParseFloat(kindEl.Element("combatPower")?.Value, 0f), 480f, 0.01f, "combatPower must be 480");
            Assert(kindEl.Element("isBoss")?.Value == "false", "isBoss must be false");
            Assert(kindEl.Element("allowInMechClusters")?.Value == "true", "Built-in GCF_MechScorpion allowInMechClusters must be true");

            XDocument recipeDoc = XDocument.Load(ResolveMod17Path("Biotech", "Defs", "RecipeDefs", "Recipes_MechScorpion.xml"));
            XElement rEl = recipeDoc.Root.Element("RecipeDef");
            Assert(rEl.Element("defName")?.Value == "GCF_Gestate_MechScorpion", "Missing GCF_Gestate_MechScorpion");
            Assert(rEl.Element("researchPrerequisite")?.Value == "HighMechtech", "Must require HighMechtech");
            AssertNear(ParseFloat(rEl.Element("gestationCycles")?.Value, 0f), 18f, 0.01f, "gestationCycles must be 18");
            var ingCounts = rEl.Element("ingredients").Elements("li").ToDictionary(
                li => li.Element("filter").Element("thingDefs").Element("li").Value,
                li => ParseFloat(li.Element("count").Value, 0f));
            AssertNear(ingCounts["Steel"], 500f, 0.01f, "Gestation Steel must be 500");
            AssertNear(ingCounts["Plasteel"], 500f, 0.01f, "Gestation Plasteel must be 500");
            AssertNear(ingCounts["PowerfocusChip"], 2f, 0.01f, "Gestation PowerfocusChip must be 2");
            AssertNear(ingCounts["SubcoreHigh"], 1f, 0.01f, "Gestation SubcoreHigh must be 1");

            XDocument patchDoc = XDocument.Load(ResolveMod17Path("Biotech", "Patches", "Patch_Biotech_MechScorpion.xml"));
            string patchXmlText = patchDoc.ToString();
            Assert(patchXmlText.Contains("LargeMechGestator") && patchXmlText.Contains("ResurrectUltraheavyMech") && patchXmlText.Contains("Corpse_GCF_MechScorpion"),
                "Patch_Biotech_MechScorpion.xml must patch LargeMechGestator and ResurrectUltraheavyMech");

            // 7. Verify 100% ChineseSimplified translation key alignment for BodyDef & BodyPartDefs
            XDocument langBodyDoc = XDocument.Load(ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "BodyDef", "Bodies_MechScorpion.xml"));
            var langKeys = new HashSet<string>(langBodyDoc.Root.Elements().Select(e => e.Name.LocalName), StringComparer.Ordinal);
            Assert(langKeys.Contains("GCF_Body_MechScorpion.label"), "Missing GCF_Body_MechScorpion.label translation");
            foreach (var p in flatParts.Where(fp => !string.IsNullOrEmpty(fp.customLabel)))
            {
                string key = $"{p.tkeyPath}.customLabel";
                Assert(langKeys.Contains(key), $"Missing ChineseSimplified DefInjected key: {key}");
            }
            var expectedCustomKeys = new HashSet<string>(flatParts.Where(fp => !string.IsNullOrEmpty(fp.customLabel)).Select(fp => $"{fp.tkeyPath}.customLabel"), StringComparer.Ordinal);
            foreach (string lk in langKeys.Where(k => k != "GCF_Body_MechScorpion.label"))
            {
                Assert(expectedCustomKeys.Contains(lk), $"Orphaned ChineseSimplified DefInjected key: {lk}");
            }

            XDocument langBpDoc = XDocument.Load(ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "BodyPartDef", "Bodies_MechScorpion.xml"));
            var langBpKeys = new HashSet<string>(langBpDoc.Root.Elements().Select(e => e.Name.LocalName), StringComparer.Ordinal);
            foreach (string bpDef in partHitPoints.Keys)
            {
                Assert(langBpKeys.Contains($"{bpDef}.label"), $"Missing ChineseSimplified BodyPartDef label: {bpDef}.label");
            }
        }

        private static void TestSoftBodyWhipAndMammalOverlap()
        {
            // Framework-pure Verlet+XPBD SoftWhipRuntime & DampedBezierChainRuntime verification on a synthetic GiantRigDef
            var strikeAnim = new GiantAnimDef
            {
                defName = "Test_SyntheticDualWhipSlam",
                durationTicks = 44f,
                loop = false,
                impactTick = 22f,
                tracks = new List<BoneAnimTrack>
                {
                    new BoneAnimTrack
                    {
                        nodeId = "whip_l_root",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f },
                            new BoneKeyframe { tick = 12f, angle = -38f },
                            new BoneKeyframe { tick = 22f, angle = 56f },
                            new BoneKeyframe { tick = 44f, angle = 0f }
                        }
                    },
                    new BoneAnimTrack
                    {
                        nodeId = "whip_r_root",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f },
                            new BoneKeyframe { tick = 12f, angle = 38f },
                            new BoneKeyframe { tick = 22f, angle = -56f },
                            new BoneKeyframe { tick = 44f, angle = 0f }
                        }
                    }
                }
            };

            var rig = new GiantRigDef
            {
                defName = "Test_SyntheticSoftWhipRig",
                deathAnim = new GiantAnimDef
                {
                    defName = "Test_SyntheticSoftWhipDeath",
                    durationTicks = 30f,
                    loop = false,
                    tracks = new List<BoneAnimTrack>
                    {
                        new BoneAnimTrack
                        {
                            nodeId = "thorax",
                            keyframes = new List<BoneKeyframe>
                            {
                                new BoneKeyframe { tick = 0f, angle = 0f },
                                new BoneKeyframe { tick = 30f, angle = 14f }
                            }
                        }
                    }
                },
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef
                    {
                        nodeId = "thorax",
                        texPath = "Things/Pawn/GiantCreature/MechScorpion/Carapace",
                        drawSize = new Vector2(5.0f, 5.0f),
                        pivotPixel = new Vector2(256f, 256f),
                        layerOffset = 0f
                    },
                    new BoneNodeDef
                    {
                        nodeId = "whip_l_root",
                        parentId = "thorax",
                        texPath = "Things/Pawn/GiantCreature/MechScorpion/ClawLeft",
                        drawSize = new Vector2(2.2f, 2.2f),
                        pivotPixel = new Vector2(256f, 256f),
                        parentSocketPixel = new Vector2(128f, 180f),
                        layerOffset = 1.6f,
                        hideWhenMissing = true
                    },
                    new BoneNodeDef
                    {
                        nodeId = "whip_r_root",
                        parentId = "thorax",
                        texPath = "Things/Pawn/GiantCreature/MechScorpion/ClawRight",
                        drawSize = new Vector2(2.2f, 2.2f),
                        pivotPixel = new Vector2(256f, 256f),
                        parentSocketPixel = new Vector2(384f, 180f),
                        layerOffset = 1.6f,
                        hideWhenMissing = true
                    }
                },
                softWhips = new List<SoftWhipDef>
                {
                    new SoftWhipDef
                    {
                        whipId = "whip_left",
                        rootBoneId = "whip_l_root",
                        torsoBoneId = "thorax",
                        texPath = "Things/Pawn/GiantCreature/MechScorpion/TailSeg1",
                        exitPixel = new Vector2(256f, 256f),
                        particleCount = 24,
                        totalLength = 14.2f,
                        baseWidth = 0.85f,
                        tipWidthFactor = 0.28f,
                        layerOffset = 1.0f,
                        lateralSideSign = -1f,
                        colliderCenterLocal = new Vector2(0f, -0.5f),
                        colliderRadii = new Vector2(2.1f, 3.0f),
                        strikeAnimDefs = new List<string> { strikeAnim.defName }
                    },
                    new SoftWhipDef
                    {
                        whipId = "whip_right",
                        rootBoneId = "whip_r_root",
                        torsoBoneId = "thorax",
                        texPath = "Things/Pawn/GiantCreature/MechScorpion/TailSeg1",
                        exitPixel = new Vector2(256f, 256f),
                        particleCount = 24,
                        totalLength = 14.2f,
                        baseWidth = 0.85f,
                        tipWidthFactor = 0.28f,
                        layerOffset = 1.0f,
                        lateralSideSign = 1f,
                        colliderCenterLocal = new Vector2(0f, -0.5f),
                        colliderRadii = new Vector2(2.1f, 3.0f),
                        strikeAnimDefs = new List<string> { strikeAnim.defName }
                    }
                }
            };
            rig.BuildTopology();
            Assert(!rig.ConfigErrors().Any(), $"Synthetic SoftWhip rig produced ConfigErrors: {string.Join("; ", rig.ConfigErrors())}");

            SoftWhipDef whipDef = rig.softWhips[0];
            SoftWhipDef whipRightDef = rig.softWhips[1];
            Assert(rig.TryGetNodeIndex("whip_l_root", out int whLRootIdx) && rig.TryGetNodeIndex("whip_r_root", out _),
                "Missing synthetic whip root bones");

            float ComputeMinThoraxEllipseRatio(SoftWhipRuntime rt, BoneWorldPose[] wp, Vector2 colliderLocal, Vector2 colliderRadii)
            {
                int tIdx = rt.Def.resolvedTorsoBoneIndex >= 0 ? rt.Def.resolvedTorsoBoneIndex : 0;
                Vector2 center = wp[tIdx].jointWorldXZ + SkeletalKinematics.RotateCW(colliderLocal, wp[tIdx].worldAngleDeg);
                float angleDeg = wp[tIdx].worldAngleDeg;
                float minRatio = float.PositiveInfinity;
                ReadOnlySpan<Vector2> pts = rt.PhysicsParticlesWorldXZ;
                for (int i = 1; i < pts.Length; i++)
                {
                    Vector2 rel = SkeletalKinematics.RotateCW(pts[i] - center, -angleDeg);
                    float rx = rel.x / Mathf.Max(0.1f, colliderRadii.x);
                    float rz = rel.y / Mathf.Max(0.1f, colliderRadii.y);
                    float r = Mathf.Sqrt(rx * rx + rz * rz);
                    if (r < minRatio) minRatio = r;
                }
                return minRatio;
            }

            var whipRt = new SoftWhipRuntime(whipDef);
            int n = rig.SortedNodes.Length;
            var local = new BoneLocalPose[n];
            var miss = new bool[n];
            var world = new BoneWorldPose[n];
            Vector2 rootXZ = new Vector2(60.5f, 60.5f);
            Vector2 strikeTarget = rootXZ + new Vector2(0f, 11.0f);
            float maxTipSpeed = 0f;

            for (int t = 0; t <= 44; t++)
            {
                for (int i = 0; i < n; i++) local[i] = BoneLocalPose.Identity;
                strikeAnim.EvaluateInto(rig, t, local);
                var stepCtx = new BezierChainStepContext
                {
                    BodyWorldAngleDeg = 0f,
                    ActiveClipDefName = strikeAnim.defName,
                    ActiveClipNormalizedTime = t / strikeAnim.durationTicks,
                    HasAttackTarget = true,
                    AttackTargetWorldXZ = strikeTarget
                };
                Assert(whipRt.Step(rig, rootXZ, 0f, local, miss, false, 1f, in stepCtx), $"SoftWhip Step failed at t={t}");
                SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, local, miss, world);

                Vector2 exitExpected = world[whLRootIdx].UVToWorldXZ(whipDef.resolvedExitUV.x, whipDef.resolvedExitUV.y);
                ReadOnlySpan<Vector2> phys = whipRt.PhysicsParticlesWorldXZ;
                Assert((phys[0] - exitExpected).magnitude < 1e-3f, $"SoftWhip particle[0] drifted at t={t}");

                float arcLen = 0f;
                for (int k = 1; k < phys.Length; k++) arcLen += (phys[k] - phys[k - 1]).magnitude;
                Assert(arcLen <= whipDef.totalLength * 1.03f, $"SoftWhip stretched beyond inextensibility bound at t={t}: {arcLen:F3}");
                Assert(ComputeMinThoraxEllipseRatio(whipRt, world, whipDef.colliderCenterLocal, whipDef.colliderRadii) >= 0.88f,
                    $"SoftWhip penetrated thorax collider at t={t}");
                maxTipSpeed = Mathf.Max(maxTipSpeed, whipRt.TipSpeedCellsPerTick);
            }
            Assert(maxTipSpeed > 1.0f, $"Expected whip-crack distal speed > 1.0 cells/tick, got {maxTipSpeed:F3}");

            var settleCtx = new BezierChainStepContext { BodyWorldAngleDeg = 0f };
            float settledSpeed = 0f;
            for (int s = 0; s < 90; s++)
            {
                for (int i = 0; i < n; i++) local[i] = BoneLocalPose.Identity;
                Vector2 beforeTip = whipRt.PhysicsParticlesWorldXZ[whipDef.particleCount - 1];
                whipRt.Step(rig, rootXZ, 0f, local, miss, false, 1f, in settleCtx);
                settledSpeed = (whipRt.PhysicsParticlesWorldXZ[whipDef.particleCount - 1] - beforeTip).magnitude;
            }
            Assert(settledSpeed < maxTipSpeed * 0.20f, $"Expected damped decay of soft whip tip speed (<20% of peak): {settledSpeed:F4}");

            // Severing root bone or soft tendril hides SoftWhipRuntime cleanly
            miss[whLRootIdx] = true;
            Assert(!whipRt.Step(rig, rootXZ, 0f, local, miss, false, 1f, in settleCtx) && !whipRt.CreateSnapshot(rootXZ).visible,
                "SoftWhip must hide when root bone is severed");
            Array.Clear(miss, 0, n);
            Assert(!whipRt.Step(rig, rootXZ, 0f, local, miss, true, 1f, in settleCtx) && !whipRt.CreateSnapshot(rootXZ).visible,
                "SoftWhip must hide when tendrilMissing is true");

            // Rest rearward drape + HitCells rasterization routing back to resolvedRootBoneIndex
            var leftWalkRt = new SoftWhipRuntime(whipDef);
            var rightWalkRt = new SoftWhipRuntime(whipRightDef);
            for (int i = 0; i < n; i++) local[i] = BoneLocalPose.Identity;
            leftWalkRt.Step(rig, rootXZ, 0f, local, miss, false, 0f, in settleCtx);
            rightWalkRt.Step(rig, rootXZ, 0f, local, miss, false, 0f, in settleCtx);
            Assert(leftWalkRt.PhysicsParticlesWorldXZ[whipDef.particleCount - 1].y - rootXZ.y < -10.0f,
                "Soft whip must naturally drape rearward at rest");

            var fullOpaqueMask = TextureAlphaMask.FromPngFile(ResolveMod17Path("Textures", "Things", "Pawn", "GiantCreature", "MechScorpion", "Carapace.png"), 1);
            var masks = new[] { fullOpaqueMask, fullOpaqueMask, fullOpaqueMask };
            var softMasks = new[] { fullOpaqueMask, fullOpaqueMask };
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, local, miss, world);
            var softSnaps = new[] { leftWalkRt.CreateSnapshot(rootXZ), rightWalkRt.CreateSnapshot(rootXZ) };
            var hitFp = new GiantFootprintData();
            IntVec3 center = new IntVec3(Mathf.FloorToInt(rootXZ.x), 0, Mathf.FloorToInt(rootXZ.y));
            hitFp.Rebuild(rig, world, masks, center, new IntVec3(120, 1, 120), softSnaps, softMasks);
            Vector2 distalSample = leftWalkRt.PhysicsParticlesWorldXZ[whipDef.particleCount - 4];
            IntVec3 distalCell = new IntVec3(Mathf.FloorToInt(distalSample.x), 0, Mathf.FloorToInt(distalSample.y));
            Assert(hitFp.hitCellSet.Contains(distalCell), $"Expected soft whip distal cell {distalCell} in HitCells");
            Assert(hitFp.TryHitTestPoint(rig, masks, new Vector3(distalSample.x, 0f, distalSample.y), out int whipHitBoneIdx, softMasks)
                   && whipHitBoneIdx == whipDef.resolvedRootBoneIndex,
                "Point hit on soft whip distal shaft must resolve back to resolvedRootBoneIndex");
        }

        private static void TestModSettingsAndDebugDefaultsOff()
        {
            // ModSettings must contain ONLY the 3 debug visualization toggles + default-off enableAuthoringTerminal/enableDebugPanel (all gameplay rules belong on XML Defs)
            string[] settingFields = typeof(GiantCreatureFrameworkSettings)
                .GetFields(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
                .Select(f => f.Name)
                .OrderBy(n => n, StringComparer.Ordinal)
                .ToArray();
            string[] expectedSettingFields = { "drawCollisionCells", "drawHitCells", "drawSkeleton", "enableAuthoringTerminal", "enableDebugPanel" };
            Assert(settingFields.SequenceEqual(expectedSettingFields),
                $"GiantCreatureFrameworkSettings must expose ONLY [drawCollisionCells, drawHitCells, drawSkeleton, enableAuthoringTerminal, enableDebugPanel], got [{string.Join(", ", settingFields)}]");

            var settings = new GiantCreatureFrameworkSettings();
            Assert(!settings.drawCollisionCells, "drawCollisionCells must default to false");
            Assert(!settings.drawHitCells, "drawHitCells must default to false");
            Assert(!settings.drawSkeleton, "drawSkeleton must default to false");
            Assert(!settings.enableDebugPanel, "enableDebugPanel must default to false");
            Assert(!settings.enableAuthoringTerminal, "enableAuthoringTerminal must default to false");

            var observedTerminalStates = new List<bool>();
            var observedDebugPanelStates = new List<bool>();
            Action<bool> handler = state => observedTerminalStates.Add(state);
            Action<bool> debugPanelHandler = state => observedDebugPanelStates.Add(state);
            GiantCreatureFrameworkMod.AuthoringTerminalChanged += handler;
            GiantCreatureFrameworkMod.DebugPanelChanged += debugPanelHandler;
            try
            {
                GiantCreatureFrameworkMod.NotifyAuthoringTerminalState(false, force: true);
                GiantCreatureFrameworkMod.NotifyDebugPanelState(false, force: true);
                observedTerminalStates.Clear();
                observedDebugPanelStates.Clear();
                settings.enableAuthoringTerminal = true;
                settings.enableDebugPanel = true;
                settings.ApplyToRuntime();
                settings.ApplyToRuntime(); // duplicate must not fire twice
                settings.ResetAllToDefault();
                Assert(observedTerminalStates.SequenceEqual(new[] { true, false }),
                    $"AuthoringTerminalChanged must fire strictly on state transitions [true, false], got [{string.Join(", ", observedTerminalStates)}]");
                Assert(observedDebugPanelStates.SequenceEqual(new[] { true, false }),
                    $"DebugPanelChanged must fire strictly on state transitions [true, false], got [{string.Join(", ", observedDebugPanelStates)}]");
            }
            finally
            {
                GiantCreatureFrameworkMod.AuthoringTerminalChanged -= handler;
                GiantCreatureFrameworkMod.DebugPanelChanged -= debugPanelHandler;
            }

            IReadOnlyList<GiantDebugActionEntry> builtInCatalog = GiantDebugActionCatalog.BuiltInActions;
            Assert(builtInCatalog != null && builtInCatalog.Count == 6,
                $"GiantDebugActionCatalog.BuiltInActions must expose exactly 6 framework-built-in debug tools (2 MechScorpion spawn + 4 tools), got {builtInCatalog?.Count ?? 0}");
            Assert(builtInCatalog.Count(a => a.Category == GiantDebugActionCategory.Spawn && a.IsMapTool) == 2,
                "GiantDebugActionCatalog.BuiltInActions must include ONLY 2 built-in Spawn actions (MechScorpion Player & Hostile)");
            Assert(builtInCatalog.Count(a => a.Category == GiantDebugActionCategory.Tools) == 4,
                "GiantDebugActionCatalog.BuiltInActions must include 4 core utility/telemetry tools");

            GiantDebugActionCatalog.InvalidateDynamicCache();
            IReadOnlyList<GiantDebugActionEntry> catalog = GiantDebugActionCatalog.AllActions;
            Assert(catalog != null && catalog.Count >= 6,
                $"GiantDebugActionCatalog.AllActions offline baseline must expose >= 6 actions, got {catalog?.Count ?? 0}");
            int baselineCount = catalog!.Count;

            // Dynamic discovery regression: registering a custom CompProperties_GiantRig PawnKindDef must auto-appear (+2 ToolMap actions) with O(1) cache reuse
            var tempDynamicKind = new PawnKindDef
            {
                defName = "Custom_TestDynamicHeli",
                label = "test dynamic heli",
                race = new ThingDef
                {
                    defName = "Custom_TestDynamicHeli_Race",
                    comps = new List<CompProperties> { new CompProperties_GiantRig() }
                }
            };
            DefDatabase<PawnKindDef>.Add(tempDynamicKind);
            try
            {
                IReadOnlyList<GiantDebugActionEntry> dynamicCatalog = GiantDebugActionCatalog.AllActions;
                Assert(dynamicCatalog != null && dynamicCatalog.Count == baselineCount + 2,
                    $"GiantDebugActionCatalog.AllActions must auto-discover +2 actions for custom giant PawnKindDef, got {dynamicCatalog?.Count ?? 0}");
                GiantDebugActionEntry dynPlayer = dynamicCatalog.FirstOrDefault(a => a.Id == "SpawnDynamicPlayer_Custom_TestDynamicHeli");
                GiantDebugActionEntry dynHostile = dynamicCatalog.FirstOrDefault(a => a.Id == "SpawnDynamicHostile_Custom_TestDynamicHeli");
                Assert(dynPlayer != null && dynPlayer.Category == GiantDebugActionCategory.Spawn && dynPlayer.IsMapTool,
                    "Dynamic player spawn entry missing or not a Spawn ToolMap action");
                Assert(dynHostile != null && dynHostile.Category == GiantDebugActionCategory.Spawn && dynHostile.IsMapTool,
                    "Dynamic hostile spawn entry missing or not a Spawn ToolMap action");
                string playerLabel = dynPlayer.GetDisplayLabel();
                string hostileLabel = dynHostile.GetDisplayLabel();
                Assert(playerLabel.Contains("Test dynamic heli", StringComparison.Ordinal) && playerLabel.StartsWith("T: ", StringComparison.Ordinal),
                    $"Unexpected dynamic player display label: '{playerLabel}'");
                Assert(hostileLabel.Contains("Test dynamic heli", StringComparison.Ordinal) && hostileLabel.StartsWith("T: ", StringComparison.Ordinal),
                    $"Unexpected dynamic hostile display label: '{hostileLabel}'");
                Assert(ReferenceEquals(dynamicCatalog, GiantDebugActionCatalog.AllActions),
                    "GiantDebugActionCatalog.AllActions must reuse cached list across calls when DefDatabase count/tail is unchanged");
            }
            finally
            {
                MethodInfo removeDefMethod = typeof(DefDatabase<PawnKindDef>).GetMethod(
                    "Remove",
                    BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
                if (removeDefMethod != null)
                {
                    removeDefMethod.Invoke(null, new object[] { tempDynamicKind });
                }
                else
                {
                    DefDatabase<PawnKindDef>.AllDefsListForReading.Remove(tempDynamicKind);
                }
                GiantDebugActionCatalog.InvalidateDynamicCache();
            }
            Assert(GiantDebugActionCatalog.AllActions.Count == baselineCount,
                $"GiantDebugActionCatalog.AllActions must return to {baselineCount} after removing temporary dynamic PawnKindDef and invalidating cache");

            // All gameplay capabilities are Def-driven with sane enabled defaults on GiantRigDef / SteeringConfigDef
            var defRig = new GiantRigDef();
            Assert(defRig.rushWhenEnemyFar, "GiantRigDef.rushWhenEnemyFar must default to true");
            Assert(defRig.crushBuildingsAndTerrain, "GiantRigDef.crushBuildingsAndTerrain must default to true");
            Assert(defRig.canCrushConstructedBuildings && defRig.canCrushNaturalRock && defRig.canCrushDestructibleTerrain,
                "GiantRigDef crushing sub-flags must default to true");
            Assert(defRig.protectAlliedStructures, "GiantRigDef.protectAlliedStructures must default to true");
            Assert(defRig.enableCollisionPawnPushOut, "GiantRigDef.enableCollisionPawnPushOut must default to true");
            Assert(defRig.enableGiantToGiantCollision, "GiantRigDef.enableGiantToGiantCollision must default to true");
            Assert(defRig.enableLimbPartDamageRouting, "GiantRigDef.enableLimbPartDamageRouting must default to true");
            Assert(defRig.useDirectionalMeleeTools, "GiantRigDef.useDirectionalMeleeTools must default to true");
            Assert(defRig.enableBoneArmorAndWeakpoints, "GiantRigDef.enableBoneArmorAndWeakpoints must default to true");
            Assert(defRig.enableMeleeCleave, "GiantRigDef.enableMeleeCleave must default to true");
            Assert(defRig.enableMeleeKnockback, "GiantRigDef.enableMeleeKnockback must default to true");
            Assert(defRig.enableGiantVfx, "GiantRigDef.enableGiantVfx must default to true");
            Assert(defRig.enableMultiCellExplosionRouting, "GiantRigDef.enableMultiCellExplosionRouting must default to true");
            Assert(defRig.enableCorpseFootprint, "GiantRigDef.enableCorpseFootprint must default to true");
            Assert(defRig.healthBarDef == null, "GiantRigDef.healthBarDef must be null unless opted in via XML Def");

            var steerCfg = new SteeringConfigDef();
            Assert(steerCfg.enabled && steerCfg.enableNeckIdleAndGaitArticulation,
                "SteeringConfigDef.enabled and enableNeckIdleAndGaitArticulation must default to true");
            AssertNear(steerCfg.intensityScale, 1.0f, 0.001f, "SteeringConfigDef.intensityScale must default to 1.0");

            var comp = new CompGiantRig();
            Assert(!comp.DebugDrawFootprint, "CompGiantRig.DebugDrawFootprint must default to false");
            Assert(!comp.DebugDrawSkeleton, "CompGiantRig.DebugDrawSkeleton must default to false");
            Assert(!comp.DebugDrawOnSelect, "CompGiantRig.DebugDrawOnSelect must default to false");

            Assert(!GiantFootprintMapComponent.GlobalDebugDrawCollisionCells, "GlobalDebugDrawCollisionCells must default to false");
            Assert(!GiantFootprintMapComponent.GlobalDebugDrawHitCells, "GlobalDebugDrawHitCells must default to false");
            Assert(!GiantFootprintMapComponent.GlobalDebugDrawFootprints, "GlobalDebugDrawFootprints must default to false");
            Assert(!GiantFootprintMapComponent.GlobalDebugDrawSkeleton, "GlobalDebugDrawSkeleton must default to false");

            settings.drawCollisionCells = true;
            settings.ApplyToRuntime();
            Assert(GiantFootprintMapComponent.GlobalDebugDrawCollisionCells
                && !GiantFootprintMapComponent.GlobalDebugDrawHitCells
                && !GiantFootprintMapComponent.GlobalDebugDrawFootprints,
                "Enabling only drawCollisionCells must enable GlobalDebugDrawCollisionCells without enabling HitCells");

            settings.drawHitCells = true;
            settings.drawSkeleton = true;
            settings.ApplyToRuntime();
            Assert(GiantFootprintMapComponent.GlobalDebugDrawCollisionCells
                && GiantFootprintMapComponent.GlobalDebugDrawHitCells
                && GiantFootprintMapComponent.GlobalDebugDrawFootprints
                && GiantFootprintMapComponent.GlobalDebugDrawSkeleton,
                "ApplyToRuntime must sync all 3 debug flags to GiantFootprintMapComponent");

            settings.ResetAllToDefault();
            Assert(!settings.drawCollisionCells && !GiantFootprintMapComponent.GlobalDebugDrawCollisionCells,
                "ResetAllToDefault must clear GlobalDebugDrawCollisionCells");
            Assert(!settings.drawHitCells && !GiantFootprintMapComponent.GlobalDebugDrawHitCells,
                "ResetAllToDefault must clear GlobalDebugDrawHitCells");
            Assert(!settings.drawSkeleton && !GiantFootprintMapComponent.GlobalDebugDrawSkeleton,
                "ResetAllToDefault must clear GlobalDebugDrawSkeleton");
            Assert(!GiantFootprintMapComponent.GlobalDebugDrawFootprints,
                "ResetAllToDefault must clear GlobalDebugDrawFootprints");

            string[] requiredSettingKeys =
            {
                "GCF_SettingsCategory",
                "GCF_SettingsSection_Debug",
                "GCF_Setting_DrawCollisionCells",
                "GCF_Setting_DrawCollisionCells_Desc",
                "GCF_Setting_DrawHitCells",
                "GCF_Setting_DrawHitCells_Desc",
                "GCF_Setting_DrawSkeleton",
                "GCF_Setting_DrawSkeleton_Desc",
                "GCF_SettingsSection_Authoring",
                "GCF_Setting_EnableAuthoringTerminal",
                "GCF_Setting_EnableAuthoringTerminal_Desc",
                "GCF_Setting_LoadedGiantsHeader",
                "GCF_Setting_LoadedGiantsEmpty",
                "GCF_GiantSource_BuiltIn",
                "GCF_GiantSource_Custom",
                "GCF_GiantSource_ExternalMod",
                "GCF_GiantSource_UnknownMod",
                "GCF_Setting_OpenCreaturesFolder"
            };
            string[] removedObsoleteKeys =
            {
                "GCF_SettingsSection_Gameplay",
                "GCF_ResetGameplaySettingsBtn",
                "GCF_Setting_EnableDistantEnemyRush",
                "GCF_Setting_EnableCollisionDestruction",
                "GCF_Setting_EnableDebugActions"
            };

            foreach (string lang in new[] { "English", "ChineseSimplified" })
            {
                string keyedPath = ResolveMod17Path("Languages", lang, "Keyed", "GiantCreatureFramework_Keys.xml");
                XDocument doc = XDocument.Load(keyedPath);
                var existingKeys = new HashSet<string>(doc.Root.Elements().Select(e => e.Name.LocalName), StringComparer.Ordinal);
                foreach (string reqKey in requiredSettingKeys)
                {
                    Assert(existingKeys.Contains(reqKey), $"Missing setting translation key '{reqKey}' in {lang} Keyed XML");
                }
                foreach (string oldKey in removedObsoleteKeys)
                {
                    Assert(!existingKeys.Contains(oldKey), $"Obsolete non-Def/removed setting key '{oldKey}' must not exist in {lang} Keyed XML");
                }
            }

            // Verify Loaded Giants roster source classification (Built-in vs Custom vs External Mod Name, never packageId field)
            string expectedSuffix = Path.Combine("Config", "GiantCreatureFramework", "Creatures");
            Assert(GiantCreatureFrameworkMod.CreaturesFolderPath.EndsWith(expectedSuffix, StringComparison.OrdinalIgnoreCase),
                $"CreaturesFolderPath must end with '{expectedSuffix}', got '{GiantCreatureFrameworkMod.CreaturesFolderPath}'");

            string tempModRoot = Path.Combine(Path.GetTempPath(), "GCF_ExtModNameTest_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(Path.Combine(tempModRoot, "About"));
            File.WriteAllText(
                Path.Combine(tempModRoot, "About", "About.xml"),
                "<?xml version=\"1.0\" encoding=\"utf-8\"?><ModMetaData><name>边缘猎人扩展包</name><packageId>testauthor.frontierhunters</packageId></ModMetaData>");

            var gcfPack = (ModContentPack)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(ModContentPack));
            typeof(ModContentPack).GetField("packageIdInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(gcfPack, "sanguo.giantcreatureframework");
            typeof(ModContentPack).GetField("packageIdPlayerFacingInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(gcfPack, "sanguo.giantcreatureframework");
            typeof(ModContentPack).GetField("nameInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(gcfPack, "Giant Creature Framework");

            var extPack = (ModContentPack)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(ModContentPack));
            typeof(ModContentPack).GetField("rootDirInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(extPack, new DirectoryInfo(tempModRoot));
            typeof(ModContentPack).GetField("packageIdInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(extPack, "testauthor.frontierhunters");
            typeof(ModContentPack).GetField("packageIdPlayerFacingInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(extPack, "testauthor.frontierhunters");
            // Simulate worst-case field fallback in nameInt to prove About.xml <name> wins over packageId
            typeof(ModContentPack).GetField("nameInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(extPack, "testauthor.frontierhunters");

            var builtInDef = new ThingDef
            {
                defName = "Test_BuiltInGiantRace",
                label = "雄火龙",
                thingClass = typeof(Pawn),
                race = new RaceProperties(),
                modContentPack = gcfPack,
                comps = new List<CompProperties> { new CompProperties_GiantRig() }
            };
            var customDef = new ThingDef
            {
                defName = "Test_CustomGiantRace",
                label = "苍冠飞龙",
                thingClass = typeof(Pawn),
                race = new RaceProperties(),
                modContentPack = gcfPack,
                comps = new List<CompProperties> { new CompProperties_GiantRig() }
            };
            var extModDef = new ThingDef
            {
                defName = "Test_ExternalGiantRace",
                label = "雷狼龙",
                thingClass = typeof(Pawn),
                race = new RaceProperties(),
                modContentPack = extPack,
                comps = new List<CompProperties> { new CompProperties_GiantRig() }
            };

            DefDatabase<ThingDef>.Add(builtInDef);
            DefDatabase<ThingDef>.Add(customDef);
            DefDatabase<ThingDef>.Add(extModDef);
            GiantCreatureFramework.Agent.UI.AuthoringTerminalHost.RegisterCustomDefClassifier(d => ReferenceEquals(d, customDef));
            try
            {
                var loadedGiants = GiantCreatureFrameworkMod.CollectLoadedGiants(gcfPack);
                var builtInHit = loadedGiants.FirstOrDefault(e => e.DisplayName == "雄火龙");
                var customHit = loadedGiants.FirstOrDefault(e => e.DisplayName == "苍冠飞龙");
                var extHit = loadedGiants.FirstOrDefault(e => e.DisplayName == "雷狼龙");

                Assert(builtInHit.DisplayName == "雄火龙" && builtInHit.SourceKind == GiantCreatureFrameworkMod.GiantSourceKind.BuiltIn,
                    $"Built-in giant classification failed: name='{builtInHit.DisplayName}', kind={builtInHit.SourceKind}");
                Assert(customHit.DisplayName == "苍冠飞龙" && customHit.SourceKind == GiantCreatureFrameworkMod.GiantSourceKind.Custom,
                    $"Custom giant classification failed: name='{customHit.DisplayName}', kind={customHit.SourceKind}");
                Assert(extHit.DisplayName == "雷狼龙"
                    && extHit.SourceKind == GiantCreatureFrameworkMod.GiantSourceKind.ExternalMod
                    && extHit.SourceLabel == "边缘猎人扩展包"
                    && !extHit.SourceLabel.Contains("testauthor.frontierhunters", StringComparison.OrdinalIgnoreCase),
                    $"External mod giant must display mod title '边缘猎人扩展包' (never packageId), got '{extHit.SourceLabel}'");
            }
            finally
            {
                GiantCreatureFramework.Agent.UI.AuthoringTerminalHost.RegisterCustomDefClassifier(null);
                DefDatabase<ThingDef>.AllDefsListForReading.Remove(builtInDef);
                DefDatabase<ThingDef>.AllDefsListForReading.Remove(customDef);
                DefDatabase<ThingDef>.AllDefsListForReading.Remove(extModDef);
                try { Directory.Delete(tempModRoot, recursive: true); } catch { }
            }
        }

        private static void TestRosterPruningAndDevModeOnlyIsolation()
        {
            Assert(!Directory.Exists(ResolveMod17Path("Textures", "Things", "Pawn", "GiantCreature", "Behemoth")),
                "Behemoth texture directory must be completely deleted");
            Assert(!Directory.Exists(Path.Combine(ModRoot, "1.7", "Anomaly")), "1.7/Anomaly folder must be completely removed");
            foreach (string searchSub in new[] { "Defs", "Biotech", "Languages" })
            {
                foreach (string xmlFile in EnumerateAllMod17Files(searchSub, "*.xml", SearchOption.AllDirectories))
                {
                    string fn = Path.GetFileName(xmlFile);
                    Assert(!fn.Contains("Behemoth", StringComparison.OrdinalIgnoreCase) && !fn.Contains("Abyssal", StringComparison.OrdinalIgnoreCase),
                        $"Found leftover Behemoth/Abyssal XML file: {xmlFile}");
                    string content = File.ReadAllText(xmlFile);
                    Assert(!content.Contains("GCF_Behemoth", StringComparison.OrdinalIgnoreCase) &&
                           !content.Contains("GCF_AbyssalDragonBeast", StringComparison.OrdinalIgnoreCase),
                        $"Found leftover Behemoth/Abyssal XML reference inside {xmlFile}");
                }
            }
            string debugSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Debug", "DebugActions_GiantCreature.cs"));
            Assert(!debugSrc.Contains("Behemoth", StringComparison.OrdinalIgnoreCase) && !debugSrc.Contains("Abyssal", StringComparison.OrdinalIgnoreCase),
                "DebugActions_GiantCreature.cs must contain zero Behemoth or Abyssal references");

            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Defs", "RecipeDefs", "Recipes_ProtossCarrier.xml"))), "Recipes_ProtossCarrier.xml must be removed");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Patches", "Patch_Biotech_ProtossCarrier.xml"))), "Patch_Biotech_ProtossCarrier.xml must be removed");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Defs", "RecipeDefs", "Recipes_PanzerIV.xml"))), "Recipes_PanzerIV.xml must be removed");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Patches", "Patch_Biotech_PanzerIV.xml"))), "Patch_Biotech_PanzerIV.xml must be removed");

            foreach (var (raceFile, defName) in new[] { ("Races_ProtossCarrier.xml", "GCF_ProtossCarrier"), ("Races_PanzerIV.xml", "GCF_PanzerIV") })
            {
                XDocument doc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", raceFile));
                XElement td = doc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == defName);
                XElement pk = doc.Root.Elements("PawnKindDef").First(e => e.Element("defName")?.Value == defName);
                Assert(td.Element("tradeability")?.Value == "None", $"{defName} must set <tradeability>None</tradeability>");
                Assert(td.Element("race")?.Element("wildBiomes") == null, $"{defName} must have no wildBiomes");
                AssertNear(ParseFloat(pk.Element("ecoSystemWeight")?.Value, -1f), 0f, 1e-4f, $"{defName} ecoSystemWeight must be 0");
                Assert(pk.Element("canArriveManhunter")?.Value == "false", $"{defName} canArriveManhunter must be false");
            }
            Console.WriteLine("       -> Verified GCF_Behemoth 100% purged & ProtossCarrier / PanzerIV strictly locked to DevMode-only");
        }

        private static void TestGiantProgressionQuestsRitualsAndBandwidth()
        {
            Assert(GameComponent_MechColossusProgression.ColossusFullMechanitorApparelBandwidth == 39,
                $"ColossusFullMechanitorApparelBandwidth must equal 39 (6+12+12+9), got {GameComponent_MechColossusProgression.ColossusFullMechanitorApparelBandwidth}");
            Assert(GameComponent_RathalosProgression.RathalosQuestTriggerTicks == 420_000, "Rathalos Day-7 delay must be 420,000 ticks");
            Assert(GameComponent_MechColossusProgression.ColossusYearOneAssaultTicks == 3_600_000, "Colossus Year-1 assault delay must be 3,600,000 ticks");

            XDocument colDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_MechColossus.xml"));
            XElement colTd = colDoc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_MechColossus");
            AssertNear(ParseFloat(colTd.Element("statBases")?.Element("BandwidthCost")?.Value, 0f), 39f, 1e-3f, "GCF_MechColossus BandwidthCost must equal 39");
            XElement colCockpit = colTd.Element("comps")!.Elements("li")
                .First(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_GiantCockpit");
            Assert(ParseBool(colCockpit.Element("requireOverseerWhenBiotechActive")?.Value, false), "GCF_MechColossus cockpit must enforce requireOverseerWhenBiotechActive=true");
            Assert(colTd.Element("comps")!.Elements("li").Any(e => (e.Attribute("Class")?.Value ?? "").EndsWith("CompProperties_DormantColossusVault", StringComparison.Ordinal)), "Missing CompProperties_DormantColossusVault");
            Assert(colTd.Element("butcherProducts")?.Element("GCF_ColossusCore")?.Value == "1", "Shredding GCF_MechColossus must yield 1x GCF_ColossusCore");

            XDocument colRecipeDoc = XDocument.Load(ResolveMod17Path("Biotech", "Defs", "RecipeDefs", "Recipes_MechColossus.xml"));
            XElement colRecipe = colRecipeDoc.Root!.Element("RecipeDef")!;
            Assert(colRecipe.Element("defName")?.Value == "GCF_Gestate_MechColossus" && colRecipe.Element("researchPrerequisite")?.Value == "UltraMechtech",
                "Recipes_MechColossus.xml must define GCF_Gestate_MechColossus requiring UltraMechtech");
            Assert(colRecipe.Descendants("thingDefs").Any(td => td.Element("li")?.Value == "GCF_ColossusCore"), "GCF_Gestate_MechColossus must require GCF_ColossusCore");
            Assert(File.Exists(ResolveMod17Path("Biotech", "Patches", "Patch_Biotech_MechColossus.xml")), "Missing Patch_Biotech_MechColossus.xml");

            XDocument rathDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_Rathalos.xml"));
            XElement rathTd = rathDoc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_Rathalos");
            XElement rathPk = rathDoc.Root.Elements("PawnKindDef").First(e => e.Element("defName")?.Value == "GCF_Rathalos");
            AssertNear(ParseFloat(rathPk.Element("ecoSystemWeight")?.Value, -1f), 0f, 1e-4f, "Rathalos ecoSystemWeight must be 0");
            Assert(rathPk.Element("canArriveManhunter")?.Value == "false", "Rathalos canArriveManhunter must be false");
            Assert(rathTd.Element("comps")!.Elements("li").Any(e => (e.Attribute("Class")?.Value ?? "").EndsWith("CompProperties_RathalosHuntTarget", StringComparison.Ordinal)), "Missing CompProperties_RathalosHuntTarget");
            Assert(rathTd.Element("butcherProducts")?.Element("GCF_RathalosScale")?.Value == "4" && rathTd.Element("butcherProducts")?.Element("GCF_RathalosWebbing")?.Value == "2",
                "Rathalos butcherProducts must yield 4x GCF_RathalosScale and 2x GCF_RathalosWebbing");

            var trophyEls = EnumerateAllMod17Files(Path.Combine("Defs", "ThingDefs_Items"), "*.xml")
                .SelectMany(f => XDocument.Load(f).Root!.Elements("ThingDef"))
                .ToList();
            var trophyNames = trophyEls.Select(e => e.Element("defName")?.Value).ToHashSet();
            Assert(trophyNames.Contains("GCF_RathalosScale") && trophyNames.Contains("GCF_RathalosWebbing")
                && trophyNames.Contains("GCF_RathalosPlate") && trophyNames.Contains("GCF_RathalosIntel")
                && !trophyNames.Contains("GCF_RathalosRuby")
                && trophyNames.Contains("GCF_ColossusCore"),
                "Missing expected Rathalos/Colossus item ThingDefs or legacy GCF_RathalosRuby not removed");
            foreach (string rathTex in new[] { "GCF_RathalosScale.png", "GCF_RathalosWebbing.png", "GCF_RathalosPlate.png", "GCF_RathalosIntel.png" })
            {
                Assert(!string.IsNullOrEmpty(ResolveMod17Path("Textures", "Things", "Item", "Special", rathTex)),
                    $"Missing Rathalos item icon texture {rathTex}");
            }
            XElement intelTd = trophyEls.First(e => e.Element("defName")?.Value == "GCF_RathalosIntel");
            Assert(intelTd.Element("comps")!.Elements("li").Any(e => e.Attribute("Class")?.Value == "CompProperties_Usable") &&
                   intelTd.Element("comps")!.Elements("li").Any(e => (e.Attribute("Class")?.Value ?? "").EndsWith("CompProperties_UseEffectReadRathalosIntel", StringComparison.Ordinal)),
                "GCF_RathalosIntel must have CompProperties_Usable + CompProperties_UseEffectReadRathalosIntel");

            XDocument rathRecipeDoc = XDocument.Load(ResolveMod17Path("Defs", "RecipeDefs", "Recipes_Rathalos.xml"));
            XElement intelRecipe = rathRecipeDoc.Root!.Elements("RecipeDef").First(e => e.Element("defName")?.Value == "GCF_Make_RathalosIntel");
            Assert(intelRecipe.Element("products")?.Element("GCF_RathalosIntel")?.Value == "1" &&
                   intelRecipe.Element("recipeUsers")!.Elements("li").Count() >= 4,
                "GCF_Make_RathalosIntel must produce 1x GCF_RathalosIntel at colony workbenches");

            XDocument rathWeaponDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Misc", "Weapons_Rathalos.xml"));
            XElement swordTd = rathWeaponDoc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_DragonscaleSword");
            Assert(!string.IsNullOrEmpty(ResolveMod17Path("Textures", "Things", "Item", "Equipment", "WeaponMelee", "GCF_DragonscaleSword.png")),
                "Missing GCF_DragonscaleSword.png weapon texture");
            XElement swordCost = swordTd.Element("costList")!;
            Assert(swordCost.Element("GCF_RathalosScale")?.Value == "2" &&
                   swordCost.Element("GCF_RathalosWebbing")?.Value == "2" &&
                   swordCost.Element("GCF_RathalosPlate")?.Value == "1",
                "GCF_DragonscaleSword must cost 2x Scale, 2x Webbing, and 1x Plate");
            Assert(swordTd.Element("statBases")?.Element("MaxHitPoints")?.Value == "120" &&
                   swordTd.Element("statBases")?.Element("MarketValue")?.Value == "2400" &&
                   swordTd.Element("tradeability")?.Value == "None" &&
                   swordTd.Element("genericMarketSellable")?.Value == "false",
                "GCF_DragonscaleSword must have 1.2x Monosword statBases and full trade/loot isolation");
            var swordTools = swordTd.Element("tools")!.Elements("li").ToList();
            Assert(swordTools.Count == 3 &&
                   swordTools[0].Element("power")?.Value == "14.4" &&
                   swordTools[1].Element("power")?.Value == "30" && swordTools[1].Element("armorPenetration")?.Value == "1.08" &&
                   swordTools[2].Element("power")?.Value == "30" && swordTools[2].Element("armorPenetration")?.Value == "1.08",
                "GCF_DragonscaleSword tools must equal 1.2x Monosword power and armorPenetration");

            var allQuestEls = EnumerateAllMod17Files(Path.Combine("Defs", "QuestScriptDefs"), "*.xml")
                .SelectMany(f => XDocument.Load(f).Root!.Elements("QuestScriptDef"))
                .ToList();
            XElement rathQuest = allQuestEls.First(e => e.Element("defName")?.Value == "GCF_Quest_RathalosHunt");
            XElement forestQuest = allQuestEls.First(e => e.Element("defName")?.Value == "GCF_Quest_AncientForest");
            XElement vaultQuest = allQuestEls.First(e => e.Element("defName")?.Value == "GCF_Quest_ColossusRelicVault");
            Assert((rathQuest.Element("root")?.Attribute("Class")?.Value ?? "").EndsWith("QuestNode_Root_RathalosHunt", StringComparison.Ordinal) &&
                   rathQuest.Element("autoAccept")?.Value == "false" &&
                   rathQuest.Element("expireDaysRange")?.Value == "10" &&
                   GameComponent_RathalosProgression.RathalosQuestDurationTicks == 600000 &&
                   GameComponent_RathalosProgression.RathalosQuestRepeatIntervalTicks == 600000 &&
                   (rathQuest.Descendants("li").FirstOrDefault()?.Value ?? "").Contains("King of the Skies", StringComparison.Ordinal),
                "GCF_Quest_RathalosHunt must be named King of the Skies (autoAccept=false, expireDaysRange=10, 10-day repeat) using QuestNode_Root_RathalosHunt");
            var testRathProg = new GameComponent_RathalosProgression(null!);
            Assert(!testRathProg.RathalosPermanentlyDismissed, "Fresh GameComponent_RathalosProgression must not be dismissed");
            testRathProg.Notify_RathalosHuntCompleted(420000);
            Assert(testRathProg.NextRathalosRepeatTick == 1020000, "Completion must schedule +600000 repeat tick");
            testRathProg.Notify_RathalosQuestManuallyDismissed();
            testRathProg.Notify_RathalosHuntCompleted(1100000);
            Assert(testRathProg.RathalosPermanentlyDismissed && testRathProg.NextRathalosRepeatTick == -1,
                "Manual dismiss once must permanently latch RathalosPermanentlyDismissed and block any future repeat scheduling");
            string oldProofPath = Path.Combine(ModsParentDir, "[GCF]Rathalos", "1.7", "Sounds", "Songs", "GCF_ProofOfAHero.wav");
            string rathAudioPath = Path.Combine(ModsParentDir, "[GCF]Rathalos", "1.7", "Sounds", "Songs", "GCF_RathalosRoar.mp3");
            Assert(!File.Exists(oldProofPath) && File.Exists(rathAudioPath) && new FileInfo(rathAudioPath).Length > 1_000_000,
                "Proof of a Hero must be removed and replaced with GCF_RathalosRoar.mp3 for King of the Skies BGM");
            XDocument rathMusicDoc = XDocument.Load(Path.Combine(ModsParentDir, "[GCF]Rathalos", "1.7", "Defs", "MusicDefs", "Music_Rathalos.xml"));
            XElement songEl = rathMusicDoc.Root!.Elements("SongDef").First(e => e.Element("defName")?.Value == "GCF_Song_RathalosRoar");
            XElement seqEl = rathMusicDoc.Root!.Elements("MusicSequenceDef").First(e => e.Element("defName")?.Value == "GCF_Sequence_RathalosHunt");
            XElement transEl = rathMusicDoc.Root!.Elements("MusicTransitionDef").First(e => e.Element("defName")?.Value == "GCF_Transition_RathalosHunt");
            Assert(songEl.Element("clipPath")?.Value == "Songs/GCF_RathalosRoar" &&
                   songEl.Element("playOnMap")?.Value == "false" &&
                   songEl.Element("commonality")?.Value == "0",
                "GCF_Song_RathalosRoar must point to Songs/GCF_RathalosRoar and be excluded from random map playback");
            Assert(seqEl.Element("song")?.Value == "GCF_Song_RathalosRoar" &&
                   seqEl.Element("loop")?.Value == "true" &&
                   seqEl.Element("fadeoutLastSongDuration")?.Value == "0" &&
                   transEl.Element("workerType")?.Value == typeof(MusicTransition_RathalosHunt).FullName &&
                   transEl.Element("sequence")?.Value == "GCF_Sequence_RathalosHunt",
                "GCF_Transition_RathalosHunt & GCF_Sequence_RathalosHunt must wire MusicTransition_RathalosHunt to loop GCF_Song_RathalosRoar immediately");
            XDocument rathSongCn = XDocument.Load(Path.Combine(ModsParentDir, "[GCF]Rathalos", "1.7", "Languages", "ChineseSimplified", "DefInjected", "SongDef", "Music_Rathalos.xml"));
            Assert(rathSongCn.Root!.Element("GCF_Song_RathalosRoar.label")?.Value == "咆哮 / 雄火龙",
                "ChineseSimplified SongDef translation must label GCF_Song_RathalosRoar as '咆哮 / 雄火龙'");
            Assert((forestQuest.Element("root")?.Attribute("Class")?.Value ?? "").EndsWith("QuestNode_Root_AncientForest", StringComparison.Ordinal) &&
                   forestQuest.Element("autoAccept")?.Value == "true",
                "GCF_Quest_AncientForest must autoAccept=true and use QuestNode_Root_AncientForest");
            XDocument rathQuestCn = XDocument.Load(Path.Combine(ModsParentDir, "[GCF]Rathalos", "1.7", "Languages", "ChineseSimplified", "DefInjected", "QuestScriptDef", "Quests_Rathalos.xml"));
            var rathQuestCnLines = rathQuestCn.Descendants("li").Select(e => e.Value).ToList();
            Assert(rathQuestCnLines.Any(s => s.Contains("questName->空之王者", StringComparison.Ordinal)) &&
                   rathQuestCnLines.Any(s => s.Contains("questName->古代树森林", StringComparison.Ordinal)),
                "ChineseSimplified Quests_Rathalos.xml must name Day-7 quest '空之王者' and intel POI quest '古代树森林'");
            XDocument forestSiteDoc = XDocument.Load(ResolveMod17Path("Defs", "SitePartDefs", "SiteParts_Rathalos.xml"));
            XElement forestSiteEl = forestSiteDoc.Root!.Elements("SitePartDef").First(e => e.Element("defName")?.Value == "GCF_SitePart_AncientForest");
            Assert(forestSiteEl.Element("disallowsAutomaticDetectionTimerStart")?.Value == "true" &&
                   forestSiteEl.Element("considerEnteringAsAttack")?.Value == "false" &&
                   forestSiteEl.Element("wantsThreatPoints")?.Value == "false",
                "GCF_SitePart_AncientForest must be a peaceful, non-raid-timed tamable POI");
            Assert((vaultQuest.Element("root")?.Attribute("Class")?.Value ?? "").EndsWith("QuestNode_Root_ColossusRelicVault", StringComparison.Ordinal) && vaultQuest.Element("defaultChallengeRating")?.Value == "3",
                "GCF_Quest_ColossusRelicVault must have challengeRating=3");

            XDocument mechPatchDoc = XDocument.Load(ResolveMod17Path("Patches", "Patch_MechanoidFaction_MechScorpion.xml"));
            string mechPatchStr = mechPatchDoc.ToString();
            Assert(mechPatchStr.Contains("FactionDef[defName=\"Mechanoid\"]/pawnGroupMakers") && mechPatchStr.Contains("<GCF_MechScorpion>"),
                "Patch_MechanoidFaction_MechScorpion.xml must inject GCF_MechScorpion into Mechanoid combat groups");

            int progPatchCount = 0;
            foreach (Type patchContainer in new[]
            {
                typeof(HarmonyPatches_GiantProgression),
                typeof(HarmonyPatches_RathalosProgression),
                typeof(HarmonyPatches_ValstraxProgression),
                typeof(HarmonyPatches_MechColossusProgression)
            })
            {
                foreach (MethodInfo pm in patchContainer.GetMethods(BindingFlags.Public | BindingFlags.Static))
                {
                    var attrs = pm.GetCustomAttributes<HarmonyPatch>(inherit: false).ToArray();
                    if (attrs.Length == 0) continue;
                    Type declType = null; string methodName = null; Type[] argTypes = null; MethodType mType = MethodType.Normal;
                    foreach (HarmonyPatch hp in attrs)
                    {
                        if (hp.info.declaringType != null) declType = hp.info.declaringType;
                        if (!string.IsNullOrEmpty(hp.info.methodName)) methodName = hp.info.methodName;
                        if (hp.info.argumentTypes != null) argTypes = hp.info.argumentTypes;
                        if (hp.info.methodType.HasValue) mType = hp.info.methodType.Value;
                    }
                    MethodBase resolved = mType == MethodType.Getter
                        ? AccessTools.PropertyGetter(declType, methodName)
                        : (argTypes != null ? AccessTools.Method(declType, methodName, argTypes) : AccessTools.Method(declType, methodName));
                    Assert(resolved != null, $"Failed to resolve {patchContainer.Name} target {declType?.FullName}.{methodName} ({mType}) for {pm.Name}");
                    progPatchCount++;
                }
            }
            Assert(progPatchCount >= 5, $"Expected >= 5 progression Harmony patches across framework + sub-mods, got {progPatchCount}");
            Assert(typeof(RimWorld.FloatMenuOptionProvider).IsAssignableFrom(typeof(FloatMenuOptionProvider_ActivateColossusVault)) &&
                   !typeof(FloatMenuOptionProvider_ActivateColossusVault).IsAbstract,
                "FloatMenuOptionProvider_ActivateColossusVault must be concrete");

            // Verify Rathalos part-break nodeId classifier matches actual GiantRigDefs_Rathalos.xml nodeIds
            XDocument rathRigDoc = XDocument.Load(ResolveMod17Path("Defs", "GiantRigDefs", "GiantRigDefs_Rathalos.xml"));
            var rathNodeIds = rathRigDoc.Descendants("nodeId").Select(e => e.Value).ToHashSet(StringComparer.Ordinal);
            foreach (string expectedLeftWing in new[] { "wing_shoulder_left", "wing_humerus_left", "wing_forearm_left", "wing_inner_fan_left", "wing_outer_fan_left" })
            {
                Assert(rathNodeIds.Contains(expectedLeftWing), $"Rathalos rig missing expected left-wing nodeId '{expectedLeftWing}'");
                Assert(RathalosProgressionUtility.ClassifyRathalosPartBreakSlot(expectedLeftWing) == "wing_l",
                    $"ClassifyRathalosPartBreakSlot('{expectedLeftWing}') must return 'wing_l'");
            }
            foreach (string expectedRightWing in new[] { "wing_shoulder_right", "wing_humerus_right", "wing_forearm_right", "wing_inner_fan_right", "wing_outer_fan_right" })
            {
                Assert(rathNodeIds.Contains(expectedRightWing), $"Rathalos rig missing expected right-wing nodeId '{expectedRightWing}'");
                Assert(RathalosProgressionUtility.ClassifyRathalosPartBreakSlot(expectedRightWing) == "wing_r",
                    $"ClassifyRathalosPartBreakSlot('{expectedRightWing}') must return 'wing_r'");
            }
            foreach (string expectedTail in new[] { "tail_club_base", "tail_club_head", "tail_tip_spike", "tail_seg3", "tail_seg4", "tail_seg5", "tail_seg6" })
            {
                Assert(rathNodeIds.Contains(expectedTail), $"Rathalos rig missing expected tail nodeId '{expectedTail}'");
                Assert(RathalosProgressionUtility.ClassifyRathalosPartBreakSlot(expectedTail) == "tail",
                    $"ClassifyRathalosPartBreakSlot('{expectedTail}') must return 'tail'");
            }
            Assert(RathalosProgressionUtility.IsWingPartBreakSlot("wing_l") && RathalosProgressionUtility.IsWingPartBreakSlot("wing_r"),
                "Wing slots must route to Rathalos Webbing drop");
            foreach (string nonWingNode in new[] { "tail_club_head", "thigh_left", "thigh_right", "horn_left", "horn_right", "skull" })
            {
                string nonWingSlot = RathalosProgressionUtility.ClassifyRathalosPartBreakSlot(nonWingNode);
                Assert(!string.IsNullOrEmpty(nonWingSlot) && !RathalosProgressionUtility.IsWingPartBreakSlot(nonWingSlot),
                    $"Non-wing bone '{nonWingNode}' must route to Rathalos Scale drop, got slot='{nonWingSlot}'");
            }
            Assert(RathalosProgressionUtility.ClassifyRathalosPartBreakSlot("thorax_core") == null,
                "Core thorax_core must not trigger non-lethal part-break drop");

            var raidComp = new CompRathalosHuntTarget();
            raidComp.BindQuestSignal("Quest1.Done", "Quest1.Fail", forbidTamingOnThisPawn: true);
            Assert(raidComp.ForbidTaming, "Day-7 manhunter raid Rathalos must forbid taming");
            var forestComp = new CompRathalosHuntTarget();
            forestComp.BindQuestSignal("Quest2.Done", null, forbidTamingOnThisPawn: false);
            Assert(!forestComp.ForbidTaming, "Ancient Forest Rathalos must allow taming");

            // Verify guaranteed boss trophy recovery when heavily damaged corpse efficiency rounds butcherProducts to 0
            var dummyCoreDef = new ThingDef { defName = "GCF_ColossusCore" };
            var dummyPlateDef = new ThingDef { defName = "GCF_RathalosPlate" };
            var emptyColossusDrops = new List<Thing>();
            GiantProgressionUtility.EnsureGuaranteedButcherTrophy(
                emptyColossusDrops, dummyCoreDef,
                def => new Thing { def = def, stackCount = 1 });
            Assert(emptyColossusDrops.Count == 1 && emptyColossusDrops[0].def == dummyCoreDef && emptyColossusDrops[0].stackCount == 1,
                "Shredding a low-efficiency GCF_MechColossus corpse must always guarantee 1x GCF_ColossusCore");
            GiantProgressionUtility.EnsureGuaranteedButcherTrophy(
                emptyColossusDrops, dummyCoreDef,
                def => new Thing { def = def, stackCount = 1 });
            Assert(emptyColossusDrops.Count == 1, "EnsureGuaranteedButcherTrophy must not duplicate an existing GCF_ColossusCore");

            var emptyRathalosDrops = new List<Thing>();
            GiantProgressionUtility.EnsureGuaranteedButcherTrophy(
                emptyRathalosDrops, dummyPlateDef,
                def => new Thing { def = def, stackCount = 1 });
            Assert(emptyRathalosDrops.Count == 1 && emptyRathalosDrops[0].def == dummyPlateDef && emptyRathalosDrops[0].stackCount == 1,
                "Butchering a low-efficiency GCF_Rathalos corpse must always guarantee at least 1x GCF_RathalosPlate");

            // Verify strict 39-bandwidth active Mechanitor control gate (removing Mechlord gear / losing ControlledPawns immediately locks control)
            Assert(GiantPlayerControlUtility.EvaluateMechanitorActiveControl(
                    hasOverseer: true, overseerDeadOrDestroyed: false, hasMechanitorTracker: true,
                    isInControlledPawns: true, totalBandwidth: 39, requiredBandwidth: 39),
                "Full 39-BW Mechanitor with Colossus in ControlledPawns must satisfy active control gate");
            Assert(!GiantPlayerControlUtility.EvaluateMechanitorActiveControl(
                    hasOverseer: true, overseerDeadOrDestroyed: false, hasMechanitorTracker: true,
                    isInControlledPawns: true, totalBandwidth: 27, requiredBandwidth: 39),
                "Removing Mechlord Helmet (27 < 39 BW) must immediately revoke active Colossus control");
            Assert(!GiantPlayerControlUtility.EvaluateMechanitorActiveControl(
                    hasOverseer: true, overseerDeadOrDestroyed: false, hasMechanitorTracker: true,
                    isInControlledPawns: false, totalBandwidth: 39, requiredBandwidth: 39),
                "Colossus excluded from Mechanitor ControlledPawns due to bandwidth overflow must revoke active control");
            Assert(!GiantPlayerControlUtility.EvaluateMechanitorActiveControl(
                    hasOverseer: true, overseerDeadOrDestroyed: true, hasMechanitorTracker: true,
                    isInControlledPawns: true, totalBandwidth: 39, requiredBandwidth: 39),
                "Dead/destroyed Mechanitor overseer must revoke active Colossus control");

            // Verify 4-language Keyed completeness for Rathalos & flight failure strings across framework + sub-mods
            foreach (string lang in new[] { "ChineseSimplified", "English", "Japanese", "Russian" })
            {
                var keyedNames = LoadMergedKeyedMap(lang).Keys.ToHashSet(StringComparer.Ordinal);
                foreach (string reqKey in new[]
                {
                    "GCF_ApexRoarFail_MustBeGrounded",
                    "GCF_FireballLiftoffFail_AlreadyAirborne",
                    "GCF_FlightFail_InsufficientLift",
                    "GCF_TalonStrikeFail_MustBeAirborne"
                })
                {
                    Assert(keyedNames.Contains(reqKey), $"Missing Keyed string '{reqKey}' in {lang}");
                }
            }

            // Verify Ancient Ruins terrain & inside-ruins placement invariants for GCF_SitePart_ColossusVault
            XDocument sitePartsDoc = XDocument.Load(ResolveMod17Path("Defs", "SitePartDefs", "SiteParts_MechColossus.xml"));
            XElement vaultSitePart = sitePartsDoc.Root!.Elements("SitePartDef").First(e => e.Element("defName")?.Value == "GCF_SitePart_ColossusVault");
            Assert(vaultSitePart.Element("minMapSize")?.Value == "(250, 1, 250)", "GCF_SitePart_ColossusVault must enforce minMapSize=(250, 1, 250) for sprawling Ancient Ruins");
            Assert(vaultSitePart.Element("gravShipsCanLandOn")?.Value == "true", "GCF_SitePart_ColossusVault must set gravShipsCanLandOn=true");

            GiantProgressionUtility.ResolveAncientRuinsDefsForBiome("TemperateForest", out string tempLm, out string tempMut);
            Assert(tempLm == "Ruins" && tempMut == "AncientRuins", $"Temperate biome must map to Ruins/AncientRuins, got {tempLm}/{tempMut}");
            GiantProgressionUtility.ResolveAncientRuinsDefsForBiome("IceSheet", out string iceLm, out string iceMut);
            Assert(iceLm == "FrozenRuins" && iceMut == "AncientRuins_Frozen", $"Glacial/IceSheet biome must map to FrozenRuins/AncientRuins_Frozen, got {iceLm}/{iceMut}");

            var sampleRuins = new List<CellRect>
            {
                new CellRect(24, 30, 32, 30),
                new CellRect(96, 92, 54, 46) // Central sprawling Odyssey AncientRuins complex
            };
            bool matchedExisting = GiantProgressionUtility.TryChooseBestRuinContainer(
                sampleRuins, new IntVec3(250, 1, 250), vaultSpan: 23,
                out CellRect chosenRuin, out IntVec3 chosenVaultCenter, out bool enclosedByRuin);
            Assert(matchedExisting && enclosedByRuin, "Must select central >=29x29 Odyssey AncientRuins complex as host");
            var embeddedVaultRect = new CellRect(chosenVaultCenter.x - 11, chosenVaultCenter.z - 11, 23, 23);
            foreach (IntVec3 corner in embeddedVaultRect.Corners)
            {
                Assert(chosenRuin.ContractedBy(3).Contains(corner),
                    $"23x23 Colossus stasis vault corner {corner} must sit strictly inside surrounding AncientRuins complex {chosenRuin}");
            }

            GiantProgressionUtility.TryChooseBestRuinContainer(
                Array.Empty<CellRect>(), new IntVec3(250, 1, 250), vaultSpan: 23,
                out CellRect fallbackRuin, out IntVec3 fallbackCenter, out bool fallbackEnclosed);
            Assert(!fallbackEnclosed && fallbackRuin.Width == 45 && fallbackRuin.Height == 45 && fallbackRuin.Contains(new CellRect(fallbackCenter.x - 11, fallbackCenter.z - 11, 23, 23).Max),
                "When no pre-existing >=29x29 ruin is present, GenStep_ColossusVault must construct a 45x45 enclosing Ancient Ruin complex around the 23x23 vault");

            Console.WriteLine($"       -> Verified 39-BW Colossus active gate + guaranteed Ruins terrain & inside-ruins vault, Day-7 Rathalos breaks, MechScorpion gate, Abyssal ritual & {progPatchCount} progression Harmony patches");
        }

        private static void TestRushDestructionAndDirectionalCombat()
        {
            // 1. Distant-enemy rush hysteresis: close enemies keep Walk, distant enemies engage Run with smooth stop threshold
            Assert(!CompGiantRig.EvaluateRushHysteresis(false, 5.0f, true, 12f, 7f),
                "Close enemy (< 12) must remain in Walk rather than rushing");
            Assert(CompGiantRig.EvaluateRushHysteresis(false, 12.0f, true, 12f, 7f),
                "Distant enemy (>= 12) must trigger Rush");
            Assert(CompGiantRig.EvaluateRushHysteresis(true, 9.0f, true, 12f, 7f),
                "Hysteresis band (7..12) must maintain Rush while closing in");
            Assert(CompGiantRig.EvaluateRushHysteresis(true, 7.0f, true, 12f, 7f),
                "At exact stop distance 7.0 must remain in Rush before dropping below");
            Assert(!CompGiantRig.EvaluateRushHysteresis(true, 6.9f, true, 12f, 7f),
                "Dropping below stop distance (6.9 < 7) must exit Rush back to Walk");
            Assert(!CompGiantRig.EvaluateRushHysteresis(true, 30.0f, false, 12f, 7f),
                "Disabling rush must stop rushing at any distance");

            // 2. Destructible terrain vs Thick Roof (Overhead Mountain) exclusion vs Deep Water
            var removableWallTerrain = new TerrainDef
            {
                defName = "Test_RemovableBarrierTerrain",
                layerable = true,
                passability = Traversability.Impassable
            };
            var walkableUnder = new TerrainDef
            {
                defName = "Test_WalkableUnderTerrain",
                passability = Traversability.Standable
            };
            var deepWaterTerrain = new TerrainDef
            {
                defName = "Test_DeepWaterTerrain",
                layerable = false,
                passability = Traversability.Impassable,
                tags = new List<string> { "Water" }
            };
            var taggedDestructibleTerrain = new TerrainDef
            {
                defName = "Test_TaggedDestructibleTerrain",
                layerable = false,
                passability = Traversability.Impassable,
                tags = new List<string> { "GCF_DestructibleTerrain" }
            };

            Assert(GiantDestructionUtility.IsTerrainCellDestructible(
                    isThickRoof: false, top: removableWallTerrain, temp: null, under: walkableUnder, foundation: null, allowDestructibleTerrain: true),
                "Non-thick-roof removable impassable terrain over walkable ground must be destructible & passable");
            Assert(!GiantDestructionUtility.IsTerrainCellDestructible(
                    isThickRoof: true, top: removableWallTerrain, temp: null, under: walkableUnder, foundation: null, allowDestructibleTerrain: true),
                "Thick-roof (Overhead Mountain) cells MUST NEVER be destructible even if terrain is removable");
            Assert(!GiantDestructionUtility.IsTerrainCellDestructible(
                    isThickRoof: false, top: deepWaterTerrain, temp: null, under: null, foundation: null, allowDestructibleTerrain: true),
                "Unremovable deep water must remain non-destructible and impassable");
            Assert(GiantDestructionUtility.IsTerrainCellDestructible(
                    isThickRoof: false, top: taggedDestructibleTerrain, temp: null, under: null, foundation: null, allowDestructibleTerrain: true),
                "Non-thick-roof GCF_DestructibleTerrain must be destructible");
            Assert(!GiantDestructionUtility.IsTerrainCellDestructible(
                    isThickRoof: true, top: taggedDestructibleTerrain, temp: null, under: null, foundation: null, allowDestructibleTerrain: true),
                "Thick-roof GCF_DestructibleTerrain must be excluded");

            // Path cost verifier
            int thickRoofCost = GiantDestructionUtility.ComputeBreachDirectCost(
                hasThickRoof: true, hasIndestructibleBlocker: false, hasProtectedAlliedObstacle: false, hasCrushableObstacle: true, vanillaDirectCost: 10000);
            Assert(thickRoofCost == GiantDestructionUtility.ImpassablePathCost,
                $"Thick-roof cell must remain impassable ({GiantDestructionUtility.ImpassablePathCost}), got {thickRoofCost}");

            int alliedCost = GiantDestructionUtility.ComputeBreachDirectCost(
                hasThickRoof: false, hasIndestructibleBlocker: false, hasProtectedAlliedObstacle: true, hasCrushableObstacle: true, vanillaDirectCost: 10000);
            Assert(alliedCost == GiantDestructionUtility.ImpassablePathCost,
                $"Protected allied building must stay impassable (10000), got {alliedCost}");

            int crushCost = GiantDestructionUtility.ComputeBreachDirectCost(
                hasThickRoof: false, hasIndestructibleBlocker: false, hasProtectedAlliedObstacle: false, hasCrushableObstacle: true, vanillaDirectCost: 10000);
            Assert(crushCost > 0 && crushCost < GiantDestructionUtility.ImpassablePathCost,
                $"Crushable non-thick-roof obstacle must become passable (< 10000), got {crushCost}");

            // Def-driven crushing flag check on GiantRigDef
            var testRig = new GiantRigDef { crushBuildingsAndTerrain = false };
            Assert(!GiantDestructionUtility.CanGiantCrushAnything(testRig, out _, out _, out _),
                "GiantRigDef.crushBuildingsAndTerrain=false must disable crushing");
            testRig.crushBuildingsAndTerrain = true;
            Assert(GiantDestructionUtility.CanGiantCrushAnything(testRig, out bool b, out bool r, out bool t) && b && r && t,
                "Default GiantRigDef crushing flags must enable buildings, natural rock, and terrain crushing");
            testRig.canCrushNaturalRock = false;
            Assert(GiantDestructionUtility.CanGiantCrushAnything(testRig, out b, out r, out t) && b && !r && t,
                "Per-Def canCrushNaturalRock=false must disable only natural rock crushing");

            // 3. Directional melee tool weighting across front/port/starboard/astern bearings
            float mawFront = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal dragon maw", 0f);
            float mawBack = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal dragon maw", 180f);
            Assert(mawFront > mawBack && mawFront > 1.2f && mawBack < 0.8f,
                $"Front maw weight must prefer 0 deg ({mawFront:F2}) over rear 180 deg ({mawBack:F2})");

            float leftOnPort = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("left boneless spine whip", -90f);
            float leftOnStarboard = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("left boneless spine whip", 90f);
            Assert(leftOnPort > leftOnStarboard && leftOnPort > 1.2f && leftOnStarboard < 0.8f,
                $"Left whip weight must prefer port -90 deg ({leftOnPort:F2}) over starboard +90 deg ({leftOnStarboard:F2})");

            float rightOnStarboard = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("right boneless spine whip", 90f);
            float rightOnPort = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("right boneless spine whip", -90f);
            Assert(rightOnStarboard > rightOnPort && rightOnStarboard > 1.2f && rightOnPort < 0.8f,
                $"Right whip weight must prefer starboard +90 deg ({rightOnStarboard:F2}) over port -90 deg ({rightOnPort:F2})");

            float tailRear = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal crucible tail halberd", 180f);
            float tailFront = HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal crucible tail halberd", 0f);
            Assert(tailRear > tailFront && tailRear > 1.2f && tailFront < 0.8f,
                $"Tail halberd weight must prefer astern 180 deg ({tailRear:F2}) over dead ahead 0 deg ({tailFront:F2})");
        }

        private static void TestMultiPartSteeringAndNeckArticulation()
        {
            var (rathRig, _, rathAnims) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (scorpRig, _, _) = LoadMechScorpionFromXml();

            foreach (GiantRigDef r in new[] { rathRig, scorpRig })
            {
                var errs = r.ConfigErrors().ToList();
                Assert(errs.Count == 0, $"Rig {r.defName} produced ConfigErrors: {string.Join("; ", errs)}");
                Assert(r.steering != null && r.steering.enabled, $"Rig {r.defName} must configure enabled <steering>");
            }

            Assert(rathRig.TryGetNodeIndex("thorax_core", out int thoraxIdx), "Missing thorax_core");
            Assert(rathRig.TryGetNodeIndex("pelvis", out int pelvisIdx), "Missing pelvis");
            Assert(rathRig.TryGetNodeIndex("neck_base", out int neck1Idx), "Missing neck_base");
            Assert(rathRig.TryGetNodeIndex("neck_mid", out int neck2Idx), "Missing neck_mid");
            Assert(rathRig.TryGetNodeIndex("skull", out int skullIdx), "Missing skull");

            int vn = rathRig.SortedNodes.Length;
            var evalLocal = new BoneLocalPose[vn];
            var evalWorld = new BoneWorldPose[vn];
            var evalMiss = new bool[vn];
            Vector2 rootXZ = new Vector2(60.5f, 60.5f);

            // Steady idle gaze, flank target aim & AttackOnce continuity
            var rSteer = new GiantSteeringRuntime(rathRig);
            rSteer.Reset(0f);
            for (int t = 0; t < 40; t++)
            {
                Array.Fill(evalLocal, BoneLocalPose.Identity);
                var flankCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 45f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = true,
                    AnimState = GiantAnimState.Idle,
                    ContinuousTicks = t,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = true
                };
                rSteer.ApplyBoneSteering(rathRig, 0f, evalLocal, evalMiss, 1f, in flankCtx);
            }
            float leadIdle = rSteer.PrimaryLookLeadDeg;
            Assert(evalLocal[neck1Idx].angle > 4f && evalLocal[neck2Idx].angle > 6f && evalLocal[skullIdx].angle > 8f,
                "Flank target aim must distribute across Rathalos neck chain");
            Assert(leadIdle >= 36f && leadIdle <= 46f, $"Flank 45 deg aim must settle without overshoot, got lead={leadIdle:F2}");

            // Sharp turn zero-socket-drift & progressive cascade
            rSteer.Reset(0f);
            var bezierRts = rathRig.bezierChains.Select(bc => new DampedBezierChainRuntime(bc)).ToArray();
            BoneWorldPose[] initialWorld = new BoneWorldPose[vn];
            Array.Fill(evalLocal, BoneLocalPose.Identity);
            SkeletalKinematics.SolveWorldPoses(rathRig, rootXZ, 0f, evalLocal, evalMiss, initialWorld);

            float heading = 0f;
            Vector2 pos = rootXZ;
            bool observedCascade = false;
            GiantAnimDef walkClip = rathAnims["GCF_Anim_Rathalos_Walk"];
            for (int t = 0; t < 65; t++)
            {
                pos += SkeletalKinematics.RotateCW(Vector2.up, heading) * 0.06f;
                Array.Fill(evalLocal, BoneLocalPose.Identity);
                walkClip.EvaluateInto(rathRig, t % walkClip.durationTicks, evalLocal);
                var steerCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 90f,
                    DesiredLookHeadingDeg = 90f,
                    HasExplicitLookTarget = true,
                    IsMoving = true,
                    MovedDistanceCells = 0.06f,
                    AnimState = GiantAnimState.Walk,
                    ContinuousTicks = t,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = false
                };
                heading = rSteer.StepBodyHeading(heading, rathRig.turnSpeedDegPerTick, 1f, in steerCtx);
                rSteer.ApplyBoneSteering(rathRig, heading, evalLocal, evalMiss, 1f, in steerCtx);
                for (int i = 0; i < vn; i++) evalLocal[i].sagittalPitch = 0f;
                var bCtx = new BezierChainStepContext { BodyWorldAngleDeg = heading };
                for (int c = 0; c < bezierRts.Length; c++) bezierRts[c].Step(rathRig, pos, heading, evalLocal, evalMiss, 1f, in bCtx);
                SkeletalKinematics.SolveWorldPoses(rathRig, pos, heading, evalLocal, evalMiss, evalWorld);

                for (int i = 0; i < vn; i++)
                {
                    BoneNodeDef node = rathRig.SortedNodes[i];
                    int pIdx = node.parentRuntimeIndex;
                    if (pIdx < 0) continue;
                    Vector2 expectedSocket = evalWorld[pIdx].UVToWorldXZ(node.resolvedParentSocketUV.x, node.resolvedParentSocketUV.y);
                    float err = Vector2.Distance(evalWorld[i].jointWorldXZ, expectedSocket);
                    Assert(err < 1e-4f, $"Socket drift on {node.nodeId} at steer tick {t}: err={err:E3}");
                }
                if (t >= 4 && t <= 16)
                {
                    float dPelvis = Mathf.DeltaAngle(initialWorld[pelvisIdx].worldAngleDeg, evalWorld[pelvisIdx].worldAngleDeg);
                    float dThorax = Mathf.DeltaAngle(initialWorld[thoraxIdx].worldAngleDeg, evalWorld[thoraxIdx].worldAngleDeg);
                    float dSk = Mathf.DeltaAngle(initialWorld[skullIdx].worldAngleDeg, evalWorld[skullIdx].worldAngleDeg);
                    if (dPelvis < dThorax && dThorax < dSk) observedCascade = true;
                }
            }
            Assert(observedCascade, "Expected progressive turn cascade: pelvis < thorax < skull");

            // MechScorpion multi-part steering cascade & SteeringEnabled=false constant rate
            var scorpSteer = new GiantSteeringRuntime(scorpRig);
            scorpSteer.Reset(0f);
            float scorpHeading = 0f;
            var scorpLocal = new BoneLocalPose[scorpRig.SortedNodes.Length];
            var scorpMiss = new bool[scorpRig.SortedNodes.Length];
            for (int t = 0; t < 10; t++)
            {
                Array.Fill(scorpLocal, BoneLocalPose.Identity);
                var sCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 90f,
                    DesiredLookHeadingDeg = 90f,
                    HasExplicitLookTarget = true,
                    IsMoving = true,
                    MovedDistanceCells = 0.06f,
                    AnimState = GiantAnimState.Walk,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f
                };
                scorpHeading = scorpSteer.StepBodyHeading(scorpHeading, scorpRig.turnSpeedDegPerTick, 1f, in sCtx);
                scorpSteer.ApplyBoneSteering(scorpRig, scorpHeading, scorpLocal, scorpMiss, 1f, in sCtx);
            }
            Assert(scorpSteer.PrimaryLookLeadDeg >= 5f && Mathf.Abs(scorpSteer.PrimarySpineBendDeg) >= 2f,
                $"Expected MechScorpion claw lead & tail bend, got lead={scorpSteer.PrimaryLookLeadDeg:F1}, bend={scorpSteer.PrimarySpineBendDeg:F1}");

            rSteer.Reset(0f);
            float rigidHeading = 0f;
            for (int t = 0; t < 5; t++)
            {
                Array.Fill(evalLocal, BoneLocalPose.Identity);
                var offCtx = new GiantSteeringContext { DesiredBodyHeadingDeg = 90f, DesiredLookHeadingDeg = 90f, HasExplicitLookTarget = true, IsMoving = true, MovedDistanceCells = 0.06f, AnimState = GiantAnimState.Walk, SteeringEnabled = false, IntensityScale = 1.0f };
                rigidHeading = rSteer.StepBodyHeading(rigidHeading, rathRig.turnSpeedDegPerTick, 1f, in offCtx);
                rSteer.ApplyBoneSteering(rathRig, rigidHeading, evalLocal, evalMiss, 1f, in offCtx);
                AssertNear(rigidHeading, (t + 1) * rathRig.turnSpeedDegPerTick, 1e-4f, "SteeringEnabled=false must turn at constant rate");
                AssertNear(rSteer.PrimaryLookLeadDeg, 0f, 1e-4f, "SteeringEnabled=false must zero look lead");
            }
        }

        private static void TestReusableCombatArenasAndSkillPackage()
        {
            Type debugType = typeof(DebugActions_GiantCreature);
            string[] requiredDebugMethods =
            {
                "ClearAllStaticDebugRefs",
                "RecallAllCarrierInterceptorsDebug",
                "SpawnGiantKindAtMouse",
                "SpawnMechScorpion",
                "LogHitCellAimingInfo",
                "DestroyBoneAtMouse",
                "StartLiveFpsTelemetryWindow",
                "StopAndLogLiveFpsTelemetryWindow"
            };
            BindingFlags flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static;
            for (int i = 0; i < requiredDebugMethods.Length; i++)
            {
                string name = requiredDebugMethods[i];
                MethodInfo mi = debugType.GetMethod(name, flags);
                Assert(mi != null, $"Missing debug helper method DebugActions_GiantCreature.{name}");
            }

            // Global invariant: zero LudeonTK.DebugActionAttribute across the entire Core assembly
            // (all debug actions live inside Dialog_GiantDebugPanel instead of RimWorld's console menu).
            BindingFlags allMethodsFlags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly;
            var lingeringDebugActions = new List<string>();
            foreach (Type t in typeof(GiantCreatureFrameworkMod).Assembly.GetTypes())
            {
                foreach (MethodInfo mi in t.GetMethods(allMethodsFlags))
                {
                    object[] attrs = mi.GetCustomAttributes(typeof(LudeonTK.DebugActionAttribute), inherit: false);
                    if (attrs != null && attrs.Length > 0)
                    {
                        lingeringDebugActions.Add($"{t.FullName}.{mi.Name}");
                    }
                }
            }
            Assert(lingeringDebugActions.Count == 0,
                $"Core assembly must contain 0 [DebugAction] methods, found {lingeringDebugActions.Count}: {string.Join(", ", lingeringDebugActions.Take(10))}");

            string skillDir = Path.Combine(ModRoot, ".agents", "skills", "giant-creature-dev");
            if (Directory.Exists(Path.Combine(ModRoot, ".agents")))
            {
                string skillMdPath = Path.Combine(skillDir, "SKILL.md");
                Assert(File.Exists(skillMdPath), $"Missing in-mod SKILL.md at {skillMdPath}");
                string skillMd = File.ReadAllText(skillMdPath);
                Assert(skillMd.StartsWith("---"), "SKILL.md must begin with YAML frontmatter ---");
                Assert(skillMd.Contains("name: giant-creature-dev"), "SKILL.md missing name: giant-creature-dev");
                Assert(skillMd.Contains("description:"), "SKILL.md missing description field");

                string spriteSkillDir = Path.Combine(ModRoot, ".agents", "skills", "rimworld-modular-sprites");
                string[] requiredSkillFiles =
                {
                    Path.Combine(skillDir, "scripts", "gcf_live_runner.py"),
                    Path.Combine(skillDir, "scripts", "audit_rig_joints.py"),
                    Path.Combine(skillDir, "references", "rig-and-joint-authoring.md"),
                    Path.Combine(skillDir, "references", "kinematics-steering-and-combat-ai.md"),
                    Path.Combine(spriteSkillDir, "SKILL.md"),
                    Path.Combine(spriteSkillDir, "PROMPT_TEMPLATES.md"),
                    Path.Combine(spriteSkillDir, "MATTING_AND_RIGGING.md"),
                    Path.Combine(spriteSkillDir, "scripts", "modular_sprite_pipeline.py")
                };
                for (int i = 0; i < requiredSkillFiles.Length; i++)
                {
                    string p = requiredSkillFiles[i];
                    Assert(File.Exists(p) && new FileInfo(p).Length > 100, $"Missing or empty skill file: {p}");
                }
            }
            else
            {
                string shippedManualsDir = ResolveMod17Path("AgentSkills", "manuals");
                Assert(Directory.Exists(shippedManualsDir) && Directory.GetFiles(shippedManualsDir, "*.md").Length >= 3,
                    $"Missing shipped AgentSkills manuals at {shippedManualsDir}");
            }
        }

        private static void TestMechColossusThreeStageRigsAnimsAndDefs()
        {
            var (rig1, masks1, anims) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (rig2, masks2, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var (rig3, masks3, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");

            Assert(rig1.SortedNodes.Length == 64, $"Stage1 expected 64 unified bones, got {rig1.SortedNodes.Length}");
            Assert(rig2.SortedNodes.Length == 64, $"Stage2 expected 64 unified bones, got {rig2.SortedNodes.Length}");
            Assert(rig3.SortedNodes.Length == 64, $"Stage3 expected 64 unified bones, got {rig3.SortedNodes.Length}");
            for (int ni = 0; ni < 64; ni++)
            {
                Assert(rig1.SortedNodes[ni].nodeId == rig2.SortedNodes[ni].nodeId && rig2.SortedNodes[ni].nodeId == rig3.SortedNodes[ni].nodeId,
                    $"Unified 64-node tree order mismatch at index {ni}: {rig1.SortedNodes[ni].nodeId} / {rig2.SortedNodes[ni].nodeId} / {rig3.SortedNodes[ni].nodeId}");
            }
            Assert(!rig1.ConfigErrors().Any() && !rig2.ConfigErrors().Any() && !rig3.ConfigErrors().Any(),
                $"MechColossus rigs must have zero ConfigErrors: {string.Join("; ", rig1.ConfigErrors().Concat(rig2.ConfigErrors()).Concat(rig3.ConfigErrors()))}");

            var rotatingCategoryA = new HashSet<string>(StringComparer.Ordinal)
            {
                "core_gimbal", "core_rotor", "sensor_turret", "sensor_turret_right",
                "turret_neck", "command_head",
                "plasma_rail_left", "plasma_rail_aft_left", "plasma_rail_right", "plasma_rail_aft_right",
                "citadel_bridge", "railgun_mount_left", "railgun_barrel_left", "railgun_mount_right", "railgun_barrel_right",
                "wing_pod_left", "railgun_outer_mount_left", "railgun_outer_barrel_left",
                "wing_pod_right", "railgun_outer_mount_right", "railgun_outer_barrel_right",
                "aft_wing_pod_left", "aft_wing_pod_right"
            };
            int catACount = 0, catBCount = 0;
            foreach (BoneNodeDef bNode in rig1.SortedNodes)
            {
                if (rotatingCategoryA.Contains(bNode.nodeId))
                {
                    catACount++;
                    Assert(string.IsNullOrEmpty(bNode.silhouetteTexPath),
                        $"Category A rotating node {bNode.nodeId} must NOT declare silhouetteTexPath");
                }
                else
                {
                    catBCount++;
                    Assert(!string.IsNullOrEmpty(bNode.silhouetteTexPath) && bNode.silhouetteLayerOffset <= -9.0f,
                        $"Category B structural plate {bNode.nodeId} must declare silhouetteTexPath and silhouetteLayerOffset <= -9.0f");
                }
            }
            Assert(catACount == 23 && catBCount == 41, $"Expected 23 Category A + 41 Category B nodes, got {catACount} + {catBCount}");
            Assert(rig1.meleeAttackAnims.Count == 0 && rig2.meleeAttackAnims.Count == 0 && rig3.meleeAttackAnims.Count == 0,
                "Pure-ranged MechColossus stages must declare zero meleeAttackAnims");
            Assert(rig1.rangedAttackAnim != null && rig2.rangedAttackAnim != null && rig3.rangedAttackAnim != null,
                "Every MechColossus stage must declare a rangedAttackAnim");
            Assert(anims.Count == 25, $"Expected 25 pure-ranged MechColossus anim clips, got {anims.Count}");

            (GiantRigDef rig, TextureAlphaMask[] masks, string prefix)[] stageSpecs =
            {
                (rig1, masks1, "GCF_Anim_MechStage1_"),
                (rig2, masks2, "GCF_Anim_MechStage2_"),
                (rig3, masks3, "GCF_Anim_MechStage3_")
            };

            foreach (var spec in stageSpecs)
            {
                for (int i = 0; i < spec.masks.Length; i++)
                {
                    Assert(spec.masks[i] != null, $"Null alpha mask on bone {spec.rig.SortedNodes[i].nodeId} in {spec.rig.defName}");
                }

                var nodeIds = new HashSet<string>(spec.rig.SortedNodes.Select(n => n.nodeId), StringComparer.Ordinal);
                foreach (var kv in anims)
                {
                    if (!kv.Key.StartsWith(spec.prefix, StringComparison.Ordinal))
                    {
                        continue;
                    }
                    GiantAnimDef clip = kv.Value;
                    Assert(clip.durationTicks > 0f, $"{kv.Key} durationTicks must be > 0");
                    foreach (BoneAnimTrack track in clip.tracks)
                    {
                        Assert(nodeIds.Contains(track.nodeId), $"Track bone {track.nodeId} in {kv.Key} missing from {spec.rig.defName}");
                        Assert(spec.rig.TryGetNodeIndex(track.nodeId, out int idx), $"Node lookup failed for {track.nodeId}");
                        bool isChild = spec.rig.SortedNodes[idx].parentRuntimeIndex >= 0;
                        foreach (BoneKeyframe kf in track.keyframes)
                        {
                            AssertNear(kf.scale.x, 1f, 0.0001f, $"{kv.Key}:{track.nodeId} scale.x must equal 1");
                            AssertNear(kf.scale.y, 1f, 0.0001f, $"{kv.Key}:{track.nodeId} scale.y must equal 1");
                            if (isChild || !kv.Key.EndsWith("_Death", StringComparison.Ordinal))
                            {
                                AssertNear(kf.offset.x, 0f, 0.0001f, $"{kv.Key}:{track.nodeId} non-death offset.x must be 0");
                                AssertNear(kf.offset.y, 0f, 0.0001f, $"{kv.Key}:{track.nodeId} non-death offset.y must be 0");
                            }
                        }
                    }
                }
            }

            // Verify rotational morph clips actually animate bones across ticks and preserve zero-pop-in continuity at SwitchRig
            string[] morphClips =
            {
                "GCF_Anim_MechStage1_MorphOut",
                "GCF_Anim_MechStage2_MorphIn",
                "GCF_Anim_MechStage2_MorphOut",
                "GCF_Anim_MechStage3_MorphIn"
            };
            for (int m = 0; m < morphClips.Length; m++)
            {
                Assert(anims.TryGetValue(morphClips[m], out GiantAnimDef morphClip), $"Missing morph clip {morphClips[m]}");
                Assert(!morphClip.loop, $"{morphClips[m]} must be one-shot (loop=false)");
                Assert(morphClip.tracks.Count >= 5, $"{morphClips[m]} must animate >= 5 bones");
            }

            Vector2 morphOrigin = new Vector2(60.5f, 60.5f);
            bool[] noMissing = new bool[64];
            var lockedTurretNodes = new HashSet<string>(rotatingCategoryA.Where(id => id != "core_gimbal" && id != "core_rotor"), StringComparer.Ordinal);
            Assert(lockedTurretNodes.Count == 21, $"Expected 21 locked turret nodes, got {lockedTurretNodes.Count}");
            var wingGyroTurretNodes = new HashSet<string>(StringComparer.Ordinal)
            {
                "wing_pod_left", "railgun_outer_mount_left",
                "wing_pod_right", "railgun_outer_mount_right",
                "aft_wing_pod_left", "aft_wing_pod_right"
            };

            GiantAnimDef morphOut1 = anims["GCF_Anim_MechStage1_MorphOut"];
            GiantAnimDef morphIn2 = anims["GCF_Anim_MechStage2_MorphIn"];
            GiantAnimDef morphOut2 = anims["GCF_Anim_MechStage2_MorphOut"];
            GiantAnimDef morphIn3 = anims["GCF_Anim_MechStage3_MorphIn"];

            var s1EndLocal = new BoneLocalPose[64];
            var s1EndWorld = new BoneWorldPose[64];
            var s2In0Local = new BoneLocalPose[64];
            var s2In0World = new BoneWorldPose[64];
            var s2EndLocal = new BoneLocalPose[64];
            var s2EndWorld = new BoneWorldPose[64];
            var s3In0Local = new BoneLocalPose[64];
            var s3In0World = new BoneWorldPose[64];

            morphOut1.EvaluateInto(rig1, morphOut1.durationTicks, s1EndLocal);
            SkeletalKinematics.SolveWorldPoses(rig1, morphOrigin, 0f, s1EndLocal, noMissing, s1EndWorld);
            morphIn2.EvaluateInto(rig2, 0f, s2In0Local);
            SkeletalKinematics.SolveWorldPoses(rig2, morphOrigin, 0f, s2In0Local, noMissing, s2In0World);

            morphOut2.EvaluateInto(rig2, morphOut2.durationTicks, s2EndLocal);
            SkeletalKinematics.SolveWorldPoses(rig2, morphOrigin, 0f, s2EndLocal, noMissing, s2EndWorld);
            morphIn3.EvaluateInto(rig3, 0f, s3In0Local);
            SkeletalKinematics.SolveWorldPoses(rig3, morphOrigin, 0f, s3In0Local, noMissing, s3In0World);

            for (int bi = 0; bi < 64; bi++)
            {
                float d12Pos = Vector2.Distance(s1EndWorld[bi].jointWorldXZ, s2In0World[bi].jointWorldXZ);
                float d12Ang = Mathf.Abs(Mathf.DeltaAngle(s1EndWorld[bi].worldAngleDeg, s2In0World[bi].worldAngleDeg));
                Assert(d12Pos < 0.02f && d12Ang < 0.2f,
                    $"Zero-pop-in handoff violation S1->S2 on {rig1.SortedNodes[bi].nodeId}: posErr={d12Pos:F4}, angErr={d12Ang:F4}");

                float d23Pos = Vector2.Distance(s2EndWorld[bi].jointWorldXZ, s3In0World[bi].jointWorldXZ);
                float d23Ang = Mathf.Abs(Mathf.DeltaAngle(s2EndWorld[bi].worldAngleDeg, s3In0World[bi].worldAngleDeg));
                Assert(d23Pos < 0.02f && d23Ang < 0.2f,
                    $"Zero-pop-in handoff violation S2->S3 on {rig2.SortedNodes[bi].nodeId}: posErr={d23Pos:F4}, angErr={d23Ang:F4}");
            }

            foreach (var inCheck in new[] { (rig2, morphIn2), (rig3, morphIn3) })
            {
                var endPoses = new BoneLocalPose[64];
                inCheck.Item2.EvaluateInto(inCheck.Item1, inCheck.Item2.durationTicks, endPoses);
                for (int bi = 0; bi < 64; bi++)
                {
                    Assert(Mathf.Abs(endPoses[bi].angle) < 0.01f && endPoses[bi].offset.magnitude < 0.001f,
                        $"{inCheck.Item2.defName} at final tick must reach exact rest lock (0 deg) on {inCheck.Item1.SortedNodes[bi].nodeId}");
                }
            }

            foreach (var morphSample in new[] { (rig1, morphOut1), (rig2, morphIn2), (rig2, morphOut2), (rig3, morphIn3) })
            {
                GiantRigDef sRig = morphSample.Item1;
                GiantAnimDef sClip = morphSample.Item2;
                bool allowWingGyroTracks = sClip.defName == "GCF_Anim_MechStage2_MorphOut";
                foreach (BoneAnimTrack tr in sClip.tracks)
                {
                    Assert(tr.nodeId != "core_hull", $"Morph clip {sClip.defName} must NOT animate root node core_hull");
                    if (lockedTurretNodes.Contains(tr.nodeId))
                    {
                        Assert(allowWingGyroTracks && wingGyroTurretNodes.Contains(tr.nodeId),
                            $"Morph clip {sClip.defName} must NOT animate turret node {tr.nodeId}");
                    }
                    foreach (BoneKeyframe kf in tr.keyframes)
                    {
                        Assert(kf.easing == AnimEasing.Linear,
                            $"Morph clip {sClip.defName}:{tr.nodeId} keyframe t={kf.tick} must use Linear easing (zero elasticity), found {kf.easing}");
                    }
                }
                int maxT = Mathf.RoundToInt(sClip.durationTicks);
                var tmpLocal = new BoneLocalPose[64];
                var tmpWorld = new BoneWorldPose[64];
                for (float tk = 0f; tk <= maxT + 0.001f; tk += 0.5f)
                {
                    sClip.EvaluateInto(sRig, tk, tmpLocal);
                    SkeletalKinematics.SolveWorldPoses(sRig, morphOrigin, 0f, tmpLocal, noMissing, tmpWorld);
                    for (int bi = 0; bi < 64; bi++)
                    {
                        string nid = sRig.SortedNodes[bi].nodeId;
                        if (lockedTurretNodes.Contains(nid))
                        {
                            float wErr = Mathf.Abs(Mathf.DeltaAngle(0f, tmpWorld[bi].worldAngleDeg));
                            Assert(wErr < 0.05f,
                                $"Turret {nid} rotated during {sClip.defName} at tick={tk:F1}: worldAngle={tmpWorld[bi].worldAngleDeg:F3} deg");
                        }
                    }
                }
            }

            // Verify Stage 3 physical footprint strictly exceeds Stage 1 and GCF_Rathalos
            var (vlRig, vlMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var fp1 = new GiantFootprintData();
            var fp2 = new GiantFootprintData();
            var fp3 = new GiantFootprintData();
            var fpVl = new GiantFootprintData();
            IntVec3 center = new IntVec3(60, 0, 60);
            Vector2 rootXZ = new Vector2(60.5f, 60.5f);
            IntVec3 mapSize = new IntVec3(150, 1, 150);

            var wp1 = new BoneWorldPose[rig1.SortedNodes.Length];
            var wp2 = new BoneWorldPose[rig2.SortedNodes.Length];
            var wp3 = new BoneWorldPose[rig3.SortedNodes.Length];
            var wpVl = new BoneWorldPose[vlRig.SortedNodes.Length];

            SkeletalKinematics.SolveWorldPoses(rig1, rootXZ, 0f, Enumerable.Repeat(BoneLocalPose.Identity, rig1.SortedNodes.Length).ToArray(), new bool[rig1.SortedNodes.Length], wp1);
            SkeletalKinematics.SolveWorldPoses(rig2, rootXZ, 0f, Enumerable.Repeat(BoneLocalPose.Identity, rig2.SortedNodes.Length).ToArray(), new bool[rig2.SortedNodes.Length], wp2);
            SkeletalKinematics.SolveWorldPoses(rig3, rootXZ, 0f, Enumerable.Repeat(BoneLocalPose.Identity, rig3.SortedNodes.Length).ToArray(), new bool[rig3.SortedNodes.Length], wp3);
            SkeletalKinematics.SolveWorldPoses(vlRig, rootXZ, 0f, Enumerable.Repeat(BoneLocalPose.Identity, vlRig.SortedNodes.Length).ToArray(), new bool[vlRig.SortedNodes.Length], wpVl);

            fp1.Rebuild(rig1, wp1, masks1, center, mapSize);
            fp2.Rebuild(rig2, wp2, masks2, center, mapSize);
            fp3.Rebuild(rig3, wp3, masks3, center, mapSize);
            fpVl.Rebuild(vlRig, wpVl, vlMasks, center, mapSize);

            Console.WriteLine($"       -> HitCells: Stage1={fp1.hitCells.Count}, Stage2={fp2.hitCells.Count}, Rathalos={fpVl.hitCells.Count}, Stage3={fp3.hitCells.Count}");
            Assert(fp2.hitCells.Count > (int)(fp1.hitCells.Count * 1.5f), $"Stage2 hitCells ({fp2.hitCells.Count}) must vastly exceed Stage1 ({fp1.hitCells.Count})");
            Assert(fp3.hitCells.Count > fp2.hitCells.Count, $"Stage3 hitCells ({fp3.hitCells.Count}) must exceed Stage2 ({fp2.hitCells.Count})");
            Assert(fp3.hitCells.Count > fpVl.hitCells.Count, $"Stage3 hitCells ({fp3.hitCells.Count}) must exceed Rathalos ({fpVl.hitCells.Count})");

            // Verify XML Defs, Shader, AssetBundle, and ChineseSimplified translations
            string[] requiredFiles =
            {
                ResolveMod17Path("Defs", "Bodies", "Bodies_MechColossus.xml"),
                ResolveMod17Path("Defs", "AbilityDefs", "Abilities_MechColossus.xml"),
                ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_MechColossus.xml"),
                ResolveMod17Path("Defs", "ThingDefs_Races", "Races_MechColossus.xml"),
                ResolveMod17Path("Defs", "ShaderDefs", "ShaderDefs_MechColossus.xml"),
                ResolveMod17Path("Shaders", "GCF_MechReactorBone.frag.glsl"),
                ResolveMod17Path("AssetBundles", "gcf_mechcolossus_vfx_win"),
                ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "ThingDef", "Races_MechColossus.xml"),
                ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "PawnKindDef", "Races_MechColossus.xml"),
                ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "AbilityDef", "Abilities_MechColossus.xml"),
                ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "BodyDef", "Bodies_MechColossus.xml"),
                ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "BodyPartDef", "Bodies_MechColossus.xml"),
                ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "GiantCreatureFramework.GiantAnimDef", "GiantAnimDefs_MechColossus.xml")
            };
            for (int i = 0; i < requiredFiles.Length; i++)
            {
                Assert(File.Exists(requiredFiles[i]), $"Missing MechColossus asset/def: {requiredFiles[i]}");
            }

            string raceXml = File.ReadAllText(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_MechColossus.xml"));
            Assert(raceXml.Contains("CompProperties_GiantPhaseTransform"), "Races_MechColossus.xml missing CompProperties_GiantPhaseTransform");
            Assert(!raceXml.Contains("<tools>"), "Pure-ranged Races_MechColossus.xml must not define melee <tools>");
            Assert(raceXml.Contains("<canMeleeAttack>false</canMeleeAttack>"), "GCF_MechColossus PawnKindDef must set <canMeleeAttack>false</canMeleeAttack>");
            Assert(!raceXml.Contains("BaseGun") && !raceXml.Contains("<rangedWeaponDef>") && !raceXml.Contains("<weaponTags>"),
                "Races_MechColossus.xml must define zero BaseGun / <rangedWeaponDef> / <weaponTags> (100% part-driven weapons)");
            Assert(raceXml.Contains("stage1_bastion") && raceXml.Contains("stage2_aero") && raceXml.Contains("stage3_fortress"),
                "Races_MechColossus.xml missing one of the 3 stage IDs");

            string bodyXml = File.ReadAllText(ResolveMod17Path("Defs", "Bodies", "Bodies_MechColossus.xml"));
            XDocument mechRigDoc = XDocument.Load(ResolveMod17Path("Defs", "GiantRigDefs", "GiantRigDefs_MechColossus.xml"));
            var mcAttackIds = mechRigDoc.Descendants("attackId").Select(e => e.Value).ToHashSet(StringComparer.Ordinal);
            foreach (string reqAttackId in new[]
            {
                "colossus_s1_pulse", "colossus_s1_pulse_r",
                "colossus_s2_director_lance",
                "colossus_s2_plasma_l", "colossus_s2_plasma_r", "colossus_s2_plasma_aft_l", "colossus_s2_plasma_aft_r",
                "colossus_s3_apex_siege",
                "colossus_s3_railgun_l", "colossus_s3_railgun_r",
                "colossus_s3_outer_railgun_l", "colossus_s3_outer_railgun_r",
                "colossus_s3_wingpod_l", "colossus_s3_wingpod_r",
                "colossus_s3_aft_wingpod_l", "colossus_s3_aft_wingpod_r"
            })
            {
                Assert(mcAttackIds.Contains(reqAttackId), $"GiantRigDefs_MechColossus.xml missing stage partAttack '{reqAttackId}'");
            }
            XDocument mechRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_MechColossus.xml"));
            var mcBulletDefs = mechRaceDoc.Root!.Elements("ThingDef").Where(e => e.Element("projectile") != null).Select(e => e.Element("defName")?.Value).ToHashSet(StringComparer.Ordinal);
            foreach (string reqBullet in new[]
            {
                "GCF_Bullet_MechBastionPulse", "GCF_Bullet_MechDirectorLance", "GCF_Bullet_MechPlasmaBolt",
                "GCF_Bullet_MechApexSiegeShell", "GCF_Bullet_MechRailgunSlug", "GCF_Bullet_MechCoilgunSabot",
                "GCF_Bullet_MechInterceptorPulse"
            })
            {
                Assert(mcBulletDefs.Contains(reqBullet), $"Races_MechColossus.xml missing projectile ThingDef '{reqBullet}'");
            }
            foreach (string s2OnlyBone in new[] { "turret_neck", "command_head", "plasma_rail_left", "plasma_rail_right", "plasma_rail_aft_left", "plasma_rail_aft_right" })
            {
                Assert(rig3.TryGetNodeIndex(s2OnlyBone, out int s3StowIdx), $"Missing bone '{s2OnlyBone}' in Stage3");
                Assert(!rig3.SortedNodes[s3StowIdx].isTurret && rig3.SortedNodes[s3StowIdx].partAttacks.Count == 0,
                    $"Stage2-only bone '{s2OnlyBone}' must stay inactive (isTurret=false, 0 partAttacks) when stowed in Stage3");
            }
            foreach (XElement linkedPart in mechRigDoc.Descendants("linkedBodyPart"))
            {
                Assert(bodyXml.Contains(linkedPart.Value), $"BodyDef missing linkedBodyPart {linkedPart.Value}");
            }

            var zhMergedKeys = LoadMergedKeyedMap("ChineseSimplified");
            string zhKeys = string.Join("\n", zhMergedKeys.Keys);
            Assert(zhKeys.Contains("GCF_Stage_MechBastion") && zhKeys.Contains("GCF_Stage_MechAeroFrame") && zhKeys.Contains("GCF_Stage_MechOrbitalFortress"),
                "ChineseSimplified Keyed missing stage label keys");

            // Verify all 3 MechColossus stages converge & split-aim per turret pivot without hull-center parallax
            static void StepColossusTurrets(
                GiantRigDef rig,
                GiantSteeringRuntime steerRt,
                GiantPartCombatRuntime partRt,
                BoneLocalPose[] localPoses,
                bool[] missing,
                BoneWorldPose[] worldPoses,
                Vector2 centerXZ,
                bool isMoving,
                int ticks,
                int baseContinuousTick)
            {
                var ctx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 0f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = false,
                    IsMoving = isMoving,
                    MovedDistanceCells = isMoving ? 0.08f : 0f,
                    AnimState = isMoving ? GiantAnimState.Walk : GiantAnimState.Idle,
                    ContinuousTicks = baseContinuousTick,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = true
                };
                for (int t = 0; t < ticks; t++)
                {
                    ctx.ContinuousTicks = baseContinuousTick + t;
                    for (int i = 0; i < localPoses.Length; i++)
                    {
                        localPoses[i] = BoneLocalPose.Identity;
                    }
                    steerRt.ApplyBoneSteering(rig, 0f, localPoses, missing, 1f, in ctx, centerXZ, partRt);
                }
                SkeletalKinematics.SolveWorldPoses(rig, centerXZ, 0f, localPoses, missing, worldPoses);
            }

            static float BearingDeg(Vector2 fromXZ, Vector2 toXZ) => Mathf.Atan2(toXZ.x - fromXZ.x, toXZ.y - fromXZ.y) * Mathf.Rad2Deg;

            // Stage 1: 360-degree independent turret tracking to rear-port target
            var s1PartRt = new GiantPartCombatRuntime(null);
            s1PartRt.RebuildFromRig(rig1);
            var s1Steer = new GiantSteeringRuntime(rig1);
            s1Steer.Reset(0f);
            var s1Local = new BoneLocalPose[rig1.SortedNodes.Length];
            var s1Miss = new bool[rig1.SortedNodes.Length];
            var s1World = new BoneWorldPose[rig1.SortedNodes.Length];
            BonePartWeaponGroup s1PulseGrp = s1PartRt.Groups.First(g => g.Bone.nodeId == "sensor_turret");
            Assert(s1PulseGrp.IsLookChainDriven, "Stage1 sensor_turret must be IsLookChainDriven");
            Vector2 s1RearTarg = new Vector2(rootXZ.x - 10f, rootXZ.y - 12f);
            s1PulseGrp.Phase = PartWeaponPhase.WarmingUp;
            s1PulseGrp.TargetWorldXZ = s1RearTarg;
            s1PulseGrp.HasTargetWorldXZ = true;
            StepColossusTurrets(rig1, s1Steer, s1PartRt, s1Local, s1Miss, s1World, rootXZ, isMoving: false, ticks: 50, baseContinuousTick: 0);
            Assert(rig1.TryGetNodeIndex("sensor_turret", out int s1TurretIdx), "Missing Stage1 sensor_turret");
            float s1Exp = BearingDeg(s1World[s1TurretIdx].jointWorldXZ, s1RearTarg);
            float s1Err = Mathf.Abs(Mathf.DeltaAngle(s1World[s1TurretIdx].worldAngleDeg, s1Exp));
            Assert(s1Err <= 1.0f, $"Stage1 sensor_turret must aim accurately at aft-port target: actual={s1World[s1TurretIdx].worldAngleDeg:F2}, expected={s1Exp:F2}, err={s1Err:F2}");

            // Stage 2: Twin plasma rails converge on single flank target (canceling +-6 deg rest splay) AND split Port vs Starboard
            var s2PartRt = new GiantPartCombatRuntime(null);
            s2PartRt.RebuildFromRig(rig2);
            var s2Steer = new GiantSteeringRuntime(rig2);
            s2Steer.Reset(0f);
            var s2Local = new BoneLocalPose[rig2.SortedNodes.Length];
            var s2Miss = new bool[rig2.SortedNodes.Length];
            var s2World = new BoneWorldPose[rig2.SortedNodes.Length];
            BonePartWeaponGroup s2LeftGrp = s2PartRt.Groups.First(g => g.Bone.nodeId == "plasma_rail_left");
            BonePartWeaponGroup s2RightGrp = s2PartRt.Groups.First(g => g.Bone.nodeId == "plasma_rail_right");
            Assert(s2LeftGrp.IsLookChainDriven && s2RightGrp.IsLookChainDriven, "Stage2 plasma rails must be IsLookChainDriven");
            Assert(rig2.TryGetNodeIndex("plasma_rail_left", out int s2LIdx), "Missing Stage2 plasma_rail_left");
            Assert(rig2.TryGetNodeIndex("plasma_rail_right", out int s2RIdx), "Missing Stage2 plasma_rail_right");

            Vector2 s2Single = new Vector2(rootXZ.x + 10f, rootXZ.y + 14f);
            s2LeftGrp.Phase = PartWeaponPhase.WarmingUp;
            s2LeftGrp.TargetWorldXZ = s2Single;
            s2LeftGrp.HasTargetWorldXZ = true;
            s2RightGrp.Phase = PartWeaponPhase.WarmingUp;
            s2RightGrp.TargetWorldXZ = s2Single;
            s2RightGrp.HasTargetWorldXZ = true;
            StepColossusTurrets(rig2, s2Steer, s2PartRt, s2Local, s2Miss, s2World, rootXZ, isMoving: false, ticks: 60, baseContinuousTick: 0);
            float s2LErr = Mathf.Abs(Mathf.DeltaAngle(s2World[s2LIdx].worldAngleDeg, BearingDeg(s2World[s2LIdx].jointWorldXZ, s2Single)));
            float s2RErr = Mathf.Abs(Mathf.DeltaAngle(s2World[s2RIdx].worldAngleDeg, BearingDeg(s2World[s2RIdx].jointWorldXZ, s2Single)));
            Assert(s2LErr <= 1.5f && s2RErr <= 1.5f,
                $"Stage2 twin plasma rails must both converge onto single target without splay: L_err={s2LErr:F2}, R_err={s2RErr:F2}");

            Vector2 s2SplitL = new Vector2(rootXZ.x - 15f, rootXZ.y + 12f);
            Vector2 s2SplitR = new Vector2(rootXZ.x + 15f, rootXZ.y + 12f);
            s2LeftGrp.TargetWorldXZ = s2SplitL;
            s2RightGrp.TargetWorldXZ = s2SplitR;
            StepColossusTurrets(rig2, s2Steer, s2PartRt, s2Local, s2Miss, s2World, rootXZ, isMoving: false, ticks: 60, baseContinuousTick: 60);
            float s2SplitLAng = Mathf.DeltaAngle(0f, s2World[s2LIdx].worldAngleDeg);
            float s2SplitRAng = Mathf.DeltaAngle(0f, s2World[s2RIdx].worldAngleDeg);
            float s2SplitLErr = Mathf.Abs(Mathf.DeltaAngle(s2World[s2LIdx].worldAngleDeg, BearingDeg(s2World[s2LIdx].jointWorldXZ, s2SplitL)));
            float s2SplitRErr = Mathf.Abs(Mathf.DeltaAngle(s2World[s2RIdx].worldAngleDeg, BearingDeg(s2World[s2RIdx].jointWorldXZ, s2SplitR)));
            Assert(s2SplitLAng < -30f && s2SplitRAng > 30f && s2SplitLErr <= 1.5f && s2SplitRErr <= 1.5f,
                $"Stage2 twin plasma rails must simultaneously split-aim left/right: L={s2SplitLAng:F1} (err={s2SplitLErr:F2}), R={s2SplitRAng:F1} (err={s2SplitRErr:F2})");

            // Stage 3: 4 turrets converge inward on close target without parallax AND independently engage 360-deg split targets while moving
            var s3PartRt = new GiantPartCombatRuntime(null);
            s3PartRt.RebuildFromRig(rig3);
            var s3Steer = new GiantSteeringRuntime(rig3);
            s3Steer.Reset(0f);
            var s3Local = new BoneLocalPose[rig3.SortedNodes.Length];
            var s3Miss = new bool[rig3.SortedNodes.Length];
            var s3World = new BoneWorldPose[rig3.SortedNodes.Length];
            BonePartWeaponGroup s3RailL = s3PartRt.Groups.First(g => g.Bone.nodeId == "railgun_barrel_left");
            BonePartWeaponGroup s3RailR = s3PartRt.Groups.First(g => g.Bone.nodeId == "railgun_barrel_right");
            BonePartWeaponGroup s3PodL = s3PartRt.Groups.First(g => g.Bone.nodeId == "wing_pod_left");
            BonePartWeaponGroup s3PodR = s3PartRt.Groups.First(g => g.Bone.nodeId == "wing_pod_right");
            Assert(s3RailL.IsLookChainDriven && s3RailR.IsLookChainDriven && s3PodL.IsLookChainDriven && s3PodR.IsLookChainDriven,
                "All 4 Stage3 weapon turrets must be IsLookChainDriven");
            Assert(rig3.TryGetNodeIndex("railgun_barrel_left", out int s3RailLIdx), "Missing Stage3 railgun_barrel_left");
            Assert(rig3.TryGetNodeIndex("railgun_barrel_right", out int s3RailRIdx), "Missing Stage3 railgun_barrel_right");
            Assert(rig3.TryGetNodeIndex("wing_pod_left", out int s3PodLIdx), "Missing Stage3 wing_pod_left");
            Assert(rig3.TryGetNodeIndex("wing_pod_right", out int s3PodRIdx), "Missing Stage3 wing_pod_right");

            Vector2 s3CloseTarg = new Vector2(rootXZ.x, rootXZ.y + 17f);
            foreach (BonePartWeaponGroup wg in new[] { s3RailL, s3RailR, s3PodL, s3PodR })
            {
                wg.Phase = PartWeaponPhase.WarmingUp;
                wg.TargetWorldXZ = s3CloseTarg;
                wg.HasTargetWorldXZ = true;
            }
            StepColossusTurrets(rig3, s3Steer, s3PartRt, s3Local, s3Miss, s3World, rootXZ, isMoving: false, ticks: 60, baseContinuousTick: 0);
            float podLAng = Mathf.DeltaAngle(0f, s3World[s3PodLIdx].worldAngleDeg);
            float podRAng = Mathf.DeltaAngle(0f, s3World[s3PodRIdx].worldAngleDeg);
            float railLErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3RailLIdx].worldAngleDeg, BearingDeg(s3World[s3RailLIdx].jointWorldXZ, s3CloseTarg)));
            float railRErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3RailRIdx].worldAngleDeg, BearingDeg(s3World[s3RailRIdx].jointWorldXZ, s3CloseTarg)));
            float podLErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3PodLIdx].worldAngleDeg, BearingDeg(s3World[s3PodLIdx].jointWorldXZ, s3CloseTarg)));
            float podRErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3PodRIdx].worldAngleDeg, BearingDeg(s3World[s3PodRIdx].jointWorldXZ, s3CloseTarg)));
            Assert(podLAng > 20f && podRAng < -20f && railLErr <= 1.5f && railRErr <= 1.5f && podLErr <= 1.5f && podRErr <= 1.5f,
                $"Stage3 4 turrets must converge inward onto close bow target without parallax: podL={podLAng:F1}, podR={podRAng:F1}, errs=({railLErr:F2},{railRErr:F2},{podLErr:F2},{podRErr:F2})");

            Vector2 s3AftPort = new Vector2(rootXZ.x - 18f, rootXZ.y - 14f);
            Vector2 s3FwdStbd = new Vector2(rootXZ.x + 18f, rootXZ.y + 16f);
            s3RailL.TargetWorldXZ = s3AftPort;
            s3PodL.TargetWorldXZ = s3AftPort;
            s3RailR.TargetWorldXZ = s3FwdStbd;
            s3PodR.TargetWorldXZ = s3FwdStbd;
            StepColossusTurrets(rig3, s3Steer, s3PartRt, s3Local, s3Miss, s3World, rootXZ, isMoving: true, ticks: 60, baseContinuousTick: 50);
            float s3SplitRailLErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3RailLIdx].worldAngleDeg, BearingDeg(s3World[s3RailLIdx].jointWorldXZ, s3AftPort)));
            float s3SplitPodLErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3PodLIdx].worldAngleDeg, BearingDeg(s3World[s3PodLIdx].jointWorldXZ, s3AftPort)));
            float s3SplitRailRErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3RailRIdx].worldAngleDeg, BearingDeg(s3World[s3RailRIdx].jointWorldXZ, s3FwdStbd)));
            float s3SplitPodRErr = Mathf.Abs(Mathf.DeltaAngle(s3World[s3PodRIdx].worldAngleDeg, BearingDeg(s3World[s3PodRIdx].jointWorldXZ, s3FwdStbd)));
            Assert(s3SplitRailLErr <= 1.5f && s3SplitPodLErr <= 1.5f && s3SplitRailRErr <= 1.5f && s3SplitPodRErr <= 1.5f,
                $"Stage3 must independently track 360-deg split targets while moving: railL_err={s3SplitRailLErr:F2}, podL_err={s3SplitPodLErr:F2}, railR_err={s3SplitRailRErr:F2}, podR_err={s3SplitPodRErr:F2}");

            // Verify Manual Phase-Advance Ability (GCF_Ability_MechPhaseAdvance): icon, XML config, stage assignment, CN/EN keys, and runtime Stage 1 -> 2 -> 3 state transitions
            string phaseIconPath = ResolveMod17Path("Textures", "UI", "Abilities", "MechPhaseAdvance.png");
            Assert(File.Exists(phaseIconPath), $"Missing manual phase-advance icon: {phaseIconPath}");
            _ = DecodePngRgbaTopDown(phaseIconPath, out int phaseIconW, out int phaseIconH);
            Assert(phaseIconW == 512 && phaseIconH == 512, $"MechPhaseAdvance.png must be 512x512 RGBA, got {phaseIconW}x{phaseIconH}");

            XDocument mcAbDoc = XDocument.Load(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_MechColossus.xml"));
            XElement phaseAbEl = mcAbDoc.Root!.Elements("AbilityDef").FirstOrDefault(e => e.Element("defName")?.Value == "GCF_Ability_MechPhaseAdvance");
            Assert(phaseAbEl != null, "Abilities_MechColossus.xml missing GCF_Ability_MechPhaseAdvance");
            Assert(string.Equals(phaseAbEl!.Element("targetRequired")?.Value?.Trim(), "false", StringComparison.OrdinalIgnoreCase),
                "GCF_Ability_MechPhaseAdvance must set <targetRequired>false</targetRequired>");
            Assert(string.Equals(phaseAbEl.Element("aiCanUse")?.Value?.Trim(), "false", StringComparison.OrdinalIgnoreCase),
                "GCF_Ability_MechPhaseAdvance must set <aiCanUse>false</aiCanUse> so AI never skips phases automatically");
            Assert(string.Equals(phaseAbEl.Element("displayGizmoWhileUndrafted")?.Value?.Trim(), "true", StringComparison.OrdinalIgnoreCase) &&
                   string.Equals(phaseAbEl.Element("disableGizmoWhileUndrafted")?.Value?.Trim(), "false", StringComparison.OrdinalIgnoreCase),
                "GCF_Ability_MechPhaseAdvance must remain visible and usable while undrafted");
            Assert(string.Equals(phaseAbEl.Element("verbProperties")?.Element("nonInterruptingSelfCast")?.Value?.Trim(), "true", StringComparison.OrdinalIgnoreCase),
                "GCF_Ability_MechPhaseAdvance must set <nonInterruptingSelfCast>true</nonInterruptingSelfCast>");
            Assert(phaseAbEl.Element("comps")!.Elements("li").Any(c => (c.Attribute("Class")?.Value ?? string.Empty).EndsWith("CompProperties_AbilityMechPhaseAdvance", StringComparison.Ordinal)),
                "GCF_Ability_MechPhaseAdvance missing CompProperties_AbilityMechPhaseAdvance");
            XElement phaseBoneReq = phaseAbEl.Element("comps")!.Elements("li").FirstOrDefault(c => (c.Attribute("Class")?.Value ?? string.Empty).EndsWith("CompProperties_AbilityRequiresGiantBone", StringComparison.Ordinal));
            Assert(phaseBoneReq != null && phaseBoneReq.Element("requiredBoneIds")?.Elements("li").Any(x => x.Value.Trim() == "core_hull") == true,
                "GCF_Ability_MechPhaseAdvance must bind to core_hull via CompProperties_AbilityRequiresGiantBone");

            List<XElement> stageEls = mechRaceDoc.Descendants("stages").First().Elements("li").ToList();
            Assert(stageEls.Count == 3, $"Expected 3 phase transform stages on GCF_MechColossus, got {stageEls.Count}");
            var s1Abs = stageEls[0].Element("stageAbilities")?.Elements("li").Select(x => x.Value.Trim()).ToList() ?? new List<string>();
            var s2Abs = stageEls[1].Element("stageAbilities")?.Elements("li").Select(x => x.Value.Trim()).ToList() ?? new List<string>();
            var s3Abs = stageEls[2].Element("stageAbilities")?.Elements("li").Select(x => x.Value.Trim()).ToList() ?? new List<string>();
            Assert(s1Abs.Contains("GCF_Ability_MechPhaseAdvance") && s2Abs.Contains("GCF_Ability_MechPhaseAdvance") && !s3Abs.Contains("GCF_Ability_MechPhaseAdvance"),
                "GCF_Ability_MechPhaseAdvance must be granted in stage1_bastion & stage2_aero and omitted in final stage3_fortress");

            string abZhXml = File.ReadAllText(ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "AbilityDef", "Abilities_MechColossus.xml"));
            Assert(abZhXml.Contains("GCF_Ability_MechPhaseAdvance.label") && abZhXml.Contains("GCF_Ability_MechPhaseAdvance.description"),
                "ChineseSimplified AbilityDef DefInjected missing GCF_Ability_MechPhaseAdvance translations");
            string enKeysXml = string.Join("\n", LoadMergedKeyedMap("English").Keys);
            foreach (string pk in new[] { "GCF_PhaseAdvanceDisabledTransforming", "GCF_PhaseAdvanceDisabledFinalStage", "GCF_PhaseAdvanceDisabledUnavailable" })
            {
                Assert(zhKeys.Contains(pk) && enKeysXml.Contains(pk), $"CN/EN Keyed XML missing phase-advance key '{pk}'");
            }

            Pawn phaseTestPawn = new Pawn
            {
                def = new ThingDef { defName = "GCF_MechColossus" },
                thingIDNumber = 90001
            };
            var phaseProps = new CompProperties_GiantPhaseTransform
            {
                stages = new List<GiantPhaseStageDef>
                {
                    new GiantPhaseStageDef { stageId = "stage1_bastion", rigDef = rig1 },
                    new GiantPhaseStageDef { stageId = "stage2_aero", rigDef = rig2 },
                    new GiantPhaseStageDef { stageId = "stage3_fortress", rigDef = rig3 }
                }
            };
            var phaseComp = new CompGiantPhaseTransform { parent = phaseTestPawn };
            phaseComp.Initialize(phaseProps);
            try
            {
                var advanceAbDef = new RimWorld.AbilityDef { defName = "GCF_Ability_MechPhaseAdvance" };
                var advanceAb = new RimWorld.Ability { pawn = phaseTestPawn, def = advanceAbDef };
                var advanceFx = new CompAbilityEffect_MechPhaseAdvance { parent = advanceAb };
                advanceFx.Initialize(new CompProperties_AbilityMechPhaseAdvance());

                MethodInfo finishTransformMi = typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.Instance | BindingFlags.NonPublic);
                Assert(finishTransformMi != null, "Missing private CompGiantPhaseTransform.FinishTransformation method");

                Assert(phaseComp.CurrentStageIndex == 0 && phaseComp.HasNextStage && !phaseComp.IsTransforming, "PhaseTransform must start in stage 0 ready");
                Assert(!advanceFx.AICanTargetNow(LocalTargetInfo.Invalid), "Manual phase advance AICanTargetNow must strictly return false");
                Assert(!advanceFx.GizmoDisabled(out string s1DisableReason), $"Phase advance gizmo must be enabled in Stage 1 (disabled reason: '{s1DisableReason}')");
                advanceFx.Apply(LocalTargetInfo.Invalid, LocalTargetInfo.Invalid);
                Assert(phaseComp.IsTransforming && phaseComp.MorphState == PhaseMorphState.MorphingOut, "Stage 1 Apply must enter MorphingOut");
                Assert(advanceFx.GizmoDisabled(out string morphDisableReason) && !string.IsNullOrEmpty(morphDisableReason), "Phase advance gizmo must be disabled while transforming");
                Assert(!phaseComp.TryAdvanceToNextStageManually(), "Duplicate manual advance during MorphingOut must return false");

                phaseComp.ForceAdvanceStageImmediateForTest();
                finishTransformMi!.Invoke(phaseComp, null);
                Assert(phaseComp.CurrentStageIndex == 1 && phaseComp.HasNextStage && !phaseComp.IsTransforming, "Stage 2 must be settled at index 1");
                Assert(!advanceFx.GizmoDisabled(out string s2DisableReason), $"Phase advance gizmo must be re-enabled in Stage 2 (disabled reason: '{s2DisableReason}')");
                Assert(phaseComp.TryAdvanceToNextStageManually(), "Stage 2 manual advance must succeed");
                Assert(phaseComp.IsTransforming && phaseComp.MorphState == PhaseMorphState.MorphingOut, "Stage 2 manual advance must enter MorphingOut toward Stage 3");

                phaseComp.ForceAdvanceStageImmediateForTest();
                finishTransformMi.Invoke(phaseComp, null);
                Assert(phaseComp.CurrentStageIndex == 2 && !phaseComp.HasNextStage && !phaseComp.IsTransforming, "Stage 3 must be final settled stage");
                Assert(advanceFx.GizmoDisabled(out string s3DisableReason) && !string.IsNullOrEmpty(s3DisableReason), "Phase advance gizmo must be disabled in final Stage 3");
                Assert(!phaseComp.TryAdvanceToNextStageManually(), "Manual advance in final Stage 3 must return false");
            }
            finally
            {
                GiantFastLookup.UnregisterPhaseTransform(phaseTestPawn);
            }
        }

        private static void TestVfxMuzzleWeakpointsExplosionAndCorpseMechanics()
        {
            // 1. Keyframe-synchronized animation event crossing (both linear and looping wrap-around)
            Assert(GiantAnimDef.DidCrossEventTick(10f, 15f, 12f, 40f, loop: false),
                "DidCrossEventTick must detect crossing eventTick=12 between [10, 15]");
            Assert(!GiantAnimDef.DidCrossEventTick(10f, 11.9f, 12f, 40f, loop: false),
                "DidCrossEventTick must not fire before reaching eventTick=12");
            Assert(GiantAnimDef.DidCrossEventTick(38f, 3f, 39.5f, 40f, loop: true),
                "DidCrossEventTick must detect crossing eventTick=39.5 across loop wrap-around 38 -> 3");
            Assert(GiantAnimDef.DidCrossEventTick(38f, 3f, 1.5f, 40f, loop: true),
                "DidCrossEventTick must detect crossing eventTick=1.5 across loop wrap-around 38 -> 3");

            // 2. Muzzle Pixel/UV & Persistent VFX Pixel/UV resolution + 360-degree world projection
            var turretNode = new BoneNodeDef
            {
                nodeId = "test_turret",
                textureResolution = 512,
                drawSize = new Vector2(4f, 6f),
                pivotPixel = new Vector2(256f, 256f),
                muzzlePixel = new Vector2(256f, 32f),
                persistentVfxPixel = new Vector2(256f, 448f),
                glowTexPath = "Things/Pawn/GiantCreature/MechScorpion/Turret",
                glowLayerOffset = 0.08f
            };
            var singleRig = new GiantRigDef { defName = "TestSingleTurretRig" };
            singleRig.nodes.Add(turretNode);
            singleRig.BuildTopology();
            AssertNear(turretNode.resolvedMuzzleUV.x, 0.5f, 1e-4f, "resolvedMuzzleUV.x");
            AssertNear(turretNode.resolvedMuzzleUV.y, 1f - (32f / 512f), 1e-4f, "resolvedMuzzleUV.y (top of texture = forward muzzle)");
            AssertNear(turretNode.resolvedPersistentVfxUV.y, 1f - (448f / 512f), 1e-4f, "resolvedPersistentVfxUV.y");
            var local = new[] { BoneLocalPose.Identity };
            var miss = new[] { false };
            var world = new BoneWorldPose[1];
            Vector2 centerXZ = new Vector2(50.5f, 50.5f);
            SkeletalKinematics.SolveWorldPoses(singleRig, centerXZ, 90f, local, miss, world);
            Vector2 muzzleEastXZ = world[0].UVToWorldXZ(turretNode.resolvedMuzzleUV.x, turretNode.resolvedMuzzleUV.y);
            Assert(muzzleEastXZ.x > centerXZ.x + 2.0f && Mathf.Abs(muzzleEastXZ.y - centerXZ.y) < 0.01f,
                $"Facing East (90 deg), muzzle world XZ must project +X ahead of joint center, got {muzzleEastXZ}");

            // 3. Per-bone armor & weakpoint effective damage multiplier calculation
            var heavyCarapaceBone = new BoneNodeDef
            {
                nodeId = "front_carapace",
                damageMultiplier = 0.65f,
                armorMultiplier = 2.0f,
                deflectChance = 0.25f
            };
            var exposedCoreBone = new BoneNodeDef
            {
                nodeId = "exposed_void_core",
                damageMultiplier = 1.75f,
                armorMultiplier = 0.5f,
                deflectChance = 0.0f
            };
            float carapaceMult = GiantCombatMechanicsUtility.ComputeEffectiveBoneDamageMultiplier(heavyCarapaceBone);
            float coreMult = GiantCombatMechanicsUtility.ComputeEffectiveBoneDamageMultiplier(exposedCoreBone);
            Assert(carapaceMult < 0.60f, $"Heavy carapace effective damage multiplier must reduce damage (< 0.60), got {carapaceMult:F3}");
            Assert(coreMult > 2.0f, $"Exposed core weakpoint effective damage multiplier must amplify damage (> 2.0), got {coreMult:F3}");

            // 4. Multi-cell explosion closest-hit-bone routing on MechScorpion footprint
            var (scRig, scMasks, _) = LoadMechScorpionFromXml();
            int sn = scRig.SortedNodes.Length;
            var scWorld = new BoneWorldPose[sn];
            SkeletalKinematics.SolveWorldPoses(
                scRig,
                centerXZ,
                0f,
                Enumerable.Repeat(BoneLocalPose.Identity, sn).ToArray(),
                new bool[sn],
                scWorld);
            var scFp = new GiantFootprintData();
            scFp.Rebuild(scRig, scWorld, scMasks, new IntVec3(50, 0, 50), new IntVec3(120, 1, 120));
            Assert(scFp.hitCells.Count > 10, "MechScorpion footprint must contain > 10 hit cells");
            int frontBlastBone = scFp.FindClosestHitBoneToCell(new IntVec3(50, 0, 60));
            Assert(frontBlastBone >= 0 && frontBlastBone < sn, $"Explosion cell ahead of giant must resolve valid bone index, got {frontBlastBone}");
        }

        private static void TestGiantToGiantHullCollisionAvoidanceAndReach()
        {
            var (vlRig, vlMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            int n = vlRig.SortedNodes.Length;
            var poses = new BoneWorldPose[n];
            var local = Enumerable.Repeat(BoneLocalPose.Identity, n).ToArray();
            var missing = new bool[n];

            // 1. Anchor-accurate localCollisionOffsets & tightCollisionBounds
            IntVec3 anchor = new IntVec3(50, 0, 50);
            SkeletalKinematics.SolveWorldPoses(vlRig, new Vector2(50.5f, 50.5f), 0f, local, missing, poses);
            var fp = new GiantFootprintData();
            fp.Rebuild(vlRig, poses, vlMasks, anchor, new IntVec3(120, 1, 120), collisionAnchorOverride: anchor);

            Assert(fp.collisionAnchorCell == anchor, $"Expected collisionAnchorCell {anchor}, got {fp.collisionAnchorCell}");
            Assert(fp.collisionCells.Count > 10, $"Expected >10 Void Leviathan collision cells, got {fp.collisionCells.Count}");
            Assert(fp.localCollisionOffsets.Count == fp.collisionCells.Count,
                $"localCollisionOffsets ({fp.localCollisionOffsets.Count}) must match collisionCells ({fp.collisionCells.Count})");
            Assert(fp.maxCollisionHorizontalExtent >= 2, $"Expected maxCollisionHorizontalExtent >= 2, got {fp.maxCollisionHorizontalExtent}");
            Assert(fp.tightCollisionBounds.Area > 0, "Expected non-empty tightCollisionBounds");
            for (int i = 0; i < fp.localCollisionOffsets.Count; i++)
            {
                IntVec3 reconstructed = anchor + fp.localCollisionOffsets[i];
                Assert(fp.collisionCellSet.Contains(reconstructed), $"Offset {fp.localCollisionOffsets[i]} failed round-trip lookup");
            }

            // Verify rotated/translated anchor override
            IntVec3 rotAnchor = new IntVec3(51, 0, 50);
            SkeletalKinematics.SolveWorldPoses(vlRig, new Vector2(51.4f, 50.5f), 90f, local, missing, poses);
            var fpRot = new GiantFootprintData();
            fpRot.Rebuild(vlRig, poses, vlMasks, anchor, new IntVec3(120, 1, 120), collisionAnchorOverride: rotAnchor);
            Assert(fpRot.collisionAnchorCell == rotAnchor, "collisionAnchorOverride must override pawn fallback anchor");
            Assert(fpRot.localCollisionOffsets.Count == fpRot.collisionCells.Count, "Rotated offsets count mismatch");
            for (int i = 0; i < fpRot.localCollisionOffsets.Count; i++)
            {
                Assert(fpRot.collisionCellSet.Contains(rotAnchor + fpRot.localCollisionOffsets[i]), "Rotated offset round-trip failed");
            }

            // 2. Strict hull-overlap gating & monotonic escape
            var blockerHull = new HashSet<IntVec3>(fp.collisionCells);
            IReadOnlyList<IntVec3> offsets = fp.localCollisionOffsets;

            IntVec3 clearFrom = anchor + new IntVec3(30, 0, 0);
            IntVec3 clearTo = anchor + new IntVec3(29, 0, 0);
            Assert(!GiantHullCollisionUtility.ShouldBlockStepAgainstHull(clearFrom, clearTo, offsets, blockerHull, out int oClearCand, out _),
                $"Separated hull move must not be blocked (overlap={oClearCand})");
            Assert(oClearCand == 0, $"Expected 0 overlap when 29 cells apart, got {oClearCand}");

            int dxFirstOverlap = -1;
            for (int dx = 25; dx >= 1; dx--)
            {
                if (GiantHullCollisionUtility.CountTranslatedHullOverlap(anchor + new IntVec3(dx, 0, 0), offsets, blockerHull) > 0)
                {
                    dxFirstOverlap = dx;
                    break;
                }
            }
            Assert(dxFirstOverlap >= 2, $"Expected boundary overlap at dx >= 2, got {dxFirstOverlap}");
            IntVec3 justOutside = anchor + new IntVec3(dxFirstOverlap + 1, 0, 0);
            IntVec3 firstInside = anchor + new IntVec3(dxFirstOverlap, 0, 0);
            Assert(GiantHullCollisionUtility.ShouldBlockStepAgainstHull(justOutside, firstInside, offsets, blockerHull, out int enterCand, out int enterCur),
                $"Entering overlap ({enterCur}->{enterCand}) must be blocked");

            IntVec3 deepInside = anchor;
            IntVec3 halfOut = anchor + new IntVec3(2, 0, 0);
            int halfOutOverlap = GiantHullCollisionUtility.CountTranslatedHullOverlap(halfOut, offsets, blockerHull);
            int deepOverlap = GiantHullCollisionUtility.CountTranslatedHullOverlap(deepInside, offsets, blockerHull);
            Assert(halfOutOverlap < deepOverlap, $"Expected moving +2 outward to reduce overlap ({halfOutOverlap} < {deepOverlap})");
            Assert(!GiantHullCollisionUtility.ShouldBlockStepAgainstHull(deepInside, halfOut, offsets, blockerHull, out _, out _),
                "Strictly overlap-reducing escape step must be allowed");
            Assert(GiantHullCollisionUtility.ShouldBlockStepAgainstHull(halfOut, deepInside, offsets, blockerHull, out _, out _),
                "Overlap-increasing step back into blocker hull must be blocked");

            // 3. Snapshot Minkowski A* avoidance cost stamping
            int sizeX = 80;
            int sizeZ = 80;
            IntVec3 g1Anchor = new IntVec3(25, 0, 30);
            IntVec3 g2Anchor = new IntVec3(45, 0, 30);
            IntVec3[] offsArr = fp.localCollisionOffsets.ToArray();
            var g1Cols = new IntVec3[offsArr.Length];
            var g2Cols = new IntVec3[offsArr.Length];
            for (int i = 0; i < offsArr.Length; i++)
            {
                g1Cols[i] = g1Anchor + offsArr[i];
                g2Cols[i] = g2Anchor + offsArr[i];
            }
            var snap = new GiantPathAvoidanceSnapshot(sizeX, sizeZ, new[]
            {
                new GiantSnapshotEntry(1, g1Anchor, CellRect.CenteredOn(g1Anchor, 6), offsArr, g1Cols, 400, fp.maxCollisionHorizontalExtent),
                new GiantSnapshotEntry(2, g2Anchor, CellRect.CenteredOn(g2Anchor, 6), offsArr, g2Cols, 400, fp.maxCollisionHorizontalExtent),
            });

            var providerCost = new ushort[sizeX * sizeZ];
            providerCost[0] = GiantHullCollisionUtility.ImpassableProviderCost; // existing impassable obstacle at (0,0)
            GiantHullCollisionUtility.StampAvoidanceCosts(snap, requesterPawnId: 1, providerCost);

            Assert(providerCost[0] == GiantHullCollisionUtility.ImpassableProviderCost, "Existing impassable cost >= 10000 must be preserved");
            int centerOverlapIdx = g2Anchor.z * sizeX + g2Anchor.x;
            Assert(providerCost[centerOverlapIdx] >= GiantHullCollisionUtility.BaseFirstOverlapPenalty + GiantHullCollisionUtility.PerCellOverlapPenalty,
                $"Expected high Minkowski avoidance penalty at g2Anchor, got {providerCost[centerOverlapIdx]}");
            Assert(providerCost[centerOverlapIdx] <= GiantHullCollisionUtility.MaxCombinedProviderCost && providerCost[centerOverlapIdx] < GiantHullCollisionUtility.ImpassableProviderCost,
                $"Avoidance penalty must stay < 10000 so flanking paths never fail prematurely, got {providerCost[centerOverlapIdx]}");
            int clearFlankIdx = 70 * sizeX + 45;
            Assert(providerCost[clearFlankIdx] == 0, $"Clear flanking cell should stay 0 cost, got {providerCost[clearFlankIdx]}");

            // 4. Symmetrical giant-vs-giant and giant-vs-small melee reach
            IntVec3 nonOverlappingFlank = justOutside;
            Assert(HarmonyPatches_CombatAndHitbox.IsGiantHullInTouchRangeOfCells(
                nonOverlappingFlank, offsets, vlRig.meleeTouchRadius, fp.hitCells, fp.tightHitBounds, fp.hitCellSet),
                $"Non-overlapping flanking hull at {nonOverlappingFlank} must be in melee touch reach of giant target HitCells");
            Assert(!HarmonyPatches_CombatAndHitbox.IsGiantHullInTouchRangeOfCells(
                anchor + new IntVec3(0, 0, 40), offsets, vlRig.meleeTouchRadius, fp.hitCells, fp.tightHitBounds, fp.hitCellSet),
                "40-cell distant giant must NOT be in melee touch reach");

            int frontColZ = fp.collisionCells.Where(c => c.x == anchor.x).Max(c => c.z);
            CellRect smallTargetRect = CellRect.SingleCell(new IntVec3(anchor.x, 0, frontColZ + 1));
            Assert(HarmonyPatches_CombatAndHitbox.IsGiantHullInTouchRangeOfCells(
                anchor, offsets, vlRig.meleeTouchRadius, null, smallTargetRect),
                "Giant attacker must reach nearby small target via Hull + meleeTouchRadius");
            Assert(!HarmonyPatches_CombatAndHitbox.IsGiantHullInTouchRangeOfCells(
                anchor, offsets, vlRig.meleeTouchRadius, null, CellRect.SingleCell(new IntVec3(50, 0, 75))),
                "Giant attacker must NOT reach 25-cell distant small target");

            // 5. Parameterize start-cell scoping and 1-node async path stale-destination guard
            Assert(GiantPathingContext.ActiveParameterizeStartCell == IntVec3.Invalid,
                "ActiveParameterizeStartCell must default to IntVec3.Invalid outside ParameterizePathJob");
            var scopeOuter = GiantPathingContext.PushParameterizePawn(null, new IntVec3(12, 0, 34));
            Assert(GiantPathingContext.ActiveParameterizeStartCell == new IntVec3(12, 0, 34),
                "ActiveParameterizeStartCell should reflect outer pushed start cell");
            var scopeInner = GiantPathingContext.PushParameterizePawn(null, new IntVec3(56, 0, 78));
            Assert(GiantPathingContext.ActiveParameterizeStartCell == new IntVec3(56, 0, 78),
                "ActiveParameterizeStartCell should reflect nested inner start cell");
            GiantPathingContext.PopParameterizePawn(scopeInner);
            Assert(GiantPathingContext.ActiveParameterizeStartCell == new IntVec3(12, 0, 34),
                "Popping inner scope must restore outer start cell");
            GiantPathingContext.PopParameterizePawn(scopeOuter);
            Assert(GiantPathingContext.ActiveParameterizeStartCell == IntVec3.Invalid,
                "Popping final scope must reset ActiveParameterizeStartCell to IntVec3.Invalid");

            MethodInfo setupMovePrefix = typeof(HarmonyPatches_CollisionAndSelection).GetMethod(
                "Pawn_PathFollower_SetupMoveIntoNextCell_Prefix",
                BindingFlags.Public | BindingFlags.Static);
            Assert(setupMovePrefix != null && setupMovePrefix.ReturnType == typeof(bool),
                "Pawn_PathFollower_SetupMoveIntoNextCell_Prefix must return bool to abort stale 1-node paths before Log.Error");
        }

        private static ThingDef ParseRaceXmlThingDef(XElement tdEl)
        {
            var td = new ThingDef
            {
                defName = tdEl.Element("defName")?.Value
            };
            XElement toolsEl = tdEl.Element("tools");
            if (toolsEl != null)
            {
                td.tools = new List<Tool>();
                foreach (XElement tEl in toolsEl.Elements("li"))
                {
                    string grp = tEl.Element("linkedBodyPartsGroup")?.Value;
                    td.tools.Add(new Tool
                    {
                        label = tEl.Element("label")?.Value,
                        untranslatedLabel = tEl.Element("label")?.Value,
                        linkedBodyPartsGroup = string.IsNullOrEmpty(grp) ? null : new BodyPartGroupDef { defName = grp }
                    });
                }
            }
            XElement verbsEl = tdEl.Element("verbs");
            if (verbsEl != null)
            {
                var vList = new List<VerbProperties>();
                foreach (XElement vEl in verbsEl.Elements("li"))
                {
                    string proj = vEl.Element("defaultProjectile")?.Value;
                    vList.Add(new VerbProperties
                    {
                        verbClass = typeof(Verb_LaunchProjectile),
                        defaultProjectile = new ThingDef { defName = proj ?? "GCF_TestProjectile" }
                    });
                }
                FieldInfo verbsField = AccessTools.Field(typeof(ThingDef), "verbs");
                Assert(verbsField != null, "ThingDef.verbs field must exist via reflection");
                verbsField.SetValue(td, vList);
            }
            return td;
        }

        private static void TestMandatoryVisibleAttackAnimationsAndZeroSilentDamage()
        {
            // 1. Load all 6 playable giant rigs (Scorpio, Behemoth, Leviathan, Colossus Stages 1-3) and verify ConfigErrors() == 0
            var (scorpRig, _, _) = LoadMechScorpionFromXml();
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valsRig, _, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            var (mcRig1, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (mcRig2, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var (mcRig3, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            var (carrierRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            var (panzerRig, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");

            var allRigs = new (string label, GiantRigDef rig)[]
            {
                ("MechScorpion", scorpRig),
                ("Rathalos", rathRig),
                ("Valstrax", valsRig),
                ("MechColossus_Stage1", mcRig1),
                ("MechColossus_Stage2", mcRig2),
                ("MechColossus_Stage3", mcRig3),
                ("ProtossCarrier", carrierRig),
                ("PanzerIV", panzerRig)
            };

            foreach (var entry in allRigs)
            {
                List<string> cfgErrs = entry.rig.ConfigErrors().ToList();
                Assert(cfgErrs.Count == 0, $"ConfigErrors on rig {entry.label}: {string.Join("; ", cfgErrs)}");
            }

            // 2. Cross-validate 100% <tools>/<verbs>/<abilities> coverage across all race XMLs and MechColossus 3 stages
            (Dictionary<string, ThingDef> thingDefs, Dictionary<string, ThingDef> gunByTag, XDocument doc) ParseRaceDoc(string fileName)
            {
                XDocument doc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", fileName));
                var byDefName = new Dictionary<string, ThingDef>(StringComparer.Ordinal);
                var byWeaponTag = new Dictionary<string, ThingDef>(StringComparer.Ordinal);
                foreach (XElement tdEl in doc.Root.Elements("ThingDef"))
                {
                    ThingDef td = ParseRaceXmlThingDef(tdEl);
                    if (!string.IsNullOrEmpty(td.defName))
                    {
                        byDefName[td.defName] = td;
                    }
                    if (tdEl.Element("verbs") != null && tdEl.Element("weaponTags") != null)
                    {
                        foreach (XElement tagEl in tdEl.Element("weaponTags").Elements("li"))
                        {
                            if (!string.IsNullOrEmpty(tagEl.Value))
                            {
                                byWeaponTag[tagEl.Value] = td;
                            }
                        }
                    }
                }
                return (byDefName, byWeaponTag, doc);
            }

            var abilityByDefName = new Dictionary<string, RimWorld.AbilityDef>(StringComparer.Ordinal);
            {
                foreach (string abXmlPath in EnumerateAllMod17Files(Path.Combine("Defs", "AbilityDefs"), "*.xml"))
                {
                    XDocument abDoc = XDocument.Load(abXmlPath);
                    foreach (XElement abEl in abDoc.Root.Elements("AbilityDef"))
                    {
                        string abName = abEl.Element("defName")?.Value;
                        if (string.IsNullOrEmpty(abName)) continue;
                        var abDef = new RimWorld.AbilityDef
                        {
                            defName = abName
                        };
                        abDef.comps ??= new();
                        if (abEl.Element("comps") != null)
                        {
                            foreach (XElement compEl in abEl.Element("comps").Elements("li"))
                            {
                                string cls = compEl.Attribute("Class")?.Value ?? string.Empty;
                                if (cls.EndsWith("CompProperties_AbilityRequiresGiantBone", StringComparison.Ordinal))
                                {
                                    var req = new CompProperties_AbilityRequiresGiantBone
                                    {
                                        requireAll = ParseBool(compEl.Element("requireAll")?.Value, false),
                                        organLabel = compEl.Element("organLabel")?.Value
                                    };
                                    if (compEl.Element("requiredBoneIds") != null)
                                    {
                                        foreach (XElement bidEl in compEl.Element("requiredBoneIds").Elements("li"))
                                        {
                                            if (!string.IsNullOrWhiteSpace(bidEl.Value))
                                            {
                                                req.requiredBoneIds.Add(bidEl.Value.Trim());
                                            }
                                        }
                                    }
                                    abDef.comps.Add(req);
                                }
                                else
                                {
                                    abDef.comps.Add(new RimWorld.CompProperties_AbilityEffect());
                                }
                            }
                        }
                        abilityByDefName[abName] = abDef;
                    }
                }
            }

            RimWorld.AbilityDef ResolveTestAbilityDef(string defName)
            {
                return abilityByDefName.TryGetValue(defName, out RimWorld.AbilityDef found)
                    ? found
                    : new RimWorld.AbilityDef { defName = defName };
            }

            (List<RimWorld.AbilityDef> abilities, ThingDef gun) ExtractPawnKindCombat(XDocument doc, string raceDefName, Dictionary<string, ThingDef> gunByTag)
            {
                var abList = new List<RimWorld.AbilityDef>();
                ThingDef resolvedGun = null;
                foreach (XElement pkEl in doc.Root.Elements("PawnKindDef"))
                {
                    if (!string.Equals(pkEl.Element("race")?.Value, raceDefName, StringComparison.Ordinal))
                    {
                        continue;
                    }
                    if (pkEl.Element("abilities") != null)
                    {
                        foreach (XElement aEl in pkEl.Element("abilities").Elements("li"))
                        {
                            if (!string.IsNullOrEmpty(aEl.Value))
                            {
                                abList.Add(ResolveTestAbilityDef(aEl.Value));
                            }
                        }
                    }
                    if (pkEl.Element("weaponTags") != null)
                    {
                        foreach (XElement tEl in pkEl.Element("weaponTags").Elements("li"))
                        {
                            if (!string.IsNullOrEmpty(tEl.Value) && gunByTag.TryGetValue(tEl.Value, out ThingDef g))
                            {
                                resolvedGun = g;
                                break;
                            }
                        }
                    }
                }
                return (abList, resolvedGun);
            }

            var (rathDefs, rathGuns, rathDoc) = ParseRaceDoc("Races_Rathalos.xml");
            ThingDef rathRace = rathDefs["GCF_Rathalos"];
            var (rathAbs, rathGun) = ExtractPawnKindCombat(rathDoc, "GCF_Rathalos", rathGuns);
            Assert(rathGun == null, "Rathalos must not equip any base-Pawn weapon");
            List<string> rathErrs = rathRig.ValidateThingDefCombatAnimations(rathRace, rathAbs, rathGun, "Rathalos").ToList();
            Assert(rathErrs.Count == 0, $"Rathalos combat anim coverage errors: {string.Join("; ", rathErrs)}");

            var (scorpDefs, scorpGuns, scorpDoc) = ParseRaceDoc("Races_MechScorpion.xml");
            ThingDef scorpRace = scorpDefs["GCF_MechScorpion"];
            var (scorpAbs, scorpGun) = ExtractPawnKindCombat(scorpDoc, "GCF_MechScorpion", scorpGuns);
            Assert(scorpGun == null, "MechScorpion must not equip any base-Pawn weapon (migrated to tail_stinger partAttacks)");
            List<string> scorpErrs = scorpRig.ValidateThingDefCombatAnimations(scorpRace, scorpAbs, scorpGun, "MechScorpion").ToList();
            Assert(scorpErrs.Count == 0, $"MechScorpion combat anim coverage errors: {string.Join("; ", scorpErrs)}");

            var (vlDefs, vlGuns, vlDoc) = ParseRaceDoc("Races_Valstrax.xml");
            ThingDef vlRace = vlDefs["GCF_Valstrax"];
            var (vlAbs, vlGun) = ExtractPawnKindCombat(vlDoc, "GCF_Valstrax", vlGuns);
            Assert(vlGun == null, "Valstrax must not equip any base-Pawn weapon");
            Assert(vlAbs.Count == 5, $"Expected 5 abilities on GCF_Valstrax PawnKind, got {vlAbs.Count}");
            List<string> vlErrs = valsRig.ValidateThingDefCombatAnimations(vlRace, vlAbs, vlGun, "Valstrax").ToList();
            Assert(vlErrs.Count == 0, $"Valstrax combat anim coverage errors: {string.Join("; ", vlErrs)}");

            var (pcDefs, pcGuns, pcDoc) = ParseRaceDoc("Races_ProtossCarrier.xml");
            ThingDef pcRace = pcDefs["GCF_ProtossCarrier"];
            var (pcAbs, pcGun) = ExtractPawnKindCombat(pcDoc, "GCF_ProtossCarrier", pcGuns);
            Assert(pcGun == null, "ProtossCarrier must not equip any base-Pawn weapon (migrated to CarrierCatapult partAttacks)");
            Assert(pcAbs.Count == 2, $"Expected 2 abilities on GCF_ProtossCarrier PawnKind, got {pcAbs.Count}");
            List<string> pcErrs = carrierRig.ValidateThingDefCombatAnimations(pcRace, pcAbs, pcGun, "ProtossCarrier").ToList();
            Assert(pcErrs.Count == 0, $"ProtossCarrier combat anim coverage errors: {string.Join("; ", pcErrs)}");

            var (pzDefs, pzGuns, pzDoc) = ParseRaceDoc("Races_PanzerIV.xml");
            ThingDef pzRace = pzDefs["GCF_PanzerIV"];
            var (pzAbs, pzGun) = ExtractPawnKindCombat(pzDoc, "GCF_PanzerIV", pzGuns);
            Assert(pzGun == null, "PanzerIV must not equip any base-Pawn weapon (migrated to main_gun + bow_mg partAttacks)");
            Assert(pzAbs.Count == 1 && pzAbs[0].defName == "GCF_Ability_PanzerSprgrSalvo",
                $"Expected 1 ranged salvo ability (zero melee abilities) on GCF_PanzerIV PawnKind, got {pzAbs.Count}");
            List<string> pzErrs = panzerRig.ValidateThingDefCombatAnimations(pzRace, pzAbs, pzGun, "PanzerIV").ToList();
            Assert(pzErrs.Count == 0, $"PanzerIV combat anim coverage errors: {string.Join("; ", pzErrs)}");

            var (mcDefs, _, mcDoc) = ParseRaceDoc("Races_MechColossus.xml");
            ThingDef mcRace = mcDefs["GCF_MechColossus"];
            XElement mcRaceEl = mcDoc.Root.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_MechColossus");
            XElement phaseCompEl = mcRaceEl.Element("comps").Elements("li")
                .First(c => (c.Attribute("Class")?.Value ?? string.Empty).Contains("CompProperties_GiantPhaseTransform"));
            var mcRigByDefName = new Dictionary<string, GiantRigDef>(StringComparer.Ordinal)
            {
                [mcRig1.defName] = mcRig1,
                [mcRig2.defName] = mcRig2,
                [mcRig3.defName] = mcRig3
            };
            int validatedStages = 0;
            foreach (XElement stEl in phaseCompEl.Element("stages").Elements("li"))
            {
                string stageId = stEl.Element("stageId")?.Value;
                string rigDefName = stEl.Element("rigDef")?.Value;
                Assert(mcRigByDefName.TryGetValue(rigDefName, out GiantRigDef stageRig), $"Unknown MechColossus stage rigDef '{rigDefName}'");
                string rGunName = stEl.Element("rangedWeaponDef")?.Value;
                Assert(string.IsNullOrEmpty(rGunName), $"MechColossus stage '{stageId}' must not declare <rangedWeaponDef>");
                ThingDef stageGun = null;
                var stageAbs = new List<RimWorld.AbilityDef>();
                if (stEl.Element("stageAbilities") != null)
                {
                    foreach (XElement aEl in stEl.Element("stageAbilities").Elements("li"))
                    {
                        stageAbs.Add(ResolveTestAbilityDef(aEl.Value));
                    }
                }
                List<string> stErrs = stageRig.ValidateThingDefCombatAnimations(mcRace, stageAbs, stageGun, stageId).ToList();
                Assert(stErrs.Count == 0, $"MechColossus stage '{stageId}' combat anim errors: {string.Join("; ", stErrs)}");
                validatedStages++;
            }
            Assert(validatedStages == 3, $"Expected 3 MechColossus stages validated, got {validatedStages}");

            // Verify ConfigErrors check catches malformed looping rangedAttackAnim AND rejects base-Pawn tools/guns/unbound abilities
            var loopingRangedRig = new GiantRigDef
            {
                defName = "Test_LoopingRangedRig",
                rangedAttackAnim = new GiantAnimDef { defName = "Test_BadLoopingRanged", loop = true, durationTicks = 20f }
            };
            Assert(loopingRangedRig.ValidateThingDefCombatAnimations(scorpRace, null, null).Any(),
                "ValidateThingDefCombatAnimations must reject a looping rangedAttackAnim");
            Assert(scorpRig.ValidateThingDefCombatAnimations(new ThingDef { defName = "Test_BadBaseTools", tools = new List<Tool> { new Tool { label = "claw" } } }).Any(),
                "ValidateThingDefCombatAnimations must reject base-Pawn <tools> when <partAttacks> are present");
            Assert(scorpRig.ValidateThingDefCombatAnimations(scorpRace, null, new ThingDef { defName = "Test_BadEquippedGun" }).Any(),
                "ValidateThingDefCombatAnimations must reject equipped rangedWeaponDef when <partAttacks> are present");
            var unboundAb = new RimWorld.AbilityDef
            {
                defName = "Test_UnboundAbility"
            };
            unboundAb.comps ??= new();
            unboundAb.comps.Add(new RimWorld.CompProperties_AbilityEffect());
            Assert(scorpRig.ValidateThingDefCombatAnimations(scorpRace, new List<RimWorld.AbilityDef> { unboundAb }).Any(),
                "ValidateThingDefCombatAnimations must reject an ability without CompProperties_AbilityRequiresGiantBone");

            // 3. Verify structural validity of configured one-shot clips (loop=false, valid duration & impactTick, finite forward kinematics) without subjective motion/displacement thresholds
            Vector2 rootXZ = new Vector2(50.5f, 50.5f);
            foreach (var entry in allRigs)
            {
                GiantRigDef rig = entry.rig;
                int n = rig.SortedNodes.Length;
                var miss = new bool[n];
                var testLocal = new BoneLocalPose[n];
                var testWorld = new BoneWorldPose[n];

                var oneShotClips = new List<GiantAnimDef>();
                oneShotClips.AddRange(rig.meleeAttackAnims);
                oneShotClips.AddRange(rig.abilityAnims);
                if (rig.rangedAttackAnim != null)
                {
                    oneShotClips.Add(rig.rangedAttackAnim);
                }
                foreach (BoneNodeDef nd in rig.nodes)
                {
                    foreach (GiantPartAttackDef pa in nd.partAttacks)
                    {
                        if (pa.attackAnim != null && !oneShotClips.Contains(pa.attackAnim))
                        {
                            oneShotClips.Add(pa.attackAnim);
                        }
                    }
                }

                foreach (GiantAnimDef clip in oneShotClips)
                {
                    Assert(!clip.loop, $"{entry.label}.{clip.defName} one-shot clip must not loop");
                    Assert(clip.durationTicks > 0f, $"{entry.label}.{clip.defName} durationTicks must be > 0");
                    float imp = clip.ResolveImpactTick();
                    Assert(imp > 0f && imp <= clip.durationTicks,
                        $"{entry.label}.{clip.defName} ResolveImpactTick={imp:F1} must lie within (0, {clip.durationTicks:F1}]");

                    for (int i = 0; i < n; i++) testLocal[i] = BoneLocalPose.Identity;
                    clip.EvaluateInto(rig, imp, testLocal);
                    SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, testLocal, miss, testWorld);
                    for (int i = 0; i < n; i++)
                    {
                        Assert(!float.IsNaN(testWorld[i].jointWorldXZ.x) && !float.IsNaN(testWorld[i].jointWorldXZ.y),
                            $"NaN world pose on {entry.label}.{clip.defName} node {i}");
                    }
                }
            }

            // 5. Runtime anti-silent-damage rejection, directional 0f wrong-hemisphere gating & Harmony bool veto verification
            var comp = new CompGiantRig();
            comp.Initialize(new CompProperties_GiantRig { rigDef = scorpRig });
            Assert(!comp.TriggerAttackAnimation("nonexistent_silent_tool", false),
                "TriggerAttackAnimation must return false for unmapped melee tool (no random fallback)");
            Assert(!comp.TriggerAbilityAnimation("GCF_Ability_NonexistentSilent"),
                "TriggerAbilityAnimation must return false for unmapped ability");

            AssertNear(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal dragon maw", 180f), 0f, 1e-4f, "maw astern must be 0f");
            AssertNear(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("left boneless spine whip", 90f), 0f, 1e-4f, "left whip starbd must be 0f");
            AssertNear(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("right boneless spine whip", -90f), 0f, 1e-4f, "right whip port must be 0f");
            AssertNear(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal crucible tail halberd", 0f), 0f, 1e-4f, "tail halberd ahead must be 0f");
            AssertNear(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("GCF_PanzerFrontRamGroup|reinforced bow glacis", 180f), 0f, 1e-4f, "front ram astern must be 0f");
            AssertNear(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("GCF_PanzerRearRamGroup|reverse stern slam", 0f), 0f, 1e-4f, "rear slam ahead must be 0f");

            // Pure-ranged giant melee veto verification (MechColossus & ProtossCarrier must never allow melee)
            var pureRangedColossus = new Pawn
            {
                def = mcRace,
                kindDef = new PawnKindDef { defName = "GCF_MechColossus", canMeleeAttack = false }
            };
            Assert(!HarmonyPatches_CombatAndHitbox.CanGiantPerformMelee(pureRangedColossus),
                "CanGiantPerformMelee must return false for pure-ranged GCF_MechColossus");

            Assert(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal dragon maw", 0f) > 1f,
                "maw ahead must receive positive directional multiplier (> 1f)");
            Assert(HarmonyPatches_CombatAndHitbox.ComputeDirectionalToolMultiplier("abyssal crucible tail halberd", 180f) > 1f,
                "tail halberd astern must receive positive directional multiplier (> 1f)");

            foreach (string prefixName in new[]
            {
                "Verb_MeleeAttack_TryCastShot_Prefix",
                "Verb_LaunchProjectile_WarmupComplete_Prefix",
                "Ability_Activate_Prefix"
            })
            {
                MethodInfo mi = typeof(HarmonyPatches_CombatAndHitbox).GetMethod(prefixName, BindingFlags.Public | BindingFlags.Static);
                Assert(mi != null && mi.ReturnType == typeof(bool),
                    $"HarmonyPatches_CombatAndHitbox.{prefixName} must exist as public static bool");
            }
        }

        private static void TestRimWorldThickSilhouetteOutlineStandard()
        {
            var rigTargets = new (string RigXml, string AnimXml, string DefName)[]
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV"),
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos"),
                ("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax"),
            };

            // Resolve textures across framework + sub-mods
            var checkedCache = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

            foreach (var target in rigTargets)
            {
                var (rig, _, _) = LoadRigFromXml(target.RigXml, target.AnimXml, target.DefName);
                var strokes = new List<int>();
                var checkedRigTex = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                void CheckTex(string id, string texPath, string silTexPath, bool openBottom)
                {
                    if (string.IsNullOrEmpty(texPath)) return;
                    string cacheKey = $"{texPath}|{silTexPath ?? ""}|{openBottom}";
                    if (!checkedRigTex.Add(cacheKey)) return;

                    if (!checkedCache.TryGetValue(cacheKey, out int strokePx))
                    {
                        string pngPath = ResolveMod17Path("Textures", texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                        Assert(File.Exists(pngPath), $"Missing rig texture for outline audit: {pngPath}");
                        byte[] rgba = DecodePngRgbaTopDown(pngPath, out int w, out int h);
                        if (!string.IsNullOrEmpty(silTexPath))
                        {
                            float[] plateDist = ComputeInwardChamferDistances(rgba, w, h, openBottom);
                            var edgeLums = new List<float>();
                            var deepLums = new List<float>();
                            for (int pi = 0; pi < plateDist.Length; pi++)
                            {
                                if (rgba[pi * 4 + 3] < 180) continue;
                                float pd = plateDist[pi];
                                float pl = 0.299f * rgba[pi * 4] + 0.587f * rgba[pi * 4 + 1] + 0.114f * rgba[pi * 4 + 2];
                                if (pd >= 1.0f && pd <= 3.5f) edgeLums.Add(pl);
                                else if (pd >= 12.0f) deepLums.Add(pl);
                            }
                            edgeLums.Sort();
                            deepLums.Sort();
                            float deepMed = deepLums.Count > 0 ? deepLums[deepLums.Count / 2] : 80f;
                            float edgeMed = edgeLums.Count > 0 ? edgeLums[edgeLums.Count / 2] : deepMed;
                            if (deepMed >= 52f && target.DefName != "GCF_Rig_Rathalos")
                            {
                                int plateStroke = MeasureOutlineStrokePxFromDist(rgba, plateDist);
                                Assert(plateStroke == 0,
                                    $"Union hull plate {target.DefName}/{id} ({texPath}) must have 0px internal/plate outline, got {plateStroke}px");
                                double intBlack = MeasureInteriorBlackRatioFromDist(rgba, plateDist, out int deepCnt);
                                Assert(deepCnt < 200 || intBlack <= 0.008,
                                    $"Union hull plate {target.DefName}/{id} ({texPath}) interior black ({intBlack:P2}) > 0.8%");
                            }
                            else
                            {
                                // Volcanic-soot / dark-palette lossless plates naturally have lum 19..45 without luminance clamping;
                                // verify there is no dark perimeter outline ring darker than the plate interior!
                                Assert((deepMed - edgeMed) < 18f || edgeMed > 26f,
                                    $"Dark-palette union hull plate {target.DefName}/{id} ({texPath}) has perimeter outline ring (edgeMed={edgeMed:F1}, deepMed={deepMed:F1})");
                            }

                            string silPath = ResolveMod17Path("Textures", silTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                            Assert(File.Exists(silPath), $"Missing silhouette texture for outline audit: {silPath}");
                            byte[] silRgba = DecodePngRgbaTopDown(silPath, out int sw, out int sh);
                            Assert(sw == w && sh == h,
                                $"Silhouette dimensions {sw}x{sh} mismatch plate {w}x{h} on {texPath}");
                            byte[] compRgba = new byte[w * h * 4];
                            for (int p = 0; p < compRgba.Length; p += 4)
                            {
                                float pa = rgba[p + 3] / 255f;
                                float sa = silRgba[p + 3] / 255f;
                                float outA = pa + sa * (1f - pa);
                                if (outA <= 1e-4f) continue;
                                float inv = 1f / outA;
                                compRgba[p + 0] = (byte)Math.Clamp(MathF.Round((rgba[p + 0] * pa + silRgba[p + 0] * sa * (1f - pa)) * inv), 0f, 255f);
                                compRgba[p + 1] = (byte)Math.Clamp(MathF.Round((rgba[p + 1] * pa + silRgba[p + 1] * sa * (1f - pa)) * inv), 0f, 255f);
                                compRgba[p + 2] = (byte)Math.Clamp(MathF.Round((rgba[p + 2] * pa + silRgba[p + 2] * sa * (1f - pa)) * inv), 0f, 255f);
                                compRgba[p + 3] = (byte)Math.Clamp(MathF.Round(outA * 255f), 0f, 255f);
                            }
                            strokePx = MeasureOutlineStrokePx(compRgba, w, h, openBottom);
                        }
                        else
                        {
                            strokePx = MeasureOutlineStrokePx(rgba, w, h, openBottom);
                        }
                        checkedCache[cacheKey] = strokePx;
                    }

                    strokes.Add(strokePx);
                    Assert(strokePx >= 6,
                        $"Outline too thin on {target.DefName}/{id} ({texPath}): strokePx={strokePx} < 6");
                }

                foreach (BoneNodeDef node in rig.SortedNodes)
                {
                    CheckTex(node.nodeId, node.texPath, node.silhouetteTexPath, openBottom: false);
                    CheckTex($"{node.nodeId}[East]", node.eastVariant?.texPath, node.eastVariant?.silhouetteTexPath ?? node.silhouetteTexPath, openBottom: false);
                    CheckTex($"{node.nodeId}[West]", node.westVariant?.texPath, node.westVariant?.silhouetteTexPath ?? node.silhouetteTexPath, openBottom: false);
                }
                if (rig.softWhips != null)
                {
                    foreach (SoftWhipDef sw in rig.softWhips)
                    {
                        CheckTex(sw.whipId, sw.texPath, null, openBottom: true);
                    }
                }

                double meanStroke = strokes.Average();
                int minStroke = strokes.Min();
                Console.WriteLine($"       -> {target.DefName}: checked={strokes.Count} textures, minOutline={minStroke}px, meanOutline={meanStroke:F2}px");
                Assert(meanStroke >= 8.0,
                    $"Rig {target.DefName} mean outer outline ({meanStroke:F2}px) must be >= 8.0px");
            }

            // Verify lineless unstroked-facet interior compliance (outer silhouette black ONLY, <= 1% black,
            // <= 4.5% thin valley seams of ANY color, >= 6.5% clean tonal facet steps) using synthetic sprites
            // and verified .verify/lineless_verify outputs.
            int sSize = 200;
            byte[] linelessBuf = new byte[sSize * sSize * 4];
            for (int y = 0; y < sSize; y++)
            {
                for (int x = 0; x < sSize; x++)
                {
                    int dx = x - 100;
                    int dy = y - 100;
                    float r = MathF.Sqrt(dx * dx + dy * dy);
                    if (r > 70f) continue;
                    int p = (y * sSize + x) * 4;
                    bool onBorder = r >= 60f;
                    byte cR, cG, cB;
                    if (onBorder)
                    {
                        cR = 20; cG = 22; cB = 26;
                    }
                    else if (x < 76)
                    {
                        cR = 242; cG = 246; cB = 252;
                    }
                    else if (x < 92)
                    {
                        cR = 212; cG = 218; cB = 228;
                    }
                    else if (x < 108)
                    {
                        cR = 182; cG = 190; cB = 202;
                    }
                    else if (x < 124)
                    {
                        cR = 152; cG = 160; cB = 174;
                    }
                    else
                    {
                        cR = 122; cG = 130; cB = 144;
                    }
                    linelessBuf[p + 0] = cR;
                    linelessBuf[p + 1] = cG;
                    linelessBuf[p + 2] = cB;
                    linelessBuf[p + 3] = 255;
                }
            }
            float[] synthDist = ComputeInwardChamferDistances(linelessBuf, sSize, sSize, openBottom: false);
            int synthStroke = MeasureOutlineStrokePxFromDist(linelessBuf, synthDist);
            double synthIntBlack = MeasureInteriorBlackRatioFromDist(linelessBuf, synthDist, out int synthIntCnt);
            double synthValleySeam = MeasureInteriorValleySeamAndFacetRatioFromDist(
                linelessBuf, synthDist, sSize, sSize, out _, out double synthCleanFacet);
            Assert(synthStroke >= 8 && synthIntCnt > 500 && synthIntBlack <= 0.001 && synthValleySeam == 0.0 && synthCleanFacet >= 0.03,
                $"Synthetic multi-facet lineless sprite failed (stroke={synthStroke}, intBlack={synthIntBlack:P2}, valleySeam={synthValleySeam:P2}, cleanFacet={synthCleanFacet:P2})");

            byte[] seamedBuf = (byte[])linelessBuf.Clone();
            for (int y = 97; y <= 103; y++)
            {
                for (int x = 45; x <= 155; x++)
                {
                    int p = (y * sSize + x) * 4;
                    seamedBuf[p + 0] = 20;
                    seamedBuf[p + 1] = 18;
                    seamedBuf[p + 2] = 24;
                }
            }
            double seamedIntBlack = MeasureInteriorBlackRatioFromDist(seamedBuf, synthDist, out _);
            Assert(seamedIntBlack > 0.02, $"Interior seam detector must catch injected black line (>2%), got {seamedIntBlack:P2}");

            byte[] greySeamedBuf = (byte[])linelessBuf.Clone();
            for (int y = 99; y <= 101; y++)
            {
                for (int x = 45; x <= 155; x++)
                {
                    int p = (y * sSize + x) * 4;
                    greySeamedBuf[p + 0] = 70;
                    greySeamedBuf[p + 1] = 78;
                    greySeamedBuf[p + 2] = 92;
                }
            }
            double greyIntBlack = MeasureInteriorBlackRatioFromDist(greySeamedBuf, synthDist, out _);
            double greyValleySeam = MeasureInteriorValleySeamAndFacetRatioFromDist(
                greySeamedBuf, synthDist, sSize, sSize, out _, out _);
            Assert(greyIntBlack == 0.0 && greyValleySeam > 0.02,
                $"Grey valley-seam detector must catch 3px slate dividing lines even when intBlack==0 (intBlack={greyIntBlack:P2}, valleySeam={greyValleySeam:P2})");

            foreach (string relLineless in new[] { "hull_512.png", "turret_512.png" })
            {
                string linelessPath = Path.Combine(ModRoot, ".verify", "lineless_verify", relLineless);
                if (!File.Exists(linelessPath)) continue;
                byte[] rgba = DecodePngRgbaTopDown(linelessPath, out int lw, out int lh);
                float[] lDist = ComputeInwardChamferDistances(rgba, lw, lh, openBottom: false);
                int lStroke = MeasureOutlineStrokePxFromDist(rgba, lDist);
                double lBlack = MeasureInteriorBlackRatioFromDist(rgba, lDist, out int lIntCnt);
                double lSeam = MeasureInteriorValleySeamAndFacetRatioFromDist(rgba, lDist, lw, lh, out _, out double lFacet);
                Console.WriteLine(
                    $"       -> LinelessProof/{relLineless}: outline={lStroke}px, intBlack={lBlack * 100.0:F2}%, valleySeam={lSeam * 100.0:F2}%, cleanFacet={lFacet * 100.0:F2}% ({lIntCnt} deep px)");
                Assert(lStroke >= 8, $"Lineless proof {relLineless} outer outline ({lStroke}px) must be >= 8px");
                Assert(lIntCnt < 200 || lBlack <= 0.01,
                    $"Lineless proof {relLineless} interior black ratio ({lBlack * 100.0:F2}%) must be <= 1.0%");
                Assert(lIntCnt < 200 || lSeam <= 0.045,
                    $"Lineless proof {relLineless} interior valley-seam ratio ({lSeam * 100.0:F2}%) must be <= 4.5%");
                Assert(lIntCnt < 200 || lFacet >= 0.065,
                    $"Lineless proof {relLineless} clean tonal-facet ratio ({lFacet * 100.0:F2}%) must be >= 6.5%");
            }
        }

        private static void TestProtossCarrierRigAndInterceptorSquadron()
        {
            var (rig, masks, anims) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            Assert(rig.SortedNodes.Length == 12, $"Expected 12 bones in GCF_Rig_ProtossCarrier, got {rig.SortedNodes.Length}");
            Assert(masks.Length == 12, $"Expected 12 alpha masks, got {masks.Length}");
            Assert(rig.ConfigErrors().Count() == 0, "GCF_Rig_ProtossCarrier must have 0 ConfigErrors");

            // 1. Verify lineless flat-vector interior (<= 1.0% black) + bold RimWorld outer silhouette (>= 8px) across all Carrier + Interceptor PNGs
            string carrierTexDir = ResolveMod17Path("Textures", "Things", "Pawn", "GiantCreature", "ProtossCarrier");
            string[] expectedPngs =
            {
                "CarrierHull.png", "CommandCrest.png", "AftThrusterCore.png",
                "ProwArmLeft.png", "ProwArmRight.png",
                "HangarBayLeft.png", "HangarBayRight.png",
                "HangarDoorLeft.png", "HangarDoorRight.png",
                "KhaydarinCore.png", "StabilizerFinLeft.png", "StabilizerFinRight.png",
                "Interceptor.png"
            };
            foreach (string png in expectedPngs)
            {
                string full = Path.Combine(carrierTexDir, png);
                Assert(File.Exists(full), $"Missing ProtossCarrier PNG: {full}");
                byte[] rgba = DecodePngRgbaTopDown(full, out int w, out int h);
                Assert(w == 512 && h == 512, $"Expected 512x512 on {png}, got {w}x{h}");
                float[] dist = ComputeInwardChamferDistances(rgba, w, h, openBottom: false);
                int stroke = MeasureOutlineStrokePxFromDist(rgba, dist);
                double intBlack = MeasureInteriorBlackRatioFromDist(rgba, dist, out int deepCnt);
                Assert(stroke >= 8, $"{png} outline stroke ({stroke}px) must be >= 8px");
                Assert(deepCnt < 200 || intBlack <= 0.01, $"{png} interior black ({intBlack * 100.0:F2}%) must be <= 1.0%");
            }

            foreach (string uiIcon in new[] { "CarrierScrambleInterceptors.png", "CarrierRecallInterceptors.png" })
            {
                string iconPath = ResolveMod17Path("Textures", "UI", "Abilities", uiIcon);
                Assert(File.Exists(iconPath), $"Missing Carrier UI ability icon: {iconPath}");
            }

            // 2. Verify parent-child layerOffset >= 0.5f, dynamic multi-cell footprint, and cascading hangar bay severing
            foreach (BoneNodeDef node in rig.SortedNodes)
            {
                if (node.parentRuntimeIndex >= 0)
                {
                    BoneNodeDef parent = rig.SortedNodes[node.parentRuntimeIndex];
                    float delta = MathF.Abs(parent.layerOffset - node.layerOffset);
                    Assert(delta + 1e-4f >= 0.5f, $"Parent-child layerOffset delta too small on {parent.nodeId}->{node.nodeId}: {delta:F2}");
                }
            }

            int n = rig.SortedNodes.Length;
            var localPoses = Enumerable.Repeat(BoneLocalPose.Identity, n).ToArray();
            var missing = new bool[n];
            var worldPoses = new BoneWorldPose[n];
            var footprint = new GiantFootprintData();
            Vector2 carrierXZ = new Vector2(50.5f, 50.5f);
            IntVec3 centerCell = new IntVec3(50, 0, 50);
            IntVec3 mapSize = new IntVec3(200, 1, 200);

            SkeletalKinematics.SolveWorldPoses(rig, carrierXZ, 0f, localPoses, missing, worldPoses);
            footprint.Rebuild(rig, worldPoses, masks, centerCell, mapSize);
            int fullHitCells = footprint.hitCells.Count;
            int fullColCells = footprint.collisionCells.Count;
            Assert(fullHitCells >= 38, $"Expected Carrier full HitCells >= 38, got {fullHitCells}");
            Assert(fullColCells >= 12, $"Expected Carrier full CollisionCells >= 12, got {fullColCells}");

            Assert(rig.TryGetNodeIndex("hangar_bay_left", out int leftBayIdx), "Missing hangar_bay_left");
            Assert(rig.TryGetNodeIndex("hangar_door_left", out int leftDoorIdx), "Missing hangar_door_left");
            Assert(rig.TryGetNodeIndex("hangar_bay_right", out int rightBayIdx), "Missing hangar_bay_right");

            missing[leftBayIdx] = true;
            SkeletalKinematics.SolveWorldPoses(rig, carrierXZ, 0f, localPoses, missing, worldPoses);
            footprint.Rebuild(rig, worldPoses, masks, centerCell, mapSize);
            Assert(!footprint.bonePoses[leftBayIdx].visible, "Severed hangar_bay_left must be hidden");
            Assert(!footprint.bonePoses[leftDoorIdx].visible, "Child hangar_door_left must cascade-hide when hangar_bay_left is severed");
            Assert(footprint.hitCells.Count < fullHitCells, $"Severing hangar_bay_left must contract HitCells ({footprint.hitCells.Count} < {fullHitCells})");

            // 3. Verify 8-Interceptor Graviton Catapult launch -> 360-deg banking strafe attack -> twin beam salvos -> recall -> dock loop
            missing[leftBayIdx] = false;
            SkeletalKinematics.SolveWorldPoses(rig, carrierXZ, 0f, localPoses, missing, worldPoses);
            footprint.Rebuild(rig, worldPoses, masks, centerCell, mapSize);
            Vector2 leftBayWorld = footprint.bonePoses[leftBayIdx].UVToWorldXZ(216f / 512f, 1f - 224f / 512f);
            Vector2 rightBayWorld = footprint.bonePoses[rightBayIdx].UVToWorldXZ(296f / 512f, 1f - 224f / 512f);
            Assert(leftBayWorld.x < carrierXZ.x && rightBayWorld.x > carrierXZ.x,
                $"Port/Starboard launch sockets must flank hull centerline: left={leftBayWorld}, right={rightBayWorld}");

            var squadron = new InterceptorKinematicState[8];
            for (int i = 0; i < 8; i++)
            {
                bool port = (i & 1) == 0;
                squadron[i] = new InterceptorKinematicState
                {
                    State = InterceptorFlightState.Launching,
                    WorldXZ = port ? leftBayWorld : rightBayWorld,
                    HeadingDeg = port ? -18f : 18f,
                    SpeedCellsPerSec = 17.5f,
                    CooldownTicksLeft = 4 + (i % 3) * 2,
                    OrbitDirectionSign = port ? -1 : 1
                };
            }

            Vector2 enemyTargetXZ = new Vector2(52.0f, 72.5f); // 22 cells North
            int totalTwinSalvos = 0;
            float peakBankDeg = 0f;
            float minTargetDist = float.MaxValue;

            // Run 220 ticks of active dogfight assault
            for (int tick = 0; tick < 220; tick++)
            {
                for (int i = 0; i < 8; i++)
                {
                    Vector2 homeXZ = (i & 1) == 0 ? leftBayWorld : rightBayWorld;
                    squadron[i].Step(
                        hangarSocketXZ: homeXZ,
                        carrierHeadingDeg: 0f,
                        hasValidTarget: true,
                        targetXZ: enemyTargetXZ,
                        recallOrdered: false,
                        maxLeashRadius: 40f,
                        baseCruiseSpeed: 16.5f,
                        speedMultiplier: 1.0f,
                        out bool firedSalvo);
                    if (firedSalvo) totalTwinSalvos++;
                    float bank = MathF.Abs(squadron[i].BankDeg);
                    if (bank > peakBankDeg) peakBankDeg = bank;
                    float dist = (squadron[i].WorldXZ - enemyTargetXZ).magnitude;
                    if (dist < minTargetDist) minTargetDist = dist;
                }
            }

            Assert(totalTwinSalvos >= 8, $"Expected 8-Interceptor squadron to fire >= 8 twin salvos (16 bolts), got {totalTwinSalvos}");
            Assert(squadron.All(s => s.TotalShotsFired >= 2), "Every Interceptor in the 8-plane squadron must fire at least one twin-beam salvo");
            Assert(peakBankDeg >= 8f, $"Expected banking dogfight turns >= 8 deg, got {peakBankDeg:F1} deg");
            Assert(minTargetDist <= 8.5f, $"Expected Interceptors to close within strafing range (<= 8.5 cells), min={minTargetDist:F2}");

            // Issue Fleet Recall while Carrier itself translates forward slightly, and verify all 8 Interceptors return & dock
            Vector2 movedLeftBay = leftBayWorld + new Vector2(0.8f, 3.2f);
            Vector2 movedRightBay = rightBayWorld + new Vector2(0.8f, 3.2f);
            int dockedCount = 0;
            for (int tick = 0; tick < 180 && dockedCount < 8; tick++)
            {
                for (int i = 0; i < 8; i++)
                {
                    if (squadron[i].State == InterceptorFlightState.Docked)
                    {
                        continue;
                    }
                    Vector2 homeXZ = (i & 1) == 0 ? movedLeftBay : movedRightBay;
                    squadron[i].Step(
                        hangarSocketXZ: homeXZ,
                        carrierHeadingDeg: 0f,
                        hasValidTarget: true,
                        targetXZ: enemyTargetXZ,
                        recallOrdered: true,
                        maxLeashRadius: 40f,
                        baseCruiseSpeed: 16.5f,
                        speedMultiplier: 1.15f,
                        out _);
                    if (squadron[i].ReadyToDock && squadron[i].State == InterceptorFlightState.Docked)
                    {
                        dockedCount++;
                    }
                }
            }
            Assert(dockedCount == 8, $"Expected all 8 recalled Interceptors to return and dock cleanly into hangar bays, docked={dockedCount}/8");

            // 4. Verify XML Defs, Biotech gestation recipe/patch, and ChineseSimplified translations exist
            Assert(File.Exists(ResolveMod17Path("Defs", "Bodies", "Bodies_ProtossCarrier.xml")), "Missing Bodies_ProtossCarrier.xml");
            Assert(File.Exists(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_ProtossCarrier.xml")), "Missing Abilities_ProtossCarrier.xml");
            Assert(File.Exists(ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_ProtossCarrier.xml")), "Missing ThinkTrees_ProtossCarrier.xml");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Defs", "RecipeDefs", "Recipes_ProtossCarrier.xml"))), "ProtossCarrier must be DevMode-only");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Patches", "Patch_Biotech_ProtossCarrier.xml"))), "ProtossCarrier must be DevMode-only");
            Assert(File.Exists(ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "ThingDef", "Races_ProtossCarrier.xml")), "Missing ChineseSimplified ThingDef translation");
            Console.WriteLine($"       -> ProtossCarrier verified: HitCells={fullHitCells}, CollisionCells={fullColCells}, Salvos={totalTwinSalvos}, Docked={dockedCount}/8");
        }

        private static void TestCustomPartMuzzlesMultiBarrelEmittersAndCalibration()
        {
            Vector2 rootXZ = new Vector2(60.5f, 60.5f);

            // 1. MechScorpion: verify tail_stinger pixel (256, 404) + muzzleAngleOffset=180 projects forward overhead across all 4 burst shots
            var (scRig, _, scAnims) = LoadMechScorpionFromXml();
            Assert(scRig.ConfigErrors().Count() == 0, $"GCF_Rig_MechScorpion ConfigErrors: {string.Join("; ", scRig.ConfigErrors())}");
            Assert(scRig.TryGetNodeIndex("tail_stinger", out int stingerIdx), "Missing tail_stinger on MechScorpion");
            BoneNodeDef stingerDef = scRig.SortedNodes[stingerIdx];
            AssertNear(stingerDef.muzzlePixel.x, 256f, 0.5f, "MechScorpion tail_stinger muzzlePixel.x");
            AssertNear(stingerDef.muzzlePixel.y, 404f, 1.0f, "MechScorpion tail_stinger muzzlePixel.y (bottom tip of TailStingerTip.png)");
            AssertNear(stingerDef.muzzleAngleOffset, 180f, 0.1f, "MechScorpion tail_stinger muzzleAngleOffset must be 180 deg");

            GiantWeaponEmitterDef scEmitter = GiantMuzzleResolver.MatchEmitter(scRig, weaponDefName: "GCF_Gun_PlasmaTailPod");
            Assert(scEmitter != null && scEmitter.emitterId == "tail_plasma_stinger", "Expected tail_plasma_stinger emitter on MechScorpion");

            GiantAnimDef rangedTailClip = scAnims["GCF_Anim_MechScorpion_RangedTail"];
            var scLocal = new BoneLocalPose[scRig.SortedNodes.Length];
            var scMissing = new bool[scRig.SortedNodes.Length];
            var scWorld = new BoneWorldPose[scRig.SortedNodes.Length];

            float[] burstShotTicks = { 12f, 21f, 30f, 39f };
            for (int i = 0; i < burstShotTicks.Length; i++)
            {
                float t = burstShotTicks[i];
                rangedTailClip.EvaluateInto(scRig, t, scLocal);
                // Facing East (90 deg)
                SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, scLocal, scMissing, scWorld);
                int cursor = 0;
                bool ok = GiantMuzzleResolver.TryResolveNextShotFromPoses(
                    scRig, scWorld, scEmitter, ref cursor, advanceCursor: true, 1.0f,
                    bid => scRig.TryGetNodeIndex(bid, out int idx) && scWorld[idx].visible,
                    out GiantMuzzleShotInfo shot);
                Assert(ok, $"MechScorpion burst shot #{i + 1} @ tick={t} failed to resolve muzzle");
                Assert(shot.BoneId == "tail_stinger", $"Expected tail_stinger muzzle, got {shot.BoneId}");
                Assert(shot.WorldPos.x > scWorld[stingerIdx].jointWorldXZ.x + 0.6f,
                    $"Facing East @ tick={t}, stinger_tip muzzle ({shot.WorldPos.x:F2}) must project forward (+X) ahead of tail_stinger joint ({scWorld[stingerIdx].jointWorldXZ.x:F2})");
                Assert(Mathf.Abs(Mathf.DeltaAngle(90f, shot.WorldAngleDeg)) <= 16f,
                    $"Facing East @ tick={t}, stinger_tip worldAngle ({shot.WorldAngleDeg:F1}) must point forward (~90 deg), not backward");
            }

            // Severing tail_seg3 cascades to hide tail_stinger and disarms the weapon emitter
            scRig.TryGetNodeIndex("tail_seg3", out int seg3Idx);
            scMissing[seg3Idx] = true;
            SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, scLocal, scMissing, scWorld);
            Assert(!GiantMuzzleResolver.IsEmitterOperational(scRig, scEmitter, bid => scRig.TryGetNodeIndex(bid, out int idx) && scWorld[idx].visible),
                "Severing tail_seg3 must disarm MechScorpion tail_plasma_stinger emitter");

            // 2. MechColossus Stage 2: Twin Plasma Accelerator Rails alternate Left <-> Right (not command_head center) + Thermal Lens ability socket
            var (mcRig2, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            Assert(mcRig2.ConfigErrors().Count() == 0, $"Stage2 ConfigErrors: {string.Join("; ", mcRig2.ConfigErrors())}");
            GiantWeaponEmitterDef s2WeaponEm = GiantMuzzleResolver.MatchEmitter(mcRig2, weaponDefName: "GCF_Gun_MechTwinPlasmaLance");
            Assert(s2WeaponEm != null && s2WeaponEm.fireMode == GiantEmitterFireMode.Alternating && s2WeaponEm.barrels.Count == 2,
                "Stage2 GCF_Gun_MechTwinPlasmaLance must bind to 2-barrel Alternating emitter");

            var s2Local = Enumerable.Repeat(BoneLocalPose.Identity, mcRig2.SortedNodes.Length).ToArray();
            var s2Missing = new bool[mcRig2.SortedNodes.Length];
            var s2World = new BoneWorldPose[mcRig2.SortedNodes.Length];
            SkeletalKinematics.SolveWorldPoses(mcRig2, rootXZ, 0f, s2Local, s2Missing, s2World);

            int s2Cursor = 0;
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(mcRig2, s2World, s2WeaponEm, ref s2Cursor, true, 1f, _ => true, out GiantMuzzleShotInfo s2Shot1), "Stage2 shot 1 failed");
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(mcRig2, s2World, s2WeaponEm, ref s2Cursor, true, 1f, _ => true, out GiantMuzzleShotInfo s2Shot2), "Stage2 shot 2 failed");
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(mcRig2, s2World, s2WeaponEm, ref s2Cursor, true, 1f, _ => true, out GiantMuzzleShotInfo s2Shot3), "Stage2 shot 3 failed");
            Assert(s2Shot1.BoneId == "plasma_rail_left" && s2Shot2.BoneId == "plasma_rail_right" && s2Shot3.BoneId == "plasma_rail_left",
                $"Expected Left -> Right -> Left alternation on Stage2 plasma rails, got {s2Shot1.BoneId} -> {s2Shot2.BoneId} -> {s2Shot3.BoneId}");
            Assert(s2Shot1.WorldPos.x < rootXZ.x - 0.35f && s2Shot2.WorldPos.x > rootXZ.x + 0.35f && s2Shot1.WorldPos.z > rootXZ.y + 2.5f,
                $"Stage2 twin plasma muzzles must sit laterally port/starboard and ahead of chassis: L={s2Shot1.WorldPos}, R={s2Shot2.WorldPos}");

            GiantWeaponEmitterDef s2ThermalEm = GiantMuzzleResolver.MatchEmitter(mcRig2, abilityDefName: "GCF_Ability_MechThermalBeamSweep", allowDefaultFallback: false);
            Assert(s2ThermalEm != null, "Stage2 thermal sweep ability emitter missing");
            var thermalShots = new List<GiantMuzzleShotInfo>();
            Assert(GiantMuzzleResolver.CollectAllIntactBarrelShots(mcRig2, s2World, s2ThermalEm, 1f, _ => true, thermalShots) == 1 &&
                   thermalShots[0].BoneId == "command_head" && thermalShots[0].SocketId == "thermal_lens",
                "Stage2 thermal sweep must anchor to command_head:thermal_lens");

            // 3. MechColossus Stage 3: Twin Orbital Railguns alternate Left <-> Right, survive single-barrel severing, disarm on dual severing
            var (mcRig3, _, mcAnims3) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            Assert(mcRig3.ConfigErrors().Count() == 0, $"Stage3 ConfigErrors: {string.Join("; ", mcRig3.ConfigErrors())}");
            GiantWeaponEmitterDef s3RailEm = GiantMuzzleResolver.MatchEmitter(mcRig3, weaponDefName: "GCF_Gun_MechTwinRailgun");
            Assert(s3RailEm != null && s3RailEm.barrels.Count == 2, "Stage3 GCF_Gun_MechTwinRailgun must bind to twin_orbital_railguns");

            var s3Local = Enumerable.Repeat(BoneLocalPose.Identity, mcRig3.SortedNodes.Length).ToArray();
            var s3Missing = new bool[mcRig3.SortedNodes.Length];
            var s3World = new BoneWorldPose[mcRig3.SortedNodes.Length];
            SkeletalKinematics.SolveWorldPoses(mcRig3, rootXZ, 0f, s3Local, s3Missing, s3World);

            int s3Cursor = 0;
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(mcRig3, s3World, s3RailEm, ref s3Cursor, true, 1f, _ => true, out GiantMuzzleShotInfo rShotL), "Stage3 left railgun shot failed");
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(mcRig3, s3World, s3RailEm, ref s3Cursor, true, 1f, _ => true, out GiantMuzzleShotInfo rShotR), "Stage3 right railgun shot failed");
            Assert(rShotL.BoneId == "railgun_barrel_left" && rShotR.BoneId == "railgun_barrel_right",
                $"Expected left then right railgun barrel, got {rShotL.BoneId} / {rShotR.BoneId}");
            Assert(rShotR.WorldPos.x - rShotL.WorldPos.x > 3.0f && rShotL.WorldPos.z > rootXZ.y + 4.5f,
                $"Stage3 twin railgun muzzles must project far forward with wide dorsal separation: L={rShotL.WorldPos}, R={rShotR.WorldPos}");

            // Sever left railgun mount -> weapon remains operational and automatically routes all shots to right railgun!
            mcRig3.TryGetNodeIndex("railgun_mount_left", out int leftMountIdx);
            s3Missing[leftMountIdx] = true;
            SkeletalKinematics.SolveWorldPoses(mcRig3, rootXZ, 0f, s3Local, s3Missing, s3World);
            Func<string, bool> s3IntactFn = bid => mcRig3.TryGetNodeIndex(bid, out int idx) && s3World[idx].visible;
            Assert(GiantMuzzleResolver.IsEmitterOperational(mcRig3, s3RailEm, s3IntactFn),
                "Stage3 twin railguns must remain operational when only left railgun is severed");
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(mcRig3, s3World, s3RailEm, ref s3Cursor, true, 1f, s3IntactFn, out GiantMuzzleShotInfo fallbackShot) &&
                   fallbackShot.BoneId == "railgun_barrel_right",
                $"Severing left railgun must route shots to intact railgun_barrel_right, got {fallbackShot.BoneId}");

            // Sever right railgun mount as well -> weapon disarms completely!
            mcRig3.TryGetNodeIndex("railgun_mount_right", out int rightMountIdx);
            s3Missing[rightMountIdx] = true;
            SkeletalKinematics.SolveWorldPoses(mcRig3, rootXZ, 0f, s3Local, s3Missing, s3World);
            Assert(!GiantMuzzleResolver.IsEmitterOperational(mcRig3, s3RailEm, s3IntactFn),
                "Stage3 twin railguns must disarm when both railgun mounts are severed");

            // Orbital Nova Salvo emitter shrinks gracefully from 5 intact ports down to remaining intact ports
            GiantWeaponEmitterDef novaEm = GiantMuzzleResolver.MatchEmitter(mcRig3, abilityDefName: "GCF_Ability_MechOrbitalStrikeNova", allowDefaultFallback: false);
            var novaShots = new List<GiantMuzzleShotInfo>();
            int remainingNovaPorts = GiantMuzzleResolver.CollectAllIntactBarrelShots(mcRig3, s3World, novaEm, 1f, s3IntactFn, novaShots);
            Assert(remainingNovaPorts == 3, $"With both dorsal railguns severed, orbital_nova_emitters should collect 3 remaining ports (bridge + 2 wing pods), got {remainingNovaPorts}");

            // Verify RailgunSalvo anim events align to left@8 and right@16 with useBoneMuzzle=true
            GiantAnimDef railSalvoAnim = mcAnims3["GCF_Anim_MechStage3_RailgunSalvo"];
            Assert(railSalvoAnim.events.Count == 2 && railSalvoAnim.events[0].useBoneMuzzle && railSalvoAnim.events[1].useBoneMuzzle,
                "GCF_Anim_MechStage3_RailgunSalvo must trigger 2 muzzle-aligned events for left and right barrels");

            // 4. ProtossCarrier: hangar catapult sockets + ActiveGiantVerbShotContext sub-unit isolation (Interceptors never hijacked)
            var (pcRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            Assert(pcRig.ConfigErrors().Count() == 0, $"Carrier ConfigErrors: {string.Join("; ", pcRig.ConfigErrors())}");
            GiantWeaponEmitterDef carrierEm = GiantMuzzleResolver.MatchEmitter(pcRig, weaponDefName: "GCF_Gun_CarrierGravitonCatapult");
            Assert(carrierEm != null && !carrierEm.spawnMuzzleVfxOnLaunch && carrierEm.barrels.Count == 2,
                "ProtossCarrier catapult emitter must bind port & starboard hangar bays with spawnMuzzleVfxOnLaunch=false");
            Assert(!ActiveGiantVerbShotContext.TryConsumeForLauncher(null, out _, out _, out _) &&
                   !ActiveGiantVerbShotContext.TryGetActiveFlashRedirect(out _),
                "Outside Verb_LaunchProjectile.TryCastShot scope, ActiveGiantVerbShotContext must never hijack external/Interceptor Projectile.Launch calls");

            Console.WriteLine($"       -> Custom Muzzles Verified: ScorpionStingerTip=(256,404)+180deg, Stage2TwinRails=({s2Shot1.WorldPos.x:F1}/{s2Shot2.WorldPos.x:F1}), Stage3TwinRailguns=({rShotL.WorldPos.x:F1}/{rShotR.WorldPos.x:F1})");
        }

        private static void TestPanzerIVModularRigToneAndKinematics()
        {
            var (rig, masks, anims) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            Assert(rig.SortedNodes.Length == 13, $"Expected 13 bones in GCF_Rig_PanzerIV, got {rig.SortedNodes.Length}");
            Assert(masks.Length == 13, $"Expected 13 alpha masks, got {masks.Length}");
            List<string> cfgErrs = rig.ConfigErrors().ToList();
            Assert(cfgErrs.Count == 0, $"GCF_Rig_PanzerIV ConfigErrors: {string.Join("; ", cfgErrs)}");
            Assert(rig.IsVehicleRig && rig.meleeAttackAnims.Count == 0, $"Vehicle rig Panzer IV must have 0 meleeAttackAnims, got {rig.meleeAttackAnims.Count}");
            Assert(rig.abilityAnims.Count == 1, $"Expected 1 abilityAnim (SprgrSalvo) on Panzer IV, got {rig.abilityAnims.Count}");
            Assert(!rig.SortedNodes.SelectMany(b => b.partAttacks ?? new List<GiantPartAttackDef>()).Any(a => a.kind == GiantPartAttackKind.Melee),
                "Vehicle rig Panzer IV must have 0 Melee partAttacks");
            Assert(rig.rangedAttackAnim != null, "Panzer IV must define non-null rangedAttackAnim (KwK40Fire)");
            Assert(!rig.hasAnyDirectionalVariants, "Panzer IV lateral views must be removed (pure Dorsal top-down across 360 deg)");
            foreach (BoneNodeDef node in rig.SortedNodes)
            {
                Assert(!node.HasDirectionalVariants && node.eastVariant == null && node.westVariant == null,
                    $"Panzer IV bone '{node.nodeId}' must have zero eastVariant/westVariant lateral views");
            }

            // 1. Verify all 13 Dorsal 512x512 Schwarzgrau RAL 7021 textures, confirm all 20 lateral/wheel PNGs were removed,
            //    plus seamless 512x2048 Dorsal rolling track ribbon and 2 UI ability icons
            string panzerTexDir = ResolveMod17Path("Textures", "Things", "Pawn", "GiantCreature", "PanzerIV");
            string[] removedLateralPngs =
            {
                "PanzerTurret_East.png", "PanzerTurret_West.png",
                "TurretSkirtNear_East.png", "TurretSkirtNear_West.png",
                "TurretSkirtFar_East.png", "TurretSkirtFar_West.png",
                "KwK40MainGun_East.png", "KwK40MainGun_West.png",
                "CommanderCupola_East.png", "CommanderCupola_West.png",
                "PanzerHull_East.png", "PanzerHull_West.png",
                "LowerHullTub_East.png", "LowerHullTub_West.png",
                "RearExhaustMuffler_East.png", "RearExhaustMuffler_West.png",
                "TrackPodNear_East.png", "TrackPodFar_East.png",
                "TrackPodNear_West.png", "TrackPodFar_West.png",
                "SideSkirtNear_East.png", "SideSkirtFar_East.png",
                "SideSkirtNear_West.png", "SideSkirtFar_West.png",
                "BowMgMount_East.png", "BowMgMount_West.png",
                "TrackBeltLateralRibbon.png", "DriveSprocket.png", "IdlerWheel.png", "RoadWheel.png"
            };
            foreach (string deadPng in removedLateralPngs)
            {
                Assert(!File.Exists(Path.Combine(panzerTexDir, deadPng)),
                    $"Removed lateral/wheel PNG must not exist: {deadPng}");
            }
            string[] expectedPngs =
            {
                "PanzerHull.png", "LowerHullTub.png", "RearExhaustMuffler.png",
                "TrackPodLeft.png", "TrackPodRight.png",
                "SideSkirtLeft.png", "SideSkirtRight.png",
                "BowMgMount.png", "PanzerTurret.png",
                "TurretSkirtLeft.png", "TurretSkirtRight.png",
                "KwK40MainGun.png", "CommanderCupola.png"
            };

            var facetRatios = new List<double>();
            foreach (string png in expectedPngs)
            {
                string full = Path.Combine(panzerTexDir, png);
                Assert(File.Exists(full), $"Missing PanzerIV PNG: {full}");
                byte[] rgba = DecodePngRgbaTopDown(full, out int w, out int h);
                Assert(w == 512 && h == 512, $"Expected 512x512 on {png}, got {w}x{h}");

                float[] dist = ComputeInwardChamferDistances(rgba, w, h, openBottom: false);
                int stroke = MeasureOutlineStrokePxFromDist(rgba, dist);
                double intBlack = MeasureInteriorBlackRatioFromDist(rgba, dist, out int deepCnt);
                double valleySeam = MeasureInteriorValleySeamAndFacetRatioFromDist(rgba, dist, w, h, out _, out double cleanFacet);
                facetRatios.Add(cleanFacet);

                Assert(stroke >= 8, $"{png} outline stroke ({stroke}px) must be >= 8px");
                Assert(deepCnt < 200 || intBlack <= 0.01, $"{png} interior black ({intBlack * 100.0:F2}%) must be <= 1.0%");
                Assert(deepCnt < 200 || valleySeam <= 0.045, $"{png} valley seam ({valleySeam * 100.0:F2}%) must be <= 4.5%");
                Assert(deepCnt < 200 || cleanFacet >= 0.030, $"{png} clean facet ({cleanFacet * 100.0:F2}%) must be >= 3.0%");

                // Interior tone verification: dark matte Schwarzgrau RAL 7021
                var toneLums = new List<double>();
                var toneSats = new List<double>();
                float minDepth = 14.0f;
                for (int pass = 0; pass < 2 && toneLums.Count < 120; pass++)
                {
                    toneLums.Clear();
                    toneSats.Clear();
                    minDepth = pass == 0 ? 14.0f : 11.0f;
                    for (int i = 0; i < dist.Length; i++)
                    {
                        if (rgba[i * 4 + 3] < 128 || dist[i] < minDepth) continue;
                        int p = i * 4;
                        byte r = rgba[p];
                        byte g = rgba[p + 1];
                        byte b = rgba[p + 2];
                        toneLums.Add(0.299 * r + 0.587 * g + 0.114 * b);
                        byte mx = Math.Max(r, Math.Max(g, b));
                        byte mn = Math.Min(r, Math.Min(g, b));
                        toneSats.Add(mx > 0 ? (double)(mx - mn) / mx : 0.0);
                    }
                }
                Assert(toneLums.Count >= 60, $"Expected >= 60 interior pixels for tone audit on {png}, got {toneLums.Count}");
                double meanLum = toneLums.Average();
                double meanSat = toneSats.Average();
                toneLums.Sort();
                double p90Lum = toneLums[Math.Min(toneLums.Count - 1, (int)(0.90 * toneLums.Count))];

                Assert(meanLum >= 65.0 && meanLum <= 96.0,
                    $"{png} Schwarzgrau RAL 7021 interior meanLum={meanLum:F1} must lie in [65.0, 96.0]");
                Assert(p90Lum <= 122.0,
                    $"{png} interior p90Lum={p90Lum:F1} must be <= 122.0");
                Assert(meanSat <= 0.10,
                    $"{png} interior meanSat={meanSat * 100.0:F1}% must be <= 10.0%");
            }

            double meanFacet = facetRatios.Average();
            Assert(meanFacet >= 0.052,
                $"PanzerIV 13-module Dorsal mean cleanFacet ({meanFacet * 100.0:F2}%) must be >= 5.20%");

            string ribbonPath = Path.Combine(panzerTexDir, "TrackBeltDorsalRibbon.png");
            Assert(File.Exists(ribbonPath), $"Missing PanzerIV Dorsal rolling track ribbon PNG: {ribbonPath}");
            {
                byte[] rRgba = DecodePngRgbaTopDown(ribbonPath, out int rw, out int rh);
                Assert(rw == 512 && rh == 2048, $"Expected 512x2048 on TrackBeltDorsalRibbon.png, got {rw}x{rh}");

                int maxSeamDiff = 0;
                int botOffset = (rh - 1) * rw * 4;
                for (int x = 0; x < rw; x++)
                {
                    int topIdx = x * 4;
                    int botIdx = botOffset + topIdx;
                    for (int c = 0; c < 4; c++)
                    {
                        int d = Math.Abs(rRgba[topIdx + c] - rRgba[botIdx + c]);
                        if (d > maxSeamDiff) maxSeamDiff = d;
                    }
                }
                Assert(maxSeamDiff <= 2, $"TrackBeltDorsalRibbon.png top/bottom cyclic seam maxDiff ({maxSeamDiff}) must be <= 2");

                var rLums = new List<double>();
                var rSats = new List<double>();
                for (int y = 0; y < rh; y += 2)
                {
                    int row = y * rw;
                    for (int x = 12; x < rw - 12; x++)
                    {
                        int p = (row + x) * 4;
                        if (rRgba[p + 3] < 200) continue;
                        if (rRgba[(row + x - 10) * 4 + 3] < 128 || rRgba[(row + x + 10) * 4 + 3] < 128) continue;
                        byte r = rRgba[p];
                        byte g = rRgba[p + 1];
                        byte b = rRgba[p + 2];
                        rLums.Add(0.299 * r + 0.587 * g + 0.114 * b);
                        byte mx = Math.Max(r, Math.Max(g, b));
                        byte mn = Math.Min(r, Math.Min(g, b));
                        rSats.Add(mx > 0 ? (double)(mx - mn) / mx : 0.0);
                    }
                }
                Assert(rLums.Count >= 500, $"TrackBeltDorsalRibbon.png expected >= 500 interior pixels, got {rLums.Count}");
                double rMeanLum = rLums.Average();
                double rMeanSat = rSats.Average();
                rLums.Sort();
                double rP90Lum = rLums[(int)(0.90 * rLums.Count)];
                Assert(rMeanLum >= 65.0 && rMeanLum <= 96.0, $"TrackBeltDorsalRibbon.png meanLum={rMeanLum:F1} must lie in [65.0, 96.0]");
                Assert(rP90Lum <= 122.0, $"TrackBeltDorsalRibbon.png p90Lum={rP90Lum:F1} must be <= 122.0");
                Assert(rMeanSat <= 0.10, $"TrackBeltDorsalRibbon.png meanSat={rMeanSat * 100.0:F1}% must be <= 10.0%");
            }

            foreach (string uiIcon in new[] { "PanzerSprgrSalvo.png" })
            {
                string iconPath = ResolveMod17Path("Textures", "UI", "Abilities", uiIcon);
                Assert(File.Exists(iconPath), $"Missing PanzerIV UI ability icon: {iconPath}");
                _ = DecodePngRgbaTopDown(iconPath, out int iw, out int ih);
                Assert(iw == 512 && ih == 512, $"Expected 512x512 UI icon for {uiIcon}, got {iw}x{ih}");
            }

            // 2. Verify Dorsal parent-child layer separation >= 0.7f and steady full-360 turret lookChain
            foreach (BoneNodeDef node in rig.SortedNodes)
            {
                if (node.parentRuntimeIndex >= 0)
                {
                    BoneNodeDef parent = rig.SortedNodes[node.parentRuntimeIndex];
                    float delta = MathF.Abs(parent.GetLayerOffset(GiantBoneViewSector.Dorsal) - node.GetLayerOffset(GiantBoneViewSector.Dorsal));
                    Assert(delta + 1e-4f >= 0.7f, $"Parent-child Dorsal layerOffset delta too small on {parent.nodeId}->{node.nodeId}: {delta:F2}");
                }
            }
            Assert(rig.steering != null && rig.steering.lookChains != null, "PanzerIV must configure steering lookChains");
            Assert(rig.TryGetNodeIndex("turret_body", out int panzerTurretIdx) && rig.SortedNodes[panzerTurretIdx].isTurret,
                "PanzerIV turret_body must set part-level <isTurret>true</isTurret>");
            AssertNear(rig.SortedNodes[panzerTurretIdx].maxTurretAimAngleDeg, 180f, 1e-4f, "PanzerIV turret_body maxTurretAimAngleDeg must be 180");
            Assert(rig.TryGetNodeIndex("main_gun", out int panzerGunIdx) && rig.IsBoneInTurretSubtree(panzerGunIdx, out float gunTurretArc) && MathF.Abs(gunTurretArc - 180f) < 1e-4f,
                "PanzerIV main_gun must inherit turret subtree status from turret_body");
            Assert(rig.TryGetNodeIndex("bow_mg", out int bowMgIdx) && !rig.IsBoneInTurretSubtree(bowMgIdx, out _),
                "PanzerIV hull-mounted bow_mg must NOT be marked as a turret");
            Assert(rig.TryGetNodeIndex("hull_chassis", out int hullIdx) && !rig.IsBoneInTurretSubtree(hullIdx, out _),
                "PanzerIV hull_chassis must NOT be marked as a turret");
            SteeringLookChainDef turretAim = rig.steering.lookChains.FirstOrDefault(c => c.chainId == "turret_aim");
            Assert(turretAim != null && turretAim.boneIds.Contains("turret_body"), "Missing turret_aim LookChain targeting turret_body");
            Assert(turretAim.full360Traverse, "PanzerIV turret_aim LookChain must enable full360Traverse");
            AssertNear(turretAim.maxChainAngleDeg, 180f, 1e-4f, "PanzerIV turret_aim maxChainAngleDeg must be 180");
            AssertNear(turretAim.combatTargetWeight, 1.0f, 1e-4f, "Panzer turret combatTargetWeight must be 1.0");
            AssertNear(turretAim.idleScanAmplitudeDeg, 0f, 1e-4f, "Panzer turret idleScanAmplitudeDeg must be 0");
            AssertNear(turretAim.locoWaveAmplitudeDeg, 0f, 1e-4f, "Panzer turret locoWaveAmplitudeDeg must be 0");

            Assert(anims.TryGetValue("GCF_Anim_PanzerIV_KwK40Fire", out GiantAnimDef kwkFireAnim), "Missing GCF_Anim_PanzerIV_KwK40Fire");
            Assert(anims.TryGetValue("GCF_Anim_PanzerIV_SprgrSalvo", out GiantAnimDef sprgrAnim), "Missing GCF_Anim_PanzerIV_SprgrSalvo");
            Assert(!anims.ContainsKey("GCF_Anim_PanzerIV_BowCrushRam")
                   && !anims.ContainsKey("GCF_Anim_PanzerIV_SternReverseSlam")
                   && !anims.ContainsKey("GCF_Anim_PanzerIV_BlitzOverrun"),
                "PanzerIV must purge all melee/ramming animation clips");
            foreach (GiantAnimDef pzClip in anims.Values)
            {
                for (float sampleTick = 0f; sampleTick <= pzClip.durationTicks; sampleTick += 2f)
                {
                    var clipPoses = new BoneLocalPose[rig.SortedNodes.Length];
                    pzClip.EvaluateInto(rig, sampleTick, clipPoses);
                    for (int bi = 0; bi < clipPoses.Length; bi++)
                    {
                        Assert(clipPoses[bi].offset.sqrMagnitude <= 1e-6f,
                            $"PanzerIV clip '{pzClip.defName}' @ tick={sampleTick} must keep bone '{rig.SortedNodes[bi].nodeId}' offset at (0, 0), got {clipPoses[bi].offset}");
                    }
                }
            }
            AssertNear(rig.ActiveVehicleLocomotion.accelSquatOffset, 0f, 1e-6f, "PanzerIV accelSquatOffset must be 0");
            AssertNear(rig.ActiveVehicleLocomotion.brakeDiveOffset, 0f, 1e-6f, "PanzerIV brakeDiveOffset must be 0");
            Assert(rig.TryResolveTurretRecoilForFiringBone(panzerGunIdx, out GiantTurretRecoilDef kwkRecDef, out int kwkRecBoneIdx)
                   && kwkRecBoneIdx == panzerGunIdx && kwkRecDef.distanceCells >= 0.40f,
                "PanzerIV recoil must resolve exclusively onto main_gun barrel (never hull_chassis or turret_body)");
            var recState = new TurretRecoilState();
            recState.QueueShotImpulse(kwkRecDef, 0f, 1.0f);
            Vector2 barrelKick = recState.StepAndEvaluate(2f, 0f);
            Assert(barrelKick.y <= -0.40f && MathF.Abs(barrelKick.x) <= 1e-4f,
                $"main_gun barrel recoil facing North must displace backward along -Z (got {barrelKick}) while hull stays at (0, 0)");

            // 3. Verify KwK 40 muzzle projection ahead of hull at 0 deg North & disarm on turret sever
            Vector2 rootXZ = new Vector2(50.5f, 50.5f);
            IntVec3 centerCell = new IntVec3(50, 0, 50);
            IntVec3 mapSize = new IntVec3(200, 1, 200);
            int n = rig.SortedNodes.Length;
            var localPoses = Enumerable.Repeat(BoneLocalPose.Identity, n).ToArray();
            var missing = new bool[n];
            var worldPoses = new BoneWorldPose[n];
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);

            GiantWeaponEmitterDef kwkEmitter = GiantMuzzleResolver.MatchEmitter(rig, weaponDefName: "GCF_Gun_PanzerKwKCannon");
            Assert(kwkEmitter != null && kwkEmitter.barrels.Count == 1, "Expected single-barrel kwk40_cannon emitter on GCF_Rig_PanzerIV");
            Func<string, bool> intactFn = bid => rig.TryGetNodeIndex(bid, out int idx) && worldPoses[idx].visible;
            int cursor = 0;
            Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(rig, worldPoses, kwkEmitter, ref cursor, true, 1f, intactFn, out GiantMuzzleShotInfo muzzleShot),
                "KwK 40 muzzle shot resolution failed");
            Assert(muzzleShot.BoneId == "main_gun" && muzzleShot.SocketId == "kwk40_muzzle",
                $"Expected main_gun:kwk40_muzzle, got {muzzleShot.BoneId}:{muzzleShot.SocketId}");
            Assert(muzzleShot.WorldPos.z > rootXZ.y + 6.0f,
                $"At 0 deg North, KwK 40 muzzle ({muzzleShot.WorldPos}) must project > 6.0 cells ahead (+Z) of hull center {rootXZ}");

            // 3b. Verify historical Panzer IV Ausf. H world-space blueprint proportions (~1.52 cells/m: 5.0w x 9.0L hull, >=11.4L total)
            (float xMin, float xMax, float zMin, float zMax) MeasureBoneWorldBox(string boneId)
            {
                Assert(rig.TryGetNodeIndex(boneId, out int bi), $"Missing bone {boneId}");
                TextureAlphaMask m = masks[bi];
                BoneWorldPose wp = worldPoses[bi];
                Vector2[] cs =
                {
                    wp.UVToWorldXZ(m.minU, m.minV),
                    wp.UVToWorldXZ(m.maxU, m.minV),
                    wp.UVToWorldXZ(m.maxU, m.maxV),
                    wp.UVToWorldXZ(m.minU, m.maxV),
                };
                return (cs.Min(c => c.x), cs.Max(c => c.x), cs.Min(c => c.y), cs.Max(c => c.y));
            }
            var hBox = MeasureBoneWorldBox("hull_chassis");
            var tlBox = MeasureBoneWorldBox("track_left");
            var trBox = MeasureBoneWorldBox("track_right");
            var slBox = MeasureBoneWorldBox("skirt_left");
            var srBox = MeasureBoneWorldBox("skirt_right");
            var tbBox = MeasureBoneWorldBox("turret_body");
            var tslBox = MeasureBoneWorldBox("turret_skirt_left");
            var tsrBox = MeasureBoneWorldBox("turret_skirt_right");
            float totalZMin = float.MaxValue, totalZMax = float.MinValue;
            for (int i = 0; i < n; i++)
            {
                if (!worldPoses[i].visible) continue;
                var bBox = MeasureBoneWorldBox(rig.SortedNodes[i].nodeId);
                totalZMin = MathF.Min(totalZMin, bBox.zMin);
                totalZMax = MathF.Max(totalZMax, bBox.zMax);
            }
            float hullSpanX = hBox.xMax - hBox.xMin;
            float hullSpanZ = hBox.zMax - hBox.zMin;
            float trackOuterSpanX = trBox.xMax - tlBox.xMin;
            float skirtOuterSpanX = srBox.xMax - slBox.xMin;
            float hullAspect = hullSpanZ / skirtOuterSpanX;
            float turretBodySpanX = tbBox.xMax - tbBox.xMin;
            float turretSkirtOuterSpanX = tsrBox.xMax - tslBox.xMin;
            float totalSpanZ = totalZMax - totalZMin;
            float totalAspect = totalSpanZ / skirtOuterSpanX;

            Assert(hullSpanX >= 3.3f && hullSpanX <= 4.0f, $"hullSpanX={hullSpanX:F2} out of [3.3, 4.0]");
            Assert(hullSpanZ >= 8.5f, $"hullSpanZ={hullSpanZ:F2} must be >= 8.5");
            Assert(trackOuterSpanX >= 4.15f && trackOuterSpanX <= 4.65f, $"trackOuterSpanX={trackOuterSpanX:F2} out of [4.15, 4.65]");
            Assert(skirtOuterSpanX >= 4.70f && skirtOuterSpanX <= 5.25f, $"skirtOuterSpanX={skirtOuterSpanX:F2} out of [4.70, 5.25]");
            Assert(hullAspect >= 1.72f, $"Panzer IV hull L/W aspect={hullAspect:F2} must be >= 1.72");
            Assert(turretSkirtOuterSpanX > turretBodySpanX + 0.6f && turretSkirtOuterSpanX < trackOuterSpanX - 0.3f,
                $"turretSkirtOuterSpanX={turretSkirtOuterSpanX:F2} must sit between turret ({turretBodySpanX:F2}+0.6) and tracks ({trackOuterSpanX:F2}-0.3)");
            Assert(totalSpanZ >= 11.4f, $"totalSpanZ={totalSpanZ:F2} with KwK 40 must be >= 11.4");
            Assert(totalAspect >= 2.25f, $"total L/W aspect={totalAspect:F2} must be >= 2.25");

            // 4. Verify footprint bounds, skirt severing (track_right stays visible), turret cascading severing, and +35 deg turret traverse
            var footprint = new GiantFootprintData();
            footprint.Rebuild(rig, worldPoses, masks, centerCell, mapSize);
            int fullHitCells = footprint.hitCells.Count;
            int fullColCells = footprint.collisionCells.Count;
            Assert(fullHitCells >= 42, $"Expected PanzerIV full HitCells >= 42, got {fullHitCells}");
            Assert(fullColCells >= 28, $"Expected PanzerIV full CollisionCells >= 28, got {fullColCells}");

            Assert(rig.TryGetNodeIndex("skirt_right", out int skirtRIdx), "Missing skirt_right");
            Assert(rig.TryGetNodeIndex("track_right", out int trackRIdx), "Missing track_right");
            missing[skirtRIdx] = true;
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            footprint.Rebuild(rig, worldPoses, masks, centerCell, mapSize);
            Assert(!footprint.bonePoses[skirtRIdx].visible, "Severed skirt_right must be hidden");
            Assert(footprint.bonePoses[trackRIdx].visible, "track_right must remain visible when starboard skirt_right is severed");

            Assert(rig.TryGetNodeIndex("turret_body", out int turretIdx), "Missing turret_body");
            Assert(rig.TryGetNodeIndex("turret_skirt_left", out int tSkirtLIdx), "Missing turret_skirt_left");
            Assert(rig.TryGetNodeIndex("turret_skirt_right", out int tSkirtRIdx), "Missing turret_skirt_right");
            Assert(rig.TryGetNodeIndex("main_gun", out int gunIdx), "Missing main_gun");
            Assert(rig.TryGetNodeIndex("commander_cupola", out int cupolaIdx), "Missing commander_cupola");
            missing[turretIdx] = true;
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            Assert(!worldPoses[turretIdx].visible && !worldPoses[tSkirtLIdx].visible && !worldPoses[tSkirtRIdx].visible &&
                   !worldPoses[gunIdx].visible && !worldPoses[cupolaIdx].visible,
                "Severing turret_body must cascade-hide turret_skirt_left, turret_skirt_right, main_gun, and commander_cupola");
            Assert(!GiantMuzzleResolver.IsEmitterOperational(rig, kwkEmitter, intactFn),
                "Severing turret_body must disarm GCF_Gun_PanzerKwKCannon emitter");

            // Restore and verify +35 deg independent turret traverse shifts main_gun rightward while hull remains at 0 deg
            Array.Clear(missing, 0, n);
            localPoses[turretIdx].angle = 35f;
            SkeletalKinematics.SolveWorldPoses(rig, rootXZ, 0f, localPoses, missing, worldPoses);
            AssertNear(worldPoses[0].worldAngleDeg, 0f, 1e-4f, "Hull root must remain at 0 deg during turret traverse");
            Vector2 mp = rig.SortedNodes[gunIdx].muzzlePixel;
            Vector2 traversedMuzzleXZ = worldPoses[gunIdx].UVToWorldXZ(mp.x / 512f, 1f - mp.y / 512f);
            Assert(traversedMuzzleXZ.x > rootXZ.x + 2.5f,
                $"Rotating turret_body +35 deg must sweep KwK 40 muzzle rightward (x={traversedMuzzleXZ.x:F2} > {rootXZ.x + 2.5f:F2})");

            // 4b. Pure-Dorsal 360-Deg Rotation & Anti-Jump Turret Traverse Verification
            foreach (float hDeg in new[] { 0f, 90f, 180f, 270f })
            {
                Array.Clear(missing, 0, n);
                localPoses[turretIdx].angle = 0f;
                SkeletalKinematics.SolveWorldPoses(rig, rootXZ, hDeg, localPoses, missing, worldPoses);
                for (int b = 0; b < n; b++)
                {
                    Assert(worldPoses[b].activeSector == GiantBoneViewSector.Dorsal,
                        $"At heading {hDeg:F0} deg, bone {rig.SortedNodes[b].nodeId} must remain Dorsal (got {worldPoses[b].activeSector})");
                }
                footprint.Rebuild(rig, worldPoses, masks, centerCell, mapSize);
                Assert(footprint.hitCells.Count >= 42 && footprint.collisionCells.Count >= 28,
                    $"Pure-Dorsal footprint at {hDeg:F0} deg must cover >=42 hit ({footprint.hitCells.Count}) & >=28 col ({footprint.collisionCells.Count}) cells");
                Assert(GiantMuzzleResolver.TryResolveNextShotFromPoses(rig, worldPoses, kwkEmitter, ref cursor, true, 1f, intactFn, out GiantMuzzleShotInfo hShot),
                    $"KwK 40 muzzle resolution failed at {hDeg:F0} deg");
                Assert(MathF.Abs(Mathf.DeltaAngle(hShot.WorldAngleDeg, hDeg)) < 1e-2f,
                    $"At {hDeg:F0} deg heading, KwK 40 muzzle world angle ({hShot.WorldAngleDeg:F1}) must match {hDeg:F0}");
            }

            // 360 deg stern-crossing shortest-arc continuity test (+168 deg -> -168 deg = 192 deg through +180 deg)
            var steerRt = new GiantSteeringRuntime(rig);
            steerRt.Reset(0f);
            Array.Clear(missing, 0, n);
            for (int t = 0; t < 120; t++)
            {
                for (int i = 0; i < n; i++) localPoses[i] = BoneLocalPose.Identity;
                var settleCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 168f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = true,
                    IsMoving = false,
                    MovedDistanceCells = 0f,
                    AnimState = GiantAnimState.Idle,
                    ContinuousTicks = t,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = true
                };
                steerRt.ApplyBoneSteering(rig, 0f, localPoses, missing, 1f, in settleCtx);
            }
            Assert(MathF.Abs(Mathf.DeltaAngle(168f, localPoses[turretIdx].angle)) <= 1.0f,
                $"Turret must settle smoothly at +168 deg astern (got {localPoses[turretIdx].angle:F2})");

            float prevTurretDeg = localPoses[turretIdx].angle;
            for (int t = 0; t < 40; t++)
            {
                for (int i = 0; i < n; i++) localPoses[i] = BoneLocalPose.Identity;
                var crossCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 192f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = true,
                    IsMoving = false,
                    MovedDistanceCells = 0f,
                    AnimState = GiantAnimState.Idle,
                    ContinuousTicks = 120 + t,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = true
                };
                steerRt.ApplyBoneSteering(rig, 0f, localPoses, missing, 1f, in crossCtx);
                float curTurretDeg = localPoses[turretIdx].angle;
                float stepDelta = Mathf.DeltaAngle(prevTurretDeg, curTurretDeg);
                Assert(stepDelta >= -0.05f && stepDelta <= turretAim.turnSpeedDegPerTick + 0.05f,
                    $"Stern crossing must advance smoothly CW across +-180 deg at tick {t}: prev={prevTurretDeg:F2}, cur={curTurretDeg:F2}, step={stepDelta:F2}");
                Assert(MathF.Abs(curTurretDeg) >= 155f,
                    $"Turret must never snap back toward 0 deg bow when crossing stern (tick {t}: cur={curTurretDeg:F2})");
                prevTurretDeg = curTurretDeg;
            }
            Assert(MathF.Abs(Mathf.DeltaAngle(-168f, prevTurretDeg)) <= 1.5f,
                $"Turret must settle at -168 deg after stern crossing (got {prevTurretDeg:F2})");

            // Combat Target Lock & Secondary-Weapon Non-Hijack Test
            var partRt = new GiantPartCombatRuntime(null);
            partRt.RebuildFromRig(rig);
            BonePartWeaponGroup mainGunGrp = partRt.Groups.FirstOrDefault(g => g.Bone.nodeId == "main_gun");
            BonePartWeaponGroup bowMgGrp = partRt.Groups.FirstOrDefault(g => g.Bone.nodeId == "bow_mg");
            Assert(mainGunGrp != null && bowMgGrp != null, "PanzerIV part combat must register both main_gun and bow_mg groups");
            Assert(mainGunGrp.IsLookChainDriven && !bowMgGrp.IsLookChainDriven,
                "main_gun must be marked IsLookChainDriven while hull bow_mg must remain non-LookChain");

            var cannonTargetXZ = new Vector2(78.5f, 50.5f);
            var bowTargetXZ = new Vector2(50.5f, 62.5f);
            mainGunGrp.Phase = PartWeaponPhase.FollowThrough;
            mainGunGrp.TargetWorldXZ = cannonTargetXZ;
            mainGunGrp.HasTargetWorldXZ = true;
            bowMgGrp.Phase = PartWeaponPhase.WarmingUp;
            bowMgGrp.TargetWorldXZ = bowTargetXZ;
            bowMgGrp.HasTargetWorldXZ = true;
            Assert(partRt.TryGetPrimaryCombatLookTargetXZ(out Vector2 followLookXZ, out _)
                   && Vector2.Distance(followLookXZ, cannonTargetXZ) < 1e-3f,
                $"FollowThrough main_gun target ({cannonTargetXZ}) must not be hijacked by warming bow_mg (got {followLookXZ})");

            mainGunGrp.Phase = PartWeaponPhase.CooldownIdle;
            mainGunGrp.HasTargetWorldXZ = false;
            mainGunGrp.LastTrackedTargetXZ = cannonTargetXZ;
            mainGunGrp.HasLastTrackedTargetXZ = true;
            Assert(partRt.TryGetPrimaryCombatLookTargetXZ(out Vector2 reloadLookXZ, out _)
                   && Vector2.Distance(reloadLookXZ, cannonTargetXZ) < 1e-3f,
                $"Reloading main_gun tracked target ({cannonTargetXZ}) must stay locked during CooldownIdle without bow_mg hijack (got {reloadLookXZ})");

            // 5. Verify Defs, Biotech recipe/patch, and ChineseSimplified localization files exist
            Assert(File.Exists(ResolveMod17Path("Defs", "Bodies", "Bodies_PanzerIV.xml")), "Missing Bodies_PanzerIV.xml");
            Assert(File.Exists(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_PanzerIV.xml")), "Missing Abilities_PanzerIV.xml");
            Assert(File.Exists(ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_PanzerIV.xml")), "Missing ThinkTrees_PanzerIV.xml");
            Assert(File.Exists(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_PanzerIV.xml")), "Missing Races_PanzerIV.xml");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Defs", "RecipeDefs", "Recipes_PanzerIV.xml"))), "PanzerIV must be DevMode-only");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Patches", "Patch_Biotech_PanzerIV.xml"))), "PanzerIV must be DevMode-only");
            Assert(File.Exists(ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "ThingDef", "Races_PanzerIV.xml")), "Missing ChineseSimplified ThingDef translation");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Biotech", "Languages", "ChineseSimplified", "DefInjected", "RecipeDef", "Recipes_PanzerIV.xml"))), "PanzerIV must have no RecipeDef translation");

            // 6. Verify Dorsal rolling caterpillar track belts, differential kinematics & synthetic closed-loop strip winding
            Assert(rig.rollingTracks.Count == 2, $"Expected 2 rollingTracks on Panzer IV, got {rig.rollingTracks.Count}");
            GiantRollingTrackDef leftTrack = rig.rollingTracks.FirstOrDefault(t => t.trackId == "track_left_belt");
            GiantRollingTrackDef rightTrack = rig.rollingTracks.FirstOrDefault(t => t.trackId == "track_right_belt");
            Assert(leftTrack != null && rightTrack != null, "Panzer IV must define track_left_belt and track_right_belt");
            Assert(leftTrack.sideSign < 0f && leftTrack.resolvedParentBoneIndex >= 0, "track_left_belt must resolve with negative sideSign");
            Assert(rightTrack.sideSign > 0f && rightTrack.resolvedParentBoneIndex >= 0, "track_right_belt must resolve with positive sideSign");
            Assert(string.IsNullOrEmpty(leftTrack.lateralRibbonTexPath) && string.IsNullOrEmpty(rightTrack.lateralRibbonTexPath),
                "Panzer IV rollingTracks must not specify lateralRibbonTexPath");
            Assert(leftTrack.nearLoopPixels.Count == 0 && rightTrack.nearLoopPixels.Count == 0, "Panzer IV belts must have 0 nearLoopPixels after lateral view removal");
            Assert(leftTrack.wheels.Count == 0 && rightTrack.wheels.Count == 0, "Panzer IV belts must have 0 lateral wheels after lateral view removal");

            GiantRollingTrackKinematics.ComputeDifferentialStep(1.5f, 0f, leftTrack.gaugeHalfWidthCells, out float fwdL, out float fwdR);
            AssertNear(fwdL, 1.5f, 1e-4f, "Straight forward drive must scroll left belt identically");
            AssertNear(fwdR, 1.5f, 1e-4f, "Straight forward drive must scroll right belt identically");

            GiantRollingTrackKinematics.ComputeDifferentialStep(0f, 90f, leftTrack.gaugeHalfWidthCells, out float pivotL, out float pivotR);
            Assert(pivotL > 2.9f && pivotR < -2.9f && MathF.Abs(pivotL + pivotR) < 1e-4f,
                $"CW pivot must advance left belt (+) and reverse right belt (-): L={pivotL:F3}, R={pivotR:F3}");

            BoneNodeDef rightTrackBone = rig.SortedNodes[rightTrack.resolvedParentBoneIndex];
            var loopVerts = new List<Vector3>();
            var loopUvs = new List<Vector2>();
            var loopTris = new List<int>();
            Assert(GiantRollingTrackMeshBuilder.BuildOpenStrip(
                rightTrack.dorsalStartPixel, rightTrack.dorsalEndPixel, rightTrack.dorsalWidthCells,
                rightTrack.tileLengthCells, 512, rightTrackBone.drawSize, false, 0.4f, loopVerts, loopUvs, loopTris),
                "Dorsal BuildOpenStrip failed");

            var syntheticLoop = new List<Vector2>
            {
                new Vector2(180f, 440f),
                new Vector2(180f, 72f),
                new Vector2(332f, 72f),
                new Vector2(332f, 440f)
            };
            foreach (bool mirror in new[] { false, true })
            {
                bool builtLoop = GiantRollingTrackMeshBuilder.BuildClosedLoopStrip(
                    syntheticLoop, 0.28f, rightTrack.tileLengthCells,
                    512, new Vector2(4f, 9f), mirror, 0.65f, loopVerts, loopUvs, loopTris);
                Assert(builtLoop, $"Synthetic BuildClosedLoopStrip failed for mirrorX={mirror}");
                Assert(loopVerts.Count == (syntheticLoop.Count + 1) * 2, $"Unexpected closed loop vertex count {loopVerts.Count}");
                Assert(loopTris.Count == syntheticLoop.Count * 6, $"Unexpected closed loop triangle index count {loopTris.Count}");

                int lastPair = loopVerts.Count - 2;
                Assert(Vector3.Distance(loopVerts[0], loopVerts[lastPair]) < 1e-4f && Vector3.Distance(loopVerts[1], loopVerts[lastPair + 1]) < 1e-4f,
                    $"Closed loop vertices must close seamlessly for mirrorX={mirror}");
                float uvSpan = MathF.Abs(loopUvs[0].y - loopUvs[lastPair].y);
                Assert(uvSpan >= 1f - 1e-4f && MathF.Abs(uvSpan - MathF.Round(uvSpan)) < 1e-4f,
                    $"Closed loop UV span ({uvSpan:F4}) must be an integer repeat count for mirrorX={mirror}");

                for (int t = 0; t < loopTris.Count; t += 3)
                {
                    Vector3 va = loopVerts[loopTris[t]];
                    Vector3 vb = loopVerts[loopTris[t + 1]];
                    Vector3 vc = loopVerts[loopTris[t + 2]];
                    float cross2D = (vb.x - va.x) * (vc.z - vb.z) - (vb.z - va.z) * (vc.x - vb.x);
                    Assert(cross2D <= 1e-5f, $"Closed loop triangle {t / 3} winding must stay CW in XZ for mirrorX={mirror}: cross={cross2D}");
                }
            }

            Console.WriteLine(
                $"       -> PanzerIV verified (Pure Dorsal 360): Hull={hullSpanX:F2}w x {hullSpanZ:F2}L | Tracks={trackOuterSpanX:F2}w | Schuerzen={skirtOuterSpanX:F2}w (Hull L/W={hullAspect:F2}) | TurretSkirt={turretSkirtOuterSpanX:F2}w | TotalL={totalSpanZ:F2} (Total L/W={totalAspect:F2}) | HitCells={fullHitCells}, ColCells={fullColCells} | MeanFacet={meanFacet * 100.0:F2}%, MuzzleZ={muzzleShot.WorldPos.z:F2}, +35deg MuzzleX={traversedMuzzleXZ.x:F2}");
        }

        private static BodyDef LoadBodyDefFromXml(string bodyFile, string bodyDefName)
        {
            string bodyPath = ResolveMod17Path("Defs", "Bodies", bodyFile);
            Assert(File.Exists(bodyPath), $"Missing body XML {bodyPath}");
            XDocument doc = XDocument.Load(bodyPath);
            var partDefs = new Dictionary<string, BodyPartDef>(StringComparer.Ordinal);
            foreach (XElement bpEl in doc.Root!.Elements("BodyPartDef"))
            {
                string dn = bpEl.Element("defName")?.Value?.Trim();
                if (string.IsNullOrEmpty(dn)) continue;
                partDefs[dn] = new BodyPartDef
                {
                    defName = dn,
                    label = bpEl.Element("label")?.Value ?? dn,
                    hitPoints = (int)ParseFloat(bpEl.Element("hitPoints")?.Value, 40f)
                };
            }

            XElement bodyEl = doc.Root.Elements("BodyDef")
                .FirstOrDefault(e => string.Equals(e.Element("defName")?.Value?.Trim(), bodyDefName, StringComparison.Ordinal));
            Assert(bodyEl != null, $"Missing BodyDef '{bodyDefName}' in {bodyFile}");

            BodyPartRecord ParsePartRecord(XElement pEl, BodyPartRecord parent, BodyDef ownerBody)
            {
                string defName = pEl.Element("def")?.Value?.Trim() ?? "UnknownPart";
                if (!partDefs.TryGetValue(defName, out BodyPartDef bpd))
                {
                    bpd = new BodyPartDef { defName = defName, label = defName, hitPoints = 40 };
                    partDefs[defName] = bpd;
                }
                var rec = new BodyPartRecord
                {
                    body = ownerBody,
                    def = bpd,
                    parent = parent,
                    customLabel = pEl.Element("customLabel")?.Value?.Trim(),
                    untranslatedCustomLabel = pEl.Element("customLabel")?.Value?.Trim(),
                    coverage = ParseFloat(pEl.Element("coverage")?.Value, parent == null ? 1f : 0.1f),
                    parts = new List<BodyPartRecord>()
                };
                if (Enum.TryParse(pEl.Element("depth")?.Value, true, out BodyPartDepth depth))
                {
                    rec.depth = depth;
                }
                else
                {
                    rec.depth = BodyPartDepth.Outside;
                }
                if (pEl.Element("parts") is XElement childrenEl)
                {
                    float covSum = 0f;
                    foreach (XElement childLi in childrenEl.Elements("li"))
                    {
                        BodyPartRecord childRec = ParsePartRecord(childLi, rec, ownerBody);
                        rec.parts.Add(childRec);
                        covSum += childRec.coverage;
                    }
                    Assert(covSum < 0.999f, $"BodyDef '{bodyDefName}' part '{rec.untranslatedCustomLabel ?? rec.def.defName}' child coverage sum={covSum:F3} >= 1.0");
                }
                return rec;
            }

            var bodyDef = new BodyDef { defName = bodyDefName, label = bodyEl.Element("label")?.Value ?? bodyDefName };
            bodyDef.corePart = ParsePartRecord(bodyEl.Element("corePart")!, null, bodyDef);
            return bodyDef;
        }

        private static void TestAnatomicalTreeAlignmentCascadeSeveringAndBattleDamage()
        {
            // 1. Validate 1:1 BodyPartRecord uniqueness and strict parent-child <parts> nesting across ALL 8 GiantRigDefs
            (string rigFile, string animFile, string rigDefName, string bodyFile, string bodyDefName)[] allRigMappings =
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion", "Bodies_MechScorpion.xml", "GCF_Body_MechScorpion"),
                ("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax", "Bodies_Valstrax.xml", "GCF_Body_Valstrax"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1", "Bodies_MechColossus.xml", "GCF_Body_MechColossus"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2", "Bodies_MechColossus.xml", "GCF_Body_MechColossus"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3", "Bodies_MechColossus.xml", "GCF_Body_MechColossus"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier", "Bodies_ProtossCarrier.xml", "GCF_Body_ProtossCarrier"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV", "Bodies_PanzerIV.xml", "GCF_Body_PanzerIV"),
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos", "Bodies_Rathalos.xml", "GCF_Body_Rathalos"),
            };

            foreach (var m in allRigMappings)
            {
                var (rig, _, _) = LoadRigFromXml(m.rigFile, m.animFile, m.rigDefName);
                BodyDef bodyDef = LoadBodyDefFromXml(m.bodyFile, m.bodyDefName);
                List<string> alignErrors = rig.ValidateAnatomicalTreeAlignment(bodyDef, m.rigDefName).ToList();
                Assert(alignErrors.Count == 0,
                    $"Anatomical 1:1 alignment errors in {m.rigDefName} vs {m.bodyDefName}: {string.Join(" | ", alignErrors)}");

                // Verify core root bone has damage reduction (< 0.80) so outer parts break before core collapse
                BoneNodeDef rootBone = rig.SortedNodes[0];
                Assert(!rootBone.hideWhenMissing, $"{m.rigDefName} root bone '{rootBone.nodeId}' must have hideWhenMissing=false");
                Assert(rootBone.damageMultiplier <= 0.80f && rootBone.armorMultiplier >= 1.35f,
                    $"{m.rigDefName} root bone '{rootBone.nodeId}' must carry core armor protection (dmgMult={rootBone.damageMultiplier:F2}, armorMult={rootBone.armorMultiplier:F2})");
            }

            // 2. Negative validation tests: catch shared severable BodyPartRecord & un-nested flat sibling child bone
            BodyDef colossusBody = LoadBodyDefFromXml("Bodies_MechColossus.xml", "GCF_Body_MechColossus");
            var (badSharedRig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            BoneNodeDef wingTipL = badSharedRig.SortedNodes.First(b => b.nodeId == "fortress_wingtip_left");
            wingTipL.linkedBodyPart = new BodyPartDef { defName = "GCF_MechWingLeft" };
            List<string> sharedErrs = badSharedRig.ValidateAnatomicalTreeAlignment(colossusBody, "NegShared").ToList();
            Assert(sharedErrs.Any(e => e.Contains("share the same BodyPartRecord")),
                $"Validator must catch duplicate severable BodyPartRecord sharing, got: {string.Join("; ", sharedErrs)}");

            var (badFlatRig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            BoneNodeDef wingMainL = badFlatRig.SortedNodes.First(b => b.nodeId == "fortress_wing_left");
            wingMainL.linkedBodyPart = new BodyPartDef { defName = "GCF_MechRailgunRight" }; // sibling subtree, not under fortress_pylon_left!
            List<string> flatErrs = badFlatRig.ValidateAnatomicalTreeAlignment(colossusBody, "NegFlat").ToList();
            Assert(flatErrs.Any(e => e.Contains("is NOT nested inside")),
                $"Validator must catch non-nested child bone anatomy, got: {string.Join("; ", flatErrs)}");

            // 3. Topological cascade severing: severing fortress_pylon_left cascades through all 7 left-wing subtree bones
            static int NodeIdx(GiantRigDef r, string id) => Array.FindIndex(r.SortedNodes, b => b.nodeId == id);
            var (stage3Rig, stage3Masks, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            int s3Count = stage3Rig.SortedNodes.Length;
            var s3Missing = new bool[s3Count];
            int pylonIdx = NodeIdx(stage3Rig, "fortress_pylon_left");
            Assert(pylonIdx >= 0, "Missing fortress_pylon_left in Stage 3");
            s3Missing[pylonIdx] = true;
            CompGiantRig.PropagateTopologicalBoneMissingMask(stage3Rig.SortedNodes, s3Missing);

            Assert(s3Missing[NodeIdx(stage3Rig, "fortress_pylon_left")], "fortress_pylon_left must be missing");
            Assert(s3Missing[NodeIdx(stage3Rig, "fortress_viaduct_left")], "fortress_viaduct_left must cascade-sever under fortress_pylon_left");
            Assert(s3Missing[NodeIdx(stage3Rig, "fortress_wing_left")], "fortress_wing_left must cascade-sever under fortress_viaduct_left");
            Assert(s3Missing[NodeIdx(stage3Rig, "fortress_wingtip_left")], "fortress_wingtip_left must cascade-sever under fortress_wing_left");
            Assert(s3Missing[NodeIdx(stage3Rig, "wing_pod_left")], "wing_pod_left must cascade-sever under fortress_wing_left");
            Assert(s3Missing[NodeIdx(stage3Rig, "railgun_outer_mount_left")], "railgun_outer_mount_left must cascade-sever under fortress_wing_left");
            Assert(s3Missing[NodeIdx(stage3Rig, "railgun_outer_barrel_left")], "railgun_outer_barrel_left must cascade-sever under railgun_outer_mount_left");
            Assert(!s3Missing[NodeIdx(stage3Rig, "fortress_pylon_right")] && !s3Missing[NodeIdx(stage3Rig, "fortress_wing_right")],
                "Right wing subtree must remain intact when left wing pylon is severed");
            Assert(s3Missing.Count(x => x) == 7, $"Severing fortress_pylon_left must sever all 7 left-wing bones, got {s3Missing.Count(x => x)}");

            // Verify footprint shrinks when left wing subtree cascades off
            var s3Local = new BoneLocalPose[s3Count];
            Array.Fill(s3Local, BoneLocalPose.Identity);
            var s3WorldFull = new BoneWorldPose[s3Count];
            var s3WorldSevered = new BoneWorldPose[s3Count];
            SkeletalKinematics.SolveWorldPoses(stage3Rig, new Vector2(100f, 100f), 180f, s3Local, new bool[s3Count], s3WorldFull);
            SkeletalKinematics.SolveWorldPoses(stage3Rig, new Vector2(100f, 100f), 180f, s3Local, s3Missing, s3WorldSevered);
            var fpFull = new GiantFootprintData();
            var fpSevered = new GiantFootprintData();
            fpFull.Rebuild(stage3Rig, s3WorldFull, stage3Masks, new IntVec3(100, 0, 100), new IntVec3(250, 1, 250));
            fpSevered.Rebuild(stage3Rig, s3WorldSevered, stage3Masks, new IntVec3(100, 0, 100), new IntVec3(250, 1, 250));
            Assert(fpSevered.hitCells.Count < fpFull.hitCells.Count - 8,
                $"Cascade-severing 4 left-wing bones must shrink Stage 3 hit footprint significantly (full={fpFull.hitCells.Count}, severed={fpSevered.hitCells.Count})");

            // Verify Panzer IV turret_body severing cascades to main_gun, both turret skirts, and commander_cupola (5 bones)
            var (pzRig, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            var pzMissing = new bool[pzRig.SortedNodes.Length];
            pzMissing[NodeIdx(pzRig, "turret_body")] = true;
            CompGiantRig.PropagateTopologicalBoneMissingMask(pzRig.SortedNodes, pzMissing);
            foreach (string childId in new[] { "turret_body", "main_gun", "turret_skirt_left", "turret_skirt_right", "commander_cupola" })
            {
                Assert(pzMissing[NodeIdx(pzRig, childId)], $"Panzer IV '{childId}' must cascade-sever when turret_body is destroyed");
            }
            Assert(pzMissing.Count(x => x) == 5, $"Severing turret_body must sever exactly 5 turret subtree bones, got {pzMissing.Count(x => x)}");

            // 4. Outer-Shell Organ Shielding: block stray external hits from one-shotting Inside organs through intact Outside armor
            var outerShell = new BodyPartRecord { def = new BodyPartDef { defName = "GCF_MechChassis" }, depth = BodyPartDepth.Outside };
            var innerBrain = new BodyPartRecord { def = new BodyPartDef { defName = "ArtificialBrain" }, depth = BodyPartDepth.Inside, parent = outerShell };
            var extHitLowAp = new DamageInfo();
            extHitLowAp.SetBodyRegion(BodyPartHeight.Undefined, BodyPartDepth.Undefined);
            Assert(CompGiantRig.ShouldBlockChildOrganRoll(outerShell, 0.95f, innerBrain, extHitLowAp, breachRoll01: 0.01f),
                "Intact Outside shell (95% HP) must block external hit from rolling into Inside ArtificialBrain");

            var bulletDamageDef = new DamageDef { defName = "Bullet" };
            var extHitHighAp = new DamageInfo(bulletDamageDef, 45f, armorPenetration: 0.95f);
            extHitHighAp.SetBodyRegion(BodyPartHeight.Undefined, BodyPartDepth.Undefined);
            Assert(CompGiantRig.ShouldBlockChildOrganRoll(outerShell, 0.55f, innerBrain, extHitHighAp, breachRoll01: 0.01f),
                "Healthy Outside shell (55% HP >= 30%) must still block external hit even at high AP");
            Assert(!CompGiantRig.ShouldBlockChildOrganRoll(outerShell, 0.20f, innerBrain, extHitHighAp, breachRoll01: 0.05f),
                "Battered Outside shell (20% HP < 30%) + high AP (>= 0.85) + low breach roll (< 0.15) should allow internal critical breach");

            var surgicalInternalHit = new DamageInfo();
            surgicalInternalHit.SetBodyRegion(BodyPartHeight.Undefined, BodyPartDepth.Inside);
            Assert(!CompGiantRig.ShouldBlockChildOrganRoll(outerShell, 1.0f, innerBrain, surgicalInternalHit, breachRoll01: 0.99f),
                "Explicit Inside-depth damage must not be blocked by outer shell guard");

            // 5. LethalDamageThreshold & anti-premature-death guard + Behemoth PainShockThreshold
            Assert(GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(0.75f, severedBoneCount: 0, totalSeverableBones: 17),
                "Giant with 75% core HP and 0 severed bones must NOT die from cumulative scratch LethalDamageThreshold");
            Assert(GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(0.45f, severedBoneCount: 1, totalSeverableBones: 17),
                "Giant with 45% core HP and only 1 severed bone must still resist cumulative scratch death");
            Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(0.45f, severedBoneCount: 2, totalSeverableBones: 17),
                "Once >= 2 limbs are severed, normal threshold checks may proceed");
            Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(0.14f, severedBoneCount: 0, totalSeverableBones: 17),
                "Once core HP drops <= 18%, lethal threshold guard yields normally");

            XDocument rathPainRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_Rathalos.xml"));
            float rathalosPainShock = ParseFloat(
                rathPainRaceDoc.Descendants("ThingDef")
                    .First(e => e.Element("defName")?.Value == "GCF_Rathalos")
                    .Element("statBases")?.Element("PainShockThreshold")?.Value,
                0.80f);
            Assert(rathalosPainShock >= 0.90f, $"Rathalos PainShockThreshold ({rathalosPainShock:F2}) must be >= 0.90 so limbs sever before pain shock");

            // 6. Progressive pre-sever battle-damage charring tint
            Color healthyTint = PawnRenderNodeWorker_GiantBone.ComputeBattleDamageTint(0.90f, isSolidOrMechanoid: true);
            Color midWoundTint = PawnRenderNodeWorker_GiantBone.ComputeBattleDamageTint(0.50f, isSolidOrMechanoid: true);
            Color critWoundTint = PawnRenderNodeWorker_GiantBone.ComputeBattleDamageTint(0.15f, isSolidOrMechanoid: true);
            AssertNear(healthyTint.r, 1f, 1e-4f, "Healthy bone (>=80% HP) must stay untinted white");
            Assert(critWoundTint.r < midWoundTint.r && midWoundTint.r < healthyTint.r && critWoundTint.a == 1f,
                $"Damaged bone charring tint must darken monotonically while keeping alpha=1 (healthy={healthyTint.r:F2}, mid={midWoundTint.r:F2}, crit={critWoundTint.r:F2})");

            Console.WriteLine(
                $"       -> All 8 GiantRigDefs passed 1:1 BodyDef subtree nesting | Stage3 left-wing cascade={s3Missing.Count(x => x)} bones ({fpFull.hitCells.Count}->{fpSevered.hitCells.Count} hitCells) | PanzerIV turret cascade=5 bones | Shell shield & lethal guard verified");
        }

        private static int MeasureOutlineStrokePx(byte[] rgbaTopDown, int width, int height, bool openBottom)
        {
            float[] dist = ComputeInwardChamferDistances(rgbaTopDown, width, height, openBottom);
            return MeasureOutlineStrokePxFromDist(rgbaTopDown, dist);
        }

        private static float[] ComputeInwardChamferDistances(byte[] rgbaTopDown, int width, int height, bool openBottom)
        {
            int n = width * height;
            float[] dist = new float[n];
            const float Inf = 1e6f;
            const float Diag = 1.41421356f;

            for (int y = 0; y < height; y++)
            {
                int row = y * width;
                bool edgeRow = (y == 0) || (!openBottom && y == height - 1);
                for (int x = 0; x < width; x++)
                {
                    int idx = row + x;
                    bool fg = rgbaTopDown[idx * 4 + 3] >= 128;
                    if (!fg)
                    {
                        dist[idx] = 0f;
                    }
                    else if (edgeRow || x == 0 || x == width - 1)
                    {
                        dist[idx] = 1f;
                    }
                    else
                    {
                        dist[idx] = Inf;
                    }
                }
            }

            for (int y = 0; y < height; y++)
            {
                int row = y * width;
                for (int x = 0; x < width; x++)
                {
                    int idx = row + x;
                    float d = dist[idx];
                    if (d <= 0f) continue;
                    if (x > 0) d = Math.Min(d, dist[idx - 1] + 1f);
                    if (y > 0)
                    {
                        int up = idx - width;
                        d = Math.Min(d, dist[up] + 1f);
                        if (x > 0) d = Math.Min(d, dist[up - 1] + Diag);
                        if (x + 1 < width) d = Math.Min(d, dist[up + 1] + Diag);
                    }
                    dist[idx] = d;
                }
            }

            for (int y = height - 1; y >= 0; y--)
            {
                int row = y * width;
                for (int x = width - 1; x >= 0; x--)
                {
                    int idx = row + x;
                    float d = dist[idx];
                    if (d <= 0f) continue;
                    if (x + 1 < width) d = Math.Min(d, dist[idx + 1] + 1f);
                    if (y + 1 < height)
                    {
                        int dn = idx + width;
                        d = Math.Min(d, dist[dn] + 1f);
                        if (x + 1 < width) d = Math.Min(d, dist[dn + 1] + Diag);
                        if (x > 0) d = Math.Min(d, dist[dn - 1] + Diag);
                    }
                    dist[idx] = d;
                }
            }

            return dist;
        }

        private static int MeasureOutlineStrokePxFromDist(byte[] rgbaTopDown, float[] dist)
        {
            int n = dist.Length;
            var bands = new List<float>[15];
            for (int b = 1; b <= 14; b++) bands[b] = new List<float>();

            for (int i = 0; i < n; i++)
            {
                float d = dist[i];
                if (d < 0.5f || d >= 14.5f) continue;
                int bin = (int)(d + 0.5f);
                if (bin < 1 || bin > 14) continue;
                int p = i * 4;
                float lum = 0.299f * rgbaTopDown[p] + 0.587f * rgbaTopDown[p + 1] + 0.114f * rgbaTopDown[p + 2];
                bands[bin].Add(lum);
            }

            int strokePx = 0;
            for (int b = 1; b <= 14; b++)
            {
                if (bands[b].Count == 0) break;
                bands[b].Sort();
                float median = bands[b][bands[b].Count / 2];
                if (median < 45f)
                {
                    strokePx++;
                }
                else
                {
                    break;
                }
            }

            return strokePx;
        }

        private static double MeasureInteriorBlackRatioFromDist(byte[] rgbaTopDown, float[] dist, out int interiorCount)
        {
            interiorCount = 0;
            int blackCount = 0;
            for (int i = 0; i < dist.Length; i++)
            {
                if (rgbaTopDown[i * 4 + 3] < 128) continue;
                if (dist[i] < 16.0f) continue;
                interiorCount++;
                int p = i * 4;
                float lum = 0.299f * rgbaTopDown[p] + 0.587f * rgbaTopDown[p + 1] + 0.114f * rgbaTopDown[p + 2];
                if (lum < 34f) blackCount++;
            }
            return interiorCount == 0 ? 0.0 : (double)blackCount / interiorCount;
        }

        private static double MeasureInteriorValleySeamAndFacetRatioFromDist(
            byte[] rgbaTopDown,
            float[] dist,
            int width,
            int height,
            out int interiorCount,
            out double cleanFacetRatio)
        {
            int n = width * height;
            float[] lum = new float[n];
            for (int i = 0; i < n; i++)
            {
                int p = i * 4;
                lum[i] = 0.299f * rgbaTopDown[p] + 0.587f * rgbaTopDown[p + 1] + 0.114f * rgbaTopDown[p + 2];
            }

            interiorCount = 0;
            int seamCount = 0;
            int cleanFacetCount = 0;
            ReadOnlySpan<(int dy, int dx)> dirs = stackalloc (int, int)[] { (0, 1), (1, 0), (1, 1), (1, -1) };

            for (int y = 0; y < height; y++)
            {
                int row = y * width;
                for (int x = 0; x < width; x++)
                {
                    int idx = row + x;
                    if (rgbaTopDown[idx * 4 + 3] < 128 || dist[idx] < 16.0f) continue;
                    interiorCount++;

                    float cLum = lum[idx];
                    bool isSeam = cLum < 34f;
                    if (!isSeam && x >= 4 && x + 4 < width && y >= 4 && y + 4 < height)
                    {
                        foreach (var (dy, dx) in dirs)
                        {
                            for (int d = 2; d <= 4; d++)
                            {
                                int i1 = (y - dy * d) * width + (x - dx * d);
                                int i2 = (y + dy * d) * width + (x + dx * d);
                                if (rgbaTopDown[i1 * 4 + 3] < 128 || rgbaTopDown[i2 * 4 + 3] < 128) continue;
                                if (dist[i1] < 12.5f || dist[i2] < 12.5f) continue;
                                float minSide = MathF.Min(lum[i1], lum[i2]);
                                if (minSide - cLum >= 16.0f)
                                {
                                    isSeam = true;
                                    break;
                                }
                            }
                            if (isSeam) break;
                        }
                    }

                    if (isSeam)
                    {
                        seamCount++;
                        continue;
                    }

                    float grad = 0f;
                    if (x > 0) grad += MathF.Abs(cLum - lum[idx - 1]);
                    if (y > 0) grad += MathF.Abs(cLum - lum[idx - width]);
                    if (grad >= 7.5f) cleanFacetCount++;
                }
            }

            cleanFacetRatio = interiorCount == 0 ? 0.0 : (double)cleanFacetCount / interiorCount;
            return interiorCount == 0 ? 0.0 : (double)seamCount / interiorCount;
        }

        private static byte[] DecodePngRgbaTopDown(string filePath, out int width, out int height)
        {
            byte[] pngBytes = File.ReadAllBytes(filePath);
            ReadOnlySpan<byte> sig = stackalloc byte[8] { 137, 80, 78, 71, 13, 10, 26, 10 };
            if (pngBytes.Length < 33 || !pngBytes.AsSpan(0, 8).SequenceEqual(sig))
            {
                throw new InvalidDataException($"Invalid PNG signature: {filePath}");
            }

            width = 0;
            height = 0;
            byte bitDepth = 0;
            byte colorType = 0;
            byte interlace = 0;
            using var idatStream = new MemoryStream();
            int pos = 8;
            while (pos + 12 <= pngBytes.Length)
            {
                int chunkLen = BinaryPrimitives.ReadInt32BigEndian(pngBytes.AsSpan(pos, 4));
                uint chunkType = BinaryPrimitives.ReadUInt32BigEndian(pngBytes.AsSpan(pos + 4, 4));
                pos += 8;
                if (chunkLen < 0 || pos + chunkLen + 4 > pngBytes.Length) break;
                ReadOnlySpan<byte> chunkData = pngBytes.AsSpan(pos, chunkLen);
                pos += chunkLen + 4;

                switch (chunkType)
                {
                    case 0x49484452u: // IHDR
                        width = BinaryPrimitives.ReadInt32BigEndian(chunkData.Slice(0, 4));
                        height = BinaryPrimitives.ReadInt32BigEndian(chunkData.Slice(4, 4));
                        bitDepth = chunkData[8];
                        colorType = chunkData[9];
                        interlace = chunkData[12];
                        break;
                    case 0x49444154u: // IDAT
                        idatStream.Write(chunkData);
                        break;
                    case 0x49454E44u: // IEND
                        pos = pngBytes.Length;
                        break;
                }
            }

            if (width <= 0 || height <= 0 || bitDepth != 8 || interlace != 0 || (colorType != 6 && colorType != 2))
            {
                throw new NotSupportedException($"Unsupported PNG format ({width}x{height}, depth={bitDepth}, colorType={colorType}) in {filePath}");
            }

            int bpp = colorType == 6 ? 4 : 3;
            int stride = width * bpp;
            byte[] rawScanlines = new byte[(stride + 1) * height];
            idatStream.Position = 0;
            using (var zlib = new ZLibStream(idatStream, CompressionMode.Decompress))
            {
                int totalRead = 0;
                while (totalRead < rawScanlines.Length)
                {
                    int r = zlib.Read(rawScanlines, totalRead, rawScanlines.Length - totalRead);
                    if (r <= 0) break;
                    totalRead += r;
                }
            }

            byte[] prevRow = new byte[stride];
            byte[] curRow = new byte[stride];
            byte[] rgba = new byte[width * height * 4];

            for (int yTop = 0; yTop < height; yTop++)
            {
                int srcStart = yTop * (stride + 1);
                byte filter = rawScanlines[srcStart];
                ReadOnlySpan<byte> raw = rawScanlines.AsSpan(srcStart + 1, stride);
                for (int i = 0; i < stride; i++)
                {
                    byte xByte = raw[i];
                    byte a = i >= bpp ? curRow[i - bpp] : (byte)0;
                    byte b = prevRow[i];
                    byte c = i >= bpp ? prevRow[i - bpp] : (byte)0;
                    curRow[i] = filter switch
                    {
                        0 => xByte,
                        1 => (byte)(xByte + a),
                        2 => (byte)(xByte + b),
                        3 => (byte)(xByte + ((a + b) >> 1)),
                        4 => (byte)(xByte + PngPaethPredictor(a, b, c)),
                        _ => xByte
                    };
                }

                int dstRow = yTop * width * 4;
                if (colorType == 6)
                {
                    Buffer.BlockCopy(curRow, 0, rgba, dstRow, width * 4);
                }
                else
                {
                    for (int x = 0; x < width; x++)
                    {
                        rgba[dstRow + x * 4 + 0] = curRow[x * 3 + 0];
                        rgba[dstRow + x * 4 + 1] = curRow[x * 3 + 1];
                        rgba[dstRow + x * 4 + 2] = curRow[x * 3 + 2];
                        rgba[dstRow + x * 4 + 3] = 255;
                    }
                }
                (prevRow, curRow) = (curRow, prevRow);
            }

            return rgba;
        }

        private static int PngPaethPredictor(int a, int b, int c)
        {
            int p = a + b - c;
            int pa = Math.Abs(p - a);
            int pb = Math.Abs(p - b);
            int pc = Math.Abs(p - c);
            if (pa <= pb && pa <= pc) return a;
            if (pb <= pc) return b;
            return c;
        }

        private static Dictionary<string, GiantHealthBarDef> LoadHealthBarDefsFromXml()
        {
            var dict = new Dictionary<string, GiantHealthBarDef>(StringComparer.Ordinal);
            foreach (string xmlFile in EnumerateAllMod17Files(Path.Combine("Defs", "GiantHealthBarDefs"), "*.xml"))
            {
                XDocument doc = XDocument.Load(xmlFile);
                if (doc.Root == null) continue;
                foreach (XElement el in doc.Root.Elements("GiantCreatureFramework.GiantHealthBarDef"))
                {
                    var hb = new GiantHealthBarDef
                    {
                        defName = el.Element("defName")?.Value?.Trim(),
                        label = el.Element("label")?.Value?.Trim(),
                        topScreenMargin = ParseFloat(el.Element("topScreenMargin")?.Value, 16f),
                        barWidth = ParseFloat(el.Element("barWidth")?.Value, 356f),
                        mainBarHeight = ParseFloat(el.Element("mainBarHeight")?.Value, 16f),
                        subRowHeight = ParseFloat(el.Element("subRowHeight")?.Value, 20f),
                        subMeterWidth = ParseFloat(el.Element("subMeterWidth")?.Value, 100f),
                        stackSpacing = ParseFloat(el.Element("stackSpacing")?.Value, 8f),
                        maxVisibleSubRows = (int)ParseFloat(el.Element("maxVisibleSubRows")?.Value, 12f),
                        enterExpandSeconds = ParseFloat(el.Element("enterExpandSeconds")?.Value, 0.48f),
                        exitCollapseSeconds = ParseFloat(el.Element("exitCollapseSeconds")?.Value, 0.40f),
                        drawerToggleSpeed = ParseFloat(el.Element("drawerToggleSpeed")?.Value, 12f),
                        damageLagDecayPerSecond = ParseFloat(el.Element("damageLagDecayPerSecond")?.Value, 0.55f),
                        defaultExpanded = ParseBool(el.Element("defaultExpanded")?.Value, false),
                        showExpandButton = ParseBool(el.Element("showExpandButton")?.Value, true),
                        clickBarToSelectAndJump = ParseBool(el.Element("clickBarToSelectAndJump")?.Value, true),
                        hideFullHealthMinorLimbs = ParseBool(el.Element("hideFullHealthMinorLimbs")?.Value, false),
                        drawHierarchyLines = ParseBool(el.Element("drawHierarchyLines")?.Value, true),
                        backgroundColor = ParseColorRgba(el.Element("backgroundColor")?.Value, new Color(0.086f, 0.098f, 0.118f, 0.92f)),
                        drawerBackgroundColor = ParseColorRgba(el.Element("drawerBackgroundColor")?.Value, new Color(0.078f, 0.090f, 0.110f, 0.90f)),
                        borderColor = ParseColorRgba(el.Element("borderColor")?.Value, new Color(0.32f, 0.35f, 0.40f, 1.00f)),
                        lagBarColor = ParseColorRgba(el.Element("lagBarColor")?.Value, new Color(0.85f, 0.76f, 0.52f, 0.95f)),
                        healthyFillColor = ParseColorRgba(el.Element("healthyFillColor")?.Value, new Color(0.33f, 0.61f, 0.35f, 1.00f)),
                        woundedFillColor = ParseColorRgba(el.Element("woundedFillColor")?.Value, new Color(0.78f, 0.57f, 0.23f, 1.00f)),
                        criticalFillColor = ParseColorRgba(el.Element("criticalFillColor")?.Value, new Color(0.74f, 0.27f, 0.25f, 1.00f)),
                        textColor = ParseColorRgba(el.Element("textColor")?.Value, new Color(0.96f, 0.97f, 0.98f, 1.00f)),
                        subtitleKey = el.Element("subtitleKey")?.Value?.Trim(),
                        subtitleText = el.Element("subtitleText")?.Value?.Trim(),
                        barFillTexPath = el.Element("barFillTexPath")?.Value?.Trim(),
                        barFillActiveTexPath = el.Element("barFillActiveTexPath")?.Value?.Trim(),
                        barFrameTexPath = el.Element("barFrameTexPath")?.Value?.Trim(),
                        activeBorderColor = ParseColorRgba(el.Element("activeBorderColor")?.Value, Color.clear),
                        activeTextColor = ParseColorRgba(el.Element("activeTextColor")?.Value, Color.clear),
                        leftOrnamentTexPath = el.Element("leftOrnamentTexPath")?.Value?.Trim(),
                        rightOrnamentTexPath = el.Element("rightOrnamentTexPath")?.Value?.Trim(),
                        leftOrnamentActiveTexPath = el.Element("leftOrnamentActiveTexPath")?.Value?.Trim(),
                        rightOrnamentActiveTexPath = el.Element("rightOrnamentActiveTexPath")?.Value?.Trim(),
                        leftOrnamentGlowTexPath = el.Element("leftOrnamentGlowTexPath")?.Value?.Trim(),
                        rightOrnamentGlowTexPath = el.Element("rightOrnamentGlowTexPath")?.Value?.Trim(),
                        ornamentSize = ParseVec2(el.Element("ornamentSize")?.Value, Vector2.zero),
                        ornamentOverlapX = ParseFloat(el.Element("ornamentOverlapX")?.Value, 12f),
                        ornamentOffsetY = ParseFloat(el.Element("ornamentOffsetY")?.Value, 0f),
                        centerCrestTexPath = el.Element("centerCrestTexPath")?.Value?.Trim(),
                        centerCrestActiveTexPath = el.Element("centerCrestActiveTexPath")?.Value?.Trim(),
                        centerCrestGlowTexPath = el.Element("centerCrestGlowTexPath")?.Value?.Trim(),
                        centerCrestSize = ParseVec2(el.Element("centerCrestSize")?.Value, Vector2.zero),
                        centerCrestOffsetY = ParseFloat(el.Element("centerCrestOffsetY")?.Value, 0f),
                        showSecondaryStateBar = ParseBool(el.Element("showSecondaryStateBar")?.Value, false),
                        secondaryBarHeight = ParseFloat(el.Element("secondaryBarHeight")?.Value, 6f),
                        secondaryBarBgColor = ParseColorRgba(el.Element("secondaryBarBgColor")?.Value, new Color(0.050f, 0.055f, 0.072f, 0.94f)),
                        secondaryBarFillColor = ParseColorRgba(el.Element("secondaryBarFillColor")?.Value, new Color(0.92f, 0.18f, 0.26f, 1.00f))
                    };
                    if (!string.IsNullOrEmpty(hb.defName))
                    {
                        dict[hb.defName] = hb;
                    }
                }
            }

            return dict;
        }

        private static Color ParseColorRgba(string s, Color fallback)
        {
            if (string.IsNullOrWhiteSpace(s)) return fallback;
            string clean = s.Trim().Trim('(', ')');
            string[] p = clean.Split(',');
            if (p.Length < 3) return fallback;
            float r = float.Parse(p[0].Trim(), CultureInfo.InvariantCulture);
            float g = float.Parse(p[1].Trim(), CultureInfo.InvariantCulture);
            float b = float.Parse(p[2].Trim(), CultureInfo.InvariantCulture);
            float a = p.Length >= 4 ? float.Parse(p[3].Trim(), CultureInfo.InvariantCulture) : 1f;
            return new Color(r, g, b, a);
        }

        private static void CollectAllBodyPartRecords(BodyPartRecord rec, List<BodyPartRecord> list)
        {
            if (rec == null) return;
            list.Add(rec);
            if (rec.parts != null)
            {
                foreach (BodyPartRecord child in rec.parts)
                {
                    CollectAllBodyPartRecords(child, list);
                }
            }
        }

        private static void ApplyChineseBodyTranslationsForTest(BodyDef bodyDef)
        {
            var zhPartLabels = new Dictionary<string, string>(StringComparer.Ordinal);
            {
                foreach (string xml in EnumerateAllMod17Files(Path.Combine("Languages", "ChineseSimplified", "DefInjected", "BodyPartDef"), "*.xml"))
                {
                    XDocument d = XDocument.Load(xml);
                    if (d.Root == null) continue;
                    foreach (XElement el in d.Root.Elements())
                    {
                        string name = el.Name.LocalName;
                        if (name.EndsWith(".label", StringComparison.Ordinal))
                        {
                            zhPartLabels[name.Substring(0, name.Length - ".label".Length)] = el.Value.Trim();
                        }
                    }
                }
            }

            var allRecords = new List<BodyPartRecord>();
            CollectAllBodyPartRecords(bodyDef.corePart, allRecords);
            foreach (BodyPartRecord rec in allRecords)
            {
                if (rec.def != null && zhPartLabels.TryGetValue(rec.def.defName, out string zhDefLabel))
                {
                    rec.def.label = zhDefLabel;
                }
            }

            {
                var customMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                string prefix = bodyDef.defName + ".";
                foreach (string xml in EnumerateAllMod17Files(Path.Combine("Languages", "ChineseSimplified", "DefInjected", "BodyDef"), "*.xml"))
                {
                    XDocument d = XDocument.Load(xml);
                    if (d.Root == null) continue;
                    foreach (XElement el in d.Root.Elements())
                    {
                        string name = el.Name.LocalName;
                        if (!name.StartsWith(prefix, StringComparison.Ordinal)) continue;
                        int lastDot = name.LastIndexOf(".customLabel", StringComparison.Ordinal);
                        if (lastDot > prefix.Length)
                        {
                            string slug = name.Substring(name.LastIndexOf('.', lastDot - 1) + 1, lastDot - name.LastIndexOf('.', lastDot - 1) - 1);
                            customMap[slug.Replace('_', ' ')] = el.Value.Trim();
                        }
                    }
                }

                foreach (BodyPartRecord rec in allRecords)
                {
                    if (!string.IsNullOrEmpty(rec.untranslatedCustomLabel) &&
                        customMap.TryGetValue(rec.untranslatedCustomLabel, out string zhCustom))
                    {
                        rec.customLabel = zhCustom;
                    }
                }
            }
        }

        private static void ResolveRigBodyPartsForTest(
            GiantRigDef rig,
            BodyDef bodyDef,
            out BodyPartRecord[] boneParts,
            out BodyPartRecord[] whipParts)
        {
            var allRecords = new List<BodyPartRecord>();
            CollectAllBodyPartRecords(bodyDef.corePart, allRecords);

            BodyPartRecord FindRecord(BodyPartDef def, string customLabel, int idx)
            {
                if (def == null) return null;
                if (!string.IsNullOrEmpty(customLabel))
                {
                    var byCustom = allRecords.FirstOrDefault(r =>
                        r.def.defName == def.defName &&
                        string.Equals(r.untranslatedCustomLabel, customLabel, StringComparison.OrdinalIgnoreCase));
                    if (byCustom != null) return byCustom;
                }
                var matches = allRecords.Where(r => r.def.defName == def.defName).ToList();
                if (matches.Count == 0) return null;
                return matches[Math.Clamp(idx, 0, matches.Count - 1)];
            }

            BoneNodeDef[] nodes = rig.SortedNodes;
            boneParts = new BodyPartRecord[nodes.Length];
            for (int i = 0; i < nodes.Length; i++)
            {
                boneParts[i] = FindRecord(nodes[i].linkedBodyPart, nodes[i].linkedBodyPartCustomLabel, nodes[i].linkedBodyPartIndex);
            }

            int wCount = rig.softWhips?.Count ?? 0;
            whipParts = new BodyPartRecord[wCount];
            for (int s = 0; s < wCount; s++)
            {
                SoftWhipDef whip = rig.softWhips[s];
                whipParts[s] = FindRecord(whip.tendrilBodyPart, whip.tendrilBodyPartCustomLabel, 0);
            }
        }

        private static void TestTopBossExpandableHealthBarAndPerPartDamageFlash()
        {
            // 1. Validate GiantHealthBarDef XML & ChineseSimplified DefInjected translation
            var hbDefs = LoadHealthBarDefsFromXml();
            Assert(hbDefs.TryGetValue("GCF_HealthBar_TopBossClean", out GiantHealthBarDef hbDef),
                "Missing GCF_HealthBar_TopBossClean in 1.7/Defs/GiantHealthBarDefs/GiantHealthBarDefs_Base.xml");
            List<string> hbErrs = hbDef.ConfigErrors().ToList();
            Assert(hbErrs.Count == 0, $"GCF_HealthBar_TopBossClean ConfigErrors: {string.Join("; ", hbErrs)}");
            Assert(hbDef.showExpandButton && !hbDef.defaultExpanded && hbDef.drawHierarchyLines,
                "GCF_HealthBar_TopBossClean must default collapsed with [+] expand button and hierarchy lines enabled");
            Assert(hbDef.enterExpandSeconds > 0.2f && hbDef.exitCollapseSeconds > 0.2f,
                "GCF_HealthBar_TopBossClean must define positive spawn unfold and despawn/death collapse durations");
            Assert(hbDef.barWidth >= 500f && hbDef.mainBarHeight >= 24f && hbDef.subRowHeight >= 24f && hbDef.subMeterWidth >= 140f,
                $"GCF_HealthBar_TopBossClean must use enlarged HUD dimensions (got {hbDef.barWidth}x{hbDef.mainBarHeight}, subRow={hbDef.subRowHeight}, subMeter={hbDef.subMeterWidth})");

            string hudSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "UI", "GiantBossHealthBarHUD.cs"));
            Assert(!hudSrc.Contains("OpenTab != null", StringComparison.Ordinal) &&
                   !hudSrc.Contains("ScreenshotModeHandler", StringComparison.Ordinal),
                "GiantBossHealthBarHUD must remain persistently visible when selecting pawns (Inspect OpenTab) or opening map tabs");

            string zhHbPath = Path.Combine(
                ModRoot, "1.7", "Languages", "ChineseSimplified", "DefInjected",
                "GiantCreatureFramework.GiantHealthBarDef", "GiantHealthBarDefs_Base.xml");
            Assert(File.Exists(zhHbPath), $"Missing ChineseSimplified DefInjected for GiantHealthBarDef: {zhHbPath}");
            XDocument zhHbDoc = XDocument.Load(zhHbPath);
            Assert(zhHbDoc.Root?.Element("GCF_HealthBar_TopBossClean.label") != null,
                "Missing GCF_HealthBar_TopBossClean.label in ChineseSimplified DefInjected");

            AssertNear(GiantBossHealthBarHUD.EaseOutCubic(0f), 0f, 1e-5f, "EaseOutCubic(0) must be 0");
            AssertNear(GiantBossHealthBarHUD.EaseOutCubic(0.5f), 0.875f, 1e-5f, "EaseOutCubic(0.5) must be 0.875");
            AssertNear(GiantBossHealthBarHUD.EaseOutCubic(1f), 1f, 1e-5f, "EaseOutCubic(1) must be 1");

            Color healthyCol = hbDef.EvaluateFillColor(0.90f);
            Color woundedCol = hbDef.EvaluateFillColor(0.50f);
            Color critCol = hbDef.EvaluateFillColor(0.20f);
            Assert(healthyCol.g > healthyCol.r && woundedCol.r > woundedCol.b && critCol.r > critCol.g * 2f,
                "GiantHealthBarDef.EvaluateFillColor must distinguish healthy green, wounded amber, and critical red");

            // 2. Verify all 8 Boss rigs mount their expected Boss Health Bar Def (including Valstrax's bespoke GCF_HealthBar_Valstrax)
            (string rigFile, string animFile, string rigDefName, string expectedHbDef)[] bossRigs =
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos", "GCF_HealthBar_TopBossClean"),
                ("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax", "GCF_HealthBar_Valstrax"),
            };
            foreach (var br in bossRigs)
            {
                var (r, _, _) = LoadRigFromXml(br.rigFile, br.animFile, br.rigDefName);
                Assert(r.healthBarDef != null && r.healthBarDef.defName == br.expectedHbDef,
                    $"Boss rig '{br.rigDefName}' must reference healthBarDef='{br.expectedHbDef}' (got '{r.healthBarDef?.defName}')");
            }

            // 2b. Verify bespoke Valstrax Boss Health Bar skinning, textures & live Dragonheart HUD telemetry
            Assert(hbDefs.TryGetValue("GCF_HealthBar_Valstrax", out GiantHealthBarDef valHbDef),
                "Missing GCF_HealthBar_Valstrax in [GCF]Valstrax/1.7/Defs/GiantHealthBarDefs/GiantHealthBarDefs_Valstrax.xml");
            List<string> valHbErrs = valHbDef.ConfigErrors().ToList();
            Assert(valHbErrs.Count == 0, $"GCF_HealthBar_Valstrax ConfigErrors: {string.Join("; ", valHbErrs)}");
            Assert(valHbDef.HasCustomSkinning && valHbDef.HasSideOrnaments && valHbDef.HasCenterCrest && valHbDef.showSecondaryStateBar,
                "GCF_HealthBar_Valstrax must enable custom skinning, side lancewing ornaments, center crest medallion, and secondary Dragonheart state bar");
            string valMod17 = Path.Combine(Path.GetDirectoryName(ModRoot)!, "[GCF]Valstrax", "1.7");
            foreach (string texRel in new[]
            {
                valHbDef.barFillTexPath, valHbDef.barFillActiveTexPath,
                valHbDef.leftOrnamentTexPath, valHbDef.leftOrnamentActiveTexPath, valHbDef.leftOrnamentGlowTexPath,
                valHbDef.rightOrnamentTexPath, valHbDef.rightOrnamentActiveTexPath, valHbDef.rightOrnamentGlowTexPath,
                valHbDef.centerCrestTexPath, valHbDef.centerCrestActiveTexPath, valHbDef.centerCrestGlowTexPath
            })
            {
                string fullPng = Path.Combine(valMod17, "Textures", texRel.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Assert(File.Exists(fullPng), $"Missing bespoke Valstrax Boss Bar texture PNG: {fullPng}");
            }
            var valEnergyComp = new CompValstraxDragonEnergy();
            valEnergyComp.Initialize(new CompProperties_ValstraxDragonEnergy());
            GiantBossHudTelemetry calmTel = default;
            valEnergyComp.FillBossHudTelemetry(ref calmTel);
            Assert(calmTel.HasCustomState && calmTel.ActiveBlend01 < 0.05f && calmTel.ShowSecondaryBar,
                "Calm Valstrax HUD telemetry must show silver resting state with secondary bar enabled");

            valEnergyComp.BeginDragonIntake(40);
            valEnergyComp.RegisterIntakeDamageCheck(42f, hitThoraxOrInternalChest: true);
            GiantBossHudTelemetry intakeTel = default;
            valEnergyComp.FillBossHudTelemetry(ref intakeTel);
            Assert(intakeTel.ActiveBlend01 > 0.30f && intakeTel.SecondaryThresholdMarker01 > 0.40f,
                "Intaking Valstrax HUD telemetry must expose chest backfire threshold progress");

            valEnergyComp.ActivateDragonEnergy(1800);
            valEnergyComp.StepTickHeadless(false, true);
            GiantBossHudTelemetry activeTel = default;
            valEnergyComp.FillBossHudTelemetry(ref activeTel);
            Assert(activeTel.ActiveBlend01 >= 0.90f && activeTel.SecondaryFill01 > 0.95f && !activeTel.IsOverdrive,
                "DragonActive Valstrax HUD telemetry must switch to full crimson active skin and countdown secondary bar");

            valEnergyComp.EnterCometAmbushOverdrive(120);
            GiantBossHudTelemetry cometTel = default;
            valEnergyComp.FillBossHudTelemetry(ref cometTel);
            Assert(cometTel.ActiveBlend01 >= 0.99f && cometTel.IsOverdrive && cometTel.SecondaryFill01 >= 0.99f,
                "CometAmbush Valstrax HUD telemetry must trigger supersonic Overdrive state");

            // 3. Verify Harmony suppression of vanilla whole-pawn red DamageFlasher
            MethodInfo notifyDmgPatch = typeof(HarmonyPatches_Rendering).GetMethod(
                nameof(HarmonyPatches_Rendering.PawnRenderer_Notify_DamageApplied_Prefix),
                BindingFlags.Public | BindingFlags.Static);
            Assert(notifyDmgPatch != null, "Missing HarmonyPatches_Rendering.PawnRenderer_Notify_DamageApplied_Prefix");

            // 4. Per-Part Isolated Damage Red Flash (only struck bone/whip turns red; all other bones stay Color.white)
            var (scorpRig, _, _) = LoadMechScorpionFromXml();
            BodyDef scorpBody = LoadBodyDefFromXml("Bodies_MechScorpion.xml", "GCF_Body_MechScorpion");
            ResolveRigBodyPartsForTest(scorpRig, scorpBody, out BodyPartRecord[] scorpBoneParts, out BodyPartRecord[] scorpWhipParts);

            int stingerIdx = Array.FindIndex(scorpRig.SortedNodes, b => b.nodeId == "tail_stinger");
            Assert(stingerIdx > 0, "Missing tail_stinger on MechScorpion");
            bool[] boneFlash = new bool[scorpRig.SortedNodes.Length];
            bool[] whipFlash = new bool[0];
            bool resolvedStinger = CompGiantRig.TryResolveFlashTargetsForHitPart(
                scorpRig.SortedNodes, scorpBoneParts, scorpWhipParts,
                scorpBoneParts[stingerIdx], stingerIdx, boneFlash, whipFlash);
            Assert(resolvedStinger && boneFlash[stingerIdx], "Striking tail_stinger must flash tail_stinger");
            for (int i = 0; i < boneFlash.Length; i++)
            {
                if (i != stingerIdx)
                {
                    Assert(!boneFlash[i], $"Unstruck bone '{scorpRig.SortedNodes[i].nodeId}' must NOT flash red when tail_stinger is hit");
                }
            }

            float fPeak = CompGiantRig.ComputeDamageFlash01(100, 100);
            float fMid = CompGiantRig.ComputeDamageFlash01(100, 108);
            float fEnd = CompGiantRig.ComputeDamageFlash01(100, 116);
            AssertNear(fPeak, 1.0f, 1e-5f, "Flash intensity at impact tick must be 1.0");
            AssertNear(fMid, 0.5f, 1e-5f, "Flash intensity at +8 ticks (half of 16) must be 0.5");
            AssertNear(fEnd, 0.0f, 1e-5f, "Flash intensity at +16 ticks must decay cleanly to 0.0");

            Color hitTint = PawnRenderNodeWorker_GiantBone.ComposeGiantPartTint(Color.white, 1.0f, true, fPeak);
            Color unhitTint = PawnRenderNodeWorker_GiantBone.ComposeGiantPartTint(Color.white, 1.0f, true, 0f);
            Assert(hitTint.r > 1.15f && hitTint.g < 0.20f && hitTint.b < 0.20f,
                $"Struck bone must receive crisp red flash tint, got ({hitTint.r:F2}, {hitTint.g:F2}, {hitTint.b:F2})");
            AssertNear(unhitTint.r, 1f, 1e-5f, "Unhit bone R channel must remain 1.0 (zero whole-creature red bleed)");
            AssertNear(unhitTint.g, 1f, 1e-5f, "Unhit bone G channel must remain 1.0");
            AssertNear(unhitTint.b, 1f, 1e-5f, "Unhit bone B channel must remain 1.0");

            // Synthetic SoftWhip isolated red flash (hitting left whip flashes ONLY whip[0], zero rigid bones)
            var synWhipPartL = new BodyPartRecord { def = new BodyPartDef { defName = "SynWhipL" } };
            var synWhipPartR = new BodyPartRecord { def = new BodyPartDef { defName = "SynWhipR" } };
            bool[] vlBoneFlash = new bool[scorpRig.SortedNodes.Length];
            bool[] vlWhipFlash = new bool[2];
            bool resolvedWhip = CompGiantRig.TryResolveFlashTargetsForHitPart(
                scorpRig.SortedNodes, scorpBoneParts, new[] { synWhipPartL, synWhipPartR },
                synWhipPartL, -1, vlBoneFlash, vlWhipFlash);
            Assert(resolvedWhip && vlWhipFlash[0] && !vlWhipFlash[1] && vlBoneFlash.All(b => !b),
                "Hitting left SoftWhip tendril must flash ONLY whip[0] and zero rigid bones");

            // Internal child organ walk-up on PanzerIV (hitting an internal organ inside turret walks up to turret_body, not whole tank)
            var (pzRig, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            BodyDef pzBody = LoadBodyDefFromXml("Bodies_PanzerIV.xml", "GCF_Body_PanzerIV");
            ResolveRigBodyPartsForTest(pzRig, pzBody, out BodyPartRecord[] pzBoneParts, out BodyPartRecord[] pzWhipParts);
            int turretIdx = Array.FindIndex(pzRig.SortedNodes, b => b.nodeId == "turret_body");
            Assert(turretIdx > 0 && pzBoneParts[turretIdx] != null, "Missing turret_body on PanzerIV");
            BodyPartRecord internalTurretOrgan = pzBoneParts[turretIdx].parts.FirstOrDefault(p => p.depth == BodyPartDepth.Inside);
            if (internalTurretOrgan != null)
            {
                bool[] pzBoneFlash = new bool[pzRig.SortedNodes.Length];
                bool[] pzWhipFlash = Array.Empty<bool>();
                bool resolvedOrgan = CompGiantRig.TryResolveFlashTargetsForHitPart(
                    pzRig.SortedNodes, pzBoneParts, pzWhipParts,
                    internalTurretOrgan, -1, pzBoneFlash, pzWhipFlash);
                Assert(resolvedOrgan && pzBoneFlash[turretIdx] && pzBoneFlash.Count(x => x) == 1,
                    "Hitting an internal turret sub-organ must walk up to flash ONLY turret_body");
            }

            // 5. Localized Title & Expandable Part-Tree Hierarchy Verification (zero exposed defName / nodeId)
            var zhThingLabels = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (string xmlPath in EnumerateAllMod17Files(Path.Combine("Languages", "ChineseSimplified", "DefInjected", "ThingDef"), "*.xml"))
            {
                XDocument tdDoc = XDocument.Load(xmlPath);
                if (tdDoc.Root == null) continue;
                foreach (XElement el in tdDoc.Root.Elements())
                {
                    zhThingLabels[el.Name.LocalName] = el.Value.Trim();
                }
            }

            (string defName, string expectedZhTitle)[] localizedBossChecks =
            {
                ("GCF_MechScorpion", "重装机械巨蝎"),
                ("GCF_MechColossus", "终焉机神巨构体"),
                ("GCF_PanzerIV", "四号坦克 H 型"),
                ("GCF_ProtossCarrier", "神族航母"),
                ("GCF_Rathalos", "雄火龙"),
                ("GCF_Valstrax", "天彗龙"),
            };

            foreach (var chk in localizedBossChecks)
            {
                Assert(zhThingLabels.TryGetValue($"{chk.defName}.label", out string zhLabel),
                    $"Missing {chk.defName}.label in ChineseSimplified ThingDef translations");
                Assert(zhLabel == chk.expectedZhTitle, $"Expected '{chk.expectedZhTitle}' for {chk.defName}.label, got '{zhLabel}'");

                var mockPawn = new Pawn { def = new ThingDef { defName = chk.defName, label = zhLabel } };
                var mockRig = new GiantRigDef { defName = "GCF_Rig_Test", label = "internal rig label" };
                string resolvedTitle = GiantBossHealthBarHUD.ResolveLocalizedBossTitle(mockPawn, mockRig);
                Assert(resolvedTitle == chk.expectedZhTitle,
                    $"ResolveLocalizedBossTitle must return localized '{chk.expectedZhTitle}', got '{resolvedTitle}'");
                Assert(!resolvedTitle.Contains("GCF_") && !resolvedTitle.Contains('_'),
                    $"Boss bar title '{resolvedTitle}' must never expose internal defName/field identifiers");
            }

            // Verify localized expandable subtree rows (dedup lower_hull_tub on PanzerIV, nested depths on Colossus Stage 3 & VoidLeviathan whips)
            ApplyChineseBodyTranslationsForTest(pzBody);
            List<GiantHealthBarPartRowSpec> pzRows = GiantBossHealthBarHUD.BuildPartTreeRowSpecs(pzRig, pzBoneParts, pzWhipParts);
            Assert(pzRig.SortedNodes.Length == 13 && pzRows.Count == 12,
                $"PanzerIV has 13 nodes including 1 non-severable lower_hull_tub backing plate; expected 12 deduplicated HUD rows, got {pzRows.Count}");
            foreach (var row in pzRows)
            {
                Assert(!string.IsNullOrWhiteSpace(row.LocalizedLabel) && !row.LocalizedLabel.Contains('_') && !row.LocalizedLabel.Contains("GCF_"),
                    $"PanzerIV HUD part row '{row.LocalizedLabel}' must be localized without internal identifiers");
            }

            var (s3Rig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            BodyDef colossusBody = LoadBodyDefFromXml("Bodies_MechColossus.xml", "GCF_Body_MechColossus");
            ApplyChineseBodyTranslationsForTest(colossusBody);
            ResolveRigBodyPartsForTest(s3Rig, colossusBody, out BodyPartRecord[] s3BoneParts, out BodyPartRecord[] s3WhipParts);
            List<GiantHealthBarPartRowSpec> s3Rows = GiantBossHealthBarHUD.BuildPartTreeRowSpecs(s3Rig, s3BoneParts, s3WhipParts);
            Assert(s3Rows.Count == 64, $"Expected 64 localized part rows for Stage 3 MechColossus, got {s3Rows.Count}");

            int pylonBoneIdx = Array.FindIndex(s3Rig.SortedNodes, b => b.nodeId == "fortress_pylon_left");
            int viaductBoneIdx = Array.FindIndex(s3Rig.SortedNodes, b => b.nodeId == "fortress_viaduct_left");
            int wingBoneIdx = Array.FindIndex(s3Rig.SortedNodes, b => b.nodeId == "fortress_wing_left");
            int tipBoneIdx = Array.FindIndex(s3Rig.SortedNodes, b => b.nodeId == "fortress_wingtip_left");
            int podBoneIdx = Array.FindIndex(s3Rig.SortedNodes, b => b.nodeId == "wing_pod_left");
            int dPylon = s3Rows.First(r => !r.IsSoftWhip && r.Index == pylonBoneIdx).Depth;
            int dViaduct = s3Rows.First(r => !r.IsSoftWhip && r.Index == viaductBoneIdx).Depth;
            int dWing = s3Rows.First(r => !r.IsSoftWhip && r.Index == wingBoneIdx).Depth;
            int dTip = s3Rows.First(r => !r.IsSoftWhip && r.Index == tipBoneIdx).Depth;
            int dPod = s3Rows.First(r => !r.IsSoftWhip && r.Index == podBoneIdx).Depth;
            Assert(dPylon == 1 && dViaduct == 2 && dWing == 3 && dTip == 4 && dPod == 4,
                $"Expected nested HUD drawer depths 1->2->3->(4,4) for left wing chain, got {dPylon}->{dViaduct}->{dWing}->({dTip},{dPod})");



            AssertNear(GiantBossHealthBarHUD.ComputeWeightedBossHealthPercent(1f, 1000f, 1000f, false), 1f, 1e-5f, "Full HP boss bar must read 100%");
            AssertNear(GiantBossHealthBarHUD.ComputeWeightedBossHealthPercent(0.80f, 500f, 1000f, false), 0.635f, 1e-4f, "Weighted boss HP formula check");
            AssertNear(GiantBossHealthBarHUD.ComputeWeightedBossHealthPercent(0f, 400f, 1000f, false), 0f, 1e-5f, "Zero core HP must read 0%");
            AssertNear(GiantBossHealthBarHUD.ComputeWeightedBossHealthPercent(0.5f, 500f, 1000f, true), 0f, 1e-5f, "Dead boss must read 0%");

            foreach (float unfoldSample in new[] { 0.25f, 0.60f, 0.88f, 1.00f })
            {
                GiantBossHealthBarHUD.ComputeSymmetricBossBarRects(
                    centerX: 960f,
                    startY: 24f,
                    totalW: 540f,
                    barH: 28f,
                    unfold01: unfoldSample,
                    hasExpandButton: true,
                    compactMode: false,
                    out Rect symTitleRect,
                    out Rect symTrackRect,
                    out Rect symBtnRect,
                    out bool showBtn);
                AssertNear(symTitleRect.center.x, 960f, 1e-4f, $"Boss title must stay coaxially centered at centerX=960 (unfold={unfoldSample})");
                AssertNear(symTrackRect.center.x, 960f, 1e-4f, $"Boss health bar track must stay coaxially symmetric with title at centerX=960 (unfold={unfoldSample})");
                Assert(symBtnRect.x > symTrackRect.xMax + 3f, $"Expand [+] button must reside in extra right area outside trackRect.xMax ({symBtnRect.x} vs {symTrackRect.xMax})");
                Assert(showBtn == (unfoldSample > 0.85f), "Expand button reveal threshold mismatch");
            }
            GiantBossHealthBarHUD.ComputeSymmetricBossBarRects(960f, 24f, 540f, 28f, 1f, true, false, out _, out Rect fullTrackWithBtn, out _, out _);
            GiantBossHealthBarHUD.ComputeSymmetricBossBarRects(960f, 24f, 540f, 28f, 1f, false, false, out _, out Rect fullTrackNoBtn, out _, out _);
            AssertNear(fullTrackWithBtn.x, fullTrackNoBtn.x, 1e-4f, "Enabling right-side [+] button must never shift main health bar X");
            AssertNear(fullTrackWithBtn.width, 540f, 1e-4f, "Main health bar track must retain full barWidth without subtracting [+] button width");

            Console.WriteLine(
                $"       -> GCF_HealthBar_TopBossClean verified on 8 Boss Rigs | Coaxial title/bar symmetry & right-side extra [+] button verified | Localized titles & nested part drawers (Colossus S3={s3Rows.Count}, PanzerIV=11, Leviathan=34) | Isolated per-bone/whip red flash verified");
        }

        private static void TestMandatoryDeathSkeletalAnimationAndCorpsePlayback()
        {
            // 1. Verify all 8 official GiantRigDefs declare valid non-looping <deathAnim> + ChineseSimplified translations
            (string rigFile, string animFile, string rigDefName, string expectedDeathDefName)[] allRigSpecs =
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion", "GCF_Anim_MechScorpion_Death"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1", "GCF_Anim_MechStage1_Death"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2", "GCF_Anim_MechStage2_Death"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3", "GCF_Anim_MechStage3_Death"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier", "GCF_Anim_Carrier_Death"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV", "GCF_Anim_PanzerIV_Death"),
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos", "GCF_Anim_Rathalos_Death"),
                ("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax", "GCF_Anim_Valstrax_Death"),
            };

            var zhAnimLabels = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (string xmlPath in EnumerateAllMod17Files(Path.Combine("Languages", "ChineseSimplified", "DefInjected", "GiantCreatureFramework.GiantAnimDef"), "*.xml"))
            {
                XDocument doc = XDocument.Load(xmlPath);
                if (doc.Root == null) continue;
                foreach (XElement el in doc.Root.Elements())
                {
                    zhAnimLabels[el.Name.LocalName] = el.Value.Trim();
                }
            }

            foreach (var spec in allRigSpecs)
            {
                var (rig, _, _) = LoadRigFromXml(spec.rigFile, spec.animFile, spec.rigDefName);
                List<string> rigErrs = rig.ConfigErrors().ToList();
                Assert(rigErrs.Count == 0, $"Rig '{spec.rigDefName}' ConfigErrors: {string.Join("; ", rigErrs)}");
                Assert(rig.deathAnim != null && rig.deathAnim.defName == spec.expectedDeathDefName,
                    $"Rig '{spec.rigDefName}' expected deathAnim '{spec.expectedDeathDefName}', got '{rig.deathAnim?.defName}'");
                Assert(!rig.deathAnim.loop, $"Death clip '{rig.deathAnim.defName}' must have loop=false");
                Assert(rig.deathAnim.durationTicks >= 20f, $"Death clip '{rig.deathAnim.defName}' durationTicks must be >= 20");
                Assert(rig.deathAnim.HasNonTrivialMotion(8f, 0.25f), $"Death clip '{rig.deathAnim.defName}' must have non-trivial skeletal motion");
                Assert(rig.deathAnim.ConfigErrors().Count() == 0, $"Death clip '{rig.deathAnim.defName}' produced GiantAnimDef.ConfigErrors");
                Assert(zhAnimLabels.TryGetValue($"{spec.expectedDeathDefName}.label", out string zhDeathLabel) && !string.IsNullOrWhiteSpace(zhDeathLabel),
                    $"Missing ChineseSimplified translation for {spec.expectedDeathDefName}.label");
            }

            // 2. Verify negative validation gates in GiantRigDef.ConfigErrors()
            GiantRigDef MakeMinimalRig(GiantAnimDef deathClip)
            {
                var r = new GiantRigDef
                {
                    defName = "Test_DeathValidationRig",
                    deathAnim = deathClip,
                    nodes = new List<BoneNodeDef>
                    {
                        new BoneNodeDef { nodeId = "root_hull", texPath = "Test/Root" },
                        new BoneNodeDef { nodeId = "child_arm", parentId = "root_hull", texPath = "Test/Arm", pivotPixel = new Vector2(256, 256), parentSocketPixel = new Vector2(256, 128) }
                    }
                };
                r.BuildTopology();
                return r;
            }

            Assert(MakeMinimalRig(null).ConfigErrors().Any(e => e.Contains("missing mandatory <deathAnim>")),
                "Missing <deathAnim> must be rejected by GiantRigDef.ConfigErrors()");

            var loopingDeath = new GiantAnimDef
            {
                defName = "Test_LoopingDeath",
                loop = true,
                durationTicks = 40f,
                tracks = new List<BoneAnimTrack>
                {
                    new BoneAnimTrack
                    {
                        nodeId = "child_arm",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f },
                            new BoneKeyframe { tick = 40f, angle = 25f }
                        }
                    }
                }
            };
            Assert(MakeMinimalRig(loopingDeath).ConfigErrors().Any(e => e.Contains("<loop>false</loop>")),
                "Looping <deathAnim> must be rejected by GiantRigDef.ConfigErrors()");

            var staticDeath = new GiantAnimDef
            {
                defName = "Test_StaticDeath",
                loop = false,
                durationTicks = 40f,
                tracks = new List<BoneAnimTrack>
                {
                    new BoneAnimTrack
                    {
                        nodeId = "child_arm",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 2f },
                            new BoneKeyframe { tick = 40f, angle = 2f }
                        }
                    }
                }
            };
            Assert(MakeMinimalRig(staticDeath).ConfigErrors().Any(e => e.Contains("non-trivial skeletal motion")),
                "Static/zero-motion <deathAnim> must be rejected by GiantRigDef.ConfigErrors()");

            var childOffsetDeath = new GiantAnimDef
            {
                defName = "Test_ChildOffsetDeath",
                loop = false,
                durationTicks = 40f,
                tracks = new List<BoneAnimTrack>
                {
                    new BoneAnimTrack
                    {
                        nodeId = "child_arm",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f, offset = Vector2.zero },
                            new BoneKeyframe { tick = 40f, angle = 24f, offset = new Vector2(0.4f, -0.3f) }
                        }
                    }
                }
            };
            Assert(MakeMinimalRig(childOffsetDeath).ConfigErrors().Any(e => e.Contains("non-zero offset")),
                "Child bone non-zero offset inside <deathAnim> must be rejected");

            // 3. Runtime Corpse Frame-by-Frame Playback: smooth C0 blend from live pose -> progressive collapse -> event firing -> settled freeze
            var (scorpRig, _, scorpAnims) = LoadMechScorpionFromXml();
            var scorpLiveComp = new CompGiantRig();
            scorpLiveComp.Initialize(new CompProperties_GiantRig { rigDef = scorpRig });
            // Prime a non-zero live pre-death pose (mid-strike frame) and verify C0 continuity across BeginDeathAnimation()
            scorpLiveComp.PlayForcedMorphClip(scorpAnims["GCF_Anim_MechScorpion_ClawLeft"], blendTicksOverride: 0f);
            int clawLeftIdx = Array.FindIndex(scorpRig.SortedNodes, n => n.nodeId == "claw_left");
            Assert(clawLeftIdx >= 0, "Missing claw_left on MechScorpion");

            int eventsBefore = GiantVfxSystem.TotalTriggeredAnimEventsCount;
            scorpLiveComp.BeginDeathAnimation();
            Assert(scorpLiveComp.CurrentAnimState == GiantAnimState.Death, "BeginDeathAnimation must enter GiantAnimState.Death");
            Assert(scorpLiveComp.IsDeathAnimPlaying && !scorpLiveComp.IsDeathAnimCompleted, "Death animation must start playing from tick 0, not jump to end");
            AssertNear(scorpLiveComp.DeathAnimElapsedTicks, 0f, 1e-5f, "DeathAnimElapsedTicks must initialize to 0");
            AssertNear(scorpLiveComp.DeathAnimNormalizedProgress, 0f, 1e-5f, "DeathAnimNormalizedProgress must initialize to 0");

            float angleTick0 = scorpLiveComp.LatestSnapshot.localPoses[clawLeftIdx].angle;
            float rootYTick0 = scorpLiveComp.LatestSnapshot.localPoses[0].offset.y;

            int durTicks = Mathf.RoundToInt(scorpRig.deathAnim.durationTicks);
            float angleMid = 0f;
            float rootYMid = 0f;
            for (int t = 1; t <= durTicks; t++)
            {
                bool stepped = scorpLiveComp.TickCorpseDeathAnimation(1f, out _);
                Assert(stepped, $"TickCorpseDeathAnimation must return true at tick {t}/{durTicks}");
                if (t == 18)
                {
                    angleMid = scorpLiveComp.LatestSnapshot.localPoses[clawLeftIdx].angle;
                    rootYMid = scorpLiveComp.LatestSnapshot.localPoses[0].offset.y;
                }
            }

            float angleEnd = scorpLiveComp.LatestSnapshot.localPoses[clawLeftIdx].angle;
            float rootYEnd = scorpLiveComp.LatestSnapshot.localPoses[0].offset.y;
            Assert(scorpLiveComp.IsDeathAnimCompleted && !scorpLiveComp.IsDeathAnimPlaying,
                "Death animation must mark IsDeathAnimCompleted=true upon reaching durationTicks");
            AssertNear(scorpLiveComp.DeathAnimNormalizedProgress, 1f, 1e-5f, "DeathAnimNormalizedProgress must reach 1.0");
            Assert(Mathf.Abs(Mathf.DeltaAngle(angleTick0, angleMid)) > 4f && Mathf.Abs(Mathf.DeltaAngle(angleMid, angleEnd)) > 4f,
                $"Corpse death animation must interpolate continuously across ticks (t0={angleTick0:F1}, mid={angleMid:F1}, end={angleEnd:F1})");
            Assert(Mathf.Abs(rootYEnd - rootYTick0) > 0.25f && Mathf.Abs(rootYMid - rootYTick0) > 0.05f,
                $"Root carapace offset must progressively settle (y0={rootYTick0:F2}, yMid={rootYMid:F2}, yEnd={rootYEnd:F2})");
            Assert(GiantVfxSystem.TotalTriggeredAnimEventsCount >= eventsBefore + 2,
                "MechScorpion deathAnim must fire its timeline VFX/slam events during corpse tick playback");

            // Drain any remaining post-death Bezier tail settling and verify O(1) idle stop
            for (int settle = 0; settle < 50; settle++)
            {
                if (!scorpLiveComp.TickCorpseDeathAnimation(1f, out _))
                {
                    break;
                }
            }
            Assert(!scorpLiveComp.TickCorpseDeathAnimation(1f, out _),
                "Once deathAnim and physics chains settle, TickCorpseDeathAnimation must return false (zero idle CPU overhead)");

            // 4. Vehicle Rigid-Hull Discipline (<isRigid>true</isRigid>) & Reactor Spin Coast-Down on ProtossCarrier, Coaxial Tank Turret on PanzerIV + SoftWhip Settling on VoidLeviathan
            var (carrierRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            string[] carrierRigidIds =
            {
                "command_crest", "prow_left", "prow_right",
                "hangar_bay_left", "hangar_bay_right",
                "hangar_door_left", "hangar_door_right",
                "fin_rear_left", "fin_rear_right", "aft_thruster"
            };
            foreach (string crId in carrierRigidIds)
            {
                int crIdx = Array.FindIndex(carrierRig.SortedNodes, n => n.nodeId == crId);
                Assert(crIdx > 0 && carrierRig.SortedNodes[crIdx].isRigid,
                    $"ProtossCarrier welded hull sub-part '{crId}' must set <isRigid>true</isRigid>");
            }

            var carrierComp = new CompGiantRig();
            carrierComp.Initialize(new CompProperties_GiantRig { rigDef = carrierRig });
            // Attempt procedural offset on a rigid bone -> must remain locked at 0 deg
            carrierComp.SetProceduralBoneAngleOffset("hangar_door_left", -36f);
            carrierComp.BeginDeathAnimation();
            int hullIdx = Array.FindIndex(carrierRig.SortedNodes, n => n.nodeId == "hull_core");
            int coreSpinIdx = Array.FindIndex(carrierRig.SortedNodes, n => n.nodeId == "khaydarin_core");

            float spinDeltaEarly = 0f;
            float spinDeltaLate = 0f;
            float prevSpinAngle = carrierComp.LatestSnapshot.localPoses[coreSpinIdx].angle;
            int carrierDur = Mathf.RoundToInt(carrierRig.deathAnim.durationTicks);
            for (int t = 1; t <= carrierDur; t++)
            {
                carrierComp.TickCorpseDeathAnimation(1f, out _);
                float curSpinAngle = carrierComp.LatestSnapshot.localPoses[coreSpinIdx].angle;
                float dSpin = Mathf.Abs(Mathf.DeltaAngle(prevSpinAngle, curSpinAngle));
                if (t == 3) spinDeltaEarly = dSpin;
                if (t == carrierDur) spinDeltaLate = dSpin;
                prevSpinAngle = curSpinAngle;

                foreach (string crId in carrierRigidIds)
                {
                    int crIdx = Array.FindIndex(carrierRig.SortedNodes, n => n.nodeId == crId);
                    AssertNear(carrierComp.LatestSnapshot.localPoses[crIdx].angle, 0f, 1e-4f,
                        $"Carrier rigid hull sub-part '{crId}' must remain locked at 0 deg during death crash");
                }
            }
            Assert(Mathf.Abs(carrierComp.LatestSnapshot.localPoses[hullIdx].angle) > 12f, "Carrier root hull_core must list visibly on crash");
            Assert(spinDeltaEarly > spinDeltaLate + 0.3f && spinDeltaLate < 0.05f,
                $"Khaydarin core spin must smoothly coast to a stop during death (early={spinDeltaEarly:F3}, late={spinDeltaLate:F3})");

            // Verify Panzer IV rigid hull & coaxial turret sub-parts (11/12 child bones <isRigid>true</isRigid>; only turret_body rotates)
            var (panzerRig, _, panzerAnims) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            string[] panzerRigidIds =
            {
                "lower_hull_tub", "track_left", "track_right", "rear_exhaust",
                "skirt_left", "skirt_right", "bow_mg",
                "turret_skirt_left", "turret_skirt_right", "main_gun", "commander_cupola"
            };
            foreach (string prId in panzerRigidIds)
            {
                int prIdx = Array.FindIndex(panzerRig.SortedNodes, n => n.nodeId == prId);
                Assert(prIdx > 0 && panzerRig.SortedNodes[prIdx].isRigid,
                    $"PanzerIV vehicle sub-part '{prId}' must set <isRigid>true</isRigid>");
            }
            int pzTurretIdx = Array.FindIndex(panzerRig.SortedNodes, n => n.nodeId == "turret_body");
            int pzGunIdx = Array.FindIndex(panzerRig.SortedNodes, n => n.nodeId == "main_gun");
            Assert(!panzerRig.SortedNodes[pzTurretIdx].isRigid, "PanzerIV rotary turret_body must remain articulated (isRigid=false)");

            var pzLocal = new BoneLocalPose[panzerRig.SortedNodes.Length];
            var pzWorld = new BoneWorldPose[panzerRig.SortedNodes.Length];
            var pzMiss = new bool[panzerRig.SortedNodes.Length];
            foreach (GiantAnimDef pzClip in panzerAnims.Values)
            {
                int maxT = Mathf.CeilToInt(pzClip.durationTicks);
                for (int t = 0; t <= maxT; t += 4)
                {
                    pzClip.EvaluateInto(panzerRig, t, pzLocal);
                    SkeletalKinematics.SolveWorldPoses(panzerRig, new Vector2(50f, 50f), 142f, pzLocal, pzMiss, pzWorld);
                    AssertNear(Mathf.DeltaAngle(pzWorld[pzTurretIdx].worldAngleDeg, pzWorld[pzGunIdx].worldAngleDeg), 0f, 1e-4f,
                        $"PanzerIV main_gun must remain 100% coaxial with turret_body in '{pzClip.defName}' @ t={t}");
                    foreach (string prId in panzerRigidIds)
                    {
                        int prIdx = Array.FindIndex(panzerRig.SortedNodes, n => n.nodeId == prId);
                        AssertNear(pzLocal[prIdx].angle, 0f, 1e-4f, $"Rigid PanzerIV bone '{prId}' must have 0 local angle in '{pzClip.defName}'");
                    }
                }
            }

            // Negative validation: GiantRigDef.ConfigErrors() must reject non-zero keyframe angles or steering bindings on <isRigid>true</isRigid> bones
            var badRigidAnim = new GiantAnimDef
            {
                defName = "Test_BadRigidAngleDeath",
                loop = false,
                durationTicks = 40f,
                tracks = new List<BoneAnimTrack>
                {
                    new BoneAnimTrack
                    {
                        nodeId = "root_hull",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f },
                            new BoneKeyframe { tick = 40f, angle = 15f }
                        }
                    },
                    new BoneAnimTrack
                    {
                        nodeId = "rigid_skirt",
                        keyframes = new List<BoneKeyframe>
                        {
                            new BoneKeyframe { tick = 0f, angle = 0f },
                            new BoneKeyframe { tick = 40f, angle = 12f }
                        }
                    }
                }
            };
            var badRigidRig = new GiantRigDef
            {
                defName = "Test_BadRigidVehicleRig",
                deathAnim = badRigidAnim,
                steering = new SteeringConfigDef
                {
                    lagBones = new List<SteeringLagBoneDef> { new SteeringLagBoneDef { boneId = "rigid_skirt", maxBendAngleDeg = 10f } }
                },
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "root_hull", texPath = "Test/Root" },
                    new BoneNodeDef { nodeId = "rigid_skirt", parentId = "root_hull", texPath = "Test/Skirt", isRigid = true }
                }
            };
            badRigidRig.BuildTopology();
            List<string> rigidErrs = badRigidRig.ConfigErrors().ToList();
            Assert(rigidErrs.Any(e => e.Contains("sets non-zero angle") && e.Contains("rigid_skirt")),
                "ConfigErrors() must reject non-zero keyframe angle on <isRigid>true</isRigid> bone");
            Assert(rigidErrs.Any(e => e.Contains("SteeringLagBoneDef") && e.Contains("rigid_skirt")),
                "ConfigErrors() must reject SteeringLagBoneDef targeting <isRigid>true</isRigid> bone");



            Console.WriteLine(
                $"       -> All 9 GiantRigDefs + zh-CN deathAnim labels verified | Negative ConfigErrors gates verified | Corpse tick-by-tick blend, events, spin coast-down & whip settling verified");
        }

        private static void TestRimfxMultiLayerShaderDefsFleckAssetsAndPerformance()
        {
            // 1. Validate Waylith GLSL 450 shader source & strict GLSL-only syntax
            string glslPath = ResolveMod17Path("Shaders", "GCF_RimfxUberVfx.frag.glsl");
            Assert(File.Exists(glslPath), $"Missing Waylith VFX shader: {glslPath}");
            string glsl = File.ReadAllText(glslPath);
            Assert(glsl.StartsWith("#version 450", StringComparison.Ordinal), "GCF_RimfxUberVfx.frag.glsl must start with #version 450");
            foreach (string requiredToken in new[] { "_CoreColor", "_BodyColor", "_EdgeColor", "_VfxParams1", "_VfxParams2", "composeSoftAdd", "fbm3", "segDist", "MODE 8:", "MODE 9:", "MODE 10:" })
            {
                Assert(glsl.Contains(requiredToken, StringComparison.Ordinal), $"Shader missing required symbol '{requiredToken}'");
            }
            foreach (string forbiddenHlsl in new[] { "atan2(", "lerp(", "saturate(", "float2", "float3", "float4", "fixed4", "tex2D(" })
            {
                Assert(!glsl.Contains(forbiddenHlsl, StringComparison.Ordinal), $"Shader contains forbidden HLSL token '{forbiddenHlsl}' in Vulkan GLSL");
            }

            string shadowGlslPath = ResolveMod17Path("Shaders", "GCF_GiantDropShadow.frag.glsl");
            Assert(File.Exists(shadowGlslPath), $"Missing Waylith shadow shader: {shadowGlslPath}");
            string shadowGlsl = File.ReadAllText(shadowGlslPath);
            Assert(shadowGlsl.StartsWith("#version 450", StringComparison.Ordinal), "GCF_GiantDropShadow.frag.glsl must start with #version 450");
            foreach (string forbiddenHlsl in new[] { "atan2(", "lerp(", "saturate(", "float2", "float3", "float4", "fixed4", "tex2D(" })
            {
                Assert(!shadowGlsl.Contains(forbiddenHlsl, StringComparison.Ordinal), $"Shadow shader contains forbidden HLSL token '{forbiddenHlsl}' in Vulkan GLSL");
            }

            // 2. Validate ShaderDefs_GiantVfx.xml (Soft-Additive One / OneMinusSrcAlpha + Stencil Drop Shadow)
            string shaderDefPath = ResolveMod17Path("Defs", "ShaderDefs", "ShaderDefs_GiantVfx.xml");
            Assert(File.Exists(shaderDefPath), $"Missing {shaderDefPath}");
            XDocument shaderDoc = XDocument.Load(shaderDefPath);
            XElement sDef = shaderDoc.Root?.Element("ShaderDef");
            XElement stDef = shaderDoc.Root?.Element("ShaderTypeDef");
            Assert(sDef?.Element("defName")?.Value == "GCF_RimfxUberVfx", "Missing ShaderDef GCF_RimfxUberVfx");
            Assert(stDef?.Element("defName")?.Value == "GCF_RimfxUberVfx" && stDef.Element("shaderPath")?.Value == "Map/GCF_RimfxUberVfx",
                "Missing ShaderTypeDef Map/GCF_RimfxUberVfx");
            XElement prog = sDef.Element("shaderProgram");
            Assert(prog?.Element("blendSrcFactor")?.Value == "One" && prog?.Element("blendDstFactor")?.Value == "OneMinusSrcAlpha",
                "GCF_RimfxUberVfx must use RimFX Premultiplied Soft-Additive blend (One / OneMinusSrcAlpha)");
            Assert(prog?.Element("flipTextureST")?.Value == "false",
                "Procedural GCF_RimfxUberVfx must keep flipTextureST=false");
            XElement shadowDef = shaderDoc.Root?.Elements("ShaderDef").FirstOrDefault(e => e.Element("defName")?.Value == "GCF_GiantDropShadow");
            XElement shadowTypeDef = shaderDoc.Root?.Elements("ShaderTypeDef").FirstOrDefault(e => e.Element("defName")?.Value == "GCF_GiantDropShadow");
            Assert(shadowDef != null && shadowTypeDef?.Element("shaderPath")?.Value == "Map/GCF_GiantDropShadow",
                "Missing GCF_GiantDropShadow ShaderDef / ShaderTypeDef");
            XElement shadowProg = shadowDef.Element("shaderProgram");
            Assert(shadowProg?.Element("flipTextureST")?.Value == "true",
                "GCF_GiantDropShadow must set flipTextureST=true so bone/skinned-mesh sprite textures never invert head-to-tail in ground shadows");
            XElement shadowWrap = shadowProg?.Element("textureWrapOverrides")?.Elements("li")
                .FirstOrDefault(li => li.Element("key")?.Value == "_MainTex");
            Assert(shadowWrap?.Element("value")?.Value == "Clamp",
                "GCF_GiantDropShadow must override _MainTex wrap to Clamp to prevent opposite-edge sprite bleed");
            string fleckDefPath = ResolveMod17Path("Defs", "FleckDefs", "FleckDefs_GiantVfx.xml");
            string vfxTexDir = ResolveMod17Path("Textures", "VFX");
            Assert(!File.Exists(fleckDefPath), $"Non-projectile VFX FleckDefs must be completely removed: {fleckDefPath}");
            Assert(!Directory.Exists(vfxTexDir) || Directory.GetFiles(vfxTexDir, "*.png", SearchOption.AllDirectories).Length == 0,
                $"Non-projectile VFX texture PNGs must be completely removed: {vfxTexDir}");

            // Verify Ranged Projectile sprite textures remain intact on disk across framework + sub-mods
            int verifiedProjSprites = 0;
            foreach (string raceXml in EnumerateAllMod17Files(Path.Combine("Defs", "ThingDefs_Races"), "*.xml"))
            {
                XDocument rDoc = XDocument.Load(raceXml);
                foreach (XElement td in rDoc.Root!.Elements("ThingDef"))
                {
                    if (td.Element("projectile") != null)
                    {
                        string pTex = td.Element("graphicData")?.Element("texPath")?.Value;
                        Assert(!string.IsNullOrWhiteSpace(pTex), $"Ranged projectile '{td.Element("defName")?.Value}' must retain graphicData.texPath");
                        if (pTex.StartsWith("GCF", StringComparison.OrdinalIgnoreCase))
                        {
                            string fullProjPng = ResolveMod17Path("Textures", pTex.Replace('/', Path.DirectorySeparatorChar) + ".png");
                            Assert(File.Exists(fullProjPng), $"Custom ranged projectile sprite texture must remain intact: {fullProjPng}");
                        }
                        verifiedProjSprites++;
                    }
                }
            }
            Assert(verifiedProjSprites >= 4, $"Expected >= 4 ranged projectile sprite textures intact, found {verifiedProjSprites}");

            // 4. Validate Zero VFX on Regular Melee Attacks
            (string rigXml, string animXml, string rigName)[] allRigSpecs =
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3"),
            };
            int verifiedZeroVfxMeleeClips = 0;
            foreach (var (rXml, aXml, rName) in allRigSpecs)
            {
                var (loadedRig, _, loadedAnims) = LoadRigFromXml(rXml, aXml, rName);
                if (loadedRig.meleeAttackAnims != null)
                {
                    foreach (GiantAnimDef mClip in loadedRig.meleeAttackAnims)
                    {
                        Assert(mClip.events == null || mClip.events.Count == 0,
                            $"Regular melee clip '{mClip.defName}' on '{rName}' must emit ZERO VFX events (found {mClip.events?.Count ?? 0})");
                        Assert(mClip.impactTick >= 0f,
                            $"Regular melee clip '{mClip.defName}' on '{rName}' must retain explicit <impactTick>");
                        verifiedZeroVfxMeleeClips++;
                    }
                }
            }
            Assert(verifiedZeroVfxMeleeClips == 3, $"Expected 3 zero-VFX regular melee clips on MechScorpion (vehicle PanzerIV=0), verified {verifiedZeroVfxMeleeClips}");
            Assert(!GiantVfxSystem.TryDetectDualWhipStrikeCrossing(ReadOnlySpan<Vector2>.Empty, ReadOnlySpan<Vector2>.Empty, out _, out _),
                "Empty/missing whip centerline must never trigger crossing");
            // Verify source-level absence of unauthorized crescent air-waves and absence of forward whip-wave dragging on Void Leviathan
            string vfxSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Rendering", "GiantVfxSystem.cs"));
            string skillSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Abilities", "GiantEntitySkillSystem.cs"));
            Assert(vfxSrc.Contains("TryDetectDualWhipStrikeCrossing", StringComparison.Ordinal)
                && vfxSrc.Contains("SpawnDualWhipConvergenceExplosion", StringComparison.Ordinal)
                && !vfxSrc.Contains("BindLayersToDualWhipConvergence", StringComparison.Ordinal)
                && !vfxSrc.Contains("RimfxFollowKind.DualWhipConvergence", StringComparison.Ordinal),
                "GiantVfxSystem must detonate stationary at TryDetectDualWhipStrikeCrossing without dragging explosion forward via DualWhipConvergence");
            Assert(skillSrc.Contains("TickPendingCrossingDetonations", StringComparison.Ordinal)
                && skillSrc.Contains("ExecuteDualWhipCrossingDetonation", StringComparison.Ordinal)
                && !skillSrc.Contains("SpawnSlashArc", StringComparison.Ordinal),
                "GiantEntitySkillSystem must synchronize explosion damage + VFX strictly at dual-whip crossing with zero crescent SlashArc waves");

            // 5. Validate Low-Saturation Atmospheric 3-Tier Triad Ramp & < 0.05 ms/iter execution budget
            Color[] samples =
            {
                new Color(1.0f, 0.72f, 0.26f, 0.95f),
                new Color(0.28f, 0.88f, 1.00f, 0.95f),
                new Color(0.96f, 0.18f, 0.38f, 0.95f)
            };
            for (int i = 0; i < samples.Length; i++)
            {
                GiantVfxSystem.DeriveRimfxTriad(samples[i], out Color core, out Color body, out Color edge);
                Color.RGBToHSV(core, out _, out float sCore, out float vCore);
                Color.RGBToHSV(body, out _, out float sBody, out float vBody);
                Color.RGBToHSV(edge, out _, out float sEdge, out float vEdge);
                Assert(vCore > vBody && vBody > vEdge,
                    $"Invalid atmospheric triad luminance hierarchy for sample {i}: core={vCore:F2}, body={vBody:F2}, edge={vEdge:F2}");
                Assert(sCore <= 0.22f && sBody <= 0.34f && sEdge <= 0.38f,
                    $"AoE triad saturation too high (cartoonish) for sample {i}: sCore={sCore:F2}, sBody={sBody:F2}, sEdge={sEdge:F2}");
            }

            Assert(Enum.GetValues(typeof(GiantVfxSystem.RimfxShaderMode)).Length == 12,
                "Expected 12 RimfxShaderMode entries (modes 0..11)");

            var sw = System.Diagnostics.Stopwatch.StartNew();
            for (int iter = 0; iter < 500; iter++)
            {
                GiantVfxSystem.DeriveRimfxTriad(samples[iter % 3], out _, out _, out _);
                GiantVfxSystem.SpawnShockRing(null, Vector3.zero, 0.2f, 3.0f, samples[1]);
                GiantVfxSystem.SpawnTectonicRift(null, Vector3.zero, 3.2f, samples[2]);
                GiantVfxSystem.SpawnOrdnanceTrailBeam(null, Vector3.zero, new Vector3(4f, 0f, 4f), 0.9f, 12, samples[1]);
                GiantVfxSystem.SpawnKhaydarinWarpPulse(null, Vector3.zero, 2.2f, 16, samples[1], isHexShieldWard: (iter & 1) == 0);
            }
            sw.Stop();
            double avgCallMs = sw.Elapsed.TotalMilliseconds / 500.0;
            Assert(avgCallMs < 0.05, $"GiantVfxSystem overhead exceeded budget: {avgCallMs:F4} ms/iter");
            Console.WriteLine($"       -> Verified pure-shader GCF_RimfxUberVfx (0 VFX textures, {verifiedProjSprites} projectile sprites intact, {verifiedZeroVfxMeleeClips} zero-VFX melee clips, AbyssalDragonBeast stationary dual-whip crossing explosion, low-sat triad & {avgCallMs:F4} ms/iter)");
        }

        private static void TestFourLayerRenderIsolationAndZeroErrorAudit()
        {
            // 1. Verify every [HarmonyPatch] in HarmonyPatches_Rendering resolves cleanly in RimWorld 1.7 Assembly-CSharp
            Assembly gcfAsm = typeof(CompGiantRig).Assembly;
            MethodInfo[] isolationMethods = typeof(HarmonyPatches_Rendering).GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
            int verifiedPatchCount = 0;
            foreach (MethodInfo pm in isolationMethods)
            {
                var attrs = pm.GetCustomAttributes<HarmonyPatch>(inherit: false).ToArray();
                if (attrs.Length == 0)
                {
                    continue;
                }
                Type declType = null;
                string methodName = null;
                Type[] argTypes = null;
                foreach (HarmonyPatch hp in attrs)
                {
                    if (hp.info.declaringType != null) declType = hp.info.declaringType;
                    if (!string.IsNullOrEmpty(hp.info.methodName)) methodName = hp.info.methodName;
                    if (hp.info.argumentTypes != null) argTypes = hp.info.argumentTypes;
                }
                Assert(declType != null && !string.IsNullOrEmpty(methodName), $"Incomplete [HarmonyPatch] on {pm.Name}");
                MethodInfo resolved = argTypes != null
                    ? AccessTools.Method(declType, methodName, argTypes)
                    : AccessTools.Method(declType, methodName);
                Assert(resolved != null, $"Failed to resolve RimWorld 1.7 target {declType.FullName}.{methodName} for {pm.Name}");
                verifiedPatchCount++;
            }
            Assert(verifiedPatchCount >= 13, $"Expected >= 13 rendering/action isolation patches, found {verifiedPatchCount}");

            // 2. Verify Layer 1 matrix sanitization strips external rotation/scale/XZ wiggle while preserving portrait matrices
            Vector3 cleanPos = new Vector3(88.5f, 0.42f, 144.5f);
            Matrix4x4 yayoDirty = Matrix4x4.TRS(
                new Vector3(89.1f, 0.77f, 143.9f),
                Quaternion.Euler(8f, 29f, -14f),
                new Vector3(1.25f, 1f, 0.82f));
            Matrix4x4 sanitized = GiantRenderIsolationGuard.SanitizeGiantRootMatrix(yayoDirty, cleanPos, isPortraitOrCache: false);
            AssertNear(sanitized.GetColumn(3).x, cleanPos.x, 1e-5f, "Sanitized X");
            AssertNear(sanitized.GetColumn(3).y, 0.77f, 1e-5f, "Preserved Y altitude");
            AssertNear(sanitized.GetColumn(3).z, cleanPos.z, 1e-5f, "Sanitized Z");
            AssertNear(Quaternion.Angle(sanitized.rotation, Quaternion.identity), 0f, 1e-3f, "Sanitized identity rotation");
            AssertNear(sanitized.lossyScale.x, 1f, 1e-5f, "Sanitized scale X");
            AssertNear(sanitized.lossyScale.z, 1f, 1e-5f, "Sanitized scale Z");

            Matrix4x4 portraitKept = GiantRenderIsolationGuard.SanitizeGiantRootMatrix(yayoDirty, cleanPos, isPortraitOrCache: true);
            AssertNear(portraitKept.GetColumn(3).x, 89.1f, 1e-5f, "Portrait matrix must remain untouched");

            // 3. Verify Layer 1/3 foreign RenderNode assembly filter & Layer 4 external animation/lasso/execution blocker
            Assert(!GiantRenderIsolationGuard.IsForeignRenderNodeAssembly(typeof(Pawn).Assembly), "Vanilla assembly must be allowed");
            Assert(!GiantRenderIsolationGuard.IsForeignRenderNodeAssembly(gcfAsm), "GCF assembly must be allowed");
            Assert(GiantRenderIsolationGuard.IsForeignRenderNodeAssembly(typeof(Harmony).Assembly), "External mod assembly must be flagged foreign");

            Assert(GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("AM_DoDuel", "AM.Jobs.JobDriver_Duel", "co.uk.epicguru.meleeanimation", false), "Must block AM_DoDuel");
            Assert(GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("AM_ExecuteTarget", "AM.Jobs.JobDriver_Execute", "co.uk.epicguru.meleeanimation", false), "Must block AM_ExecuteTarget");
            Assert(GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("GrappleLasso", "Verse.AI.JobDriver_CastVerbOnce", "co.uk.epicguru.meleeanimation", true), "Must block external Lasso jobDef");
            Assert(GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("YayoDance", "YayoAnimation.JobDriver_Custom", "com.yayo.yayoani", false), "Must block YayoAnimation custom driver");
            Assert(!GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("AttackMelee", "Verse.AI.JobDriver_AttackMelee", "ludeon.rimworld", true), "Must allow vanilla AttackMelee");
            Assert(!GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("PrisonerExecution", "RimWorld.JobDriver_Execute", "ludeon.rimworld", true), "Must allow vanilla PrisonerExecution");
            Assert(!GiantRenderIsolationGuard.ShouldBlockExternalAnimationJob("GCF_ExecuteSpecial", "GiantCreatureFramework.JobDriver_Custom", "sanguo.giantcreatureframework", true), "Must allow GCF jobs");

            // 4. Verify zero missing [StaticConstructorOnStartup] on any GCF type holding Unity asset static fields
            Type[] unityAssetTypes = { typeof(Texture2D), typeof(Material), typeof(Shader), typeof(Graphic), typeof(Mesh), typeof(MaterialPropertyBlock) };
            foreach (Type t in gcfAsm.GetTypes())
            {
                if (t.GetCustomAttribute<StaticConstructorOnStartup>() != null)
                {
                    continue;
                }
                foreach (FieldInfo fi in t.GetFields(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
                {
                    bool isUnityAsset = unityAssetTypes.Any(ut => ut.IsAssignableFrom(fi.FieldType));
                    Assert(!isUnityAsset, $"Type {t.FullName} has static Unity asset field '{fi.Name}' ({fi.FieldType.Name}) without [StaticConstructorOnStartup]!");
                }
            }

            // 5. Verify MainButtons_AuthoringTerminal.xml workerClass & tabWindowClass resolve cleanly in GiantCreatureFramework.dll
            Type workerType = gcfAsm.GetType("GiantCreatureFramework.Agent.UI.MainButtonWorker_AuthoringTerminal");
            Type windowType = gcfAsm.GetType("GiantCreatureFramework.Agent.UI.MainTabWindow_AuthoringTerminal");
            Assert(workerType != null && typeof(RimWorld.MainButtonWorker).IsAssignableFrom(workerType), "Missing MainButtonWorker_AuthoringTerminal");
            Assert(windowType != null && typeof(RimWorld.MainTabWindow).IsAssignableFrom(windowType), "Missing MainTabWindow_AuthoringTerminal");
            Assert(Activator.CreateInstance(workerType) != null && Activator.CreateInstance(windowType) != null, "Failed to instantiate AuthoringTerminal UI stubs");

            Console.WriteLine($"       -> Verified {verifiedPatchCount} isolation patches, matrix/job/flyer guards, 0 missing [StaticConstructorOnStartup], and AuthoringTerminal UI types");
        }

        private static void TestGiantCockpitDualModePatchesAndDefs()
        {
            // 1. Verify every [HarmonyPatch] in HarmonyPatches_VehicleAndTurrets resolves cleanly in RimWorld 1.7 Assembly-CSharp
            MethodInfo[] patchMethods = typeof(HarmonyPatches_VehicleAndTurrets).GetMethods(BindingFlags.Public | BindingFlags.Static);
            int patchCount = 0;
            foreach (MethodInfo pm in patchMethods)
            {
                var attrs = pm.GetCustomAttributes<HarmonyPatch>(inherit: false).ToArray();
                if (attrs.Length == 0)
                {
                    continue;
                }
                Type declType = null;
                string methodName = null;
                Type[] argTypes = null;
                MethodType mType = MethodType.Normal;
                foreach (HarmonyPatch hp in attrs)
                {
                    if (hp.info.declaringType != null) declType = hp.info.declaringType;
                    if (!string.IsNullOrEmpty(hp.info.methodName)) methodName = hp.info.methodName;
                    if (hp.info.argumentTypes != null) argTypes = hp.info.argumentTypes;
                    if (hp.info.methodType.HasValue) mType = hp.info.methodType.Value;
                }
                Assert(declType != null && !string.IsNullOrEmpty(methodName), $"Incomplete [HarmonyPatch] on {pm.Name}");
                MethodBase resolved = mType == MethodType.Getter
                    ? AccessTools.PropertyGetter(declType, methodName)
                    : (argTypes != null ? AccessTools.Method(declType, methodName, argTypes) : AccessTools.Method(declType, methodName));
                Assert(resolved != null, $"Failed to resolve RimWorld 1.7 target {declType.FullName}.{methodName} ({mType}) for {pm.Name}");
                patchCount++;
            }
            Assert(patchCount >= 21, $"Expected >= 21 vehicle/cockpit, null-ThinkTree & anti-game-over Harmony patches, found {patchCount}");

            // Verify ThinkNode_GiantDormantNull returns NoJob safely with zero child nodes
            Verse.AI.ThinkResult dormantRes = ThinkNode_GiantDormantNull.Instance.TryIssueJobPackage(null, default);
            Assert(!dormantRes.IsValid && dormantRes.Job == null, "ThinkNode_GiantDormantNull must return ThinkResult.NoJob");
            Assert(ThinkNode_GiantDormantNull.Instance.FirstNodeOfType<Verse.AI.ThinkNode_Priority>() == null,
                "ThinkNode_GiantDormantNull.FirstNodeOfType must return null without throwing");

            // 2. Verify pilot & gunner skill/consciousness multiplier curves
            float noviceMove = CompGiantCockpit.EvaluatePilotMoveMultiplier(0.10f, 1.0f, 1.0f, 0.88f, 1.28f);
            float aceMove = CompGiantCockpit.EvaluatePilotMoveMultiplier(0.95f, 1.0f, 1.0f, 0.88f, 1.28f);
            Assert(aceMove > noviceMove + 0.20f, $"Ace pilot move multiplier ({aceMove:F3}) must exceed novice ({noviceMove:F3})");

            float soloGunner = CompGiantCockpit.EvaluateGunnerCombatMultiplier(0.85f, 1.0f, 1.0f, 0f, 0.88f, 1.36f);
            float withCommander = CompGiantCockpit.EvaluateGunnerCombatMultiplier(0.85f, 1.0f, 1.0f, 0.10f, 0.88f, 1.36f);
            AssertNear(withCommander - soloGunner, 0.10f, 1e-4f, "Commander fire-control bonus must add +0.10x");

            // 3. Verify XML CompProperties_GiantCockpit seat <-> BodyDef alignment on Panzer IV (3 seats)
            XDocument pzRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_PanzerIV.xml"));
            XElement pzCockpitEl = pzRaceDoc.Descendants("li")
                .FirstOrDefault(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_GiantCockpit");
            Assert(pzCockpitEl != null, "Missing CompProperties_GiantCockpit on GCF_PanzerIV");
            Assert(!ParseBool(pzCockpitEl.Element("autonomousWhenEmpty")?.Value, true),
                "Pure vehicle GCF_PanzerIV must set autonomousWhenEmpty=false so unmanned ThinkTree is nullified");
            List<XElement> pzSeats = pzCockpitEl.Element("seats")!.Elements("li").ToList();
            Assert(pzSeats.Count == 3, $"Expected 3 seats on GCF_PanzerIV (Driver, Gunner, Commander), got {pzSeats.Count}");

            XDocument pzBodyDoc = XDocument.Load(ResolveMod17Path("Defs", "Bodies", "Bodies_PanzerIV.xml"));
            HashSet<string> pzBodyPartDefs = pzBodyDoc.Descendants("BodyDef").First()
                .Descendants("def").Select(d => d.Value).ToHashSet();
            foreach (XElement s in pzSeats)
            {
                string partName = s.Element("linkedBodyPart")!.Value;
                Assert(pzBodyPartDefs.Contains(partName), $"PanzerIV seat references missing BodyPartDef '{partName}'");
            }
            // Verify Commander seat (GCF_PanzerCupola) sits inside Gunner turret subtree (GCF_PanzerTurret) for cascade ejection
            XElement turretNode = pzBodyDoc.Descendants("BodyDef").First().Descendants("li")
                .First(e => e.Element("def")?.Value == "GCF_PanzerTurret");
            Assert(turretNode.Descendants("def").Any(d => d.Value == "GCF_PanzerCupola"),
                "GCF_PanzerCupola must be nested under GCF_PanzerTurret so turret destruction cascades ejection to both Gunner and Commander");

            // 4. Verify JobDef & full ChineseSimplified / English localization key parity
            Assert(File.Exists(ResolveMod17Path("Defs", "JobDefs", "Jobs_GiantCockpit.xml")), "Missing Jobs_GiantCockpit.xml");
            Assert(File.Exists(ResolveMod17Path("Languages", "ChineseSimplified", "DefInjected", "JobDef", "Jobs_GiantCockpit.xml")),
                "Missing ChineseSimplified JobDef translation for GCF_EnterGiantCockpit");

            XDocument cnKeys = XDocument.Load(ResolveMod17Path("Languages", "ChineseSimplified", "Keyed", "GiantCreatureFramework_Keys.xml"));
            XDocument enKeys = XDocument.Load(ResolveMod17Path("Languages", "English", "Keyed", "GiantCreatureFramework_Keys.xml"));
            var cnSet = cnKeys.Root!.Elements().Select(e => e.Name.LocalName).ToHashSet();
            var enSet = enKeys.Root!.Elements().Select(e => e.Name.LocalName).ToHashSet();
            string[] requiredCockpitKeys =
            {
                "GCF_Tab_Cockpit", "GCF_CockpitMode_Piloted", "GCF_CockpitMode_Autonomous", "GCF_CockpitMode_Dormant",
                "GCF_CockpitRole_PrimaryPilot", "GCF_CockpitRole_Gunner", "GCF_CockpitRole_Commander",
                "GCF_Gizmo_AutonomousMode_Label", "GCF_Gizmo_BoardCrew_Label", "GCF_Gizmo_DisembarkAll_Label",
                "GCF_FloatMenu_BoardCockpitSeat", "GCF_CockpitTab_EfficiencySummary", "GCF_CockpitTab_PartDestroyed"
            };
            foreach (string k in requiredCockpitKeys)
            {
                Assert(cnSet.Contains(k) && enSet.Contains(k), $"Missing cockpit translation key '{k}' in CN or EN Keyed XML");
            }
            Assert(cnSet.SetEquals(enSet), "ChineseSimplified and English Keyed XML files must have 1:1 key parity");

            Console.WriteLine($"       -> Verified {patchCount} cockpit/anti-gameover Harmony patches, PanzerIV 3-seat subtree cascade & CN/EN key parity");
        }

        private static void TestZeroBasePawnAttacksAndPartDrivenCombatSystem()
        {
            // 1. Audit all race XML files: zero BaseGun, <tools Inherit="False" /> with 0 <li>, <canMeleeAttack>false</canMeleeAttack>, zero <weaponTags>/<rangedWeaponDef>
            string[] raceFiles = EnumerateAllMod17Files(Path.Combine("Defs", "ThingDefs_Races"), "Races_*.xml");
            Assert(raceFiles.Length == 6 && !raceFiles.Any(f => f.Contains("AegisCenturion", StringComparison.OrdinalIgnoreCase) || f.Contains("Abyssal", StringComparison.OrdinalIgnoreCase)),
                $"Expected 6 active race XML files across framework + 5 sub-mods, got {raceFiles.Length}");
            foreach (string rf in raceFiles)
            {
                XDocument rDoc = XDocument.Load(rf);
                string fn = Path.GetFileName(rf);
                Assert(!rDoc.Root!.Elements("ThingDef").Any(e => e.Attribute("ParentName")?.Value == "BaseGun"),
                    $"{fn} must contain zero BaseGun ThingDefs");
                Assert(!rDoc.Descendants("weaponTags").Any() && !rDoc.Descendants("rangedWeaponDef").Any() && !rDoc.Descendants("catapultWeaponDef").Any(),
                    $"{fn} must contain zero <weaponTags>, <rangedWeaponDef>, or <catapultWeaponDef>");

                foreach (XElement td in rDoc.Root.Elements("ThingDef"))
                {
                    if (td.Element("race") == null) continue;
                    string defName = td.Element("defName")?.Value ?? "<unnamed>";
                    XElement toolsEl = td.Element("tools");
                    Assert(toolsEl != null && toolsEl.Attribute("Inherit")?.Value == "False" && !toolsEl.Elements("li").Any(),
                        $"{fn} giant ThingDef '{defName}' must declare <tools Inherit=\"False\" /> with zero tools");
                }
                foreach (XElement pk in rDoc.Root.Elements("PawnKindDef"))
                {
                    string pkName = pk.Element("defName")?.Value ?? "<unnamed>";
                    Assert(pk.Element("canMeleeAttack")?.Value == "false",
                        $"{fn} PawnKindDef '{pkName}' must declare <canMeleeAttack>false</canMeleeAttack>");
                }
            }

            // 2. Audit all ThinkTrees_*.xml: every giant ThinkTree uses JobGiver_GiantPartCombatPositioning and zero JobGiver_AIFightEnemies / JobGiver_ReactToCloseMeleeThreat
            string[] ttFiles = EnumerateAllMod17Files(Path.Combine("Defs", "ThinkTreeDefs"), "ThinkTrees_*.xml");
            Assert(ttFiles.Length == 6 && !ttFiles.Any(f => f.Contains("AegisCenturion", StringComparison.OrdinalIgnoreCase) || f.Contains("Abyssal", StringComparison.OrdinalIgnoreCase)),
                $"Expected 6 ThinkTree XML files across framework + 5 sub-mods, got {ttFiles.Length}");
            foreach (string tf in ttFiles)
            {
                string txt = File.ReadAllText(tf);
                string fn = Path.GetFileName(tf);
                Assert(txt.Contains("GiantCreatureFramework.JobGiver_GiantPartCombatPositioning"),
                    $"{fn} must wire JobGiver_GiantPartCombatPositioning");
                Assert(!txt.Contains("JobGiver_AIFightEnemies") && !txt.Contains("JobGiver_ReactToCloseMeleeThreat"),
                    $"{fn} must not contain vanilla JobGiver_AIFightEnemies or JobGiver_ReactToCloseMeleeThreat");
            }

            // 3. Audit all GiantRigDefs: every rig has >= 1 BoneNodeDef.partAttacks, 0 ConfigErrors, zero <weaponDefName> on emitters, and zero <events> on Melee clips
            var allRigs = new List<(string label, GiantRigDef rig)>
            {
                ("MechScorpion", LoadMechScorpionFromXml().rig),
                ("MechColossus_S1", LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1").rig),
                ("MechColossus_S2", LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2").rig),
                ("MechColossus_S3", LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3").rig),
                ("ProtossCarrier", LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier").rig),
                ("PanzerIV", LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV").rig)
            };
            foreach (string rigFile in EnumerateAllMod17Files(Path.Combine("Defs", "GiantRigDefs"), "GiantRigDefs_*.xml"))
            {
                string rigFileName = Path.GetFileName(rigFile);
                string suffix = Path.GetFileNameWithoutExtension(rigFileName).Substring("GiantRigDefs_".Length);
                string animFileName = $"GiantAnimDefs_{suffix}.xml";
                if (!File.Exists(ResolveMod17Path("Defs", "GiantAnimDefs", animFileName)))
                {
                    continue;
                }
                XDocument rDoc = XDocument.Load(rigFile);
                foreach (XElement rigEl in rDoc.Root!.Elements().Where(e => e.Name.LocalName.EndsWith("GiantRigDef", StringComparison.Ordinal)))
                {
                    string dName = rigEl.Element("defName")?.Value?.Trim();
                    if (!string.IsNullOrEmpty(dName) && !allRigs.Any(x => string.Equals(x.rig.defName, dName, StringComparison.Ordinal)))
                    {
                        allRigs.Add((suffix, LoadRigFromXml(rigFileName, animFileName, dName).rig));
                    }
                }
            }
            int totalPartAttacks = 0;
            foreach (var (label, rig) in allRigs)
            {
                List<string> errs = rig.ConfigErrors().ToList();
                Assert(errs.Count == 0, $"{label} ConfigErrors: {string.Join("; ", errs)}");
                Assert(!rig.weaponEmitters.Any(em => !string.IsNullOrEmpty(em.weaponDefName)),
                    $"{label} must have zero legacy <weaponDefName> entries in <weaponEmitters>");

                var attacks = rig.nodes.SelectMany(n => n.partAttacks).ToList();
                Assert(attacks.Count > 0, $"{label} must declare at least one BoneNodeDef.partAttacks entry");
                if (rig.IsVehicleRig)
                {
                    Assert(rig.meleeAttackAnims == null || rig.meleeAttackAnims.Count == 0,
                        $"Vehicle rig '{label}' must have zero meleeAttackAnims");
                    Assert(!attacks.Any(a => a.kind == GiantPartAttackKind.Melee),
                        $"Vehicle rig '{label}' must have zero Melee partAttacks");
                }
                totalPartAttacks += attacks.Count;
                foreach (GiantPartAttackDef pa in attacks)
                {
                    if (pa.kind == GiantPartAttackKind.Melee)
                    {
                        Assert(pa.attackAnim != null && !pa.attackAnim.loop && (pa.attackAnim.events == null || pa.attackAnim.events.Count == 0),
                            $"{label} melee partAttack '{pa.attackId}' must have non-looping attackAnim with zero VFX events");
                    }
                    else if (pa.kind == GiantPartAttackKind.Ranged)
                    {
                        Assert(pa.projectileDef != null && pa.attackAnim != null && !pa.attackAnim.loop,
                            $"{label} ranged partAttack '{pa.attackId}' must have projectileDef and non-looping attackAnim");
                    }
                }
            }
            Assert(totalPartAttacks >= 20, $"Expected >= 20 partAttacks across all GiantRigDefs, got {totalPartAttacks}");

            // 4. Audit all AbilityDefs in 1.7/Defs/AbilityDefs: every ability binds to valid BoneNodeDef(s) via CompProperties_AbilityRequiresGiantBone
            int abilityCount = 0;
            foreach (string abFile in EnumerateAllMod17Files(Path.Combine("Defs", "AbilityDefs"), "*.xml"))
            {
                XDocument abDoc = XDocument.Load(abFile);
                foreach (XElement abEl in abDoc.Root!.Elements("AbilityDef"))
                {
                    abilityCount++;
                    string abName = abEl.Element("defName")?.Value ?? "<unnamed>";
                    XElement reqComp = abEl.Element("comps")?.Elements("li")
                        .FirstOrDefault(c => (c.Attribute("Class")?.Value ?? string.Empty).EndsWith("CompProperties_AbilityRequiresGiantBone", StringComparison.Ordinal));
                    Assert(reqComp != null, $"AbilityDef '{abName}' must declare CompProperties_AbilityRequiresGiantBone");
                    var boneIds = reqComp!.Element("requiredBoneIds")?.Elements("li").Select(x => x.Value.Trim()).Where(x => x.Length > 0).ToList() ?? new List<string>();
                    Assert(boneIds.Count > 0, $"AbilityDef '{abName}' must specify >= 1 requiredBoneIds");
                    Assert(allRigs.Any(r => boneIds.All(bid => r.rig.TryGetNodeIndex(bid, out _))),
                        $"AbilityDef '{abName}' requiredBoneIds [{string.Join(", ", boneIds)}] did not match any active GiantRigDef");
                }
            }
            Assert(abilityCount >= 8, $"Expected >= 8 active AbilityDefs across AbilityDefs/*.xml (1 Leviathan + 3 MechColossus + 2 Carrier + 2 PanzerIV + optional extras), got {abilityCount}");

            // 5. Runtime verification: Harmony hard-locks, layered per-bone animation blending while walking, and soft-whip strike override
            Assert(!HarmonyPatches_CombatAndHitbox.CanGiantPerformMelee(null), "CanGiantPerformMelee(null) must be false");
            string[] requiredHardLockPatches =
            {
                "Pawn_TryGetAttackVerb_Prefix",
                "Pawn_TryStartAttack_Prefix",
                "Pawn_MeleeVerbs_TryGetMeleeVerb_Prefix",
                "PawnAttackGizmoUtility_ShouldUseMeleeAttackGizmo_Prefix",
                "JobGiver_AIFightEnemy_TryGiveJob_Prefix",
                "JobGiver_Manhunter_TryGiveJob_Prefix",
                "JobGiver_ReactToCloseMeleeThreat_TryGiveJob_Prefix",
                "AttackTargetFinder_BestAttackTarget_Prefix",
                "AttackTargetFinder_BestShootTargetFromCurrentPosition_Prefix"
            };
            foreach (string pName in requiredHardLockPatches)
            {
                Assert(typeof(HarmonyPatches_CombatAndHitbox).GetMethod(pName, BindingFlags.Public | BindingFlags.Static) != null,
                    $"Missing mandatory base-attack hard-lock patch method {pName}");
            }

            // Layered animation blending: MechScorpion walking stride offset on root carapace is preserved while left claw strikes independently
            GiantRigDef scorpRig = allRigs.First(x => x.label == "MechScorpion").rig;
            var scorpPartRt = new GiantPartCombatRuntime(null);
            scorpPartRt.RebuildFromRig(scorpRig);
            Assert(scorpPartRt.Groups.Count == 4, $"Expected 4 offensive bone groups on MechScorpion (carapace, claw_left, claw_right, tail_stinger), got {scorpPartRt.Groups.Count}");
            BonePartWeaponGroup leftClawGrp = scorpPartRt.Groups.First(g => g.Bone.nodeId == "claw_left");
            leftClawGrp.Phase = PartWeaponPhase.WarmingUp;
            leftClawGrp.ActiveAttack = leftClawGrp.Attacks[0];
            leftClawGrp.AnimSampleTick = leftClawGrp.ActiveAttack.attackAnim.ResolveImpactTick();

            var poses = new BoneLocalPose[scorpRig.SortedNodes.Length];
            for (int i = 0; i < poses.Length; i++) poses[i] = BoneLocalPose.Identity;
            poses[0].offset = new Vector2(0.18f, -0.24f); // Active walking stride bob on root carapace
            Assert(scorpRig.TryGetNodeIndex("claw_left", out int clawLIdx), "Missing claw_left");
            scorpPartRt.ApplyLayeredPartAnimations(scorpRig, isLocomoting: true, poses);
            AssertNear(poses[0].offset.x, 0.18f, 1e-4f, "Layered part animation while locomoting must preserve root stride X offset");
            AssertNear(poses[0].offset.y, -0.24f, 1e-4f, "Layered part animation while locomoting must preserve root stride Y offset");
            Assert(Mathf.Abs(poses[clawLIdx].angle) > 5f, $"Layered claw_left strike clip must rotate claw_left (got {poses[clawLIdx].angle:F2} deg)");

            // Verify MechScorpion gentle Bezier tail sway, zero claw-to-tail interference, and smooth 8-tick abort pose fade-out
            Assert(scorpRig.bezierChains != null && scorpRig.bezierChains.Count == 1 && scorpRig.bezierChains[0].chainId == "tail_main",
                "MechScorpion must declare BezierChainDef 'tail_main' for gentle normal tail sway");
            AssertNear(scorpRig.bezierChains[0].idleWaveAmplitudeDeg, 1.2f, 0.25f, "MechScorpion tail_main must configure gentle idleWaveAmplitudeDeg");
            Assert(scorpRig.TryGetNodeIndex("tail_seg1", out int scTail1Idx), "Missing MechScorpion tail_seg1");
            Assert(scorpRig.TryGetNodeIndex("tail_stinger", out int scTailTipIdx), "Missing MechScorpion tail_stinger");
            AssertNear(poses[scTail1Idx].angle, 0f, 1e-4f, "Front claw_left strike must NOT whip MechScorpion tail_seg1");
            AssertNear(poses[scTailTipIdx].angle, 0f, 1e-4f, "Front claw_left strike must NOT whip MechScorpion tail_stinger");

            BonePartWeaponGroup stingerGrp = scorpPartRt.Groups.First(g => g.Bone.nodeId == "tail_stinger");
            Assert(stingerGrp.DefaultRangeAnchorBoneIndex >= 0, "Multi-segment tail_stinger group must auto-resolve proximal DefaultRangeAnchorBoneIndex");
            stingerGrp.Phase = PartWeaponPhase.WarmingUp;
            stingerGrp.ActiveAttack = stingerGrp.Attacks[0];
            stingerGrp.AnimSampleTick = 10f;
            stingerGrp.AbortActiveCycle(8);
            Assert(stingerGrp.IsFadingOut && stingerGrp.FadeOutTicksLeft == 8, "AbortActiveCycle must enter 8-tick smooth fade-out instead of 1-frame snap");
            var fadePoses = new BoneLocalPose[scorpRig.SortedNodes.Length];
            scorpPartRt.ApplyLayeredPartAnimations(scorpRig, isLocomoting: false, fadePoses);
            float abortStartAngle = Mathf.Abs(fadePoses[scTail1Idx].angle);
            Assert(abortStartAngle > 20f, $"First frame after abort must preserve smooth pose continuity (got {abortStartAngle:F1} deg)");
            for (int ft = 0; ft < 8; ft++) stingerGrp.StepFadeOut();
            Assert(!stingerGrp.IsFadingOut, "Fade-out must complete cleanly after 8 ticks");



            // Vanilla drafted attack commands (FloatMenuUtility.UseRangedAttack / GetRangedAttackAction / GetMeleeAttackAction)
            // now drive giant right-click attack orders directly, and IsValidManualFocusTarget accepts non-hostile pawns & attackable buildings.
            Assert(typeof(HarmonyPatches_CombatAndHitbox).GetMethod(
                nameof(HarmonyPatches_CombatAndHitbox.CanGiantIssueDraftedAttackAction),
                BindingFlags.Public | BindingFlags.Static) != null,
                "HarmonyPatches_CombatAndHitbox must expose CanGiantIssueDraftedAttackAction for vanilla drafted attack routing");
            Assert(!GiantPartCombatRuntime.IsValidManualFocusTarget(null, null),
                "IsValidManualFocusTarget must reject null caster/target");
            var dummyGiant = new Pawn();
            var dummyBuilding = new Verse.Building { def = new ThingDef { defName = "Wall", destroyable = true } };
            Assert(GiantPartCombatRuntime.IsValidManualFocusTarget(dummyGiant, dummyBuilding),
                "IsValidManualFocusTarget must accept attackable building targets when manually ordered");
            Assert(!GiantPartCombatRuntime.IsValidManualFocusTarget(dummyGiant, dummyGiant),
                "IsValidManualFocusTarget must reject self-targeting");

            // Localization parity check for new part-combat keys
            XDocument cnKeys = XDocument.Load(ResolveMod17Path("Languages", "ChineseSimplified", "Keyed", "GiantCreatureFramework_Keys.xml"));
            XDocument enKeys = XDocument.Load(ResolveMod17Path("Languages", "English", "Keyed", "GiantCreatureFramework_Keys.xml"));
            var cnSet = cnKeys.Root!.Elements().Select(e => e.Name.LocalName).ToHashSet();
            var enSet = enKeys.Root!.Elements().Select(e => e.Name.LocalName).ToHashSet();
            foreach (string reqKey in new[]
            {
                "GCF_PartFocusTarget_Label", "GCF_PartFocusTarget_Desc",
                "GCF_PartClearTarget_Label", "GCF_PartClearTarget_Desc",
                "GCF_PartFireAtWill_Label", "GCF_PartFireAtWill_Desc",
                "GCF_PartWeaponsAllSevered", "GCF_FloatMenu_PartFocusAttack"
            })
            {
                Assert(cnSet.Contains(reqKey) && enSet.Contains(reqKey), $"Missing part-combat localization key '{reqKey}'");
            }

            Console.WriteLine($"       -> Verified 0 base-Pawn tools/guns across 6 races, {totalPartAttacks} BoneNodeDef.partAttacks across 8 rigs, 8 bone-bound abilities, 9 hard-lock patches & layered stride+strike runtime");
        }

        private static void TestMechScorpionRearTrailingTailRestAndAttackReturn()
        {
            var (scRig, _, scAnims) = LoadMechScorpionFromXml();
            Assert(scRig.ConfigErrors().Count() == 0, $"GCF_Rig_MechScorpion ConfigErrors: {string.Join("; ", scRig.ConfigErrors())}");
            Assert(scRig.bezierChains != null && scRig.bezierChains.Count == 1, "MechScorpion must declare exactly 1 bezierChain (tail_main)");

            // Enforce part-level turret rule: zero whole-giant <independentTurretRangedAim> tags in XML, and zero turret bones on biological/arachnid rigs
            foreach (string xmlFile in EnumerateAllMod17Files("Defs", "*.xml", SearchOption.AllDirectories))
            {
                string rawXml = File.ReadAllText(xmlFile);
                Assert(!rawXml.Contains("independentTurretRangedAim", StringComparison.Ordinal),
                    $"Legacy whole-giant <independentTurretRangedAim> tag found in {Path.GetFileName(xmlFile)} — turret must be defined per-part (<isTurret> on BoneNodeDef)");
            }
            for (int i = 0; i < scRig.SortedNodes.Length; i++)
            {
                Assert(!scRig.IsBoneInTurretSubtree(i, out _),
                    $"MechScorpion bone '{scRig.SortedNodes[i].nodeId}' must NOT be a turret part");
            }
            var (mcRig3, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            Assert(mcRig3.TryGetNodeIndex("railgun_barrel_left", out int rgLeftIdx) && mcRig3.IsBoneInTurretSubtree(rgLeftIdx, out _),
                "MechColossus Stage3 railgun_barrel_left must inherit part-level turret status from railgun_mount_left");
            Assert(mcRig3.TryGetNodeIndex("wing_pod_left", out int wpLeftIdx) && mcRig3.IsBoneInTurretSubtree(wpLeftIdx, out _),
                "MechColossus Stage3 wing_pod_left must be a turret part");
            Assert(mcRig3.TryGetNodeIndex("core_hull", out int mcCoreIdx) && !mcRig3.IsBoneInTurretSubtree(mcCoreIdx, out _),
                "MechColossus Stage3 core_hull must NOT be a turret part");

            BezierChainDef tailChain = scRig.bezierChains[0];
            Assert(tailChain.chainId == "tail_main" && tailChain.resolvedBoneIndices.Length == 7,
                $"Expected tail_main with 7 resolved bones, got '{tailChain.chainId}' ({tailChain.resolvedBoneIndices.Length})");
            AssertNear(tailChain.tipUV.x, 0.5f, 0.02f, "MechScorpion tail_main tipUV.x");
            AssertNear(tailChain.tipUV.y, 0.21f, 0.03f, "MechScorpion tail_main tipUV.y must match bottom stinger_tip (pixel y=404 -> v=0.21)");

            Assert(scRig.TryGetNodeIndex("carapace", out int carapaceIdx), "Missing carapace");
            Assert(scRig.TryGetNodeIndex("tail_seg1", out int seg1Idx), "Missing tail_seg1");
            Assert(scRig.TryGetNodeIndex("tail_stinger", out int stingerIdx), "Missing tail_stinger");
            BoneNodeDef stingerNode = scRig.SortedNodes[stingerIdx];

            Assert(stingerNode.partAttacks != null && stingerNode.partAttacks.Count == 1, "tail_stinger must own 1 partAttack");
            GiantPartAttackDef barrage = stingerNode.partAttacks[0];
            Assert(barrage.sectorHalfAngleDeg <= 36f, $"scorpion_plasma_barrage sectorHalfAngleDeg ({barrage.sectorHalfAngleDeg}) must be narrow frontal (not a turret)");
            AssertNear(barrage.minRange, 7.5f, 0.1f, "scorpion_plasma_barrage minRange");

            int n = scRig.SortedNodes.Length;
            var localPoses = new BoneLocalPose[n];
            var noMiss = new bool[n];
            var worldPoses = new BoneWorldPose[n];
            var bz = new DampedBezierChainRuntime(tailChain);
            var bzCtx = new BezierChainStepContext { BodyWorldAngleDeg = 90f }; // Facing East (+X)

            GiantAnimDef walkAnim = scAnims["GCF_Anim_MechScorpion_Walk"];
            GiantAnimDef clawLeftAnim = scAnims["GCF_Anim_MechScorpion_ClawLeft"];
            GiantAnimDef rangedAnim = scAnims["GCF_Anim_MechScorpion_RangedTail"];

            Vector2 rootXZ = new Vector2(80.5f, 60.5f);
            float prevStingerAngle = float.NaN;
            float maxIdleAngularStep = 0f;
            float maxClawMeleeStep = 0f;

            // (a) 60 ticks stationary idle + 60 ticks concurrent ClawLeft melee (with stationary root recoil damping) facing East (+X)
            for (int t = 0; t < 120; t++)
            {
                if (t < 60)
                {
                    Array.Fill(localPoses, BoneLocalPose.Identity);
                }
                else
                {
                    clawLeftAnim.EvaluateInto(scRig, (t - 60) % clawLeftAnim.durationTicks, localPoses);
                    localPoses[0].offset *= 0.30f;
                    localPoses[0].angle *= 0.25f;
                }
                bz.Step(scRig, rootXZ, 90f, localPoses, noMiss, 1f, in bzCtx);
                SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, localPoses, noMiss, worldPoses);

                float carapaceX = worldPoses[carapaceIdx].jointWorldXZ.x;
                float prevX = carapaceX;
                for (int k = 0; k < tailChain.resolvedBoneIndices.Length; k++)
                {
                    int bIdx = tailChain.resolvedBoneIndices[k];
                    float jx = worldPoses[bIdx].jointWorldXZ.x;
                    Assert(jx < carapaceX - 1.0f,
                        $"Idle/Melee tick {t}: bone '{scRig.SortedNodes[bIdx].nodeId}' jointX ({jx:F2}) must be behind carapaceX ({carapaceX:F2})");
                    Assert(jx <= prevX + 0.05f,
                        $"Idle/Melee tick {t}: tail X must extend monotonically rearward at '{scRig.SortedNodes[bIdx].nodeId}' ({jx:F2} vs prev {prevX:F2})");
                    prevX = jx;
                }
                Vector2 tipXZ = worldPoses[stingerIdx].UVToWorldXZ(tailChain.tipUV.x, tailChain.tipUV.y);
                Assert(tipXZ.x < prevX - 0.3f && tipXZ.x < carapaceX - 4.0f,
                    $"Idle/Melee tick {t}: stinger_tip ({tipXZ.x:F2}) must extend behind tail_stinger ({prevX:F2}) and carapace ({carapaceX:F2})");

                float curAngle = worldPoses[stingerIdx].worldAngleDeg;
                if (t > 1 && !float.IsNaN(prevStingerAngle))
                {
                    float step = Mathf.Abs(Mathf.DeltaAngle(prevStingerAngle, curAngle));
                    if (t < 60)
                    {
                        if (step > maxIdleAngularStep) maxIdleAngularStep = step;
                    }
                    else
                    {
                        if (step > maxClawMeleeStep) maxClawMeleeStep = step;
                    }
                }
                prevStingerAngle = curAngle;
            }
            Assert(maxIdleAngularStep < 1.5f, $"MechScorpion idle tail angular step ({maxIdleAngularStep:F2} deg/t) must remain gentle (<1.5)");
            Assert(maxClawMeleeStep < 3.5f, $"MechScorpion claw-melee tail angular step ({maxClawMeleeStep:F2} deg/t) must remain smooth (<3.5)");

            // (b) 120 ticks walking forward East (+0.06/t) + 60 ticks reverse backpedaling West (-0.04/t while still facing East 90 deg)
            for (int t = 0; t < 180; t++)
            {
                rootXZ.x += (t < 120) ? 0.06f : -0.04f;
                walkAnim.EvaluateInto(scRig, t % walkAnim.durationTicks, localPoses);
                bz.Step(scRig, rootXZ, 90f, localPoses, noMiss, 1f, in bzCtx);
                SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, localPoses, noMiss, worldPoses);

                float carapaceX = worldPoses[carapaceIdx].jointWorldXZ.x;
                for (int k = 0; k < tailChain.resolvedBoneIndices.Length; k++)
                {
                    int bIdx = tailChain.resolvedBoneIndices[k];
                    float jx = worldPoses[bIdx].jointWorldXZ.x;
                    Assert(jx < carapaceX - 0.8f,
                        $"Locomotion tick {t} ({(t < 120 ? "forward" : "reverse")}): '{scRig.SortedNodes[bIdx].nodeId}' ({jx:F2}) folded ahead of rear threshold ({carapaceX - 0.8f:F2})");
                }
                Vector2 tipXZ = worldPoses[stingerIdx].UVToWorldXZ(tailChain.tipUV.x, tailChain.tipUV.y);
                Assert(tipXZ.x < carapaceX - 3.5f,
                    $"Locomotion tick {t} ({(t < 120 ? "forward" : "reverse")}): stinger_tip ({tipXZ.x:F2}) must stay behind carapace ({carapaceX:F2})");
            }

            // (c) RangedTail overhead volley (projects forward at burst ticks 12..39) -> smooth uncoil back behind carapace by end of clip -> seamless Bezier handoff
            rangedAnim.EvaluateInto(scRig, 21f, localPoses);
            SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, localPoses, noMiss, worldPoses);
            Vector2 volleyTipXZ = worldPoses[stingerIdx].UVToWorldXZ(tailChain.tipUV.x, tailChain.tipUV.y);
            Assert(volleyTipXZ.x > worldPoses[carapaceIdx].jointWorldXZ.x,
                $"During RangedTail volley (t=21), stinger_tip ({volleyTipXZ.x:F2}) must arch forward over carapace ({worldPoses[carapaceIdx].jointWorldXZ.x:F2})");

            rangedAnim.EvaluateInto(scRig, rangedAnim.durationTicks, localPoses);
            SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, localPoses, noMiss, worldPoses);
            Vector2 endClipTipXZ = worldPoses[stingerIdx].UVToWorldXZ(tailChain.tipUV.x, tailChain.tipUV.y);
            float endClipStingerAngle = worldPoses[stingerIdx].worldAngleDeg;
            Assert(endClipTipXZ.x < worldPoses[carapaceIdx].jointWorldXZ.x - 4.0f,
                $"At end of RangedTail (t={rangedAnim.durationTicks}), stinger_tip ({endClipTipXZ.x:F2}) must return behind carapace ({worldPoses[carapaceIdx].jointWorldXZ.x:F2})");

            bz.Reset();
            Array.Fill(localPoses, BoneLocalPose.Identity);
            bz.Step(scRig, rootXZ, 90f, localPoses, noMiss, 1f, in bzCtx);
            SkeletalKinematics.SolveWorldPoses(scRig, rootXZ, 90f, localPoses, noMiss, worldPoses);
            float handoffDelta = Mathf.Abs(Mathf.DeltaAngle(endClipStingerAngle, worldPoses[stingerIdx].worldAngleDeg));
            Assert(handoffDelta < 3.0f, $"Post-RangedTail -> Bezier handoff angular delta ({handoffDelta:F2} deg) must be seamless (<3.0 deg)");

            Console.WriteLine($"       -> MechScorpion rear-trailing tail verified: IdleMaxStep={maxIdleAngularStep:F3} deg/t, ClawMeleeMaxStep={maxClawMeleeStep:F3} deg/t, EndClipTipDeltaX={endClipTipXZ.x - worldPoses[carapaceIdx].jointWorldXZ.x:F2} cells, HandoffDelta={handoffDelta:F3} deg");
        }

        private static float ParseFloat(string s, float fallback)
        {
            if (string.IsNullOrWhiteSpace(s)) return fallback;
            return float.Parse(s.Trim(), CultureInfo.InvariantCulture);
        }

        private static bool ParseBool(string s, bool fallback)
        {
            if (string.IsNullOrWhiteSpace(s)) return fallback;
            return bool.Parse(s.Trim());
        }

        private static Vector2 ParseVec2(string s, Vector2 fallback)
        {
            if (string.IsNullOrWhiteSpace(s)) return fallback;
            string clean = s.Trim().Trim('(', ')');
            string[] parts = clean.Split(',');
            return new Vector2(
                float.Parse(parts[0].Trim(), CultureInfo.InvariantCulture),
                float.Parse(parts[1].Trim(), CultureInfo.InvariantCulture));
        }

        private static void TestArchitecturalFastLookupDecouplingAndBuildBoundaries()
        {
            // 1. Verify zero unguarded TryGetComp / GetComponent<GiantFootprintMapComponent> across all 5 HarmonyPatches_*.cs files
            string patchesDir = Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Patches");
            string[] patchFiles = Directory.GetFiles(patchesDir, "HarmonyPatches_*.cs");
            Assert(patchFiles.Length == 5, $"Expected 5 HarmonyPatches_*.cs files, found {patchFiles.Length}");
            foreach (string pf in patchFiles)
            {
                string src = File.ReadAllText(pf);
                Assert(!src.Contains("TryGetComp<CompGiantRig>", StringComparison.Ordinal),
                    $"Unguarded TryGetComp<CompGiantRig> found in {Path.GetFileName(pf)}; must use GiantFastLookup.TryGetRig");
                Assert(!src.Contains("TryGetComp<CompGiantPhaseTransform>", StringComparison.Ordinal),
                    $"Unguarded TryGetComp<CompGiantPhaseTransform> found in {Path.GetFileName(pf)}; must use GiantFastLookup.TryGetPhaseTransform");
                Assert(!src.Contains("GetComponent<GiantFootprintMapComponent>", StringComparison.Ordinal),
                    $"Slow GetComponent<GiantFootprintMapComponent> found in {Path.GetFileName(pf)}; must use GiantFootprintMapComponent.GetFast");
            }

            // 2. Verify zero TryGetComp in GiantPartCombatSystem.cs and zero hardcoded creature defNames in GiantVfxSystem.cs
            string partCombatSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Combat", "GiantPartCombatSystem.cs"));
            Assert(!partCombatSrc.Contains("TryGetComp<", StringComparison.Ordinal),
                "GiantPartCombatSystem.cs must use GiantFastLookup bitset caches instead of TryGetComp");

            string vfxSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Rendering", "GiantVfxSystem.cs"));
            Assert(!vfxSrc.Contains("\"GCF_ProtossCarrier\"", StringComparison.Ordinal)
                && !vfxSrc.Contains("\"GCF_CarrierInterceptor\"", StringComparison.Ordinal)
                && !vfxSrc.Contains("\"GCF_AbyssalDragonBeast\"", StringComparison.Ordinal)
                && !vfxSrc.Contains("TryGetComp<CompGiantBioferriteCore>", StringComparison.Ordinal),
                "GiantVfxSystem.cs must remain 100% Def/type-driven without hardcoded creature defNames or TryGetComp");

            // 3. Verify explicit [HarmonyPriority] contracts on multi-patch targets
            var ptTakeDmg = typeof(HarmonyPatches_PhaseTransform).GetMethod("Thing_TakeDamage_Prefix")?.GetCustomAttribute<HarmonyLib.HarmonyPriority>();
            var chTakeDmg = typeof(HarmonyPatches_CombatAndHitbox).GetMethod("Thing_TakeDamage_Prefix")?.GetCustomAttribute<HarmonyLib.HarmonyPriority>();
            Assert(ptTakeDmg != null && chTakeDmg != null && ptTakeDmg.info.priority > chTakeDmg.info.priority,
                "PhaseTransform.Thing_TakeDamage_Prefix must have higher priority than CombatAndHitbox.Thing_TakeDamage_Prefix");

            var csTicks = typeof(HarmonyPatches_CollisionAndSelection).GetMethod("Pawn_TicksPerMove_Postfix")?.GetCustomAttribute<HarmonyLib.HarmonyPriority>();
            var vtTicks = typeof(HarmonyPatches_VehicleAndTurrets).GetMethod("Pawn_TicksPerMove_Crew_Postfix")?.GetCustomAttribute<HarmonyLib.HarmonyPriority>();
            Assert(csTicks != null && vtTicks != null && csTicks.info.priority > vtTicks.info.priority,
                "VehicleAndTurrets.Pawn_TicksPerMove_Crew_Postfix must run after CollisionAndSelection so dormant 600f override is final");

            var vtAct = typeof(HarmonyPatches_VehicleAndTurrets).GetMethod("Ability_Activate_Crew_Prefix")?.GetCustomAttribute<HarmonyLib.HarmonyPriority>();
            var chAct = typeof(HarmonyPatches_CombatAndHitbox).GetMethod("Ability_Activate_Prefix")?.GetCustomAttribute<HarmonyLib.HarmonyPriority>();
            Assert(vtAct != null && chAct != null && vtAct.info.priority > chAct.info.priority,
                "VehicleAndTurrets.Ability_Activate_Crew_Prefix must run before CombatAndHitbox.Ability_Activate_Prefix");

            // 4. Verify AuthoringTerminalHost zero-collision delegate bridge & GameComponent_GiantCacheLifecycle
            bool visibleCalled = false;
            GiantCreatureFramework.Agent.UI.AuthoringTerminalHost.RegisterImplementation(
                () => { visibleCalled = true; return true; },
                (_, _) => { },
                new Vector2(900f, 640f));
            var worker = new GiantCreatureFramework.Agent.UI.MainButtonWorker_AuthoringTerminal();
            var win = new GiantCreatureFramework.Agent.UI.MainTabWindow_AuthoringTerminal();
            Assert(worker.Visible && visibleCalled && win.RequestedTabSize == new Vector2(900f, 640f),
                "AuthoringTerminalHost delegate bridge failed to route visibility and window size");
            GiantCreatureFramework.Agent.UI.AuthoringTerminalHost.ClearImplementation();
            Assert(!worker.Visible, "AuthoringTerminalHost.ClearImplementation must hide button by default");

            // 5. Verify modular partial split of CompGiantRig
            string compDir = Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Components");
            Assert(File.Exists(Path.Combine(compDir, "CompGiantRig.SpatialAndMuzzles.cs"))
                && File.Exists(Path.Combine(compDir, "CompGiantRig.RenderingAndOverlays.cs")),
                "CompGiantRig partial domain files must exist");

            Console.WriteLine("       -> Verified 0 unguarded hotpath lookups across 5 patch suites, Priority contracts, 0 VFX hardcoded defNames, CompGiantRig partial split & AuthoringTerminalHost delegate bridge");
        }

        private static void TestTurretRecoilOppositeVectorAndBarrelIsolation()
        {
            var (mc1, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (mc2, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var (mc3, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            var (panzer, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            var (scorp, _, _) = LoadMechScorpionFromXml();

            foreach (var validRig in new[] { mc1, mc2, mc3, panzer })
            {
                List<string> errs = validRig.ConfigErrors().ToList();
                Assert(errs.Count == 0, $"{validRig.defName} ConfigErrors: {string.Join("; ", errs)}");
            }

            // 1. Verify active turret recoil bindings across all 3 MechColossus stages and Panzer IV
            void AssertRecoilBinding(GiantRigDef rig, string firingBoneId, string expectedTargetBoneId, float expectedDist)
            {
                Assert(rig.TryGetNodeIndex(firingBoneId, out int firingIdx), $"{rig.defName} missing bone {firingBoneId}");
                Assert(rig.TryResolveTurretRecoilForFiringBone(firingIdx, out GiantTurretRecoilDef rec, out int targetIdx),
                    $"{rig.defName}:{firingBoneId} failed TryResolveTurretRecoilForFiringBone");
                Assert(rig.SortedNodes[targetIdx].nodeId == expectedTargetBoneId,
                    $"{rig.defName}:{firingBoneId} expected recoil bone '{expectedTargetBoneId}', got '{rig.SortedNodes[targetIdx].nodeId}'");
                AssertNear(rec.distanceCells, expectedDist, 1e-4f, $"{rig.defName}:{firingBoneId} distanceCells");
            }

            AssertRecoilBinding(mc1, "sensor_turret", "sensor_turret", 0.26f);
            AssertRecoilBinding(mc1, "sensor_turret_right", "sensor_turret_right", 0.26f);

            foreach (string s2Pod in new[] { "sensor_turret", "sensor_turret_right" })
                AssertRecoilBinding(mc2, s2Pod, s2Pod, 0.26f);
            AssertRecoilBinding(mc2, "command_head", "command_head", 0.36f);
            foreach (string s2Rail in new[] { "plasma_rail_left", "plasma_rail_right", "plasma_rail_aft_left", "plasma_rail_aft_right" })
                AssertRecoilBinding(mc2, s2Rail, s2Rail, 0.34f);

            AssertRecoilBinding(mc3, "citadel_bridge", "citadel_bridge", 0.48f);
            AssertRecoilBinding(mc3, "railgun_barrel_left", "railgun_barrel_left", 0.56f);
            AssertRecoilBinding(mc3, "railgun_barrel_right", "railgun_barrel_right", 0.56f);
            AssertRecoilBinding(mc3, "railgun_outer_barrel_left", "railgun_outer_barrel_left", 0.44f);
            AssertRecoilBinding(mc3, "railgun_outer_barrel_right", "railgun_outer_barrel_right", 0.44f);
            foreach (string s3Pod in new[] { "wing_pod_left", "wing_pod_right", "aft_wing_pod_left", "aft_wing_pod_right", "sensor_turret", "sensor_turret_right" })
                AssertRecoilBinding(mc3, s3Pod, s3Pod, 0.26f);

            AssertRecoilBinding(panzer, "main_gun", "main_gun", 0.46f);
            AssertRecoilBinding(panzer, "turret_body", "main_gun", 0.46f);

            // Hull weapons and non-turret biological parts must NOT resolve turret recoil
            Assert(panzer.TryGetNodeIndex("bow_mg", out int pzBowMgIdx) && !panzer.TryResolveTurretRecoilForFiringBone(pzBowMgIdx, out _, out _),
                "PanzerIV hull-mounted bow_mg must NOT resolve turret recoil");
            Assert(scorp.TryGetNodeIndex("tail_stinger", out int scTailIdx) && !scorp.TryResolveTurretRecoilForFiringBone(scTailIdx, out _, out _),
                "MechScorpion tail_stinger must NOT resolve turret recoil");

            // 2. Negative ConfigErrors validation gates
            var badRootRig = new GiantRigDef
            {
                defName = "BadRecoilRoot",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "root", texPath = "T/R", turretRecoil = new GiantTurretRecoilDef { distanceCells = 0.2f } }
                },
                deathAnim = panzer.deathAnim
            };
            Assert(badRootRig.ConfigErrors().Any(e => e.Contains("turretRecoil") && e.Contains("root")),
                "ConfigErrors must reject <turretRecoil> on root bone");

            var badNonTurretRig = new GiantRigDef
            {
                defName = "BadRecoilNonTurret",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "root", texPath = "T/R" },
                    new BoneNodeDef { nodeId = "claw", parentId = "root", texPath = "T/C", isTurret = false, turretRecoil = new GiantTurretRecoilDef { distanceCells = 0.2f } }
                },
                deathAnim = panzer.deathAnim
            };
            Assert(badNonTurretRig.ConfigErrors().Any(e => e.Contains("turretRecoil") && e.Contains("claw")),
                "ConfigErrors must reject <turretRecoil> on non-turret part");

            var badParamsRig = new GiantRigDef
            {
                defName = "BadRecoilParams",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "root", texPath = "T/R" },
                    new BoneNodeDef
                    {
                        nodeId = "turret",
                        parentId = "root",
                        texPath = "T/T",
                        isTurret = true,
                        turretRecoil = new GiantTurretRecoilDef { distanceCells = -0.1f, recoveryTicks = 0, recoilBoneId = "root" }
                    }
                },
                deathAnim = panzer.deathAnim
            };
            List<string> paramErrs = badParamsRig.ConfigErrors().ToList();
            Assert(paramErrs.Any(e => e.Contains("distanceCells")), "ConfigErrors must reject non-positive distanceCells");
            Assert(paramErrs.Any(e => e.Contains("recoveryTicks")), "ConfigErrors must reject non-positive recoveryTicks");
            Assert(paramErrs.Any(e => e.Contains("recoilBoneId")), "ConfigErrors must reject non-descendant recoilBoneId");

            // 3. Verify exact opposite-fire-direction vector alignment (-fireDir), monotonic zero-overshoot recovery,
            //    and zero parent-hull / turret-housing displacement across arbitrary headings, X-wing diagonals & off-boresight shots
            void VerifyRecoilTrajectory(
                GiantRigDef rig,
                string firingBoneId,
                float[] hullHeadings,
                float[] fireAnglesDeg,
                string[] parentMustStayZeroBones,
                float scale = 1f)
            {
                Assert(rig.TryGetNodeIndex(firingBoneId, out int firingIdx), $"Missing firing bone {firingBoneId}");
                Assert(rig.TryResolveTurretRecoilForFiringBone(firingIdx, out GiantTurretRecoilDef recDef, out int targetIdx),
                    $"Missing recoil def for {firingBoneId}");

                int n = rig.SortedNodes.Length;
                var restPoses = Enumerable.Repeat(BoneLocalPose.Identity, n).ToArray();
                var recoilOffsets = new Vector2[n];
                var noMiss = new bool[n];
                var restWorld = new BoneWorldPose[n];
                var recoiledWorld = new BoneWorldPose[n];
                Vector2 rootXZ = new Vector2(50.5f, 50.5f);
                Vector2 muzzleUV = rig.SortedNodes[firingIdx].resolvedMuzzleUV;

                foreach (float heading in hullHeadings)
                {
                    SkeletalKinematics.SolveWorldPoses(rig, rootXZ, heading, restPoses, noMiss, restWorld);
                    Vector2 restJoint = restWorld[targetIdx].jointWorldXZ;
                    Vector2 restMuzzle = restWorld[firingIdx].UVToWorldXZ(muzzleUV.x, muzzleUV.y);
                    float boneWorldAng = restWorld[targetIdx].worldAngleDeg;

                    foreach (float fireDeg in fireAnglesDeg)
                    {
                        float fRad = fireDeg * Mathf.Deg2Rad;
                        Vector2 fireDir = new Vector2(MathF.Sin(fRad), MathF.Cos(fRad));
                        Vector2 rightPerp = new Vector2(fireDir.y, -fireDir.x);

                        TurretRecoilState state = default;
                        state.QueueShotImpulse(recDef, fireDeg, scale);

                        float peakBackward = 0f;
                        float prevRecoveryBackward = float.MaxValue;
                        int totalSteps = recDef.kickTicks + recDef.recoveryTicks + 3;

                        for (int t = 0; t <= totalSteps; t++)
                        {
                            float dt = t == 0 ? 0f : 1f;
                            Array.Clear(recoilOffsets, 0, n);
                            recoilOffsets[targetIdx] = state.StepAndEvaluate(dt, boneWorldAng);

                            SkeletalKinematics.SolveWorldPoses(
                                rig,
                                rootXZ,
                                heading,
                                restPoses,
                                noMiss,
                                recoiledWorld,
                                1f,
                                ReadOnlySpan<GiantBoneViewSector>.Empty,
                                -1,
                                recoilOffsets);
                            Vector2 deltaJoint = recoiledWorld[targetIdx].jointWorldXZ - restJoint;
                            Vector2 deltaMuzzle = recoiledWorld[firingIdx].UVToWorldXZ(muzzleUV.x, muzzleUV.y) - restMuzzle;

                            float projFire = Vector2.Dot(deltaJoint, fireDir);
                            float lateral = MathF.Abs(Vector2.Dot(deltaJoint, rightPerp));
                            Assert(projFire <= 1e-5f,
                                $"{rig.defName}:{firingBoneId} @hdg={heading},fire={fireDeg},t={t} overshot forward: proj={projFire:F5}");
                            Assert(lateral <= 1e-5f,
                                $"{rig.defName}:{firingBoneId} @hdg={heading},fire={fireDeg},t={t} drifted laterally: lat={lateral:F5}");
                            Assert((deltaMuzzle - deltaJoint).magnitude <= 1e-4f,
                                $"{rig.defName}:{firingBoneId} @t={t} muzzle displacement mismatch: muzzle={deltaMuzzle} vs joint={deltaJoint}");

                            float backward = -projFire;
                            if (backward > peakBackward)
                            {
                                peakBackward = backward;
                            }
                            if (t >= recDef.kickTicks)
                            {
                                Assert(backward <= prevRecoveryBackward + 1e-5f,
                                    $"{rig.defName}:{firingBoneId} non-monotonic recovery bounce at t={t}: {backward:F4} > {prevRecoveryBackward:F4}");
                                prevRecoveryBackward = backward;
                            }

                            foreach (string zeroBone in parentMustStayZeroBones)
                            {
                                Assert(rig.TryGetNodeIndex(zeroBone, out int zIdx), $"Missing zero check bone {zeroBone}");
                                float zeroDrift = (recoiledWorld[zIdx].jointWorldXZ - restWorld[zIdx].jointWorldXZ).magnitude;
                                Assert(zeroDrift <= 1e-5f,
                                    $"{rig.defName}:{firingBoneId} recoil leaked into '{zeroBone}' (drift={zeroDrift:F5})");
                            }
                        }

                        AssertNear(peakBackward, recDef.distanceCells * scale, 1e-4f,
                            $"{rig.defName}:{firingBoneId} peak recoil mismatch");
                        Assert(!state.active, $"{rig.defName}:{firingBoneId} recoil state did not settle to inactive");
                    }
                }
            }

            float[] sampleHeadings = { 0f, 37.5f, 142.3f, 270f };
            float[] sampleFireAngles = { 0f, 58f, 135f, 225f, 310f };

            VerifyRecoilTrajectory(mc3, "railgun_barrel_left", sampleHeadings, sampleFireAngles,
                new[] { "core_hull", "s3_bow_bastion", "railgun_mount_left", "citadel_bridge" });
            VerifyRecoilTrajectory(mc3, "wing_pod_left", sampleHeadings, sampleFireAngles,
                new[] { "core_hull", "fortress_wing_left", "railgun_outer_mount_left" });
            VerifyRecoilTrajectory(mc3, "railgun_outer_barrel_left", sampleHeadings, sampleFireAngles,
                new[] { "core_hull", "fortress_wing_left", "railgun_outer_mount_left" });
            VerifyRecoilTrajectory(mc2, "command_head", sampleHeadings, new[] { 0f, 45f, 315f },
                new[] { "core_hull", "s2_fore_glacis", "turret_neck" }, scale: 1.15f);
            VerifyRecoilTrajectory(panzer, "main_gun", sampleHeadings, sampleFireAngles,
                new[] { "hull_chassis", "turret_body", "turret_skirt_left", "turret_skirt_right", "commander_cupola" });

            // 4. Rapid burst accumulation must cap at maxAccumulatedCells and settle cleanly with zero overshoot
            GiantTurretRecoilDef wpRec = null;
            bool hasWpRec = mc3.TryGetNodeIndex("wing_pod_right", out int wpRIdx) &&
                            mc3.TryResolveTurretRecoilForFiringBone(wpRIdx, out wpRec, out _);
            Assert(hasWpRec && wpRec != null, "Missing wing_pod_right recoil");
            TurretRecoilState burstState = default;
            for (int b = 0; b < 5; b++)
            {
                burstState.QueueShotImpulse(wpRec, 90f, 1f);
                Vector2 bOff = burstState.StepAndEvaluate(1f, 0f);
                Assert(bOff.x <= 1e-5f, $"Burst firing East must never recoil East (+X): x={bOff.x}");
                Assert(MathF.Abs(bOff.y) <= 1e-5f, $"Burst firing East must stay strictly collinear along -X: y={bOff.y}");
                Assert(-bOff.x <= wpRec.EffectiveMaxAccumulatedCells + 1e-4f,
                    $"Burst accumulation {-bOff.x:F3} exceeded maxAccumulatedCells {wpRec.EffectiveMaxAccumulatedCells:F3}");
            }
            for (int r = 0; r <= wpRec.kickTicks + wpRec.recoveryTicks + 2; r++)
            {
                burstState.StepAndEvaluate(1f, 0f);
            }
            Assert(!burstState.active && MathF.Abs(burstState.currentDisplacementCells) <= 1e-5f,
                "Rapid-burst recoil state must fully reset to 0");

            Console.WriteLine("       -> Verified <turretRecoil> on all Colossus (S1/S2/S3) & Panzer IV turrets: exact -fireDir vector across 360 deg, barrel-only isolation, maxAccumulatedCells cap & monotonic zero-overshoot recuperation");
        }

        private static VehicleLocomotionDef ParseVehicleLocomotionXml(XElement vEl)
        {
            if (vEl == null) return null;
            var def = new VehicleLocomotionDef
            {
                allowPivotTurnInPlace = ParseBool(vEl.Element("allowPivotTurnInPlace")?.Value, true),
                pivotTurnEnterAngleDeg = ParseFloat(vEl.Element("pivotTurnEnterAngleDeg")?.Value, 32f),
                pivotTurnExitAngleDeg = ParseFloat(vEl.Element("pivotTurnExitAngleDeg")?.Value, 8f),
                pivotTurnRateDegPerTick = ParseFloat(vEl.Element("pivotTurnRateDegPerTick")?.Value, 1.8f),
                movingTurnRateDegPerTick = ParseFloat(vEl.Element("movingTurnRateDegPerTick")?.Value, 1.1f),
                turnSpeedMinFactor = ParseFloat(vEl.Element("turnSpeedMinFactor")?.Value, 0.55f),
                minTurnRadiusCells = ParseFloat(vEl.Element("minTurnRadiusCells")?.Value, 3.8f),
                maxSlipAngleDeg = ParseFloat(vEl.Element("maxSlipAngleDeg")?.Value, 18f),
                accelerationCellsPerSec2 = ParseFloat(vEl.Element("accelerationCellsPerSec2")?.Value, 1.9f),
                brakingCellsPerSec2 = ParseFloat(vEl.Element("brakingCellsPerSec2")?.Value, 4.6f),
                handbrakeCellsPerSec2 = ParseFloat(vEl.Element("handbrakeCellsPerSec2")?.Value, 9.5f),
                gearShiftPauseTicks = (int)ParseFloat(vEl.Element("gearShiftPauseTicks")?.Value, 10f),
                allowReverse = ParseBool(vEl.Element("allowReverse")?.Value, true),
                reverseMinHeadingErrorDeg = ParseFloat(vEl.Element("reverseMinHeadingErrorDeg")?.Value, 115f),
                reverseSpeedMultiplier = ParseFloat(vEl.Element("reverseSpeedMultiplier")?.Value, 0.40f),
                maxReverseDistanceCells = ParseFloat(vEl.Element("maxReverseDistanceCells")?.Value, 8.5f),
                lookaheadMinCells = ParseFloat(vEl.Element("lookaheadMinCells")?.Value, 2.0f),
                lookaheadMaxCells = ParseFloat(vEl.Element("lookaheadMaxCells")?.Value, 3.6f),
                lockHullHeadingWhenParked = ParseBool(vEl.Element("lockHullHeadingWhenParked")?.Value, true),
                allowHullTraverseForFixedWeapons = ParseBool(vEl.Element("allowHullTraverseForFixedWeapons")?.Value, false),
                stabilizeTurretsAgainstHullTurn = ParseBool(vEl.Element("stabilizeTurretsAgainstHullTurn")?.Value, true),
                movingFireAccuracyFactor = ParseFloat(vEl.Element("movingFireAccuracyFactor")?.Value, 0.78f),
                requireHaltToFireWhenSingleCrew = ParseBool(vEl.Element("requireHaltToFireWhenSingleCrew")?.Value, false),
                autoBindRollingTrackParentBones = ParseBool(vEl.Element("autoBindRollingTrackParentBones")?.Value, true),
                immobilizeWhenAnySideDestroyed = ParseBool(vEl.Element("immobilizeWhenAnySideDestroyed")?.Value, true),
                damagedDriveMinSpeedFactor = ParseFloat(vEl.Element("damagedDriveMinSpeedFactor")?.Value, 0.35f),
                suppressBiologicalGait = ParseBool(vEl.Element("suppressBiologicalGait")?.Value, true),
                accelSquatOffset = ParseFloat(vEl.Element("accelSquatOffset")?.Value, 0f),
                brakeDiveOffset = ParseFloat(vEl.Element("brakeDiveOffset")?.Value, 0f)
            };
            if (Enum.TryParse(vEl.Element("chassisType")?.Value, true, out VehicleChassisType ct))
            {
                def.chassisType = ct;
            }
            return def;
        }

        private static void TestDecoupledGroundVehicleLocomotionAndCrossGiantIsolation()
        {
            // 1. Cross-Giant Zero-Impact Decoupling Audit:
            //    Every biological, arachnid/mech walker, wyvern, and aerial carrier rig MUST have ActiveVehicleLocomotion == null
            //    and VehicleLocomotionSystem.cs must contain zero hardcoded creature/vehicle defNames.
            string vehSysSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Vehicle", "VehicleLocomotionSystem.cs"));
            foreach (string forbiddenName in new[]
            {
                "GCF_PanzerIV", "GCF_Behemoth", "GCF_AbyssalDragonBeast",
                "GCF_MechScorpion", "GCF_MechColossus", "GCF_ProtossCarrier"
            })
            {
                Assert(!vehSysSrc.Contains($"\"{forbiddenName}\"", StringComparison.Ordinal),
                    $"VehicleLocomotionSystem.cs must be 100% Def-driven without hardcoded '{forbiddenName}'");
            }

            (string rigFile, string animFile, string defName)[] nonVehicleRigs =
            {
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos"),
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier")
            };
            foreach (var (rf, af, dn) in nonVehicleRigs)
            {
                var (nvRig, _, _) = LoadRigFromXml(rf, af, dn);
                Assert(nvRig.ActiveVehicleLocomotion == null,
                    $"Non-vehicle rig '{dn}' must have ActiveVehicleLocomotion == null to preserve 100% original movement & steering");
                Assert(nvRig.SortedNodes.All(b => !b.isLocomotionDrivePart),
                    $"Non-vehicle rig '{dn}' must not mark any bone as isLocomotionDrivePart");
            }

            // 2. Load GCF_Rig_PanzerIV and verify VehicleLocomotionDef schema, 0 ConfigErrors & zero waddle angles on Walk/Run
            var (pzRig, _, pzAnims) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            List<string> pzErrs = pzRig.ConfigErrors().ToList();
            Assert(pzErrs.Count == 0, $"GCF_Rig_PanzerIV ConfigErrors: {string.Join("; ", pzErrs)}");

            VehicleLocomotionDef pzVehDef = pzRig.ActiveVehicleLocomotion;
            Assert(pzVehDef != null && pzVehDef.chassisType == VehicleChassisType.Tracked,
                "GCF_Rig_PanzerIV must configure ActiveVehicleLocomotion with chassisType=Tracked");
            Assert(pzVehDef.resolvedDriveBones.Length == 2 && pzVehDef.hasPortDriveGroup && pzVehDef.hasStarboardDriveGroup,
                $"Expected 2 resolved port/starboard drive bones on PanzerIV, got {pzVehDef.resolvedDriveBones.Length}");

            foreach (string locoClipName in new[] { "GCF_Anim_PanzerIV_Walk", "GCF_Anim_PanzerIV_Run" })
            {
                GiantAnimDef clip = pzAnims[locoClipName];
                for (float t = 0f; t <= clip.durationTicks; t += 4f)
                {
                    var sample = new BoneLocalPose[pzRig.SortedNodes.Length];
                    clip.EvaluateInto(pzRig, t, sample);
                    AssertNear(sample[0].angle, 0f, 1e-5f, $"{locoClipName} @ t={t} must have 0 deg biological yaw waddle on steel hull_chassis");
                }
            }

            // 3. Tracked Neutral Pivot-Turn + Throttle Acceleration + Arrival Braking + Zero Lateral Crab-Slide
            int n = pzRig.SortedNodes.Length;
            var noMissing = new bool[n];
            var fullHp = Enumerable.Repeat(1f, n).ToArray();
            var rt = new VehicleLocomotionRuntime(pzRig, pzVehDef);
            Vector2 startXZ = new Vector2(50.5f, 50.5f);
            rt.Reset(0f, startXZ); // Parked facing 0 deg North

            Vector2[] eastPath = { new Vector2(64.5f, 50.5f) }; // 14 cells due East (90 deg off bow -> > 32 deg pivot threshold)
            int pivotTicks = 0;
            float maxPosDriftDuringPivot = 0f;
            float maxLateralCrabSlide = 0f;
            float peakForwardSpeedPerSec = 0f;
            bool sawForwardDriving = false;
            bool sawArrivalBraking = false;
            float leftTrackPivotScroll = 0f;
            float rightTrackPivotScroll = 0f;

            for (int tick = 0; tick < 360; tick++)
            {
                rt.StepHeadlessAlongPath(eastPath, 4.6f, noMissing, fullHp);
                if (MathF.Abs(rt.LastStepLateralDriftCells) > maxLateralCrabSlide)
                {
                    maxLateralCrabSlide = MathF.Abs(rt.LastStepLateralDriftCells);
                }

                if (rt.DriveState == VehicleDriveState.PivotTurning)
                {
                    pivotTicks++;
                    float drift = Vector2.Distance(rt.ExactVehiclePosXZ, startXZ);
                    if (drift > maxPosDriftDuringPivot) maxPosDriftDuringPivot = drift;
                    GiantRollingTrackKinematics.ComputeDifferentialStep(
                        rt.LastStepSignedForwardCells,
                        rt.LastStepHullDeltaDeg,
                        1.92f,
                        out float lStep,
                        out float rStep);
                    leftTrackPivotScroll += lStep;
                    rightTrackPivotScroll += rStep;
                }
                else if (rt.DriveState == VehicleDriveState.ForwardDriving)
                {
                    sawForwardDriving = true;
                    if (rt.CurrentSignedSpeedCellsPerSec > peakForwardSpeedPerSec)
                    {
                        peakForwardSpeedPerSec = rt.CurrentSignedSpeedCellsPerSec;
                    }
                }
                else if (rt.DriveState == VehicleDriveState.Braking && sawForwardDriving)
                {
                    sawArrivalBraking = true;
                }

                if (sawForwardDriving && Vector2.Distance(rt.ExactVehiclePosXZ, eastPath[0]) <= 0.12f)
                {
                    // Let vehicle settle after reaching destination
                    for (int s = 0; s < 25; s++)
                    {
                        rt.StepHeadlessAlongPath(ReadOnlySpan<Vector2>.Empty, 4.6f, noMissing, fullHp);
                    }
                    break;
                }
            }

            Assert(pivotTicks >= 35, $"Tracked 90-deg turn must execute multi-tick Neutral Pivot Turn first, got pivotTicks={pivotTicks}");
            Assert(maxPosDriftDuringPivot <= 1e-5f, $"Vehicle must not translate while PivotTurning in place, drift={maxPosDriftDuringPivot:E3}");
            Assert(leftTrackPivotScroll > 1.5f && rightTrackPivotScroll < -1.5f,
                $"Clockwise right pivot must counter-scroll tracks differentially (L={leftTrackPivotScroll:F2} > 0, R={rightTrackPivotScroll:F2} < 0)");
            Assert(maxLateralCrabSlide <= 1e-5f, $"Tracked non-holonomic lateral crab-slide must be 0, got {maxLateralCrabSlide:E3}");
            Assert(sawForwardDriving && peakForwardSpeedPerSec > 3.2f && peakForwardSpeedPerSec <= 4.61f,
                $"Expected smooth throttle ramp to ~4.6 cells/s, peak={peakForwardSpeedPerSec:F2}");
            Assert(sawArrivalBraking && rt.DriveState == VehicleDriveState.Parked && MathF.Abs(rt.CurrentSignedSpeedCellsPerSec) <= 1e-4f,
                $"Vehicle must brake smoothly to Parked (state={rt.DriveState}, spd={rt.CurrentSignedSpeedCellsPerSec:F4})");
            AssertNear(Mathf.DeltaAngle(rt.HullHeadingDeg, 90f), 0f, 2.0f, "Final parked hull heading must align East (~90 deg)");

            // 4. Grid Staircase Lookahead Smoothing (eliminates 45/90-deg discrete path fishtailing)
            var staircase = new List<Vector2>();
            for (int k = 1; k <= 12; k++)
            {
                staircase.Add(new Vector2(50.5f + k, 50.5f + (k / 2)));
            }
            rt.Reset(63.4f, new Vector2(50.5f, 50.5f));
            float maxHeadingJitter = 0f;
            float prevHdg = rt.HullHeadingDeg;
            for (int tick = 0; tick < 90; tick++)
            {
                rt.StepHeadlessAlongPath(staircase.ToArray(), 4.6f, noMissing, fullHp);
                float dH = MathF.Abs(Mathf.DeltaAngle(prevHdg, rt.HullHeadingDeg));
                if (dH > maxHeadingJitter) maxHeadingJitter = dH;
                prevHdg = rt.HullHeadingDeg;
            }
            Assert(maxHeadingJitter <= 1.2f && MathF.Abs(Mathf.DeltaAngle(rt.HullHeadingDeg, 63.4f)) <= 8.5f,
                $"Lookahead carrot must smooth discrete staircase without fishtailing (hdg={rt.HullHeadingDeg:F1}, maxStep={maxHeadingJitter:F2})");

            // 5. Short-Range Tactical Reverse Gear (<= 8.5 cells astern, >= 115 deg -> backs up keeping front armor East!)
            Vector2 revOrigin = new Vector2(64.5f, 50.5f);
            rt.Reset(90f, revOrigin); // Facing 90 deg East
            Vector2[] reversePath = { new Vector2(59.0f, 50.5f) }; // 5.5 cells due West (180 deg astern)
            bool sawReverseState = false;
            float minSignedReverseSpeed = 0f;
            float maxHullDeviationFromEast = 0f;
            for (int tick = 0; tick < 260; tick++)
            {
                rt.StepHeadlessAlongPath(reversePath, 4.6f, noMissing, fullHp);
                if (rt.DriveState == VehicleDriveState.ReverseDriving)
                {
                    sawReverseState = true;
                }
                if (rt.CurrentSignedSpeedCellsPerSec < minSignedReverseSpeed)
                {
                    minSignedReverseSpeed = rt.CurrentSignedSpeedCellsPerSec;
                }
                float dev = MathF.Abs(Mathf.DeltaAngle(90f, rt.HullHeadingDeg));
                if (dev > maxHullDeviationFromEast) maxHullDeviationFromEast = dev;
                if (Vector2.Distance(rt.ExactVehiclePosXZ, reversePath[0]) <= 0.12f)
                {
                    break;
                }
            }
            Assert(sawReverseState && minSignedReverseSpeed < -1.2f && minSignedReverseSpeed >= -(4.6f * pzVehDef.reverseSpeedMultiplier + 0.05f),
                $"Expected ReverseDriving at ~-1.84 cells/s, got minSpd={minSignedReverseSpeed:F2}");
            Assert(maxHullDeviationFromEast <= 2.0f,
                $"ReverseDriving must keep front glacis facing East (90 deg) without 180-deg U-turn, maxDev={maxHullDeviationFromEast:F2}");
            Assert(rt.ExactVehiclePosXZ.x < revOrigin.x - 4.8f, $"Expected >= 4.8 cells westward reverse travel, pos={rt.ExactVehiclePosXZ}");

            // 6. Wheeled Ackermann Kinematics (zero turn at zero speed; omega <= |v|/R_min; negative ConfigErrors validation)
            var wheeledDef = new VehicleLocomotionDef
            {
                chassisType = VehicleChassisType.Wheeled,
                allowPivotTurnInPlace = false,
                minTurnRadiusCells = 4.0f,
                movingTurnRateDegPerTick = 2.5f,
                accelerationCellsPerSec2 = 3.2f,
                brakingCellsPerSec2 = 6.8f
            };
            var wheeledRt = new VehicleLocomotionRuntime(pzRig, wheeledDef);
            wheeledRt.Reset(0f, new Vector2(50.5f, 50.5f));
            // Stationary aim request must produce 0 deg/tick on Wheeled chassis!
            wheeledRt.StepHeadlessAlongPath(ReadOnlySpan<Vector2>.Empty, 6.5f, noMissing, fullHp, hasStationaryAimRequest: true, stationaryAimDeg: 90f);
            AssertNear(wheeledRt.HullHeadingDeg, 0f, 1e-5f, "Wheeled chassis must have strictly 0 deg/tick turn rate when stationary (v == 0)");

            Vector2[] wideArcPath = { new Vector2(68.5f, 68.5f) };
            for (int tick = 0; tick < 80; tick++)
            {
                wheeledRt.StepHeadlessAlongPath(wideArcPath, 6.5f, noMissing, fullHp);
                float vCellsPerTick = MathF.Abs(wheeledRt.CurrentSignedSpeedCellsPerTick);
                float ackermannBound = (vCellsPerTick / wheeledDef.minTurnRadiusCells) * Mathf.Rad2Deg + 1e-4f;
                Assert(MathF.Abs(wheeledRt.LastStepHullDeltaDeg) <= ackermannBound,
                    $"Wheeled turn step ({MathF.Abs(wheeledRt.LastStepHullDeltaDeg):F4}) exceeded Ackermann |v|/R_min bound ({ackermannBound:F4}) at tick {tick}");
            }

            var invalidWheeled = new VehicleLocomotionDef { chassisType = VehicleChassisType.Wheeled, minTurnRadiusCells = 0f };
            Assert(invalidWheeled.ValidateConfig("BadWheeled").Any(e => e.Contains("minTurnRadiusCells")),
                "ValidateConfig must reject Wheeled chassis with minTurnRadiusCells <= 0.25");

            // 7. Part-Level Decoupling: Skirt vs Track Damage vs Turret Operation + World-Space Turret Gyro Stabilization
            Assert(pzRig.TryGetNodeIndex("skirt_left", out int skirtLIdx), "Missing skirt_left");
            Assert(pzRig.TryGetNodeIndex("track_left", out int trackLIdx), "Missing track_left");
            Assert(pzRig.TryGetNodeIndex("turret_body", out int turretIdx), "Missing turret_body");
            Assert(pzRig.TryGetNodeIndex("main_gun", out int gunIdx), "Missing main_gun");
            Assert(pzRig.TryGetNodeIndex("bow_mg", out int bowMgIdx), "Missing bow_mg");

            // (a) Severing armor side skirt has ZERO effect on vehicle drive mobility
            var testMask = new bool[n];
            var testHp = Enumerable.Repeat(1f, n).ToArray();
            testMask[skirtLIdx] = true;
            rt.EvaluateDriveMobility(testMask, testHp);
            Assert(!rt.IsDriveImmobilized && MathF.Abs(rt.DriveMobilitySpeedFactor - 1f) < 1e-5f,
                "Severing non-drive skirt_left must have zero impact on vehicle mobility");

            // (b) Damaging track_left below 50% HP degrades mobility smoothly without immobilizing
            Array.Clear(testMask, 0, n);
            testHp[trackLIdx] = 0.25f;
            rt.EvaluateDriveMobility(testMask, testHp);
            Assert(!rt.IsDriveImmobilized && rt.DriveMobilitySpeedFactor > 0.35f && rt.DriveMobilitySpeedFactor < 0.95f,
                $"25% HP track_left must degrade speed factor smoothly, got {rt.DriveMobilitySpeedFactor:F2}");

            // (c) Severing track_left immobilizes hull (speedFactor = 0), while turret_body + main_gun still traverse 360 deg & resolve muzzle!
            testMask[trackLIdx] = true;
            testHp[trackLIdx] = 0f;
            rt.EvaluateDriveMobility(testMask, testHp);
            Assert(rt.IsDriveImmobilized && rt.DriveMobilitySpeedFactor == 0f,
                "Severing track_left must immobilize vehicle hull");

            var steerRt = new GiantSteeringRuntime(pzRig);
            steerRt.Reset(0f);
            var localPoses = new BoneLocalPose[n];
            var worldPoses = new BoneWorldPose[n];
            Vector2 rootXZ = new Vector2(50.5f, 50.5f);
            for (int t = 0; t < 90; t++)
            {
                Array.Fill(localPoses, BoneLocalPose.Identity);
                var ctx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 90f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = true,
                    SteeringEnabled = true,
                    IntensityScale = 1f,
                    HasLookTargetWorldXZ = true,
                    LookTargetWorldXZ = new Vector2(75.5f, 50.5f),
                    StabilizeTurretsAgainstHullTurn = true
                };
                steerRt.ApplyBoneSteering(pzRig, 0f, localPoses, testMask, 1f, in ctx, rootXZ);
            }
            SkeletalKinematics.SolveWorldPoses(pzRig, rootXZ, 0f, localPoses, testMask, worldPoses);
            Vector2 lookTargetEastXZ = new Vector2(75.5f, 50.5f);
            float expectedTurretWorldDeg = VehicleLocomotionRuntime.BearingDegFromDelta(lookTargetEastXZ - worldPoses[turretIdx].jointWorldXZ);
            AssertNear(Mathf.DeltaAngle(worldPoses[gunIdx].worldAngleDeg, expectedTurretWorldDeg), 0f, 0.25f,
                "Immobilized tank with severed track_left must still traverse turret_body & main_gun onto exact East target bearing");

            // (d) World-space turret gyro stabilization while hull pivots 0 -> 54 deg (+1.8 deg/tick):
            //     main_gun stays locked onto exact world target bearing (< 0.12 deg drift), while hull-fixed bow_mg rotates rigidly with hull!
            Array.Clear(testMask, 0, n);
            float hullDeg = 0f;
            float maxGunWorldDrift = 0f;
            for (int t = 0; t < 30; t++)
            {
                hullDeg += 1.8f;
                Array.Fill(localPoses, BoneLocalPose.Identity);
                var stabCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = hullDeg,
                    DesiredLookHeadingDeg = 90f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = true,
                    IsMoving = true,
                    SteeringEnabled = true,
                    IntensityScale = 1f,
                    HasLookTargetWorldXZ = true,
                    LookTargetWorldXZ = lookTargetEastXZ,
                    LastBodyHeadingStepDeg = 1.8f,
                    StabilizeTurretsAgainstHullTurn = true
                };
                steerRt.ApplyBoneSteering(pzRig, hullDeg, localPoses, testMask, 1f, in stabCtx, rootXZ);
                SkeletalKinematics.SolveWorldPoses(pzRig, rootXZ, hullDeg, localPoses, testMask, worldPoses);
                float exactTargetBrg = VehicleLocomotionRuntime.BearingDegFromDelta(lookTargetEastXZ - worldPoses[turretIdx].jointWorldXZ);
                float gunErr = MathF.Abs(Mathf.DeltaAngle(worldPoses[gunIdx].worldAngleDeg, exactTargetBrg));
                if (gunErr > maxGunWorldDrift) maxGunWorldDrift = gunErr;
            }
            Assert(maxGunWorldDrift <= 0.20f,
                $"Gyro-stabilized turret gun drifted {maxGunWorldDrift:F4} deg from target during +54 deg hull pivot (expected <= 0.20 deg)");
            AssertNear(worldPoses[bowMgIdx].worldAngleDeg, 54f, 1e-4f,
                "Hull-fixed bow_mg (isTurret=false) must remain strictly bound to hull heading (54 deg)");

            // (e) Severing turret_body leaves drive mobility 100% intact
            testMask[turretIdx] = true;
            CompGiantRig.PropagateTopologicalBoneMissingMask(pzRig.SortedNodes, testMask);
            rt.EvaluateDriveMobility(testMask, fullHp);
            Assert(!rt.IsDriveImmobilized && MathF.Abs(rt.DriveMobilitySpeedFactor - 1f) < 1e-5f,
                "Severing turret_body must have zero impact on chassis drive-track mobility");

            Console.WriteLine($"       -> Verified 8 non-vehicle rigs untouched, Tracked Pivot ({pivotTicks}t, crab={maxLateralCrabSlide:E2}), Reverse ({minSignedReverseSpeed:F2} c/s, hdgDev={maxHullDeviationFromEast:F2} deg), Wheeled R_min, Drive/Turret part isolation & Turret Gyro (drift={maxGunWorldDrift:F4} deg)");
        }

        private static GiantFlightDef ParseFlightLocomotionXml(XElement fEl, Dictionary<string, GiantAnimDef> anims)
        {
            if (fEl == null) return null;
            var def = new GiantFlightDef
            {
                flightSpeedMultiplier = ParseFloat(fEl.Element("flightSpeedMultiplier")?.Value, 1.0f),
                worldFlightSpeedMultiplier = ParseFloat(fEl.Element("worldFlightSpeedMultiplier")?.Value, 0f),
                takeoffDurationTicks = (int)ParseFloat(fEl.Element("takeoffDurationTicks")?.Value, 35f),
                landingDurationTicks = (int)ParseFloat(fEl.Element("landingDurationTicks")?.Value, 40f),
                autoTakeoffInCombat = ParseBool(fEl.Element("autoTakeoffInCombat")?.Value, true),
                autoTakeoffMinDistanceCells = ParseFloat(fEl.Element("autoTakeoffMinDistanceCells")?.Value, 10f),
                autoTakeoffWhenPathBlocked = ParseBool(fEl.Element("autoTakeoffWhenPathBlocked")?.Value, true),
                autoLandInCombat = ParseBool(fEl.Element("autoLandInCombat")?.Value, true),
                autoLandMaxDistanceCells = ParseFloat(fEl.Element("autoLandMaxDistanceCells")?.Value, 14.5f),
                minAirborneTicksBeforeAutoLand = (int)ParseFloat(fEl.Element("minAirborneTicksBeforeAutoLand")?.Value, 48f),
                maxCombatAirborneTicks = (int)ParseFloat(fEl.Element("maxCombatAirborneTicks")?.Value, 0f),
                postLandTakeoffCooldownTicks = (int)ParseFloat(fEl.Element("postLandTakeoffCooldownTicks")?.Value, 210f),
                minLiftEfficiencyToFly = ParseFloat(fEl.Element("minLiftEfficiencyToFly")?.Value, 0.40f),
                crashOnZeroLift = ParseBool(fEl.Element("crashOnZeroLift")?.Value, false),
                damagedLiftMinSpeedFactor = ParseFloat(fEl.Element("damagedLiftMinSpeedFactor")?.Value, 0.45f),
                forcedLandingStunTicks = (int)ParseFloat(fEl.Element("forcedLandingStunTicks")?.Value, 180f),
                takeoffWindblastRadius = ParseFloat(fEl.Element("takeoffWindblastRadius")?.Value, 0f),
                takeoffWindblastDamage = (int)ParseFloat(fEl.Element("takeoffWindblastDamage")?.Value, 0f),
                takeoffWindblastStunTicks = (int)ParseFloat(fEl.Element("takeoffWindblastStunTicks")?.Value, 0f),
                landingImpactRadius = ParseFloat(fEl.Element("landingImpactRadius")?.Value, 0f),
                landingImpactDamage = (int)ParseFloat(fEl.Element("landingImpactDamage")?.Value, 0f),
                landingImpactStunTicks = (int)ParseFloat(fEl.Element("landingImpactStunTicks")?.Value, 0f),
                canFlyOverWalls = ParseBool(fEl.Element("canFlyOverWalls")?.Value, true),
                canFlyOverWaterAndLava = ParseBool(fEl.Element("canFlyOverWaterAndLava")?.Value, true),
                blockedByThickRoof = ParseBool(fEl.Element("blockedByThickRoof")?.Value, true),
                canHoverOverImpassable = ParseBool(fEl.Element("canHoverOverImpassable")?.Value, true),
                immuneToGroundMelee = ParseBool(fEl.Element("immuneToGroundMelee")?.Value, true),
                allowAirToAirMelee = ParseBool(fEl.Element("allowAirToAirMelee")?.Value, true),
                altitudeVisualOffsetZ = ParseFloat(fEl.Element("altitudeVisualOffsetZ")?.Value, 1.50f),
                renderLayerAltitudeBoost = ParseFloat(fEl.Element("renderLayerAltitudeBoost")?.Value, 3.2f),
                dropShadowScale = ParseFloat(fEl.Element("dropShadowScale")?.Value, 0.80f),
                dropShadowAlpha = ParseFloat(fEl.Element("dropShadowAlpha")?.Value, 0.40f),
                dropShadowOffsetXZ = ParseVec2(fEl.Element("dropShadowOffsetXZ")?.Value, new Vector2(0.42f, -0.45f)),
                hoverBobAmplitude = ParseFloat(fEl.Element("hoverBobAmplitude")?.Value, 0.08f),
                hoverBobPeriodTicks = ParseFloat(fEl.Element("hoverBobPeriodTicks")?.Value, 120f),
                bankingRollMaxAngleDeg = ParseFloat(fEl.Element("bankingRollMaxAngleDeg")?.Value, 6.0f)
            };
            if (Enum.TryParse(fEl.Element("flightMode")?.Value, true, out GiantFlightMode fm))
            {
                def.flightMode = fm;
            }
            if (Enum.TryParse(fEl.Element("altitudeTier")?.Value, true, out FlightAltitudeTier tier))
            {
                def.altitudeTier = tier;
            }
            string animName = fEl.Element("flightLocomotionAnim")?.Value?.Trim();
            if (!string.IsNullOrEmpty(animName) && anims != null && anims.TryGetValue(animName, out GiantAnimDef fAnim))
            {
                def.flightLocomotionAnim = fAnim;
            }
            string toAnimName = fEl.Element("takeoffAnim")?.Value?.Trim();
            if (!string.IsNullOrEmpty(toAnimName) && anims != null && anims.TryGetValue(toAnimName, out GiantAnimDef toAnim))
            {
                def.takeoffAnim = toAnim;
            }
            string ldAnimName = fEl.Element("landingAnim")?.Value?.Trim();
            if (!string.IsNullOrEmpty(ldAnimName) && anims != null && anims.TryGetValue(ldAnimName, out GiantAnimDef ldAnim))
            {
                def.landingAnim = ldAnim;
            }
            return def;
        }

        private static void TestDecoupledFlightPathfindingAndMeleeImmunity()
        {
            // 1. Cross-Giant Zero-Impact Decoupling Audit:
            //    GiantFlightSystem.cs must contain zero hardcoded unit defNames, and every ground biological/walker/vehicle rig
            //    must keep ActiveFlightLocomotion == null and zero isFlightLiftPart bones.
            string flightSysSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Flight", "GiantFlightSystem.cs"));
            foreach (string forbiddenName in new[]
            {
                "GCF_ProtossCarrier", "GCF_Rathalos", "GCF_PanzerIV",
                "GCF_Behemoth", "GCF_AbyssalDragonBeast", "GCF_MechScorpion", "GCF_MechColossus"
            })
            {
                Assert(!flightSysSrc.Contains($"\"{forbiddenName}\"", StringComparison.Ordinal),
                    $"GiantFlightSystem.cs must be 100% Def-driven without hardcoded '{forbiddenName}'");
            }

            (string rigFile, string animFile, string defName)[] groundRigs =
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV")
            };
            foreach (var (rf, af, dn) in groundRigs)
            {
                var (gRig, _, _) = LoadRigFromXml(rf, af, dn);
                Assert(gRig.ActiveFlightLocomotion == null,
                    $"Ground rig '{dn}' must keep ActiveFlightLocomotion == null");
                Assert(gRig.SortedNodes.All(b => !b.isFlightLiftPart),
                    $"Ground rig '{dn}' must not mark any bone as isFlightLiftPart");
                if (dn == "GCF_Rig_PanzerIV")
                {
                    Assert(gRig.ActiveVehicleLocomotion != null, "Panzer IV must keep its decoupled ActiveVehicleLocomotion intact");
                }
            }

            // 2. Protoss Carrier AlwaysAirborne Configuration & Immediate Elevation
            var (carrierRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            List<string> carrierErrs = carrierRig.ConfigErrors().ToList();
            Assert(carrierErrs.Count == 0, $"GCF_Rig_ProtossCarrier ConfigErrors: {string.Join("; ", carrierErrs)}");
            Assert(!carrierRig.crushBuildingsAndTerrain, "Airborne ProtossCarrier must have crushBuildingsAndTerrain=false so it flies over walls cleanly");

            GiantFlightDef carrierFlight = carrierRig.ActiveFlightLocomotion;
            Assert(carrierFlight != null && carrierFlight.flightMode == GiantFlightMode.AlwaysAirborne,
                "GCF_Rig_ProtossCarrier must configure ActiveFlightLocomotion with flightMode=AlwaysAirborne");
            Assert(carrierFlight.resolvedLiftBones.Length == 2,
                $"Expected 2 lift bones (khaydarin_core + aft_thruster) on ProtossCarrier, got {carrierFlight.resolvedLiftBones.Length}");

            var carrierRt = new GiantFlightRuntime(carrierRig, carrierFlight);
            Assert(carrierRt.FlightState == GiantFlightState.Airborne
                   && carrierRt.IsCurrentlyAirborne
                   && carrierRt.IsImmuneToGroundMelee
                   && carrierRt.CurrentAltitude01 == 1f,
                "AlwaysAirborne runtime must spawn directly in Airborne state with ground melee immunity");
            Assert(carrierRt.ComputeVisualOffsetXZ().y >= 1.50f && carrierRt.ComputeRenderAltitudeBoost() >= 3.0f,
                "AlwaysAirborne Carrier must apply visual elevation offset & MoteOverhead render boost");
            Assert(!carrierRt.TryCommandLanding(null, out _),
                "AlwaysAirborne unit must reject manual landing commands while lift systems are intact");

            // 3. TakeoffAndLanding Full 4-State Cycle + Path-Rebuild Trigger + Bilateral Wing-Sever Forced Crash
            var wyvernRig = new GiantRigDef
            {
                defName = "Test_AmphibiousWyvernRig",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "torso", texPath = "Things/Pawn/GiantCreature/Rathalos/Torso", drawSize = new Vector2(4f, 4f) },
                    new BoneNodeDef { nodeId = "wing_left", parentId = "torso", texPath = "Things/Pawn/GiantCreature/Rathalos/Torso", isFlightLiftPart = true },
                    new BoneNodeDef { nodeId = "wing_right", parentId = "torso", texPath = "Things/Pawn/GiantCreature/Rathalos/Torso", isFlightLiftPart = true },
                    new BoneNodeDef
                    {
                        nodeId = "jaw_head",
                        parentId = "torso",
                        texPath = "Things/Pawn/GiantCreature/Rathalos/Torso",
                        partAttacks = new List<GiantPartAttackDef>
                        {
                            new GiantPartAttackDef { attackId = "ground_bite", kind = GiantPartAttackKind.Melee, canStrikeGroundWhileFlying = false },
                            new GiantPartAttackDef { attackId = "aerial_talon_dive", kind = GiantPartAttackKind.Melee, canStrikeGroundWhileFlying = true }
                        }
                    }
                },
                flightLocomotion = new GiantFlightDef
                {
                    flightMode = GiantFlightMode.TakeoffAndLanding,
                    flightSpeedMultiplier = 1.35f,
                    takeoffDurationTicks = 20,
                    landingDurationTicks = 24,
                    minLiftEfficiencyToFly = 0.40f,
                    forcedLandingStunTicks = 180,
                    immuneToGroundMelee = true,
                    allowAirToAirMelee = true,
                    altitudeVisualOffsetZ = 1.45f
                }
            };
            wyvernRig.BuildTopology();
            Assert(wyvernRig.ActiveFlightLocomotion.hasPortLiftGroup && wyvernRig.ActiveFlightLocomotion.hasStarboardLiftGroup,
                "wing_left and wing_right must auto-resolve into bilateral port & starboard lift groups");

            var wyvernRt = new GiantFlightRuntime(wyvernRig, wyvernRig.ActiveFlightLocomotion);
            int wn = wyvernRig.SortedNodes.Length;
            var wMissing = new bool[wn];
            var wHp = Enumerable.Repeat(1f, wn).ToArray();
            wyvernRt.EvaluateLiftEfficiency(wMissing, wHp);

            Assert(wyvernRt.FlightState == GiantFlightState.Grounded && !wyvernRt.IsCurrentlyAirborne && !wyvernRt.IsImmuneToGroundMelee,
                "TakeoffAndLanding unit must initialize Grounded and vulnerable to ground melee");

            int domainFlips = 0;
            Assert(wyvernRt.TryCommandTakeoff(null, out string takeoffErr) && string.IsNullOrEmpty(takeoffErr), "Intact wyvern must start TakingOff");
            Assert(wyvernRt.FlightState == GiantFlightState.TakingOff, "Expected TakingOff state");
            for (int t = 0; t < 20; t++)
            {
                wyvernRt.StepHeadlessTick(headingStepDeg: 2.0f, onDomainFlipped: () => domainFlips++);
            }
            Assert(wyvernRt.FlightState == GiantFlightState.Airborne
                   && wyvernRt.IsCurrentlyAirborne
                   && wyvernRt.IsImmuneToGroundMelee
                   && domainFlips == 1
                   && wyvernRt.PathRebuildCount == 1,
                $"Expected Airborne after 20t takeoff with 1 path rebuild (state={wyvernRt.FlightState}, flips={domainFlips}, rebuilds={wyvernRt.PathRebuildCount})");
            AssertNear(wyvernRt.EffectiveFlightSpeedMultiplier, 1.35f, 1e-4f, "Airborne wyvern speed multiplier must equal 1.35x");

            // Manual landing -> restores Grounded state, 0 visual altitude, and triggers path rebuild #2
            Assert(wyvernRt.TryCommandLanding(null, out _), "TakeoffAndLanding unit must accept manual landing");
            for (int t = 0; t < 24; t++)
            {
                wyvernRt.StepHeadlessTick(headingStepDeg: 0f, onDomainFlipped: () => domainFlips++);
            }
            Assert(wyvernRt.FlightState == GiantFlightState.Grounded
                   && !wyvernRt.IsCurrentlyAirborne
                   && !wyvernRt.IsImmuneToGroundMelee
                   && domainFlips == 2
                   && wyvernRt.PathRebuildCount == 2,
                $"Expected Grounded after 24t landing with 2nd path rebuild (state={wyvernRt.FlightState}, rebuilds={wyvernRt.PathRebuildCount})");

            // Take off again, then sever wing_left -> bilateral lift failure forces crash-landing and blocks re-takeoff!
            Assert(wyvernRt.TryCommandTakeoff(null, out _), "Re-takeoff must succeed while wings intact");
            for (int t = 0; t < 20; t++) wyvernRt.StepHeadlessTick();
            Assert(wyvernRt.FlightState == GiantFlightState.Airborne, "Expected Airborne before wing sever");

            Assert(wyvernRig.TryGetNodeIndex("wing_left", out int wingLIdx), "Missing wing_left");
            Assert(wyvernRig.TryGetNodeIndex("jaw_head", out int jawIdx), "Missing jaw_head");
            wMissing[wingLIdx] = true;
            wHp[wingLIdx] = 0f;
            bool crashed = wyvernRt.EvaluateLiftEfficiency(wMissing, wHp);
            Assert(crashed && wyvernRt.ForcedCrashCount == 1 && !wyvernRt.CanMaintainLift && wyvernRt.FlightState == GiantFlightState.Landing,
                "Severing wing_left while Airborne must immediately trigger ForcedCrashLanding");
            for (int t = 0; t < 20; t++) wyvernRt.StepHeadlessTick();
            Assert(wyvernRt.FlightState == GiantFlightState.Grounded && !wyvernRt.IsCurrentlyAirborne && !wyvernRt.IsImmuneToGroundMelee,
                "Crash-landed wyvern must return to Grounded and become vulnerable to ground melee again");
            Assert(!wyvernRt.TryCommandTakeoff(null, out string damagedFail) && !string.IsNullOrEmpty(damagedFail),
                "Crash-landed wyvern with severed wing must block takeoff with localized failure reason");
            Assert(!wMissing[jawIdx], "Severing wing_left must leave jaw_head offensive bone 100% intact (part-level decoupling)");

            // 4. Aerial Pathfinding Direct Cost & SafeLandingSpotResolver Verification
            Assert(GiantFlightUtility.ComputeAerialDirectCost(
                hasThickRoof: false, blockedByThickRoof: true,
                hasImpassableEdifice: true, canFlyOverWalls: true,
                hasImpassableTerrain: false, canFlyOverWaterAndLava: true) == GiantFlightUtility.AerialWallOverflyDirectCost,
                "Walls without thick roof must have low aerial overfly cost (2)");
            Assert(GiantFlightUtility.ComputeAerialDirectCost(
                hasThickRoof: false, blockedByThickRoof: true,
                hasImpassableEdifice: false, canFlyOverWalls: true,
                hasImpassableTerrain: true, canFlyOverWaterAndLava: true) == GiantFlightUtility.AerialOpenDirectCost,
                "Deep water / lava must have open aerial cost (1)");
            Assert(GiantFlightUtility.ComputeAerialDirectCost(
                hasThickRoof: true, blockedByThickRoof: true,
                hasImpassableEdifice: false, canFlyOverWalls: true,
                hasImpassableTerrain: false, canFlyOverWaterAndLava: true) == GiantDestructionUtility.ImpassablePathCost,
                "Overhead mountain thick roof must remain strictly impassable (10000) when blockedByThickRoof=true");

            IntVec3 mapSz = new IntVec3(60, 1, 60);
            var hullOffsets = new List<IntVec3> { IntVec3.Zero, new IntVec3(1, 0, 0), new IntVec3(-1, 0, 0), new IntVec3(0, 0, 1), new IntVec3(0, 0, -1) };
            bool IsDryClearGround(IntVec3 c) => c.x < 18 || c.x > 22; // x in [18..22] is deep water / wall barrier
            bool resolvedPad = SafeLandingSpotResolver.TryResolveSafeLandingCellHeadless(
                mapSz, new IntVec3(20, 0, 20), hullOffsets, IsDryClearGround, maxSearchRadius: 12, out IntVec3 safePad);
            Assert(resolvedPad && safePad.IsValid && hullOffsets.All(o => IsDryClearGround(safePad + o)),
                $"SafeLandingSpotResolver must move landing anchor out of wall/deep-water band [18..22], got {safePad}");

            // 5. Melee Immunity Matrix, LowSkim Melee-Targetable Aerial MechColossus & Shadow Texture Verification
            Assert(!GiantFlightUtility.CanAttackerReachAirborneInMelee(attackerIsAirborne: false, targetAllowsAirToAirMelee: true),
                "Ground attacker must NEVER reach high-airborne immune target in melee");
            Assert(GiantFlightUtility.CanAttackerReachAirborneInMelee(attackerIsAirborne: false, targetAllowsAirToAirMelee: true, targetImmuneToGroundMelee: false),
                "Ground attacker MUST reach airborne target when targetImmuneToGroundMelee=false");
            Assert(GiantFlightUtility.CanAttackerReachAirborneInMelee(attackerIsAirborne: true, targetAllowsAirToAirMelee: true),
                "Airborne attacker must reach airborne target when allowAirToAirMelee=true");
            Assert(!GiantFlightUtility.CanAttackerReachAirborneInMelee(attackerIsAirborne: true, targetAllowsAirToAirMelee: false),
                "Airborne attacker must be blocked when target sets allowAirToAirMelee=false");

            (string defName, string expectedShadowTex, float expectedSpan)[] colossusStageSpecs =
            {
                ("GCF_Rig_MechColossus_Stage1", "Things/Pawn/GiantCreature/MechColossus/MechColossusShadow_S1", 18.0f),
                ("GCF_Rig_MechColossus_Stage2", "Things/Pawn/GiantCreature/MechColossus/MechColossusShadow_S2", 26.0f),
                ("GCF_Rig_MechColossus_Stage3", "Things/Pawn/GiantCreature/MechColossus/MechColossusShadow_S3", 35.0f)
            };

            var colGroundAttacker = new Pawn
            {
                thingIDNumber = 94810,
                def = new ThingDef { defName = "Human", race = new RaceProperties { intelligence = Intelligence.Humanlike } },
                kindDef = new PawnKindDef { defName = "Colonist" }
            };
            colGroundAttacker.health = new Pawn_HealthTracker(colGroundAttacker);
            var (abRigForMelee, _, _) = LoadMechScorpionFromXml();
            var colGroundGiant = new Pawn
            {
                thingIDNumber = 94811,
                def = new ThingDef { defName = "GCF_MechScorpion", race = new RaceProperties { intelligence = Intelligence.ToolUser } },
                kindDef = new PawnKindDef { defName = "GCF_MechScorpion", canMeleeAttack = false }
            };
            colGroundGiant.health = new Pawn_HealthTracker(colGroundGiant);
            var abCompForMelee = new CompGiantRig { parent = colGroundGiant };
            abCompForMelee.Initialize(new CompProperties_GiantRig { rigDef = abRigForMelee });
            GiantFastLookup.Register(colGroundGiant, abCompForMelee);

            var carrierPawnForMelee = new Pawn
            {
                thingIDNumber = 94812,
                def = new ThingDef { defName = "GCF_ProtossCarrier", race = new RaceProperties { intelligence = Intelligence.ToolUser } },
                kindDef = new PawnKindDef { defName = "GCF_ProtossCarrier", canMeleeAttack = false }
            };
            carrierPawnForMelee.health = new Pawn_HealthTracker(carrierPawnForMelee);
            var carrierCompForMelee = new CompGiantRig { parent = carrierPawnForMelee };
            carrierCompForMelee.Initialize(new CompProperties_GiantRig { rigDef = carrierRig });
            GiantFastLookup.Register(carrierPawnForMelee, carrierCompForMelee);

            var colossusAirPawn = new Pawn
            {
                thingIDNumber = 94813,
                def = new ThingDef
                {
                    defName = "GCF_MechColossus",
                    race = new RaceProperties
                    {
                        intelligence = Intelligence.ToolUser,
                        baseBodySize = 9.5f,
                        baseHealthScale = 6.5f,
                        lifeStageAges = new List<LifeStageAge>
                        {
                            new LifeStageAge
                            {
                                minAge = 0f,
                                def = new RimWorld.LifeStageDef { defName = "MechanoidFullyFormed", healthScaleFactor = 1f, bodySizeFactor = 1f }
                            }
                        }
                    }
                },
                kindDef = new PawnKindDef { defName = "GCF_MechColossus", canMeleeAttack = false }
            };
            colossusAirPawn.ageTracker = new Pawn_AgeTracker(colossusAirPawn);
            typeof(Pawn_AgeTracker).GetField("cachedLifeStageIndex", BindingFlags.Instance | BindingFlags.NonPublic)?.SetValue(colossusAirPawn.ageTracker, 0);
            colossusAirPawn.health = new Pawn_HealthTracker(colossusAirPawn);
            var colossusAirComp = new CompGiantRig { parent = colossusAirPawn };
            GiantFastLookup.Register(colossusAirPawn, colossusAirComp);

            try
            {
                foreach (var (stDefName, expShadowTex, expSpan) in colossusStageSpecs)
                {
                    var (stRig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", stDefName);
                    Assert(!stRig.ConfigErrors().Any(), $"ConfigErrors on {stDefName}: {string.Join("; ", stRig.ConfigErrors())}");
                    Assert(!stRig.crushBuildingsAndTerrain, $"{stDefName} must set crushBuildingsAndTerrain=false while airborne");

                    // Shadow texture & config verification
                    Assert(stRig.shadowTexPath == expShadowTex, $"{stDefName} expected shadowTexPath '{expShadowTex}', got '{stRig.shadowTexPath}'");
                    AssertNear(stRig.shadowDrawSize.x, expSpan, 1e-3f, $"{stDefName} shadowDrawSize.x");
                    AssertNear(stRig.shadowDrawSize.y, expSpan, 1e-3f, $"{stDefName} shadowDrawSize.y");
                    Assert(stRig.shadowAlpha > 0.25f && stRig.shadowAlpha <= 0.65f, $"{stDefName} shadowAlpha out of range");
                    Assert(stRig.renderGroundShadowWhenGrounded, $"{stDefName} must enable renderGroundShadowWhenGrounded");

                    string shadowPngPath = ResolveMod17Path("Textures", expShadowTex.Replace('/', Path.DirectorySeparatorChar) + ".png");
                    Assert(File.Exists(shadowPngPath), $"Missing lossless shadow PNG on disk: {shadowPngPath}");
                    byte[] shRgba = DecodePngRgbaTopDown(shadowPngPath, out int shW, out int shH);
                    Assert(shW == 512 && shH == 512, $"{expShadowTex} must be 512x512 RGBA8, got {shW}x{shH}");
                    int maxAlpha = 0, softPenumbraPixels = 0;
                    for (int p = 0; p < shW * shH; p++)
                    {
                        byte r = shRgba[p * 4], g = shRgba[p * 4 + 1], b = shRgba[p * 4 + 2], a = shRgba[p * 4 + 3];
                        Assert(r == 0 && g == 0 && b == 0, $"{expShadowTex} must have pure (0,0,0) RGB at every pixel to prevent bilinear white fringe");
                        if (a > maxAlpha) maxAlpha = a;
                        if (a > 8 && a < 220) softPenumbraPixels++;
                    }
                    Assert(maxAlpha >= 240 && softPenumbraPixels >= 4000,
                        $"{expShadowTex} must contain dense umbra core + smooth soft penumbra (maxA={maxAlpha}, softPx={softPenumbraPixels})");

                    // Aerial LowSkim + ground-melee-targetable verification
                    GiantFlightDef stFlight = stRig.ActiveFlightLocomotion;
                    Assert(stFlight != null
                           && stFlight.flightMode == GiantFlightMode.AlwaysAirborne
                           && stFlight.altitudeTier == FlightAltitudeTier.LowSkim
                           && !stFlight.immuneToGroundMelee
                           && stFlight.allowAirToAirMelee
                           && stFlight.canFlyOverWalls
                           && stFlight.canFlyOverWaterAndLava
                           && stFlight.blockedByThickRoof,
                        $"{stDefName} must configure AlwaysAirborne + LowSkim + immuneToGroundMelee=false");
                    Assert(stFlight.resolvedLiftBones.Length == 3
                           && stFlight.hasPortLiftGroup
                           && stFlight.hasStarboardLiftGroup
                           && stFlight.hasCenterLiftGroup,
                        $"{stDefName} must bind 3 lift bones (susp_arc_left, susp_arc_right, core_gimbal)");

                    if (colossusAirComp.props == null)
                    {
                        colossusAirComp.Initialize(new CompProperties_GiantRig { rigDef = stRig });
                    }
                    else
                    {
                        colossusAirComp.SwitchRig(stRig);
                    }
                    Assert(colossusAirComp.IsCurrentlyAirborne && !colossusAirComp.IsImmuneToGroundMeleeNow,
                        $"{stDefName} runtime must be Airborne yet vulnerable to ground melee");
                    Assert(!GiantFlightUtility.ShouldBlockMeleeAgainstAirborneTarget(colGroundAttacker, colossusAirPawn),
                        $"Ground colonist must be allowed to melee airborne {stDefName}");
                    Assert(!GiantFlightUtility.ShouldBlockMeleeAgainstAirborneTarget(colGroundGiant, colossusAirPawn),
                        $"Ground giant (AbyssalDragonBeast) must be allowed to melee airborne {stDefName}");
                    Assert(!GiantFlightUtility.ShouldBlockMeleeAgainstAirborneTarget(carrierPawnForMelee, colossusAirPawn),
                        $"Airborne unit must be allowed to melee airborne {stDefName}");
                    Assert(GiantFlightUtility.CanGiantEngageTargetInCurrentDomain(colGroundGiant, abCompForMelee, colossusAirPawn),
                        $"Ground giant AI must engage airborne {stDefName} in melee");
                    Assert(colossusAirComp.FlightLocomotion.BreakGroundMeleePursuers(colossusAirComp) == 0,
                        $"{stDefName} must never break ground melee pursuers when immuneToGroundMelee=false");
                }

                // Contrast check: high-altitude ProtossCarrier (immuneToGroundMelee=true) still blocks ground melee!
                Assert(carrierCompForMelee.IsCurrentlyAirborne && carrierCompForMelee.IsImmuneToGroundMeleeNow,
                    "ProtossCarrier must remain immune to ground melee");
                Assert(GiantFlightUtility.ShouldBlockMeleeAgainstAirborneTarget(colGroundAttacker, carrierPawnForMelee),
                    "Ground colonist must still be blocked from meleeing high-altitude ProtossCarrier");
            }
            finally
            {
                GiantFastLookup.Unregister(colGroundGiant);
                GiantFastLookup.Unregister(carrierPawnForMelee);
                GiantFastLookup.Unregister(colossusAirPawn);
            }

            var badFlight = new GiantFlightDef { flightMode = GiantFlightMode.AlwaysAirborne, flightSpeedMultiplier = 0f, takeoffDurationTicks = 1 };
            List<string> fErrs = badFlight.ValidateConfig("BadFlightRig").ToList();
            Assert(fErrs.Count >= 2, "ValidateConfig must catch invalid flightSpeedMultiplier and takeoffDurationTicks");

            var badShadowRig = new GiantRigDef
            {
                defName = "BadShadowRig",
                nodes = new List<BoneNodeDef> { new BoneNodeDef { nodeId = "root", texPath = "Dummy" } },
                shadowTexPath = "Things/Pawn/GiantCreature/MechColossus/MechColossusShadow_S1",
                shadowDrawSize = Vector2.zero
            };
            badShadowRig.BuildTopology();
            Assert(badShadowRig.ConfigErrors().Any(e => e.Contains("shadowDrawSize", StringComparison.Ordinal)),
                "GiantRigDef.ConfigErrors must reject shadowTexPath with zero shadowDrawSize");

            Console.WriteLine($"       -> Verified 4 ground rigs untouched, MechColossus 3-stage LowSkim melee-targetable flight + 3 lossless shadow PNGs, ProtossCarrier AlwaysAirborne, Wyvern 4-state Takeoff/Land + wing-sever crash ({wyvernRt.PathRebuildCount} path rebuilds), AerialCost/SafeLanding ({safePad}) & 4-layer melee immunity");
        }

        private static void TestRathalos44BoneWingWalkingWyvernAndFullCombatFlightSuite()
        {
            var (rig, masks, anims) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            BodyDef bodyDef = LoadBodyDefFromXml("Bodies_Rathalos.xml", "GCF_Body_Rathalos");

            // 1. 44-Bone Zero-Forepaw Flying Wyvern Anatomy & 1:1 BodyDef Parity
            Assert(rig.SortedNodes.Length == 44, $"Expected 44 bones in GCF_Rig_Rathalos, got {rig.SortedNodes.Length}");
            Assert(masks.Length == 44, $"Expected 44 alpha masks in GCF_Rig_Rathalos, got {masks.Length}");
            List<string> cfgErrs = rig.ConfigErrors().ToList();
            Assert(cfgErrs.Count == 0, $"GCF_Rig_Rathalos ConfigErrors: {string.Join("; ", cfgErrs)}");

            List<string> alignErrs = rig.ValidateAnatomicalTreeAlignment(bodyDef, "GCF_Rig_Rathalos").ToList();
            Assert(alignErrs.Count == 0, $"GCF_Rig_Rathalos BodyDef 1:1 alignment errors: {string.Join("; ", alignErrs)}");

            foreach (BoneNodeDef node in rig.SortedNodes)
            {
                Assert(!node.nodeId.Contains("forepaw", StringComparison.OrdinalIgnoreCase)
                       && !node.nodeId.Contains("front_paw", StringComparison.OrdinalIgnoreCase)
                       && !node.nodeId.Contains("front_leg", StringComparison.OrdinalIgnoreCase),
                    $"Rathalos must have zero separate front paws/legs, found '{node.nodeId}'");
                Assert(!string.IsNullOrEmpty(node.silhouetteTexPath),
                    $"Bone '{node.nodeId}' must declare <silhouetteTexPath> for zero-internal-line union silhouette rendering");
            }

            // 2. Verify all 21 bespoke Monster Hunter Rathalos animations: zero <scale> != 1, zero child <offset> != 0, zero ConfigErrors
            string[] expectedAnimNames =
            {
                "GCF_Anim_Rathalos_Idle",
                "GCF_Anim_Rathalos_Walk",
                "GCF_Anim_Rathalos_Run",
                "GCF_Anim_Rathalos_TurnLeft",
                "GCF_Anim_Rathalos_TurnRight",
                "GCF_Anim_Rathalos_DragonCharge",
                "GCF_Anim_Rathalos_FireballBreath",
                "GCF_Anim_Rathalos_AerialFireball",
                "GCF_Anim_Rathalos_FireballLiftoff",
                "GCF_Anim_Rathalos_TalonStrike",
                "GCF_Anim_Rathalos_Roar",
                "GCF_Anim_Rathalos_WingSlashLeft",
                "GCF_Anim_Rathalos_WingSlashRight",
                "GCF_Anim_Rathalos_TailClubSweep",
                "GCF_Anim_Rathalos_FierceBite",
                "GCF_Anim_Rathalos_BiteRightToLeft",
                "GCF_Anim_Rathalos_BiteLeftToRight",
                "GCF_Anim_Rathalos_Takeoff",
                "GCF_Anim_Rathalos_FlyMove",
                "GCF_Anim_Rathalos_Land",
                "GCF_Anim_Rathalos_Death"
            };
            var animMap = anims;
            foreach (string animName in expectedAnimNames)
            {
                Assert(animMap.TryGetValue(animName, out GiantAnimDef clip), $"Missing GiantAnimDef '{animName}'");
                List<string> aErrs = clip.ConfigErrors().ToList();
                Assert(aErrs.Count == 0, $"GiantAnimDef '{animName}' ConfigErrors: {string.Join("; ", aErrs)}");
                foreach (BoneAnimTrack tr in clip.tracks)
                {
                    foreach (BoneKeyframe kf in tr.keyframes)
                    {
                        Assert((kf.scale - Vector2.one).sqrMagnitude < 1e-6f,
                            $"Clip '{animName}' bone '{tr.nodeId}' must not scale (got {kf.scale})");
                        if (tr.nodeId != "thorax_core")
                        {
                            Assert(kf.offset.sqrMagnitude < 1e-6f,
                                $"Clip '{animName}' child bone '{tr.nodeId}' must be pure rotational pin-mount (got offset {kf.offset})");
                        }
                    }
                }
            }

            static float SampleBoneAngle(GiantAnimDef clip, string boneId, float tick)
            {
                BoneAnimTrack tr = clip.tracks.FirstOrDefault(t => t.nodeId == boneId);
                return tr != null ? tr.SampleAt(tick, clip.durationTicks, clip.loop).angle : 0f;
            }

            static float SampleBoneSagittalPitch(GiantAnimDef clip, string boneId, float tick)
            {
                BoneAnimTrack tr = clip.tracks.FirstOrDefault(t => t.nodeId == boneId);
                return tr != null ? tr.SampleAt(tick, clip.durationTicks, clip.loop).sagittalPitch : 0f;
            }

            static float SampleBoneCoronalFlap(GiantAnimDef clip, string boneId, float tick)
            {
                BoneAnimTrack tr = clip.tracks.FirstOrDefault(t => t.nodeId == boneId);
                return tr != null ? tr.SampleAt(tick, clip.durationTicks, clip.loop).coronalFlap : 0f;
            }

            // Verify articulated 3-blade ~180-deg folding wing hierarchy + welded costal crests & longitudinal coronal shoulder hinges
            foreach (string rigidId in new[] { "wing_costal_crest_left", "wing_costal_crest_right" })
            {
                BoneNodeDef rNode = rig.SortedNodes.First(n => n.nodeId == rigidId);
                Assert(rNode.isRigid, $"Wing costal crest '{rigidId}' must set <isRigid>true</isRigid> so leading-edge spikes never detach");
            }
            BoneNodeDef shNodeL = rig.SortedNodes.First(n => n.nodeId == "wing_shoulder_left");
            BoneNodeDef shNodeR = rig.SortedNodes.First(n => n.nodeId == "wing_shoulder_right");
            Assert(shNodeL.isCoronalFlapHinge && shNodeR.isCoronalFlapHinge
                   && shNodeL.baseCoronalFlap >= 32f && shNodeR.baseCoronalFlap >= 32f,
                "Wing shoulders must declare <isCoronalFlapHinge>true</isCoronalFlapHinge> and <baseCoronalFlap> for converged ground rest posture");
            Assert(rig.SortedNodes.First(n => n.nodeId == "wing_costal_crest_left").parentId == "wing_outer_fan_left"
                   && rig.SortedNodes.First(n => n.nodeId == "wing_costal_crest_right").parentId == "wing_outer_fan_right",
                "Wing costal crests must be parented directly to wing_outer_fan so leading-edge spikes never detach");

            // 3. 3D Sagittal-Plane Quadrupedal Gait (zero flat XY hindleg wiggle; vertical-plane sagittal stride on hindlegs & wing-roots)
            GiantAnimDef walkClip = animMap["GCF_Anim_Rathalos_Walk"];
            Assert(walkClip.loop && Mathf.Abs(walkClip.durationTicks - 48f) < 1e-3f, "Walk clip must loop over 48 ticks");
            for (int t = 0; t <= 48; t += 4)
            {
                Assert(Mathf.Abs(SampleBoneAngle(walkClip, "thigh_left", t)) < 1e-3f
                       && Mathf.Abs(SampleBoneAngle(walkClip, "shin_left", t)) < 1e-3f
                       && Mathf.Abs(SampleBoneAngle(walkClip, "thigh_right", t)) < 1e-3f
                       && Mathf.Abs(SampleBoneAngle(walkClip, "shin_right", t)) < 1e-3f,
                    $"Hindlegs must have zero horizontal XY wiggle during Walk (tick {t})");
            }
            float thighPitchL0 = SampleBoneSagittalPitch(walkClip, "thigh_left", 0f);
            float thighPitchL24 = SampleBoneSagittalPitch(walkClip, "thigh_left", 24f);
            float thighPitchR0 = SampleBoneSagittalPitch(walkClip, "thigh_right", 0f);
            float thighPitchR24 = SampleBoneSagittalPitch(walkClip, "thigh_right", 24f);
            Assert(thighPitchL0 > 20f && thighPitchL24 < -12f && thighPitchR0 < -12f && thighPitchR24 > 20f,
                $"Hindlegs must execute anti-phase 3D vertical sagittal strides: L=({thighPitchL0:F1},{thighPitchL24:F1}), R=({thighPitchR0:F1},{thighPitchR24:F1})");

            float wingShSagL11 = SampleBoneSagittalPitch(walkClip, "wing_shoulder_left", 11f);
            float wingShSagR35 = SampleBoneSagittalPitch(walkClip, "wing_shoulder_right", 35f);
            Assert(wingShSagL11 > 20f && wingShSagR35 > 20f,
                $"Wing-forelimbs must execute 4-beat sagittal strides on wing-wrists: L@11={wingShSagL11:F1}, R@35={wingShSagR35:F1}");

            // Verify FK sagittal projection moves hind_paw & wing_thumb_claw predominantly along forward +Z with minimal lateral X drift
            var evalLocal = new BoneLocalPose[rig.SortedNodes.Length];
            var evalWorld = new BoneWorldPose[rig.SortedNodes.Length];
            var zeroMissing = new bool[rig.SortedNodes.Length];
            int pawLIdx = rig.SortedNodes.First(n => n.nodeId == "hind_paw_left").runtimeIndex;
            int clawLIdx = rig.SortedNodes.First(n => n.nodeId == "wing_thumb_claw_left").runtimeIndex;
            float minPawX = float.MaxValue, maxPawX = float.MinValue, minPawZ = float.MaxValue, maxPawZ = float.MinValue;
            float minClawX = float.MaxValue, maxClawX = float.MinValue, minClawZ = float.MaxValue, maxClawZ = float.MinValue;
            for (int t = 0; t < 48; t++)
            {
                walkClip.EvaluateInto(rig, t, evalLocal);
                SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50f, 50f), 0f, evalLocal, zeroMissing, evalWorld);
                Vector2 pXZ = evalWorld[pawLIdx].jointWorldXZ;
                Vector2 cXZ = evalWorld[clawLIdx].jointWorldXZ;
                if (pXZ.x < minPawX) minPawX = pXZ.x; if (pXZ.x > maxPawX) maxPawX = pXZ.x;
                if (pXZ.y < minPawZ) minPawZ = pXZ.y; if (pXZ.y > maxPawZ) maxPawZ = pXZ.y;
                if (cXZ.x < minClawX) minClawX = cXZ.x; if (cXZ.x > maxClawX) maxClawX = cXZ.x;
                if (cXZ.y < minClawZ) minClawZ = cXZ.y; if (cXZ.y > maxClawZ) maxClawZ = cXZ.y;
            }
            Assert((maxPawZ - minPawZ) > 0.70f && (maxPawX - minPawX) < 0.08f,
                $"Hind paw walk excursion must be >90% sagittal (+Z={maxPawZ - minPawZ:F2}, X={maxPawX - minPawX:F2})");
            Assert((maxClawZ - minClawZ) > 0.70f && (maxClawX - minClawX) < 0.14f,
                $"Wing thumb-claw walk excursion must be predominantly sagittal (+Z={maxClawZ - minClawZ:F2}, X={maxClawX - minClawX:F2})");

            // 3b. Authentic Monster Hunter Two-Step Wyvern Pivot Turn (TurnLeft / TurnRight, 48t loop, 45 deg cycle)
            GiantAnimDef turnLClip = animMap["GCF_Anim_Rathalos_TurnLeft"];
            GiantAnimDef turnRClip = animMap["GCF_Anim_Rathalos_TurnRight"];
            Assert(turnLClip.loop && Mathf.Abs(turnLClip.durationTicks - 48f) < 1e-3f
                   && turnRClip.loop && Mathf.Abs(turnRClip.durationTicks - 48f) < 1e-3f
                   && Mathf.Abs(rig.turnCycleAngleDeg - 45f) < 1e-3f,
                "TurnLeft and TurnRight must loop over 48 ticks with turnCycleAngleDeg = 45");
            Assert(SampleBoneSagittalPitch(turnLClip, "thigh_right", 9f) > 20f
                   && Mathf.Abs(SampleBoneSagittalPitch(turnLClip, "thigh_right", 21f)) < 10f
                   && SampleBoneSagittalPitch(turnLClip, "thigh_left", 33f) > 20f
                   && Mathf.Abs(SampleBoneAngle(turnLClip, "thigh_left", 9f)) < 1e-3f
                   && Mathf.Abs(SampleBoneAngle(turnLClip, "thigh_right", 33f)) < 1e-3f,
                "TurnLeft must execute two distinct Monster Hunter step-and-pause beats with zero horizontal frog-leg splay");

            // 4. Monster Hunter Signature Abilities (DragonCharge, FireballBreath, FireballLiftoff, TalonStrike, ApexRoar)
            string abilPath = ResolveMod17Path("Defs", "AbilityDefs", "Abilities_Rathalos.xml");
            XDocument abilDoc = XDocument.Load(abilPath);
            string[] expectedAbilities =
            {
                "GCF_Ability_Rathalos_DragonCharge",
                "GCF_Ability_Rathalos_FireballBreath",
                "GCF_Ability_Rathalos_FireballLiftoff",
                "GCF_Ability_Rathalos_TalonStrike",
                "GCF_Ability_Rathalos_ApexRoar"
            };
            foreach (string abDefName in expectedAbilities)
            {
                XElement abEl = abilDoc.Root!.Elements("AbilityDef").FirstOrDefault(e => e.Element("defName")?.Value == abDefName);
                Assert(abEl != null, $"Missing {abDefName} in Abilities_Rathalos.xml");
                Assert(abEl.Descendants("li").Any(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_AbilityRequiresGiantBone"),
                    $"Ability '{abDefName}' must wire CompProperties_AbilityRequiresGiantBone");
            }
            XElement dcEl = abilDoc.Root!.Elements("AbilityDef")
                .First(e => e.Element("defName")?.Value == "GCF_Ability_Rathalos_DragonCharge");
            XElement dcCompEl = dcEl.Descendants("li")
                .FirstOrDefault(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_AbilityRathalosDragonCharge");
            Assert(dcCompEl != null, "DragonCharge AbilityDef must wire CompProperties_AbilityRathalosDragonCharge");
            Assert(dcEl.Element("verbProperties")?.Element("verbClass")?.Value == "GiantCreatureFramework.Verb_CastGiantAbility",
                "DragonCharge AbilityDef must use Verb_CastGiantAbility");
            AssertNear(ParseFloat(dcEl.Element("verbProperties")?.Element("range")?.Value, 0f), 53.7f, 0.01f,
                "DragonCharge range must be 3x (53.7)");
            AssertNear(ParseFloat(dcCompEl.Element("maxChargeDistance")?.Value, 0f), 54.0f, 0.01f,
                "DragonCharge maxChargeDistance must be 3x (54.0)");
            AssertNear(ParseFloat(dcCompEl.Element("chargeSpeedCellsPerSecond")?.Value, 0f), 15.0f, 0.01f,
                "DragonCharge speed must be halved to 15.0 cells/sec (0.25 cells/tick)");
            var dcPropsVerify = new CompProperties_AbilityRathalosDragonCharge();
            Assert(dcPropsVerify.ResolveChargeDurationTicks(18.0f) == 72 && dcPropsVerify.ResolveChargeDurationTicks(54.0f) == 216,
                "DragonCharge duration must double to 72 ticks at 18 cells and scale to 216 ticks at 54 cells");
            Assert(RathalosDragonChargeSim.EvaluateDragonChargeAnimTick(100, 216) >= 13.5f
                   && RathalosDragonChargeSim.EvaluateDragonChargeAnimTick(100, 216) <= 24.5f
                   && Mathf.Abs(RathalosDragonChargeSim.EvaluateDragonChargeAnimTick(216, 216) - 42f) < 1e-3f,
                "Long DragonCharge must cycle pure [13.5..24.5] rush strides mid-charge (never entering 30.5 snap-bite windup early) and finish on terminal frame 42");

            XElement fbEl = abilDoc.Root!.Elements("AbilityDef")
                .First(e => e.Element("defName")?.Value == "GCF_Ability_Rathalos_FireballBreath");
            XElement fbCompEl = fbEl.Descendants("li")
                .FirstOrDefault(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_AbilityRathalosFireball");
            Assert(fbCompEl != null, "FireballBreath AbilityDef must wire CompProperties_AbilityRathalosFireball");
            Assert(fbEl.Element("verbProperties")?.Element("verbClass")?.Value == "GiantCreatureFramework.Verb_CastGiantAbility",
                "FireballBreath AbilityDef (range=73.5 > GenRadial.MaxRadialPatternRadius) must use Verb_CastGiantAbility");
            AssertNear(ParseFloat(fbEl.Element("verbProperties")?.Element("range")?.Value, 0f), 73.5f, 0.01f,
                "FireballBreath range must be 3x (73.5)");
            AssertNear(ParseFloat(fbCompEl.Element("maxDistance")?.Value, 0f), 73.5f, 0.01f,
                "FireballBreath maxDistance must be 3x (73.5)");
            AssertNear(ParseFloat(fbCompEl.Element("fireballSpeedCellsPerSecond")?.Value, 0f), 15.0f, 0.01f,
                "FireballBreath flight speed must be dodgeable (15.0 cells/sec)");
            var fbPropsVerify = new CompProperties_AbilityRathalosFireball();
            Assert(fbPropsVerify.ResolveTravelTicks(1.5f) == 18
                   && fbPropsVerify.ResolveTravelTicks(12.0f) == 48
                   && fbPropsVerify.ResolveTravelTicks(73.5f) == 294,
                "FireballBreath travel ticks must enforce minTravelTicks=18 and scale smoothly at 15.0 cells/sec (48 at 12 cells, 294 at 73.5 cells)");
            foreach (string groundFbDef in new[] { "GCF_Ability_Rathalos_FireballBreath", "GCF_Ability_Rathalos_FireballLiftoff" })
            {
                XElement gfbEl = abilDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == groundFbDef);
                XElement tpEl = gfbEl.Element("verbProperties")?.Element("targetParams");
                Assert(tpEl != null
                       && string.Equals(tpEl.Element("canTargetLocations")?.Value, "true", StringComparison.OrdinalIgnoreCase)
                       && string.Equals(tpEl.Element("canTargetPawns")?.Value, "false", StringComparison.OrdinalIgnoreCase)
                       && string.Equals(tpEl.Element("canTargetBuildings")?.Value, "false", StringComparison.OrdinalIgnoreCase),
                    $"{groundFbDef} must target ground map cells only (canTargetLocations=true, canTargetPawns=false, canTargetBuildings=false)");
            }

            GiantAnimDef fbClip = animMap["GCF_Anim_Rathalos_FireballBreath"];
            GiantAnimDef afbClip = animMap["GCF_Anim_Rathalos_AerialFireball"];
            GiantAnimDef liftoffClip = animMap["GCF_Anim_Rathalos_FireballLiftoff"];
            GiantAnimDef talonClip = animMap["GCF_Anim_Rathalos_TalonStrike"];
            GiantAnimDef roarClip = animMap["GCF_Anim_Rathalos_Roar"];
            Assert((SampleBoneSagittalPitch(fbClip, "neck_mid", 16f) - SampleBoneSagittalPitch(fbClip, "neck_mid", 12f)) > 55f
                   && SampleBoneAngle(afbClip, "wing_outer_fan_left", 0f) > 70f,
                "FireballBreath & AerialFireball must execute 4-segment neck coil/whip and maintain ~180 deg wingspan airborne");
            Assert(SampleBoneAngle(liftoffClip, "wing_outer_fan_left", 40f) > 70f
                   && (RathalosDragonChargeSim.ComputeBackjumpLandingXZ(new Vector2(20f, 20f), new Vector2(20f, 26f), 3.6f) - new Vector2(20f, 16.4f)).magnitude < 1e-3f,
                "FireballLiftoff must spring backward away from target into ~180 deg open-wing airborne posture");
            Assert((SampleBoneSagittalPitch(talonClip, "hind_paw_left", 21f) - SampleBoneSagittalPitch(talonClip, "hind_paw_left", 11f)) > 40f
                   && Mathf.Abs(RathalosDragonChargeSim.EvaluateSwoopProgress01(26, 26) - 1f) < 1e-4f,
                "TalonStrike must thrust venomous hind talons forward during airborne raptor swoop");
            Assert(SampleBoneAngle(roarClip, "wing_outer_fan_left", 16f) > 62f
                   && roarClip.events.Any(ev => ev.vfxPreset == GiantAnimVfxPreset.RoarShockwave),
                "Roar must flare wings into ~170 deg threat display and emit RoarShockwave");

            GiantAnimDef chargeClip = animMap["GCF_Anim_Rathalos_DragonCharge"];
            Assert(!chargeClip.loop && Mathf.Abs(chargeClip.durationTicks - 42f) < 1e-3f, "DragonCharge clip must be one-shot 42 ticks");
            Assert(Mathf.Abs(SampleBoneAngle(chargeClip, "skull", 30.5f) - SampleBoneAngle(chargeClip, "skull", 35f)) > 32f
                   && (SampleBoneSagittalPitch(chargeClip, "wing_shoulder_left", 35f) - SampleBoneSagittalPitch(chargeClip, "wing_shoulder_left", 8f)) > 40f,
                "DragonCharge must execute predatory sagittal coil, full-speed rush, and terminal snap-bite skid");
            Assert(SampleBoneAngle(chargeClip, "wing_humerus_left", 13.5f) > 15f
                   && SampleBoneAngle(chargeClip, "wing_humerus_right", 19.0f) < -15f
                   && SampleBoneAngle(chargeClip, "wing_humerus_left", 35.0f) > 15f
                   && SampleBoneAngle(chargeClip, "wing_humerus_right", 35.0f) < -15f,
                "DragonCharge wings must swing forward-center (向前中摆动) during rush strides and terminal snap-bite");

            // Regression check: zero head twitching & C1-continuous ~36-tick stride loop during long 216-tick charge
            float maxCruiseSkullWorldYaw = 0f;
            float maxCruiseSkullPitchDelta = 0f;
            float maxCruiseWingPitchDelta = 0f;
            float prevSampleAt = RathalosDragonChargeSim.EvaluateDragonChargeAnimTick(18, 216);
            float prevSkullPitch = SampleBoneSagittalPitch(chargeClip, "skull", prevSampleAt);
            float prevWingPitch = SampleBoneSagittalPitch(chargeClip, "wing_shoulder_left", prevSampleAt);
            for (int ct = 19; ct <= 192; ct++)
            {
                float st = RathalosDragonChargeSim.EvaluateDragonChargeAnimTick(ct, 216);
                float worldSkullYaw = SampleBoneAngle(chargeClip, "thorax_core", st)
                                    + SampleBoneAngle(chargeClip, "neck_base", st)
                                    + SampleBoneAngle(chargeClip, "neck_mid", st)
                                    + SampleBoneAngle(chargeClip, "neck_upper", st)
                                    + SampleBoneAngle(chargeClip, "skull", st);
                maxCruiseSkullWorldYaw = Mathf.Max(maxCruiseSkullWorldYaw, Mathf.Abs(worldSkullYaw));
                float curSkullPitch = SampleBoneSagittalPitch(chargeClip, "skull", st);
                float curWingPitch = SampleBoneSagittalPitch(chargeClip, "wing_shoulder_left", st);
                maxCruiseSkullPitchDelta = Mathf.Max(maxCruiseSkullPitchDelta, Mathf.Abs(curSkullPitch - prevSkullPitch));
                maxCruiseWingPitchDelta = Mathf.Max(maxCruiseWingPitchDelta, Mathf.Abs(curWingPitch - prevWingPitch));
                prevSkullPitch = curSkullPitch;
                prevWingPitch = curWingPitch;
            }
            Assert(maxCruiseSkullWorldYaw < 0.25f && maxCruiseSkullPitchDelta < 1.0f && maxCruiseWingPitchDelta < 6.5f,
                $"DragonCharge cruise loop must keep skull dead-steady without twitching or wrap pops (yaw={maxCruiseSkullWorldYaw:F3}, skullPitchStep={maxCruiseSkullPitchDelta:F3}, wingPitchStep={maxCruiseWingPitchDelta:F3})");

            float prevProg = 0f;
            for (int t = 1; t <= 36; t++)
            {
                float p = RathalosDragonChargeSim.EvaluateChargeProgress01(t, 36);
                Assert(p > prevProg && p <= 1.0001f, $"DragonCharge progress must advance monotonically at tick {t} ({prevProg} -> {p})");
                prevProg = p;
            }
            AssertNear(prevProg, 1.0f, 1e-4f, "DragonCharge must reach 1.0 at completion");
            Vector2 pushed = RathalosDragonChargeSim.ComputeKnockbackTargetXZ(new Vector2(10f, 10f), new Vector2(10.8f, 10.5f), new Vector2(0f, 1f), 3.2f);
            Assert((pushed - new Vector2(10.8f, 10.5f)).magnitude > 3.0f && pushed.x > 12.0f && pushed.y > 11.5f,
                $"DragonCharge knockback must push corridor targets laterally + forward, got {pushed}");

            // 5. Part-Driven Attacks: Wing Slashes (L/R), 2-Beat 100% Isolated Tail-Club Swipe & 3-Mode Non-Wagging Predatory Bites
            BoneNodeDef skullNode = rig.SortedNodes.First(n => n.nodeId == "skull");
            BoneNodeDef wingArmL = rig.SortedNodes.First(n => n.nodeId == "wing_forearm_left");
            BoneNodeDef wingArmR = rig.SortedNodes.First(n => n.nodeId == "wing_forearm_right");
            BoneNodeDef tailHead = rig.SortedNodes.First(n => n.nodeId == "tail_club_head");

            Assert(skullNode.partAttacks.Count == 3
                   && skullNode.partAttacks[0].attackId == "rathalos_fierce_bite"
                   && skullNode.partAttacks[1].attackId == "rathalos_bite_right_to_left"
                   && skullNode.partAttacks[2].attackId == "rathalos_bite_left_to_right",
                "Skull must mount all 3 predatory bites (fierce_bite, bite_right_to_left, bite_left_to_right)");
            Assert(wingArmL.partAttacks.Count == 1 && wingArmL.partAttacks[0].attackId == "rathalos_wing_slash_left", "Left wing forearm must mount rathalos_wing_slash_left");
            Assert(wingArmR.partAttacks.Count == 1 && wingArmR.partAttacks[0].attackId == "rathalos_wing_slash_right", "Right wing forearm must mount rathalos_wing_slash_right");
            Assert(tailHead.partAttacks.Count == 1 && tailHead.partAttacks[0].attackId == "rathalos_tail_club_sweep"
                   && tailHead.partAttacks[0].independentOverlay
                   && tailHead.partAttacks[0].canStrikeGroundWhileFlying,
                "Tail club head must mount independentOverlay + canStrikeGroundWhileFlying rathalos_tail_club_sweep");

            GiantAnimDef slashL = animMap["GCF_Anim_Rathalos_WingSlashLeft"];
            GiantAnimDef slashR = animMap["GCF_Anim_Rathalos_WingSlashRight"];
            GiantAnimDef biteClip = animMap["GCF_Anim_Rathalos_FierceBite"];
            GiantAnimDef biteR2L = animMap["GCF_Anim_Rathalos_BiteRightToLeft"];
            GiantAnimDef biteL2R = animMap["GCF_Anim_Rathalos_BiteLeftToRight"];
            GiantAnimDef tailClip = animMap["GCF_Anim_Rathalos_TailClubSweep"];

            float slashInwardSweepL = (SampleBoneAngle(slashL, "wing_shoulder_left", 14f) + SampleBoneAngle(slashL, "wing_humerus_left", 14f)
                                     + SampleBoneAngle(slashL, "wing_forearm_left", 14f) + SampleBoneAngle(slashL, "wing_thumb_claw_left", 14f))
                                    - (SampleBoneAngle(slashL, "wing_shoulder_left", 9f) + SampleBoneAngle(slashL, "wing_humerus_left", 9f)
                                     + SampleBoneAngle(slashL, "wing_forearm_left", 9f) + SampleBoneAngle(slashL, "wing_thumb_claw_left", 9f));
            float slashInwardSweepR = (SampleBoneAngle(slashR, "wing_shoulder_right", 9f) + SampleBoneAngle(slashR, "wing_humerus_right", 9f)
                                     + SampleBoneAngle(slashR, "wing_forearm_right", 9f) + SampleBoneAngle(slashR, "wing_thumb_claw_right", 9f))
                                    - (SampleBoneAngle(slashR, "wing_shoulder_right", 14f) + SampleBoneAngle(slashR, "wing_humerus_right", 14f)
                                     + SampleBoneAngle(slashR, "wing_forearm_right", 14f) + SampleBoneAngle(slashR, "wing_thumb_claw_right", 14f));
            Assert(slashInwardSweepL > 65f && SampleBoneAngle(slashL, "wing_thumb_claw_left", 14f) > 8f,
                $"Left wing slash must sweep > 65 deg inward toward front-middle (got {slashInwardSweepL:F1} deg)");
            Assert(slashInwardSweepR > 65f && SampleBoneAngle(slashR, "wing_thumb_claw_right", 14f) < -8f,
                $"Right wing slash must sweep > 65 deg inward toward front-middle (got {slashInwardSweepR:F1} deg)");
            Assert((SampleBoneSagittalPitch(biteClip, "skull", 13f) - SampleBoneSagittalPitch(biteClip, "skull", 9f)) > 42f
                   && Mathf.Abs(SampleBoneAngle(biteClip, "skull", 9f)) < 1e-3f
                   && Mathf.Abs(SampleBoneAngle(biteClip, "skull", 13f)) < 1e-3f,
                "FierceBite must execute pure sagittal forward-and-back snap with zero lateral wagging");
            Assert((SampleBoneAngle(biteR2L, "skull", 9f) - SampleBoneAngle(biteR2L, "skull", 15f)) > 36f
                   && (SampleBoneAngle(biteL2R, "skull", 15f) - SampleBoneAngle(biteL2R, "skull", 9f)) > 36f,
                "BiteRightToLeft and BiteLeftToRight must execute opposite >36 deg predatory lateral sweeps");

            // Verify partAnimBodyCoupling = 0.50 (50%) & inverse-BodySize inertia scaling
            AssertNear(rig.partAnimBodyCoupling, 0.50f, 1e-4f, "Rathalos rig must configure <partAnimBodyCoupling>0.50</partAnimBodyCoupling>");
            float c2 = GiantRigDef.ComputeSizeScaledBodyCoupling(2.0f);
            float c4 = GiantRigDef.ComputeSizeScaledBodyCoupling(4.0f);
            float c8 = GiantRigDef.ComputeSizeScaledBodyCoupling(8.0f);
            float c13 = GiantRigDef.ComputeSizeScaledBodyCoupling(13.0f);
            Assert(c2 > c4 && c4 > c8 && c8 > c13,
                $"ComputeSizeScaledBodyCoupling must decrease monotonically with giant BodySize ({c2:F2} > {c4:F2} > {c8:F2} > {c13:F2})");
            Assert(biteClip.actingSubtreeRootBoneId == "neck_base"
                   && biteR2L.actingSubtreeRootBoneId == "neck_base"
                   && biteL2R.actingSubtreeRootBoneId == "neck_base"
                   && slashL.actingSubtreeRootBoneId == "wing_shoulder_left"
                   && slashR.actingSubtreeRootBoneId == "wing_shoulder_right",
                "Predatory bites and WingSlashes must declare actingSubtreeRootBoneId for 50% coupled body carryover");
            BoneAnimTrack rawBiteRoot = biteClip.tracks.First(t => t.nodeId == "thorax_core");
            float rawRootZ13 = rawBiteRoot.SampleAt(13f, biteClip.durationTicks, false).offset.y;
            float rawSkullPitch13 = SampleBoneSagittalPitch(biteClip, "skull", 13f);
            biteClip.EvaluateInto(rig, 13f, evalLocal, pawnBodySize: 8.5f);
            int skullIdx = rig.SortedNodes.First(n => n.nodeId == "skull").runtimeIndex;
            AssertNear(evalLocal[0].offset.y, rawRootZ13 * 0.50f, 1e-4f, "FierceBite must scale thorax_core root forward lunge to 50%");
            AssertNear(evalLocal[skullIdx].sagittalPitch, rawSkullPitch13, 1e-4f, "FierceBite must preserve 100% skull sagittal snap inside neck_base acting subtree");

            Assert(tailClip.isolatedSubtreeRootBoneId == "tail_seg1" && Mathf.Abs(tailClip.durationTicks - 42f) < 1e-3f,
                "TailClubSweep must declare isolatedSubtreeRootBoneId='tail_seg1' over 42 ticks");
            Assert(SampleBoneAngle(tailClip, "tail_seg1", 16f) > 15f && SampleBoneAngle(tailClip, "tail_seg1", 29f) < -15f,
                "TailClubSweep must execute authentic Monster Hunter two-stage whip (Beat 1 + Beat 2)");
            Assert(rig.TryGetNodeIndex("tail_seg1", out int tailRootIdx), "Missing tail_seg1");
            foreach (BoneAnimTrack tr in tailClip.tracks)
            {
                Assert(rig.TryGetNodeIndex(tr.nodeId, out int bIdx) && rig.IsBoneInSubtree(bIdx, tailRootIdx),
                    $"TailClubSweep track '{tr.nodeId}' violates tail_seg1 subtree isolation");
            }

            // 6. Flight Animations (<flightLocomotion> 42t Takeoff, 180t Soaring-Dominant Cruise + Occasional Flap, 44t Landing & Wing-Sever Crash)
            GiantFlightDef fDef = rig.ActiveFlightLocomotion;
            Assert(fDef != null && fDef.flightMode == GiantFlightMode.TakeoffAndLanding, "Rathalos must configure TakeoffAndLanding flightLocomotion");
            Assert(fDef.flightLocomotionAnim?.defName == "GCF_Anim_Rathalos_FlyMove"
                   && fDef.takeoffAnim?.defName == "GCF_Anim_Rathalos_Takeoff"
                   && fDef.landingAnim?.defName == "GCF_Anim_Rathalos_Land"
                   && fDef.takeoffDurationTicks == 42
                   && fDef.landingDurationTicks == 44,
                "Rathalos flightLocomotion must wire 42t Takeoff, 180t FlyMove, and 44t Land animations");
            Assert(fDef.resolvedLiftBones.Length == 8 && fDef.hasPortLiftGroup && fDef.hasStarboardLiftGroup,
                $"Expected 8 bilateral wing lift bones on Rathalos, got {fDef.resolvedLiftBones.Length}");

            GiantAnimDef flyClip = animMap["GCF_Anim_Rathalos_FlyMove"];
            Assert(flyClip.loop && Mathf.Abs(flyClip.durationTicks - 108f) < 1e-3f,
                $"FlyMove must loop over a calm 108-tick (1.80s) 3-segment wingbeat cycle, got {flyClip.durationTicks}");
            Assert(rig.steering?.yawBankBones != null && rig.steering.yawBankBones.Count == 10,
                $"Rathalos steering must configure 10 bilateral 3-segment aero-elastic yawBankBones, got {rig.steering?.yawBankBones?.Count ?? 0}");

            float effFlapUp26 = shNodeL.baseCoronalFlap + SampleBoneCoronalFlap(flyClip, "wing_shoulder_left", 39f);
            float effFlapSweep46 = shNodeL.baseCoronalFlap + SampleBoneCoronalFlap(flyClip, "wing_shoulder_left", 69f);
            float effFlapCup59 = shNodeL.baseCoronalFlap + SampleBoneCoronalFlap(flyClip, "wing_shoulder_left", 88f);
            Assert(effFlapUp26 >= 50f && Mathf.Abs(effFlapSweep46) < 4f && effFlapCup59 >= -14f && effFlapCup59 <= -6f,
                $"Airborne FlyMove must execute smooth single-peaked 3D coronal flap without double-spasm (up={effFlapUp26:F1}, sweep={effFlapSweep46:F1}, cup={effFlapCup59:F1})");
            Assert(Mathf.Abs(SampleBoneAngle(flyClip, "wing_shoulder_left", 79f)) < 5f
                   && SampleBoneAngle(flyClip, "wing_forearm_left", 73f) < -10f
                   && SampleBoneAngle(flyClip, "wing_outer_fan_left", 82f) > 30f
                   && SampleBoneAngle(flyClip, "wing_inner_fan_left", 79f) > 18f
                   && Mathf.Abs(SampleBoneAngle(flyClip, "wing_shoulder_right", 79f)) < 5f
                   && SampleBoneAngle(flyClip, "wing_forearm_right", 73f) > 10f
                   && SampleBoneAngle(flyClip, "wing_outer_fan_right", 82f) < -30f
                   && SampleBoneAngle(flyClip, "wing_inner_fan_right", 79f) < -18f,
                "Airborne FlyMove must execute bilateral 3-segment phase-lagged wing expansion while keeping proximal shoulder stable");
            Assert(Mathf.Abs(SampleBoneAngle(flyClip, "thigh_left", 73f)) < 1e-3f
                   && Mathf.Abs(SampleBoneAngle(flyClip, "thigh_right", 73f)) < 1e-3f
                   && SampleBoneSagittalPitch(flyClip, "thigh_left", 73f) > 18f
                   && SampleBoneSagittalPitch(flyClip, "shin_left", 73f) > 30f
                   && SampleBoneSagittalPitch(flyClip, "thigh_right", 73f) > 18f
                   && SampleBoneSagittalPitch(flyClip, "shin_right", 73f) > 30f,
                "Airborne FlyMove must tuck both hindlegs cleanly in sagittal plane with zero lateral sway");

            // Verify converged ground rest span vs unfolded 3D coronal flight wingspan + exact BuildRenderMatrix <-> UVToWorldXZ <-> TryWorldToUV round-trip
            int outerFanLIdx = rig.SortedNodes.First(n => n.nodeId == "wing_outer_fan_left").runtimeIndex;
            int outerFanRIdx = rig.SortedNodes.First(n => n.nodeId == "wing_outer_fan_right").runtimeIndex;
            int wingShLIdx = rig.SortedNodes.First(n => n.nodeId == "wing_shoulder_left").runtimeIndex;

            walkClip.EvaluateInto(rig, 0f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50f, 50f), 0f, evalLocal, zeroMissing, evalWorld);
            float groundWingSpan = Mathf.Abs(evalWorld[outerFanRIdx].UVToWorldXZ(0.92f, 0.35f).x - evalWorld[outerFanLIdx].UVToWorldXZ(0.08f, 0.35f).x);

            flyClip.EvaluateInto(rig, 79f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50f, 50f), 0f, evalLocal, zeroMissing, evalWorld);
            float flightWingSpan = Mathf.Abs(evalWorld[outerFanRIdx].UVToWorldXZ(0.92f, 0.35f).x - evalWorld[outerFanLIdx].UVToWorldXZ(0.08f, 0.35f).x);
            Assert(flightWingSpan > groundWingSpan * 1.28f,
                $"Unfolded 3D coronal flight wingspan must expand >1.28x wider than converged ground walking posture (flight={flightWingSpan:F2} vs ground={groundWingSpan:F2})");

            // 6b. Verify 9-Layer 2D Skeletal Skinning, Zero Lateral Vertex Sway, and 100% Rigid SO(2) Wrist-Pinned Wing Thumb-Claws
            Assert(rig.useCoupledSagittalKinematics, "GCF_Rig_Rathalos must enable <useCoupledSagittalKinematics>true</useCoupledSagittalKinematics>");
            Assert(rig.skinnedMeshes.Count == 9, $"Expected 9 continuous skinned mesh layers on GCF_Rig_Rathalos, got {rig.skinnedMeshes.Count}");
            Assert(rig.SortedNodes.All(n => n.isRenderedBySkinnedMesh), "All 44 Rathalos bones must be visually owned by the 9 skinned mesh layers");

            var rathBoneSilMasks = new TextureAlphaMask[rig.SortedNodes.Length];
            for (int bi = 0; bi < rig.SortedNodes.Length; bi++)
            {
                string silRel = rig.SortedNodes[bi].silhouetteTexPath;
                if (!string.IsNullOrEmpty(silRel))
                {
                    string silPath = ResolveMod17Path("Textures", silRel.Replace('/', Path.DirectorySeparatorChar) + ".png");
                    if (File.Exists(silPath))
                    {
                        rathBoneSilMasks[bi] = TextureAlphaMask.FromPngFile(silPath, rig.SortedNodes[bi].alphaThreshold);
                    }
                }
            }

            var rathSkinRuntimes = new Dictionary<string, SkinnedMeshRuntime>(StringComparer.Ordinal);
            foreach (GiantSkinnedMeshDef smDef in rig.skinnedMeshes)
            {
                string colPng = ResolveMod17Path("Textures", smDef.texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                string silPng = ResolveMod17Path("Textures", smDef.silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Assert(File.Exists(colPng) && File.Exists(silPng), $"Missing baked skinned layer PNG(s) for '{smDef.meshId}'");
                TextureAlphaMask silMask = TextureAlphaMask.FromPngFile(silPng, smDef.alphaThreshold);
                var smRt = new SkinnedMeshRuntime(rig, smDef);
                smRt.EnsureBindTopology(silMask, masks, rathBoneSilMasks);
                Assert(smRt.IsBindInitialized && smRt.VertexCount > 10 && smRt.ActiveTriangleCount > 6,
                    $"SkinnedMeshRuntime '{smDef.meshId}' failed topology init (verts={smRt.VertexCount}, tris={smRt.ActiveTriangleCount})");
                rathSkinRuntimes[smDef.meshId] = smRt;
            }

            // Assert strict zero lateral vertex drift (max X - min X < 1e-4) on Dorsal_Body & Hindlegs across Walk & FlyMove
            foreach (GiantAnimDef locoClip in new[] { walkClip, flyClip })
            {
                foreach (string strictLayer in new[] { "Dorsal_Body", "Hindleg_Left", "Hindleg_Right" })
                {
                    SkinnedMeshRuntime smRt = rathSkinRuntimes[strictLayer];
                    var minVX = Enumerable.Repeat(float.MaxValue, smRt.VertexCount).ToArray();
                    var maxVX = Enumerable.Repeat(float.MinValue, smRt.VertexCount).ToArray();
                    for (int s = 0; s < 36; s++)
                    {
                        float tSample = (s / 36f) * locoClip.durationTicks;
                        locoClip.EvaluateInto(rig, tSample, evalLocal);
                        SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, zeroMissing, evalWorld);
                        smRt.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                        Vector3[] dv = smRt.DeformedVertices;
                        for (int vi = 0; vi < dv.Length; vi++)
                        {
                            if (dv[vi].x < minVX[vi]) minVX[vi] = dv[vi].x;
                            if (dv[vi].x > maxVX[vi]) maxVX[vi] = dv[vi].x;
                        }
                    }
                    float maxDriftX = 0f;
                    for (int vi = 0; vi < minVX.Length; vi++)
                    {
                        float d = maxVX[vi] - minVX[vi];
                        if (d > maxDriftX) maxDriftX = d;
                    }
                    Assert(maxDriftX < 1e-4f,
                        $"Skinned layer '{strictLayer}' violated zero lateral sway in '{locoClip.defName}' (max vertex dX={maxDriftX:F6})");
                }
            }

            // Assert 100% rigid SO(2) Euclidean distance preservation on Wing_Thumb_Left & Wing_Thumb_Right across Idle, Walk, FlyMove, and WingSlash!
            Assert(SampleBoneAngle(walkClip, "wing_thumb_claw_left", 12f) > 25f
                   && SampleBoneAngle(walkClip, "wing_thumb_claw_right", 36f) < -25f
                   && Mathf.Abs(SampleBoneAngle(animMap["GCF_Anim_Rathalos_Idle"], "wing_thumb_claw_left", 0f)) < 1e-4f,
                "Wing thumb-claw must stay at 0 deg in Idle and rotate inward toward front-middle during Walk");

            SkinnedMeshRuntime thumbLRt = rathSkinRuntimes["Wing_Thumb_Left"];
            animMap["GCF_Anim_Rathalos_Idle"].EvaluateInto(rig, 0f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, zeroMissing, evalWorld);
            thumbLRt.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
            Vector3[] idleThumbVerts = (Vector3[])thumbLRt.DeformedVertices.Clone();

            foreach ((GiantAnimDef testClip, float testTick, float testHeading) in new[]
            {
                (walkClip, 12f, 0f),
                (slashL, 14f, 0f),
                (slashL, 14f, 37f),
                (flyClip, 39f, 125f),
                (flyClip, 79f, 125f)
            })
            {
                testClip.EvaluateInto(rig, testTick, evalLocal);
                SkeletalKinematics.SolveWorldPoses(rig, new Vector2(10f, -8f), testHeading, evalLocal, zeroMissing, evalWorld);
                thumbLRt.EvaluateDeformedVertices(evalWorld, new Vector2(10f, -8f), false, out _);
                Vector3[] liveThumbVerts = thumbLRt.DeformedVertices;
                float maxEdgeDistErr = 0f;
                for (int vi = 1; vi < liveThumbVerts.Length; vi++)
                {
                    float dIdle = Vector3.Distance(idleThumbVerts[0], idleThumbVerts[vi]);
                    float dLive = Vector3.Distance(liveThumbVerts[0], liveThumbVerts[vi]);
                    float err = Mathf.Abs(dLive - dIdle);
                    if (err > maxEdgeDistErr) maxEdgeDistErr = err;
                }
                Assert(maxEdgeDistErr < 1e-4f,
                    $"Wing_Thumb_Left deformed non-rigidly in '{testClip.defName}'@{testTick} (heading={testHeading}, maxDistErr={maxEdgeDistErr:F6})");
            }

            flyClip.EvaluateInto(rig, 79f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50f, 50f), 25f, evalLocal, zeroMissing, evalWorld);
            float fullLatSpan = (evalWorld[outerFanLIdx].UVToWorldXZ(0.08f, 0.35f) - evalWorld[wingShLIdx].jointWorldXZ).magnitude;

            flyClip.EvaluateInto(rig, 39f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, new Vector2(50f, 50f), 25f, evalLocal, zeroMissing, evalWorld);
            ref readonly BoneWorldPose fanPoseUp = ref evalWorld[outerFanLIdx];
            float upLatSpan = (fanPoseUp.UVToWorldXZ(0.08f, 0.35f) - evalWorld[wingShLIdx].jointWorldXZ).magnitude;
            Assert(fanPoseUp.hasCoronalFlap && upLatSpan < fullLatSpan * 0.72f,
                $"3D coronal high-upstroke must foreshorten lateral wingspan (<72% of clap span, got {upLatSpan:F2} vs {fullLatSpan:F2})");
            Vector2 testWorldPt = fanPoseUp.UVToWorldXZ(0.32f, 0.64f);
            Vector3 matWorldPt = fanPoseUp.BuildRenderMatrix(3.5f).MultiplyPoint3x4(new Vector3(0.32f - 0.5f, 0f, 0.64f - 0.5f));
            AssertNear(testWorldPt.x, matWorldPt.x, 1e-4f, "Coronal BuildRenderMatrix X must match UVToWorldXZ");
            AssertNear(testWorldPt.y, matWorldPt.z, 1e-4f, "Coronal BuildRenderMatrix Z must match UVToWorldXZ");
            AssertNear(matWorldPt.y, 3.5f, 1e-5f, "Coronal BuildRenderMatrix must preserve exact worldAltitudeY");
            Assert(fanPoseUp.TryWorldToUV(testWorldPt.x, testWorldPt.y, out float rtU, out float rtV)
                && Mathf.Abs(rtU - 0.32f) < 1e-4f && Mathf.Abs(rtV - 0.64f) < 1e-4f,
                $"Coronal TryWorldToUV must invert UVToWorldXZ to <1e-4 (got ({rtU:F5}, {rtV:F5}))");

            // 6c. Regression: Skinned-Mesh Part Severing (Zero Silhouette Thread Leakage, Zero Boundary Snap, Crisp Stump Outlines)
            {
                // Verify exact Meijster 2D EDT against brute-force on a 24x19 grid
                int edtW = 24, edtH = 19;
                var fg = new bool[edtW * edtH];
                fg[4 * edtW + 5] = true;
                fg[14 * edtW + 19] = true;
                fg[9 * edtW + 11] = true;
                int[] edtOut = SkinnedMeshRuntime.ComputeSquaredDistanceTransform(fg, edtW, edtH);
                for (int y = 0; y < edtH; y++)
                {
                    for (int x = 0; x < edtW; x++)
                    {
                        int best = int.MaxValue;
                        for (int fy = 0; fy < edtH; fy++)
                        {
                            for (int fx = 0; fx < edtW; fx++)
                            {
                                if (fg[fy * edtW + fx])
                                {
                                    int d2 = (x - fx) * (x - fx) + (y - fy) * (y - fy);
                                    if (d2 < best) best = d2;
                                }
                            }
                        }
                        Assert(edtOut[y * edtW + x] == best,
                            $"Meijster EDT mismatch at ({x},{y}): got {edtOut[y * edtW + x]}, expected {best}");
                    }
                }

                // Sever right wing outer+inner fans during Walk pose -> zero dangling outer-wing triangles and zero vertex snap!
                SkinnedMeshRuntime wingMemR = rathSkinRuntimes["Wing_Membrane_Right"];
                SkinnedMeshRuntime wingArmRSev = rathSkinRuntimes["Wing_Arm_Right"];
                SkinnedMeshRuntime dorsalRt = rathSkinRuntimes["Dorsal_Body"];

                walkClip.EvaluateInto(rig, 12f, evalLocal);
                SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, zeroMissing, evalWorld);
                wingMemR.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                Vector3[] intactWingVerts = (Vector3[])wingMemR.DeformedVertices.Clone();
                wingArmRSev.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                Vector3[] intactArmVerts = (Vector3[])wingArmRSev.DeformedVertices.Clone();

                var sevWingMissing = new bool[rig.SortedNodes.Length];
                sevWingMissing[rig.SortedNodes.First(n => n.nodeId == "wing_outer_fan_right").runtimeIndex] = true;
                sevWingMissing[rig.SortedNodes.First(n => n.nodeId == "wing_inner_fan_right").runtimeIndex] = true;
                CompGiantRig.PropagateTopologicalBoneMissingMask(rig.SortedNodes, sevWingMissing);

                SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, sevWingMissing, evalWorld);
                wingMemR.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                wingArmRSev.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                Assert(wingMemR.IsCurrentlyVisible && wingMemR.HasPartialMemberSevering,
                    "Severing right wing fans while axilla web remains intact must flag partial severing");

                // Every active triangle on Wing_Membrane_Right must stay near the proximal axillary web (x < 4.8) — ZERO trailing-edge thread!
                float maxActiveWingX = float.MinValue;
                int[] activeTris = wingMemR.ActiveTriangleIndices;
                for (int k = 0; k < wingMemR.ActiveTriangleIndexCount; k++)
                {
                    int vi = activeTris[k];
                    float vx = wingMemR.DeformedVertices[vi].x;
                    if (vx > maxActiveWingX) maxActiveWingX = vx;
                    float snapDist = Vector3.Distance(wingMemR.DeformedVertices[vi], intactWingVerts[vi]);
                    Assert(snapDist < 1e-4f,
                        $"Surviving Wing_Membrane_Right vertex {vi} snapped by {snapDist:F4} cells after wing-fan severing");
                }
                Assert(maxActiveWingX < 4.8f,
                    $"Severed Wing_Membrane_Right leaked dangling outer-wing triangles out to x={maxActiveWingX:F2} (must be < 4.8)");

                // Verify Wing_Arm_Right forearm vertices suffered zero snap distortion after wing_outer_fan cascade to costal crest
                for (int vi = 0; vi < wingArmRSev.VertexCount; vi++)
                {
                    float armSnap = Vector3.Distance(wingArmRSev.DeformedVertices[vi], intactArmVerts[vi]);
                    Assert(armSnap < 1e-4f, $"Wing_Arm_Right vertex {vi} snapped by {armSnap:F4} when wing_outer_fan severed");
                }

                // Verify pixel-exact severed compositor for Wing_Membrane_Right produces clean axillary web + crisp #14161A outline
                string wmColPath = ResolveMod17Path("Textures", wingMemR.MeshDef.texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                string wmSilPath = ResolveMod17Path("Textures", wingMemR.MeshDef.silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Color32[] wmSrcCol = TextureAlphaMask.DecodePngRgbaBottomUpFromFile(wmColPath, out int wmW, out int wmH);
                Color32[] wmSrcSil = TextureAlphaMask.DecodePngRgbaBottomUpFromFile(wmSilPath, out int _, out int _);
                float wmOutlineR = SkinnedMeshRuntime.CalibrateOutlineRadiusPx(wmSrcCol, wmSrcSil, wmW, wmH, wingMemR.MeshDef, out Color32 wmSilCol);
                Assert(wmOutlineR >= 8f && wmOutlineR <= 14f, $"Calibrated Wing_Membrane_Right outline radius out of range: {wmOutlineR:F2}px");
                bool builtWm = SkinnedMeshRuntime.BuildSeveredLayerPixels(
                    rig, wingMemR.MeshDef, wingMemR.FlatBindPoses, masks, wingMemR.CurrentVisibleMemberMask,
                    wmSrcCol, null, wmW, wmH, wmOutlineR, wmSilCol,
                    out Color32[] outWmCol, out Color32[] outWmSil, out _);
                Assert(builtWm && outWmCol != null && outWmSil != null, "BuildSeveredLayerPixels must succeed for partially severed Wing_Membrane_Right");
                int leakedOuterPx = 0;
                int silBorderPx = 0;
                for (int py = 0; py < wmH; py++)
                {
                    for (int px = 0; px < wmW; px++)
                    {
                        int idx = py * wmW + px;
                        if (px > (int)(wmW * 0.45f) && (outWmCol[idx].a >= 12 || outWmSil[idx].a >= 12))
                        {
                            leakedOuterPx++;
                        }
                        if (outWmSil[idx].a >= 200 && outWmCol[idx].a < 12)
                        {
                            silBorderPx++;
                        }
                    }
                }
                Assert(leakedOuterPx == 0, $"Partially severed Wing_Membrane_Right leaked {leakedOuterPx} opaque pixels into outer fan half (x > 45%)");
                Assert(silBorderPx > 2500, $"Partially severed Wing_Membrane_Right must synthesize crisp silhouette outline around axillary stump (got {silBorderPx} px)");

                // Sever entire right wing shoulder -> Wing_Membrane_Right must hide completely even though thorax_core is in its capsules!
                sevWingMissing[rig.SortedNodes.First(n => n.nodeId == "wing_shoulder_right").runtimeIndex] = true;
                CompGiantRig.PropagateTopologicalBoneMissingMask(rig.SortedNodes, sevWingMissing);
                SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, sevWingMissing, evalWorld);
                wingMemR.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                Assert(!wingMemR.IsCurrentlyVisible,
                    "Severing wing_shoulder_right must hide Wing_Membrane_Right completely (zero leftover triangles from thorax_core flank capsules)");

                // Sever tail_seg1 on Dorsal_Body -> Dorsal_Body must stay visible, shrink cleanly, and synthesize crisp silhouette outline at sacrum stump!
                var sevTailMissing = new bool[rig.SortedNodes.Length];
                sevTailMissing[rig.SortedNodes.First(n => n.nodeId == "tail_seg1").runtimeIndex] = true;
                CompGiantRig.PropagateTopologicalBoneMissingMask(rig.SortedNodes, sevTailMissing);
                SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, sevTailMissing, evalWorld);
                dorsalRt.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                Assert(dorsalRt.IsCurrentlyVisible && dorsalRt.HasPartialMemberSevering,
                    "Severing tail_seg1 must keep Dorsal_Body visible with HasPartialMemberSevering=true");
                string dbColPath = ResolveMod17Path("Textures", dorsalRt.MeshDef.texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                string dbSilPath = ResolveMod17Path("Textures", dorsalRt.MeshDef.silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                Color32[] dbSrcCol = TextureAlphaMask.DecodePngRgbaBottomUpFromFile(dbColPath, out int dbW, out int dbH);
                Color32[] dbSrcSil = TextureAlphaMask.DecodePngRgbaBottomUpFromFile(dbSilPath, out int _, out int _);
                float dbOutlineR = SkinnedMeshRuntime.CalibrateOutlineRadiusPx(dbSrcCol, dbSrcSil, dbW, dbH, dorsalRt.MeshDef, out Color32 dbSilCol);
                bool builtDb = SkinnedMeshRuntime.BuildSeveredLayerPixels(
                    rig, dorsalRt.MeshDef, dorsalRt.FlatBindPoses, masks, dorsalRt.CurrentVisibleMemberMask,
                    dbSrcCol, null, dbW, dbH, dbOutlineR, dbSilCol,
                    out Color32[] outDbCol, out Color32[] outDbSil, out _);
                Assert(builtDb && outDbCol != null && outDbSil != null, "BuildSeveredLayerPixels must succeed for tail-severed Dorsal_Body");
                // Bottom 35% of Dorsal_Body is severed tail (tail_seg2..tip): must have 0 opaque pixels!
                int tailLeakPx = 0;
                for (int py = 0; py < (int)(dbH * 0.35f); py++)
                {
                    for (int px = 0; px < dbW; px++)
                    {
                        int idx = py * dbW + px;
                        if (outDbCol[idx].a >= 12 || outDbSil[idx].a >= 12) tailLeakPx++;
                    }
                }
                Assert(tailLeakPx == 0, $"Tail-severed Dorsal_Body leaked {tailLeakPx} pixels into severed tail region");
            }

            var flightRt = new GiantFlightRuntime(rig, fDef);
            bool[] missing = new bool[rig.SortedNodes.Length];
            float[] hp = Enumerable.Repeat(1f, rig.SortedNodes.Length).ToArray();
            flightRt.EvaluateLiftEfficiency(missing, hp);

            Assert(flightRt.FlightState == GiantFlightState.Grounded && flightRt.TryCommandTakeoff(null, out _), "Takeoff must start from Grounded");
            for (int t = 0; t < 42; t++) flightRt.StepHeadlessTick();
            Assert(flightRt.FlightState == GiantFlightState.Airborne && flightRt.IsCurrentlyAirborne && flightRt.IsImmuneToGroundMelee,
                "Rathalos must reach Airborne with ground melee immunity after 42-tick takeoff");

            // Verify combat airborne duration cap (maxCombatAirborneTicks == 540) + post-land combat takeoff lockout (480t)
            Assert(fDef.maxCombatAirborneTicks == 540 && fDef.postLandTakeoffCooldownTicks == 480,
                $"Rathalos flightLocomotion must configure maxCombatAirborneTicks=540 and postLandTakeoffCooldownTicks=480 (got {fDef.maxCombatAirborneTicks}, {fDef.postLandTakeoffCooldownTicks})");
            var combatCapRt = new GiantFlightRuntime(rig, fDef);
            Assert(combatCapRt.TryCommandTakeoff(null, out _), "Combat cap test takeoff must start");
            for (int t = 0; t < 42; t++) combatCapRt.StepHeadlessTick();
            Assert(combatCapRt.FlightState == GiantFlightState.Airborne, "Combat cap test must reach Airborne");
            for (int t = 0; t < 600; t++)
            {
                Assert(!combatCapRt.StepCombatFlightCapTick(inCombat: false, hasActiveDisplacement: false, () => combatCapRt.TryCommandLanding(null, out _)),
                    "Out-of-combat peaceful flight must never trigger combat airborne cap landing");
            }
            Assert(combatCapRt.CombatAirborneTicks == 0 && combatCapRt.FlightState == GiantFlightState.Airborne,
                "Peaceful flight must keep CombatAirborneTicks at 0");
            for (int t = 0; t < 539; t++)
            {
                Assert(!combatCapRt.StepCombatFlightCapTick(inCombat: true, hasActiveDisplacement: false, () => combatCapRt.TryCommandLanding(null, out _)),
                    $"Combat flight cap must not land prematurely at tick {t + 1}");
            }
            Assert(!combatCapRt.StepCombatFlightCapTick(inCombat: true, hasActiveDisplacement: true, () => combatCapRt.TryCommandLanding(null, out _)),
                "Combat flight cap must wait for active TalonStrike aerial displacement to finish before landing");
            Assert(combatCapRt.StepCombatFlightCapTick(inCombat: true, hasActiveDisplacement: false, () => combatCapRt.TryCommandLanding(null, out _))
                   && combatCapRt.FlightState == GiantFlightState.Landing,
                "Combat flight cap must immediately transition to Landing once maxCombatAirborneTicks (540) is reached");
            for (int t = 0; t < 44; t++) combatCapRt.StepHeadlessTick();
            Assert(combatCapRt.FlightState == GiantFlightState.Grounded && combatCapRt.PostLandTakeoffLockoutTicks == 480,
                $"Landing completion must arm 480-tick post-land combat takeoff lockout (got {combatCapRt.PostLandTakeoffLockoutTicks})");
            Assert(!combatCapRt.IsCombatTakeoffLockedOut(null, out _, inCombatOverride: false),
                "Out-of-combat peaceful flight must never lock out takeoff even immediately after landing");
            Assert(combatCapRt.IsCombatTakeoffLockedOut(null, out string cdMsg, inCombatOverride: true) && !string.IsNullOrEmpty(cdMsg),
                "Grounded Rathalos in combat must lock out immediate re-takeoff during postLandTakeoffCooldownTicks");
            for (int t = 0; t < 480; t++) combatCapRt.StepCombatFlightCapTick(inCombat: true, hasActiveDisplacement: false, null);
            Assert(!combatCapRt.IsCombatTakeoffLockedOut(null, out _, inCombatOverride: true) && combatCapRt.TryCommandTakeoff(null, out _),
                "Rathalos must allow combat takeoff again after 480-tick grounded recovery completes");

            // Sever left wing shoulder -> topological cascade destroys all 8 left-wing bones -> immediate forced crash landing!
            Assert(rig.TryGetNodeIndex("wing_shoulder_left", out int wingShL), "Missing wing_shoulder_left");
            missing[wingShL] = true;
            CompGiantRig.PropagateTopologicalBoneMissingMask(rig.SortedNodes, missing);
            for (int i = 0; i < missing.Length; i++)
            {
                if (missing[i]) hp[i] = 0f;
            }
            bool crashTriggered = flightRt.EvaluateLiftEfficiency(missing, hp);
            Assert(crashTriggered && flightRt.ForcedCrashCount == 1 && flightRt.FlightState == GiantFlightState.Landing,
                "Severing left wing shoulder must cascade to wing lift bones and trigger immediate crash landing");
            for (int t = 0; t < 44; t++) flightRt.StepHeadlessTick();
            Assert(flightRt.FlightState == GiantFlightState.Grounded && !flightRt.TryCommandTakeoff(null, out _),
                "Crash-landed Rathalos with severed left wing must settle Grounded and block re-takeoff");
            Assert(!missing[rig.SortedNodes.ToList().FindIndex(n => n.nodeId == "skull")]
                   && !missing[rig.SortedNodes.ToList().FindIndex(n => n.nodeId == "tail_club_head")],
                "Wing severing must leave skull bite and tail-club sweep 100% intact");

            // 7. RimFX Procedural Shader & Atmospheric VFX Specification Compliance for Rathalos
            string rathalosCsPath = Path.Combine(ModsParentDir, "[GCF]Rathalos", "Source", "GCF.Rathalos", "Abilities", "RathalosDragonChargeSystem.cs");
            string rathalosCs = File.ReadAllText(rathalosCsPath);
            Assert(!rathalosCs.Contains("FleckMaker."),
                "RathalosDragonChargeSystem.cs must use 100% procedural RimFX layers with zero vanilla FleckMaker calls");
            Assert(!rathalosCs.Contains("SpawnSlashArc"),
                "RathalosDragonChargeSystem.cs must not spawn cartoon SlashArc crescents on TalonStrike");
            Assert(rathalosCs.Contains("doVisualEffects: !vfxEnabled")
                   && rathalosCs.Contains("SpawnMuzzleBlastVfx")
                   && rathalosCs.Contains("SpawnTectonicRift")
                   && rathalosCs.Contains("SpawnDetonationNova")
                   && rathalosCs.Contains("SpawnImpactSparkFan")
                   && rathalosCs.Contains("SpawnVolumetricSmokeCluster"),
                "RathalosDragonChargeSystem.cs must suppress vanilla DoExplosion visual flecks and layer pure RimFX primitives");

            string[] zeroEventClips =
            {
                "GCF_Anim_Rathalos_Idle",
                "GCF_Anim_Rathalos_Walk",
                "GCF_Anim_Rathalos_Run",
                "GCF_Anim_Rathalos_TurnLeft",
                "GCF_Anim_Rathalos_TurnRight",
                "GCF_Anim_Rathalos_FlyMove",
                "GCF_Anim_Rathalos_WingSlashLeft",
                "GCF_Anim_Rathalos_WingSlashRight",
                "GCF_Anim_Rathalos_TailClubSweep",
                "GCF_Anim_Rathalos_FierceBite",
                "GCF_Anim_Rathalos_BiteRightToLeft",
                "GCF_Anim_Rathalos_BiteLeftToRight",
                "GCF_Anim_Rathalos_FireballBreath",
                "GCF_Anim_Rathalos_AerialFireball",
                "GCF_Anim_Rathalos_TalonStrike"
            };
            foreach (string zeroClipName in zeroEventClips)
            {
                GiantAnimDef zc = animMap[zeroClipName];
                Assert(zc.events == null || zc.events.Count == 0,
                    $"Clip '{zeroClipName}' must emit zero redundant XML VFX events under RimFX discipline");
            }
            foreach (GiantAnimDef rClip in animMap.Values)
            {
                if (rClip.events == null) continue;
                Assert(rClip.events.All(ev => ev.vfxPreset != GiantAnimVfxPreset.SlashArc
                                           && ev.fleckDef == null && ev.moteDef == null && ev.effecterDef == null),
                    $"Clip '{rClip.defName}' must not reference SlashArc or vanilla Fleck/Mote/Effecter defs");
            }

            Color[] rathalosRimfxColors =
            {
                RathalosRimfxPalette.VolcanicMuzzleColor,
                RathalosRimfxPalette.VolcanicDetonationColor,
                RathalosRimfxPalette.VolcanicHeartColor,
                RathalosRimfxPalette.VolcanicPressureColor,
                RathalosRimfxPalette.TalonShearColor,
                RathalosRimfxPalette.TalonVenomMistColor,
                RathalosRimfxPalette.ChargeSkidRiftColor,
                RathalosRimfxPalette.RoarDustPressureColor
            };
            foreach (Color palCol in rathalosRimfxColors)
            {
                GiantVfxSystem.DeriveRimfxTriad(palCol, out Color cCore, out Color cBody, out Color cEdge);
                Color.RGBToHSV(cCore, out _, out float sCore, out float vCore);
                Color.RGBToHSV(cBody, out _, out float sBody, out float vBody);
                Color.RGBToHSV(cEdge, out _, out float sEdge, out float vEdge);
                Assert(vCore > vBody && vBody > vEdge,
                    $"RathalosRimfxPalette triad luminance ordering violated for {palCol}");
                Assert(sCore <= 0.22f && sBody <= 0.34f && sEdge <= 0.38f,
                    $"RathalosRimfxPalette triad saturation exceeded RimFX atmospheric bounds for {palCol}");
            }

            // 8. Verify Procedural GLSL Dragon-Flame + Atomized Dust Mist Shader & 100% Action Damage + Stun Coverage
            string rimfxGlsl = File.ReadAllText(ResolveMod17Path("Shaders", "GCF_RimfxUberVfx.frag.glsl"));
            Assert(rimfxGlsl.Contains("ridgedFlameFbm", StringComparison.Ordinal)
                   && rimfxGlsl.Contains("blackbodyCrimsonFlameRamp", StringComparison.Ordinal)
                   && rimfxGlsl.Contains("composeDragonFlame", StringComparison.Ordinal)
                   && rathalosCs.Contains("isDragonFlame: true", StringComparison.Ordinal)
                   && rathalosCs.Contains("atomizedMist: true", StringComparison.Ordinal),
                "GCF_RimfxUberVfx.frag.glsl and RathalosDragonChargeSystem.cs must wire procedural dragon-flame & atomized dust mist shader modes");

            // All 6 partAttacks must deal positive damage with zero stunTicks (only ApexRoar stuns), and 2-beat tail whip must fire 2 strikes
            var allRathalosPartAttacks = rig.SortedNodes.SelectMany(n => n.partAttacks).ToList();
            Assert(allRathalosPartAttacks.Count == 6, $"Expected 6 Rathalos partAttacks, got {allRathalosPartAttacks.Count}");
            foreach (GiantPartAttackDef patk in allRathalosPartAttacks)
            {
                Assert(patk.power > 0f && patk.stunTicks == 0,
                    $"Rathalos partAttack '{patk.attackId}' must configure positive damage (power={patk.power}) and zero stun (stunTicks={patk.stunTicks})");
                Assert(!string.IsNullOrEmpty(patk.rangeOriginBoneId) && rig.TryGetNodeIndex(patk.rangeOriginBoneId, out _),
                    $"Rathalos melee partAttack '{patk.attackId}' must declare valid proximal <rangeOriginBoneId> so hull/wing/tail perimeter has zero melee blind spots");
            }
            Assert(tailHead.partAttacks[0].burstShotCount == 2 && tailHead.partAttacks[0].ticksBetweenBurstShots == 13,
                "2-beat rathalos_tail_club_sweep must execute 2 melee strikes 13 ticks apart");

            // Flight Takeoff windblast & Land touchdown slam must configure both actual damage and stun
            Assert(fDef.takeoffWindblastDamage > 0 && fDef.takeoffWindblastStunTicks == 0
                   && fDef.landingImpactDamage > 0 && fDef.landingImpactStunTicks == 0,
                "Rathalos Takeoff and Land transitions must configure positive damage with zero stunTicks (only ApexRoar stuns)");

            // All 5 signature AbilityDefs must configure positive damage, >= 30s cooldown, and ONLY ApexRoar may have stunTicks > 0
            (string abName, string dmgTag, string stunTag, bool expectStun)[] abilityDamageAndStunChecks =
            {
                ("GCF_Ability_Rathalos_DragonCharge", "trampleDamage", "stunTicks", false),
                ("GCF_Ability_Rathalos_DragonCharge", "snapBiteDamage", "stunTicks", false),
                ("GCF_Ability_Rathalos_FireballBreath", "flameDamage", "stunTicks", false),
                ("GCF_Ability_Rathalos_FireballLiftoff", "flameDamage", "stunTicks", false),
                ("GCF_Ability_Rathalos_FireballLiftoff", "liftoffWindDamage", "liftoffWindStunTicks", false),
                ("GCF_Ability_Rathalos_TalonStrike", "cutDamage", "stunTicks", false),
                ("GCF_Ability_Rathalos_ApexRoar", "sonicDamage", "stunTicks", true)
            };
            foreach (var (abName, dmgTag, stunTag, expectStun) in abilityDamageAndStunChecks)
            {
                XElement aEl = abilDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == abName);
                int dmgVal = int.Parse(aEl.Descendants(dmgTag).First().Value);
                int stunVal = int.Parse(aEl.Descendants(stunTag).First().Value);
                int cdVal = int.Parse(aEl.Element("cooldownTicksRange")!.Value);
                Assert(dmgVal > 0 && cdVal >= 1800,
                    $"Ability '{abName}' must configure positive <{dmgTag}>={dmgVal} and cooldown >= 1800 ticks (30s), got {cdVal}");
                Assert(expectStun ? stunVal > 0 : stunVal == 0,
                    $"Ability '{abName}' <{stunTag}> mismatch: expected {(expectStun ? "> 0" : "== 0")}, got {stunVal}");
            }

            // Vanilla melee hit/dodge formula must NEVER artificially cap high dodge (e.g. 99% melee dodge stays 99%)
            float highDodgeHitProb = GiantPartCombatRuntime.ComputeVanillaMeleeCombinedHitProbability(0.90f, 0.99f);
            AssertNear(highDodgeHitProb, 0.009f, 0.0005f, "99% melee dodge must yield 0.9% combined hit chance (no artificial 0.65 dodge cap)");

            // 9. Verify Wild Manhunter & Provoked Retaliation AI (Target Acquisition + Damage Retaliation + MentalState Prefixes)
            MethodInfo manhunterPrefix = typeof(HarmonyPatches_CombatAndHitbox).GetMethod("JobGiver_Manhunter_TryGiveJob_Prefix", BindingFlags.Public | BindingFlags.Static);
            MethodInfo berserkPrefix = typeof(HarmonyPatches_CombatAndHitbox).GetMethod("JobGiver_Berserk_TryGiveJob_Prefix", BindingFlags.Public | BindingFlags.Static);
            MethodInfo closeThreatPrefix = typeof(HarmonyPatches_CombatAndHitbox).GetMethod("JobGiver_ReactToCloseMeleeThreat_TryGiveJob_Prefix", BindingFlags.Public | BindingFlags.Static);
            Assert(manhunterPrefix != null && berserkPrefix != null && closeThreatPrefix != null,
                "Manhunter, Berserk, and ReactToCloseMeleeThreat Harmony prefixes must all be present for GCF giants");

            var wildRathPawn = new Pawn
            {
                thingIDNumber = 94001,
                def = new ThingDef { defName = "GCF_Rathalos", race = new RaceProperties { intelligence = Intelligence.Animal } },
                kindDef = new PawnKindDef { defName = "GCF_Rathalos", canMeleeAttack = false },
                mindState = new Verse.AI.Pawn_MindState()
            };
            wildRathPawn.mindState.pawn = wildRathPawn;
            var wildRathComp = new CompGiantRig { parent = wildRathPawn };
            wildRathComp.Initialize(new CompProperties_GiantRig { rigDef = rig });
            wildRathPawn.AllComps.Add(wildRathComp);
            GiantFastLookup.Register(wildRathPawn, wildRathComp);

            var attackerColonist = new Pawn
            {
                thingIDNumber = 94002,
                def = new ThingDef { defName = "Human", race = new RaceProperties { intelligence = Intelligence.Humanlike } },
                kindDef = new PawnKindDef { defName = "Colonist" }
            };
            var violentDmgDef = new DamageDef { defName = "Bullet", harmsHealth = true, isRanged = true };
            try
            {
                Assert(!wildRathComp.HasActiveProvokedTarget, "Unprovoked wild Rathalos must start with HasActiveProvokedTarget == false");
                DamageInfo shotDinfo = new DamageInfo(violentDmgDef, 18f, 0.35f, -1f, attackerColonist);
                wildRathComp.RegisterDamageRetaliation(shotDinfo, 18f, fallbackTick: 100);
                Assert(wildRathComp.HasActiveProvokedTarget && wildRathComp.IsProvokedAgainst(attackerColonist),
                    "Attacked wild Rathalos must record active provoked retaliation against its attacker");
                Assert(wildRathPawn.mindState.enemyTarget == attackerColonist,
                    "Attacked wild Rathalos must immediately lock mindState.enemyTarget onto the attacker");
                Assert(GiantPartCombatRuntime.IsValidHostileThing(wildRathPawn, attackerColonist),
                    "IsValidHostileThing must recognize attacker as hostile to provoked wild Rathalos even before Manhunter triggers");
                Assert(CompAbilityEffect_RathalosDragonCharge.IsValidHostilePawnOrTurret(wildRathPawn, attackerColonist),
                    "Rathalos ability targeting must recognize provoked attacker as valid target");
            }
            finally
            {
                GiantFastLookup.Unregister(wildRathPawn);
            }

            string rathThinkXml = File.ReadAllText(ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_Rathalos.xml"));
            Assert(rathThinkXml.Contains("ThinkNode_QueuedJob", StringComparison.Ordinal)
                   && rathThinkXml.Contains("JobGiver_RathalosCombatAbilities", StringComparison.Ordinal)
                   && rathThinkXml.Contains("JobGiver_GiantPartCombatPositioning", StringComparison.Ordinal)
                   && rathThinkXml.Contains("MentalStateNonCritical", StringComparison.Ordinal),
                "ThinkTrees_Rathalos.xml must wire QueuedJob, Rathalos abilities, GiantPartCombatPositioning, and MentalStateNonCritical");
            // 10. Verify Firepower Hull Rotation & Snug Melee Contact Invariants
            var rathPartRt = new GiantPartCombatRuntime(null);
            rathPartRt.RebuildFromRig(rig);
            Assert(rathPartRt.ShouldRotateHullTowardTarget(null),
                "Rathalos must actively rotate hull toward combat targets to align frontal bite and bilateral wing slashes");

            var (mcS1, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (mcS2, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var s1Rt = new GiantPartCombatRuntime(null);
            s1Rt.RebuildFromRig(mcS1);
            var s2Rt = new GiantPartCombatRuntime(null);
            s2Rt.RebuildFromRig(mcS2);
            Assert(!s1Rt.ShouldRotateHullTowardTarget(null),
                "MechColossus Stage 1 (pure 360-deg sensor turrets) should hold hull steady without unnecessary hull spin");
            Assert(s2Rt.ShouldRotateHullTowardTarget(null),
                "MechColossus Stage 2 (limited-arc thermal lance + twin plasma accelerators) must rotate hull to maximize simultaneous firepower");

            Console.WriteLine("       -> Verified 44-bone lossless Rathalos, GLSL dragon-flame & atomized mist shader, 100% damage+stun, Manhunter AI & full-firepower hull rotation");
        }

        private static FlightVehicleLocomotionDef ParseFlightVehicleLocomotionXml(XElement el)
        {
            var def = new FlightVehicleLocomotionDef
            {
                minAirspeedFraction = ParseFloat(el.Element("minAirspeedFraction")?.Value, 0.42f),
                loiterSpeedFraction = ParseFloat(el.Element("loiterSpeedFraction")?.Value, 0.56f),
                loiterOrbitRadiusCells = ParseFloat(el.Element("loiterOrbitRadiusCells")?.Value, 6.5f),
                orbitClockwise = ParseBool(el.Element("orbitClockwise")?.Value, true),
                canHoverInPlace = ParseBool(el.Element("canHoverInPlace")?.Value, true),
                hoverTransitionSpeedFraction = ParseFloat(el.Element("hoverTransitionSpeedFraction")?.Value, 0.24f),
                hoverYawRateDegPerTick = ParseFloat(el.Element("hoverYawRateDegPerTick")?.Value, 1.65f),
                hoverYawEnterAngleDeg = ParseFloat(el.Element("hoverYawEnterAngleDeg")?.Value, 28f),
                hoverYawExitAngleDeg = ParseFloat(el.Element("hoverYawExitAngleDeg")?.Value, 7f),
                maxBankAngleDeg = ParseFloat(el.Element("maxBankAngleDeg")?.Value, 28f),
                maxRollRateDegPerTick = ParseFloat(el.Element("maxRollRateDegPerTick")?.Value, 1.45f),
                maxTurnRateDegPerTick = ParseFloat(el.Element("maxTurnRateDegPerTick")?.Value, 2.10f),
                minTurnRadiusCells = ParseFloat(el.Element("minTurnRadiusCells")?.Value, 5.2f),
                effectiveGravityCellsPerSec2 = ParseFloat(el.Element("effectiveGravityCellsPerSec2")?.Value, 11.5f),
                inducedTurnDragFactor = ParseFloat(el.Element("inducedTurnDragFactor")?.Value, 0.22f),
                throttleSpoolRatePerSec = ParseFloat(el.Element("throttleSpoolRatePerSec")?.Value, 1.65f),
                thrustAccelCellsPerSec2 = ParseFloat(el.Element("thrustAccelCellsPerSec2")?.Value, 2.40f),
                airbrakeDecelCellsPerSec2 = ParseFloat(el.Element("airbrakeDecelCellsPerSec2")?.Value, 3.80f),
                flareStartDistanceScale = ParseFloat(el.Element("flareStartDistanceScale")?.Value, 1.25f),
                taxiSpeedMultiplier = ParseFloat(el.Element("taxiSpeedMultiplier")?.Value, 0.36f),
                taxiTurnRateDegPerTick = ParseFloat(el.Element("taxiTurnRateDegPerTick")?.Value, 1.25f),
                taxiMinTurnRadiusCells = ParseFloat(el.Element("taxiMinTurnRadiusCells")?.Value, 3.2f),
                lookaheadMinCells = ParseFloat(el.Element("lookaheadMinCells")?.Value, 3.2f),
                lookaheadMaxCells = ParseFloat(el.Element("lookaheadMaxCells")?.Value, 7.5f),
                lockHullHeadingWhenHovered = ParseBool(el.Element("lockHullHeadingWhenHovered")?.Value, true),
                allowHullTraverseForFixedWeapons = ParseBool(el.Element("allowHullTraverseForFixedWeapons")?.Value, false),
                stabilizeTurretsAgainstHullTurn = ParseBool(el.Element("stabilizeTurretsAgainstHullTurn")?.Value, true),
                movingFireAccuracyFactor = ParseFloat(el.Element("movingFireAccuracyFactor")?.Value, 0.88f),
                suppressBiologicalGait = ParseBool(el.Element("suppressBiologicalGait")?.Value, true),
                cruiseNoseDownPitchOffset = ParseFloat(el.Element("cruiseNoseDownPitchOffset")?.Value, 0.04f),
                flareNoseUpPitchOffset = ParseFloat(el.Element("flareNoseUpPitchOffset")?.Value, 0.06f),
                damagedPropulsionMinSpeedFactor = ParseFloat(el.Element("damagedPropulsionMinSpeedFactor")?.Value, 0.42f)
            };
            if (Enum.TryParse(el.Element("airframeType")?.Value, true, out FlightVehicleAirframeType af))
            {
                def.airframeType = af;
            }
            return def;
        }

        private static void TestFlightVehicleLocomotionPhaseRevertAndColossus12Crew()
        {
            // 1. FlightVehicleLocomotion Decoupling & ProtossCarrier HeavyAirship Wiring
            (string rigFile, string animFile, string defName)[] nonFlightVehicleRigs =
            {
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos"),
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3")
            };
            foreach (var (rf, af, dn) in nonFlightVehicleRigs)
            {
                var (r, _, _) = LoadRigFromXml(rf, af, dn);
                Assert(r.ActiveFlightVehicleLocomotion == null,
                    $"Rig '{dn}' must keep ActiveFlightVehicleLocomotion == null");
            }

            var (carrierRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            Assert(!carrierRig.ConfigErrors().Any(), $"Carrier ConfigErrors: {string.Join("; ", carrierRig.ConfigErrors())}");
            Assert(carrierRig.ActiveFlightVehicleLocomotion != null
                   && carrierRig.ActiveFlightVehicleLocomotion.airframeType == FlightVehicleAirframeType.HeavyAirship,
                "GCF_Rig_ProtossCarrier must mount <flightVehicleLocomotion> with airframeType=HeavyAirship");
            Assert(carrierRig.ActiveFlightVehicleLocomotion.resolvedThrusterBones.Length >= 2,
                "Carrier FlightVehicleLocomotion must bind its <isFlightLiftPart> core/thruster bones");

            // Mutual-exclusion guard: simultaneous ground <vehicleLocomotion> + <flightVehicleLocomotion> must emit ConfigError
            var conflictRig = new GiantRigDef
            {
                defName = "Test_ConflictRig",
                deathAnim = carrierRig.deathAnim,
                nodes = new List<BoneNodeDef> { new BoneNodeDef { nodeId = "root", texPath = "Dummy" } },
                vehicleLocomotion = new VehicleLocomotionDef { chassisType = VehicleChassisType.Tracked },
                flightVehicleLocomotion = new FlightVehicleLocomotionDef { airframeType = FlightVehicleAirframeType.FixedWing }
            };
            conflictRig.BuildTopology();
            Assert(conflictRig.ConfigErrors().Any(e => e.Contains("cannot activate both", StringComparison.OrdinalIgnoreCase)),
                "Activating both <vehicleLocomotion> and <flightVehicleLocomotion> must be rejected by ConfigErrors");

            // 2. FixedWing Aircraft Physics: Coordinated Bank-to-Turn (speed-dependent turn radius), Stall Speed Floor, Zero Reverse & Loiter Orbit
            float slowTurn = FlightVehicleLocomotionRuntime.ComputeCoordinatedTurnRateDegPerTick(28f, 4.5f, 11.5f, 4.0f, 3.5f);
            float fastTurn = FlightVehicleLocomotionRuntime.ComputeCoordinatedTurnRateDegPerTick(28f, 11.0f, 11.5f, 4.0f, 3.5f);
            Assert(slowTurn > fastTurn * 1.6f,
                $"Coordinated turn rate at 4.5 c/s ({slowTurn:F3} deg/t) must exceed high-speed 11.0 c/s ({fastTurn:F3} deg/t)");

            var fwDef = new FlightVehicleLocomotionDef
            {
                airframeType = FlightVehicleAirframeType.FixedWing,
                minAirspeedFraction = 0.45f,
                loiterSpeedFraction = 0.58f,
                loiterOrbitRadiusCells = 6.0f,
                maxBankAngleDeg = 32f,
                maxRollRateDegPerTick = 1.6f,
                maxTurnRateDegPerTick = 2.4f,
                minTurnRadiusCells = 4.8f,
                thrustAccelCellsPerSec2 = 3.2f,
                airbrakeDecelCellsPerSec2 = 4.2f
            };
            var fwRt = new FlightVehicleLocomotionRuntime(carrierRig, fwDef);
            fwRt.Reset(0f, new Vector2(60f, 60f), hasValidPos: true, startAirborne: true);

            // Airborne with NO move order -> must enter LoiterOrbit above stall floor (never stop at 0 speed in mid-air!)
            for (int t = 0; t < 180; t++)
            {
                fwRt.StepHeadlessAlongPath(ReadOnlySpan<Vector2>.Empty, 8.0f, isAirborne: true);
                Assert(fwRt.CurrentForwardSpeedCellsPerTick >= 0f, "FixedWing must never engage negative reverse speed in mid-air");
            }
            Assert(fwRt.DriveState == FlightVehicleDriveState.LoiterOrbit, $"Expected LoiterOrbit when FixedWing has no move order, got {fwRt.DriveState}");
            Assert(fwRt.CurrentForwardSpeedCellsPerSec >= 8.0f * fwDef.minAirspeedFraction - 0.15f,
                $"FixedWing loiter airspeed ({fwRt.CurrentForwardSpeedCellsPerSec:F2}) fell below stall floor ({8.0f * fwDef.minAirspeedFraction:F2})");
            Assert(Mathf.Abs(fwRt.CurrentBankAngleDeg) > 5f, $"FixedWing loiter orbit must maintain coordinated roll bank, got {fwRt.CurrentBankAngleDeg:F2} deg");

            // Astern waypoint (180 deg behind nose): FixedWing must carve forward banked turn without ever backing up
            fwRt.Reset(0f, new Vector2(60f, 60f), hasValidPos: true, startAirborne: true);
            Vector2[] asternWp = { new Vector2(60f, 32f) };
            float peakBank = 0f;
            for (int t = 0; t < 200; t++)
            {
                fwRt.StepHeadlessAlongPath(asternWp, 8.0f, isAirborne: true);
                Assert(fwRt.LastStepForwardCells >= 0f, "FixedWing must never reverse backward toward an astern waypoint");
                if (Mathf.Abs(fwRt.CurrentBankAngleDeg) > peakBank) peakBank = Mathf.Abs(fwRt.CurrentBankAngleDeg);
            }
            Assert(peakBank >= 15f, $"FixedWing astern turn must build substantial coordinated bank (>=15 deg), got {peakBank:F2}");

            // Grounded taxiing mode: FixedWing settles cleanly to GroundedParked at 0 speed when order completes
            fwRt.StepHeadlessAlongPath(ReadOnlySpan<Vector2>.Empty, 8.0f, isAirborne: false);
            for (int t = 0; t < 90; t++)
            {
                fwRt.StepHeadlessAlongPath(ReadOnlySpan<Vector2>.Empty, 8.0f, isAirborne: false);
            }
            Assert(fwRt.DriveState == FlightVehicleDriveState.GroundedParked && fwRt.CurrentForwardSpeedCellsPerSec < 0.01f,
                $"Grounded FixedWing must park at 0 speed, got state={fwRt.DriveState}, speed={fwRt.CurrentForwardSpeedCellsPerSec:F3}");

            // 3. RotorcraftVTOL Physics: Hover Pedal-Yaw -> Forward Banked Cruise -> Flare Deceleration -> Stationary Hover
            var vtolDef = new FlightVehicleLocomotionDef
            {
                airframeType = FlightVehicleAirframeType.RotorcraftVTOL,
                canHoverInPlace = true,
                hoverYawEnterAngleDeg = 28f,
                hoverYawExitAngleDeg = 7f,
                hoverYawRateDegPerTick = 2.0f,
                maxBankAngleDeg = 22f,
                thrustAccelCellsPerSec2 = 2.8f,
                airbrakeDecelCellsPerSec2 = 4.2f
            };
            var vtolRt = new FlightVehicleLocomotionRuntime(carrierRig, vtolDef);
            Vector2 vtolStart = new Vector2(40f, 40f);
            vtolRt.Reset(0f, vtolStart, hasValidPos: true, startAirborne: true);
            Vector2[] eastTarget = { new Vector2(58f, 40f) }; // 90 deg off nose
            bool sawHoverYaw = false, sawCruiseOrBank = false, sawFlare = false;
            for (int t = 0; t < 380; t++)
            {
                vtolRt.StepHeadlessAlongPath(eastTarget, 6.0f, isAirborne: true);
                if (vtolRt.DriveState == FlightVehicleDriveState.HoverYawing)
                {
                    sawHoverYaw = true;
                    Assert(Vector2.Distance(vtolRt.ExactWorldPosXZ, vtolStart) < 0.15f, "VTOL hover pedal-yaw must rotate in place without crabbing");
                }
                else if (vtolRt.DriveState == FlightVehicleDriveState.ForwardCruise || vtolRt.DriveState == FlightVehicleDriveState.BankedTurn)
                {
                    sawCruiseOrBank = true;
                }
                else if (vtolRt.DriveState == FlightVehicleDriveState.FlareDecelerating)
                {
                    sawFlare = true;
                }
            }
            for (int t = 0; t < 60; t++)
            {
                vtolRt.StepHeadlessAlongPath(ReadOnlySpan<Vector2>.Empty, 6.0f, isAirborne: true);
            }
            Assert(sawHoverYaw && sawCruiseOrBank && sawFlare && vtolRt.DriveState == FlightVehicleDriveState.Hovering,
                $"VTOL lifecycle incomplete: hoverYaw={sawHoverYaw}, cruise={sawCruiseOrBank}, flare={sawFlare}, final={vtolRt.DriveState}");

            // Asymmetric thruster damage degrades propulsion speed factor
            vtolRt.SetSimulatedPropulsionEfficiencyForTest(0.0f, 1.0f, 0.5f);
            Assert(vtolRt.PropulsionSpeedFactor < 0.85f && vtolRt.PropulsionSpeedFactor >= vtolDef.damagedPropulsionMinSpeedFactor,
                $"Damaged propulsion speed factor out of expected range: {vtolRt.PropulsionSpeedFactor:F3}");

            // 4. Time-Reversed Morph Continuity & Full-State Manual Stage Rollback vs Damaged Forward-Only Progression
            var (colRig1, _, colAnims) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (colRig2, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var (colRig3, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");

            GiantAnimDef mOut1 = colAnims["GCF_Anim_MechStage1_MorphOut"];
            GiantAnimDef mIn2 = colAnims["GCF_Anim_MechStage2_MorphIn"];
            GiantAnimDef mOut2 = colAnims["GCF_Anim_MechStage2_MorphOut"];
            GiantAnimDef mIn3 = colAnims["GCF_Anim_MechStage3_MorphIn"];

            GiantAnimDef revOut1 = mOut1.GetOrCreateTimeReversed();
            GiantAnimDef revIn2 = mIn2.GetOrCreateTimeReversed();
            var fwdStart = new BoneLocalPose[64];
            var fwdEnd = new BoneLocalPose[64];
            var revStart = new BoneLocalPose[64];
            var revEnd = new BoneLocalPose[64];
            mOut1.EvaluateInto(colRig1, 0f, fwdStart);
            mOut1.EvaluateInto(colRig1, mOut1.durationTicks, fwdEnd);
            revOut1.EvaluateInto(colRig1, 0f, revStart);
            revOut1.EvaluateInto(colRig1, revOut1.durationTicks, revEnd);
            for (int b = 0; b < 64; b++)
            {
                AssertNear(Mathf.DeltaAngle(fwdEnd[b].angle, revStart[b].angle), 0f, 1e-3f, $"Reversed clip t=0 mismatch on bone {b}");
                AssertNear(Mathf.DeltaAngle(fwdStart[b].angle, revEnd[b].angle), 0f, 1e-3f, $"Reversed clip t=dur mismatch on bone {b}");
            }

            if (DefDatabase<PawnCapacityDef>.DefCount == 0)
            {
                DefDatabase<PawnCapacityDef>.Add(new PawnCapacityDef { defName = "Moving" });
                typeof(DefDatabase<PawnCapacityDef>).GetMethod("SetIndices", BindingFlags.Static | BindingFlags.NonPublic)?.Invoke(null, null);
            }

            var testBodyDef = new BodyDef
            {
                defName = "Test_ColossusBody",
                corePart = new BodyPartRecord
                {
                    def = new BodyPartDef { defName = "GCF_MechChassis", hitPoints = 320 },
                    parts = new List<BodyPartRecord>
                    {
                        new BodyPartRecord { def = new BodyPartDef { defName = "GCF_MechBlastShieldLeft", hitPoints = 110 } }
                    }
                }
            };
            testBodyDef.corePart.body = testBodyDef;
            testBodyDef.corePart.parts[0].body = testBodyDef;
            testBodyDef.corePart.parts[0].parent = testBodyDef.corePart;
            testBodyDef.ResolveReferences();

            var colPawn = new Pawn
            {
                thingIDNumber = 95001,
                def = new ThingDef
                {
                    defName = "GCF_MechColossus",
                    race = new RaceProperties
                    {
                        body = testBodyDef,
                        baseBodySize = 9.5f,
                        baseHealthScale = 6.5f,
                        lifeStageAges = new List<LifeStageAge>
                        {
                            new LifeStageAge
                            {
                                minAge = 0f,
                                def = new RimWorld.LifeStageDef { defName = "MechanoidFullyFormed", healthScaleFactor = 1f, bodySizeFactor = 1f }
                            }
                        }
                    }
                },
                kindDef = new PawnKindDef { defName = "GCF_MechColossus", canMeleeAttack = false }
            };
            colPawn.ageTracker = new Pawn_AgeTracker(colPawn);
            typeof(Pawn_AgeTracker).GetField("cachedLifeStageIndex", BindingFlags.Instance | BindingFlags.NonPublic)?.SetValue(colPawn.ageTracker, 0);
            colPawn.health = new Pawn_HealthTracker(colPawn);
            var colRigComp = new CompGiantRig { parent = colPawn };
            colRigComp.Initialize(new CompProperties_GiantRig { rigDef = colRig1 });
            var phaseProps = new CompProperties_GiantPhaseTransform
            {
                stages = new List<GiantPhaseStageDef>
                {
                    new GiantPhaseStageDef { stageId = "s1", rigDef = colRig1, morphOutToNextClip = mOut1 },
                    new GiantPhaseStageDef { stageId = "s2", rigDef = colRig2, morphInFromPrevClip = mIn2, morphOutToNextClip = mOut2, transitionEmpDamage = 45, transitionBlastDamage = 80, transitionBlastRadius = 7.5f },
                    new GiantPhaseStageDef { stageId = "s3", rigDef = colRig3, morphInFromPrevClip = mIn3, transitionEmpDamage = 65, transitionBlastDamage = 120, transitionBlastRadius = 9.5f }
                }
            };
            var phaseComp = new CompGiantPhaseTransform { parent = colPawn };
            phaseComp.Initialize(phaseProps);
            typeof(ThingWithComps).GetField("comps", BindingFlags.Instance | BindingFlags.NonPublic)!
                .SetValue(colPawn, new List<ThingComp> { colRigComp, phaseComp });
            GiantFastLookup.Register(colPawn, colRigComp);
            GiantFastLookup.RegisterPhaseTransform(colPawn, phaseComp);

            try
            {
                // Stage 1 (index 0): cannot revert (already initial stage), can advance
                Assert(phaseComp.CurrentStageIndex == 0 && phaseComp.IsAtFullState, "Stage 1 fresh unit must be at full state");
                Assert(!phaseComp.CanManuallyRevertToPreviousStage(out string s1RevKey, out _) && s1RevKey == "GCF_PhaseRevertDisabledFirstStage",
                    "Stage 1 must block revert with GCF_PhaseRevertDisabledFirstStage");
                Assert(phaseComp.CanManuallyAdvanceToNextStage(out _, out _), "Stage 1 must allow advance");

                // Advance to Stage 2 (index 1) and finish MorphingIn
                phaseComp.ForceAdvanceStageImmediateForTest();
                typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(phaseComp, null);
                Assert(phaseComp.CurrentStageIndex == 1 && !phaseComp.IsTransforming && phaseComp.IsAtFullState, "Must be in Stage 2 at full state");

                // At FULL state in Stage 2: manual rollback to Stage 1 MUST be allowed!
                Assert(phaseComp.CanManuallyRevertToPreviousStage(out _, out _), "Stage 2 at full state must allow manual revert to Stage 1");
                Assert(phaseComp.ForceRevertStageImmediateForTest(), "ForceRevertStageImmediateForTest must succeed at full state");
                typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(phaseComp, null);
                Assert(phaseComp.CurrentStageIndex == 0 && colRigComp.RigDef == colRig1, "Must have reverted cleanly back to Stage 1 rig");

                // Advance to Stage 2 again, then apply damage (NON-FULL state -> revert forbidden, ONLY advance allowed!)
                phaseComp.ForceAdvanceStageImmediateForTest();
                typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(phaseComp, null);
                var inj = new Hediff_Injury
                {
                    pawn = colPawn,
                    def = new HediffDef { defName = "Cut", isBad = true },
                    Severity = 12f
                };
                colPawn.health.hediffSet.hediffs.Add(inj);

                Assert(!phaseComp.IsAtFullState, "Damaged Colossus must report IsAtFullState == false");
                Assert(!phaseComp.CanManuallyRevertToPreviousStage(out string dmgRevKey, out _) && dmgRevKey == "GCF_PhaseRevertDisabledNotFullState",
                    $"Damaged Colossus must forbid manual revert with GCF_PhaseRevertDisabledNotFullState, got {dmgRevKey}");
                Assert(!phaseComp.TryRevertToPreviousStageManually(), "TryRevertToPreviousStageManually must return false when not at full state");
                Assert(phaseComp.CanManuallyAdvanceToNextStage(out _, out _),
                    "Damaged Colossus in Stage 2 MUST still allow advancing to Stage 3 ('不满时只能进下个阶段')");

                // Advance while damaged -> Stage 3 restores full health -> at full state in Stage 3 can revert to Stage 2!
                phaseComp.ForceAdvanceStageImmediateForTest();
                typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(phaseComp, null);
                Assert(phaseComp.CurrentStageIndex == 2 && phaseComp.IsAtFullState, "Stage 3 after forward advance must be at full state");
                Assert(!phaseComp.CanManuallyAdvanceToNextStage(out string s3AdvKey, out _) && s3AdvKey == "GCF_PhaseAdvanceDisabledFinalStage",
                    "Stage 3 must disable further advance");
                Assert(phaseComp.CanManuallyRevertToPreviousStage(out _, out _), "Stage 3 at full state must allow manual revert to Stage 2");

                // Missing part also counts as non-full state and blocks revert
                var missingPart = new Hediff_MissingPart
                {
                    pawn = colPawn,
                    def = new HediffDef { defName = "MissingBodyPart", isBad = true }
                };
                colPawn.health.hediffSet.hediffs.Add(missingPart);
                Assert(!phaseComp.IsAtFullState && !phaseComp.TryRevertToPreviousStageManually(),
                    "Missing body part must count as non-full state and block Stage 3 -> Stage 2 revert");
                colPawn.health.hediffSet.hediffs.Remove(missingPart);
                Assert(phaseComp.ForceRevertStageImmediateForTest() && phaseComp.CurrentStageIndex == 1 && colRigComp.RigDef == colRig2,
                    "Restored Stage 3 at full state must revert cleanly to Stage 2");
                typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(phaseComp, null);

                // Frame-staggered dual shockwave & in-place PawnRenderNode_GiantRoot subtree swap verification
                var mockDrawer = (Pawn_DrawTracker)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Pawn_DrawTracker));
                var mockRenderer = (PawnRenderer)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(PawnRenderer));
                typeof(PawnRenderer).GetField("woundOverlays", BindingFlags.Instance | BindingFlags.NonPublic)?.SetValue(mockRenderer, new RimWorld.PawnWoundDrawer(colPawn));
                var mockTree = new PawnRenderTree(colPawn);
                var mockRoot = new PawnRenderNode_GiantRoot(colPawn, new PawnRenderNodeProperties_GiantRoot(), mockTree);
                mockTree.rootNode = mockRoot;
                mockRenderer.renderTree = mockTree;
                mockDrawer.renderer = mockRenderer;
                typeof(Pawn).GetField("drawer", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(colPawn, mockDrawer);

                colRigComp.PrewarmStageRenderSubtree(colRig1);
                colRigComp.PrewarmStageRenderSubtree(colRig2);
                colRigComp.PrewarmStageRenderSubtree(colRig3);
                Assert(colRigComp.CachedStageSubtreeCount == 3,
                    $"Expected 3 prewarmed stage render subtrees, got {colRigComp.CachedStageSubtreeCount}");

                colRigComp.SwitchRig(colRig2);
                PawnRenderNode[] s2ChildrenCached = mockRoot.children;
                Assert(colRigComp.InPlaceSubtreeSwapCount == 1 && s2ChildrenCached != null && s2ChildrenCached.Length >= 64 && mockRoot.requestRecache,
                    "SwitchRig(colRig2) must swap PawnRenderNode_GiantRoot.children in-place and set requestRecache");
                mockRoot.requestRecache = false;

                // Begin Stage 2 -> Stage 3 transformation and verify Tick 0 schedules waves without firing either explosion synchronously
                MethodInfo completeMorphOutMi = typeof(CompGiantPhaseTransform).GetMethod("CompleteMorphOutAndSwitchRig", BindingFlags.Instance | BindingFlags.NonPublic)!;
                FieldInfo morphElapsedFi = typeof(CompGiantPhaseTransform).GetField("morphElapsedTicks", BindingFlags.Instance | BindingFlags.NonPublic)!;
                MethodInfo finishMi = typeof(CompGiantPhaseTransform).GetMethod("FinishTransformation", BindingFlags.Instance | BindingFlags.NonPublic)!;

                phaseComp.BeginNextStageTransformation();
                Assert(phaseComp.MorphState == PhaseMorphState.MorphingOut, "Must enter MorphingOut for Stage 2 -> Stage 3");
                completeMorphOutMi.Invoke(phaseComp, null);
                Assert(phaseComp.CurrentStageIndex == 2 && phaseComp.MorphState == PhaseMorphState.MorphingIn,
                    "CompleteMorphOutAndSwitchRig must advance to Stage 3 MorphingIn");
                Assert(colRigComp.InPlaceSubtreeSwapCount == 2 && mockRoot.children != null && !ReferenceEquals(mockRoot.children, s2ChildrenCached),
                    "CompleteMorphOutAndSwitchRig must perform in-place subtree swap to Stage 3 children");
                Assert(phaseComp.HasPendingEmpWave && phaseComp.HasPendingBlastWave
                    && phaseComp.ExecutedEmpWaveCount == 0 && phaseComp.ExecutedBlastWaveCount == 0,
                    "Tick 0 of MorphingIn must arm both transition waves with 0 synchronous explosions");

                // Revert back to Stage 2 after testing early FinishTransformation wave flush
                finishMi.Invoke(phaseComp, null);
                Assert(!phaseComp.HasPendingEmpWave && !phaseComp.HasPendingBlastWave
                    && phaseComp.ExecutedEmpWaveCount == 1 && phaseComp.ExecutedBlastWaveCount == 1,
                    "Early FinishTransformation must flush both pending waves cleanly");

                // Verify round-trip Stage 3 -> Stage 2 reuses exact cached Stage 2 PawnRenderNode[] with zero reallocation and zero waves on revert
                Assert(phaseComp.TryRevertToPreviousStageManually(), "Stage 3 manual revert must start");
                completeMorphOutMi.Invoke(phaseComp, null);
                Assert(!phaseComp.HasPendingEmpWave && !phaseComp.HasPendingBlastWave,
                    "Reverting stage must not arm transition explosion waves");
                Assert(colRigComp.InPlaceSubtreeSwapCount == 3 && colRigComp.CachedStageSubtreeCount == 3
                    && ReferenceEquals(mockRoot.children, s2ChildrenCached),
                    "Stage 3 -> Stage 2 revert must reuse exact cached Stage 2 PawnRenderNode[] array with zero reallocation");
                finishMi.Invoke(phaseComp, null);

                // Verify MorphingIn tick-by-tick wave staggering (Tick +1 = 0 waves, Tick +2 = EMP only, Tick +5 = Blast)
                MethodInfo tickMorphMi = typeof(CompGiantPhaseTransform).GetMethod("TickMorphState", BindingFlags.Instance | BindingFlags.NonPublic)!;
                try
                {
                    phaseComp.BeginNextStageTransformation();
                    completeMorphOutMi.Invoke(phaseComp, null);
                    int baseEmp = phaseComp.ExecutedEmpWaveCount;
                    int baseBlast = phaseComp.ExecutedBlastWaveCount;

                    // Tick 1: morphElapsedTicks increments 0 -> 1 (< 2)
                    tickMorphMi.Invoke(phaseComp, null);
                    Assert(phaseComp.ExecutedEmpWaveCount == baseEmp && phaseComp.ExecutedBlastWaveCount == baseBlast,
                        "MorphingIn Tick +1 must not detonate EMP or Blast wave yet");

                    // Tick 2: morphElapsedTicks increments 1 -> 2 (== StaggeredEmpWaveDelayTicks)
                    tickMorphMi.Invoke(phaseComp, null);
                    Assert(phaseComp.ExecutedEmpWaveCount == baseEmp + 1 && !phaseComp.HasPendingEmpWave
                        && phaseComp.ExecutedBlastWaveCount == baseBlast && phaseComp.HasPendingBlastWave,
                        "MorphingIn Tick +2 must detonate ONLY Wave 1 (EMP) while keeping Wave 2 (Blast) pending");

                    // Tick 3 & 4: morphElapsedTicks = 3, 4 (< 5)
                    tickMorphMi.Invoke(phaseComp, null);
                    tickMorphMi.Invoke(phaseComp, null);
                    Assert(phaseComp.ExecutedBlastWaveCount == baseBlast && phaseComp.HasPendingBlastWave,
                        "MorphingIn Ticks +3..+4 must keep Wave 2 pending until Tick +5");

                    // Tick 5: morphElapsedTicks = 5 (== StaggeredBlastWaveDelayTicks)
                    tickMorphMi.Invoke(phaseComp, null);
                    Assert(phaseComp.ExecutedBlastWaveCount == baseBlast + 1 && !phaseComp.HasPendingBlastWave,
                        "MorphingIn Tick +5 must detonate Wave 2 (Blast) on separate frame from Wave 1");
                }
                finally
                {
                    typeof(Pawn).GetField("drawer", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(colPawn, null);
                    finishMi.Invoke(phaseComp, null);
                }
            }
            finally
            {
                GiantFastLookup.UnregisterPhaseTransform(colPawn);
                GiantFastLookup.Unregister(colPawn);
            }

            // 5. Verify MechColossus XML: GCF_Ability_MechPhaseRevert on Stage 2 & Stage 3 + 12-Seat CompProperties_GiantCockpit
            XDocument colAbilDoc = XDocument.Load(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_MechColossus.xml"));
            Assert(colAbilDoc.Root!.Elements("AbilityDef").Any(e => e.Element("defName")?.Value == "GCF_Ability_MechPhaseRevert"),
                "Abilities_MechColossus.xml must define GCF_Ability_MechPhaseRevert");

            XDocument colRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_MechColossus.xml"));
            XElement colThingEl = colRaceDoc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_MechColossus");
            List<XElement> stageEls = colThingEl.Descendants("stages").First().Elements("li").ToList();
            Assert(stageEls.Count == 3, $"Expected 3 stages on GCF_MechColossus, got {stageEls.Count}");
            Assert(!stageEls[0].Element("stageAbilities")!.Elements("li").Any(e => e.Value == "GCF_Ability_MechPhaseRevert"),
                "Stage 1 must not mount GCF_Ability_MechPhaseRevert");
            Assert(stageEls[1].Element("stageAbilities")!.Elements("li").Any(e => e.Value == "GCF_Ability_MechPhaseRevert")
                   && stageEls[1].Element("stageAbilities")!.Elements("li").Any(e => e.Value == "GCF_Ability_MechPhaseAdvance"),
                "Stage 2 must mount both GCF_Ability_MechPhaseAdvance and GCF_Ability_MechPhaseRevert");
            Assert(stageEls[2].Element("stageAbilities")!.Elements("li").Any(e => e.Value == "GCF_Ability_MechPhaseRevert"),
                "Stage 3 must mount GCF_Ability_MechPhaseRevert");

            XElement colCockpitEl = colThingEl.Element("comps")!.Elements("li")
                .FirstOrDefault(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_GiantCockpit");
            Assert(colCockpitEl != null, "GCF_MechColossus must mount CompProperties_GiantCockpit");
            Assert(ParseBool(colCockpitEl.Element("autonomousWhenEmpty")?.Value, false),
                "GCF_MechColossus must keep autonomousWhenEmpty=true so unboarded Colossus retains onboard AI");
            List<XElement> colSeats = colCockpitEl.Element("seats")!.Elements("li").ToList();
            Assert(colSeats.Count == 12, $"Expected max 12 seats on GCF_MechColossus, got {colSeats.Count}");

            var seatIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            XDocument colBodyDoc = XDocument.Load(ResolveMod17Path("Defs", "Bodies", "Bodies_MechColossus.xml"));
            HashSet<string> colBodyParts = colBodyDoc.Descendants("BodyDef").First()
                .Descendants("def").Select(d => d.Value).ToHashSet();
            int pilotCnt = 0, cmdCnt = 0, gunCnt = 0, paxCnt = 0;
            foreach (XElement sEl in colSeats)
            {
                string sid = sEl.Element("seatId")!.Value;
                Assert(seatIds.Add(sid), $"Duplicate seatId '{sid}' on GCF_MechColossus");
                string linked = sEl.Element("linkedBodyPart")!.Value;
                Assert(colBodyParts.Contains(linked), $"MechColossus seat '{sid}' references missing BodyPartDef '{linked}'");
                switch (sEl.Element("role")!.Value)
                {
                    case "PrimaryPilot": pilotCnt++; break;
                    case "Commander": cmdCnt++; break;
                    case "Gunner": gunCnt++; break;
                    case "Passenger": paxCnt++; break;
                }
            }
            Assert(pilotCnt == 1 && cmdCnt == 1 && gunCnt == 2 && paxCnt == 8,
                $"Expected 1 Pilot + 1 Commander + 2 Gunners + 8 Passengers (=12), got {pilotCnt}/{cmdCnt}/{gunCnt}/{paxCnt}");

            // 6. Verify HarmonyPatches_PlayerControl targets, FloatMenu providers, null-equipment guard & queued-job dequeuing
            int ctrlPatchCount = 0;
            foreach (MethodInfo pm in typeof(HarmonyPatches_PlayerControl).GetMethods(BindingFlags.Public | BindingFlags.Static))
            {
                var attrs = pm.GetCustomAttributes<HarmonyPatch>(inherit: false).ToArray();
                if (attrs.Length == 0) continue;
                Type declType = null;
                string methodName = null;
                Type[] argTypes = null;
                MethodType mType = MethodType.Normal;
                foreach (HarmonyPatch hp in attrs)
                {
                    if (hp.info.declaringType != null) declType = hp.info.declaringType;
                    if (!string.IsNullOrEmpty(hp.info.methodName)) methodName = hp.info.methodName;
                    if (hp.info.argumentTypes != null) argTypes = hp.info.argumentTypes;
                    if (hp.info.methodType.HasValue) mType = hp.info.methodType.Value;
                }
                MethodBase resolved = mType == MethodType.Getter
                    ? AccessTools.PropertyGetter(declType, methodName)
                    : mType == MethodType.Setter
                        ? AccessTools.PropertySetter(declType, methodName)
                        : (argTypes != null ? AccessTools.Method(declType, methodName, argTypes) : AccessTools.Method(declType, methodName));
                Assert(resolved != null, $"Failed to resolve HarmonyPatches_PlayerControl target {declType?.FullName}.{methodName} ({mType}) for {pm.Name}");
                ctrlPatchCount++;
            }
            Assert(ctrlPatchCount >= 14, $"Expected >= 14 HarmonyPatches_PlayerControl patches, got {ctrlPatchCount}");

            Assert(typeof(RimWorld.FloatMenuOptionProvider).IsAssignableFrom(typeof(FloatMenuOptionProvider_EnterGiantCockpit)) && !typeof(FloatMenuOptionProvider_EnterGiantCockpit).IsAbstract,
                "FloatMenuOptionProvider_EnterGiantCockpit must be a concrete FloatMenuOptionProvider");
            Assert(typeof(RimWorld.FloatMenuOptionProvider).IsAssignableFrom(typeof(FloatMenuOptionProvider_GiantControl)) && !typeof(FloatMenuOptionProvider_GiantControl).IsAbstract,
                "FloatMenuOptionProvider_GiantControl must be a concrete FloatMenuOptionProvider");

            bool useRangedRes = true;
            bool runOrig = HarmonyPatches_CombatAndHitbox.FloatMenuUtility_UseRangedAttack_Prefix(new Pawn(), ref useRangedRes);
            Assert(!runOrig && !useRangedRes, "FloatMenuUtility_UseRangedAttack_Prefix must short-circuit cleanly when pawn.equipment is null");

            var testColossus = new Pawn { thingIDNumber = 994201, def = new ThingDef { defName = "GCF_MechColossus", race = new RaceProperties() } };
            testColossus.health = new Pawn_HealthTracker(testColossus);
            testColossus.jobs = new Verse.AI.Pawn_JobTracker(testColossus);
            var queuedGoto = new Verse.AI.Job
            {
                def = new JobDef { defName = "Goto", driverClass = typeof(Verse.AI.JobDriver_Goto) },
                targetA = new LocalTargetInfo(new IntVec3(12, 0, 15))
            };
            testColossus.jobs.jobQueue.EnqueueFirst(queuedGoto, Verse.AI.JobTag.Misc);
            Verse.AI.ThinkResult draftedThink = ThinkNode_GiantPlayerDrafted.Instance.TryIssueJobPackage(testColossus, default);
            Assert(draftedThink.Job == queuedGoto && draftedThink.FromQueue && draftedThink.SourceNode == ThinkNode_GiantPlayerDrafted.Instance,
                "ThinkNode_GiantPlayerDrafted must dequeue player-ordered jobs from jobQueue with SourceNode=ThinkNode_GiantPlayerDrafted.Instance");
            Assert(testColossus.jobs.jobQueue.Count == 0, "Queued job must be consumed from jobQueue");

            // Verify 4-language Keyed 1:1 parity across CN, EN, JA, RU including all new FloatMenu control keys
            var enSet = XDocument.Load(ResolveMod17Path("Languages", "English", "Keyed", "GiantCreatureFramework_Keys.xml"))
                .Root!.Elements().Select(e => e.Name.LocalName).ToHashSet();
            foreach (string reqCtrlKey in new[]
            {
                "GCF_FloatMenu_TakeCockpitControl", "GCF_FloatMenu_BoardRoleOpenCount",
                "GCF_FloatMenu_DraftControl", "GCF_FloatMenu_UndraftControl",
                "GCF_FloatMenu_DraftAndMoveHere", "GCF_FloatMenu_DraftAndFocusAttack",
                "GCF_FloatMenu_SwitchAutonomousOn", "GCF_FloatMenu_SwitchStandbyOn",
                "GCF_FloatMenu_PartFireAtWillOn", "GCF_FloatMenu_PartFireAtWillOff",
                "GCF_FloatMenu_PhaseAdvance", "GCF_FloatMenu_PhaseRevert", "GCF_FloatMenu_PhaseDisabled"
            })
            {
                Assert(enSet.Contains(reqCtrlKey), $"Missing right-click control key '{reqCtrlKey}'");
            }
            foreach (string lang in new[] { "ChineseSimplified", "Japanese", "Russian" })
            {
                var lSet = XDocument.Load(ResolveMod17Path("Languages", lang, "Keyed", "GiantCreatureFramework_Keys.xml"))
                    .Root!.Elements().Select(e => e.Name.LocalName).ToHashSet();
                Assert(enSet.SetEquals(lSet), $"{lang} Keyed XML keys must match English 1:1");
            }

            Console.WriteLine("       -> Verified FixedWing/VTOL/HeavyAirship flight vehicle physics, full-state-only manual phase rollback, Colossus 12-seat cockpit & right-click control menus");
        }

        private static void TestGizmoStreamliningAirborneZeroCollisionAndHighLayer()
        {
            // 1. Airborne Zero Collision Volume while preserving HitCells & LandingCollisionOffsets
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml");
            int nCount = rathRig.SortedNodes.Length;
            var poses = new BoneWorldPose[nCount];
            SkeletalKinematics.SolveWorldPoses(
                rathRig,
                new Vector2(50.5f, 50.5f),
                0f,
                ReadOnlySpan<BoneLocalPose>.Empty,
                ReadOnlySpan<bool>.Empty,
                poses);

            var fp = new GiantFootprintData();
            fp.Rebuild(rathRig, poses, rathMasks, new IntVec3(50, 0, 50), new IntVec3(150, 1, 150));
            int groundedHitCount = fp.hitCells.Count;
            int groundedColCount = fp.collisionCells.Count;
            int groundedOffsetsCount = fp.localCollisionOffsets.Count;
            Assert(groundedHitCount > 20 && groundedColCount > 10 && groundedOffsetsCount == groundedColCount,
                $"Grounded Rathalos must have positive hit & collision cells (hit={groundedHitCount}, col={groundedColCount})");

            fp.ClearCollisionVolume();
            Assert(fp.collisionCells.Count == 0
                   && fp.collisionCellSet.Count == 0
                   && fp.localCollisionOffsets.Count == 0
                   && fp.maxCollisionHorizontalExtent == 0
                   && fp.tightCollisionBounds == CellRect.Empty
                   && !fp.collisionAnchorCell.IsValid,
                "Airborne ClearCollisionVolume() must strip 100% of ground collision cells, bounds, and extent");
            Assert(fp.hitCells.Count == groundedHitCount
                   && fp.hitCells.All(h => !h.isCollisionCell && h.collisionCoverage == 0f),
                "Airborne ClearCollisionVolume() must preserve 100% of ranged/selection hitCells while clearing isCollisionCell flags");
            Assert(fp.LandingCollisionOffsets.Count == groundedOffsetsCount,
                "Airborne ClearCollisionVolume() must retain LandingCollisionOffsets so SafeLandingSpotResolver checks full grounded hull on touchdown");

            // 2. Above-FogOfWar High Render Layer & Worker-Thread Parity
            var carrierFlight = new GiantFlightDef
            {
                flightMode = GiantFlightMode.AlwaysAirborne,
                altitudeTier = FlightAltitudeTier.HighAirborne,
                renderLayerAltitudeBoost = 3.2f
            };
            var carrierRt = new GiantFlightRuntime(rathRig, carrierFlight);
            float groundAliveAlt = CompGiantRig.GroundAliveBaseAltitudeY;
            float moteOverheadAlt = Altitudes.AltitudeFor(AltitudeLayer.MoteOverhead);
            float gasAlt = Altitudes.AltitudeFor(AltitudeLayer.Gas);
            float skyfallerAlt = Altitudes.AltitudeFor(AltitudeLayer.Skyfaller);
            float weatherAlt = Altitudes.AltitudeFor(AltitudeLayer.Weather);
            float fogOfWarAlt = Altitudes.AltitudeFor(AltitudeLayer.FogOfWar);
            float darknessAlt = Altitudes.AltitudeFor(AltitudeLayer.Darkness);
            float worldClipperAlt = Altitudes.AltitudeFor(AltitudeLayer.WorldClipper);

            float boostMain = CompGiantRig.ComputeAirborneRenderAltitudeBoost(false, carrierRt, thingIdNumber: 5);
            float boostWorker = System.Threading.Tasks.Task.Run(
                () => CompGiantRig.ComputeAirborneRenderAltitudeBoost(false, carrierRt, thingIdNumber: 5)).GetAwaiter().GetResult();
            AssertNear(boostWorker, boostMain, 1e-6f,
                "ComputeAirborneRenderAltitudeBoost must return identical non-zero altitude boost on background PawnRenderTree worker threads");

            float airborneWorldY = groundAliveAlt + boostMain;
            Assert(airborneWorldY > moteOverheadAlt
                   && airborneWorldY > gasAlt
                   && airborneWorldY > skyfallerAlt
                   && airborneWorldY > weatherAlt
                   && airborneWorldY > fogOfWarAlt
                   && airborneWorldY > darknessAlt
                   && airborneWorldY < worldClipperAlt,
                $"HighAirborne world-Y ({airborneWorldY:F3}) must render above MoteOverhead ({moteOverheadAlt:F3}), Skyfaller ({skyfallerAlt:F3}), Weather ({weatherAlt:F3}), FogOfWar ({fogOfWarAlt:F3}), and Darkness ({darknessAlt:F3}), yet strictly below WorldClipper ({worldClipperAlt:F3})");

            float entryBoost = CompGiantRig.ComputeAirborneRenderAltitudeBoost(true, null, thingIdNumber: 15);
            Assert(groundAliveAlt + entryBoost > fogOfWarAlt && groundAliveAlt + entryBoost > darknessAlt && groundAliveAlt + entryBoost < worldClipperAlt,
                "Flying-entry altitude boost must sit strictly above FogOfWar/Darkness and below WorldClipper");

            // 3. Harmony Collision Patch & Zero Duplicate Ability Gizmo Loops
            Assert(AccessTools.Method(typeof(RimWorld.PawnUtility), nameof(RimWorld.PawnUtility.ShouldCollideWithPawns)) != null
                   && AccessTools.Method(typeof(HarmonyPatches_CollisionAndSelection), nameof(HarmonyPatches_CollisionAndSelection.PawnUtility_ShouldCollideWithPawns_Postfix)) != null,
                "PawnUtility.ShouldCollideWithPawns Harmony postfix must resolve cleanly");

            foreach (string relFile in new[]
            {
                Path.Combine("Abilities", "GiantEntitySkillSystem.cs"),
                Path.Combine("Components", "CompGiantPhaseTransform.cs"),
                Path.Combine("Carrier", "ProtossCarrierSystem.cs")
            })
            {
                string src = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", relFile));
                Assert(!src.Contains("pawn.abilities.GetGizmos()", StringComparison.Ordinal),
                    $"{relFile} must not duplicate pawn.abilities.GetGizmos() inside CompGetGizmosExtra");
            }

            string cockpitSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Vehicle", "CompGiantCockpit.cs"));
            Assert(!cockpitSrc.Contains("var boardCmd = new Command_Action", StringComparison.Ordinal),
                "CompGiantCockpit.CompGetGizmosExtra must omit redundant BoardCrew gizmo button (already in ITab & FloatMenu)");

            // 4. Narrative Lore Quality Gate: zero demo/meta/CAD tokens across all Defs, Biotech, Anomaly & 4-language XMLs
            string[] bannedDemoTokens =
            {
                "512x512", "showcase", "Giant Creature Framework", "巨型生物框架", "巨大生物フレームワーク",
                "Каркас гигантских существ", "原生攻击", "原生攻撃", "собственных атак", "Verlet", "XPBD",
                "怪物猎人", "Monster Hunter", "星际争霸", "StarCraft", "1.5x", "1.5倍", "1,5 раза",
                "实体守恒", "conjured from nowhere", "180-degree", "170-degree"
            };
            int auditedXmlFiles = 0;
            foreach (string subDir in new[] { "Defs", "Biotech", "Languages" })
            {
                foreach (string xmlFile in EnumerateAllMod17Files(subDir, "*.xml", SearchOption.AllDirectories))
                {
                    XDocument doc = XDocument.Load(xmlFile);
                    auditedXmlFiles++;
                    if (xmlFile.Contains("AuthoringTerminal", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                    bool isDefInjected = xmlFile.Contains("DefInjected", StringComparison.OrdinalIgnoreCase);
                    foreach (XElement descEl in doc.Descendants().Where(e =>
                        e.Name.LocalName == "description" ||
                        (isDefInjected && e.Name.LocalName.EndsWith(".description", StringComparison.Ordinal))))
                    {
                        string val = descEl.Value ?? string.Empty;
                        foreach (string banned in bannedDemoTokens)
                        {
                            Assert(!val.Contains(banned, StringComparison.OrdinalIgnoreCase),
                                $"Found leftover demo/technical token '{banned}' in {Path.GetRelativePath(ModRoot, xmlFile)} <{descEl.Name.LocalName}>");
                        }
                    }
                }
            }
            Assert(auditedXmlFiles >= 120, $"Expected >= 120 XML files audited for narrative descriptions, got {auditedXmlFiles}");

            Console.WriteLine($"       -> Verified airborne 0-collision volume (hit={fp.hitCells.Count}, col=0), Skyfaller high-layer Y={airborneWorldY:F3}, streamlined Gizmos, & {auditedXmlFiles} narrative XML files");
        }

        private static void TestReusableSkinnedMeshLbsAndManualIntegrity()
        {
            // 1. Build a 3-bone wing rig with a declarative GiantSkinnedMeshDef (<skinnedMeshes>)
            var rig = new GiantRigDef
            {
                defName = "Test_SkinnedWyvernRig",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef
                    {
                        nodeId = "thorax",
                        texPath = "Test/Thorax",
                        drawSize = new Vector2(4.0f, 4.0f),
                        pivotPixel = new Vector2(256f, 256f),
                        layerOffset = 2.0f
                    },
                    new BoneNodeDef
                    {
                        nodeId = "wing_inner",
                        parentId = "thorax",
                        texPath = "Test/WingInner",
                        drawSize = new Vector2(3.0f, 2.0f),
                        pivotPixel = new Vector2(440f, 256f),
                        parentSocketPixel = new Vector2(128f, 256f),
                        layerOffset = 3.0f,
                        hideWhenMissing = true
                    },
                    new BoneNodeDef
                    {
                        nodeId = "wing_outer",
                        parentId = "wing_inner",
                        texPath = "Test/WingOuter",
                        drawSize = new Vector2(3.2f, 2.0f),
                        pivotPixel = new Vector2(440f, 256f),
                        parentSocketPixel = new Vector2(64f, 256f),
                        layerOffset = 4.0f,
                        hideWhenMissing = true
                    }
                },
                skinnedMeshes = new List<GiantSkinnedMeshDef>
                {
                    new GiantSkinnedMeshDef
                    {
                        meshId = "left_patagium",
                        texPath = "Test/Patagium",
                        silhouetteTexPath = "Test/Patagium_Sil",
                        anchorBoneId = "thorax",
                        drawSize = new Vector2(6.0f, 4.0f),
                        pivotPixel = new Vector2(420f, 256f),
                        parentSocketPixel = new Vector2(128f, 256f),
                        layerOffset = 1.0f,
                        silhouetteLayerOffset = -8.5f,
                        subdivisionsX = 12,
                        subdivisionsY = 8,
                        weightSharpness = 3.0f,
                        maxInfluences = 4,
                        cullSeveredBoneTriangles = true,
                        boneIds = new List<string> { "thorax", "wing_inner", "wing_outer" }
                    }
                }
            };

            rig.BuildTopology();
            Assert(rig.skinnedMeshes[0].resolvedAnchorBoneIndex == 0, "SkinnedMesh anchorBoneId must resolve to thorax index 0");
            Assert(rig.skinnedMeshes[0].resolvedBoneIndices.Length == 3, "SkinnedMesh boneIds must resolve all 3 bones");

            var smRuntime = new SkinnedMeshRuntime(rig, rig.skinnedMeshes[0]);
            smRuntime.EnsureBindTopology(alphaMask: null);
            Assert(smRuntime.IsBindInitialized, "SkinnedMeshRuntime bind topology must initialize");
            Assert(smRuntime.VertexCount == 13 * 9, $"Expected 117 vertices on 12x8 unmasked grid, got {smRuntime.VertexCount}");
            int fullTriCount = smRuntime.ActiveTriangleCount;
            Assert(fullTriCount == 12 * 8 * 2, $"Expected 192 triangles on 12x8 grid, got {fullTriCount}");

            // 2. Verify exact bind-pose identity: evaluating at rest pose (heading=0, local=Identity) matches restRigXZ
            var poses = new BoneWorldPose[3];
            var localPoses = new BoneLocalPose[] { BoneLocalPose.Identity, BoneLocalPose.Identity, BoneLocalPose.Identity };
            var missing = new bool[] { false, false, false };
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, missing, poses, 1f);
            smRuntime.EvaluateDeformedVertices(poses, Vector2.zero, meshPartMissing: false, out _);
            Assert(smRuntime.IsCurrentlyVisible, "Skinned mesh must be visible when bones are intact");
            Vector3 restTipVert = smRuntime.DeformedVertices[0]; // (gx=0, gy=0) -> outer wingtip corner

            // 3. Rotate wing_inner and wing_outer forward (+32 deg, +24 deg) -> outer vertices must deform smoothly
            localPoses[1] = new BoneLocalPose(Vector2.zero, 32f, Vector2.one);
            localPoses[2] = new BoneLocalPose(Vector2.zero, 24f, Vector2.one);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, missing, poses, 1f);
            smRuntime.EvaluateDeformedVertices(poses, Vector2.zero, meshPartMissing: false, out _);
            Vector3 bentTipVert = smRuntime.DeformedVertices[0];
            float tipDelta = Vector3.Distance(restTipVert, bentTipVert);
            Assert(tipDelta > 0.6f, $"Expected significant LBS vertex displacement when wing bones bend, got {tipDelta:F4}");

            // 4. Sever wing_outer -> dominant wingtip triangles cull cleanly while proximal patagium remains intact
            missing[2] = true;
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, missing, poses, 1f);
            bool idxChanged = smRuntime.EvaluateDeformedVertices(poses, Vector2.zero, meshPartMissing: false, out bool trisChanged);
            Assert(idxChanged || trisChanged, "Severing a skinned bone must flag triangle buffer update");
            Assert(smRuntime.IsCurrentlyVisible, "Remaining intact bones must keep proximal skinned mesh visible");
            Assert(smRuntime.ActiveTriangleCount > 0 && smRuntime.ActiveTriangleCount < fullTriCount,
                $"Expected partial triangle culling on severed outer bone (0 < {smRuntime.ActiveTriangleCount} < {fullTriCount})");

            // 5. Verify the visual manual, unit conventions, XML examples and tool entry points.
            string manualPath = Path.Combine(ModRoot, "Docs", "GiantCreatureFramework_Manual.md");
            Assert(File.Exists(manualPath), $"Manual must exist at {manualPath}");
            string manualText = File.ReadAllText(manualPath);
            Assert(!manualText.Contains("<br>", StringComparison.OrdinalIgnoreCase), "Manual must not contain raw <br> HTML tags inside Markdown tables");
            Assert(manualText.Contains("<skinnedMeshes>", StringComparison.Ordinal) &&
                   manualText.Contains("<isTurret>true</isTurret>", StringComparison.Ordinal) &&
                   manualText.Contains("read_mod_manual", StringComparison.Ordinal) &&
                   manualText.Contains("gcf_archetype_and_def_manual", StringComparison.Ordinal) &&
                   manualText.Contains("durationTicks", StringComparison.Ordinal) &&
                   manualText.Contains("60 Ticks = 1 秒", StringComparison.Ordinal),
                "Manual must document <skinnedMeshes>, <isTurret>, Agent manual tools, and seconds-vs-ticks disambiguation");
            foreach (Rune r in manualText.EnumerateRunes())
            {
                int cp = r.Value;
                bool isEmoji = (cp >= 0x1F300 && cp <= 0x1FAFF) || (cp >= 0x2600 && cp <= 0x27BF);
                Assert(!isEmoji, $"Manual must contain zero Emoji characters per AGENTS.md, found U+{cp:X4}");
            }

            Console.WriteLine($"       -> Verified LBS SkinnedMesh ({smRuntime.VertexCount} verts, tipDelta={tipDelta:F2}, severedTris={fullTriCount}->{smRuntime.ActiveTriangleCount}) & zero-Emoji Manual");
        }

        private static void TestAllGiantsCollisionStrictlyInsideTextureCells()
        {
            var rigSpecs = new (string rigFile, string animFile, string defName)[]
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV"),
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos"),
                ("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax")
            };

            IntVec3 center = new IntVec3(60, 0, 60);
            Vector2 rootXZ = new Vector2(60.5f, 60.5f);
            IntVec3 mapSize = new IntVec3(140, 1, 140);
            float[] headings = { 0f, 45f, 90f, 135f, 180f, 225f, 270f, 315f };

            foreach (var (rigFile, animFile, defName) in rigSpecs)
            {
                var (rig, masks, _) = LoadRigFromXml(rigFile, animFile, defName);
                Assert(rig.coreClearanceRadius <= 1, $"{defName} coreClearanceRadius must be <= 1, got {rig.coreClearanceRadius}");
                Assert(rig.collisionCoverageThreshold >= 0.40f, $"{defName} collisionCoverageThreshold must be >= 0.40, got {rig.collisionCoverageThreshold:F2}");

                int n = rig.SortedNodes.Length;
                var localPoses = Enumerable.Repeat(BoneLocalPose.Identity, n).ToArray();
                var missing = new bool[n];
                var worldPoses = new BoneWorldPose[n];
                var fp = new GiantFootprintData();

                TextureAlphaMask[] softMasks = rig.softWhips != null && rig.softWhips.Count > 0 ? LoadSoftWhipMasks(rig) : Array.Empty<TextureAlphaMask>();

                for (int h = 0; h < headings.Length; h++)
                {
                    float hdg = headings[h];
                    SkeletalKinematics.SolveWorldPoses(rig, rootXZ, hdg, localPoses, missing, worldPoses);

                    SoftWhipRibbonSnapshot[] softSnaps = Array.Empty<SoftWhipRibbonSnapshot>();
                    if (rig.softWhips != null && rig.softWhips.Count > 0)
                    {
                        softSnaps = new SoftWhipRibbonSnapshot[rig.softWhips.Count];
                        BezierChainStepContext idleCtx = default;
                        for (int s = 0; s < rig.softWhips.Count; s++)
                        {
                            var rt = new SoftWhipRuntime(rig.softWhips[s]);
                            rt.Step(rig, rootXZ, hdg, localPoses, missing, false, 0f, in idleCtx);
                            softSnaps[s] = rt.CreateSnapshot(rootXZ);
                        }
                    }

                    fp.Rebuild(rig, worldPoses, masks, center, mapSize, softSnaps, softMasks, center);
                    Assert(fp.collisionCells.Count > 0, $"{defName} at {hdg} deg must produce >= 1 grounded collision cell");

                    var exactTexCells = new HashSet<IntVec3>();
                    int texMinX = int.MaxValue, texMaxX = int.MinValue;
                    int texMinZ = int.MaxValue, texMaxZ = int.MinValue;

                    for (int b = 0; b < n; b++)
                    {
                        if (!worldPoses[b].visible || b >= masks.Length || masks[b] == null || !masks[b].HasAnyOpaquePixels)
                        {
                            continue;
                        }
                        TextureAlphaMask m = masks[b];
                        int step = Math.Max(1, m.width / 128);
                        for (int py = 0; py < m.height; py += step)
                        {
                            float v = (py + 0.5f) / m.height;
                            if (v < m.minV || v >= m.maxV) continue;
                            for (int px = 0; px < m.width; px += step)
                            {
                                if (!m.IsOpaquePixelBottomUp(px, py)) continue;
                                float u = (px + 0.5f) / m.width;
                                Vector2 wxz = worldPoses[b].UVToWorldXZ(u, v);
                                IntVec3 tc = new IntVec3(Mathf.FloorToInt(wxz.x), 0, Mathf.FloorToInt(wxz.y));
                                exactTexCells.Add(tc);
                                if (tc.x < texMinX) texMinX = tc.x;
                                if (tc.x > texMaxX) texMaxX = tc.x;
                                if (tc.z < texMinZ) texMinZ = tc.z;
                                if (tc.z > texMaxZ) texMaxZ = tc.z;
                            }
                        }
                    }

                    for (int s = 0; s < softSnaps.Length; s++)
                    {
                        SoftWhipRibbonSnapshot ws = softSnaps[s];
                        if (ws == null || !ws.visible || ws.stripLeftLocalXZ == null) continue;
                        for (int k = 0; k < ws.stripLeftLocalXZ.Length; k++)
                        {
                            Vector2 lw = ws.rootWorldXZ + ws.stripLeftLocalXZ[k];
                            Vector2 rw = ws.rootWorldXZ + ws.stripRightLocalXZ[k];
                            IntVec3 lc = new IntVec3(Mathf.FloorToInt(lw.x), 0, Mathf.FloorToInt(lw.y));
                            IntVec3 rc = new IntVec3(Mathf.FloorToInt(rw.x), 0, Mathf.FloorToInt(rw.y));
                            exactTexCells.Add(lc);
                            exactTexCells.Add(rc);
                            if (lc.x < texMinX) texMinX = lc.x; if (lc.x > texMaxX) texMaxX = lc.x;
                            if (lc.z < texMinZ) texMinZ = lc.z; if (lc.z > texMaxZ) texMaxZ = lc.z;
                            if (rc.x < texMinX) texMinX = rc.x; if (rc.x > texMaxX) texMaxX = rc.x;
                            if (rc.z < texMinZ) texMinZ = rc.z; if (rc.z > texMaxZ) texMaxZ = rc.z;
                        }
                    }

                    foreach (IntVec3 cc in fp.collisionCells)
                    {
                        Assert(fp.hitCellSet.Contains(cc), $"{defName}@{hdg}: collision cell {cc} must be in hitCellSet");
                        Assert(cc.x >= texMinX && cc.x <= texMaxX && cc.z >= texMinZ && cc.z <= texMaxZ,
                            $"{defName}@{hdg}: collision cell {cc} exceeded outermost texture bounds [{texMinX}..{texMaxX}, {texMinZ}..{texMaxZ}]");

                        bool hasExactPixelInCell = exactTexCells.Contains(cc);
                        if (!hasExactPixelInCell)
                        {
                            for (int sz = 1; sz <= 2 && !hasExactPixelInCell; sz++)
                            {
                                for (int sx = 1; sx <= 2 && !hasExactPixelInCell; sx++)
                                {
                                    float wx = cc.x + 0.125f + 0.25f * sx;
                                    float wz = cc.z + 0.125f + 0.25f * sz;
                                    for (int b = 0; b < n; b++)
                                    {
                                        if (worldPoses[b].visible && rig.SortedNodes[b].contributesToCollision &&
                                            b < masks.Length && masks[b] != null &&
                                            worldPoses[b].TryWorldToUV(wx, wz, out float u, out float v) &&
                                            masks[b].IsOpaqueUV(u, v))
                                        {
                                            hasExactPixelInCell = true;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        Assert(hasExactPixelInCell,
                            $"{defName}@{hdg}: collision cell {cc} has zero rendered opaque texture pixels");
                    }

                    foreach (HitCellEntry he in fp.hitCells)
                    {
                        IntVec3 hc = he.cell;
                        Assert(hc.x >= texMinX && hc.x <= texMaxX && hc.z >= texMinZ && hc.z <= texMaxZ,
                            $"{defName}@{hdg}: hitCell {hc} exceeded outermost projected texture bounds [{texMinX}..{texMaxX}, {texMinZ}..{texMaxZ}]");
                    }

                    if (h == 0)
                    {
                        Console.WriteLine($"       -> {defName}: Hit={fp.hitCells.Count}, Col={fp.collisionCells.Count}, ColRect={fp.tightCollisionBounds}, TexOuter=[{texMinX}..{texMaxX}, {texMinZ}..{texMaxZ}]");
                    }
                }
            }
        }

        private static void TestBrawlOptimizationSuite()
        {
            // 1. LowSkim perimeter hull gap vs under-belly overlap rejection
            var (colRig, colMasks, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            var (abyRig, abyMasks, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");

            var colLocal = new BoneLocalPose[colRig.SortedNodes.Length];
            var colWorld = new BoneWorldPose[colRig.SortedNodes.Length];
            for (int i = 0; i < colLocal.Length; i++) colLocal[i] = BoneLocalPose.Identity;
            SkeletalKinematics.SolveWorldPoses(colRig, new Vector2(60.5f, 60.5f), 0f, colLocal, new bool[colLocal.Length], colWorld);
            var colFp = new GiantFootprintData();
            colFp.Rebuild(colRig, colWorld, colMasks, new IntVec3(60, 0, 60));

            var abyLocal = new BoneLocalPose[abyRig.SortedNodes.Length];
            var abyWorld = new BoneWorldPose[abyRig.SortedNodes.Length];
            for (int i = 0; i < abyLocal.Length; i++) abyLocal[i] = BoneLocalPose.Identity;
            SkeletalKinematics.SolveWorldPoses(abyRig, new Vector2(60.5f, 60.5f), 0f, abyLocal, new bool[abyLocal.Length], abyWorld);
            var abyFp = new GiantFootprintData();
            abyFp.Rebuild(abyRig, abyWorld, abyMasks, new IntVec3(60, 0, 60));

            int centerUnderBellyOverlap = GiantPartCombatRuntime.CountHullOverlapWithForbiddenSet(
                new IntVec3(60, 0, 60), abyFp.localCollisionOffsets, colFp.hitCellSet);
            Assert(centerUnderBellyOverlap > 0,
                $"Expected positive under-belly overlap when AbyssalDragonBeast stands at Stage3 center, got {centerUnderBellyOverlap}");

            bool foundSnugPerimeter = false;
            for (int z = 36; z <= 52; z++)
            {
                IntVec3 cand = new IntVec3(60, 0, z);
                int ov = GiantPartCombatRuntime.CountHullOverlapWithForbiddenSet(cand, abyFp.localCollisionOffsets, colFp.hitCellSet);
                float gapSq = GiantPartCombatRuntime.ComputeHullGapToHitCellsSq(cand, abyFp.localCollisionOffsets, colFp.hitCells, colFp.hitCellSet);
                if (ov == 0 && gapSq >= 1f && gapSq <= 6.25f)
                {
                    foundSnugPerimeter = true;
                    break;
                }
            }
            Assert(foundSnugPerimeter, "Must find a zero-overlap snug melee perimeter cell outside Stage3 LowSkim hitCells");

            // 2. Tuned lethal damage threshold cap on high-bone-count giants
            var mockAbyComp = new CompGiantRig();
            mockAbyComp.Initialize(new CompProperties_GiantRig { rigDef = abyRig });
            float abyLethalMult = GiantCombatMechanicsUtility.ComputeGiantLethalThresholdMultiplier(mockAbyComp);
            AssertNear(abyLethalMult, 6.0f, 1e-4f, $"Expected capped lethal multiplier 6.0f for 32+ bone giant, got {abyLethalMult:F2}");

            // 3. Rathalos non-looping collapse fallback, Bioferrite core focus, Carrier orbit & 2-column HUD wiring
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            Assert(rathRig.downedAnim == null && rathRig.deathAnim != null && !rathRig.deathAnim.loop,
                "GCF_Rig_Rathalos must have non-looping deathAnim available for clamped Downed pose fallback");

            string rigCs = ReadCompGiantRigSource();
            Assert(rigCs.Contains("RigDef.downedAnim ?? RigDef.deathAnim", StringComparison.Ordinal)
                   && rigCs.Contains("raw = raw.parent;", StringComparison.Ordinal),
                "CompGiantRig must wire non-looping downedAnim??deathAnim fallback and ancestor part damage propagation");

            string combatCs = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Combat", "GiantPartCombatSystem.cs"));
            Assert(combatCs.Contains("TryBuildCarrierCombatOrbitGotoJob", StringComparison.Ordinal)
                   && combatCs.Contains("IsLiveLowSkimOpponent", StringComparison.Ordinal),
                "GiantPartCombatSystem.cs must wire Carrier combat standoff orbit and LowSkim perimeter check");

            string aimCs = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Combat", "GiantTargetAimTracker.cs"));
            Assert(aimCs.Contains("TryFindBioferriteCorePriorityCell", StringComparison.Ordinal),
                "GiantTargetAimTracker.cs must prioritize intact CompGiantBioferriteCore bones on low-HP targets");

            string hudCs = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "UI", "GiantBossHealthBarHUD.cs"));
            Assert(hudCs.Contains("if (drawLimit >= 3)", StringComparison.Ordinal)
                   && hudCs.Contains("compactWidthOverride", StringComparison.Ordinal),
                "GiantBossHealthBarHUD.cs must switch to 2-column compact layout when 3+ Boss bars are active");

            Console.WriteLine($"       -> Verified LowSkim perimeter (centerOverlap={centerUnderBellyOverlap}), lethalCap={abyLethalMult:F1}x, Downed fallback, Carrier orbit, Bioferrite focus & 2-col Boss HUD");
        }

        private static void TestDraftedThinkTreeOrdersQueueAnd10kVault()
        {
            // 1. Verify 10,000-pt Colossus Vault floor & zero-drop fallback in [GCF]Mech Colossus
            AssertNear(GameComponent_MechColossusProgression.ColossusVaultMinThreatPoints, 10000f, 1e-3f,
                "ColossusVaultMinThreatPoints must equal 10000f");
            string progCs = File.ReadAllText(Path.Combine(ModsParentDir, "[GCF]Mech Colossus", "Source", "GCF.MechColossus", "Progression", "MechColossusProgressionSystem.cs"));
            Assert(!progCs.Contains("5000f", StringComparison.Ordinal),
                "MechColossusProgressionSystem.cs must not retain any legacy 5000f threat point floor");
            Assert(progCs.Contains("interiorThreatPoints = Mathf.Max(7500f, points * 0.75f)", StringComparison.Ordinal)
                   && progCs.Contains("northGateOutside", StringComparison.Ordinal),
                "GenStep_ColossusVault must enforce >=7500f interior points and guaranteed zero-drop Mechanoid spawn fallback");

            // 2. Verify all 6 XML ThinkTreeDefs embed native ThinkNode_ConditionalGiantPlayerDrafted -> ThinkNode_GiantPlayerDrafted
            string[] thinkTreeFiles =
            {
                "ThinkTrees_Valstrax.xml",
                "ThinkTrees_MechColossus.xml",
                "ThinkTrees_MechScorpion.xml",
                "ThinkTrees_PanzerIV.xml",
                "ThinkTrees_ProtossCarrier.xml",
                "ThinkTrees_Rathalos.xml"
            };
            foreach (string ttFile in thinkTreeFiles)
            {
                XDocument ttDoc = XDocument.Load(ResolveMod17Path("Defs", "ThinkTreeDefs", ttFile));
                XElement mainTree = ttDoc.Root!.Elements("ThinkTreeDef").First();
                var subNodes = mainTree.Element("thinkRoot")!.Element("subNodes")!.Elements("li").ToList();

                Assert(subNodes.Any(e => e.Element("treeDef")?.Value == "Despawned"),
                    $"{ttFile} main ThinkTree must include Despawned guard");

                int draftedIdx = subNodes.FindIndex(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.ThinkNode_ConditionalGiantPlayerDrafted");
                int queuedIdx = subNodes.FindIndex(e => e.Attribute("Class")?.Value == "ThinkNode_QueuedJob");
                Assert(draftedIdx >= 0 && queuedIdx > draftedIdx,
                    $"{ttFile} must place ThinkNode_ConditionalGiantPlayerDrafted strictly before ThinkNode_QueuedJob (draftedIdx={draftedIdx}, queuedIdx={queuedIdx})");
                Assert(subNodes[draftedIdx].Element("subNodes")?.Elements("li")
                           .Any(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.ThinkNode_GiantPlayerDrafted") == true,
                    $"{ttFile} ThinkNode_ConditionalGiantPlayerDrafted must wrap ThinkNode_GiantPlayerDrafted");
            }

            XDocument rathTtDoc = XDocument.Load(ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_Rathalos.xml"));
            XElement rathConst = rathTtDoc.Root!.Elements("ThinkTreeDef").First(e => e.Element("defName")?.Value == "GCF_ThinkTree_RathalosConstant");
            Assert(rathConst.Descendants("treeDef").Any(e => e.Value == "Despawned")
                   && rathConst.Descendants("li").Any(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.ThinkNode_ConditionalAutonomousGiantCanInterrupt"),
                "GCF_ThinkTree_RathalosConstant must guard with Despawned and ThinkNode_ConditionalAutonomousGiantCanInterrupt");

            // 3. Verify ThinkNode_GiantPlayerDrafted Wait_Combat (isIdle=true, canUseRangedWeapon=false) & ignoreQueue=true idle consumption
            RimWorld.JobDefOf.Wait_Combat ??= new JobDef { defName = "Wait_Combat", isIdle = true, driverClass = typeof(Verse.AI.JobDriver_Wait) };
            RimWorld.JobDefOf.Wait_MaintainPosture ??= new JobDef { defName = "Wait_MaintainPosture", isIdle = false, driverClass = typeof(Verse.AI.JobDriver_WaitMaintainPosture) };
            RimWorld.JobDefOf.Wait ??= new JobDef { defName = "Wait", isIdle = true, driverClass = typeof(Verse.AI.JobDriver_Wait) };
            RimWorld.JobDefOf.Wait_Wander ??= new JobDef { defName = "Wait_Wander", isIdle = true, driverClass = typeof(Verse.AI.JobDriver_Wait) };
            RimWorld.JobDefOf.Wait_WithSleeping ??= new JobDef { defName = "Wait_WithSleeping", isIdle = false, driverClass = typeof(Verse.AI.JobDriver_Wait) };

            var p = new Pawn { thingIDNumber = 995501, def = new ThingDef { defName = "GCF_Rathalos", race = new RaceProperties() } };
            p.health = new Pawn_HealthTracker(p);
            p.jobs = new Verse.AI.Pawn_JobTracker(p);

            var nodeCopy = (ThinkNode_GiantPlayerDrafted)ThinkNode_GiantPlayerDrafted.Instance.DeepCopy(resolve: true);
            Verse.AI.ThinkResult idleRes = nodeCopy.TryIssueJobPackage(p, default);
            Assert(idleRes.IsValid
                   && idleRes.Job.def == RimWorld.JobDefOf.Wait_Combat
                   && !idleRes.Job.canUseRangedWeapon
                   && idleRes.Job.expiryInterval == -1
                   && !idleRes.Job.checkOverrideOnExpire
                   && idleRes.SourceNode == nodeCopy
                   && idleRes.Tag == Verse.AI.JobTag.DraftedOrder,
                "Drafted idle giant must receive Wait_Combat (isIdle=true, canUseRangedWeapon=false, expiryInterval=-1, SourceNode=this)");

            // Simulate CheckForJobOverride(ignoreQueue: true) while giant is standing in Wait_MaintainPosture or Wait_Combat with a Shift-queued Goto!
            p.jobs.curJob = new Verse.AI.Job { def = RimWorld.JobDefOf.Wait_MaintainPosture };
            var shiftQueuedGoto = new Verse.AI.Job
            {
                def = new JobDef { defName = "Goto", driverClass = typeof(Verse.AI.JobDriver_Goto) },
                targetA = new LocalTargetInfo(new IntVec3(30, 0, 30))
            };
            p.jobs.jobQueue.EnqueueLast(shiftQueuedGoto, Verse.AI.JobTag.Misc);
            Verse.AI.ThinkResult overrideRes = nodeCopy.TryIssueJobPackage(p, new Verse.AI.JobIssueParams { ignoreQueue = true });
            Assert(overrideRes.Job == shiftQueuedGoto && overrideRes.FromQueue && p.jobs.jobQueue.Count == 0,
                "ThinkNode_GiantPlayerDrafted must consume Shift-queued orders even when CheckForJobOverride passes ignoreQueue=true while standing in an idle/hold job");

            // While actively executing a non-idle Goto, CheckForJobOverride(ignoreQueue: true) must NOT prematurely pop the NEXT waypoint!
            var activeGoto = new Verse.AI.Job
            {
                def = new JobDef { defName = "Goto", isIdle = false, driverClass = typeof(Verse.AI.JobDriver_Goto) },
                targetA = new LocalTargetInfo(new IntVec3(20, 0, 20))
            };
            var secondWaypoint = new Verse.AI.Job
            {
                def = new JobDef { defName = "Goto", isIdle = false, driverClass = typeof(Verse.AI.JobDriver_Goto) },
                targetA = new LocalTargetInfo(new IntVec3(40, 0, 40))
            };
            p.jobs.curJob = activeGoto;
            p.jobs.jobQueue.EnqueueLast(secondWaypoint, Verse.AI.JobTag.Misc);
            Verse.AI.ThinkResult midMoveOverride = nodeCopy.TryIssueJobPackage(p, new Verse.AI.JobIssueParams { ignoreQueue = true });
            Assert(midMoveOverride.Job != secondWaypoint && p.jobs.jobQueue.Count == 1,
                "While actively moving on Waypoint 1, ignoreQueue=true must preserve Waypoint 2 in jobQueue until Waypoint 1 completes");

            // 4. Verify IsAirborneOrTakingOff is immediately true on TakingOff Tick 0 (before altitude01 reaches 0.50)
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var rathFlightDef = new GiantFlightDef
            {
                flightMode = GiantFlightMode.TakeoffAndLanding,
                takeoffDurationTicks = 35,
                autoTakeoffWhenPathBlocked = true
            };
            var rathFlight = new GiantFlightRuntime(rathRig, rathFlightDef);
            rathFlight.ResetForSpawn(42);
            Assert(!rathFlight.IsCurrentlyAirborne && !rathFlight.IsAirborneOrTakingOff, "Grounded Rathalos must start non-airborne");
            Assert(rathFlight.TryCommandTakeoff(null, out _), "TryCommandTakeoff must succeed on healthy Rathalos");
            Assert(!rathFlight.IsCurrentlyAirborne && rathFlight.IsAirborneOrTakingOff,
                "Immediately on TakingOff Tick 0, IsAirborneOrTakingOff must be true so PathFinder builds an aerial path without ErroredPather -> Wait(250)");

            // 5. Verify Harmony patches for Building_Door.PawnCanOpen, Mechanitor cockpit CanControlMechs, and Notify_DeSpawned resolve cleanly
            Assert(AccessTools.Method(typeof(RimWorld.Building_Door), nameof(RimWorld.Building_Door.PawnCanOpen)) != null
                   && AccessTools.Method(typeof(HarmonyPatches_CollisionAndSelection), nameof(HarmonyPatches_CollisionAndSelection.Building_Door_PawnCanOpen_Postfix)) != null,
                "Building_Door.PawnCanOpen postfix must resolve cleanly");
            Assert(AccessTools.PropertyGetter(typeof(RimWorld.Pawn_MechanitorTracker), nameof(RimWorld.Pawn_MechanitorTracker.CanControlMechs)) != null
                   && AccessTools.Method(typeof(RimWorld.Pawn_MechanitorTracker), nameof(RimWorld.Pawn_MechanitorTracker.Notify_DeSpawned)) != null,
                "Pawn_MechanitorTracker cockpit control patches must resolve cleanly in RimWorld 1.7");

            Console.WriteLine("       -> Verified 10,000-pt Vault, 6 XML ThinkTrees, Wait_Combat idle/queue semantics, Tick-0 TakingOff aerial pathing & Mechanitor/Door/Achtung compatibility");
        }

        private static void TestDeepCloseUpBrawlSixFixesRegression()
        {
            // 1. Harmony targets for SummaryHealthHandler.SummaryHealthPercent & PawnUIOverlay.DrawPawnGUIOverlay
            Assert(AccessTools.PropertyGetter(typeof(Verse.SummaryHealthHandler), nameof(Verse.SummaryHealthHandler.SummaryHealthPercent)) != null
                   && AccessTools.Method(typeof(HarmonyPatches_CombatAndHitbox), nameof(HarmonyPatches_CombatAndHitbox.SummaryHealthHandler_SummaryHealthPercent_Postfix)) != null,
                "SummaryHealthHandler.SummaryHealthPercent postfix must resolve cleanly");
            Assert(AccessTools.Method(typeof(Verse.PawnUIOverlay), nameof(Verse.PawnUIOverlay.DrawPawnGUIOverlay)) != null
                   && AccessTools.Method(typeof(HarmonyPatches_Rendering), nameof(HarmonyPatches_Rendering.PawnUIOverlay_DrawPawnGUIOverlay_Prefix)) != null,
                "PawnUIOverlay.DrawPawnGUIOverlay prefix must resolve cleanly");

            // 2. Boss HUD & SummaryHealthPercent reconciliation: early scratches stay high, near-lethal drops to low HP
            float fullHp = GiantBossHealthBarHUD.ReconcileBossHealthPercent(1f, 1f, 1f, preventPrematureLethalDeath: true, isDead: false);
            float earlyScratchHp = GiantBossHealthBarHUD.ReconcileBossHealthPercent(0.92f, 0.90f, 0.91f, preventPrematureLethalDeath: true, isDead: false);
            float nearLethalGuardedHp = GiantBossHealthBarHUD.ReconcileBossHealthPercent(0.88f, 0.85f, 0.02f, preventPrematureLethalDeath: true, isDead: false);
            float nearLethalUnguardedHp = GiantBossHealthBarHUD.ReconcileBossHealthPercent(0.88f, 0.85f, 0.04f, preventPrematureLethalDeath: false, isDead: false);
            float deadHp = GiantBossHealthBarHUD.ReconcileBossHealthPercent(0.50f, 0.50f, 0.50f, preventPrematureLethalDeath: false, isDead: true);

            AssertNear(fullHp, 1f, 1e-4f, "Full HP reconciled Boss HP must be 100%");
            Assert(earlyScratchHp >= 0.88f, $"Early limb scratches must stay >=88% rather than plunging to 5% (got {earlyScratchHp:F3})");
            Assert(nearLethalGuardedHp >= 0.20f && nearLethalGuardedHp <= 0.24f,
                $"Premature-death-guarded Boss HP must clamp smoothly near 20% floor (got {nearLethalGuardedHp:F3})");
            Assert(nearLethalUnguardedHp <= 0.05f && nearLethalUnguardedHp > 0f,
                $"Near-lethal unguarded Boss HP must descend to <=5% instead of reading 88% (got {nearLethalUnguardedHp:F3})");
            AssertNear(deadHp, 0f, 1e-5f, "Dead reconciled Boss HP must be 0%");

            // 3. Stage dwell protection default on CompProperties_GiantPhaseTransform
            var phaseProps = new CompProperties_GiantPhaseTransform();
            Assert(phaseProps.minStageDwellTicks >= 240, $"minStageDwellTicks default ({phaseProps.minStageDwellTicks}) must be >= 240 ticks (4s)");

            // 4. DevMode top toolbar safe Y margin (>= 42px base + margin)
            float nonDevTopY = GiantBossHealthBarHUD.ComputeSafeTopScreenYForMode(0f, 16f, devModeActive: false);
            float devTopY = GiantBossHealthBarHUD.ComputeSafeTopScreenYForMode(0f, 16f, devModeActive: true);
            Assert(devTopY >= 58f && devTopY > nonDevTopY + 20f,
                $"DevMode top Y ({devTopY:F1}) must clear DebugWindowsOpener toolbar (nonDev={nonDevTopY:F1})");

            // 5. Dead corpse darkening & severed-child stump darkening
            Color bioCorpse = PawnRenderNodeWorker_GiantBone.ComputeDeadCorpseTint(Color.white, isSolidOrMechanoid: false, hasSeveredChildBone: false);
            Color bioStump = PawnRenderNodeWorker_GiantBone.ComputeDeadCorpseTint(Color.white, isSolidOrMechanoid: false, hasSeveredChildBone: true);
            Assert(bioCorpse.r < 0.50f && bioCorpse.g < 0.45f && bioCorpse.a == 1f,
                $"Dead biological corpse tint ({bioCorpse}) must darken bright painted core well below 0.50");
            Assert(bioStump.r < bioCorpse.r && bioStump.g < bioCorpse.g && bioStump.a == 1f,
                $"Dead severed-child limb stump ({bioStump}) must darken further than intact corpse bone ({bioCorpse})");

            Console.WriteLine("       -> Verified SummaryHealthPercent/BossHUD sync, DevMode top-Y clearance, minStageDwellTicks>=240, DrawPawnGUIOverlay guard & corpse/stump darkening");
        }

        private static void TestRound3LosslessPerfSuite()
        {
            // 1. Verify DynamicDrawManager.DrawDynamicThings Harmony prefix target resolves cleanly in RimWorld 1.7
            Assert(AccessTools.Method(typeof(Verse.DynamicDrawManager), nameof(Verse.DynamicDrawManager.DrawDynamicThings)) != null
                   && AccessTools.Method(typeof(HarmonyPatches_Rendering), nameof(HarmonyPatches_Rendering.DynamicDrawManager_DrawDynamicThings_Prefix)) != null,
                "DynamicDrawManager.DrawDynamicThings prefix must resolve cleanly in RimWorld 1.7");

            // 2. Exhaustively verify TextureAlphaMask.ClassifyUVRect (8x8 tile 2D integral) vs brute-force IsOpaqueUV
            var (colRig, colMasks, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            Assert(colRig != null && colMasks != null && colMasks.Length > 0, "MechColossus rig & masks must load");

            int checkedBoxes = 0;
            int fastEmptyHits = 0;
            int fastOpaqueHits = 0;
            for (int m = 0; m < colMasks.Length; m++)
            {
                TextureAlphaMask mask = colMasks[m];
                if (mask == null || !mask.HasAnyOpaquePixels)
                {
                    continue;
                }
                for (int gy = 0; gy < 20; gy++)
                {
                    float v0 = gy * 0.05f;
                    float v1 = v0 + 0.038f;
                    for (int gx = 0; gx < 20; gx++)
                    {
                        float u0 = gx * 0.05f;
                        float u1 = u0 + 0.038f;
                        int cls = mask.ClassifyUVRect(u0, u1, v0, v1);
                        checkedBoxes++;

                        int bruteCount = 0;
                        for (int sz = 0; sz < 4; sz++)
                        {
                            float v = Mathf.Lerp(v0, v1, sz / 3f);
                            for (int sx = 0; sx < 4; sx++)
                            {
                                float u = Mathf.Lerp(u0, u1, sx / 3f);
                                if (mask.IsOpaqueUV(u, v))
                                {
                                    bruteCount++;
                                }
                            }
                        }

                        if (cls == 0)
                        {
                            fastEmptyHits++;
                            Assert(bruteCount == 0, $"ClassifyUVRect==0 must guarantee 0/16 opaque samples (got {bruteCount} on mask #{m} [{u0:F3},{u1:F3}]x[{v0:F3},{v1:F3}])");
                        }
                        else if (cls == 2)
                        {
                            fastOpaqueHits++;
                            Assert(bruteCount == 16, $"ClassifyUVRect==2 must guarantee 16/16 opaque samples (got {bruteCount} on mask #{m} [{u0:F3},{u1:F3}]x[{v0:F3},{v1:F3}])");
                        }
                    }
                }
            }
            Assert(fastEmptyHits > 200 && fastOpaqueHits > 20,
                $"8x8 integral classifier must accelerate both empty ({fastEmptyHits}) and interior opaque ({fastOpaqueHits}) regions across {checkedBoxes} UV boxes");

            // 3. Verify bit-for-bit identical Footprint.Rebuild hitCells, collisionCells, coverage & dominantBone across 12 rotations
            BoneNodeDef[] nodes = colRig.SortedNodes;
            var localPoses = new BoneLocalPose[nodes.Length];
            for (int i = 0; i < nodes.Length; i++) localPoses[i] = BoneLocalPose.Identity;
            var missing = new bool[nodes.Length];
            var worldPoses = new BoneWorldPose[nodes.Length];
            var fp = new GiantFootprintData();

            for (int a = 0; a < 12; a++)
            {
                float heading = a * 30f + 7.5f;
                SkeletalKinematics.SolveWorldPoses(colRig, new Vector2(125.3f, 125.7f), heading, localPoses, missing, worldPoses);
                fp.Rebuild(colRig, worldPoses, colMasks, new IntVec3(125, 0, 125), new IntVec3(250, 1, 250));
                Assert(fp.hitCells.Count > 20 && fp.collisionCells.Count > 10,
                    $"MechColossus footprint at {heading:F1} deg must produce valid hitCells ({fp.hitCells.Count}) & collisionCells ({fp.collisionCells.Count})");
                for (int c = 0; c < fp.collisionCells.Count; c++)
                {
                    Assert(fp.hitCellSet.Contains(fp.collisionCells[c]), "Every collision cell must remain inside hitCellSet");
                }
            }

            // 4. Verify persistentAuraBoneIndices precomputation matches node defs 1:1
            int expectedAuras = 0;
            for (int i = 0; i < nodes.Length; i++)
            {
                if (nodes[i].persistentVfxPreset != GiantBoneAuraVfxKind.None)
                {
                    expectedAuras++;
                }
            }
            Assert((colRig.persistentAuraBoneIndices?.Length ?? 0) == expectedAuras,
                $"persistentAuraBoneIndices length ({colRig.persistentAuraBoneIndices?.Length ?? 0}) must match node definitions ({expectedAuras})");

            Console.WriteLine($"       -> Verified 8x8 tile integral exactness ({fastEmptyHits} empty + {fastOpaqueHits} opaque / {checkedBoxes} boxes), 12-angle footprint invariants & DrawDynamicThings hook");
        }

        private static void TestUniversalPhysicalLayerOrderingAndAltitudeStratification()
        {
            // 1. Validate all 8 official GiantRigDefs against universal physical layer invariants
            (string rigFile, string animFile, string rigDefName)[] rigSpecs =
            {
                ("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2"),
                ("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3"),
                ("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier"),
                ("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV"),
                ("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos"),
                ("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax"),
            };

            foreach (var spec in rigSpecs)
            {
                var (rig, _, _) = LoadRigFromXml(spec.rigFile, spec.animFile, spec.rigDefName);
                List<string> layerErrs = rig.ValidatePhysicalLayerOrdering(0.5f).ToList();
                Assert(layerErrs.Count == 0,
                    $"Rig '{spec.rigDefName}' violated universal physical layer rules: {string.Join(" | ", layerErrs)}");
                List<string> cfgErrs = rig.ConfigErrors().ToList();
                Assert(cfgErrs.Count == 0,
                    $"Rig '{spec.rigDefName}' ConfigErrors: {string.Join(" | ", cfgErrs)}");
            }

            // 2. Verify MechColossus Stage 3 dorsal turret & barrel elevation + exact left/right symmetry across all hull decks
            var (mc3, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            float Layer3(string id)
            {
                Assert(mc3.TryGetNodeIndex(id, out int idx), $"Missing Stage3 node '{id}'");
                return mc3.SortedNodes[idx].layerOffset;
            }
            float maxHull = MathF.Max(Layer3("core_hull"), Layer3("core_shutter_left"));
            Assert(Layer3("turret_neck") >= maxHull + 0.5f && Layer3("command_head") >= Layer3("turret_neck") + 0.5f,
                "Stage3 deployed fire-control director must sit strictly above core_hull and core_shutter");
            Assert(Layer3("plasma_rail_left") == Layer3("plasma_rail_right") && Layer3("plasma_rail_left") >= maxHull + 0.5f,
                "Stage3 bilateral plasma rails must be symmetric and strictly above core_shutter");
            Assert(Layer3("wing_pod_left") == Layer3("wing_pod_right") && Layer3("wing_pod_left") >= maxHull + 0.5f,
                "Stage3 wing pods must be symmetric and strictly above all hull/wing decks");
            Assert(Layer3("aft_wing_pod_left") == Layer3("aft_wing_pod_right") && Layer3("aft_wing_pod_left") >= maxHull + 0.5f,
                "Stage3 aft wing pods must be symmetric and strictly above all hull/wing decks");
            Assert(Layer3("railgun_mount_left") == Layer3("railgun_mount_right")
                   && Layer3("railgun_barrel_left") == Layer3("railgun_barrel_right")
                   && Layer3("railgun_barrel_left") >= Layer3("railgun_mount_left") + 0.5f
                   && Layer3("railgun_barrel_left") > Layer3("citadel_bridge"),
                "Stage3 twin orbital railguns must be symmetric, barrel > mount, and strictly above central citadel_bridge across 360-deg traverse");
            Assert(Layer3("railgun_outer_mount_left") == Layer3("railgun_outer_mount_right")
                   && Layer3("railgun_outer_barrel_left") == Layer3("railgun_outer_barrel_right")
                   && Layer3("railgun_outer_barrel_left") >= Layer3("railgun_outer_mount_left") + 0.5f
                   && Layer3("railgun_outer_barrel_left") > Layer3("citadel_bridge"),
                "Stage3 outer wing coilguns must be symmetric, barrel > mount, and strictly above central citadel_bridge across 360-deg traverse");

            // 3. Negative mutation verification: confirm validator catches asymmetry, sunken dorsal turret, high silhouette, and inverted leg
            mc3.TryGetNodeIndex("railgun_barrel_right", out int rbrIdx);
            float savedRbr = mc3.SortedNodes[rbrIdx].layerOffset;
            mc3.SortedNodes[rbrIdx].layerOffset = savedRbr + 0.3f;
            Assert(mc3.ValidatePhysicalLayerOrdering(0.5f).Any(e => e.Contains("bilateral Dorsal layerOffset asymmetry")),
                "Validator must catch left/right layerOffset asymmetry");
            mc3.SortedNodes[rbrIdx].layerOffset = savedRbr;

            mc3.TryGetNodeIndex("wing_pod_left", out int wplIdx);
            mc3.TryGetNodeIndex("wing_pod_right", out int wprIdx);
            float savedWpl = mc3.SortedNodes[wplIdx].layerOffset;
            mc3.SortedNodes[wplIdx].layerOffset = -5.6f;
            mc3.SortedNodes[wprIdx].layerOffset = -5.6f;
            Assert(mc3.ValidatePhysicalLayerOrdering(0.5f).Any(e => e.Contains("active dorsal turret")),
                "Validator must reject dorsal turret sunken below hull plates");
            mc3.SortedNodes[wplIdx].layerOffset = savedWpl;
            mc3.SortedNodes[wprIdx].layerOffset = savedWpl;

            mc3.TryGetNodeIndex("core_hull", out int chIdx);
            float savedSil = mc3.SortedNodes[chIdx].silhouetteLayerOffset;
            mc3.SortedNodes[chIdx].silhouetteLayerOffset = -4.0f;
            Assert(mc3.ValidatePhysicalLayerOrdering(0.5f).Any(e => e.Contains("global floor")),
                "Validator must reject silhouette underlay sitting above lower girders");
            mc3.SortedNodes[chIdx].silhouetteLayerOffset = savedSil;

            var (scRig, _, _) = LoadMechScorpionFromXml();
            scRig.TryGetNodeIndex("leg_l1", out int l1Idx);
            scRig.TryGetNodeIndex("leg_r1", out int r1Idx);
            float savedLeg = scRig.SortedNodes[l1Idx].layerOffset;
            scRig.SortedNodes[l1Idx].layerOffset = 1.5f;
            scRig.SortedNodes[r1Idx].layerOffset = 1.5f;
            Assert(scRig.ValidatePhysicalLayerOrdering(0.5f).Any(e => e.Contains("walking limb bone")),
                "Validator must reject walking leg placed above torso carapace");
            scRig.SortedNodes[l1Idx].layerOffset = savedLeg;
            scRig.SortedNodes[r1Idx].layerOffset = savedLeg;

            // 3b. Positive verification: ventral / chin / belly turrets (both narrow-arc and 360-deg) mounted below parent hull pass cleanly
            var ventralTestRig = new GiantRigDef
            {
                defName = "GCF_Test_VentralGunshipRig",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "fuselage", layerOffset = 0.0f, drawSize = new Vector2(7f, 7f), pivotPixel = new Vector2(256f, 256f) },
                    new BoneNodeDef { nodeId = "nose_cannon", parentId = "fuselage", layerOffset = -0.6f, isTurret = true, maxTurretAimAngleDeg = 110f, drawSize = new Vector2(2.4f, 2.4f), pivotPixel = new Vector2(256f, 330f), parentSocketPixel = new Vector2(256f, 100f) },
                    new BoneNodeDef { nodeId = "belly_ball_turret", parentId = "fuselage", layerOffset = -0.8f, isTurret = true, maxTurretAimAngleDeg = 180f, drawSize = new Vector2(2.0f, 2.0f), pivotPixel = new Vector2(256f, 256f), parentSocketPixel = new Vector2(256f, 280f) },
                    new BoneNodeDef { nodeId = "wing_left", parentId = "fuselage", layerOffset = -1.2f, isRigid = true, drawSize = new Vector2(4.2f, 4.2f), pivotPixel = new Vector2(256f, 256f), parentSocketPixel = new Vector2(180f, 230f) },
                    new BoneNodeDef { nodeId = "wing_right", parentId = "fuselage", layerOffset = -1.2f, isRigid = true, drawSize = new Vector2(4.2f, 4.2f), pivotPixel = new Vector2(256f, 256f), parentSocketPixel = new Vector2(332f, 230f) },
                    new BoneNodeDef { nodeId = "rotor_left", parentId = "wing_left", layerOffset = 1.2f, continuousSpinDegPerTick = 24f, drawSize = new Vector2(3.0f, 3.0f), pivotPixel = new Vector2(256f, 256f), parentSocketPixel = new Vector2(120f, 256f) },
                    new BoneNodeDef { nodeId = "rotor_right", parentId = "wing_right", layerOffset = 1.2f, continuousSpinDegPerTick = -24f, drawSize = new Vector2(3.0f, 3.0f), pivotPixel = new Vector2(256f, 256f), parentSocketPixel = new Vector2(392f, 256f) },
                }
            };
            ventralTestRig.BuildTopology();
            List<string> ventralErrs = ventralTestRig.ValidatePhysicalLayerOrdering(0.5f).ToList();
            Assert(ventralErrs.Count == 0,
                $"Ventral chin & belly turrets must pass ValidatePhysicalLayerOrdering cleanly, got: {string.Join(" | ", ventralErrs)}");

            // 4. Verify 5-band global world-Y stratification:
            // DeadCorpse < DownedGround < NormalPawns < StandingGroundAlive < MoteOverhead < FogOfWar < LowSkim < Darkness < HighAirborne < AirborneVfx < WorldClipper
            float pawnAlt = Altitudes.AltitudeFor(AltitudeLayer.Pawn);
            float shadowsAlt = Altitudes.AltitudeFor(AltitudeLayer.Shadows);
            float moteOverheadLowAlt = Altitudes.AltitudeFor(AltitudeLayer.MoteOverheadLow);
            float moteOverheadAlt = Altitudes.AltitudeFor(AltitudeLayer.MoteOverhead);
            float fogOfWarAlt = Altitudes.AltitudeFor(AltitudeLayer.FogOfWar);
            float darknessAlt = Altitudes.AltitudeFor(AltitudeLayer.Darkness);
            float worldClipperAlt = Altitudes.AltitudeFor(AltitudeLayer.WorldClipper);

            var lowSkimDef = new GiantFlightDef { flightMode = GiantFlightMode.AlwaysAirborne, altitudeTier = FlightAltitudeTier.LowSkim };
            var highAirDef = new GiantFlightDef { flightMode = GiantFlightMode.AlwaysAirborne, altitudeTier = FlightAltitudeTier.HighAirborne };
            var lowSkimRt = new GiantFlightRuntime(mc3, lowSkimDef);
            var highAirRt = new GiantFlightRuntime(mc3, highAirDef);
            lowSkimRt.ResetForSpawn(1);
            highAirRt.ResetForSpawn(2);
            float lowSkimBoost = CompGiantRig.ComputeAirborneRenderAltitudeBoost(false, lowSkimRt, 1);
            float highAirBoost = CompGiantRig.ComputeAirborneRenderAltitudeBoost(false, highAirRt, 2);

            // Worst-case southern corpse (Z=5, highest possible bone +18, stale airborne boost=highAirBoost) vs northern downed giant (Z=245, lowest silhouette -14)
            float corpseMaxY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: true, isDowned: false, rootColY: pawnAlt, worldZ: 5f, thingIdNumber: 15,
                isFlyingVisual: true, flightAltitudeBoost: highAirBoost, partLayerOffset: 18f);
            float corpseMinY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: true, isDowned: false, rootColY: pawnAlt, worldZ: 245f, thingIdNumber: 0,
                isFlyingVisual: true, flightAltitudeBoost: highAirBoost, partLayerOffset: -14f);
            float downedMinY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: true, rootColY: pawnAlt, worldZ: 245f, thingIdNumber: 0,
                isFlyingVisual: true, flightAltitudeBoost: highAirBoost, partLayerOffset: -14f);
            float downedMaxY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: true, rootColY: pawnAlt, worldZ: 5f, thingIdNumber: 15,
                isFlyingVisual: false, flightAltitudeBoost: 0f, partLayerOffset: 18f);
            float groundMinY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: false, rootColY: pawnAlt, worldZ: 245f, thingIdNumber: 0,
                isFlyingVisual: false, flightAltitudeBoost: 0f, partLayerOffset: -14f);
            float groundMaxY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: false, rootColY: pawnAlt, worldZ: 5f, thingIdNumber: 15,
                isFlyingVisual: false, flightAltitudeBoost: 0f, partLayerOffset: 18f);
            float lowSkimMinY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: false, rootColY: pawnAlt, worldZ: 245f, thingIdNumber: 0,
                isFlyingVisual: true, flightAltitudeBoost: lowSkimBoost, partLayerOffset: -14f);
            float lowSkimMaxY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: false, rootColY: pawnAlt, worldZ: 5f, thingIdNumber: 15,
                isFlyingVisual: true, flightAltitudeBoost: lowSkimBoost, partLayerOffset: 18f);
            float highAirMinY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: false, rootColY: pawnAlt, worldZ: 245f, thingIdNumber: 0,
                isFlyingVisual: true, flightAltitudeBoost: highAirBoost, partLayerOffset: -14f);
            float highAirMaxY = CompGiantRig.ComputeGiantPartWorldAltitude(
                isPortrait: false, isDead: false, isDowned: false, rootColY: pawnAlt, worldZ: 5f, thingIdNumber: 15,
                isFlyingVisual: true, flightAltitudeBoost: highAirBoost, partLayerOffset: 18f);

            Assert(corpseMinY > shadowsAlt + 0.02f, $"Corpse min Y ({corpseMinY:F4}) must stay above ground shadows ({shadowsAlt:F4})");
            Assert(corpseMaxY < downedMinY, $"Corpse max Y ({corpseMaxY:F4}) must sit strictly below Downed min Y ({downedMinY:F4})");
            Assert(downedMaxY < pawnAlt, $"Downed max Y ({downedMaxY:F4}) must sit strictly below standing normal pawns ({pawnAlt:F4})");
            Assert(groundMinY > pawnAlt + 0.50f && groundMinY > moteOverheadLowAlt,
                $"Standing Ground Alive min Y ({groundMinY:F4}) must sit strictly above normal pawns/weapons/PawnState/Blueprint/MoteOverheadLow ({moteOverheadLowAlt:F4})");
            Assert(groundMaxY < moteOverheadAlt,
                $"Standing Ground Alive max Y ({groundMaxY:F4}) must sit strictly below MoteOverhead ({moteOverheadAlt:F4}) so combat hit slashes/VFX stay visible");
            Assert(lowSkimMinY > fogOfWarAlt,
                $"LowSkim Airborne min Y ({lowSkimMinY:F4}) must sit strictly above FogOfWar ({fogOfWarAlt:F4})");
            Assert(lowSkimMaxY < highAirMinY, $"LowSkim max Y ({lowSkimMaxY:F4}) must sit strictly below HighAirborne min Y ({highAirMinY:F4})");
            Assert(highAirMinY > darknessAlt && highAirMinY > fogOfWarAlt,
                $"HighAirborne min Y ({highAirMinY:F4}) must sit strictly above FogOfWar ({fogOfWarAlt:F4}) and Darkness ({darknessAlt:F4})");
            Assert(highAirMaxY < CompGiantRig.AirborneVfxBaseAltitudeY && CompGiantRig.AirborneVfxBaseAltitudeY < worldClipperAlt,
                $"HighAirborne max Y ({highAirMaxY:F4}) < AirborneVfx ({CompGiantRig.AirborneVfxBaseAltitudeY:F4}) < WorldClipper ({worldClipperAlt:F4})");

            Console.WriteLine($"       -> Verified 0 layer violations across all 8 rigs & 5-band world-Y stratification: Corpse[{corpseMinY:F3}..{corpseMaxY:F3}] < Downed[{downedMinY:F3}..{downedMaxY:F3}] < NormalPawn({pawnAlt:F3}) < GroundAlive[{groundMinY:F3}..{groundMaxY:F3}] < MoteOverhead({moteOverheadAlt:F3}) < FogOfWar({fogOfWarAlt:F3}) < LowSkim[{lowSkimMinY:F3}..{lowSkimMaxY:F3}] < HighAir[{highAirMinY:F3}..{highAirMaxY:F3}] < WorldClipper({worldClipperAlt:F3})");
        }

        private static void TestDragonHeadNaturalMotionStabilizationCascadeAndRecoils()
        {
            var (rathRig, _, rathAnims) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");

            Assert(rathRig.TryGetNodeIndex("thorax_core", out int rThoraxIdx), "Missing thorax_core");
            Assert(rathRig.TryGetNodeIndex("neck_base", out int rNeckBaseIdx), "Missing neck_base");
            Assert(rathRig.TryGetNodeIndex("neck_mid", out _), "Missing neck_mid");
            Assert(rathRig.TryGetNodeIndex("neck_upper", out _), "Missing neck_upper");
            Assert(rathRig.TryGetNodeIndex("skull", out int rSkullIdx), "Missing skull");

            var rSteer = new GiantSteeringRuntime(rathRig);
            rSteer.Reset(0f);
            int rn = rathRig.SortedNodes.Length;
            var rLocal = new BoneLocalPose[rn];
            var rWorld = new BoneWorldPose[rn];
            var rMiss = new bool[rn];
            GiantAnimDef rRun = rathAnims["GCF_Anim_Rathalos_Run"];
            float rMinTh = float.MaxValue, rMaxTh = float.MinValue;
            float rMinSk = float.MaxValue, rMaxSk = float.MinValue;
            for (int t = 0; t < 108; t++)
            {
                for (int i = 0; i < rn; i++) rLocal[i] = BoneLocalPose.Identity;
                rRun.EvaluateInto(rathRig, t % rRun.durationTicks, rLocal);
                var runCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 0f,
                    IsMoving = true,
                    MovedDistanceCells = 0.12f,
                    AnimState = GiantAnimState.Run,
                    ContinuousTicks = t,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = true,
                    IsRushing = true
                };
                rSteer.ApplyBoneSteering(rathRig, 0f, rLocal, rMiss, 1f, in runCtx);
                SkeletalKinematics.SolveWorldPoses(rathRig, new Vector2(50f, 50f), 0f, rLocal, rMiss, rWorld);
                if (t >= 36)
                {
                    float thYaw = Mathf.DeltaAngle(0f, rWorld[rThoraxIdx].worldAngleDeg);
                    float skYaw = Mathf.DeltaAngle(0f, rWorld[rSkullIdx].worldAngleDeg);
                    rMinTh = Mathf.Min(rMinTh, thYaw); rMaxTh = Mathf.Max(rMaxTh, thYaw);
                    rMinSk = Mathf.Min(rMinSk, skYaw); rMaxSk = Mathf.Max(rMaxSk, skYaw);
                }
            }
            float rThoraxSpan = rMaxTh - rMinTh;
            float rSkullSpan = rMaxSk - rMinSk;
            Assert(rThoraxSpan > 2.2f && rSkullSpan < rThoraxSpan * 0.35f,
                $"Rathalos Run vestibulo-collic stabilization must suppress >65% of thorax roll (thoraxSpan={rThoraxSpan:F2}, skullSpan={rSkullSpan:F2})");

            rSteer.Reset(0f);
            float prevLead = 0f, rSkullTick6 = 0f, rBaseTick6 = 0f;
            for (int t = 1; t <= 45; t++)
            {
                for (int i = 0; i < rn; i++) rLocal[i] = BoneLocalPose.Identity;
                var snapCtx = new GiantSteeringContext
                {
                    DesiredBodyHeadingDeg = 0f,
                    DesiredLookHeadingDeg = 45f,
                    HasExplicitLookTarget = true,
                    IsCombatTarget = true,
                    AnimState = GiantAnimState.Idle,
                    ContinuousTicks = t,
                    SteeringEnabled = true,
                    IntensityScale = 1.0f,
                    EnableNeckIdleAndGaitArticulation = true
                };
                rSteer.ApplyBoneSteering(rathRig, 0f, rLocal, rMiss, 1f, in snapCtx);
                float curLead = rSteer.PrimaryLookLeadDeg;
                Assert(curLead >= prevLead - 1e-3f && curLead <= 45.02f, "Rathalos 45-deg neck cascade must be monotonic");
                prevLead = curLead;
                if (t == 6) { rSkullTick6 = rLocal[rSkullIdx].angle; rBaseTick6 = rLocal[rNeckBaseIdx].angle; }
            }
            Assert(rSkullTick6 > rBaseTick6 * 2.2f, "Rathalos skull must snap onto target first before neck_base catches up");

            GiantAnimDef rFierce = rathAnims["GCF_Anim_Rathalos_FierceBite"];
            float fierceSkullArch = rFierce.tracks.First(tr => tr.nodeId == "skull").SampleAt(5.5f, rFierce.durationTicks, false).sagittalPitch;
            float fierceBaseCoil = rFierce.tracks.First(tr => tr.nodeId == "neck_base").SampleAt(8f, rFierce.durationTicks, false).sagittalPitch;
            float fierceHit13 = rFierce.tracks.First(tr => tr.nodeId == "skull").SampleAt(13f, rFierce.durationTicks, false).sagittalPitch;
            Assert(fierceSkullArch > 5f && fierceBaseCoil <= -28f && fierceHit13 >= 30f, "FierceBite 4-phase S-arch/coil/snap check failed");

            GiantAnimDef rFireball = rathAnims["GCF_Anim_Rathalos_FireballBreath"];
            float fbSkull16 = rFireball.tracks.First(tr => tr.nodeId == "skull").SampleAt(16f, rFireball.durationTicks, false).sagittalPitch;
            float fbSkullRecoil = rFireball.tracks.First(tr => tr.nodeId == "skull").SampleAt(18.5f, rFireball.durationTicks, false).sagittalPitch;
            Assert(fbSkull16 - fbSkullRecoil >= 18f, "FireballBreath post-ejection muzzle blast recoil check failed");
        }

        private static void TestWorldAerialOverflightAntiGameOverAndColonyVehicleGuards()
        {
            // 1. Spherical great-circle aerial route across "impassable" mountain/ocean longitudes on a 2D lat/lon sphere mesh
            const int latSteps = 12;
            const int lonSteps = 24;
            int ToId(int lat, int lon) => lat * lonSteps + ((lon % lonSteps + lonSteps) % lonSteps);
            Vector3 GetSphereCenter(int id)
            {
                int lat = id / lonSteps;
                int lon = id % lonSteps;
                float phi = Mathf.Lerp(-70f, 70f, lat / (float)(latSteps - 1)) * Mathf.Deg2Rad;
                float theta = (lon / (float)lonSteps) * Mathf.PI * 2f;
                return new Vector3(Mathf.Cos(phi) * Mathf.Cos(theta), Mathf.Sin(phi), Mathf.Cos(phi) * Mathf.Sin(theta)) * 100f;
            }
            void GetSphereNeighbors(int id, List<int> nb)
            {
                int lat = id / lonSteps;
                int lon = id % lonSteps;
                nb.Add(ToId(lat, lon - 1));
                nb.Add(ToId(lat, lon + 1));
                if (lat > 0) nb.Add(ToId(lat - 1, lon));
                if (lat < latSteps - 1) nb.Add(ToId(lat + 1, lon));
            }

            int startTile = ToId(6, 2);
            int destTile = ToId(6, 11);
            bool builtAerial = WorldObject_Giant.TryBuildSphericalAerialRoute(
                startTile,
                destTile,
                maxSteps: 256,
                GetSphereCenter,
                GetSphereNeighbors,
                out List<int> aerialRoute);
            Assert(builtAerial && aerialRoute != null && aerialRoute.Count == 9 && aerialRoute[aerialRoute.Count - 1] == destTile,
                $"Spherical great-circle route must step cleanly across 9 tiles to destination, got count={aerialRoute?.Count ?? -1}");
            int prev = startTile;
            var checkNb = new List<int>(6);
            foreach (int hop in aerialRoute)
            {
                checkNb.Clear();
                GetSphereNeighbors(prev, checkNb);
                Assert(checkNb.Contains(hop), $"Aerial hop {prev} -> {hop} must be topological neighbors");
                prev = hop;
            }

            // 1b. Direct geodesic shortest straight-line movement (no tile-by-tile hopping) & direct current-tile world departure
            {
                const float R = 100f;
                Vector3 eqStart = new Vector3(R, 0f, 0f);
                Vector3 eqEnd = new Vector3(0f, 0f, R);
                float qArc = WorldObject_Giant.ComputeGeodesicArcLength(eqStart, eqEnd, R);
                AssertNear(qArc, Mathf.PI * 0.5f * R, 1e-3f, "Quarter-circle geodesic arc length must equal (pi/2)*R");
                Vector3 planeN = Vector3.Cross(eqStart, eqEnd).normalized;
                for (int k = 0; k <= 20; k++)
                {
                    float t = k / 20f;
                    Vector3 p = WorldObject_Giant.EvaluateGeodesicPoint(eqStart, eqEnd, t, R);
                    AssertNear(p.magnitude, R, 1e-4f, "Geodesic point must stay strictly on sphere surface");
                    AssertNear(Vector3.Dot(p, planeN), 0f, 1e-4f, "Geodesic path must remain strictly in shortest great-circle plane");
                }
                // Antipodal (180-deg) safety: zero NaN, exact sphere radius
                Vector3 antiMid = WorldObject_Giant.EvaluateGeodesicPoint(eqStart, -eqStart, 0.5f, R);
                Assert(!float.IsNaN(antiMid.x) && !float.IsNaN(antiMid.y) && !float.IsNaN(antiMid.z),
                    "Antipodal geodesic evaluation must never produce NaN");
                AssertNear(antiMid.magnitude, R, 1e-4f, "Antipodal midpoint must lie on sphere surface");

                // Heading due north along meridian (equator -> north pole) must be ~0 deg
                Vector3 eqPoint = new Vector3(R, 0f, 0f);
                Vector3 northPole = new Vector3(0f, R, 0f);
                float hdgNorth = WorldObject_Giant.ComputeGeodesicHeadingDeg(eqPoint, northPole);
                AssertNear(hdgNorth, 0f, 1e-3f, "Geodesic heading toward North Pole must be 0 deg");

                // DepartureCommand / ExecuteImmediateDeparture must NOT open WorldTargeter to pick a destination;
                // it must spawn directly above the current map tile via TryLeaveMap
                MethodInfo depMethod = typeof(GiantWorldUtility).GetMethod(nameof(GiantWorldUtility.ExecuteImmediateDeparture), BindingFlags.Static | BindingFlags.Public);
                Assert(depMethod != null, "ExecuteImmediateDeparture must exist");
                var depCalls = HarmonyLib.PatchProcessor.GetOriginalInstructions(depMethod!)
                    .Where(ci => ci.operand is MethodBase)
                    .Select(ci => ((MethodBase)ci.operand).Name)
                    .ToList();
                Assert(!depCalls.Contains("BeginTargeting"),
                    "ExecuteImmediateDeparture must NOT invoke WorldTargeter.BeginTargeting (must spawn directly above current map tile)");
                Assert(depCalls.Contains(nameof(GiantWorldUtility.TryLeaveMap)),
                    "ExecuteImmediateDeparture must directly invoke TryLeaveMap onto the current map tile");
                MethodInfo depCmdMethod = typeof(GiantWorldUtility).GetMethod(nameof(GiantWorldUtility.DepartureCommand), BindingFlags.Static | BindingFlags.Public);
                var depCmdCalls = HarmonyLib.PatchProcessor.GetOriginalInstructions(depCmdMethod!)
                    .Where(ci => ci.operand is MethodBase)
                    .Select(ci => ((MethodBase)ci.operand).Name)
                    .ToList();
                Assert(!depCmdCalls.Contains("BeginTargeting"),
                    "DepartureCommand must NOT invoke WorldTargeter.BeginTargeting");

                // OrderMove must NOT invoke WorldPather.FindPath or tile-by-tile route building
                MethodInfo orderMoveMethod = typeof(WorldObject_Giant).GetMethod(nameof(WorldObject_Giant.OrderMove), BindingFlags.Instance | BindingFlags.Public);
                var orderMoveCalls = HarmonyLib.PatchProcessor.GetOriginalInstructions(orderMoveMethod!)
                    .Where(ci => ci.operand is MethodBase)
                    .Select(ci => ((MethodBase)ci.operand).Name)
                    .ToList();
                Assert(!orderMoveCalls.Contains("TryBuildRoute") && !orderMoveCalls.Contains("FindPath"),
                    "OrderMove must move via direct shortest geodesic line, never tile-by-tile pathfinding");

                // 1c. Vanilla Caravan parity: no fabricated Camp on empty tiles, non-player Settlement is attack-only,
                // and non-colony departure guards against hostile/last-unit site removal
                string worldGiantSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "World", "WorldObject_Giant.cs"));
                Assert(!worldGiantSrc.Contains("WorldObjectDefOf.Camp", StringComparison.Ordinal),
                    "WorldObject_Giant must NOT fabricate WorldObjectDefOf.Camp on empty tiles (vanilla Caravan parity)");
                Assert(WorldObject_Giant.ResolveArrivalActionForMapParent(null) == WorldGiantArrivalAction.None,
                    "Null MapParent must resolve to WorldGiantArrivalAction.None");
                Assert(!WorldObject_Giant.CanEnterWorldTile(RimWorld.Planet.PlanetTile.Invalid),
                    "Invalid tile must NOT be enterable");

                MethodInfo attackNowMethod = typeof(WorldObject_Giant).GetMethod("AttackSettlementNow", BindingFlags.Instance | BindingFlags.NonPublic);
                Assert(attackNowMethod != null, "WorldObject_Giant.AttackSettlementNow must exist for vanilla Settlement attack path");
                var attackCalls = HarmonyLib.PatchProcessor.GetOriginalInstructions(attackNowMethod!)
                    .Where(ci => ci.operand is MethodBase)
                    .Select(ci => ((MethodBase)ci.operand).Name)
                    .ToList();
                Assert(attackCalls.Contains(nameof(RimWorld.Planet.SettlementUtility.AffectRelationsOnAttacked)),
                    "AttackSettlementNow must invoke vanilla SettlementUtility.AffectRelationsOnAttacked");
                Assert(attackCalls.Contains(nameof(GetOrGenerateMapUtility.GetOrGenerateMap)),
                    "AttackSettlementNow must invoke GetOrGenerateMapUtility.GetOrGenerateMap");
                Assert(attackCalls.Contains(nameof(GiantWorldUtility.TryEnterMap)),
                    "AttackSettlementNow must enter the map via GiantWorldUtility.TryEnterMap");
                Assert(attackCalls.IndexOf(nameof(RimWorld.Planet.SettlementUtility.AffectRelationsOnAttacked))
                    < attackCalls.IndexOf(nameof(GiantWorldUtility.TryEnterMap)),
                    "AttackSettlementNow must call AffectRelationsOnAttacked BEFORE spawning giant (matching vanilla SettlementUtility.AttackNow)");

                Assert(depCmdCalls.Contains("AnyHostileActiveThreatToPlayer"),
                    "DepartureCommand must disable instant departure on non-colony maps with active hostile threats (vanilla FormCaravanComp parity)");
                Assert(typeof(GiantWorldUtility).GetMethod(nameof(GiantWorldUtility.WouldLeavingTriggerMapOrWorldObjectRemoval), BindingFlags.Static | BindingFlags.Public) != null,
                    "GiantWorldUtility.WouldLeavingTriggerMapOrWorldObjectRemoval must exist to warn before closing/removing non-colony maps");

                string worldUtilSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "World", "GiantWorldUtility.cs"));
                Assert(worldUtilSrc.Contains("CommandReformCaravanFailHostilePawns", StringComparison.Ordinal),
                    "DepartureCommand must reuse vanilla CommandReformCaravanFailHostilePawns message on hostile non-colony maps");
                Assert(worldUtilSrc.Contains("\"AttackSettlement\".Translate", StringComparison.Ordinal),
                    "World right-click menu must use vanilla AttackSettlement option for non-player settlements");
                Assert(!worldUtilSrc.Contains("|| allowedToJoinOrCreateCaravan", StringComparison.Ordinal),
                    "ExitMap_Prefix must NOT skip allowedToJoinOrCreateCaravan so giants exiting via map edge become WorldObject_Giant");

                MethodInfo gotoPostfix = typeof(HarmonyPatches_PlayerControl).GetMethod("PawnGotoAction_Postfix", BindingFlags.Static | BindingFlags.Public);
                Assert(gotoPostfix != null, "PawnGotoAction_Postfix must exist so drafted mech/vehicle giants can exit via ExitMapGrid");
            }

            // 2. CanFlyOnWorld checks ActiveFlightLocomotion & intact lift parts
            var (carrierRigDef, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            var (panzerRigDef, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            var (rathRigDef, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            Assert(carrierRigDef.ActiveFlightLocomotion != null && rathRigDef.ActiveFlightLocomotion != null && panzerRigDef.ActiveFlightLocomotion == null,
                "Expected flightLocomotion on Carrier & Rathalos and null on ground PanzerIV");

            var carrierPawn = new Pawn { thingIDNumber = 998101, def = new ThingDef { defName = "GCF_ProtossCarrier", shortHash = 61101, race = new RaceProperties() } };
            carrierPawn.health = new Pawn_HealthTracker(carrierPawn);
            var carrierComp = new CompGiantRig { parent = carrierPawn };
            carrierComp.Initialize(new CompProperties_GiantRig { rigDef = carrierRigDef });
            Assert(WorldObject_Giant.CanFlyOnWorld(carrierPawn), "ProtossCarrier with ActiveFlightLocomotion must satisfy CanFlyOnWorld");

            var panzerPawn = new Pawn { thingIDNumber = 998102, def = new ThingDef { defName = "GCF_PanzerIV", shortHash = 61102, race = new RaceProperties() } };
            panzerPawn.health = new Pawn_HealthTracker(panzerPawn);
            var panzerComp = new CompGiantRig { parent = panzerPawn };
            panzerComp.Initialize(new CompProperties_GiantRig { rigDef = panzerRigDef });
            Assert(!WorldObject_Giant.CanFlyOnWorld(panzerPawn), "Ground PanzerIV must NOT satisfy CanFlyOnWorld");

            // 3. WorldObject_Giant Anti-GameOver & Man-in-Black boarded colonist detection
            var playerFac = new RimWorld.Faction { def = new RimWorld.FactionDef { defName = "PlayerColony", isPlayer = true } };
            var hostileFac = new RimWorld.Faction { def = new RimWorld.FactionDef { defName = "Mechanoid", isPlayer = false } };

            var cockpitProps = new CompProperties_GiantCockpit
            {
                autonomousWhenEmpty = false,
                allowPlayerControlWithoutOverseer = true,
                seats = new List<GiantCockpitSeatDef>
                {
                    new GiantCockpitSeatDef { seatId = "Driver", role = GiantCockpitRole.PrimaryPilot, linkedBodyPart = new BodyPartDef { defName = "GCF_PanzerHull" } }
                }
            };
            var panzerCockpit = new CompGiantCockpit { parent = panzerPawn };
            panzerCockpit.Initialize(cockpitProps);

            var worldGiant = new WorldObject_Giant();
            typeof(RimWorld.Planet.WorldObject).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(worldGiant, playerFac);
            var wgInner = (List<Thing>)worldGiant.GetDirectlyHeldThings().GetType()
                .GetField("innerList", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(worldGiant.GetDirectlyHeldThings())!;
            wgInner.Add(panzerPawn);
            Assert(worldGiant.Pawn == panzerPawn, "WorldObject_Giant.Pawn must resolve held PanzerIV");

            var worldObjects = new List<RimWorld.Planet.WorldObject> { worldGiant };
            Assert(!HarmonyPatches_VehicleAndTurrets.HasAnyWorldGiantBoardedFreeColonist(worldObjects, playerFac, requireHealthyUndowned: false),
                "Empty WorldObject_Giant must NOT suppress GameOver");

            var colonist = new Pawn
            {
                thingIDNumber = 998103,
                def = new ThingDef { defName = "Human", race = new RaceProperties { intelligence = Intelligence.Humanlike } },
                guest = null
            };
            colonist.health = new Pawn_HealthTracker(colonist);
            typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(colonist, playerFac);
            var cpInner = (List<Thing>)panzerCockpit.GetDirectlyHeldThings().GetType()
                .GetField("innerList", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(panzerCockpit.GetDirectlyHeldThings())!;
            cpInner.Add(colonist);
            Assert(colonist.IsFreeColonist && panzerCockpit.HasAnyBoardedFreeColonist(), "Boarded human in player faction must be recognized as free colonist");
            Assert(HarmonyPatches_VehicleAndTurrets.HasAnyWorldGiantBoardedFreeColonist(worldObjects, playerFac, requireHealthyUndowned: false),
                "Player WorldObject_Giant carrying boarded free colonist must suppress GameOver");
            Assert(HarmonyPatches_VehicleAndTurrets.HasAnyWorldGiantBoardedFreeColonist(worldObjects, playerFac, requireHealthyUndowned: true),
                "Player WorldObject_Giant carrying healthy free colonist must suppress Man in Black");
            Assert(!HarmonyPatches_VehicleAndTurrets.HasAnyWorldGiantBoardedFreeColonist(worldObjects, hostileFac, requireHealthyUndowned: false),
                "Faction mismatch must NOT suppress GameOver");

            // 4. Colony Vehicle Non-Pawn Behavior Firewall (Dormant, Piloted, Autonomous, Custom Rotorcraft vs Biological Dragon)
            var rathPawn = new Pawn { thingIDNumber = 998104, def = new ThingDef { defName = "GCF_Rathalos", shortHash = 61104, race = new RaceProperties() } };
            rathPawn.health = new Pawn_HealthTracker(rathPawn);
            var rathComp = new CompGiantRig { parent = rathPawn };
            rathComp.Initialize(new CompProperties_GiantRig { rigDef = rathRigDef });

            Assert(GiantVehicleBehaviorGuard.IsVehiclePawn(panzerPawn, out _, out _), "PanzerIV (cockpit + vehicleLocomotion) must be classified as vehicle");
            Assert(GiantVehicleBehaviorGuard.IsVehiclePawn(carrierPawn, out _, out _), "ProtossCarrier (flightVehicleLocomotion) must be classified as vehicle");
            Assert(!GiantVehicleBehaviorGuard.IsVehiclePawn(rathPawn, out _, out _), "Biological Rathalos must NOT be classified as vehicle");

            // Remove colonist -> PanzerIV becomes Unmanned Dormant (autonomousWhenEmpty = false)
            cpInner.Remove(colonist);
            typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(panzerPawn, playerFac);
            typeof(Thing).GetField("mapIndexOrState", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(panzerPawn, (sbyte)0);
            panzerPawn.jobs = new Verse.AI.Pawn_JobTracker(panzerPawn);
            Assert(panzerCockpit.IsDormantUnmanned, "Unmanned PanzerIV with autonomousWhenEmpty=false must enter Dormant mode");

            var fleeJob = new Verse.AI.Job { def = new JobDef { defName = "Flee" } };
            Assert(GiantVehicleBehaviorGuard.TryFilterVehicleStartJob(panzerPawn, ref fleeJob, out bool allowDormantFlee)
                   && allowDormantFlee && fleeJob?.def?.defName == "Wait_MaintainPosture",
                "Dormant unmanned vehicle with curJob==null must rewrite Flee into stationary Wait_MaintainPosture (preventing ErrorRecover loop)");

            panzerPawn.jobs.curJob = fleeJob;
            var gotoJob = new Verse.AI.Job { def = new JobDef { defName = "Goto" } };
            Assert(GiantVehicleBehaviorGuard.TryFilterVehicleStartJob(panzerPawn, ref gotoJob, out bool allowDormantGoto)
                   && !allowDormantGoto && gotoJob == null,
                "Dormant unmanned vehicle with active hold job must hard-veto Goto");

            // Board colonist -> PanzerIV is Piloted (active), verify non-vehicle jobs & peacetime wander are blocked while Goto is allowed
            cpInner.Add(colonist);
            var seatArr = (Pawn[])typeof(CompGiantCockpit).GetField("seatOccupants", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(panzerCockpit)!;
            seatArr[0] = colonist;
            Assert(panzerCockpit.IsPiloted, "Seated PrimaryPilot must switch PanzerIV to Piloted mode");
            Assert(panzerCockpit.ShouldHoldPositionWhenPilotedUndrafted, "Piloted undrafted player PanzerIV must hold position");

            string[] forbiddenActiveJobs =
            {
                "Flee", "FleeAndCower", "ExtinguishSelf", "BeatFire", "JumpInWater", "RunRandom",
                "MechCharge", "SelfShutdown", "BoardOrLeaveGravship", "Ingest", "LayDown",
                "HaulToCell", "Mine", "Rescue", "TendPatient", "DoBill", "RopeToPen"
            };
            foreach (string badJobName in forbiddenActiveJobs)
            {
                var badJob = new Verse.AI.Job { def = new JobDef { defName = badJobName } };
                Assert(GiantVehicleBehaviorGuard.TryFilterVehicleStartJob(panzerPawn, ref badJob, out bool allowBad) && !allowBad,
                    $"Active vehicle must hard-veto non-vehicle job '{badJobName}'");
            }

            // Peacetime player vehicle (ProtossCarrier) converts GotoWander into Wait_MaintainPosture, while hostile Carrier keeps patrol GotoWander
            typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(carrierPawn, playerFac);
            typeof(Thing).GetField("mapIndexOrState", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(carrierPawn, (sbyte)0);
            carrierPawn.jobs = new Verse.AI.Pawn_JobTracker(carrierPawn);
            var playerWander = new Verse.AI.Job { def = new JobDef { defName = "GotoWander" } };
            Assert(GiantVehicleBehaviorGuard.TryFilterVehicleStartJob(carrierPawn, ref playerWander, out bool allowPlayerWander)
                   && allowPlayerWander && playerWander?.def?.defName == "Wait_MaintainPosture",
                "Player colony vehicle in peacetime must convert GotoWander into stationary Wait_MaintainPosture");

            typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(carrierPawn, hostileFac);
            var hostileWander = new Verse.AI.Job { def = new JobDef { defName = "GotoWander" } };
            Assert(!GiantVehicleBehaviorGuard.TryFilterVehicleStartJob(carrierPawn, ref hostileWander, out _),
                "Hostile raid vehicle must retain battlefield patrol GotoWander");

            // Verify biological need suppression
            Assert(GiantVehicleBehaviorGuard.ShouldSuppressVehicleNeed(carrierPawn, new RimWorld.NeedDef { defName = "Food" }),
                "Vehicles must suppress biological Food need");
            Assert(GiantVehicleBehaviorGuard.ShouldSuppressVehicleNeed(carrierPawn, new RimWorld.NeedDef { defName = "Rest" }),
                "Vehicles must suppress biological Rest need");
            Assert(!GiantVehicleBehaviorGuard.ShouldSuppressVehicleNeed(rathPawn, new RimWorld.NeedDef { defName = "Food" }),
                "Biological Rathalos must keep its natural Food need");

            // 5. Verify vehicle ThinkTree XMLs exclude BurningResponse & MentalStateCritical
            foreach (string vehTt in new[] { "ThinkTrees_MechColossus.xml", "ThinkTrees_PanzerIV.xml", "ThinkTrees_ProtossCarrier.xml" })
            {
                XDocument doc = XDocument.Load(ResolveMod17Path("Defs", "ThinkTreeDefs", vehTt));
                var treeDefs = doc.Descendants("treeDef").Select(e => e.Value).ToList();
                Assert(!treeDefs.Contains("BurningResponse") && !treeDefs.Contains("MentalStateCritical"),
                    $"{vehTt} must not run BurningResponse or MentalStateCritical above vehicle control");
            }

            // 6. Architectural cleanliness invariant: ZERO per-JobGiver / per-WorkGiver Harmony patches!
            foreach (MethodInfo pm in typeof(HarmonyPatches_VehicleAndTurrets).GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic))
            {
                foreach (HarmonyPatch hp in pm.GetCustomAttributes<HarmonyPatch>())
                {
                    Type dt = hp.info?.declaringType;
                    if (dt != null)
                    {
                        Assert(!dt.Name.StartsWith("JobGiver_", StringComparison.Ordinal) && !dt.Name.StartsWith("WorkGiver_", StringComparison.Ordinal),
                            $"Architectural bloat guard: {pm.Name} patches {dt.Name}. All JobGiver/WorkGiver filtering must stay centralized in GiantVehicleBehaviorGuard choke points.");
                    }
                }
            }

            // 7. Round-2 deep checks: DetermineNextJob sanitizer (Escort FollowClose, modded WorkGiver, Downed FleeDanger),
            //    colonist carry guard, caravan unmanned exclusion, ambient call guard, and WorldObject_Giant crew life-support
            typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(carrierPawn, playerFac);
            var escortJob = new Verse.AI.Job { def = new JobDef { defName = "FollowClose" }, playerForced = false };
            var escortRes = new Verse.AI.ThinkResult(escortJob, null);
            Assert(GiantVehicleBehaviorGuard.SanitizeThinkResultForVehicle(carrierPawn, ref escortRes)
                   && escortRes.Job?.def?.defName == "Wait_MaintainPosture",
                "Player colony vehicle must sanitize Biotech Escort FollowClose into stationary Wait_MaintainPosture");

            var moddedWorkJob = new Verse.AI.Job { def = new JobDef { defName = "CustomModdedLaborJob" }, workGiverDef = new RimWorld.WorkGiverDef { defName = "CustomModWork" } };
            var moddedWorkRes = new Verse.AI.ThinkResult(moddedWorkJob, null);
            Assert(GiantVehicleBehaviorGuard.SanitizeThinkResultForVehicle(carrierPawn, ref moddedWorkRes)
                   && moddedWorkRes.Job?.def?.defName == "Wait_MaintainPosture",
                "Vehicle must sanitize any modded WorkGiver job generically via workGiverDef != null without per-JobGiver patches");

            Assert(GiantVehicleBehaviorGuard.ShouldBlockSmallPawnCarry(colonist, panzerPawn),
                "Small human/lifter pawn must NEVER pick up a 50-ton vehicle or giant in Pawn_CarryTracker");
            Assert(GiantVehicleBehaviorGuard.ShouldBlockSmallPawnCarry(colonist, rathPawn),
                "Small human/lifter pawn must NEVER pick up a giant creature in Pawn_CarryTracker");
            Assert(!GiantVehicleBehaviorGuard.ShouldBlockSmallPawnCarry(colonist, new Pawn { thingIDNumber = 998199, def = colonist.def }),
                "Normal human-to-human rescue carry must remain unaffected");

            Assert(GiantVehicleBehaviorGuard.ShouldSuppressPawnCall(panzerPawn, forceAggressive: false),
                "Parked vehicle must suppress ambient animal/centipede call");
            Assert(!GiantVehicleBehaviorGuard.ShouldSuppressPawnCall(rathPawn, forceAggressive: false),
                "Biological giant Rathalos must retain natural ambient calls");

            // Both unmanned and piloted PanzerIV are excluded from vanilla CaravanFormingUtility.AllSendablePawns
            // (giants/cockpit units travel as WorldObject_Giant, preventing Caravan ticking from starving boarded crew).
            cpInner.Clear();
            seatArr[0] = null;
            Assert(GiantVehicleBehaviorGuard.ShouldExcludeFromSendableCaravanPawns(panzerPawn),
                "Unmanned Dormant PanzerIV must be excluded from CaravanFormingUtility.AllSendablePawns to prevent caravan deadlock");
            cpInner.Add(colonist);
            seatArr[0] = colonist;
            Assert(GiantVehicleBehaviorGuard.ShouldExcludeFromSendableCaravanPawns(panzerPawn),
                "Piloted PanzerIV must also be excluded from vanilla CaravanFormingUtility.AllSendablePawns (uses WorldObject_Giant instead of Caravan)");

            // Verify WorldObject_Giant crew life-support stabilization prevents starvation during long ocean/mountain transit
            panzerPawn.holdingOwner = worldGiant.GetDirectlyHeldThings();
            Assert(CompGiantCockpit.IsHeldInsideWorldGiant(panzerPawn),
                "PanzerIV held inside WorldObject_Giant must satisfy IsHeldInsideWorldGiant");
            panzerCockpit.StabilizeBoardedCrewInWorldTransit();

            Console.WriteLine("       -> Verified spherical great-circle aerial route, WorldObject_Giant anti-GameOver & crew life-support, zero-JobGiver unified vehicle guard & domain isolation");
        }

        private static void TestGiantCrewSeatMountsAndRathalosThreeRiders()
        {
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var rigErrors = rathRig.ConfigErrors().ToList();
            Assert(rigErrors.Count == 0, $"GCF_Rig_Rathalos ConfigErrors must be empty, got: {string.Join("; ", rigErrors)}");

            // 1. Verify BoneNodeDef <crewSeats> topology resolution: 3 seats across 2 midline dorsal parts (thorax_core & thorax_rear)
            IReadOnlyList<GiantBoneCrewSeatDef> mounts = rathRig.CrewSeatMounts;
            Assert(mounts != null && mounts.Count == 3, $"Expected 3 <crewSeats> on GCF_Rig_Rathalos, got {mounts?.Count ?? 0}");

            Assert(rathRig.TryGetCrewSeatMount("SaddleLead", out int leadBoneIdx, out GiantBoneCrewSeatDef leadMount), "Missing SaddleLead mount");
            Assert(rathRig.TryGetCrewSeatMount("SaddleMid", out int midBoneIdx, out GiantBoneCrewSeatDef midMount), "Missing SaddleMid mount");
            Assert(rathRig.TryGetCrewSeatMount("SaddleAft", out int aftBoneIdx, out GiantBoneCrewSeatDef aftMount), "Missing SaddleAft mount");

            Assert(rathRig.SortedNodes[leadBoneIdx].nodeId == "thorax_core",
                $"SaddleLead must be mounted on thorax_core, got '{rathRig.SortedNodes[leadBoneIdx].nodeId}'");
            Assert(rathRig.SortedNodes[midBoneIdx].nodeId == "thorax_rear" && rathRig.SortedNodes[aftBoneIdx].nodeId == "thorax_rear",
                "SaddleMid and SaddleAft must both be mounted on thorax_rear (two midline dorsal parts total)");
            var distinctMountBones = mounts.Select(m => m.resolvedBoneId).Distinct(StringComparer.Ordinal).ToList();
            Assert(distinctMountBones.Count == 2, $"Rathalos 3 crew seats must use exactly 2 midline parts, got {distinctMountBones.Count}");

            // 2. Verify anatomical placement: strictly behind neck (neck_base) and strictly ahead of tail (tail_seg1) along X=0 midline
            int nodeCount = rathRig.SortedNodes.Length;
            var restPoses = new BoneWorldPose[nodeCount];
            SkeletalKinematics.SolveWorldPoses(
                rathRig,
                Vector2.zero,
                0f,
                ReadOnlySpan<BoneLocalPose>.Empty,
                ReadOnlySpan<bool>.Empty,
                restPoses);

            Assert(rathRig.TryGetNodeIndex("neck_base", out int neckBaseIdx), "Missing neck_base");
            Assert(rathRig.TryGetNodeIndex("tail_seg1", out int tailSeg1Idx), "Missing tail_seg1");
            float neckJointZ = restPoses[neckBaseIdx].jointWorldXZ.y;
            float tailJointZ = restPoses[tailSeg1Idx].jointWorldXZ.y;

            Vector3 hostOrigin = new Vector3(50f, Altitudes.AltitudeFor(AltitudeLayer.Pawn), 60f);
            var northPoses = new BoneWorldPose[nodeCount];
            SkeletalKinematics.SolveWorldPoses(
                rathRig,
                new Vector2(hostOrigin.x, hostOrigin.z),
                0f,
                ReadOnlySpan<BoneLocalPose>.Empty,
                ReadOnlySpan<bool>.Empty,
                northPoses);

            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleLead", northPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose pLead), "Eval SaddleLead failed");
            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleMid", northPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose pMid), "Eval SaddleMid failed");
            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleAft", northPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose pAft), "Eval SaddleAft failed");

            foreach (var (name, sp) in new[] { ("SaddleLead", pLead), ("SaddleMid", pMid), ("SaddleAft", pAft) })
            {
                float relX = sp.worldXZ.x - hostOrigin.x;
                float relZ = sp.worldXZ.y - hostOrigin.z;
                Assert(Mathf.Abs(relX) < 1e-3f, $"{name} must lie on the X=0 dorsal midline, got relX={relX:F4}");
                Assert(relZ < neckJointZ - 0.5f, $"{name} relZ={relZ:F3} must sit strictly behind neck_base ({neckJointZ:F3})");
                Assert(relZ > tailJointZ + 2.0f, $"{name} relZ={relZ:F3} must sit strictly ahead of tail_seg1 ({tailJointZ:F3})");
                Assert(sp.facingRot4 == Rot4.North, $"{name} facing 0 deg must resolve Rot4.North");
            }
            Assert(pLead.worldXZ.y > pMid.worldXZ.y + 0.9f && pMid.worldXZ.y > pAft.worldXZ.y + 0.9f,
                "Seats must be spaced cleanly front-to-back along dorsal midline (Lead > Mid > Aft)");

            // 3. Verify unoccluded altitude strictly above all giant bones & skinned meshes (including -10 layer pack clearance)
            float maxGiantPartY = CompGiantRig.ComputeGiantPartWorldAltitude(
                false, false, false, hostOrigin.y, hostOrigin.z, 101, false, 0f, rathRig.maxAuthoredLayerOffset);
            float moteOverheadFloorY = Altitudes.AltitudeFor(AltitudeLayer.MoteOverhead);
            foreach (var (name, sp) in new[] { ("SaddleLead", pLead), ("SaddleMid", pMid), ("SaddleAft", pAft) })
            {
                float lowestRiderSubNodeY = sp.worldY - 0.00366f; // PawnRenderTree layer=-10f worst-case pack/cape node
                Assert(lowestRiderSubNodeY > maxGiantPartY + 0.001f,
                    $"{name} lowest sub-node Y ({lowestRiderSubNodeY:F5}) must stay strictly above highest giant part Y ({maxGiantPartY:F5})");
                Assert(sp.worldY + 0.035f < moteOverheadFloorY,
                    $"{name} ground rider top Y must stay strictly below MoteOverhead ({moteOverheadFloorY:F4})");
            }
            Assert(pAft.worldY > pMid.worldY && pMid.worldY > pLead.worldY,
                "Facing North (0 deg), southern riders must sort visually in front of northern riders (Aft.Y > Mid.Y > Lead.Y)");

            // 4. Verify 360-deg heading, spinal lag bend on thorax_rear, root walk offset, and airborne flight follow
            var localPoses = new BoneLocalPose[nodeCount];
            for (int i = 0; i < nodeCount; i++) localPoses[i] = BoneLocalPose.Identity;
            localPoses[leadBoneIdx] = new BoneLocalPose(new Vector2(0.32f, -0.44f), 0f, Vector2.one); // root gait offset
            localPoses[midBoneIdx] = new BoneLocalPose(Vector2.zero, 14f, Vector2.one); // thorax_rear spinal lag bend

            var eastBentPoses = new BoneWorldPose[nodeCount];
            SkeletalKinematics.SolveWorldPoses(
                rathRig,
                new Vector2(hostOrigin.x, hostOrigin.z),
                90f,
                localPoses,
                ReadOnlySpan<bool>.Empty,
                eastBentPoses);

            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleLead", eastBentPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose eLead), "East Lead failed");
            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleMid", eastBentPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose eMid), "East Mid failed");
            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleAft", eastBentPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose eAft), "East Aft failed");

            Assert(eLead.facingRot4 == Rot4.East && Mathf.Abs(eLead.worldFacingDeg - 90f) < 1e-3f,
                $"East Lead facing expected 90 deg / Rot4.East, got {eLead.worldFacingDeg:F2} / {eLead.facingRot4}");
            Assert(Mathf.Abs(eMid.worldFacingDeg - 104f) < 1e-2f && Mathf.Abs(eAft.worldFacingDeg - 104f) < 1e-2f,
                "SaddleMid & SaddleAft on thorax_rear must follow +14 deg spinal lag bend (90 + 14 = 104 deg)");
            // At 90 deg East, local (+0.32 right, -0.44 forward) rotates to (-0.44 X, -0.32 Z), plus SaddleLead +0.25 forward -> (+0.25 X) => (-0.19 X, -0.32 Z)
            Assert(Mathf.Abs((eLead.worldXZ.x - hostOrigin.x) - (-0.44f + 0.25f)) < 1e-2f
                   && Mathf.Abs((eLead.worldXZ.y - hostOrigin.z) - (-0.32f)) < 1e-2f,
                $"SaddleLead must track rotated root gait offset + localOffset, got rel=({eLead.worldXZ.x - hostOrigin.x:F3}, {eLead.worldXZ.y - hostOrigin.z:F3})");
            // Because thorax_rear bent +14 deg CW from East (toward South-East), Aft seat swings northward (+Z) relative to unbent thorax_rear!
            Assert(Mathf.Abs((eAft.worldXZ.y - eLead.worldXZ.y)) > 0.25f,
                "Spinal lag bend on thorax_rear must laterally displace SaddleAft relative to thorax_core");

            // Airborne flight visual offset (+2.35 Z) and HighAirborne above-FogOfWar altitude boost
            Vector2 flightOffXZ = new Vector2(0f, 2.35f);
            float flightBoostY = CompGiantRig.ComputeAirborneRenderAltitudeBoost(true, null, 101);
            var flyPoses = new BoneWorldPose[nodeCount];
            SkeletalKinematics.SolveWorldPoses(
                rathRig,
                new Vector2(hostOrigin.x, hostOrigin.z) + flightOffXZ,
                180f,
                ReadOnlySpan<BoneLocalPose>.Empty,
                ReadOnlySpan<bool>.Empty,
                flyPoses);

            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleLead", flyPoses, hostOrigin, false, 101, true, flightOffXZ, flightBoostY, out CrewSeatWorldPose fLead), "Fly Lead failed");
            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleAft", flyPoses, hostOrigin, false, 101, true, flightOffXZ, flightBoostY, out CrewSeatWorldPose fAft), "Fly Aft failed");

            Assert(fLead.facingRot4 == Rot4.South && fAft.facingRot4 == Rot4.South, "180 deg flight heading must resolve Rot4.South");
            Assert(Mathf.Abs((fLead.worldXZ.y - hostOrigin.z) - (2.35f - 0.25f)) < 1e-2f,
                $"Airborne SaddleLead must track +2.35 Z flight lift minus 0.25 Southward localOffset, got {fLead.worldXZ.y - hostOrigin.z:F3}");
            float maxAirborneGiantPartY = CompGiantRig.ComputeGiantPartWorldAltitude(
                false, false, false, hostOrigin.y, hostOrigin.z, 101, true, flightBoostY, rathRig.maxAuthoredLayerOffset);
            Assert(fLead.worldY - 0.00366f > maxAirborneGiantPartY + 0.001f
                   && fLead.worldY > Altitudes.AltitudeFor(AltitudeLayer.FogOfWar)
                   && fLead.worldY + 0.035f < Altitudes.AltitudeFor(AltitudeLayer.WorldClipper),
                "Airborne riders must render strictly above airborne dragon parts and FogOfWar, and strictly below WorldClipper");
            Assert(fLead.worldY > fAft.worldY,
                "Facing South (180 deg), Lead rider is further South and must sort above Aft rider");

            // 5. Verify severing thorax_rear hides SaddleMid & SaddleAft while SaddleLead on thorax_core remains visible
            var severedMask = new bool[nodeCount];
            severedMask[midBoneIdx] = true;
            var severedPoses = new BoneWorldPose[nodeCount];
            SkeletalKinematics.SolveWorldPoses(
                rathRig,
                new Vector2(hostOrigin.x, hostOrigin.z),
                0f,
                ReadOnlySpan<BoneLocalPose>.Empty,
                severedMask,
                severedPoses);

            Assert(CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleLead", severedPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out CrewSeatWorldPose sevLead) && sevLead.visible,
                "SaddleLead on intact thorax_core must remain visible when thorax_rear is severed");
            Assert(!CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleMid", severedPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out _),
                "SaddleMid on severed thorax_rear must stop rendering");
            Assert(!CompGiantRig.TryEvaluateCrewSeatWorldPoseFromPoses(
                rathRig, "SaddleAft", severedPoses, hostOrigin, false, 101, false, Vector2.zero, 0f, out _),
                "SaddleAft on severed thorax_rear must stop rendering");

            // 6. Verify Races_Rathalos.xml CompProperties_GiantCrew XML & Biological Mount Non-Vehicle Firewall
            XDocument rathRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_Rathalos.xml"));
            XElement crewCompEl = rathRaceDoc.Descendants("li")
                .FirstOrDefault(e => (string)e.Attribute("Class") == "GiantCreatureFramework.CompProperties_GiantCrew");
            Assert(crewCompEl != null, "Races_Rathalos.xml must define CompProperties_GiantCrew");

            var crewProps = new CompProperties_GiantCrew
            {
                treatHostAsVehicle = ParseBool(crewCompEl.Element("treatHostAsVehicle")?.Value, false),
                renderCrewOnRig = ParseBool(crewCompEl.Element("renderCrewOnRig")?.Value, true),
                autonomousWhenEmpty = ParseBool(crewCompEl.Element("autonomousWhenEmpty")?.Value, true),
                allowHostileAutonomousFallback = ParseBool(crewCompEl.Element("allowHostileAutonomousFallback")?.Value, true),
                allowPlayerControlWithoutOverseer = ParseBool(crewCompEl.Element("allowPlayerControlWithoutOverseer")?.Value, true),
                autonomousMoveSpeedFactor = ParseFloat(crewCompEl.Element("autonomousMoveSpeedFactor")?.Value, 1f),
                autonomousAccuracyFactor = ParseFloat(crewCompEl.Element("autonomousAccuracyFactor")?.Value, 1f),
                autonomousReloadFactor = ParseFloat(crewCompEl.Element("autonomousReloadFactor")?.Value, 1f),
                pilotedMinMoveSpeedFactor = ParseFloat(crewCompEl.Element("pilotedMinMoveSpeedFactor")?.Value, 1f),
                pilotedMaxMoveSpeedFactor = ParseFloat(crewCompEl.Element("pilotedMaxMoveSpeedFactor")?.Value, 1.24f),
                pilotedMinAccuracyFactor = ParseFloat(crewCompEl.Element("pilotedMinAccuracyFactor")?.Value, 1f),
                pilotedMaxAccuracyFactor = ParseFloat(crewCompEl.Element("pilotedMaxAccuracyFactor")?.Value, 1.28f),
                pilotedMinReloadFactor = ParseFloat(crewCompEl.Element("pilotedMinReloadFactor")?.Value, 1f),
                pilotedMaxReloadFactor = ParseFloat(crewCompEl.Element("pilotedMaxReloadFactor")?.Value, 1.24f),
                enterTicks = int.Parse(crewCompEl.Element("enterTicks")?.Value ?? "45", CultureInfo.InvariantCulture)
            };

            BodyDef rathBody = LoadBodyDefFromXml("Bodies_Rathalos.xml", "GCF_Body_Rathalos");
            foreach (XElement sEl in crewCompEl.Element("seats")!.Elements("li"))
            {
                Enum.TryParse(sEl.Element("role")?.Value, true, out GiantCockpitRole parsedRole);
                string bpName = sEl.Element("linkedBodyPart")?.Value;
                crewProps.seats.Add(new GiantCockpitSeatDef
                {
                    seatId = sEl.Element("seatId")?.Value,
                    role = parsedRole,
                    labelKey = sEl.Element("labelKey")?.Value,
                    partLabelKey = sEl.Element("partLabelKey")?.Value,
                    linkedBodyPart = !string.IsNullOrEmpty(bpName) ? new BodyPartDef { defName = bpName } : null,
                    linkedBodyPartCustomLabel = sEl.Element("linkedBodyPartCustomLabel")?.Value,
                    renderOccupant = ParseBool(sEl.Element("renderOccupant")?.Value, true)
                });
            }

            Assert(!crewProps.treatHostAsVehicle && crewProps.renderCrewOnRig && crewProps.seats.Count == 3,
                "Rathalos CompProperties_GiantCrew must set treatHostAsVehicle=false, renderCrewOnRig=true, and 3 seats");

            var rathThingDef = new ThingDef
            {
                defName = "GCF_Rathalos",
                shortHash = 61255,
                race = new RaceProperties { intelligence = Intelligence.Animal, body = rathBody },
                comps = new List<CompProperties>
                {
                    new CompProperties_GiantRig { rigDef = rathRig },
                    crewProps
                }
            };
            var crewCfgErrors = crewProps.ConfigErrors(rathThingDef).ToList();
            Assert(crewCfgErrors.Count == 0, $"Rathalos CompProperties_GiantCrew ConfigErrors must be empty, got: {string.Join("; ", crewCfgErrors)}");

            // Negative validation check: enabling renderCrewOnRig with an unmapped seatId must emit a ConfigError
            var badCrewProps = new CompProperties_GiantCrew
            {
                renderCrewOnRig = true,
                seats = new List<GiantCockpitSeatDef> { new GiantCockpitSeatDef { seatId = "NonExistentTailSeat", renderOccupant = true } }
            };
            var badThingDef = new ThingDef
            {
                defName = "GCF_TestBadCrewMount",
                comps = new List<CompProperties> { new CompProperties_GiantRig { rigDef = rathRig }, badCrewProps }
            };
            Assert(badCrewProps.ConfigErrors(badThingDef).Any(e => e.Contains("NonExistentTailSeat", StringComparison.Ordinal)),
                "CompProperties_GiantCockpit.ConfigErrors must catch unmapped seatId when renderCrewOnRig is true");

            var mountedRathPawn = new Pawn { thingIDNumber = 998601, def = rathThingDef };
            mountedRathPawn.health = new Pawn_HealthTracker(mountedRathPawn);
            var mountedRigComp = new CompGiantRig { parent = mountedRathPawn };
            mountedRigComp.Initialize(new CompProperties_GiantRig { rigDef = rathRig });
            var mountedCrewComp = new CompGiantCrew { parent = mountedRathPawn };
            mountedCrewComp.Initialize(crewProps);
            mountedCrewComp.ResolveSeatBodyPartLinks();
            mountedRathPawn.AllComps.Add(mountedRigComp);
            mountedRathPawn.AllComps.Add(mountedCrewComp);
            GiantFastLookup.Register(mountedRathPawn, mountedRigComp);
            GiantFastLookup.RegisterCockpit(mountedRathPawn, mountedCrewComp);
            try
            {
                Assert(!GiantVehicleBehaviorGuard.IsVehiclePawn(mountedRathPawn, out _, out CompGiantCockpit resolvedCrew) && resolvedCrew == mountedCrewComp,
                    "Biological Rathalos with CompGiantCrew (treatHostAsVehicle=false) must NOT be classified as a mechanical vehicle");
                Assert(!GiantVehicleBehaviorGuard.ShouldSuppressVehicleNeed(mountedRathPawn, new RimWorld.NeedDef { defName = "Food" }),
                    "Saddled Rathalos must retain its natural biological Food need");
                Assert(!GiantVehicleBehaviorGuard.ShouldSuppressPawnCall(mountedRathPawn, forceAggressive: false),
                    "Saddled Rathalos must retain natural ambient calls");
                Assert(!mountedCrewComp.IsAutonomousPlayerControlledVehicle,
                    "Biological Rathalos must never set IsAutonomousPlayerControlledVehicle (ColonyMech flag)");
                Assert(mountedCrewComp.CurrentMode == GiantCockpitControlMode.Autonomous
                       && Mathf.Approximately(mountedCrewComp.ComputeMoveSpeedMultiplier(), 1f),
                    "Unmounted Rathalos must operate at 100% natural speed without Dormant lockout");
                Assert(mountedCrewComp.GetSeatBodyPartRecord(0)?.customLabel == "thorax core"
                       && mountedCrewComp.GetSeatBodyPartRecord(1)?.customLabel == "rear thorax"
                       && mountedCrewComp.GetSeatBodyPartRecord(2)?.customLabel == "rear thorax",
                    "All 3 Rathalos seats must resolve their exact BodyPartRecords on GCF_Body_Rathalos");

                // 6b. Regression: Mounted + Airborne Rathalos ability usability (TakingOff + Airborne, undrafted queue pass-through & aerial clip resolution)
                XDocument rathAbilDoc = XDocument.Load(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_Rathalos.xml"));
                foreach (string aerialAbName in new[] { "GCF_Ability_Rathalos_FireballBreath", "GCF_Ability_Rathalos_TalonStrike" })
                {
                    XElement abNode = rathAbilDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == aerialAbName);
                    float xmlMinRange = float.Parse(abNode.Element("verbProperties")!.Element("minRange")!.Value, System.Globalization.CultureInfo.InvariantCulture);
                    float xmlMinDist = float.Parse(abNode.Descendants("minDistance").First().Value, System.Globalization.CultureInfo.InvariantCulture);
                    AssertNear(xmlMinRange, 1.5f, 1e-3f, $"{aerialAbName} minRange must allow close-range aerial targeting (1.5)");
                    AssertNear(xmlMinDist, 1.5f, 1e-3f, $"{aerialAbName} minDistance must allow close-range aerial targeting (1.5)");
                }

                var playerFacDef = new RimWorld.FactionDef { defName = "PlayerColony", isPlayer = true };
                var playerFac = new RimWorld.Faction { def = playerFacDef };
                typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(mountedRathPawn, playerFac);
                typeof(Thing).GetField("mapIndexOrState", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(mountedRathPawn, (sbyte)0);
                mountedRathPawn.jobs = new Verse.AI.Pawn_JobTracker(mountedRathPawn);
                mountedRathPawn.jobs.jobQueue = new Verse.AI.JobQueue();
                mountedRathPawn.stances = new Pawn_StanceTracker(mountedRathPawn);
                mountedRathPawn.drafter = new RimWorld.Pawn_DraftController(mountedRathPawn);

                // Unmounted biological Rathalos must NOT short-circuit ThinkTree or nullify ConstantThinkTree
                Assert(!GiantVehicleBehaviorGuard.ShouldNullifyConstantThinkTree(mountedRathPawn),
                    "Unmounted biological Rathalos must keep ConstantThinkTree active");
                ThinkTreeDef dummyTree = new ThinkTreeDef { defName = "GCF_ThinkTree_Rathalos" };
                Assert(!GiantVehicleBehaviorGuard.TryShortCircuitDetermineNextJob(mountedRathPawn, ref dummyTree, out _),
                    "Unmounted biological Rathalos must not short-circuit DetermineNextJob");

                // Board primary rider -> Piloted mode (populate innerList directly in headless test without WorldPawns)
                var riderColonist = new Pawn
                {
                    thingIDNumber = 998602,
                    def = new ThingDef { defName = "Human", race = new RaceProperties { intelligence = Intelligence.Humanlike } }
                };
                riderColonist.health = new Pawn_HealthTracker(riderColonist);
                var crewInnerList = (List<Thing>)typeof(ThingOwner<Thing>).GetField("innerList", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(mountedCrewComp.GetDirectlyHeldThings())!;
                crewInnerList.Add(riderColonist);
                var crewSeatsArr = (Pawn[])typeof(CompGiantCockpit).GetField("seatOccupants", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(mountedCrewComp)!;
                crewSeatsArr[0] = riderColonist;
                Assert(mountedCrewComp.IsPiloted, "Seated rider must place Rathalos into Piloted (Mounted) mode");

                // While mounted & undrafted with empty queue, hold station; as soon as player queues CastAbilityOnThing, allow ThinkNode_QueuedJob!
                Assert(mountedCrewComp.ShouldHoldPositionWhenPilotedUndrafted,
                    "Mounted undrafted Rathalos with no queued order must hold station for its rider");
                Assert(GiantVehicleBehaviorGuard.ShouldNullifyConstantThinkTree(mountedRathPawn),
                    "Mounted undrafted Rathalos with no queued order must suppress autonomous ConstantThinkTree ability burn");
                ThinkTreeDef holdTree = new ThinkTreeDef { defName = "GCF_ThinkTree_Rathalos" };
                Assert(GiantVehicleBehaviorGuard.TryShortCircuitDetermineNextJob(mountedRathPawn, ref holdTree, out Verse.AI.ThinkResult holdRes)
                       && holdRes.Job?.def?.defName == "Wait_MaintainPosture",
                    "Mounted undrafted Rathalos must hold posture instead of wandering away");

                var castAbilityJob = new Verse.AI.Job
                {
                    def = new JobDef { defName = "CastAbilityOnThing", abilityCasting = true },
                    playerForced = true
                };
                mountedRathPawn.jobs.jobQueue.EnqueueFirst(castAbilityJob);
                Assert(!mountedCrewComp.ShouldHoldPositionWhenPilotedUndrafted,
                    "Queued player CastAbilityOnThing must immediately release undrafted station-hold");
                ThinkTreeDef castTree = new ThinkTreeDef { defName = "GCF_ThinkTree_Rathalos" };
                Assert(!GiantVehicleBehaviorGuard.TryShortCircuitDetermineNextJob(mountedRathPawn, ref castTree, out _),
                    "Queued player CastAbilityOnThing must pass straight through DetermineNextJob to ThinkNode_QueuedJob");
                mountedRathPawn.jobs.jobQueue.Dequeue();

                // Command Takeoff: verify both TakingOff (tick 0, altitude 0) and full Airborne (altitude 1) enable aerial abilities & aerial clip
                var flightRt = mountedRigComp.FlightLocomotion ?? new GiantFlightRuntime(rathRig, rathRig.ActiveFlightLocomotion!);
                typeof(CompGiantRig).GetField("flightLocomotion", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(mountedRigComp, flightRt);
                Assert(flightRt.TryCommandTakeoff(mountedRigComp, out string takeoffFail) && flightRt.FlightState == GiantFlightState.TakingOff,
                    $"Mounted Rathalos takeoff must succeed, got '{takeoffFail}'");
                Assert(CompAbilityEffect_RathalosDragonCharge.IsRathalosInAerialAbilityState(mountedRigComp),
                    "TakingOff state must immediately count as aerial ability state so aerial abilities do not stall on pause/liftoff");

                var talonAb = (RimWorld.Ability)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(RimWorld.Ability));
                talonAb.pawn = mountedRathPawn;
                talonAb.def = new RimWorld.AbilityDef { defName = "GCF_Ability_Rathalos_TalonStrike" };
                var talonComp = new CompAbilityEffect_RathalosTalonStrike
                {
                    parent = talonAb,
                    props = new CompProperties_AbilityRathalosTalonStrike()
                };
                talonAb.comps = new List<RimWorld.AbilityComp> { talonComp };
                Assert(!talonComp.GizmoDisabled(out string talonReason),
                    $"TalonStrike must NOT be disabled during TakingOff, got '{talonReason}'");

                var fbAb = (RimWorld.Ability)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(RimWorld.Ability));
                fbAb.pawn = mountedRathPawn;
                fbAb.def = new RimWorld.AbilityDef { defName = "GCF_Ability_Rathalos_FireballBreath" };
                var fbComp = new CompAbilityEffect_RathalosFireball
                {
                    parent = fbAb,
                    props = new CompProperties_AbilityRathalosFireball()
                };
                fbAb.comps = new List<RimWorld.AbilityComp> { fbComp };
                Assert(mountedRigComp.ResolveAbilityAnim(fbAb)?.defName == "GCF_Anim_Rathalos_AerialFireball",
                    "TakingOff/Airborne FireballBreath must resolve GCF_Anim_Rathalos_AerialFireball during warmup and cast");

                for (int t = 0; t < 50; t++)
                {
                    flightRt.StepHeadlessTick(0f);
                }
                Assert(flightRt.FlightState == GiantFlightState.Airborne && mountedRigComp.IsCurrentlyAirborne,
                    "Rathalos must reach full Airborne state");
                Assert(!talonComp.GizmoDisabled(out _) && mountedRigComp.ResolveAbilityAnim(fbAb)?.defName == "GCF_Anim_Rathalos_AerialFireball",
                    "Full Airborne mounted Rathalos must keep TalonStrike enabled and FireballBreath on AerialFireball clip");

                // 6c. Regression: Drafted movement arrival must preserve exact heading instead of snapping to Rot4.South (180 deg)
                typeof(RimWorld.Pawn_DraftController).GetField("draftedInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(mountedRathPawn.drafter, true);
                mountedRathPawn.jobs.curJob = new Verse.AI.Job { def = new JobDef { defName = "Wait_Combat" } };
                MethodInfo updateHeadingMethod = typeof(CompGiantRig).GetMethod("UpdateHeadingAndSteering", BindingFlags.Instance | BindingFlags.NonPublic)!;
                FieldInfo curHeadingField = typeof(CompGiantRig).GetField("currentHeadingDeg", BindingFlags.Instance | BindingFlags.NonPublic)!;
                FieldInfo tgtHeadingField = typeof(CompGiantRig).GetField("targetHeadingDeg", BindingFlags.Instance | BindingFlags.NonPublic)!;
                FieldInfo hdgInitField = typeof(CompGiantRig).GetField("headingInitialized", BindingFlags.Instance | BindingFlags.NonPublic)!;

                foreach (var (arrivalDeg, expectedRot) in new (float, Rot4)[]
                {
                    (0f, Rot4.North),
                    (90f, Rot4.East),
                    (270f, Rot4.West),
                    (42f, Rot4.North)
                })
                {
                    curHeadingField.SetValue(mountedRigComp, arrivalDeg);
                    tgtHeadingField.SetValue(mountedRigComp, arrivalDeg);
                    hdgInitField.SetValue(mountedRigComp, true);
                    mountedRathPawn.Rotation = Rot4.South; // simulate vanilla trying to force South

                    bool runVanillaRot = HarmonyPatches_VehicleAndTurrets.Pawn_RotationTracker_UpdateRotation_Vehicle_Prefix(mountedRathPawn);
                    Assert(!runVanillaRot && mountedRathPawn.Rotation == expectedRot,
                        $"Drafted stationary Rathalos at {arrivalDeg} deg must block vanilla Rot4.South reset and sync Rotation={expectedRot}, got {mountedRathPawn.Rotation}");

                    for (int step = 0; step < 12; step++)
                    {
                        updateHeadingMethod.Invoke(mountedRigComp, new object[] { 1f, 0f });
                    }
                    AssertNear(mountedRigComp.CurrentHeadingDeg, arrivalDeg, 1e-2f,
                        $"Drafted stationary Rathalos must preserve exact arrival heading {arrivalDeg} deg instead of turning downward (180 deg), got {mountedRigComp.CurrentHeadingDeg}");
                }

                // 6d. Regression: Zoom-out SilhouetteGraphic NRE guard + Player-faction Giant Health Bar suppression
                bool silResult = true;
                bool runVanillaSil = HarmonyPatches_Rendering.SilhouetteUtility_ShouldDrawSilhouette_Prefix(mountedRathPawn, ref silResult);
                Assert(!runVanillaSil && !silResult,
                    "SilhouetteUtility_ShouldDrawSilhouette_Prefix must block silhouette rendering on GCF giants (preventing DrawSilhouettes NullReferenceException)");

                Assert(!GiantBossHealthBarHUD.ShouldDisplayBossHealthBar(mountedRathPawn, mountedRigComp),
                    "Player-faction giants must NEVER display the top-screen Boss Health Bar HUD");
                Assert(!HarmonyPatches_Rendering.PawnUIOverlay_DrawPawnGUIOverlay_Prefix(mountedRathPawn),
                    "Player-faction giants must also suppress ground-level PawnUIOverlay miniature health bars");

                var testHud = new GiantBossHealthBarHUD();
                testHud.NotifyGiantRegistered(mountedRigComp);
                var hudEntries = (System.Collections.IList)typeof(GiantBossHealthBarHUD).GetField("entries", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(testHud)!;
                Assert(hudEntries.Count == 0, "NotifyGiantRegistered must ignore player-faction giants");

                var hostileFac = new RimWorld.Faction { def = new RimWorld.FactionDef { defName = "Mechanoid", isPlayer = false } };
                typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(mountedRathPawn, hostileFac);
                Assert(GiantBossHealthBarHUD.ShouldDisplayBossHealthBar(mountedRathPawn, mountedRigComp),
                    "Hostile/non-player giants must still display the top-screen Boss Health Bar HUD");
            }
            finally
            {
                GiantFastLookup.Unregister(mountedRathPawn);
                GiantFastLookup.UnregisterCockpit(mountedRathPawn);
            }

            // 7. Verify 4-language Keyed XML parity for all new crew/saddle keys
            string[] reqKeys =
            {
                "GCF_CrewMode_Mounted",
                "GCF_CrewMode_Unmounted",
                "GCF_CrewRole_WyvernLeadRider",
                "GCF_CrewRole_WyvernMidRider",
                "GCF_CrewRole_WyvernAftRider",
                "GCF_CrewPart_RathalosThoraxCore",
                "GCF_CrewPart_RathalosThoraxRearFore",
                "GCF_CrewPart_RathalosThoraxRearAft"
            };
            foreach (string lang in new[] { "ChineseSimplified", "English", "Japanese", "Russian" })
            {
                var merged = LoadMergedKeyedMap(lang);
                foreach (string k in reqKeys)
                {
                    Assert(merged.TryGetValue(k, out string val) && !string.IsNullOrWhiteSpace(val),
                        $"Missing or empty keyed translation '{k}' in {lang}");
                }
            }

            Console.WriteLine("       -> Verified <crewSeats> topology, <renderCrewOnRig> unoccluded pose/flight tracking, Rathalos 3-rider 2-part dorsal saddle & biological firewall");
        }

        private static void TestMechColossusMainGunDeadzoneRetreatAndScaledSkillRanges()
        {
            // 1. Verify Stage 1 (13.8), Stage 2 (2x = 35.0 range & coneLength), and Stage 3 (3x = 72.0 range + Verb_CastGiantAbility)
            XDocument abDoc = XDocument.Load(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_MechColossus.xml"));
            XElement s1Ab = abDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == "GCF_Ability_MechHydraulicImpact");
            XElement s2Ab = abDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == "GCF_Ability_MechThermalBeamSweep");
            XElement s3Ab = abDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == "GCF_Ability_MechOrbitalStrikeNova");

            AssertNear(ParseFloat(s1Ab.Element("verbProperties")?.Element("range")?.Value, 0f), 13.8f, 0.01f, "Stage 1 HydraulicImpact range must remain 13.8");
            AssertNear(ParseFloat(s2Ab.Element("verbProperties")?.Element("range")?.Value, 0f), 35.0f, 0.01f, "Stage 2 ThermalBeamSweep range must be 2x (35.0)");
            XElement s2SweepComp = s2Ab.Element("comps")!.Elements("li")
                .First(c => (c.Attribute("Class")?.Value ?? string.Empty).EndsWith("CompProperties_AbilityMechThermalBeamSweep", StringComparison.Ordinal));
            AssertNear(ParseFloat(s2SweepComp.Element("coneLength")?.Value, 0f), 35.0f, 0.01f, "Stage 2 ThermalBeamSweep coneLength must match 2x range (35.0)");

            AssertNear(ParseFloat(s3Ab.Element("verbProperties")?.Element("range")?.Value, 0f), 72.0f, 0.01f, "Stage 3 OrbitalStrikeNova range must be 3x (72.0)");
            Assert(s3Ab.Element("verbProperties")?.Element("verbClass")?.Value == "GiantCreatureFramework.Verb_CastGiantAbility",
                "Stage 3 OrbitalStrikeNova (range=72 > GenRadial.MaxRadialPatternRadius) must use Verb_CastGiantAbility");

            // 2. Verify ThinkTrees_MechColossus.xml & dynamic autonomous AI acquire radius cover 72.0 range
            XDocument ttDoc = XDocument.Load(ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_MechColossus.xml"));
            XElement abNode = ttDoc.Descendants("li").First(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.JobGiver_GiantAbilityFight");
            XElement posNode = ttDoc.Descendants("li").First(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.JobGiver_GiantPartCombatPositioning");
            Assert(ParseFloat(abNode.Element("maxAcquireRadius")?.Value, 0f) >= 75f, "MechColossus JobGiver_GiantAbilityFight maxAcquireRadius must cover 72.0 range");
            Assert(ParseFloat(posNode.Element("targetAcquireRadius")?.Value, 0f) >= 75f &&
                   ParseFloat(posNode.Element("targetKeepRadius")?.Value, 0f) >= 85f,
                "MechColossus JobGiver_GiantPartCombatPositioning acquire/keep radii must cover 72.0 range");

            var dummyPawn = new Pawn { thingIDNumber = 998811 };
            dummyPawn.abilities = new RimWorld.Pawn_AbilityTracker(dummyPawn);
            var novaDef = new RimWorld.AbilityDef
            {
                defName = "GCF_Ability_MechOrbitalStrikeNova",
                aiCanUse = true,
                ai_IsOffensive = true,
                verbProperties = new VerbProperties { range = 72.0f }
            };
            dummyPawn.abilities.abilities.Add(new RimWorld.Ability { pawn = dummyPawn, def = novaDef });
            AssertNear(JobGiver_GiantAbilityFight.GetMaxOffensiveAbilityRange(dummyPawn), 72.0f, 0.01f,
                "GetMaxOffensiveAbilityRange must resolve 72.0f for Stage 3 OrbitalStrikeNova");

            // 3. Verify Capital Main-Gun vs Point-Defense CIWS classification & minRange deadzone retreat trigger on MechColossus & PanzerIV
            // Stage 3 Colossus: Railgun (range=42, minRange=3.5), Bridge Siege (range=36, minRange=4.5), Wing CIWS Pod (range=25, minRange=1.2)
            float s3MaxRange = 42.0f;
            float s3MaxGroupDps = 26.55f;
            Assert(GiantPartCombatRuntime.IsCapitalMainRangedWeapon(42.0f, 3.5f, 18.1f, s3MaxRange, s3MaxGroupDps), "Stage 3 Annihilation Railgun must be capital main weapon");
            Assert(GiantPartCombatRuntime.IsCapitalMainRangedWeapon(36.0f, 4.5f, 26.5f, s3MaxRange, s3MaxGroupDps), "Stage 3 Bridge Siege Cannon must be capital main weapon");
            Assert(!GiantPartCombatRuntime.IsCapitalMainRangedWeapon(25.0f, 1.2f, 12.0f, s3MaxRange, s3MaxGroupDps), "Stage 3 X-Wing CIWS Pod must NOT be capital main weapon");

            // When enemy closes to 2.8 cells from Bridge Siege muzzle (< 4.5 + 0.65), retreat triggers even though CIWS pod (minRange=1.2) can still fire!
            Assert(GiantPartCombatRuntime.IsMainGunInMinRangeDeadzone(36.0f, 4.5f, 26.5f, s3MaxRange, s3MaxGroupDps, alignedMuzzleDist: 2.8f),
                "Stage 3 must trigger deadzone retreat when Bridge Siege Cannon is inside minRange (2.8 < 4.5 + 0.65)");
            Assert(GiantPartCombatRuntime.IsMainGunInMinRangeDeadzone(42.0f, 3.5f, 18.1f, s3MaxRange, s3MaxGroupDps, alignedMuzzleDist: 3.2f),
                "Stage 3 must trigger deadzone retreat when Annihilation Railgun is inside minRange (3.2 < 3.5 + 0.65)");
            Assert(!GiantPartCombatRuntime.IsMainGunInMinRangeDeadzone(36.0f, 4.5f, 26.5f, s3MaxRange, s3MaxGroupDps, alignedMuzzleDist: 6.5f),
                "Stage 3 must hold firing posture once clear of Bridge Siege deadzone (6.5 >= 5.15)");

            // Stage 2 Colossus: Director Lance (range=32, minRange=2.5) vs S1 CIWS (range=24, minRange=1.5)
            Assert(GiantPartCombatRuntime.IsMainGunInMinRangeDeadzone(32.0f, 2.5f, 29.5f, 32.0f, 29.5f, alignedMuzzleDist: 1.9f),
                "Stage 2 must trigger deadzone retreat when Director Lance is jammed inside minRange");

            // Panzer IV: 7.5cm KwK 40 (range=35.9, minRange=3.9) vs MG 34 (range=21.9, minRange=1.5)
            Assert(GiantPartCombatRuntime.IsMainGunInMinRangeDeadzone(35.9f, 3.9f, 18.0f, 35.9f, 18.0f, alignedMuzzleDist: 2.5f),
                "Panzer IV must trigger deadzone retreat when KwK 40 main gun is inside 3.9 minRange");
            Assert(!GiantPartCombatRuntime.IsMainGunInMinRangeDeadzone(35.9f, 3.9f, 18.0f, 35.9f, 18.0f, alignedMuzzleDist: 5.2f),
                "Panzer IV must hold firing stance outside KwK 40 minRange");
            Assert(!GiantPartCombatRuntime.IsCapitalMainRangedWeapon(21.9f, 1.5f, 6.8f, 35.9f, 18.0f),
                "Panzer IV bow MG 34 must remain secondary weapon");
        }

        private static void TestAnimalGiantPredatorHuntHullTamingAutoLandAndThinkTree()
        {
            // 1. Verify ThinkTrees_Rathalos.xml includes full vanilla animal daily lifecycle & master obedience nodes
            string rathTreePath = ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_Rathalos.xml");
            XDocument treeDoc = XDocument.Load(rathTreePath);
            List<string> nodeClasses = treeDoc.Descendants("li")
                .Select(e => (string)e.Attribute("Class"))
                .Where(c => !string.IsNullOrEmpty(c))
                .ToList();
            List<string> subTreeDefs = treeDoc.Descendants("treeDef")
                .Select(e => e.Value?.Trim())
                .Where(v => !string.IsNullOrEmpty(v))
                .ToList();

            string[] requiredAnimalNodes =
            {
                "ThinkNode_ConditionalMustKeepLyingDown",
                "JobGiver_KeepLyingDown",
                "GiantCreatureFramework.JobGiver_GiantPartCombatPositioning",
                "JobGiver_LayEgg",
                "ThinkNode_ConditionalTrainableCompleted",
                "JobGiver_AIDefendMaster",
                "JobGiver_AIFollowMaster",
                "JobGiver_WanderNearMaster",
                "JobGiver_SeekAllowedArea",
                "JobGiver_SeekSafeTemperature",
                "JobGiver_Mate",
                "JobGiver_Nuzzle",
                "JobGiver_WanderColony",
                "JobGiver_WanderAnywhere"
            };
            foreach (string req in requiredAnimalNodes)
            {
                Assert(nodeClasses.Contains(req), $"ThinkTrees_Rathalos.xml missing required animal behavior node '{req}'");
            }
            Assert(subTreeDefs.Contains("SatisfyBasicNeeds"),
                "ThinkTrees_Rathalos.xml must preserve SatisfyBasicNeeds sub-tree for food & sleep");

            // Verify Races_Rathalos.xml preserves predator, Advanced trainability, non-vehicle biological mount, and 0 base <tools>
            XDocument rathRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_Rathalos.xml"));
            XElement rathDefEl = rathRaceDoc.Descendants("ThingDef")
                .FirstOrDefault(e => e.Element("defName")?.Value == "GCF_Rathalos");
            Assert(rathDefEl != null && (string)rathDefEl.Attribute("ParentName") == "AnimalThingBase",
                "GCF_Rathalos must inherit from AnimalThingBase");
            Assert((rathDefEl.Element("tools")?.Elements().Count() ?? 0) == 0,
                "GCF_Rathalos must have 0 base-Pawn <tools> entries (all strikes driven by GiantPartCombatRuntime)");
            XElement raceEl = rathDefEl.Element("race");
            Assert(raceEl?.Element("predator")?.Value == "true", "GCF_Rathalos must declare <predator>true</predator>");
            Assert(raceEl?.Element("trainability")?.Value == "Advanced", "GCF_Rathalos must declare <trainability>Advanced</trainability>");

            // 2. Verify PredatorHunt -> PartCombat live/downed prey tracking & Corpse transition handoff
            var predator = new Pawn
            {
                thingIDNumber = 999201,
                def = new ThingDef { defName = "GCF_Rathalos", shortHash = 62201, race = new RaceProperties { predator = true } }
            };
            predator.health = new Pawn_HealthTracker(predator);
            predator.jobs = new Verse.AI.Pawn_JobTracker(predator);

            var prey = new Pawn
            {
                thingIDNumber = 999202,
                def = new ThingDef { defName = "Muffalo", shortHash = 62202, race = new RaceProperties() }
            };
            prey.health = new Pawn_HealthTracker(prey);

            var huntPawnJob = new Verse.AI.Job
            {
                def = new JobDef { defName = "PredatorHunt" },
                targetA = new LocalTargetInfo(prey)
            };
            predator.jobs.curJob = huntPawnJob;
            Assert(GiantPartCombatRuntime.TryGetActivePredatorHuntPrey(predator, out Pawn activePrey) && activePrey == prey,
                "TryGetActivePredatorHuntPrey must resolve live/downed Pawn target during PredatorHunt");

            var preyCorpse = new Corpse { InnerPawn = prey };
            var huntCorpseJob = new Verse.AI.Job
            {
                def = new JobDef { defName = "PredatorHunt" },
                targetA = new LocalTargetInfo(preyCorpse)
            };
            predator.jobs.curJob = huntCorpseJob;
            Assert(!GiantPartCombatRuntime.TryGetActivePredatorHuntPrey(predator, out _),
                "TryGetActivePredatorHuntPrey must return false once PredatorHunt targetA switches to Corpse for eating");

            predator.jobs.curJob = new Verse.AI.Job
            {
                def = new JobDef { defName = "Ingest" },
                targetA = new LocalTargetInfo(preyCorpse)
            };
            Assert(!GiantPartCombatRuntime.TryGetActivePredatorHuntPrey(predator, out _),
                "TryGetActivePredatorHuntPrey must return false for non-PredatorHunt jobs");

            // 3. Verify Hull-Perimeter Taming/Training/Social patches & GotoInteractablePosition delegate wrapping
            Assert(typeof(HarmonyPatches_CombatAndHitbox).GetMethod("FoodUtility_BestPawnToHuntForPredator_Prefix", BindingFlags.Public | BindingFlags.Static) != null,
                "Missing FoodUtility_BestPawnToHuntForPredator_Prefix");
            Assert(typeof(HarmonyPatches_CollisionAndSelection).GetMethod("SocialInteractionUtility_IsGoodPositionForInteraction_Postfix", BindingFlags.Public | BindingFlags.Static) != null,
                "Missing SocialInteractionUtility_IsGoodPositionForInteraction_Postfix");
            Assert(typeof(HarmonyPatches_CollisionAndSelection).GetMethod("SocialInteractionUtility_BestInteractableCell_Postfix", BindingFlags.Public | BindingFlags.Static) != null,
                "Missing SocialInteractionUtility_BestInteractableCell_Postfix");

            bool origInitCalled = false;
            int origTickDelta = -1;
            var testToil = new Verse.AI.Toil
            {
                initAction = () => { origInitCalled = true; },
                tickIntervalAction = d => { origTickDelta = d; }
            };
            HarmonyPatches_CollisionAndSelection.Toils_Interpersonal_GotoInteractablePosition_Postfix(Verse.AI.TargetIndex.A, ref testToil);
            testToil.initAction();
            testToil.tickIntervalAction(15);
            Assert(origInitCalled && origTickDelta == 15,
                "Wrapped GotoInteractablePosition toil must cleanly delegate to vanilla actions for non-giant pawns");

            // 4. Verify Biological Flyer Out-of-Combat & Terrestrial Activity Auto-Landing (GiantFlightRuntime)
            var ingestJob = new Verse.AI.Job { def = new JobDef { defName = "Ingest" } };
            var layDownJob = new Verse.AI.Job { def = new JobDef { defName = "LayDown" } };
            var mateJob = new Verse.AI.Job { def = new JobDef { defName = "Mate" } };
            var layEggJob = new Verse.AI.Job { def = new JobDef { defName = "LayEgg" } };
            var nuzzleJob = new Verse.AI.Job { def = new JobDef { defName = "Nuzzle" } };
            var handlerPawn = new Pawn { thingIDNumber = 999203, def = new ThingDef { defName = "Human", race = new RaceProperties { intelligence = Intelligence.Humanlike } } };
            var tamerForceWaitJob = new Verse.AI.Job { def = new JobDef { defName = "Wait" }, targetB = new LocalTargetInfo(handlerPawn) };
            var plainGotoJob = new Verse.AI.Job { def = new JobDef { defName = "Goto" } };
            var combatWaitJob = new Verse.AI.Job { def = new JobDef { defName = "Wait_Combat" } };

            foreach (var terrJob in new[] { ingestJob, layDownJob, mateJob, layEggJob, nuzzleJob, huntCorpseJob, tamerForceWaitJob })
            {
                Assert(GiantFlightRuntime.IsBiologicalTerrestrialActivityJob(terrJob),
                    $"Expected IsBiologicalTerrestrialActivityJob == true for '{terrJob.def.defName}'");
                Assert(GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                        isVehiclePawn: false,
                        flightMode: GiantFlightMode.TakeoffAndLanding,
                        hasActiveHostileEnemy: false,
                        isFlyingEnRouteFar: true,
                        airborneSustainedTicks: 10,
                        minAirborneTicksBeforeAutoLand: 120,
                        currentJob: terrJob),
                    $"Biological TakeoffAndLanding flyer must auto-land immediately for terrestrial job '{terrJob.def.defName}'");
            }

            foreach (var airOkJob in new[] { huntPawnJob, plainGotoJob, combatWaitJob })
            {
                Assert(!GiantFlightRuntime.IsBiologicalTerrestrialActivityJob(airOkJob),
                    $"Expected IsBiologicalTerrestrialActivityJob == false for '{airOkJob.def.defName}'");
            }

            // Stay airborne in active combat or while flying far en route; auto-land once out of combat & settled (>= 120 ticks)
            Assert(!GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                    false, GiantFlightMode.TakeoffAndLanding, hasActiveHostileEnemy: true, isFlyingEnRouteFar: false,
                    airborneSustainedTicks: 300, minAirborneTicksBeforeAutoLand: 120, currentJob: combatWaitJob),
                "Biological flyer must NOT auto-land out-of-combat while an active hostile enemy exists");
            Assert(!GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                    false, GiantFlightMode.TakeoffAndLanding, hasActiveHostileEnemy: false, isFlyingEnRouteFar: true,
                    airborneSustainedTicks: 300, minAirborneTicksBeforeAutoLand: 120, currentJob: plainGotoJob),
                "Biological flyer must remain airborne while actively flying long-distance en route");
            Assert(!GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                    false, GiantFlightMode.TakeoffAndLanding, hasActiveHostileEnemy: false, isFlyingEnRouteFar: false,
                    airborneSustainedTicks: 60, minAirborneTicksBeforeAutoLand: 120, currentJob: plainGotoJob),
                "Biological flyer must respect minimum airborne settle window before out-of-combat auto-landing");
            Assert(GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                    false, GiantFlightMode.TakeoffAndLanding, hasActiveHostileEnemy: false, isFlyingEnRouteFar: false,
                    airborneSustainedTicks: 150, minAirborneTicksBeforeAutoLand: 120, currentJob: plainGotoJob),
                "Biological TakeoffAndLanding flyer must auto-land once out of combat, settled, and not flying far en route");

            // Vehicles and AlwaysAirborne flyers must never trigger biological out-of-combat auto-landing
            Assert(!GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                    isVehiclePawn: true, GiantFlightMode.TakeoffAndLanding, hasActiveHostileEnemy: false, isFlyingEnRouteFar: false,
                    airborneSustainedTicks: 500, minAirborneTicksBeforeAutoLand: 120, currentJob: ingestJob),
                "Vehicle flyers must NEVER use biological out-of-combat auto-landing");
            Assert(!GiantFlightRuntime.ShouldBiologicalFlyerAutoLandOutOfCombat(
                    isVehiclePawn: false, GiantFlightMode.AlwaysAirborne, hasActiveHostileEnemy: false, isFlyingEnRouteFar: false,
                    airborneSustainedTicks: 500, minAirborneTicksBeforeAutoLand: 120, currentJob: ingestJob),
                "AlwaysAirborne flyers must NEVER auto-land");

            Console.WriteLine("       -> Verified PredatorHunt PartCombat prey bridge, hull-perimeter taming/training social patches, biological auto-landing & full animal ThinkTree");
        }

        private static void TestBiologicalGiantSleepBodyRotationCurlUp()
        {
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valsRig, _, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            Assert(rathRig != null, "Missing GCF_Rig_Rathalos");
            Assert(valsRig != null, "Missing GCF_Rig_Valstrax");

            foreach (GiantRigDef rig in new[] { rathRig, valsRig })
            {
                GiantSleepCurlProfile profile = GiantSleepCurlSolver.GetOrBuildProfile(rig);
                Assert(profile != null && profile.NodeCount == rig.SortedNodes.Length,
                    $"Failed to build GiantSleepCurlProfile for {rig.defName}");

                int antCount = 0, postCount = 0, tailCount = 0, wingCount = 0, legCount = 0;
                float antSum = 0f, postTailSum = 0f;
                for (int i = 0; i < profile.NodeCount; i++)
                {
                    switch (profile.Roles[i])
                    {
                        case GiantSleepBoneRole.AnteriorNeckHead:
                            antCount++;
                            antSum += profile.CurlAnglePlusSignDeg[i];
                            break;
                        case GiantSleepBoneRole.PosteriorTorso:
                            postCount++;
                            postTailSum += profile.CurlAnglePlusSignDeg[i];
                            break;
                        case GiantSleepBoneRole.Tail:
                            tailCount++;
                            postTailSum += profile.CurlAnglePlusSignDeg[i];
                            break;
                        case GiantSleepBoneRole.Wing:
                            wingCount++;
                            break;
                        case GiantSleepBoneRole.Leg:
                            legCount++;
                            Assert(Mathf.Abs(profile.CurlAnglePlusSignDeg[i]) <= 1e-6f,
                                $"{rig.defName} leg bone '{rig.SortedNodes[i].nodeId}' must have 0 horizontal curl angle");
                            break;
                    }
                }

                Assert(antCount >= 3 && antSum >= 85f,
                    $"{rig.defName} anterior neck/head curl must bend >= +85 deg (got count={antCount}, sum={antSum:F1})");
                Assert(postCount >= 1 && tailCount >= 6 && postTailSum <= -175f,
                    $"{rig.defName} posterior spine+tail curl must wrap <= -175 deg toward same flank (got post={postCount}, tail={tailCount}, sum={postTailSum:F1})");
                Assert(wingCount >= 6 && legCount >= 8,
                    $"{rig.defName} expected wings & legs classified (wings={wingCount}, legs={legCount})");

                // Jaw / mandible passive alignment check (must never receive independent neck curl yaw)
                for (int i = 0; i < profile.NodeCount; i++)
                {
                    string nid = (rig.SortedNodes[i].nodeId ?? string.Empty).ToLowerInvariant();
                    if (nid.Contains("jaw") || nid.Contains("mandible"))
                    {
                        Assert(profile.Roles[i] == GiantSleepBoneRole.RigidOrPassive && Mathf.Abs(profile.CurlAnglePlusSignDeg[i]) <= 1e-6f,
                            $"{rig.defName} jaw bone '{rig.SortedNodes[i].nodeId}' must be RigidOrPassive with 0 local curl yaw (got {profile.Roles[i]}, {profile.CurlAnglePlusSignDeg[i]:F2})");
                    }
                }

                int count = rig.SortedNodes.Length;
                var localPoses = new BoneLocalPose[count];
                var worldPoses = new BoneWorldPose[count];

                foreach (float sign in new[] { 1f, -1f })
                {
                    float targetSleepHeading = GiantSleepCurlSolver.GetTargetSleepHeadingDeg(rig, sign);
                    foreach (float prog in new[] { 0f, 0.25f, 0.5f, 0.75f, 1.0f })
                    {
                        foreach (float breathTick in new[] { 0f, 48f, 96f, 144f })
                        {
                            for (int i = 0; i < count; i++) localPoses[i] = BoneLocalPose.Identity;
                            GiantSleepCurlSolver.ApplySleepCurl(rig, localPoses, ReadOnlySpan<bool>.Empty, prog, sign, breathTick, includeBezierBones: true);

                            // Strict hard rule: ALL leg bones must maintain |angle| <= 1e-5f at all curl & breath phases
                            for (int i = 0; i < count; i++)
                            {
                                if (profile.Roles[i] == GiantSleepBoneRole.Leg)
                                {
                                    Assert(Mathf.Abs(localPoses[i].angle) <= 1e-5f,
                                        $"{rig.defName} leg bone '{rig.SortedNodes[i].nodeId}' violated zero-yaw rule: angle={localPoses[i].angle}");
                                }
                            }

                            float uTurn = GiantSleepCurlSolver.EaseInOutCubic(prog);
                            float heading = SkeletalKinematics.NormalizeAngle360(180f + Mathf.DeltaAngle(180f, targetSleepHeading) * uTurn);
                            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, heading, localPoses, ReadOnlySpan<bool>.Empty, worldPoses, 1f);
                            for (int i = 0; i < count; i++)
                            {
                                Matrix4x4 m = worldPoses[i].BuildRenderMatrix(0f);
                                Assert(Mathf.Abs(m.m30) < 1e-5f && Mathf.Abs(m.m31) < 1e-5f && Mathf.Abs(m.m32) < 1e-5f && Mathf.Abs(m.m33 - 1f) < 1e-5f && m.m11 > 0.05f,
                                    $"{rig.defName} bone {i} non-homogeneous or non-positive Y scale matrix during sleep curl");
                                float xzDet = m.m00 * m.m22 - m.m02 * m.m20;
                                Assert(xzDet > 0.05f,
                                    $"{rig.defName} bone {i} ('{rig.SortedNodes[i].nodeId}') degenerate XZ determinant {xzDet:F4} during sleep curl");
                            }
                        }
                    }

                    // At heading=0 and full curl=1, verify both snout and mid-tail shift toward +sign*X and coiled ring stays centered near (0,0)
                    for (int i = 0; i < count; i++) localPoses[i] = BoneLocalPose.Identity;
                    GiantSleepCurlSolver.ApplySleepCurl(rig, localPoses, ReadOnlySpan<bool>.Empty, 1f, sign, 0f, includeBezierBones: true);
                    SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, ReadOnlySpan<bool>.Empty, worldPoses, 1f);

                    float rootX = worldPoses[0].jointWorldXZ.x;
                    int skullIdx = Array.FindLastIndex(profile.Roles, r => r == GiantSleepBoneRole.AnteriorNeckHead);
                    int firstTailIdx = Array.FindIndex(profile.Roles, r => r == GiantSleepBoneRole.Tail);
                    int lastTailIdx = Array.FindLastIndex(profile.Roles, r => r == GiantSleepBoneRole.Tail);
                    int midTailIdx = (firstTailIdx + lastTailIdx) / 2;
                    Assert((worldPoses[skullIdx].jointWorldXZ.x - rootX) * sign > 1.2f,
                        $"{rig.defName} skull failed to curl toward sign={sign} flank");
                    Assert((worldPoses[midTailIdx].jointWorldXZ.x - rootX) * sign > 1.3f &&
                           (worldPoses[lastTailIdx].jointWorldXZ.x - rootX) * sign > 1.0f,
                        $"{rig.defName} tail failed to curl toward same sign={sign} flank as skull");

                    float minX = float.MaxValue, maxX = float.MinValue, minZ = float.MaxValue, maxZ = float.MinValue;
                    for (int i = 0; i < count; i++)
                    {
                        if (profile.Roles[i] is GiantSleepBoneRole.Root or GiantSleepBoneRole.AnteriorNeckHead or GiantSleepBoneRole.PosteriorTorso or GiantSleepBoneRole.Tail)
                        {
                            Vector2 j = worldPoses[i].jointWorldXZ;
                            if (j.x < minX) minX = j.x;
                            if (j.x > maxX) maxX = j.x;
                            if (j.y < minZ) minZ = j.y;
                            if (j.y > maxZ) maxZ = j.y;
                        }
                    }
                    Vector2 mid = new Vector2((minX + maxX) * 0.5f, (minZ + maxZ) * 0.5f);
                    Assert(mid.magnitude <= 1.25f,
                        $"{rig.defName} coiled sleep ring center drifted too far from DrawPos (0,0): {mid}");

                    // Verify dorsal wing fold shrinks lateral wingspan by >= 38% compared to flat bind pose
                    var bindWorld = new BoneWorldPose[count];
                    SkeletalKinematics.SolveFlatBindPoses(rig, bindWorld);
                    float bindWingMinX = float.MaxValue, bindWingMaxX = float.MinValue;
                    float curlWingMinX = float.MaxValue, curlWingMaxX = float.MinValue;
                    for (int i = 0; i < count; i++)
                    {
                        if (profile.Roles[i] == GiantSleepBoneRole.Wing)
                        {
                            float bx = bindWorld[i].flatQuadCenterWorldXZ.x;
                            if (bx < bindWingMinX) bindWingMinX = bx;
                            if (bx > bindWingMaxX) bindWingMaxX = bx;
                            float cx = worldPoses[i].quadCenterWorldXZ.x - worldPoses[0].jointWorldXZ.x;
                            if (cx < curlWingMinX) curlWingMinX = cx;
                            if (cx > curlWingMaxX) curlWingMaxX = cx;
                        }
                    }
                    float bindWingSpan = bindWingMaxX - bindWingMinX;
                    float curlWingSpan = curlWingMaxX - curlWingMinX;
                    Assert(bindWingSpan > 4f && curlWingSpan <= bindWingSpan * 0.62f,
                        $"{rig.defName} dorsal wing tuck insufficient: bindSpan={bindWingSpan:F2}, curlSpan={curlWingSpan:F2}");

                    // Verify unified top-body (+Z North) / bottom-gap (-Z South) world orientation at TargetSleepHeadingDeg
                    SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, targetSleepHeading, localPoses, ReadOnlySpan<bool>.Empty, worldPoses, 1f);
                    Vector2 dorsalSum = Vector2.zero;
                    int dorsalN = 0;
                    for (int i = 0; i < count; i++)
                    {
                        if (profile.Roles[i] == GiantSleepBoneRole.Root || profile.Roles[i] == GiantSleepBoneRole.PosteriorTorso
                            || (profile.Roles[i] == GiantSleepBoneRole.AnteriorNeckHead && profile.RoleDepth[i] == 0))
                        {
                            dorsalSum += worldPoses[i].jointWorldXZ;
                            dorsalN++;
                        }
                    }
                    Vector2 dorsalWorldXZ = dorsalSum / Mathf.Max(1, dorsalN);
                    Vector2 gapMidWorldXZ = 0.5f * (worldPoses[skullIdx].quadCenterWorldXZ + worldPoses[lastTailIdx].quadCenterWorldXZ);
                    Vector2 bodyToGapWorld = gapMidWorldXZ - dorsalWorldXZ;
                    Assert(dorsalWorldXZ.y > 0.35f && gapMidWorldXZ.y < dorsalWorldXZ.y - 1.2f && Mathf.Abs(bodyToGapWorld.x) <= 0.15f,
                        $"{rig.defName} (sign={sign}) failed top-arch/bottom-gap alignment at heading={targetSleepHeading:F1}: dorsal={dorsalWorldXZ}, gapMid={gapMidWorldXZ}");

                    if (sign > 0f)
                    {
                        Console.WriteLine($"       -> {rig.defName}: antCurl={antSum:F1}deg, postTailCurl={postTailSum:F1}deg, targetH={targetSleepHeading:F1}deg, dorsalZ={dorsalWorldXZ.y:F2}, gapZ={gapMidWorldXZ.y:F2}, wingSpan={bindWingSpan:F2}->{curlWingSpan:F2}");
                    }
                }

                // Verify ChooseBestSleepSideSign always picks the shortest turn (<= 125 deg) from any starting cardinal heading
                foreach (float startH in new[] { 0f, 90f, 180f, 270f })
                {
                    float bestSign = GiantSleepCurlSolver.ChooseBestSleepSideSign(rig, startH);
                    float bestTargetH = GiantSleepCurlSolver.GetTargetSleepHeadingDeg(rig, bestSign);
                    Assert(Mathf.Abs(Mathf.DeltaAngle(startH, bestTargetH)) <= 125f,
                        $"{rig.defName} excessive sleep turn from {startH:F0} to {bestTargetH:F1} deg");
                }
            }

            Console.WriteLine("       -> Verified unified top-arch (+Z) / bottom-gap (-Z) sleep curl, jaw alignment, dorsal wing tuck & strict 0-deg leg yaw");
        }

        private static void TestBiologicalGiantSimpleDailyActivityPoses()
        {
            // 1. Pure classifier verification (Ingest, PredatorHunt Corpse vs live Pawn, Nuzzle, ForceWait humanlike, external Tame/Train, Nuzzle linger & strict isolation)
            var ingestJob = new Verse.AI.Job { def = new JobDef { defName = "Ingest" } };
            var livePrey = new Pawn { thingIDNumber = 8801, def = new ThingDef { defName = "Deer", race = new RaceProperties { intelligence = Intelligence.Animal } } };
            var deadCorpse = new Corpse { def = new ThingDef { defName = "Corpse_Deer" } };
            var huntLiveJob = new Verse.AI.Job { def = new JobDef { defName = "PredatorHunt" }, targetA = new LocalTargetInfo(livePrey) };
            var huntCorpseJob = new Verse.AI.Job { def = new JobDef { defName = "PredatorHunt" }, targetA = new LocalTargetInfo(deadCorpse) };
            var nuzzleJob = new Verse.AI.Job { def = new JobDef { defName = "Nuzzle" } };
            var handler = new Pawn { thingIDNumber = 8802, def = new ThingDef { defName = "Human", race = new RaceProperties { intelligence = Intelligence.Humanlike } } };
            var forceWaitJob = new Verse.AI.Job { def = new JobDef { defName = "Wait" }, targetB = new LocalTargetInfo(handler) };
            var plainWaitJob = new Verse.AI.Job { def = new JobDef { defName = "Wait_Wander" } };

            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, ingestJob, false, false) == GiantDailyActivityKind.Ingesting,
                "Expected Ingesting for stationary biological Ingest job");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, huntCorpseJob, false, false) == GiantDailyActivityKind.Ingesting,
                "Expected Ingesting for stationary PredatorHunt on Corpse");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, huntLiveJob, false, false) == GiantDailyActivityKind.None,
                "PredatorHunt targeting live prey must NOT trigger Ingesting pose");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, nuzzleJob, false, false) == GiantDailyActivityKind.SocialAffection,
                "Expected SocialAffection for stationary Nuzzle job");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, forceWaitJob, false, false) == GiantDailyActivityKind.SocialAffection,
                "Expected SocialAffection for ForceWait targeting humanlike handler");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, plainWaitJob, true, false) == GiantDailyActivityKind.SocialAffection,
                "Expected SocialAffection when external colonist is actively Taming/Training");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, plainWaitJob, false, true) == GiantDailyActivityKind.SocialAffection,
                "Expected SocialAffection during post-Nuzzle stationary linger");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, false, plainWaitJob, false, false) == GiantDailyActivityKind.None,
                "Plain Wait_Wander without trainer or linger must remain None");

            // Strict isolation: vehicle, mechanoid, dead/downed, drafted, airborne, moving, sleeping, or combat/morph must return None
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(true, false, false, false, false, false, false, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Vehicle must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, true, false, false, false, false, false, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Mechanoid must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, true, false, false, false, false, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Dead/Downed must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, true, false, false, false, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Drafted must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, true, false, false, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Airborne must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, true, false, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Moving must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, true, false, ingestJob, true, true) == GiantDailyActivityKind.None, "Sleeping/Curling must never run daily biological poses");
            Assert(GiantDailyActivityPoseSolver.ResolveActivityKind(false, false, false, false, false, false, false, true, ingestJob, true, true) == GiantDailyActivityKind.None, "Combat/Morph state must never run daily biological poses");

            // 2. Kinematic pose & GPU render matrix verification on Rathalos (44-bone LBS skinned), Valstrax (46-bone 6-limb LBS), & AbyssalDragonBeast (32-node + Bezier tail)
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valsRig, _, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");

            foreach (GiantRigDef rig in new[] { rathRig, valsRig })
            {
                GiantSleepCurlProfile profile = GiantSleepCurlSolver.GetOrBuildProfile(rig);
                int count = rig.SortedNodes.Length;
                var localPoses = new BoneLocalPose[count];
                var worldPoses = new BoneWorldPose[count];
                var bindWorld = new BoneWorldPose[count];
                var restWorld = new BoneWorldPose[count];
                SkeletalKinematics.SolveFlatBindPoses(rig, bindWorld);
                for (int i = 0; i < count; i++) localPoses[i] = BoneLocalPose.Identity;
                SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, ReadOnlySpan<bool>.Empty, restWorld, 1f);

                int skullIdx = Array.FindLastIndex(profile.Roles, r => r == GiantSleepBoneRole.AnteriorNeckHead);
                int lastTailIdx = Array.FindLastIndex(profile.Roles, r => r == GiantSleepBoneRole.Tail);
                float bindSkullZ = restWorld[skullIdx].jointWorldXZ.y;

                // A) Ingesting cycle sweep (0..56 ticks) — STRICT NECK + HEAD ONLY (zero pelvis/tail/wing/leg motion)
                float maxIngestSnoutForwardDelta = 0f;
                float minIngestSkullX = float.MaxValue, maxIngestSkullX = float.MinValue;
                float maxNonNeckShiftIngest = 0f;

                for (int t = 0; t <= 56; t += 2)
                {
                    for (int i = 0; i < count; i++) localPoses[i] = BoneLocalPose.Identity;
                    bool hasBeziers = rig.bezierChains != null && rig.bezierChains.Count > 0;
                    GiantDailyActivityPoseSolver.ApplyDailyActivity(rig, localPoses, ReadOnlySpan<bool>.Empty, 1f, 0f, t, includeBezierBones: !hasBeziers);
                    if (hasBeziers)
                    {
                        GiantDailyActivityPoseSolver.ApplyDailyActivityToBezierBones(rig, localPoses, ReadOnlySpan<bool>.Empty, 1f, 0f, t);
                    }

                    for (int i = 0; i < count; i++)
                    {
                        if (profile.Roles[i] == GiantSleepBoneRole.Leg)
                        {
                            Assert(Mathf.Abs(localPoses[i].angle) <= 1e-5f,
                                $"{rig.defName} leg '{rig.SortedNodes[i].nodeId}' violated zero-yaw rule during Ingest at t={t}: angle={localPoses[i].angle}");
                        }
                        if (profile.Roles[i] is GiantSleepBoneRole.Root or GiantSleepBoneRole.PosteriorTorso or GiantSleepBoneRole.Tail or GiantSleepBoneRole.Wing)
                        {
                            Assert(Mathf.Abs(localPoses[i].angle) <= 1e-5f && localPoses[i].offset.sqrMagnitude <= 1e-8f,
                                $"{rig.defName} non-neck bone '{rig.SortedNodes[i].nodeId}' ({profile.Roles[i]}) moved during Ingest at t={t}");
                        }
                    }

                    SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, ReadOnlySpan<bool>.Empty, worldPoses, 1f);
                    for (int i = 0; i < count; i++)
                    {
                        Matrix4x4 m = worldPoses[i].BuildRenderMatrix(0f);
                        Assert(Mathf.Abs(m.m30) < 1e-5f && Mathf.Abs(m.m31) < 1e-5f && Mathf.Abs(m.m32) < 1e-5f && Mathf.Abs(m.m33 - 1f) < 1e-5f && m.m11 > 0.05f,
                            $"{rig.defName} bone {i} non-homogeneous matrix during Ingest");
                        Assert((m.m00 * m.m22 - m.m02 * m.m20) > 0.05f,
                            $"{rig.defName} bone {i} degenerate XZ determinant during Ingest");

                        if (profile.Roles[i] is GiantSleepBoneRole.Root or GiantSleepBoneRole.PosteriorTorso or GiantSleepBoneRole.Tail or GiantSleepBoneRole.Leg or GiantSleepBoneRole.Wing)
                        {
                            float shift = Vector2.Distance(worldPoses[i].jointWorldXZ, restWorld[i].jointWorldXZ);
                            if (shift > maxNonNeckShiftIngest) maxNonNeckShiftIngest = shift;
                        }
                    }

                    float fwdDelta = worldPoses[skullIdx].jointWorldXZ.y - bindSkullZ;
                    if (fwdDelta > maxIngestSnoutForwardDelta) maxIngestSnoutForwardDelta = fwdDelta;
                    float sx = worldPoses[skullIdx].jointWorldXZ.x;
                    if (sx < minIngestSkullX) minIngestSkullX = sx;
                    if (sx > maxIngestSkullX) maxIngestSkullX = sx;
                }

                bool anyNeckHasSagittal = false;
                for (int i = 0; i < count; i++)
                {
                    if (profile.Roles[i] == GiantSleepBoneRole.AnteriorNeckHead && profile.HasSagittalTarget[i])
                    {
                        anyNeckHasSagittal = true;
                        break;
                    }
                }
                float ingestSkullLateralSpan = maxIngestSkullX - minIngestSkullX;
                if (anyNeckHasSagittal)
                {
                    Assert(maxIngestSnoutForwardDelta >= 0.45f,
                        $"{rig.defName} Ingest snout forward peck reach too small: {maxIngestSnoutForwardDelta:F2}");
                }
                Assert(ingestSkullLateralSpan >= 0.45f,
                    $"{rig.defName} Ingest alternating tear lateral span too small: {ingestSkullLateralSpan:F2}");
                Assert(maxNonNeckShiftIngest <= 1e-4f,
                    $"{rig.defName} Ingest caused pelvis/hindquarter/tail shift: {maxNonNeckShiftIngest:F4}");

                // B) SocialAffection cycle sweep (0..144 ticks) — STRICT NECK + HEAD ONLY (zero pelvis/tail/wing/leg motion)
                float minSocialSkullX = float.MaxValue, maxSocialSkullX = float.MinValue;
                float maxNonNeckShiftSocial = 0f;

                for (int t = 0; t <= 144; t += 3)
                {
                    for (int i = 0; i < count; i++) localPoses[i] = BoneLocalPose.Identity;
                    bool hasBeziers = rig.bezierChains != null && rig.bezierChains.Count > 0;
                    GiantDailyActivityPoseSolver.ApplyDailyActivity(rig, localPoses, ReadOnlySpan<bool>.Empty, 0f, 1f, t, includeBezierBones: !hasBeziers);
                    if (hasBeziers)
                    {
                        GiantDailyActivityPoseSolver.ApplyDailyActivityToBezierBones(rig, localPoses, ReadOnlySpan<bool>.Empty, 0f, 1f, t);
                    }

                    for (int i = 0; i < count; i++)
                    {
                        if (profile.Roles[i] == GiantSleepBoneRole.Leg)
                        {
                            Assert(Mathf.Abs(localPoses[i].angle) <= 1e-5f,
                                $"{rig.defName} leg '{rig.SortedNodes[i].nodeId}' violated zero-yaw rule during SocialAffection at t={t}: angle={localPoses[i].angle}");
                        }
                        if (profile.Roles[i] is GiantSleepBoneRole.Root or GiantSleepBoneRole.PosteriorTorso or GiantSleepBoneRole.Tail or GiantSleepBoneRole.Wing)
                        {
                            Assert(Mathf.Abs(localPoses[i].angle) <= 1e-5f && localPoses[i].offset.sqrMagnitude <= 1e-8f,
                                $"{rig.defName} non-neck bone '{rig.SortedNodes[i].nodeId}' ({profile.Roles[i]}) moved during SocialAffection at t={t}");
                        }
                    }

                    SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, localPoses, ReadOnlySpan<bool>.Empty, worldPoses, 1f);
                    for (int i = 0; i < count; i++)
                    {
                        Matrix4x4 m = worldPoses[i].BuildRenderMatrix(0f);
                        Assert(Mathf.Abs(m.m30) < 1e-5f && Mathf.Abs(m.m31) < 1e-5f && Mathf.Abs(m.m32) < 1e-5f && Mathf.Abs(m.m33 - 1f) < 1e-5f && m.m11 > 0.05f,
                            $"{rig.defName} bone {i} non-homogeneous matrix during SocialAffection");
                        Assert((m.m00 * m.m22 - m.m02 * m.m20) > 0.05f,
                            $"{rig.defName} bone {i} degenerate XZ determinant during SocialAffection");

                        if (profile.Roles[i] is GiantSleepBoneRole.Root or GiantSleepBoneRole.PosteriorTorso or GiantSleepBoneRole.Tail or GiantSleepBoneRole.Leg or GiantSleepBoneRole.Wing)
                        {
                            float shift = Vector2.Distance(worldPoses[i].jointWorldXZ, restWorld[i].jointWorldXZ);
                            if (shift > maxNonNeckShiftSocial) maxNonNeckShiftSocial = shift;
                        }
                    }

                    float sx = worldPoses[skullIdx].jointWorldXZ.x;
                    if (sx < minSocialSkullX) minSocialSkullX = sx;
                    if (sx > maxSocialSkullX) maxSocialSkullX = sx;
                }

                float socialSkullRubSpan = maxSocialSkullX - minSocialSkullX;
                Assert(socialSkullRubSpan >= 0.70f,
                    $"{rig.defName} SocialAffection affectionate head-rub lateral span too small: {socialSkullRubSpan:F2}");
                Assert(maxNonNeckShiftSocial <= 1e-4f,
                    $"{rig.defName} SocialAffection caused pelvis/hindquarter/tail shift: {maxNonNeckShiftSocial:F4}");

                Console.WriteLine($"       -> {rig.defName}: ingestFwd={maxIngestSnoutForwardDelta:F2}c, ingestTearSpan={ingestSkullLateralSpan:F2}c, socialRubSpan={socialSkullRubSpan:F2}c, pelvisTailShift={Mathf.Max(maxNonNeckShiftIngest, maxNonNeckShiftSocial):F4}c (maxLegYaw=0.000deg)");
            }

            Console.WriteLine("       -> Verified Ingest peck/tear & SocialAffection head-rub/tail-wag poses, strict 0-deg leg yaw & vehicle/mech isolation");
        }

        private static void TestFlightGroundShadowForwardOrientationAlignment()
        {
            // 1. ShaderDef flipTextureST & Clamp invariant across all sprite-sampling vs procedural shaders
            string vfxShaderXml = ResolveMod17Path("Defs", "ShaderDefs", "ShaderDefs_GiantVfx.xml");
            string mechShaderXml = ResolveMod17Path("Defs", "ShaderDefs", "ShaderDefs_MechColossus.xml");
            XDocument vfxDoc = XDocument.Load(vfxShaderXml);
            XDocument mechDoc = XDocument.Load(mechShaderXml);

            XElement dropShadowProg = vfxDoc.Root!.Elements("ShaderDef")
                .First(e => e.Element("defName")?.Value == "GCF_GiantDropShadow")
                .Element("shaderProgram")!;
            bool flipDropShadow = string.Equals(dropShadowProg.Element("flipTextureST")?.Value, "true", StringComparison.OrdinalIgnoreCase);
            Assert(flipDropShadow, "GCF_GiantDropShadow MUST set <flipTextureST>true</flipTextureST> so sprite top (v_tex=0) maps to +Z anterior");

            XElement mechBoneProg = mechDoc.Root!.Elements("ShaderDef")
                .First(e => e.Element("defName")?.Value == "GCF_MechReactorBone")
                .Element("shaderProgram")!;
            Assert(string.Equals(mechBoneProg.Element("flipTextureST")?.Value, "true", StringComparison.OrdinalIgnoreCase),
                "GCF_MechReactorBone MUST keep <flipTextureST>true</flipTextureST>");

            XElement uberProg = vfxDoc.Root!.Elements("ShaderDef")
                .First(e => e.Element("defName")?.Value == "GCF_RimfxUberVfx")
                .Element("shaderProgram")!;
            Assert(string.Equals(uberProg.Element("flipTextureST")?.Value, "false", StringComparison.OrdinalIgnoreCase),
                "Procedural GCF_RimfxUberVfx MUST keep <flipTextureST>false</flipTextureST>");

            // Exact GPU vertex+fragment mapping of MeshPool.plane10 + BuildRenderMatrix + SceneDefault.vert.glsl + GCF_GiantDropShadow.frag.glsl:
            // RimWorld Vulkan sets _MainTex_ST = (0, 1, 1, -1) when flipTextureST == true:
            //   tex_uv = vUv * (1, -1) + (0, 1) => vUv = (u_tex, 1 - v_tex)
            // On MeshPool.plane10, local vertex for vUv is (vUv.x - 0.5, 0, vUv.y - 0.5) = (u_tex - 0.5, 0, 0.5 - v_tex).
            static Vector2 ProjectShadowTexelGpu(in BoneWorldPose shadowPose, float uTex, float vTex, bool shaderFlipST)
            {
                float vUvY = shaderFlipST ? (1f - vTex) : vTex;
                Vector3 plane10Local = new Vector3(uTex - 0.5f, 0f, vUvY - 0.5f);
                Matrix4x4 m = shadowPose.BuildRenderMatrix(0f);
                Vector3 w = m.MultiplyPoint3x4(plane10Local);
                return new Vector2(w.x, w.z);
            }

            // 2. Verify UVToWorldXZ == GPU shadow texel projection across all flying rigs & 8 headings
            var (valsRig, _, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            var (rathRig, _, rathAnims) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (carrRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            var (colRig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");

            float[] headings = { 0f, 45f, 90f, 135f, 180f, 225f, 270f, 315f };
            Vector2 shadowOrigin = new Vector2(128.35f, 96.65f);
            const float shadowScale = 0.68f;

            foreach (GiantRigDef rig in new[] { valsRig, rathRig, carrRig, colRig })
            {
                int n = rig.SortedNodes.Length;
                var locals = new BoneLocalPose[n];
                var shadowPoses = new BoneWorldPose[n];
                for (int i = 0; i < n; i++) locals[i] = BoneLocalPose.Identity;

                foreach (float hdg in headings)
                {
                    SkeletalKinematics.SolveWorldPoses(rig, shadowOrigin, hdg, locals, ReadOnlySpan<bool>.Empty, shadowPoses, shadowScale);
                    for (int i = 0; i < n; i++)
                    {
                        if (!shadowPoses[i].visible) continue;
                        foreach ((float u, float v) in new[] { (0.5f, 0.1f), (0.5f, 0.9f), (0.2f, 0.5f), (0.8f, 0.5f) })
                        {
                            Vector2 gpuPt = ProjectShadowTexelGpu(in shadowPoses[i], u, v, flipDropShadow);
                            Vector2 kinPt = shadowPoses[i].UVToWorldXZ(u, 1f - v);
                            float err = Vector2.Distance(gpuPt, kinPt);
                            Assert(err < 1e-4f,
                                $"{rig.defName} bone '{rig.SortedNodes[i].nodeId}' shadow GPU texel mismatch at hdg={hdg}: err={err:F6}");
                        }
                    }
                }
            }

            // 4. Rathalos Flight head snout forward check across all 8 headings
            GiantAnimDef rathFlight = rathAnims.Values.First(a => a.defName.IndexOf("Flight", StringComparison.OrdinalIgnoreCase) >= 0
                || a.defName.IndexOf("Fly", StringComparison.OrdinalIgnoreCase) >= 0);
            int rathSkullIdx = Array.FindIndex(rathRig.SortedNodes, b => b.nodeId.IndexOf("skull", StringComparison.OrdinalIgnoreCase) >= 0
                || b.nodeId.IndexOf("head", StringComparison.OrdinalIgnoreCase) >= 0);
            Assert(rathSkullIdx >= 0, "Could not locate Rathalos head/skull bone");
            var rathLocal = new BoneLocalPose[rathRig.SortedNodes.Length];
            var rathShadow = new BoneWorldPose[rathRig.SortedNodes.Length];
            foreach (float hdg in headings)
            {
                float rad = hdg * Mathf.Deg2Rad;
                Vector2 fwd = new Vector2(Mathf.Sin(rad), Mathf.Cos(rad));
                for (int i = 0; i < rathRig.SortedNodes.Length; i++) rathLocal[i] = BoneLocalPose.Identity;
                rathFlight.EvaluateInto(rathRig, 6f, rathLocal);
                SkeletalKinematics.SolveWorldPoses(rathRig, shadowOrigin, hdg, rathLocal, ReadOnlySpan<bool>.Empty, rathShadow, shadowScale);
                Vector2 rSnout = ProjectShadowTexelGpu(in rathShadow[rathSkullIdx], 0.5f, 0.10f, flipDropShadow);
                Vector2 rBase = ProjectShadowTexelGpu(in rathShadow[rathSkullIdx], 0.5f, 0.88f, flipDropShadow);
                Assert(Vector2.Dot(rSnout - rBase, fwd) > 0.40f * shadowScale,
                    $"Rathalos shadow head inverted at hdg={hdg}");
            }

            Console.WriteLine("       -> Verified flipTextureST=true + Clamp shadow orientation across 4 flying rigs & 8 headings");
        }

        private static void TestSeveredPartFallingDebrisPhysicsSubtreeAndSkinnedSnapshot()
        {
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml");
            BoneNodeDef[] nodes = rathRig.SortedNodes;

            // 1. Subtree detachment root partitioning:
            //    (a) tail_seg1..6 -> 1 single cohesive falling tail cluster
            int[] tailIds = new[] { "tail_seg1", "tail_seg2", "tail_seg3", "tail_seg4", "tail_seg5", "tail_seg6" }
                .Select(id => { Assert(rathRig.TryGetNodeIndex(id, out int idx), $"Missing {id}"); return idx; })
                .ToArray();
            List<List<int>> tailGroups = GiantSeveredDebrisSystem.PartitionDetachmentRoots(nodes, tailIds);
            Assert(tailGroups.Count == 1 && tailGroups[0].Count == 6 && tailGroups[0][0] == tailIds[0],
                $"Severed tail_seg1..6 must group into 1 cluster rooted at tail_seg1, got groups={tailGroups.Count}");

            //    (b) wing_outer_fan_right + wing_costal_crest_right -> 1 single cluster
            Assert(rathRig.TryGetNodeIndex("wing_outer_fan_right", out int wOutR), "Missing wing_outer_fan_right");
            Assert(rathRig.TryGetNodeIndex("wing_costal_crest_right", out int wCrestR), "Missing wing_costal_crest_right");
            List<List<int>> outerGroups = GiantSeveredDebrisSystem.PartitionDetachmentRoots(nodes, new[] { wOutR, wCrestR });
            Assert(outerGroups.Count == 1 && outerGroups[0].Count == 2 && outerGroups[0][0] == wOutR,
                $"wing_outer_fan_right + wing_costal_crest_right must group into 1 cluster, got {outerGroups.Count}");

            //    (c) Simultaneous 3-part sever (wing_forearm_right+thumb, shin_left+foot+talon, horn_left) -> 3 independent clusters
            int[] multiIds = new[]
            {
                "wing_forearm_right", "wing_thumb_claw_right",
                "shin_left", "ankle_left", "talon_left",
                "horn_left"
            }.Where(id => rathRig.TryGetNodeIndex(id, out _))
             .Select(id => { rathRig.TryGetNodeIndex(id, out int idx); return idx; })
             .ToArray();
            List<List<int>> multiGroups = GiantSeveredDebrisSystem.PartitionDetachmentRoots(nodes, multiIds);
            Assert(multiGroups.Count == 3, $"Simultaneous forearm + hindleg + horn sever must produce 3 clusters, got {multiGroups.Count}");

            // 2. Skinned-mesh detached complement snapshot (pure read-only, exact pre-sever geometry, zero live mutation)
            var rathSilMasks = new TextureAlphaMask[nodes.Length];
            for (int i = 0; i < nodes.Length; i++)
            {
                string silPath = nodes[i].silhouetteTexPath;
                if (!string.IsNullOrEmpty(silPath))
                {
                    string absSil = ResolveMod17Path("Textures", silPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                    if (File.Exists(absSil))
                    {
                        rathSilMasks[i] = TextureAlphaMask.FromPngBytes(File.ReadAllBytes(absSil), (byte)25);
                    }
                }
            }

            GiantSkinnedMeshDef wingMemRDef = rathRig.skinnedMeshes.First(s => s.meshId == "Wing_Membrane_Right");
            GiantSkinnedMeshDef dorsalDef = rathRig.skinnedMeshes.First(s => s.meshId == "Dorsal_Body");
            var wingRt = new SkinnedMeshRuntime(rathRig, wingMemRDef);
            var dorsalRt = new SkinnedMeshRuntime(rathRig, dorsalDef);

            string wmMaskPath = ResolveMod17Path("Textures", wingMemRDef.silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
            string dbMaskPath = ResolveMod17Path("Textures", dorsalDef.silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
            wingRt.EnsureBindTopology(TextureAlphaMask.FromPngBytes(File.ReadAllBytes(wmMaskPath), (byte)25), rathMasks, rathSilMasks);
            dorsalRt.EnsureBindTopology(TextureAlphaMask.FromPngBytes(File.ReadAllBytes(dbMaskPath), (byte)25), rathMasks, rathSilMasks);

            var poses = new BoneWorldPose[nodes.Length];
            var localZero = new BoneLocalPose[nodes.Length];
            for (int i = 0; i < nodes.Length; i++) localZero[i] = BoneLocalPose.Identity;
            SkeletalKinematics.SolveWorldPoses(rathRig, Vector2.zero, 90f, localZero, ReadOnlySpan<bool>.Empty, poses);

            wingRt.EvaluateDeformedVertices(poses, Vector2.zero, false, out _);
            int liveWingTrisBefore = wingRt.ActiveTriangleCount;
            ulong liveWingMaskBefore = wingRt.CurrentVisibleMemberMask;

            int outBit = Array.IndexOf(wingMemRDef.resolvedMemberBoneIndices, wOutR);
            Assert(outBit >= 0, "wing_outer_fan_right must be member of Wing_Membrane_Right");
            bool okPartial = wingRt.TryExtractDetachedMeshSnapshot(
                poses, new Vector2(50f, 50f), 1UL << outBit,
                out Vector2[] wVerts, out Vector2[] wUVs, out int[] wTris,
                out Vector2 wMin, out Vector2 wMax, out bool isFullPartial);
            Assert(okPartial && !isFullPartial && wTris.Length >= 30 && wVerts.Length == wUVs.Length,
                $"Partial outer wing snapshot failed: ok={okPartial}, full={isFullPartial}, tris={wTris.Length}");
            Assert(wingRt.ActiveTriangleCount == liveWingTrisBefore && wingRt.CurrentVisibleMemberMask == liveWingMaskBefore,
                "TryExtractDetachedMeshSnapshot must NEVER mutate live SkinnedMeshRuntime state");

            ulong allWingMask = (1UL << wingMemRDef.resolvedMemberBoneIndices.Length) - 1UL;
            bool okFull = wingRt.TryExtractDetachedMeshSnapshot(
                poses, new Vector2(50f, 50f), allWingMask,
                out Vector2[] fullVerts, out _, out int[] fullTris, out _, out _, out bool isFullAll);
            Assert(okFull && isFullAll && fullTris.Length > wTris.Length,
                $"Full Wing_Membrane_Right snapshot failed: ok={okFull}, isFull={isFullAll}, fullTris={fullTris.Length}");

            ulong tailMask = 0UL;
            for (int mb = 0; mb < dorsalDef.resolvedMemberBoneIndices.Length; mb++)
            {
                if (Array.IndexOf(tailIds, dorsalDef.resolvedMemberBoneIndices[mb]) >= 0)
                {
                    tailMask |= 1UL << mb;
                }
            }
            bool okTail = dorsalRt.TryExtractDetachedMeshSnapshot(
                poses, new Vector2(50f, 50f), tailMask,
                out Vector2[] tVerts, out _, out int[] tTris, out Vector2 tMin, out Vector2 tMax, out bool tailIsFull);
            Assert(okTail && !tailIsFull && tTris.Length >= 60 && (tMax.x - tMin.x) > 3.5f,
                $"Detached tail snapshot invalid: ok={okTail}, tris={tTris.Length}, spanX={tMax.x - tMin.x:F2}");

            // 3. Ballistic 2.5D fall, bounce, impact, settle, corpse tint & fade-out across all 3 categories + airborne launch
            SeveredDebrisProfile bioGround = GiantSeveredDebrisSystem.ComputeDebrisProfile(GiantSeverVfxKind.FleshSever, 2.2f, 0f, 101);
            SeveredDebrisProfile bioAir = GiantSeveredDebrisSystem.ComputeDebrisProfile(GiantSeverVfxKind.FleshSever, 2.2f, 1.0f, 101);
            SeveredDebrisProfile mechProf = GiantSeveredDebrisSystem.ComputeDebrisProfile(GiantSeverVfxKind.MechExplosion, 1.8f, 0f, 202);
            SeveredDebrisProfile voidProf = GiantSeveredDebrisSystem.ComputeDebrisProfile(GiantSeverVfxKind.VoidRupture, 2.0f, 0f, 303);

            Assert(bioAir.startHeight > bioGround.startHeight + 2.5f,
                $"Airborne severed part must launch much higher than grounded: air={bioAir.startHeight:F2}, ground={bioGround.startHeight:F2}");
            Assert(mechProf.maxBounces == 2 && bioGround.maxBounces == 1,
                $"MechExplosion must bounce twice while FleshSever bounces once: mech={mechProf.maxBounces}, bio={bioGround.maxBounces}");

            void SimulateAndVerify(string label, SeveredDebrisProfile prof, GiantSeverVfxKind kind, bool isSolid)
            {
                Vector2 visualOrigin = new Vector2(60f, 60f);
                var inst = new SeveredDebrisInstance
                {
                    GroundPosXZ = new Vector2(visualOrigin.x, visualOrigin.y - prof.startHeight * SeveredDebrisInstance.HeightVisualShiftZFactor),
                    VelXZ = new Vector2(prof.outwardSpeed, 0.35f),
                    Height = prof.startHeight,
                    LaunchHeightBaseline = prof.startHeight,
                    VelY = prof.upwardVel,
                    AngleDeg = 0f,
                    AngularVelDeg = prof.angularVelDeg,
                    Gravity = prof.gravity,
                    Restitution = prof.restitution,
                    MaxBounces = prof.maxBounces,
                    ApproxRadius = 2.0f,
                    IsSolidOrMech = isSolid,
                    Kind = kind,
                    RestDurationTicks = 90,
                    FadeDurationTicks = 30
                };

                // t=0 exact visual position & scale continuity (0.0 px pop)
                Assert(Vector2.Distance(inst.ComputeVisualWorldXZ(), visualOrigin) < 1e-4f,
                    $"{label}: t=0 visual position must match exact pre-sever origin");
                AssertNear(inst.ComputeVisualScale(), 1.0f, 1e-4f, $"{label}: t=0 visual scale must be 1.0");

                float peakHeight = inst.Height;
                int firstImpactCount = 0;
                int bounceCountSeen = 0;
                int guard = 0;
                while (!inst.IsExpired && guard++ < 800)
                {
                    inst.StepTick(out bool firstImp, out bool bounceImp);
                    if (inst.Height > peakHeight) peakHeight = inst.Height;
                    if (firstImp) firstImpactCount++;
                    if (bounceImp) bounceCountSeen++;
                    Assert(inst.Height >= 0f && !float.IsNaN(inst.GroundPosXZ.x) && !float.IsNaN(inst.AngleDeg),
                        $"{label}: invalid state at tick {inst.ElapsedTicks}");
                }

                Assert(peakHeight > prof.startHeight + 0.25f, $"{label}: part must arc upward before falling (peak={peakHeight:F2})");
                Assert(firstImpactCount == 1, $"{label}: first touchdown callback must fire exactly once (got {firstImpactCount})");
                Assert(inst.BounceCount >= 1 && inst.BounceCount <= prof.maxBounces, $"{label}: expected 1..{prof.maxBounces} bounces, got {inst.BounceCount}");
                Assert(inst.IsSettled && inst.IsExpired, $"{label}: must settle on ground and expire cleanly after rest+fade");
                AssertNear(inst.ComputeFadeAlpha(), 0f, 1e-4f, $"{label}: final alpha after fade must reach 0");
                Assert(Vector2.Distance(inst.GroundPosXZ, visualOrigin) > 0.6f, $"{label}: severed part must displace visibly outward");
                Assert(Mathf.Abs(inst.AngleDeg) > 10f, $"{label}: severed part must tumble/rotate visibly during fall");
                Color settledTint = inst.ComputeBodyTint(1f);
                Assert(settledTint.r < 0.70f, $"{label}: landed debris must darken toward dead/wreckage tone (r={settledTint.r:F2})");
            }

            SimulateAndVerify("BioGrounded", bioGround, GiantSeverVfxKind.FleshSever, isSolid: false);
            SimulateAndVerify("BioAirborne", bioAir, GiantSeverVfxKind.FleshSever, isSolid: false);
            SimulateAndVerify("MechDebris", mechProf, GiantSeverVfxKind.MechExplosion, isSolid: true);
            SimulateAndVerify("VoidDebris", voidProf, GiantSeverVfxKind.VoidRupture, isSolid: false);

            Console.WriteLine($"       -> Verified subtree partitioning (tail=1x6, wingtip=1x2, multi=3), skinned complement snapshots (wing={wTris.Length / 3}t, tail={tTris.Length / 3}t), & 4 ballistic fall/bounce/fade profiles");
        }

        private static void TestValstrax46BoneCometElderDragonAndDragonEnergyShader()
        {
            // 1. Verify GCF_ValstraxDragonEnergy.frag.glsl & ShaderDefs_Valstrax.xml
            string glslPath = ResolveMod17Path("Shaders", "GCF_ValstraxDragonEnergy.frag.glsl");
            string jetGlslPath = ResolveMod17Path("Shaders", "GCF_ValstraxDragonJetVfx.frag.glsl");
            string shaderXmlPath = ResolveMod17Path("Defs", "ShaderDefs", "ShaderDefs_Valstrax.xml");
            Assert(File.Exists(glslPath) && File.Exists(jetGlslPath) && File.Exists(shaderXmlPath),
                "Missing Valstrax Dragon-Energy GLSL, DragonJetVfx GLSL, or ShaderDefs_Valstrax.xml");

            string glsl = File.ReadAllText(glslPath);
            Assert(glsl.StartsWith("#version 450", StringComparison.Ordinal)
                   && glsl.Contains("uniform sampler2D _MaskTex", StringComparison.Ordinal)
                   && glsl.Contains("sootObsidian", StringComparison.Ordinal)
                   && glsl.Contains("intakeEnergy", StringComparison.Ordinal)
                   && glsl.Contains("roseWhiteCore", StringComparison.Ordinal),
                "GCF_ValstraxDragonEnergy.frag.glsl must implement #version 450, _MaskTex, Kokuka soot-blackening, chest intake wave, and pure crimson/rose-white orifice ramp");

            string jetGlsl = File.ReadAllText(jetGlslPath);
            Assert(jetGlsl.StartsWith("#version 450", StringComparison.Ordinal)
                   && jetGlsl.Contains("ridgedFlameFbm", StringComparison.Ordinal)
                   && jetGlsl.Contains("valstraxDragonThermalRamp", StringComparison.Ordinal)
                   && jetGlsl.Contains("composeDragonPremul", StringComparison.Ordinal)
                   && jetGlsl.Contains("machWave", StringComparison.Ordinal)
                   && jetGlsl.Contains("starGlare", StringComparison.Ordinal),
                "GCF_ValstraxDragonJetVfx.frag.glsl must implement RimFX 4-octave ridgedFlameFbm, physical thermal-soot ramp, supersonic wing-engine jet torrents, fractal Dragon lightning, Dragon plasma beam, and Crimson Star comet glare");

            XDocument shDoc = XDocument.Load(shaderXmlPath);
            XElement shProg = shDoc.Root!.Elements("ShaderDef")
                .First(e => e.Element("defName")?.Value == "GCF_ValstraxDragonEnergy")
                .Element("shaderProgram")!;
            Assert(string.Equals(shProg.Element("flipTextureST")?.Value, "true", StringComparison.OrdinalIgnoreCase),
                "GCF_ValstraxDragonEnergy must set <flipTextureST>true</flipTextureST>");
            Assert(shDoc.Root.Elements("ShaderTypeDef").Any(e => e.Element("defName")?.Value == "GCF_ValstraxDragonEnergy"),
                "Missing ShaderTypeDef GCF_ValstraxDragonEnergy");

            XElement jetProg = shDoc.Root.Elements("ShaderDef")
                .First(e => e.Element("defName")?.Value == "GCF_ValstraxDragonJetVfx")
                .Element("shaderProgram")!;
            Assert(string.Equals(jetProg.Element("blendSrcFactor")?.Value, "One", StringComparison.OrdinalIgnoreCase)
                   && string.Equals(jetProg.Element("blendDstFactor")?.Value, "OneMinusSrcAlpha", StringComparison.OrdinalIgnoreCase),
                "GCF_ValstraxDragonJetVfx must use premultiplied One / OneMinusSrcAlpha blending for simultaneous soot-black & crimson-white plasma");
            Assert(shDoc.Root.Elements("ShaderTypeDef").Any(e => e.Element("defName")?.Value == "GCF_ValstraxDragonJetVfx"),
                "Missing ShaderTypeDef GCF_ValstraxDragonJetVfx");

            // 2. Load 46-bone rig, BodyDef, and 19 animations; verify 1:1 alignment & physical layer rules
            var (rig, masks, animMap) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            Assert(rig.SortedNodes.Length == 46, $"Expected 46 bones on GCF_Rig_Valstrax, got {rig.SortedNodes.Length}");
            Assert(rig.ConfigErrors().Count() == 0, $"GCF_Rig_Valstrax ConfigErrors: {string.Join("; ", rig.ConfigErrors())}");
            Assert(rig.ValidatePhysicalLayerOrdering(0.5f).Count() == 0, "GCF_Rig_Valstrax violated physical layer ordering");

            BodyDef body = LoadBodyDefFromXml("Bodies_Valstrax.xml", "GCF_Body_Valstrax");
            ResolveRigBodyPartsForTest(rig, body, out BodyPartRecord[] boneParts, out _);
            var uniqueSeverParts = new HashSet<BodyPartRecord>();
            for (int i = 0; i < rig.SortedNodes.Length; i++)
            {
                Assert(boneParts[i] != null, $"Unresolved BodyPartRecord for Valstrax bone '{rig.SortedNodes[i].nodeId}'");
                Assert(uniqueSeverParts.Add(boneParts[i]), $"Duplicate BodyPartRecord ownership on '{rig.SortedNodes[i].nodeId}'");
            }

            // 3. Verify all 9 SkinnedMesh layers + *_Sil.png + *m.png (_MaskTex) + zero lateral X drift on body/forelegs/hindlegs
            Assert(rig.skinnedMeshes != null && rig.skinnedMeshes.Count == 9, $"Expected 9 SkinnedMeshes on GCF_Rig_Valstrax, got {rig.skinnedMeshes?.Count ?? 0}");
            var silMasks = new TextureAlphaMask[rig.SortedNodes.Length];
            for (int i = 0; i < rig.SortedNodes.Length; i++)
            {
                string silPng = ResolveMod17Path("Textures", rig.SortedNodes[i].silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                string mPng = ResolveMod17Path("Textures", rig.SortedNodes[i].texPath.Replace('/', Path.DirectorySeparatorChar) + "m.png");
                Assert(File.Exists(silPng) && File.Exists(mPng), $"Missing _Sil.png or m.png for bone '{rig.SortedNodes[i].nodeId}'");
                silMasks[i] = TextureAlphaMask.FromPngFile(silPng, 24);
            }

            var skinRts = new Dictionary<string, SkinnedMeshRuntime>(StringComparer.Ordinal);
            foreach (GiantSkinnedMeshDef smDef in rig.skinnedMeshes)
            {
                string colPng = ResolveMod17Path("Textures", smDef.texPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                string silPng = ResolveMod17Path("Textures", smDef.silhouetteTexPath.Replace('/', Path.DirectorySeparatorChar) + ".png");
                string maskPng = ResolveMod17Path("Textures", smDef.texPath.Replace('/', Path.DirectorySeparatorChar) + "m.png");
                Assert(File.Exists(colPng) && File.Exists(silPng) && File.Exists(maskPng),
                    $"Missing Skinned PNG / _Sil.png / m.png for '{smDef.meshId}'");
                var smRt = new SkinnedMeshRuntime(rig, smDef);
                smRt.EnsureBindTopology(TextureAlphaMask.FromPngFile(silPng, smDef.alphaThreshold), masks, silMasks);
                Assert(smRt.IsBindInitialized && smRt.VertexCount > 8 && smRt.ActiveTriangleCount > 4,
                    $"Valstrax SkinnedMesh '{smDef.meshId}' failed bind init");
                skinRts[smDef.meshId] = smRt;
            }

            var evalLocal = new BoneLocalPose[rig.SortedNodes.Length];
            var evalWorld = new BoneWorldPose[rig.SortedNodes.Length];
            var zeroMissing = new bool[rig.SortedNodes.Length];
            GiantAnimDef walkClip = animMap["GCF_Anim_Valstrax_Walk"];
            GiantAnimDef flyClip = animMap["GCF_Anim_Valstrax_FlyMove"];

            foreach (GiantAnimDef loco in new[] { walkClip, flyClip })
            {
                foreach (string strictMesh in new[] { "Dorsal_Body", "Foreleg_Left", "Foreleg_Right", "Hindleg_Left", "Hindleg_Right" })
                {
                    SkinnedMeshRuntime rt = skinRts[strictMesh];
                    var minX = Enumerable.Repeat(float.MaxValue, rt.VertexCount).ToArray();
                    var maxX = Enumerable.Repeat(float.MinValue, rt.VertexCount).ToArray();
                    for (int s = 0; s < 24; s++)
                    {
                        loco.EvaluateInto(rig, (s / 24f) * loco.durationTicks, evalLocal);
                        SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, zeroMissing, evalWorld);
                        rt.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
                        Vector3[] dv = rt.DeformedVertices;
                        for (int vi = 0; vi < dv.Length; vi++)
                        {
                            if (dv[vi].x < minX[vi]) minX[vi] = dv[vi].x;
                            if (dv[vi].x > maxX[vi]) maxX[vi] = dv[vi].x;
                        }
                    }
                    float maxDrift = 0f;
                    for (int vi = 0; vi < minX.Length; vi++)
                    {
                        float d = maxX[vi] - minX[vi];
                        if (d > maxDrift) maxDrift = d;
                    }
                    Assert(maxDrift < 1e-4f, $"Valstrax '{strictMesh}' lateral X drift ({maxDrift:F6}) in '{loco.defName}'");
                }
            }

            // Partial jet-lance severing on Wing_Lances_Right
            var sevMissing = new bool[rig.SortedNodes.Length];
            sevMissing[rig.SortedNodes.First(n => n.nodeId == "wing_lance_outer_right").runtimeIndex] = true;
            CompGiantRig.PropagateTopologicalBoneMissingMask(rig.SortedNodes, sevMissing);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, sevMissing, evalWorld);
            SkinnedMeshRuntime lancesRRt = skinRts["Wing_Lances_Right"];
            lancesRRt.EvaluateDeformedVertices(evalWorld, Vector2.zero, false, out _);
            Assert(lancesRRt.IsCurrentlyVisible && lancesRRt.HasPartialMemberSevering,
                "Severing wing_lance_outer_right must keep inner+mid lances visible with HasPartialMemberSevering=true");

            // 4. Verify CompValstraxDragonEnergy state machine, shader uniform outputs, and canon Chest Intake Backfire!
            var deComp = new CompValstraxDragonEnergy();
            deComp.Initialize(new CompProperties_ValstraxDragonEnergy
            {
                intakeWindupTicks = 30,
                dragonActiveDurationTicks = 200,
                chestBurstDamageThreshold = 85f
            });
            deComp.ComputeShaderSnapshot(out _, out Vector4 calmVec);
            AssertNear(calmVec.y, 0f, 1e-5f, "Calm Valstrax must output 0.0 chargeLevel (0% red glow)");
            AssertNear(calmVec.w, 0f, 1e-5f, "Calm Valstrax must output 0.0 intakePulse");

            // Test Chest Intake Interruption Backfire (canon MHXX chest stagger!)
            deComp.BeginDragonIntake(30);
            for (int t = 0; t < 10; t++) deComp.StepTickHeadless();
            deComp.ComputeShaderSnapshot(out _, out Vector4 intakeVec);
            Assert(deComp.DragonState == ValstraxDragonState.Intaking && intakeVec.w > 0.5f && intakeVec.y > 0.1f,
                "Intaking Valstrax must drive positive intakePulse and rising chargeLevel");
            Assert(!deComp.RegisterIntakeDamageCheck(40f, hitThoraxOrInternalChest: true),
                "Sub-threshold chest hit (40 < 85) must not trigger chest backfire yet");
            Assert(deComp.RegisterIntakeDamageCheck(50f, hitThoraxOrInternalChest: true)
                   && deComp.DragonState == ValstraxDragonState.Calm
                   && deComp.ChestBackfireCount == 1
                   && deComp.ChargeLevel == 0f,
                "Exceeding chest damage threshold (40+50 >= 85) during Intaking must trigger Chest Intake Backfire and reset to Calm");

            // Full uninterrupted Intake -> DragonActive -> CometAmbush -> DragonActive -> Calm cycle
            deComp.BeginDragonIntake(20);
            for (int t = 0; t < 20; t++) deComp.StepTickHeadless();
            Assert(deComp.DragonState == ValstraxDragonState.DragonActive && deComp.IsDragonActive,
                "Uninterrupted Dragon Intake must ignite DragonActive state");
            for (int t = 0; t < 15; t++) deComp.StepTickHeadless(isAirborne: true, isPerformingWingAction: true);
            deComp.ComputeShaderSnapshot(out Color glowCol, out Vector4 activeVec);
            Assert(glowCol.r > 0.90f && activeVec.y > 0.95f && activeVec.z > 0.80f && activeVec.w < 0.05f,
                $"DragonActive airborne Valstrax shader uniforms invalid: {activeVec}");

            deComp.EnterCometAmbushOverdrive(25);
            deComp.StepTickHeadless();
            deComp.ComputeShaderSnapshot(out _, out Vector4 cometVec);
            Assert(deComp.DragonState == ValstraxDragonState.CometAmbush && cometVec.z >= 1.50f,
                "CometAmbush overdrive must drive maximum jetThrust >= 1.50");
            for (int t = 0; t < 25; t++) deComp.StepTickHeadless();
            Assert(deComp.DragonState == ValstraxDragonState.DragonActive,
                "CometAmbush completion must return smoothly to DragonActive");

            // 5. Strict Zero-Rathalos-Reuse Gate + 6-Nozzle Wing-Morph Kinematics + RimFX Discipline
            string valCs = File.ReadAllText(Path.Combine(ModsParentDir, "[GCF]Valstrax", "Source", "GCF.Valstrax", "Abilities", "ValstraxDragonEnergySystem.cs"));
            Assert(!valCs.Contains("FleckMaker.", StringComparison.Ordinal) && !valCs.Contains("SpawnSlashArc", StringComparison.Ordinal),
                "ValstraxDragonEnergySystem.cs must use pure GPU shaders with zero vanilla FleckMaker or cartoon SlashArc");
            Assert(!valCs.Contains("Rathalos", StringComparison.OrdinalIgnoreCase)
                   && !valCs.Contains("Wyvern", StringComparison.OrdinalIgnoreCase)
                   && !valCs.Contains("SpawnFlyingDragonFireball", StringComparison.Ordinal)
                   && !valCs.Contains("isDragonFlame", StringComparison.Ordinal),
                "ValstraxDragonEnergySystem.cs must have ZERO Rathalos reuse and ZERO orange/yellow fireball calls");

            string rathCs = File.ReadAllText(Path.Combine(ModsParentDir, "[GCF]Rathalos", "Source", "GCF.Rathalos", "Abilities", "RathalosDragonChargeSystem.cs"));
            Assert(!rathCs.Contains("Valstrax", StringComparison.OrdinalIgnoreCase),
                "RathalosDragonChargeSystem.cs must remain 100% isolated with zero Valstrax references");

            foreach (string valXml in EnumerateAllMod17Files("", "*Valstrax*.xml", SearchOption.AllDirectories))
            {
                string xmlTxt = File.ReadAllText(valXml);
                Assert(!xmlTxt.Contains("Rathalos", StringComparison.OrdinalIgnoreCase)
                       && !xmlTxt.Contains("Wyvern", StringComparison.OrdinalIgnoreCase),
                    $"Valstrax XML '{Path.GetFileName(valXml)}' must contain zero Rathalos/Wyvern reuse");
            }

            // Verify 6-Nozzle Wing-Lance Vectors in Rest Pose (aftward thrust), DragonCannon (forward flip), and WingThrustLeft (3-lance spear convergence!)
            var baseNoz = new Vector2[6];
            var tipNoz = new Vector2[6];
            var dirNoz = new Vector2[6];
            Array.Clear(evalLocal, 0, evalLocal.Length);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
            int restCount = ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
            Assert(restCount == 6, $"Expected 6 wing nozzles on Valstrax, got {restCount}");
            for (int n = 0; n < 6; n++)
            {
                Assert(dirNoz[n].y < -0.78f, $"Rest wing nozzle {n} must point aftward (dir.y < -0.78), got {dirNoz[n]}");
            }

            GiantAnimDef cannonClip = animMap["GCF_Anim_Valstrax_DragonCannon"];
            Assert(cannonClip.durationTicks == 124 && Mathf.Abs(cannonClip.impactTick - 56f) < 0.01f && cannonClip.tracks.Count >= 32,
                $"DragonCannon must articulate >= 32 bones over 124 ticks with deliberate 56-tick charge, got {cannonClip.tracks.Count} tracks / {cannonClip.durationTicks} ticks / impact={cannonClip.impactTick}");
            foreach (float cannonSampleTick in new[] { 24f, 56f, 88f })
            {
                cannonClip.EvaluateInto(rig, cannonSampleTick, evalLocal);
                SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
                ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
                for (int n = 0; n < 6; n++)
                {
                    Assert(dirNoz[n].y > 0.72f, $"DragonCannon forward-flipped wing nozzle {n} at tick {cannonSampleTick} must aim forward toward +Z (dir.y > 0.72), got {dirNoz[n]}");
                }
                // Verify 3 wing-lance claws on each wing FAN WIDE OPEN facing the target (NOT folded/collapsed together!)
                float leftClawFanSpanX = Mathf.Abs(tipNoz[0].x - tipNoz[2].x);
                float rightClawFanSpanX = Mathf.Abs(tipNoz[3].x - tipNoz[5].x);
                float leftOuterInnerDot = Vector2.Dot(dirNoz[0], dirNoz[2]);
                float rightOuterInnerDot = Vector2.Dot(dirNoz[3], dirNoz[5]);
                Assert(leftClawFanSpanX > 4.5f && rightClawFanSpanX > 4.5f && leftOuterInnerDot < 0.85f && rightOuterInnerDot < 0.85f,
                    $"DragonCannon claws at tick {cannonSampleTick} must fan wide open facing target (spanL={leftClawFanSpanX:F2}, spanR={rightClawFanSpanX:F2}, dotL={leftOuterInnerDot:F3}, dotR={rightOuterInnerDot:F3})");
            }
            cannonClip.EvaluateInto(rig, 63f, evalLocal);
            Assert(evalLocal[0].offset.y < -0.40f, $"DragonCannon must drive heavy thorax_core recoil (< -0.40) at tick 63, got {evalLocal[0].offset}");

            GiantAnimDef cometClip = animMap["GCF_Anim_Valstrax_CometAmbush"];
            Assert(cometClip.durationTicks == 156 && Mathf.Abs(cometClip.impactTick - 112f) < 0.01f && cometClip.tracks.Count == 46,
                $"CometAmbush must articulate all 46 bones over 156 ticks (impactTick=112), got {cometClip.tracks.Count} tracks / {cometClip.durationTicks} ticks / impact={cometClip.impactTick}");
            int shLIdx = rig.SortedNodes.First(nd => nd.nodeId == "wing_shoulder_left").runtimeIndex;
            int shRIdx = rig.SortedNodes.First(nd => nd.nodeId == "wing_shoulder_right").runtimeIndex;
            cometClip.EvaluateInto(rig, 13f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
            ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
            float scoopSpanX = Mathf.Abs(tipNoz[0].x - tipNoz[3].x);
            cometClip.EvaluateInto(rig, 27f, evalLocal);
            Assert(evalLocal[0].offset.y < -0.40f, $"CometAmbush booster clamp at tick 27 must coil thorax_core aftward (< -0.40), got {evalLocal[0].offset}");
            cometClip.EvaluateInto(rig, 104f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
            ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
            float diveSpanX = Mathf.Abs(tipNoz[0].x - tipNoz[3].x);
            for (int n = 0; n < 6; n++)
            {
                Assert(dirNoz[n].y < -0.90f, $"CometAmbush supersonic dive nozzle {n} at tick 104 must point parallel aftward (dir.y < -0.90), got {dirNoz[n]}");
            }
            cometClip.EvaluateInto(rig, 118f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
            ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
            float brakeSpanX = Mathf.Abs(tipNoz[0].x - tipNoz[3].x);
            Console.WriteLine($"       -> Valstrax CometAmbush wingspan: scoop={scoopSpanX:F2}c, dive={diveSpanX:F2}c, airbrake={brakeSpanX:F2}c (dirL={dirNoz[0]}, dirR={dirNoz[3]})");
            Assert(evalLocal[shLIdx].angle >= 26f && evalLocal[shRIdx].angle <= -26f && Mathf.Abs(dirNoz[0].x) > 0.85f && brakeSpanX > diveSpanX + 3.0f && scoopSpanX > diveSpanX + 2.5f,
                $"CometAmbush wingspan contrast insufficient: scoop={scoopSpanX:F2}, dive={diveSpanX:F2}, airbrake={brakeSpanX:F2}, dirL={dirNoz[0]}");

            GiantAnimDef spearClip = animMap["GCF_Anim_Valstrax_JetWingThrust"];
            Assert(spearClip.tracks.Count == 46 && spearClip.durationTicks == 56,
                $"JetWingThrust must use the 46-bone Comet-liftoff rocket rush clip (56 ticks), got {spearClip.tracks.Count} tracks / {spearClip.durationTicks} ticks");
            spearClip.EvaluateInto(rig, 8f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
            ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
            float rushScoopSpanX = Mathf.Abs(tipNoz[0].x - tipNoz[3].x);
            spearClip.EvaluateInto(rig, 28f, evalLocal);
            SkeletalKinematics.SolveWorldPoses(rig, Vector2.zero, 0f, evalLocal, ReadOnlySpan<bool>.Empty, evalWorld);
            ValstraxDragonEnergyVfxRenderer.EvaluateSixWingNozzleVectors(rig, evalWorld, baseNoz, tipNoz, dirNoz);
            float rushConeSpanX = Mathf.Abs(tipNoz[0].x - tipNoz[3].x);
            for (int n = 0; n < 6; n++)
            {
                Assert(dirNoz[n].y < -0.90f,
                    $"JetWingThrust Comet-liftoff rocket cone nozzle {n} at tick 28 must point parallel aftward (dir.y < -0.90), got {dirNoz[n]}");
            }
            Assert(rushScoopSpanX > rushConeSpanX + 2.5f,
                $"JetWingThrust must scoop wide ({rushScoopSpanX:F2}c) then clamp into tight aft rocket cone ({rushConeSpanX:F2}c)");

            Color[] valColors =
            {
                ValstraxRimfxPalette.DragonCoreScarlet,
                ValstraxRimfxPalette.DragonExhaustCrimson,
                ValstraxRimfxPalette.DragonLightningRuby,
                ValstraxRimfxPalette.DragonPressureWave
            };
            foreach (Color pc in valColors)
            {
                GiantVfxSystem.DeriveRimfxTriad(pc, out Color cCore, out Color cBody, out Color cEdge);
                Color.RGBToHSV(cCore, out _, out float sCore, out float vCore);
                Color.RGBToHSV(cBody, out _, out float sBody, out float vBody);
                Color.RGBToHSV(cEdge, out _, out float sEdge, out float vEdge);
                Assert(vCore > vBody && vBody > vEdge && sCore <= 0.22f && sBody <= 0.34f && sEdge <= 0.38f,
                    $"ValstraxRimfxPalette triad invalid for {pc}");
            }

            var valPartAttacks = rig.SortedNodes.SelectMany(n => n.partAttacks).ToList();
            string[] expectedNormalMeleeIds =
            {
                "valstrax_fierce_bite",
                "valstrax_claw_slash_left",
                "valstrax_claw_slash_right",
                "valstrax_wing_claw_slash_left",
                "valstrax_wing_claw_slash_right",
                "valstrax_tail_spear_sweep"
            };
            Assert(valPartAttacks.Count == 6 && expectedNormalMeleeIds.All(id => valPartAttacks.Any(a => a.attackId == id)),
                $"Valstrax normal melee must expose 6 bite/claw/wing-claw/tail attacks ({string.Join(",", expectedNormalMeleeIds)}), got {valPartAttacks.Count}: {string.Join(",", valPartAttacks.Select(a => a.attackId))}");
            Assert(!valPartAttacks.Any(a => a.attackId == "valstrax_jet_spin_slash"),
                "valstrax_jet_spin_slash must be promoted to an AbilityDef and removed from normal <partAttacks>");
            Assert(rig.meleeAttackAnims != null && rig.meleeAttackAnims.Count == 6
                   && !rig.meleeAttackAnims.Any(a => a.defName == "GCF_Anim_Valstrax_JetSpinSlash")
                   && rig.abilityAnims != null && rig.abilityAnims.Any(a => a.defName == "GCF_Anim_Valstrax_JetSpinSlash"),
                "GCF_Anim_Valstrax_JetSpinSlash must live in <abilityAnims> while <meleeAttackAnims> holds the 6 normal melee clips");

            GiantAnimDef spinClip = animMap["GCF_Anim_Valstrax_JetSpinSlash"];
            Assert(spinClip.tracks.Count >= 35 && spinClip.durationTicks >= 80 && spinClip.impactTick >= 24f && spinClip.impactTick < spinClip.durationTicks,
                $"JetSpinSlash must articulate >= 35 bones with valid duration/impactTick, got {spinClip.tracks.Count} tracks / {spinClip.durationTicks} ticks / impact={spinClip.impactTick}");
            float maxWindupAng = float.MinValue;
            float minSpinAng = float.MaxValue;
            for (int t = 0; t <= Mathf.RoundToInt(spinClip.durationTicks); t++)
            {
                spinClip.EvaluateInto(rig, t, evalLocal);
                if (evalLocal[0].angle > maxWindupAng) maxWindupAng = evalLocal[0].angle;
                if (evalLocal[0].angle < minSpinAng) minSpinAng = evalLocal[0].angle;
            }
            Assert(maxWindupAng > 55f, $"JetSpinSlash must exhibit pronounced > +55 deg clockwise windup, got {maxWindupAng:F1} deg");
            Assert(minSpinAng <= -355f, $"JetSpinSlash must complete full -360 deg thorax_core spin, got min={minSpinAng:F1} deg");

            foreach (GiantPartAttackDef pa in valPartAttacks)
            {
                Assert(pa.power > 0f && pa.stunTicks > 0 && !string.IsNullOrEmpty(pa.rangeOriginBoneId) && rig.TryGetNodeIndex(pa.rangeOriginBoneId, out _),
                    $"Invalid Valstrax partAttack '{pa.attackId}'");
            }

            // Verify zero wing-flapping during flight (FlyMove steady swept-back jet pose) & always-on flight jet thrust even in Calm state
            foreach (string steadyWingNode in new[]
            {
                "wing_shoulder_left", "wing_shoulder_right",
                "wing_forearm_left", "wing_forearm_right",
                "wing_lance_outer_left", "wing_lance_outer_right",
                "wing_lance_mid_left", "wing_lance_mid_right",
                "wing_lance_inner_left", "wing_lance_inner_right"
            })
            {
                int wIdx = rig.SortedNodes.First(nd => nd.nodeId == steadyWingNode).runtimeIndex;
                float minA = float.MaxValue, maxA = float.MinValue, minF = float.MaxValue, maxF = float.MinValue;
                for (int t = 0; t <= Mathf.RoundToInt(flyClip.durationTicks); t += 4)
                {
                    flyClip.EvaluateInto(rig, t, evalLocal);
                    if (evalLocal[wIdx].angle < minA) minA = evalLocal[wIdx].angle;
                    if (evalLocal[wIdx].angle > maxA) maxA = evalLocal[wIdx].angle;
                    if (evalLocal[wIdx].coronalFlap < minF) minF = evalLocal[wIdx].coronalFlap;
                    if (evalLocal[wIdx].coronalFlap > maxF) maxF = evalLocal[wIdx].coronalFlap;
                }
                Assert((maxA - minA) < 1e-4f && (maxF - minF) < 1e-4f,
                    $"Valstrax FlyMove '{steadyWingNode}' must have ZERO wing-flapping oscillation (dAngle={maxA - minA:F4}, dFlap={maxF - minF:F4})");
            }

            var calmFlyDe = new CompValstraxDragonEnergy();
            calmFlyDe.Initialize(new CompProperties_ValstraxDragonEnergy());
            Assert(calmFlyDe.DragonState == ValstraxDragonState.Calm && calmFlyDe.JetThrustBoost == 0f, "Initial Calm grounded thrust must be 0");
            for (int t = 0; t < 12; t++) calmFlyDe.StepTickHeadless(isAirborne: true, isPerformingWingAction: false);
            Assert(calmFlyDe.DragonState == ValstraxDragonState.Calm && calmFlyDe.JetThrustBoost >= 0.90f,
                $"Airborne Calm Valstrax must maintain always-on jet exhaust thrust >= 0.90, got {calmFlyDe.JetThrustBoost:F2}");
            for (int t = 0; t < 20; t++) calmFlyDe.StepTickHeadless(isAirborne: false, isPerformingWingAction: false);
            AssertNear(calmFlyDe.JetThrustBoost, 0f, 1e-3f, "Grounded Calm Valstrax must extinguish flight jet thrust back to 0");

            // Verify all 5 abilities (including promoted JetSpinSlash + icon) & tuned cooldowns (JetSpinSlash >= 900 ticks / 15s)
            Assert(File.Exists(ResolveMod17Path("Textures", "UI", "Icons", "Abilities", "GCF_Valstrax_JetSpinSlash.png")),
                "Missing GCF_Valstrax_JetSpinSlash.png ability icon");
            XDocument abDoc = XDocument.Load(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_Valstrax.xml"));
            (string abName, string dmgTag, string stunTag, int minCdTicks)[] abChecks =
            {
                ("GCF_Ability_Valstrax_DragonIntake", "shockDamage", "stunTicks", 1500),
                ("GCF_Ability_Valstrax_JetSpinSlash", "slashDamage", "stunTicks", 900),
                ("GCF_Ability_Valstrax_DragonCannon", "cannonDamage", "stunTicks", 1800),
                ("GCF_Ability_Valstrax_JetWingThrust", "rushDamage", "stunTicks", 1800),
                ("GCF_Ability_Valstrax_CometAmbush", "cometImpactDamage", "stunTicks", 2400),
            };
            foreach (var (abName, dmgTag, stunTag, minCdTicks) in abChecks)
            {
                XElement aEl = abDoc.Root!.Elements("AbilityDef").First(e => e.Element("defName")?.Value == abName);
                int cdTicks = int.Parse(aEl.Element("cooldownTicksRange")!.Value);
                Assert(cdTicks >= minCdTicks, $"Valstrax ability '{abName}' cooldownTicksRange ({cdTicks}) must be >= {minCdTicks}");
                Assert(int.Parse(aEl.Descendants(dmgTag).First().Value) > 0 && int.Parse(aEl.Descendants(stunTag).First().Value) > 0,
                    $"Valstrax ability '{abName}' missing positive damage or stunTicks");
            }

            // Verify explicit Dragon-Energy Active duration on DragonIntake & strict IsDragonActive gating on all 4 other abilities
            XElement intakeXmlEl = abDoc.Root!.Elements("AbilityDef")
                .First(e => e.Element("defName")?.Value == "GCF_Ability_Valstrax_DragonIntake");
            int intakeCdXml = int.Parse(intakeXmlEl.Element("cooldownTicksRange")!.Value);
            int intakeDurTicksXml = int.Parse(intakeXmlEl.Descendants("activeDurationTicks").First().Value);
            float intakeStatDurSec = ParseFloat(intakeXmlEl.Element("statBases")?.Element("Ability_Duration")?.Value, 0f);
            Assert(intakeDurTicksXml >= 600 && intakeCdXml > intakeDurTicksXml,
                $"DragonIntake must configure finite activeDurationTicks ({intakeDurTicksXml}) strictly shorter than cooldownTicksRange ({intakeCdXml})");
            AssertNear(intakeStatDurSec * 60f, intakeDurTicksXml, 1f,
                $"DragonIntake <Ability_Duration> ({intakeStatDurSec}s) must match <activeDurationTicks> ({intakeDurTicksXml} ticks)");

            XElement cometXmlEl = abDoc.Root!.Elements("AbilityDef")
                .First(e => e.Element("defName")?.Value == "GCF_Ability_Valstrax_CometAmbush");
            float cometImpactRadXml = ParseFloat(cometXmlEl.Descendants("impactRadius").First().Value, 0f);
            float cometStatRadXml = ParseFloat(cometXmlEl.Element("statBases")?.Element("Ability_EffectRadius")?.Value, 0f);
            int cometDmgXml = int.Parse(cometXmlEl.Descendants("cometImpactDamage").First().Value);
            int cometFissureDmgXml = int.Parse(cometXmlEl.Descendants("fissureDamage").First().Value);
            float cometFissureRadXml = ParseFloat(cometXmlEl.Descendants("fissureRadius").First().Value, 0f);
            Assert(cometImpactRadXml >= 9.0f && cometDmgXml >= 150 && cometFissureDmgXml >= 50 && cometFissureRadXml >= 3.0f,
                $"CometAmbush must configure wide impactRadius >= 9.0 ({cometImpactRadXml}), high cometImpactDamage >= 150 ({cometDmgXml}), and positive 2-wave fissure aftershocks ({cometFissureDmgXml} @ r={cometFissureRadXml})");
            AssertNear(cometStatRadXml, cometImpactRadXml, 0.05f,
                "CometAmbush Ability_EffectRadius must match impactRadius");
            IntVec3 epiCellCheck = ValstraxCombatUtility.ResolveBlastEpicenterCell(null, new Vector2(60.5f, 60.5f), new IntVec3(60, 0, 68));
            Assert(epiCellCheck == new IntVec3(60, 0, 60),
                $"ResolveBlastEpicenterCell must preserve locked target epicenter (60,0,60) rather than displaced landing cell (60,0,68), got {epiCellCheck}");

            var gatePawn = new Pawn
            {
                thingIDNumber = 998765,
                def = new ThingDef
                {
                    defName = "GCF_Valstrax",
                    shortHash = 61888,
                    race = new RaceProperties(),
                    comps = new List<CompProperties>
                    {
                        new CompProperties_ValstraxDragonEnergy
                        {
                            intakeWindupTicks = 12,
                            dragonActiveDurationTicks = 90
                        }
                    }
                }
            };
            gatePawn.health = new Pawn_HealthTracker(gatePawn);
            gatePawn.InitializeComps();
            var gateDe = gatePawn.GetComp<CompValstraxDragonEnergy>();
            Assert(gateDe != null, "Expected InitializeComps to attach CompValstraxDragonEnergy");

            var abParent = new RimWorld.Ability { pawn = gatePawn };
            var intakeComp = new CompAbilityEffect_ValstraxDragonIntake { parent = abParent };
            intakeComp.Initialize(new CompProperties_AbilityValstraxDragonIntake { windupTicks = 12, activeDurationTicks = 90 });
            var spinAbComp = new CompAbilityEffect_ValstraxJetSpinSlash { parent = abParent };
            spinAbComp.Initialize(new CompProperties_AbilityValstraxJetSpinSlash());
            var cannonAbComp = new CompAbilityEffect_ValstraxDragonCannon { parent = abParent };
            cannonAbComp.Initialize(new CompProperties_AbilityValstraxDragonCannon());
            var thrustAbComp = new CompAbilityEffect_ValstraxJetWingThrust { parent = abParent };
            thrustAbComp.Initialize(new CompProperties_AbilityValstraxJetWingThrust());
            var cometAbComp = new CompAbilityEffect_ValstraxCometAmbush { parent = abParent };
            cometAbComp.Initialize(new CompProperties_AbilityValstraxCometAmbush());
            RimWorld.CompAbilityEffect[] gatedOtherComps = { spinAbComp, cannonAbComp, thrustAbComp, cometAbComp };

            // 1) Calm state: ONLY DragonIntake is enabled; all 4 other abilities are disabled for both Gizmo and AI
            Assert(gateDe.DragonState == ValstraxDragonState.Calm && !gateDe.IsDragonActive && gateDe.RemainingDragonActiveTicks == 0,
                "Expected initial Calm state with 0 remaining active ticks");
            Assert(!intakeComp.GizmoDisabled(out _) && intakeComp.AICanTargetNow(new LocalTargetInfo(gatePawn)),
                "DragonIntake must be available in Calm state");
            Assert(intakeComp.ExtraTooltipPart().Contains("2s", StringComparison.Ordinal) || intakeComp.ExtraTooltipPart().Contains("1s", StringComparison.Ordinal),
                $"DragonIntake ExtraTooltipPart must report configured active duration, got '{intakeComp.ExtraTooltipPart()}'");
            foreach (var other in gatedOtherComps)
            {
                Assert(other.GizmoDisabled(out string calmDisableReason) && !string.IsNullOrEmpty(calmDisableReason),
                    $"{other.GetType().Name} Gizmo must be disabled while Valstrax is Calm");
                Assert(!other.AICanTargetNow(new LocalTargetInfo(new IntVec3(20, 0, 20))),
                    $"{other.GetType().Name} AICanTargetNow must be false while Valstrax is Calm");
            }

            // 2) Intaking state: ALL 5 abilities (including DragonIntake) are disabled until inhalation completes
            gateDe.BeginDragonIntake(12, 6.4f, 36, 78, customActiveDurationTicks: 90);
            Assert(gateDe.DragonState == ValstraxDragonState.Intaking && !gateDe.IsDragonActive,
                "Expected Intaking state");
            Assert(intakeComp.GizmoDisabled(out _) && !intakeComp.AICanTargetNow(new LocalTargetInfo(gatePawn)),
                "DragonIntake must be disabled while already Intaking");
            foreach (var other in gatedOtherComps)
            {
                Assert(other.GizmoDisabled(out _) && !other.AICanTargetNow(new LocalTargetInfo(new IntVec3(20, 0, 20))),
                    $"{other.GetType().Name} must remain disabled during Intaking windup");
            }

            // 3) Ignition into DragonActive (exact 90-tick configured duration): DragonIntake locks, all 4 other abilities unlock
            for (int t = 0; t < 12; t++) gateDe.StepTickHeadless();
            Assert(gateDe.DragonState == ValstraxDragonState.DragonActive && gateDe.IsDragonActive && gateDe.RemainingDragonActiveTicks == 90,
                $"Expected DragonActive with exact 90 remaining ticks, got state={gateDe.DragonState}, rem={gateDe.RemainingDragonActiveTicks}");
            Assert(intakeComp.GizmoDisabled(out string activeLockReason) && !string.IsNullOrEmpty(activeLockReason)
                   && !intakeComp.AICanTargetNow(new LocalTargetInfo(gatePawn)),
                "DragonIntake must be disabled while DragonActive is already running");
            Assert(ValstraxCombatUtility.IsCasterDragonActiveForAbility(gatePawn, out _),
                "IsCasterDragonActiveForAbility must return true during DragonActive");
            foreach (var other in gatedOtherComps)
            {
                Assert(!other.GizmoDisabled(out string unexpReason),
                    $"{other.GetType().Name} Gizmo must unlock during DragonActive, but got disabled: {unexpReason}");
            }

            // 4) CometAmbush preserves remaining duration instead of resetting back to full duration, then expires cleanly to Calm!
            for (int t = 0; t < 10; t++) gateDe.StepTickHeadless(); // 90 -> 80 ticks left
            Assert(gateDe.RemainingDragonActiveTicks == 80, $"Expected 80 ticks left before ambush, got {gateDe.RemainingDragonActiveTicks}");
            gateDe.EnterCometAmbushOverdrive(20);
            for (int t = 0; t < 20; t++) gateDe.StepTickHeadless(); // ambush finishes; savedActiveTicks ticked 80 -> 60
            Assert(gateDe.DragonState == ValstraxDragonState.DragonActive && gateDe.RemainingDragonActiveTicks == 60,
                $"ExitCometAmbushToDragonActive must preserve remaining duration (60 ticks) without infinite reset, got {gateDe.RemainingDragonActiveTicks}");
            for (int t = 0; t < 60; t++) gateDe.StepTickHeadless();
            Assert(gateDe.DragonState == ValstraxDragonState.Calm && !gateDe.IsDragonActive && gateDe.RemainingDragonActiveTicks == 0,
                $"DragonActive must expire back to Calm once duration reaches 0, got state={gateDe.DragonState}, rem={gateDe.RemainingDragonActiveTicks}");
            foreach (var other in gatedOtherComps)
            {
                Assert(other.GizmoDisabled(out _) && !other.AICanTargetNow(new LocalTargetInfo(new IntVec3(20, 0, 20))),
                    $"{other.GetType().Name} must immediately re-lock once DragonActive duration expires");
            }

            // Verify 3-seat dorsal riding, ecology parity, and exact 4.0x Rathalos World Map movement speed
            XDocument valRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_Valstrax.xml"));
            XDocument rathRaceDoc = XDocument.Load(ResolveMod17Path("Defs", "ThingDefs_Races", "Races_Rathalos.xml"));
            XElement valTd = valRaceDoc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_Valstrax");
            XElement valPk = valRaceDoc.Root.Elements("PawnKindDef").First(e => e.Element("defName")?.Value == "GCF_Valstrax");
            XElement rathTd = rathRaceDoc.Root!.Elements("ThingDef").First(e => e.Element("defName")?.Value == "GCF_Rathalos");

            float valCaravanFactor = ParseFloat(valTd.Element("statBases")?.Element("CaravanRidingSpeedFactor")?.Value, 0f);
            float rathCaravanFactor = ParseFloat(rathTd.Element("statBases")?.Element("CaravanRidingSpeedFactor")?.Value, 0f);
            AssertNear(valCaravanFactor, rathCaravanFactor * 4.0f, 0.01f,
                $"Valstrax CaravanRidingSpeedFactor ({valCaravanFactor}) must equal 4x Rathalos ({rathCaravanFactor * 4f})");

            var (rathRigCheck, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            float valMoveSpd = ParseFloat(valTd.Element("statBases")?.Element("MoveSpeed")?.Value, 0f);
            float rathMoveSpd = ParseFloat(rathTd.Element("statBases")?.Element("MoveSpeed")?.Value, 0f);
            float valBaseTicks = Mathf.RoundToInt(60f / valMoveSpd);
            float rathBaseTicks = Mathf.RoundToInt(60f / rathMoveSpd);
            float valWorldTicks = WorldObject_Giant.ComputeEffectiveWorldTicksPerCell(valBaseTicks, true, rig.ActiveFlightLocomotion.ResolvedWorldFlightSpeedMultiplier);
            float rathWorldTicks = WorldObject_Giant.ComputeEffectiveWorldTicksPerCell(rathBaseTicks, true, rathRigCheck.ActiveFlightLocomotion.ResolvedWorldFlightSpeedMultiplier);
            float worldSpeedRatio = (1f / valWorldTicks) / (1f / rathWorldTicks);
            AssertNear(worldSpeedRatio, 4.0f, 0.02f,
                $"Valstrax WorldObject_Giant travel speed must be 4.0x Rathalos (got {worldSpeedRatio:F3}x: valTicks={valWorldTicks:F3}, rathTicks={rathWorldTicks:F3})");

            XElement valCrew = valTd.Element("comps")!.Elements("li")
                .FirstOrDefault(e => e.Attribute("Class")?.Value == "GiantCreatureFramework.CompProperties_GiantCrew");
            Assert(valCrew != null && valCrew.Element("seats")!.Elements("li").Count() == 3,
                "Valstrax must configure 3-seat dorsal CompProperties_GiantCrew riding");
            var valRigSeats = rig.SortedNodes.SelectMany(n => n.crewSeats ?? new List<GiantBoneCrewSeatDef>()).Select(s => s.seatId).ToHashSet();
            Assert(valRigSeats.Contains("SaddleLead") && valRigSeats.Contains("SaddleMid") && valRigSeats.Contains("SaddleAft"),
                "GCF_Rig_Valstrax must mount SaddleLead, SaddleMid, and SaddleAft crewSeats on dorsal thorax");
            Assert(valTd.Element("comps")!.Elements("li").Any(e => (e.Attribute("Class")?.Value ?? "").EndsWith("CompProperties_ValstraxHuntTarget", StringComparison.Ordinal)),
                "Valstrax must include CompProperties_ValstraxHuntTarget for world ecology quest parity");
            Assert(valPk.Element("abilities")!.Elements("li").Count() == 5
                   && valPk.Element("abilities")!.Elements("li").Any(e => e.Value == "GCF_Ability_Valstrax_JetSpinSlash"),
                "GCF_Valstrax PawnKindDef must declare all 5 signature abilities including GCF_Ability_Valstrax_JetSpinSlash");
            Assert(ValstraxProgressionUtility.ClassifyValstraxPartBreakSlot("tail_spear_head") == "tail"
                   && ValstraxProgressionUtility.ClassifyValstraxPartBreakSlot("wing_lance_outer_left") == "wing_l"
                   && ValstraxProgressionUtility.ClassifyValstraxPartBreakSlot("wing_lance_mid_right") == "wing_r",
                "ClassifyValstraxPartBreakSlot must map Valstrax tail-spear and left/right jet-wings");

            Console.WriteLine($"       -> Verified 46-bone Valstrax rig, 4 normal melee attacks, 5 high-CD abilities (incl. JetSpinSlash), 3-seat riding, ecology quest/carves, steady non-flapping jet flight, & {worldSpeedRatio:F2}x world speed");
        }

        private static void TestAllHitboxCellInteractionAndPathModeExtensions()
        {
            // 1. PathEndMode compatibility covers Touch, ClosestTouch (FeedPatient), InteractionCell (Tend), and OnCell (Tame/Train/Slaughter/Rescue)
            Assert(GiantHullInteractionUtility.IsGiantTouchCompatiblePathEndMode(Verse.AI.PathEndMode.Touch), "PathEndMode.Touch must be giant-touch compatible");
            Assert(GiantHullInteractionUtility.IsGiantTouchCompatiblePathEndMode(Verse.AI.PathEndMode.ClosestTouch), "PathEndMode.ClosestTouch must be giant-touch compatible");
            Assert(GiantHullInteractionUtility.IsGiantTouchCompatiblePathEndMode(Verse.AI.PathEndMode.InteractionCell), "PathEndMode.InteractionCell must be giant-touch compatible");
            Assert(GiantHullInteractionUtility.IsGiantTouchCompatiblePathEndMode(Verse.AI.PathEndMode.OnCell), "PathEndMode.OnCell must be giant-touch compatible");
            Assert(!GiantHullInteractionUtility.IsGiantTouchCompatiblePathEndMode(Verse.AI.PathEndMode.None), "PathEndMode.None must not be giant-touch compatible");

            // 2. Footprint touch check covers non-center outer hitbox cells (wings, tail, head) and their 8-way neighbors
            var fp = new GiantFootprintData();
            fp.hitCellSet.Add(new IntVec3(50, 0, 50)); // center
            fp.hitCellSet.Add(new IntVec3(58, 0, 50)); // outer wing/tail cell 8 cells away from center
            fp.hitCellPositions.Add(new IntVec3(50, 0, 50));
            fp.hitCellPositions.Add(new IntVec3(58, 0, 50));
            Assert(HarmonyPatches_CombatAndHitbox.IsCellTouchingFootprint(new IntVec3(58, 0, 50), fp), "Outer hitbox cell itself must satisfy IsCellTouchingFootprint");
            Assert(HarmonyPatches_CombatAndHitbox.IsCellTouchingFootprint(new IntVec3(59, 0, 51), fp), "8-way neighbor of outer hitbox cell must satisfy IsCellTouchingFootprint");
            Assert(!HarmonyPatches_CombatAndHitbox.IsCellTouchingFootprint(new IntVec3(61, 0, 50), fp), "Cell 3 tiles away from outer hitbox cell must not touch footprint");

            // 3. Verify Harmony patch methods exist with valid attributes on HarmonyPatches_CollisionAndSelection
            Type patchType = typeof(HarmonyPatches_CollisionAndSelection);
            string[] requiredPatchMethods =
            {
                nameof(HarmonyPatches_CollisionAndSelection.GenPath_ResolvePathMode_Prefix),
                nameof(HarmonyPatches_CollisionAndSelection.GenAdj_AdjacentTo8WayOrInside_Thing_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.GenAdj_AdjacentTo8WayOrInside_LocalTarget_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.GenAdj_AdjacentTo8WayOrInside_ThingPair_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.GenAdj_IsInside_Thing_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.ForbidUtility_IsForbidden_ThingPawn_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.WorkGiver_Tend_GoodLayingStatusForTend_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.Reachability_CanReach_Postfix),
                nameof(HarmonyPatches_CollisionAndSelection.Pawn_PathFollower_StartPath_Prefix),
                nameof(HarmonyPatches_CollisionAndSelection.GenUI_ThingsUnderMouse_Postfix)
            };
            Assert(typeof(HarmonyPatches_CombatAndHitbox).GetMethod(
                nameof(HarmonyPatches_CombatAndHitbox.ReachabilityImmediate_CanReachImmediate_Postfix),
                BindingFlags.Public | BindingFlags.Static) != null,
                "HarmonyPatches_CombatAndHitbox must provide unified ReachabilityImmediate_CanReachImmediate_Postfix");
            foreach (string methodName in requiredPatchMethods)
            {
                MethodInfo mi = patchType.GetMethod(methodName, BindingFlags.Public | BindingFlags.Static);
                Assert(mi != null, $"Missing Harmony patch method {methodName} on HarmonyPatches_CollisionAndSelection");
                object[] attrs = mi!.GetCustomAttributes(typeof(HarmonyLib.HarmonyPatch), inherit: false);
                Assert(attrs.Length > 0, $"Patch method {methodName} missing [HarmonyPatch] attribute");
            }

            // 4. Verify WorkGiver_Tend / WorkGiver_FeedPatient / WorkGiver_Tame / WorkGiver_Train / WorkGiver_Slaughter PathEndModes are all covered
            RimWorld.WorkGiver_Scanner[] scanners =
            {
                new RimWorld.WorkGiver_Tend(),
                new RimWorld.WorkGiver_FeedPatient(),
                new RimWorld.WorkGiver_Tame(),
                new RimWorld.WorkGiver_Train(),
                new RimWorld.WorkGiver_Slaughter(),
                new RimWorld.WorkGiver_RescueDowned(),
                new RimWorld.WorkGiver_Shear(),
                new RimWorld.WorkGiver_Milk(),
                new RimWorld.WorkGiver_RepairMech()
            };
            foreach (RimWorld.WorkGiver_Scanner scanner in scanners)
            {
                Assert(GiantHullInteractionUtility.IsGiantTouchCompatiblePathEndMode(scanner.PathEndMode),
                    $"{scanner.GetType().Name}.PathEndMode ({scanner.PathEndMode}) must be covered by IsGiantTouchCompatiblePathEndMode");
            }

            Console.WriteLine($"       -> Verified all-hitbox-cell PathEndMode ({scanners.Length} vanilla WorkGivers), GenPath.ResolvePathMode, GenAdj, ForbidUtility & biological giant tend extensions");
        }

        private static void TestGiantIngestTouchRangeAndDownedPawnCollisionImmunity()
        {
            // 1. Downed-pawn collision immunity contract (ground collision cells ignore downed/dead/flying pawns)
            Assert(!GiantFootprintMapComponent.ShouldIgnoreCollisionPawnState(isFlying: false, isDowned: false, isDead: false),
                "Standing alive ground pawn must NOT ignore giant collision cells");
            Assert(GiantFootprintMapComponent.ShouldIgnoreCollisionPawnState(isFlying: false, isDowned: true, isDead: false),
                "Downed pawn MUST be ignored by giant collision cells and push-out");
            Assert(GiantFootprintMapComponent.ShouldIgnoreCollisionPawnState(isFlying: false, isDowned: false, isDead: true),
                "Dead pawn MUST be ignored by giant collision cells");
            Assert(GiantFootprintMapComponent.ShouldIgnoreCollisionPawnState(isFlying: true, isDowned: false, isDead: false),
                "Flying pawn MUST be ignored by giant collision cells");
            Assert(!GiantFootprintMapComponent.ShouldPawnIgnoreGiantCollision(null),
                "Null pawn guard must return false");

            // 1b. PathEndMode.OnCell on plain map cells (JobDefOf.Goto / JobGiver_GiantPartCombatPositioning) MUST NEVER
            //     use giant-hull touch expansion (otherwise StartPath fires PatherArrived synchronously -> 10 jobs/tick loop).
            Assert(!HarmonyPatches_CombatAndHitbox.ShouldApplyGiantAttackerHullTouch(
                Verse.AI.PathEndMode.OnCell, targetHasThing: false, targetHasGiantHitCells: false, isGiantIngestTarget: false),
                "Plain cell Goto (OnCell, !HasThing) must NOT use giant hull touch expansion");
            Assert(!HarmonyPatches_CombatAndHitbox.ShouldApplyGiantAttackerHullTouch(
                Verse.AI.PathEndMode.OnCell, targetHasThing: true, targetHasGiantHitCells: false, isGiantIngestTarget: false),
                "Non-giant non-ingest Thing OnCell must NOT use giant hull touch expansion");
            Assert(HarmonyPatches_CombatAndHitbox.ShouldApplyGiantAttackerHullTouch(
                Verse.AI.PathEndMode.Touch, targetHasThing: true, targetHasGiantHitCells: false, isGiantIngestTarget: true),
                "Animal giant Ingest (Touch) must use giant hull touch expansion");
            Assert(HarmonyPatches_CombatAndHitbox.ShouldApplyGiantAttackerHullTouch(
                Verse.AI.PathEndMode.OnCell, targetHasThing: true, targetHasGiantHitCells: false, isGiantIngestTarget: true),
                "ToolUser giant Ingest (ClosestTouch -> OnCell) must use giant hull touch expansion");
            Assert(HarmonyPatches_CombatAndHitbox.ShouldApplyGiantAttackerHullTouch(
                Verse.AI.PathEndMode.OnCell, targetHasThing: true, targetHasGiantHitCells: true, isGiantIngestTarget: false),
                "Interacting with multi-cell giant/giant corpse (OnCell) must keep giant hull touch expansion");

            // 2. Real Rathalos (GCF_Rig_Rathalos) ingest touch-range invariance across all 360-degree headings
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            int n = rathRig.SortedNodes.Length;
            var localPoses = Enumerable.Repeat(BoneLocalPose.Identity, n).ToArray();
            var missing = new bool[n];
            var worldPoses = new BoneWorldPose[n];
            IntVec3 anchor = new IntVec3(60, 0, 60);
            Vector2 rootXZ = new Vector2(60.5f, 60.5f);
            IntVec3 mapSize = new IntVec3(140, 1, 140);

            var fpWest = new GiantFootprintData();
            SkeletalKinematics.SolveWorldPoses(rathRig, rootXZ, 270f, localPoses, missing, worldPoses);
            fpWest.Rebuild(rathRig, worldPoses, rathMasks, anchor, mapSize, collisionAnchorOverride: anchor);
            Assert(fpWest.localCollisionOffsets.Count > 0, "Rathalos must produce non-empty localCollisionOffsets");

            float baseMelee = rathRig.meleeTouchRadius > 0.01f ? rathRig.meleeTouchRadius : 2.0f;
            float snugRadius = HarmonyPatches_CombatAndHitbox.ComputeSnugIngestWalkRadius(baseMelee, fpWest.maxCollisionHorizontalExtent);
            float maxOffDist = HarmonyPatches_CombatAndHitbox.ComputeMaxLocalOffsetDistance(fpWest.localCollisionOffsets, fpWest.maxCollisionHorizontalExtent);
            float stationaryRadius = HarmonyPatches_CombatAndHitbox.ComputeGiantStationaryTouchRadius(
                baseMelee, fpWest.localCollisionOffsets, fpWest.maxCollisionHorizontalExtent);
            Assert(snugRadius >= 1.5f && snugRadius <= 3.2f, $"Snug ingest walk radius out of bounds: {snugRadius:F2}");
            Assert(stationaryRadius >= maxOffDist + 2.49f,
                $"Stationary touch radius ({stationaryRadius:F2}) must exceed maxOffsetDist + 2.5 ({maxOffDist + 2.5f:F2})");

            // 2a. Verify elongated dragon hull: an outermost tail/snout collision cell at distance 6-7 must NOT prematurely
            //     terminate Toils_Goto during StartPath (prevents stopping 7 cells away on a wingtip/tailtip).
            var elongatedOffsets = new List<IntVec3>
            {
                new IntVec3(0, 0, 0), new IntVec3(-2, 0, 0), new IntVec3(-4, 0, 0), new IntVec3(-6, 0, 0),
                new IntVec3(2, 0, 0), new IntVec3(4, 0, 0), new IntVec3(6, 0, 0)
            };
            IntVec3 farSnoutCorpse = anchor + new IntVec3(-7, 0, -1); // adjacent to (-6, 0) collision cell, dist = 7.07 > snug (4.35)
            CellRect farCorpseRect = CellRect.SingleCell(farSnoutCorpse);
            Assert(HarmonyPatches_CombatAndHitbox.IsGiantHullInTouchRangeOfCells(anchor, elongatedOffsets, baseMelee, null, farCorpseRect),
                "Sanity check: outer collision cell at (-6,0) must be adjacent to (-7,-1)");
            Assert(!HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                anchor, anchor, isStationaryNonGotoToil: false, isMovingAtFinalPathNode: false,
                elongatedOffsets, maxCollisionHorizontalExtent: 6, baseMeleeTouchRadius: baseMelee, targetRect: farCorpseRect),
                "Toils_Goto must walk snugly closer instead of prematurely stopping 7 cells away on a tail/snout collision cell");

            // 2b. Tier-2 fallback path (e.g., corpse wedged behind thick-roof corner): remote LastNode check (NeedNewPath)
            //     and final-node arrival must succeed, and subsequent ChewIngestible must NEVER fail even after 180-deg rotation!
            Assert(HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                anchor, anchor + new IntVec3(5, 0, 0), isStationaryNonGotoToil: false, isMovingAtFinalPathNode: false,
                elongatedOffsets, maxCollisionHorizontalExtent: 6, baseMeleeTouchRadius: baseMelee, targetRect: farCorpseRect),
                "NeedNewPath LastNode validation must accept Tier-2 hull-touch corner cell");
            Assert(HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                anchor, anchor, isStationaryNonGotoToil: false, isMovingAtFinalPathNode: true,
                elongatedOffsets, maxCollisionHorizontalExtent: 6, baseMeleeTouchRadius: baseMelee, targetRect: farCorpseRect),
                "Final path node arrival must succeed at Tier-2 corner cell");

            // Rotate elongated offsets 90 deg (now north-south only, so NO collision cell is adjacent to (-7,-1)!)
            var rotatedOffsets90 = new List<IntVec3>
            {
                new IntVec3(0, 0, 0), new IntVec3(0, 0, -3), new IntVec3(0, 0, -6), new IntVec3(0, 0, 3), new IntVec3(0, 0, 6)
            };
            Assert(!HarmonyPatches_CombatAndHitbox.IsGiantHullInTouchRangeOfCells(anchor, rotatedOffsets90, baseMelee + 2.75f, null, farCorpseRect),
                "Sanity check: legacy fixed +2.75f slack failed after 90-deg rotation at 7.07 cells");
            Assert(HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                anchor, anchor, isStationaryNonGotoToil: true, isMovingAtFinalPathNode: false,
                rotatedOffsets90, maxCollisionHorizontalExtent: 6, baseMeleeTouchRadius: baseMelee, targetRect: farCorpseRect),
                "ChewIngestible stationary FailOnCannotTouch MUST remain true after rotating 90/180 degrees");

            // 2c. Full 360-degree heading sweep on real Rathalos footprint (both snug distance & outer collision boundary)
            IntVec3 snugCorpseCell = anchor + new IntVec3(-3, 0, -2); // dist = 3.61 <= snugRadius + 1.15
            CellRect snugCorpseRect = CellRect.SingleCell(snugCorpseCell);
            Assert(HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                anchor, anchor, isStationaryNonGotoToil: false, isMovingAtFinalPathNode: false,
                fpWest.localCollisionOffsets, fpWest.maxCollisionHorizontalExtent, baseMelee, snugCorpseRect),
                "Rathalos must cleanly arrive at snug mouth-over-corpse distance");

            IntVec3 outermostColOff = IntVec3.Zero;
            int maxOffSq = -1;
            for (int i = 0; i < fpWest.localCollisionOffsets.Count; i++)
            {
                IntVec3 off = fpWest.localCollisionOffsets[i];
                int sq = off.x * off.x + off.z * off.z;
                if (sq > maxOffSq)
                {
                    maxOffSq = sq;
                    outermostColOff = off;
                }
            }
            IntVec3 outerStep = new IntVec3(Math.Sign(outermostColOff.x), 0, Math.Sign(outermostColOff.z));
            if (outerStep == IntVec3.Zero) outerStep = new IntVec3(-1, 0, 0);
            CellRect outerBoundaryCorpseRect = CellRect.SingleCell(anchor + outermostColOff + outerStep);

            var fpRot = new GiantFootprintData();
            for (int deg = 0; deg < 360; deg += 30)
            {
                SkeletalKinematics.SolveWorldPoses(rathRig, rootXZ, deg, localPoses, missing, worldPoses);
                fpRot.Rebuild(rathRig, worldPoses, rathMasks, anchor, mapSize, collisionAnchorOverride: anchor);
                Assert(HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                    anchor, anchor, isStationaryNonGotoToil: true, isMovingAtFinalPathNode: false,
                    fpRot.localCollisionOffsets, fpRot.maxCollisionHorizontalExtent, baseMelee, snugCorpseRect, fpRot.hitCells),
                    $"Rathalos ChewIngestible failed FailOnCannotTouch on snug corpse at heading {deg} deg");
                Assert(HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallIngestTouchImmediate(
                    anchor, anchor, isStationaryNonGotoToil: true, isMovingAtFinalPathNode: false,
                    fpRot.localCollisionOffsets, fpRot.maxCollisionHorizontalExtent, baseMelee, outerBoundaryCorpseRect, fpRot.hitCells),
                    $"Rathalos ChewIngestible failed FailOnCannotTouch on outer collision-boundary corpse at heading {deg} deg");
            }

            Console.WriteLine($"       -> Verified downed-pawn collision immunity & Rathalos 360-deg Ingest touch-range stability (snug={snugRadius:F2}, maxOff={maxOffDist:F2}, stationary={stationaryRadius:F2})");
        }

        private static void TestConfigurablePainThresholdsZeroPainAndLethalCores()
        {
            // 1. Audit XML configurations & ConfigErrors across all 9 GiantRigDefs
            var (pzRig, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            var (scorpRig, _, _) = LoadMechScorpionFromXml();
            var (carrierRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            var (colS1Rig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (colS2Rig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var (colS3Rig, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");
            var (rathRig, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valRig, _, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");

            foreach (GiantRigDef r in new[] { pzRig, scorpRig, carrierRig, colS1Rig, colS2Rig, colS3Rig, rathRig, valRig })
            {
                var errs = r.ConfigErrors().ToList();
                Assert(errs.Count == 0, $"Expected 0 ConfigErrors on {r.defName}, got: {string.Join("; ", errs)}");
            }

            foreach (GiantRigDef zeroPainCoreRig in new[] { pzRig, scorpRig, carrierRig, colS1Rig, colS2Rig, colS3Rig })
            {
                Assert(zeroPainCoreRig.painImmune && zeroPainCoreRig.onlyDieWhenCoreDestroyed,
                    $"{zeroPainCoreRig.defName} must configure painImmune=true and onlyDieWhenCoreDestroyed=true");
            }

            // Negative ConfigErrors validation on lethalWhenDestroyed without linkedBodyPart and out-of-range threshold
            var badLethalRig = new GiantRigDef
            {
                defName = "GCF_TestBadLethalRig",
                painShockThresholdOverride = 1.35f,
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "root_hull", linkedBodyPart = new BodyPartDef { defName = "Torso" }, hideWhenMissing = false },
                    new BoneNodeDef { nodeId = "orphan_core", parentId = "root_hull", lethalWhenDestroyed = true, linkedBodyPart = null }
                }
            };
            var badErrs = badLethalRig.ConfigErrors().ToList();
            Assert(badErrs.Any(e => e.Contains("orphan_core", StringComparison.Ordinal) && e.Contains("lethalWhenDestroyed", StringComparison.Ordinal)),
                "ConfigErrors must catch <lethalWhenDestroyed>true</lethalWhenDestroyed> on a bone without <linkedBodyPart>");
            Assert(badErrs.Any(e => e.Contains("painShockThresholdOverride", StringComparison.Ordinal)),
                "ConfigErrors must catch out-of-range painShockThresholdOverride > 1.0");

            // Verify exposed lethalWhenDestroyed cores on ProtossCarrier (khaydarin_core) & MechColossus Stages 1-3 (GCF_MechReactorCore)
            Assert(carrierRig.LethalCoreNodeIndices.Length == 1 &&
                   carrierRig.SortedNodes[carrierRig.LethalCoreNodeIndices[0]].nodeId == "khaydarin_core",
                "ProtossCarrier must mark khaydarin_core as lethalWhenDestroyed");
            foreach (GiantRigDef colStageRig in new[] { colS1Rig, colS2Rig, colS3Rig })
            {
                Assert(colStageRig.LethalCoreNodeIndices.Length == 1 &&
                       colStageRig.SortedNodes[colStageRig.LethalCoreNodeIndices[0]].linkedBodyPart?.defName == "GCF_MechReactorCore",
                    $"{colStageRig.defName} must mark GCF_MechReactorCore bone as lethalWhenDestroyed");
            }
            Assert(scorpRig.LethalCoreNodeIndices.Length == 0,
                "MechScorpion keeps sole lethal core on carapace corePart");

            // 2. Live Pawn / CompGiantRig verification: Zero-pain & Core-Only Death on Entity (AbyssalDragonBeast) & Vehicles/Mechs
            static void EnsureBodyAllPartsCached(BodyDef bodyDef)
            {
                if (bodyDef?.corePart == null || (bodyDef.AllParts != null && bodyDef.AllParts.Count > 0))
                {
                    return;
                }
                var list = new List<BodyPartRecord>();
                static void Walk(BodyPartRecord r, List<BodyPartRecord> dst)
                {
                    if (r == null) return;
                    dst.Add(r);
                    if (r.parts == null) return;
                    for (int i = 0; i < r.parts.Count; i++) Walk(r.parts[i], dst);
                }
                Walk(bodyDef.corePart, list);
                FieldInfo cachedField = AccessTools.Field(typeof(BodyDef), "cachedAllParts");
                cachedField?.SetValue(bodyDef, list);
            }

            static (Pawn pawn, CompGiantRig comp) CreateTestGiantPawn(
                int id, string defName, GiantRigDef rigDef, BodyDef bodyDef, float baseHealthScale)
            {
                EnsureBodyAllPartsCached(bodyDef);
                var td = new ThingDef
                {
                    defName = defName,
                    shortHash = (ushort)(55000 + (id % 5000)),
                    race = new RaceProperties
                    {
                        body = bodyDef,
                        baseHealthScale = baseHealthScale
                    },
                    comps = new List<CompProperties> { new CompProperties_GiantRig { rigDef = rigDef } }
                };
                var p = new Pawn { thingIDNumber = id, def = td };
                p.health = new Pawn_HealthTracker(p);
                var c = new CompGiantRig { parent = p };
                c.Initialize(new CompProperties_GiantRig { rigDef = rigDef });
                c.ResolveBodyPartLinks();
                p.AllComps.Add(c);
                GiantFastLookup.Register(p, c);
                return (p, c);
            }

            BodyDef abyBody = LoadBodyDefFromXml("Bodies_MechScorpion.xml", "GCF_Body_MechScorpion");
            BodyDef carrierBody = LoadBodyDefFromXml("Bodies_ProtossCarrier.xml", "GCF_Body_ProtossCarrier");
            BodyDef colBody = LoadBodyDefFromXml("Bodies_MechColossus.xml", "GCF_Body_MechColossus");

            var (abyPawn, abyComp) = CreateTestGiantPawn(999101, "GCF_MechScorpion", scorpRig, abyBody, 5.0f);
            var (carrierPawn, carrierComp) = CreateTestGiantPawn(999102, "GCF_ProtossCarrier", carrierRig, carrierBody, 9.5f);
            var (colPawn, colComp) = CreateTestGiantPawn(999103, "GCF_MechColossus", colS1Rig, colBody, 6.5f);
            try
            {
                // (a) MechScorpion: 0 pain, 0 bleed, survives severing stinger + 3 legs without dying or getting downed
                Assert(GiantCombatMechanicsUtility.IsPainImmuneGiant(abyPawn, abyComp), "MechScorpion must be pain-immune");
                float prefixPain = 0.77f;
                bool runOrigPain = HarmonyPatches_CombatAndHitbox.HediffSet_CalculatePain_Prefix(abyPawn.health.hediffSet, abyPawn, ref prefixPain);
                Assert(!runOrigPain && prefixPain == 0f, "HediffSet_CalculatePain_Prefix must short-circuit to 0f for MechScorpion");

                bool inShock = true;
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_InPainShock_Postfix(abyPawn, ref inShock);
                Assert(!inShock, "MechScorpion must never enter InPainShock");

                bool canBleed = true;
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_CanBleed_Postfix(abyPawn, ref canBleed);
                Assert(!canBleed, "MechScorpion with onlyDieWhenCoreDestroyed must disable bleeding");

                foreach (string severNodeId in new[] { "tail_stinger", "leg_l1", "leg_r1", "leg_l2" })
                {
                    Assert(scorpRig.TryGetNodeIndex(severNodeId, out int sIdx), $"Missing node {severNodeId}");
                    BodyPartRecord partRec = abyComp.GetLinkedBodyPartRaw(sIdx);
                    Assert(partRec != null, $"Unresolved BodyPartRecord for {severNodeId}");
                    abyPawn.health.hediffSet.hediffs.Add(new Hediff_MissingPart { pawn = abyPawn, Part = partRec, def = new HediffDef { defName = "MissingBodyPart" } });
                }
                Assert(abyComp.CountSeveredBones() >= 4, "Expected >= 4 severed bones on MechScorpion");
                Assert(GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(abyPawn, abyComp),
                    "MechScorpion with onlyDieWhenCoreDestroyed must resist cumulative scratch death even after >= 4 limbs/tail are severed");
                bool downedCheck = true;
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_ShouldBeDowned_CoreOnly_Postfix(abyPawn, ref downedCheck);
                Assert(!downedCheck, "MechScorpion must not become Downed while its carapace core is intact");

                abyPawn.health.hediffSet.hediffs.Add(new Hediff_MissingPart { pawn = abyPawn, Part = abyBody.corePart, def = new HediffDef { defName = "MissingBodyPart" } });
                Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(abyPawn, abyComp),
                    "Destroying MechScorpion carapace corePart must immediately allow death");

                // (b) ProtossCarrier: destroying khaydarin_core (lethalWhenDestroyed=true) immediately triggers ShouldBeDead even with intact hull
                Assert(!GiantCombatMechanicsUtility.HasDestroyedLethalCoreBone(carrierPawn, carrierComp),
                    "Intact ProtossCarrier must have HasDestroyedLethalCoreBone == false");
                int khayIdx = carrierRig.LethalCoreNodeIndices[0];
                BodyPartRecord khayRec = carrierComp.GetLinkedBodyPartRaw(khayIdx);
                Assert(khayRec != null && khayRec != carrierBody.corePart, "khaydarin_core must link to GCF_CarrierKhaydarinCore distinct from hull corePart");
                carrierPawn.health.hediffSet.hediffs.Add(new Hediff_MissingPart { pawn = carrierPawn, Part = khayRec, def = new HediffDef { defName = "MissingBodyPart" } });

                Assert(GiantCombatMechanicsUtility.HasDestroyedLethalCoreBone(carrierPawn, carrierComp),
                    "Destroying khaydarin_core must trigger HasDestroyedLethalCoreBone == true");
                bool shouldDieCarrier = false;
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_ShouldBeDead_LethalCore_Postfix(carrierPawn, ref shouldDieCarrier);
                Assert(shouldDieCarrier, "Destroying khaydarin_core must immediately set ShouldBeDead = true regardless of remaining hull HP");
                Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(carrierPawn, carrierComp),
                    "Destroyed lethalWhenDestroyed bone must lift premature-lethal-death guard");
                AssertNear(GiantBossHealthBarHUD.ComputeSynchronizedGiantHealthPercent(carrierPawn, carrierComp), 0f, 1e-5f,
                    "Boss health bar must drop to 0% immediately when lethalWhenDestroyed core bone is destroyed");

                // (c) MechColossus: destroying GCF_MechReactorCore triggers ShouldBeDead (for Stage 1->2 intercept or Stage 3 kill), suppressed during active morph
                int reactorIdx = colS1Rig.LethalCoreNodeIndices[0];
                BodyPartRecord reactorRec = colComp.GetLinkedBodyPartRaw(reactorIdx);
                Assert(reactorRec != null, "Missing GCF_MechReactorCore record on MechColossus");
                colPawn.health.hediffSet.hediffs.Add(new Hediff_MissingPart { pawn = colPawn, Part = reactorRec, def = new HediffDef { defName = "MissingBodyPart" } });

                bool shouldDieCol = false;
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_ShouldBeDead_LethalCore_Postfix(colPawn, ref shouldDieCol);
                Assert(shouldDieCol, "Destroying GCF_MechReactorCore must set ShouldBeDead = true so Stage 1/2 transforms or Stage 3 dies");

                // Verify vehicle zero-pain fallback even if an authored vehicle uses an organic default RaceProperties
                Assert(GiantCombatMechanicsUtility.IsPainImmuneGiantConfig(pzRig, isVehicle: true, isFlesh: true, isMechanoid: false),
                    "Any vehicle unit must be pain-immune even if RaceProps.IsFlesh defaulted to true");
                Assert(GiantCombatMechanicsUtility.IsPainImmuneGiantConfig(new GiantRigDef { painImmune = false }, isVehicle: false, isFlesh: false, isMechanoid: true),
                    "Any mechanoid unit must be pain-immune automatically");
            }
            finally
            {
                GiantFastLookup.Unregister(abyPawn);
                GiantFastLookup.Unregister(carrierPawn);
                GiantFastLookup.Unregister(colPawn);
            }

            // 3. Biological Animal Giants (Rathalos vs Elder Dragon Valstrax): Differentiated Pain Scaling & Unsevered Structural Shock Gate
            Assert(!rathRig.painImmune && !valRig.painImmune, "Biological Rathalos and Valstrax must retain biological pain (painImmune=false)");
            Assert(valRig.painScaleFactor < rathRig.painScaleFactor &&
                   valRig.painShockThresholdOverride > rathRig.painShockThresholdOverride &&
                   valRig.minSeveredBonesForPainShock > rathRig.minSeveredBonesForPainShock &&
                   valRig.unseveredPainShockMaxHealthPct < rathRig.unseveredPainShockMaxHealthPct,
                "Elder Dragon Valstrax must configure stricter pain resistance & tougher shock gates than standard wyvern Rathalos");

            var rathCompMock = new CompGiantRig();
            rathCompMock.Initialize(new CompProperties_GiantRig { rigDef = rathRig });
            var valCompMock = new CompGiantRig();
            valCompMock.Initialize(new CompProperties_GiantRig { rigDef = valRig });

            float rathDiv = GiantCombatMechanicsUtility.ComputeGiantPainNormalizationDivisor(rathCompMock, corePartBaseHp: 140f);
            float valDiv = GiantCombatMechanicsUtility.ComputeGiantPainNormalizationDivisor(valCompMock, corePartBaseHp: 155f);
            Assert(rathDiv >= 11.5f && valDiv > rathDiv, $"Expected skeletal pain divisors rath={rathDiv:F2}, val={valDiv:F2}");

            // At rawInjuryPainOffsetSum = 3.5 (3.5x vanilla human coma pain, ~4,300+ HP distributed scratches, 0 parts broken, 72% Boss HP):
            float rathModeratePain = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                rathRig, isPainImmune: false, rawInjuryPainOffsetSum: 3.5f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: rathDiv,
                effectivePainShockThreshold: rathRig.painShockThresholdOverride,
                severedBoneCount: 0, synchronizedHealthPct: 0.72f);
            float valModeratePain = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                valRig, isPainImmune: false, rawInjuryPainOffsetSum: 3.5f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: valDiv,
                effectivePainShockThreshold: valRig.painShockThresholdOverride,
                severedBoneCount: 0, synchronizedHealthPct: 0.72f);
            Assert(rathModeratePain > 0.15f && rathModeratePain < 0.35f,
                $"Rathalos moderate multi-limb scratch pain should be ~0.25 (well below 0.90 shock), got {rathModeratePain:F3}");
            Assert(valModeratePain > 0.08f && valModeratePain < rathModeratePain,
                $"Valstrax pain ({valModeratePain:F3}) must be strictly lower than Rathalos ({rathModeratePain:F3}) at equal injury load");

            // Extreme unsevered wound load (raw=18.0, 0 severed bones, 45% Boss HP): NEVER crosses PainShockThreshold!
            float rathUnseveredClamped = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                rathRig, isPainImmune: false, rawInjuryPainOffsetSum: 18.0f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: rathDiv,
                effectivePainShockThreshold: rathRig.painShockThresholdOverride,
                severedBoneCount: 0, synchronizedHealthPct: 0.45f);
            Assert(rathUnseveredClamped < rathRig.painShockThresholdOverride,
                $"Unsevered Rathalos at 45% HP must never suffer wound pain shock ({rathUnseveredClamped:F3} vs threshold {rathRig.painShockThresholdOverride:F2})");

            // Once 1 bone is severed on Rathalos (>= minSeveredBonesForPainShock=1), extreme wound load CAN shock Rathalos,
            // whereas Valstrax (minSeveredBonesForPainShock=3) STILL resists wound pain shock until >= 3 bones are severed!
            float rathOneSeverPain = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                rathRig, isPainImmune: false, rawInjuryPainOffsetSum: 18.0f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: rathDiv,
                effectivePainShockThreshold: rathRig.painShockThresholdOverride,
                severedBoneCount: 1, synchronizedHealthPct: 0.45f);
            float valOneSeverPain = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                valRig, isPainImmune: false, rawInjuryPainOffsetSum: 26.0f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: valDiv,
                effectivePainShockThreshold: valRig.painShockThresholdOverride,
                severedBoneCount: 1, synchronizedHealthPct: 0.45f);
            float valTwoSeverPain = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                valRig, isPainImmune: false, rawInjuryPainOffsetSum: 26.0f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: valDiv,
                effectivePainShockThreshold: valRig.painShockThresholdOverride,
                severedBoneCount: 2, synchronizedHealthPct: 0.45f);
            float valThreeSeverPain = GiantCombatMechanicsUtility.EvaluateGiantNormalizedPain(
                valRig, isPainImmune: false, rawInjuryPainOffsetSum: 40.0f, nonInjuryPainOffsetSum: 0f,
                combinedPainFactorProduct: 1f, painNormalizationDivisor: valDiv,
                effectivePainShockThreshold: valRig.painShockThresholdOverride,
                severedBoneCount: 3, synchronizedHealthPct: 0.45f);

            Assert(rathOneSeverPain >= rathRig.painShockThresholdOverride,
                $"Rathalos with 1 severed bone under extreme load should cross 0.90 shock threshold, got {rathOneSeverPain:F3}");
            Assert(valOneSeverPain < valRig.painShockThresholdOverride,
                $"Valstrax with only 1 severed bone (< minSeveredBonesForPainShock=3) at 45% HP must still resist wound pain shock, got {valOneSeverPain:F3}");
            Assert(valTwoSeverPain < valRig.painShockThresholdOverride,
                $"Valstrax with 2 severed bones (< minSeveredBonesForPainShock=3) at 45% HP must still resist wound pain shock, got {valTwoSeverPain:F3}");
            Assert(valThreeSeverPain >= valRig.painShockThresholdOverride,
                $"Valstrax with 3 severed bones under extreme load should cross 0.96 shock threshold, got {valThreeSeverPain:F3}");

            // 4. Multi-bone peripheral-break premature LethalDamageThreshold guard (Valstrax 3x JetLance break at ~60% Boss HP)
            Assert(GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(
                    corePartHpPct: 0.82f, severedBoneCount: 3, totalSeverableBones: 45, synchronizedHealthPct: 0.60f),
                "4-arg premature lethal guard must protect Valstrax with 3 severed peripheral bones when core=82% and syncedHP=60%");
            Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(
                    corePartHpPct: 0.18f, severedBoneCount: 3, totalSeverableBones: 45, synchronizedHealthPct: 0.60f),
                "4-arg premature lethal guard must yield once core HP drops <= 18%");
            Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(
                    corePartHpPct: 0.82f, severedBoneCount: 3, totalSeverableBones: 45, synchronizedHealthPct: 0.18f),
                "4-arg premature lethal guard must yield once synchronized Boss HP drops <= 18% with >= 2 severed bones");

            BodyDef valBody = LoadBodyDefFromXml("Bodies_Valstrax.xml", "GCF_Body_Valstrax");
            var (valPawn, valComp) = CreateTestGiantPawn(999104, "GCF_Valstrax", valRig, valBody, 17.5f);
            valPawn.def.race.lifeStageAges = new List<LifeStageAge>
            {
                new LifeStageAge
                {
                    minAge = 0f,
                    def = new RimWorld.LifeStageDef { defName = "ElderDragonAdult", healthScaleFactor = 1f, bodySizeFactor = 1f }
                }
            };
            valPawn.ageTracker = new Pawn_AgeTracker(valPawn);
            typeof(Pawn_AgeTracker).GetField("cachedLifeStageIndex", BindingFlags.Instance | BindingFlags.NonPublic)?.SetValue(valPawn.ageTracker, 0);
            FieldInfo hediffSevField = AccessTools.Field(typeof(Hediff), "severityInt");
            Hediff_Injury MakeTestInjury(Pawn owner, BodyPartRecord part, float sev)
            {
                var inj = new Hediff_Injury
                {
                    pawn = owner,
                    Part = part,
                    def = new HediffDef { defName = "Cut", maxSeverity = float.MaxValue }
                };
                hediffSevField.SetValue(inj, sev);
                return inj;
            }

            try
            {
                // Verify multi-bone bleed normalization & vanilla 50% animal DeathOnDowned suppression
                Assert(AccessTools.Method(typeof(HediffSet), "CalculateBleedRate") != null
                    && AccessTools.Method(typeof(Pawn_HealthTracker), nameof(Pawn_HealthTracker.CheckForStateChange)) != null,
                    "RimWorld 1.7 HediffSet.CalculateBleedRate and Pawn_HealthTracker.CheckForStateChange patch targets must resolve");

                float rawValBleed = 27.1f;
                HarmonyPatches_CombatAndHitbox.HediffSet_CalculateBleedRate_Postfix(valPawn, ref rawValBleed);
                AssertNear(rawValBleed, 27.1f / valDiv, 1e-4f,
                    "Valstrax multi-bone bleed rate must divide by ComputeGiantPainNormalizationDivisor (~13.29) to prevent 60%-HP BloodLoss coma");

                Assert(GiantCombatMechanicsUtility.ShouldSuppressRandomDeathOnDowned(valRig),
                    "Valstrax must suppress random 50% animal DeathOnDowned so downedAnim plays cleanly");
                Assert(valPawn.health.overrideDeathOnDownedChance < 0f, "Unpatched Pawn_HealthTracker defaults overrideDeathOnDownedChance to -1f");
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_CheckForStateChange_Prefix(valPawn.health, valPawn);
                AssertNear(valPawn.health.overrideDeathOnDownedChance, 0f, 1e-5f,
                    "CheckForStateChange_Prefix / EnsureGiantDeathOnDownedSuppressed must clamp overrideDeathOnDownedChance to 0f");
                valPawn.health.overrideDeathOnDownedChance = 0.25f;
                GiantCombatMechanicsUtility.EnsureGiantDeathOnDownedSuppressed(valPawn, valComp);
                AssertNear(valPawn.health.overrideDeathOnDownedChance, 0.25f, 1e-5f,
                    "Explicit non-negative overrideDeathOnDownedChance must not be overwritten");
                valPawn.health.overrideDeathOnDownedChance = 0f;

                foreach (string lanceId in new[] { "wing_lance_outer_left", "wing_lance_mid_left", "wing_lance_outer_right" })
                {
                    Assert(valRig.TryGetNodeIndex(lanceId, out int lIdx), $"Missing Valstrax bone {lanceId}");
                    BodyPartRecord lanceRec = valComp.GetLinkedBodyPartRaw(lIdx);
                    Assert(lanceRec != null, $"Unresolved BodyPartRecord for {lanceId}");
                    valPawn.health.hediffSet.hediffs.Add(new TestFreshMissingPartHediff
                    {
                        pawn = valPawn,
                        Part = lanceRec,
                        def = new HediffDef { defName = "MissingBodyPart" },
                        MockPainOffset = 0.30f
                    });
                }
                Assert(valComp.CountSeveredBones() == 3, $"Expected 3 severed peripheral jet-lance bones, got {valComp.CountSeveredBones()}");

                float freshAmputationPain = GiantCombatMechanicsUtility.CalculateGiantPain(valPawn, valPawn.health.hediffSet, valComp);
                Assert(freshAmputationPain > 0.01f && freshAmputationPain < 0.10f && freshAmputationPain < valRig.painShockThresholdOverride,
                    $"3 freshly severed 30-HP JetLances (3x +0.30 PainOffset) must be normalized by painNormalizationDivisor & painScaleFactor instead of triggering 84%-HP PainShock, got {freshAmputationPain:F4}");

                Assert(valRig.TryGetNodeIndex("wing_shoulder_left", out int wShIdx), "Missing wing_shoulder_left");
                BodyPartRecord wShPart = valComp.GetLinkedBodyPartRaw(wShIdx);
                valPawn.health.hediffSet.hediffs.Add(MakeTestInjury(valPawn, valBody.corePart, 500f));
                valPawn.health.hediffSet.hediffs.Add(MakeTestInjury(valPawn, wShPart, 812.5f));

                float valCorePctMid = valPawn.health.hediffSet.GetPartHealth(valBody.corePart) / valBody.corePart.def.GetMaxHealth(valPawn);
                float valSyncedMid = GiantBossHealthBarHUD.ComputeSynchronizedGiantHealthPercent(valPawn, valComp);
                Assert(valCorePctMid > 0.50f && valSyncedMid > 0.55f && valSyncedMid < 0.65f,
                    $"Expected Valstrax mid-fight state corePct > 0.50 and syncedHpPct ~ 0.60, got core={valCorePctMid:F3}, synced={valSyncedMid:F3}");
                Assert(GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(valPawn, valComp),
                    $"Valstrax at {valSyncedMid:P1} Boss HP (core={valCorePctMid:P1}) with 3 severed peripheral jet-lances must NOT die from premature LethalDamageThreshold");

                bool shouldDieMid = true;
                HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_ShouldBeDeadFromLethalDamageThreshold_Postfix(valPawn, ref shouldDieMid);
                Assert(!shouldDieMid, "Harmony Postfix must suppress ShouldBeDeadFromLethalDamageThreshold while Valstrax core & Boss HP remain > 18%");

                // Crossing LethalDamageThreshold while core & anatomical HP remain high (> 50%) must still hold Boss HP >= 20% (> 18%) and prevent instant death
                Assert(valRig.TryGetNodeIndex("wing_shoulder_right", out int wShRIdx), "Missing wing_shoulder_right");
                Hediff_Injury extraWingInj = MakeTestInjury(valPawn, valComp.GetLinkedBodyPartRaw(wShRIdx), 1600f);
                valPawn.health.hediffSet.hediffs.Add(extraWingInj);
                Assert(GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(valPawn, valComp),
                    "Valstrax exceeding cumulative LethalDamageThreshold with intact core & high anatomical HP must still resist instant threshold death");

                // Once thorax core drops <= 18% HP, the guard yields false
                Hediff_Injury heavyCoreInj = MakeTestInjury(valPawn, valBody.corePart, 1800f);
                valPawn.health.hediffSet.hediffs.Add(heavyCoreInj);
                float valCorePctLow = valPawn.health.hediffSet.GetPartHealth(valBody.corePart) / valBody.corePart.def.GetMaxHealth(valPawn);
                Assert(valCorePctLow <= 0.18f, $"Expected battered corePct <= 0.18, got {valCorePctLow:F3}");
                Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(valPawn, valComp),
                    "Premature lethal guard must yield false once thorax core HP drops <= 18%");

                // Restore thorax core (> 50% HP) and batter non-core body parts until syncedHpPct <= 0.18f -> guard yields false
                valPawn.health.hediffSet.hediffs.Remove(heavyCoreInj);
                foreach (BodyPartRecord bp in valBody.AllParts)
                {
                    if (bp == null || bp == valBody.corePart || valPawn.health.hediffSet.PartIsMissing(bp))
                    {
                        continue;
                    }
                    float rem = valPawn.health.hediffSet.GetPartHealth(bp);
                    if (rem > 2f)
                    {
                        valPawn.health.hediffSet.hediffs.Add(MakeTestInjury(valPawn, bp, rem * 0.94f));
                    }
                }
                float valSyncedCrit = GiantBossHealthBarHUD.ComputeSynchronizedGiantHealthPercent(valPawn, valComp);
                Assert(valSyncedCrit <= 0.18f, $"Expected critical Valstrax syncedHpPct <= 0.18, got {valSyncedCrit:F3}");
                Assert(!GiantCombatMechanicsUtility.ShouldPreventPrematureLethalThresholdDeath(valPawn, valComp),
                    $"Premature lethal guard must yield false once Valstrax syncedHpPct ({valSyncedCrit:F3}) drops <= 0.18 with 3 severed bones");
            }
            finally
            {
                GiantFastLookup.Unregister(valPawn);
            }

            Console.WriteLine(
                $"       -> Verified 0-pain & core-only lethality (PanzerIV/MechScorpion/Carrier/MechColossus/AbyssalDragonBeast), lethalWhenDestroyed cores, biological pain scaling (Rathalos={rathModeratePain:F2}->{rathUnseveredClamped:F2}/{rathOneSeverPain:F2}, Valstrax={valModeratePain:F2}->{valOneSeverPain:F2}/{valTwoSeverPain:F2}/{valThreeSeverPain:F2}), & multi-sever premature-lethal guard");
        }

        private static void TestGiantArenaPresetsConfigCliCameraAndBridgeTools()
        {
            // 1. Built-in presets catalog
            var presets = GiantArenaMapPresets.ListPresets();
            Assert(presets.Count == 5, $"Expected 5 arena presets, got {presets.Count}");
            Assert(GiantArenaMatchConfig.ResolvePresetId("colosseum") == GiantArenaPresetId.Colosseum, "Colosseum alias failed");
            Assert(GiantArenaMatchConfig.ResolvePresetId("volcanic") == GiantArenaPresetId.VolcanicBasalt, "Volcanic alias failed");
            Assert(GiantArenaMatchConfig.ResolvePresetId("desert_ruins") == GiantArenaPresetId.DesertRuins, "DesertRuins alias failed");
            Assert(GiantArenaMatchConfig.ResolvePresetId("frost") == GiantArenaPresetId.Tundra, "Tundra alias failed");
            Assert(GiantArenaMatchConfig.ResolvePresetId("meadow") == GiantArenaPresetId.Plains, "Plains alias failed");

            // 2. CLI compact spec parsing: KindA:KindB:Preset:CountAxCountB:Separation:StartPaused
            bool okCli = GiantArenaMatchConfig.TryExtractFromCommandLine(
                new[] { "RimWorldWin64.exe", "-fast", "-quicktest", "-gcfarena=GCF_Rathalos:GCF_Valstrax:VolcanicBasalt:1x2:38:false" },
                envSpec: null,
                out GiantArenaMatchConfig cliCfg,
                out string cliSrc,
                out string cliErr);
            Assert(okCli && string.IsNullOrEmpty(cliErr), $"CLI parse failed: {cliErr}");
            Assert(cliSrc == "cli", $"Expected source=cli, got {cliSrc}");
            Assert(cliCfg.SideAKind == "GCF_Rathalos" && cliCfg.SideBKind == "GCF_Valstrax", "Side kinds mismatch");
            Assert(cliCfg.Preset == "VolcanicBasalt", $"Expected VolcanicBasalt, got {cliCfg.Preset}");
            Assert(cliCfg.SideACount == 1 && cliCfg.SideBCount == 2, $"Expected 1x2, got {cliCfg.SideACount}x{cliCfg.SideBCount}");
            Assert(cliCfg.SpawnSeparation == 38 && !cliCfg.StartPaused, "Separation / StartPaused mismatch");

            // 3. Inline JSON & file JSON parsing + clamping
            string tmpJson = Path.Combine(Path.GetTempPath(), $"gcf_arena_test_{Guid.NewGuid():N}.json");
            try
            {
                File.WriteAllText(tmpJson, "{\"sideAKind\":\"GCF_AbyssalDragonBeast\",\"sideBKind\":\"GCF_MechColossus\",\"preset\":\"DesertRuins\",\"sideACount\":99,\"spawnSeparation\":5}");
                bool okFile = GiantArenaMatchConfig.TryExtractFromCommandLine(
                    new[] { "RimWorldWin64.exe", "-gcfarena", tmpJson },
                    envSpec: null,
                    out GiantArenaMatchConfig fileCfg,
                    out string fileSrc,
                    out string fileErr);
                Assert(okFile && string.IsNullOrEmpty(fileErr) && fileSrc == "cli", $"JSON file parse failed: {fileErr}");
                Assert(fileCfg.SideAKind == "GCF_AbyssalDragonBeast" && fileCfg.SideBKind == "GCF_MechColossus", "JSON kinds mismatch");
                Assert(fileCfg.SideACount == 8, $"Expected SideACount clamped to 8, got {fileCfg.SideACount}");
                Assert(fileCfg.SpawnSeparation == 12, $"Expected SpawnSeparation clamped to 12, got {fileCfg.SpawnSeparation}");
            }
            finally
            {
                if (File.Exists(tmpJson)) File.Delete(tmpJson);
            }

            // 4. Dynamic camera bounds math
            GiantArenaCameraRecommendation closeCam = GiantArenaService.ComputeCameraFromBounds(
                minX: 95f, maxX: 105f, minZ: 95f, maxZ: 105f,
                paddingCells: 10f, minRootSize: 15f, maxRootSize: 46f, aspectRatio: 16f / 9f);
            GiantArenaCameraRecommendation wideCam = GiantArenaService.ComputeCameraFromBounds(
                minX: 70f, maxX: 130f, minZ: 90f, maxZ: 110f,
                paddingCells: 10f, minRootSize: 15f, maxRootSize: 46f, aspectRatio: 16f / 9f);
            Assert(Mathf.Approximately(closeCam.CenterX, 100f) && Mathf.Approximately(closeCam.CenterZ, 100f), "Close cam center mismatch");
            Assert(wideCam.RootSize > closeCam.RootSize, $"Wide battle span must zoom out more than close span ({wideCam.RootSize:F2} vs {closeCam.RootSize:F2})");
            Assert(wideCam.RootSize <= 46.01f && closeCam.RootSize >= 14.99f, "Camera rootSize out of clamp bounds");

            // 5. Verify ForceProvokeTarget, Giant Ranged minRange Slant Distance & GiantArenaBridgeTools DLL
            Assert(typeof(CompGiantRig).GetMethod(nameof(CompGiantRig.ForceProvokeTarget)) != null, "CompGiantRig.ForceProvokeTarget missing");
            float normalMinDist = GiantPartCombatRuntime.ComputeEffectiveRangedMinRangeDistance(4.2f, 4.2f, targetIsGiant: false, targetIsAirborne: false);
            float groundGiantMinDist = GiantPartCombatRuntime.ComputeEffectiveRangedMinRangeDistance(4.5f, 10.5f, targetIsGiant: true, targetIsAirborne: false);
            float airGiantMinDist = GiantPartCombatRuntime.ComputeEffectiveRangedMinRangeDistance(3.0f, 6.0f, targetIsGiant: true, targetIsAirborne: true);
            AssertNear(normalMinDist, 4.2f, 0.01f, "Non-giant target minRange distance must stay unchanged");
            Assert(groundGiantMinDist >= 10.49f, $"Grounded giant torso at 10.5 cells must clear 7.5 minRange despite outstretched wingtip at 4.5, got {groundGiantMinDist:F2}");
            Assert(airGiantMinDist >= 8.0f, $"Airborne giant at 6.0 horizontal + 5.5 altitude must clear 7.5 minRange via 3D slant, got {airGiantMinDist:F2}");
            string bridgeDll = Path.Combine(ModRoot, ".verify", "isolated_rw_host", "BridgeTools", "GiantCreatureFramework", "GiantCreatureFramework.Arena.BridgeTools.dll");
            string bridgeProj = Path.Combine(ModRoot, "Source", "GiantCreatureFramework.Arena.BridgeTools", "GiantCreatureFramework.Arena.BridgeTools.csproj");
            Assert(File.Exists(bridgeDll) || File.Exists(bridgeProj), $"Arena BridgeTools project or DLL missing at {bridgeProj}");

            // 6. Verify continuous C1 critically-damped camera smoothing (zero integer snapping, monotonic convergence, zoom deadzone)
            bool hasCamState = false;
            float camX = 0f, camZ = 0f, camSize = 0f, camVx = 0f, camVz = 0f, camVs = 0f;
            GiantArenaService.StepArenaCameraSmoothing(100f, 100f, 22f, smoothFactor: 1.0f, dtSeconds: 1f / 60f, ref hasCamState, ref camX, ref camZ, ref camSize, ref camVx, ref camVz, ref camVs);
            Assert(hasCamState, "Initial camera snap must initialize state");
            AssertNear(camX, 100f, 1e-4f, "Initial snap X");
            AssertNear(camSize, 22f, 1e-4f, "Initial snap Size");

            float prevX = camX;
            float prevSize = camSize;
            float maxSingleStepX = 0f;
            int subCellStepCount = 0;
            for (int f = 0; f < 60; f++)
            {
                GiantArenaService.StepArenaCameraSmoothing(112f, 108f, 28f, smoothFactor: 0.07f, dtSeconds: 1f / 60f, ref hasCamState, ref camX, ref camZ, ref camSize, ref camVx, ref camVz, ref camVs);
                float dx = camX - prevX;
                float ds = camSize - prevSize;
                Assert(dx > 0f && camX <= 112.001f, $"Camera X must converge monotonically without overshoot (frame {f}: {prevX:F4} -> {camX:F4})");
                Assert(ds >= 0f && camSize <= 28.001f, $"Camera Size must converge monotonically without overshoot (frame {f}: {prevSize:F4} -> {camSize:F4})");
                if (dx > 0.001f && dx < 0.45f) subCellStepCount++;
                if (dx > maxSingleStepX) maxSingleStepX = dx;
                prevX = camX;
                prevSize = camSize;
            }
            Assert(subCellStepCount >= 50, $"Expected smooth sub-cell camera steps across 60fps pan, got {subCellStepCount}/60");
            Assert(maxSingleStepX < 0.45f, $"Max single-frame pan step must stay silky smooth (<0.45 cells/frame), got {maxSingleStepX:F4}");
            Assert(camX > 106f && camSize > 24.5f, $"Camera should smoothly advance toward target within 1.0s (got X={camX:F2}, Size={camSize:F2})");

            // Zoom micro-deadzone: < 0.25 cell jitter should not trigger zoom drift
            bool deadState = true;
            float deadX = 100f, deadZ = 100f, deadSize = 24f, deadVx = 0f, deadVz = 0f, deadVs = 0f;
            GiantArenaService.StepArenaCameraSmoothing(100f, 100f, 24.15f, smoothFactor: 0.07f, dtSeconds: 1f / 60f, ref deadState, ref deadX, ref deadZ, ref deadSize, ref deadVx, ref deadVz, ref deadVs);
            AssertNear(deadSize, 24f, 1e-4f, "Sub-0.25 cell zoom jitter must be absorbed by deadzone");

            // 7. Verify Arena Ability Bar layout geometry (left bar left-aligned, right bar right-aligned, clean wrapping)
            Rect left0 = GiantBossHealthBarHUD.ComputeArenaAbilitySlotRect(320f, 440f, 100f, alignRight: false, slotIndex: 0, totalCount: 5, slotSize: 64f, slotGap: 6f, rowExtraVerticalGap: 16f, out int maxRowL);
            Rect left4 = GiantBossHealthBarHUD.ComputeArenaAbilitySlotRect(320f, 440f, 100f, alignRight: false, slotIndex: 4, totalCount: 5, slotSize: 64f, slotGap: 6f, rowExtraVerticalGap: 16f, out _);
            Assert(maxRowL == 6, $"Expected 6 slots per 440px row at 64+6px, got {maxRowL}");
            AssertNear(left0.x, 320f, 0.5f, "Left ability bar slot 0 must align flush-left with left health bar");
            AssertNear(left4.x, 320f + 4f * 70f, 0.5f, "Left ability bar slot 4 spacing mismatch");

            Rect right0 = GiantBossHealthBarHUD.ComputeArenaAbilitySlotRect(840f, 440f, 100f, alignRight: true, slotIndex: 0, totalCount: 5, slotSize: 64f, slotGap: 6f, rowExtraVerticalGap: 16f, out _);
            Rect right4 = GiantBossHealthBarHUD.ComputeArenaAbilitySlotRect(840f, 440f, 100f, alignRight: true, slotIndex: 4, totalCount: 5, slotSize: 64f, slotGap: 6f, rowExtraVerticalGap: 16f, out _);
            AssertNear(right4.xMax, 840f + 440f, 0.5f, "Right ability bar last slot must align flush-right with right health bar");
            AssertNear(right0.x, (840f + 440f) - (5f * 64f + 4f * 6f), 0.5f, "Right ability bar slot 0 origin mismatch");

            Rect rightWrapRow2 = GiantBossHealthBarHUD.ComputeArenaAbilitySlotRect(840f, 440f, 100f, alignRight: true, slotIndex: 6, totalCount: 7, slotSize: 64f, slotGap: 6f, rowExtraVerticalGap: 16f, out _);
            AssertNear(rightWrapRow2.xMax, 840f + 440f, 0.5f, "Wrapped row 2 on right side must also align flush-right");
            Assert(rightWrapRow2.y > right0.y + 64f, "Wrapped row 2 must sit cleanly below row 1");

            // 8. Verify raid-points army config parsing and clamping
            bool okRaid = GiantArenaMatchConfig.TryParseSpecOrFile(
                "{\"sideARaidPoints\":5000,\"sideAVanillaOnly\":true,\"sideAFactionDef\":\"Mechanoid\",\"sideBKind\":\"GCF_Rathalos\"}",
                out GiantArenaMatchConfig raidCfg,
                out string raidErr);
            Assert(okRaid && string.IsNullOrEmpty(raidErr), $"Raid JSON parse failed: {raidErr}");
            AssertNear(raidCfg.SideARaidPoints, 5000f, 1e-3f, "SideARaidPoints mismatch");
            Assert(raidCfg.SideAVanillaOnly && raidCfg.SideAFactionDef == "Mechanoid" && raidCfg.SideBKind == "GCF_Rathalos", "Raid config fields mismatch");

            // 9. Verify strict zero-intrusion into normal RimWorld gameplay when Arena is unused
            Type arenaPatchType = typeof(GiantArenaService).Assembly.GetType("GiantCreatureFramework.HarmonyPatches_GiantArena");
            Assert(arenaPatchType != null, "HarmonyPatches_GiantArena type must exist");
            Assert(arenaPatchType.GetCustomAttributes(typeof(HarmonyPatch), inherit: true).Length == 0,
                "HarmonyPatches_GiantArena class must NOT carry [HarmonyPatch] attributes (must never auto-patch at mod startup)");
            foreach (MethodInfo m in arenaPatchType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.DeclaredOnly))
            {
                Assert(m.GetCustomAttributes(typeof(HarmonyPatch), inherit: true).Length == 0,
                    $"HarmonyPatches_GiantArena.{m.Name} must NOT carry [HarmonyPatch] attributes");
            }
            bool isPatched = (bool)arenaPatchType.GetProperty("IsPatched", BindingFlags.Public | BindingFlags.Static)!.GetValue(null)!;
            Assert(!isPatched, "HarmonyPatches_GiantArena.IsPatched must remain false when Arena has not been activated");
            Assert(!GiantArenaService.IsArenaActive && !GiantArenaService.IsCleanVideoMode && !GiantArenaService.IsCinematicHudOnly && !GiantArenaService.IsMatchConcluded,
                "All GiantArenaService active/video/HUD flags must be false when unused");
            Assert(!GiantArenaService.ShouldRenderVersusHud(null) && !GiantArenaService.ShouldSuppressSpeechBubblesOnMap(null)
                   && !GiantArenaService.IsOutsideActiveArenaInnerRect(null, IntVec3.Zero),
                "All Arena gameplay/HUD/boundary queries must return false when unused");
            bool isDrawingVersusHud = (bool)typeof(GiantBossHealthBarHUD).GetField("IsDrawingArenaVersusHud", BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
            Assert(!GiantBossHealthBarHUD.ManualStepMode && !isDrawingVersusHud,
                "GiantBossHealthBarHUD manual/versus flags must remain false when Arena is unused");
            Assert(!File.Exists(ResolveMod17Path("Assemblies", "GiantCreatureFramework.Arena.BridgeTools.dll")),
                "BridgeTools DLL must not be shipped inside mod 1.7/Assemblies");
            Assert(typeof(GameComponent_GiantArena).GetMethod(nameof(GameComponent.StartedNewGame), BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly) != null
                   && typeof(GameComponent_GiantArena).GetMethod(nameof(GameComponent.LoadedGame), BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly) != null,
                "GameComponent_GiantArena must override StartedNewGame and LoadedGame to guarantee clean unpatch/reset across save loads");

            Console.WriteLine($"       -> Verified 5 presets, CLI/JSON config, raid-points config, C1 smooth camera (maxStep={maxSingleStepX:F3}), L/R aligned ability slots, BridgeTools DLL, and strict zero-intrusion when unused");
        }

        private static void TestCustomAoeAbilityTargetsAndFloatMenuWorkGiverGuard()
        {
            // 1. Every AbilityDef declaring Ability_EffectRadius must set <canUseAoeToGetTargets>false</canUseAoeToGetTargets>
            // so ground-targeted abilities (e.g. Rathalos FireballBreath / FireballLiftoff) are never reduced to 0 targets
            // and custom AOE abilities never invoke Apply() N times per radial Thing.
            string[] abilFiles = EnumerateAllMod17Files(Path.Combine("Defs", "AbilityDefs"), "*.xml");
            Assert(abilFiles.Length >= 5, $"Expected >= 5 AbilityDefs XML files across sub-mods, got {abilFiles.Length}");
            int checkedAoeAbilities = 0;
            foreach (string file in abilFiles)
            {
                XDocument doc = XDocument.Load(file);
                foreach (XElement abEl in doc.Root!.Elements("AbilityDef"))
                {
                    string defName = abEl.Element("defName")?.Value ?? "(unnamed)";
                    XElement radiusEl = abEl.Element("statBases")?.Element("Ability_EffectRadius");
                    if (radiusEl != null && ParseFloat(radiusEl.Value, 0f) > 0f)
                    {
                        checkedAoeAbilities++;
                        string aoeFlag = abEl.Element("canUseAoeToGetTargets")?.Value;
                        Assert(string.Equals(aoeFlag, "false", StringComparison.OrdinalIgnoreCase),
                            $"AbilityDef '{defName}' in {Path.GetFileName(file)} sets Ability_EffectRadius={radiusEl.Value} without <canUseAoeToGetTargets>false</canUseAoeToGetTargets>");
                    }
                }
            }
            Assert(checkedAoeAbilities >= 10, $"Expected at least 10 custom-AOE AbilityDefs checked across sub-mods, got {checkedAoeAbilities}");

            // 2. Verify FloatMenuOptionProvider_SelectedPawnValid_Postfix blocks WorkGivers when workSettings == null
            // and preserves MechanoidCanDo=true providers (DraftedAttack / DraftedMove / GiantControl).
            var wgProvider = new RimWorld.FloatMenuOptionProvider_WorkGivers();
            var atkProvider = new RimWorld.FloatMenuOptionProvider_DraftedAttack();
            var moveProvider = new RimWorld.FloatMenuOptionProvider_DraftedMove();
            var giantCtrlProvider = new FloatMenuOptionProvider_GiantControl();

            Pawn pawnWithoutWorkSettings = (Pawn)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Pawn));
            bool wgAllowed = true;
            HarmonyPatches_PlayerControl.FloatMenuOptionProvider_SelectedPawnValid_Postfix(wgProvider, pawnWithoutWorkSettings, ref wgAllowed);
            Assert(!wgAllowed, "FloatMenuOptionProvider_WorkGivers must be blocked when pawn.workSettings == null");

            bool atkAllowed = true;
            HarmonyPatches_PlayerControl.FloatMenuOptionProvider_SelectedPawnValid_Postfix(atkProvider, pawnWithoutWorkSettings, ref atkAllowed);
            Assert(atkAllowed, "FloatMenuOptionProvider_DraftedAttack must remain allowed");

            bool moveAllowed = true;
            HarmonyPatches_PlayerControl.FloatMenuOptionProvider_SelectedPawnValid_Postfix(moveProvider, pawnWithoutWorkSettings, ref moveAllowed);
            Assert(moveAllowed, "FloatMenuOptionProvider_DraftedMove must remain allowed");

            bool giantCtrlAllowed = true;
            HarmonyPatches_PlayerControl.FloatMenuOptionProvider_SelectedPawnValid_Postfix(giantCtrlProvider, pawnWithoutWorkSettings, ref giantCtrlAllowed);
            Assert(giantCtrlAllowed, "FloatMenuOptionProvider_GiantControl must remain allowed");

            // 3. Verify MechanoidCanDo virtual getter delegate works across derived FloatMenuOptionProviders
            FieldInfo getterField = typeof(HarmonyPatches_PlayerControl).GetField(
                "FloatMenuProviderMechanoidCanDoGetter",
                BindingFlags.Static | BindingFlags.NonPublic);
            Assert(getterField != null, "FloatMenuProviderMechanoidCanDoGetter field missing");
            var getter = getterField.GetValue(null) as Func<RimWorld.FloatMenuOptionProvider, bool>;
            Assert(getter != null, "FloatMenuProviderMechanoidCanDoGetter delegate must initialize");
            Assert(!getter(wgProvider), "WorkGivers.MechanoidCanDo must resolve to false");
            Assert(getter(atkProvider), "DraftedAttack.MechanoidCanDo must resolve to true");
            Assert(getter(moveProvider), "DraftedMove.MechanoidCanDo must resolve to true");
            Assert(getter(giantCtrlProvider), "GiantControl.MechanoidCanDo must resolve to true");

            Console.WriteLine($"       -> Verified {checkedAoeAbilities} custom-AOE AbilityDefs (<canUseAoeToGetTargets>false) & FloatMenuOptionProvider_WorkGivers null-workSettings guard");
        }

        private static void TestQaAuditCriticalRegressionSuite()
        {
            // 1. [M1-P0-1 & M2-P2-4] MechColossus equal-bone (64 == 64) stage swap must rebuild runtime buffers & re-sort FootprintRasterizer bone order
            var (colStage1, colMasks1, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (colStage2, colMasks2, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            Assert(colStage1.SortedNodes.Length == colStage2.SortedNodes.Length && colStage1.SortedNodes.Length == 64,
                $"Expected both Colossus Stage1 & Stage2 to have 64 bones, got {colStage1.SortedNodes.Length} & {colStage2.SortedNodes.Length}");

            var colPawn = new Pawn
            {
                thingIDNumber = 999101,
                def = new ThingDef { defName = "GCF_MechColossus", shortHash = 62101, race = new RaceProperties() }
            };
            colPawn.health = new Pawn_HealthTracker(colPawn);
            var colRigComp = new CompGiantRig { parent = colPawn };
            colRigComp.Initialize(new CompProperties_GiantRig { rigDef = colStage1 });

            FieldInfo bufRigField = typeof(CompGiantRig).GetField("buffersInitializedRigDef", BindingFlags.Instance | BindingFlags.NonPublic);
            FieldInfo overrideRigField = typeof(CompGiantRig).GetField("overrideRigDef", BindingFlags.Instance | BindingFlags.NonPublic);
            MethodInfo ensureBufMethod = typeof(CompGiantRig).GetMethod("EnsureBuffersInitialized", BindingFlags.Instance | BindingFlags.NonPublic);
            Assert(bufRigField != null && overrideRigField != null && ensureBufMethod != null,
                "CompGiantRig must expose buffersInitializedRigDef, overrideRigDef, and EnsureBuffersInitialized");

            ensureBufMethod!.Invoke(colRigComp, null);
            Assert(ReferenceEquals(bufRigField!.GetValue(colRigComp), colStage1),
                "Initial EnsureBuffersInitialized must record Stage1 RigDef");
            Assert(colRigComp.PartCombat != null, "Stage1 PartCombat must initialize");
            int stage1WeaponGroups = colRigComp.PartCombat.CountIntactWeaponGroups();

            // Simulate PostExposeData restoring overrideRigDef = Stage2 (same 64 bone count!)
            overrideRigField!.SetValue(colRigComp, colStage2);
            ensureBufMethod.Invoke(colRigComp, null);
            Assert(ReferenceEquals(bufRigField.GetValue(colRigComp), colStage2),
                "EnsureBuffersInitialized must NOT early-return on equal bone count (64 == 64) when RigDef changed to Stage2");
            int stage2WeaponGroups = colRigComp.PartCombat.CountIntactWeaponGroups();
            Assert(stage2WeaponGroups > stage1WeaponGroups,
                $"Stage2 equal-bone buffer rebuild must populate Stage2 weapons (Stage1={stage1WeaponGroups} groups, Stage2={stage2WeaponGroups} groups)");

            // Also verify FootprintRasterizer re-sorts boneOrderDescByLayer when RigDef changes with equal bone count
            var fp = new GiantFootprintData();
            var local64 = new BoneLocalPose[64];
            var world1 = new BoneWorldPose[64];
            var world2 = new BoneWorldPose[64];
            SkeletalKinematics.SolveWorldPoses(colStage1, new Vector2(50.5f, 50.5f), 0f, local64, ReadOnlySpan<bool>.Empty, world1, 1f);
            SkeletalKinematics.SolveWorldPoses(colStage2, new Vector2(50.5f, 50.5f), 0f, local64, ReadOnlySpan<bool>.Empty, world2, 1f);
            fp.Rebuild(colStage1, world1, colMasks1, new IntVec3(50, 0, 50));
            FieldInfo lastSortedField = typeof(GiantFootprintData).GetField("lastSortedRigDef", BindingFlags.Instance | BindingFlags.NonPublic);
            Assert(lastSortedField != null && ReferenceEquals(lastSortedField.GetValue(fp), colStage1),
                "GiantFootprintData must track lastSortedRigDef on Stage1 Rebuild");
            fp.Rebuild(colStage2, world2, colMasks2, new IntVec3(50, 0, 50));
            Assert(ReferenceEquals(lastSortedField!.GetValue(fp), colStage2),
                "GiantFootprintData must re-sort boneOrderDescByLayer when equal-bone RigDef switches Stage1 -> Stage2");

            // 2. [M2-P0-2] otherPawnsCustomizer giant collision cost cap must stay <= 5500 (never 10000 impassable)
            Assert(GiantFootprintMapComponent.MaxOtherPawnGiantCollisionCost <= 5500 &&
                   GiantFootprintMapComponent.MaxOtherPawnGiantCollisionCost >= 3000,
                $"MaxOtherPawnGiantCollisionCost must be in [3000, 5500], got {GiantFootprintMapComponent.MaxOtherPawnGiantCollisionCost}");
            MethodInfo getColCost = typeof(GiantFootprintMapComponent).GetMethod("GetGiantCollisionCost", BindingFlags.Static | BindingFlags.NonPublic);
            Assert(getColCost != null, "GiantFootprintMapComponent.GetGiantCollisionCost missing");
            ushort cappedCost = (ushort)getColCost!.Invoke(null, new object[] { colRigComp })!;
            Assert(cappedCost <= 5500 && cappedCost == GiantFootprintMapComponent.MaxOtherPawnGiantCollisionCost,
                $"Rig with collisionPathCost=10000 must be clamped to {GiantFootprintMapComponent.MaxOtherPawnGiantCollisionCost}, got {cappedCost}");

            // 3. [M4-P0-2 & M4-P1-5] CompGiantCockpit ThingOwner<Thing>, PrePreTraded override, and LowSkim vs HighAirborne boarding rules
            FieldInfo innerContainerField = typeof(CompGiantCockpit).GetField("innerContainer", BindingFlags.Instance | BindingFlags.NonPublic);
            Assert(innerContainerField != null && innerContainerField.FieldType == typeof(ThingOwner<Thing>),
                $"CompGiantCockpit.innerContainer must be ThingOwner<Thing> (holds dead crew Corpse safely), got {innerContainerField?.FieldType}");

            MethodInfo prePreTraded = typeof(CompGiantCockpit).GetMethod(
                nameof(ThingComp.PrePreTraded),
                BindingFlags.Instance | BindingFlags.Public,
                null,
                new[] { typeof(RimWorld.TradeAction), typeof(Pawn), typeof(RimWorld.ITrader) },
                null);
            Assert(prePreTraded != null && prePreTraded.DeclaringType == typeof(CompGiantCockpit),
                "CompGiantCockpit must directly override ThingComp.PrePreTraded(TradeAction, Pawn, ITrader)");

            // Verify AlwaysAirborne + LowSkim (GCF_MechColossus) IS boardable/disembarkable over dry ground!
            var colCockpit = new CompGiantCockpit { parent = colPawn };
            colCockpit.Initialize(new CompProperties_GiantCockpit
            {
                seats = new List<GiantCockpitSeatDef> { new GiantCockpitSeatDef { seatId = "Pilot", role = GiantCockpitRole.PrimaryPilot } }
            });
            colPawn.AllComps.Add(colRigComp);
            colPawn.AllComps.Add(colCockpit);
            GiantFastLookup.Register(colPawn, colRigComp);
            GiantFastLookup.RegisterCockpit(colPawn, colCockpit);
            try
            {
                Assert(colRigComp.FlightLocomotion != null &&
                       colRigComp.FlightLocomotion.Def.flightMode == GiantFlightMode.AlwaysAirborne &&
                       colRigComp.FlightLocomotion.Def.altitudeTier == FlightAltitudeTier.LowSkim,
                    "GCF_MechColossus must be configured as AlwaysAirborne + LowSkim");
                Assert(!colCockpit.IsFlightStateBlockingBoardingOrDisembark(out string colBlockReason),
                    $"GCF_MechColossus (AlwaysAirborne + LowSkim) must remain boardable over dry ground, but was blocked: {colBlockReason}");
            }
            finally
            {
                GiantFastLookup.Unregister(colPawn);
                GiantFastLookup.UnregisterCockpit(colPawn);
            }

            // Verify AlwaysAirborne + HighAirborne (GCF_ProtossCarrier) IS blocked from boarding/disembarking
            var (carrierRigDef, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            var carrierPawn = new Pawn { thingIDNumber = 999102, def = new ThingDef { defName = "GCF_ProtossCarrier", shortHash = 62102, race = new RaceProperties() } };
            carrierPawn.health = new Pawn_HealthTracker(carrierPawn);
            var carrierRigComp = new CompGiantRig { parent = carrierPawn };
            carrierRigComp.Initialize(new CompProperties_GiantRig { rigDef = carrierRigDef });
            var carrierCockpit = new CompGiantCockpit { parent = carrierPawn };
            carrierCockpit.Initialize(new CompProperties_GiantCockpit
            {
                seats = new List<GiantCockpitSeatDef> { new GiantCockpitSeatDef { seatId = "Bridge", role = GiantCockpitRole.PrimaryPilot } }
            });
            GiantFastLookup.Register(carrierPawn, carrierRigComp);
            GiantFastLookup.RegisterCockpit(carrierPawn, carrierCockpit);
            try
            {
                Assert(carrierCockpit.IsFlightStateBlockingBoardingOrDisembark(out _),
                    "HighAirborne AlwaysAirborne flyer must block boarding/disembarking");
            }
            finally
            {
                GiantFastLookup.Unregister(carrierPawn);
                GiantFastLookup.UnregisterCockpit(carrierPawn);
            }

            // Verify TakeoffAndLanding + HighAirborne (GCF_Rathalos): Grounded allowed, TakingOff/Airborne/Landing blocked
            var (rathRigDef, _, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var rathPawn = new Pawn { thingIDNumber = 999103, def = new ThingDef { defName = "GCF_Rathalos", shortHash = 62103, race = new RaceProperties() } };
            rathPawn.health = new Pawn_HealthTracker(rathPawn);
            var rathRigComp = new CompGiantRig { parent = rathPawn };
            rathRigComp.Initialize(new CompProperties_GiantRig { rigDef = rathRigDef });
            var rathCockpit = new CompGiantCockpit { parent = rathPawn };
            rathCockpit.Initialize(new CompProperties_GiantCockpit
            {
                seats = new List<GiantCockpitSeatDef> { new GiantCockpitSeatDef { seatId = "Saddle", role = GiantCockpitRole.PrimaryPilot } }
            });
            GiantFastLookup.Register(rathPawn, rathRigComp);
            GiantFastLookup.RegisterCockpit(rathPawn, rathCockpit);
            try
            {
                Assert(rathRigComp.FlightLocomotion != null && rathRigComp.FlightLocomotion.FlightState == GiantFlightState.Grounded,
                    "Rathalos should start Grounded");
                Assert(!rathCockpit.IsFlightStateBlockingBoardingOrDisembark(out string rathGroundBlock),
                    $"Grounded Rathalos must allow boarding/disembarking, got: {rathGroundBlock}");
                Assert(rathRigComp.FlightLocomotion!.TryCommandTakeoff(rathRigComp, out string takeoffErr),
                    $"Rathalos headless TryCommandTakeoff must succeed without Find.TickManager NRE: {takeoffErr}");
                Assert(rathCockpit.IsFlightStateBlockingBoardingOrDisembark(out _),
                    "TakingOff/Airborne Rathalos must block boarding/disembarking");
            }
            finally
            {
                GiantFastLookup.Unregister(rathPawn);
                GiantFastLookup.UnregisterCockpit(rathPawn);
            }

            // 4. [M3-P1-1 & M3-P1-9] ValstraxDragonEnergyVfxRenderer wired in MapComponentUpdate + HasActiveCometAscentOrOrbit footprint hook
            MethodInfo valUpdate = typeof(ValstraxDragonEnergyMapComponent).GetMethod(nameof(MapComponent.MapComponentUpdate), BindingFlags.Instance | BindingFlags.Public);
            MethodInfo drawValVfx = typeof(ValstraxDragonEnergyVfxRenderer).GetMethod(nameof(ValstraxDragonEnergyVfxRenderer.DrawMapValstraxVfx), BindingFlags.Static | BindingFlags.Public);
            Assert(valUpdate != null && drawValVfx != null, "ValstraxDragonEnergyMapComponent.MapComponentUpdate and DrawMapValstraxVfx must exist");
            Assert(PatchProcessor.GetOriginalInstructions(valUpdate!).Any(ci => ci.Calls(drawValVfx!)),
                "ValstraxDragonEnergyMapComponent.MapComponentUpdate must call ValstraxDragonEnergyVfxRenderer.DrawMapValstraxVfx");
            ValstraxDragonEnergyVfxRenderer.ClearAll();
            ValstraxDragonEnergyVfxRenderer.ClearForMap(null);
            Assert(!ValstraxDragonEnergyMapComponent.HasActiveCometAscentOrOrbit(null),
                "HasActiveCometAscentOrOrbit(null) must safely return false");
            MethodInfo rebuildFp = typeof(CompGiantRig).GetMethod(nameof(CompGiantRig.RebuildFootprintNow), BindingFlags.Instance | BindingFlags.Public);
            MethodInfo clearFpHook = typeof(GiantMotionOverrideRegistry).GetMethod(nameof(GiantMotionOverrideRegistry.HasActiveHighAltitudeOverride), BindingFlags.Static | BindingFlags.Public);
            Assert(rebuildFp != null && clearFpHook != null && PatchProcessor.GetOriginalInstructions(rebuildFp!).Any(ci => ci.Calls(clearFpHook!)),
                "CompGiantRig.RebuildFootprintNow must delegate to GiantMotionOverrideRegistry.HasActiveHighAltitudeOverride");
            Assert(!GiantMotionOverrideRegistry.HasActiveHighAltitudeOverride(null),
                "GiantMotionOverrideRegistry.HasActiveHighAltitudeOverride(null) must safely return false");

            // 5. [M3-P1-7] Verb_TryFindShootLineFromTo_Transpiler patches 4th get_Cell (!requireLineOfSight) and preserves 3rd (OutOfRange)
            MethodInfo shootLineTarget = typeof(Verb).GetMethod(nameof(Verb.TryFindShootLineFromTo),
                new[] { typeof(IntVec3), typeof(LocalTargetInfo), typeof(ShootLine).MakeByRefType(), typeof(bool) })!;
            MethodInfo getCellMethod = typeof(LocalTargetInfo).GetProperty(nameof(LocalTargetInfo.Cell))!.GetGetMethod()!;
            MethodInfo outOfRangeMethod = typeof(Verb).GetMethod(nameof(Verb.OutOfRange))!;
            FieldInfo reqLosField = typeof(VerbProperties).GetField(nameof(VerbProperties.requireLineOfSight))!;
            MethodInfo resolveTargetRef = typeof(HarmonyPatches_CombatAndHitbox).GetMethod("ResolveShootLineTargetCellRef", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)!;
            var transpiledShootLine = HarmonyPatches_CombatAndHitbox.Verb_TryFindShootLineFromTo_Transpiler(
                PatchProcessor.GetOriginalInstructions(shootLineTarget)).ToList();
            int ilOutOfRange = -1, ilReqLos = -1, cellsBeforeReqLos = 0, resolvesBeforeReqLos = 0, resolvesAfterReqLos = 0;
            for (int i = 0; i < transpiledShootLine.Count; i++)
            {
                var ci = transpiledShootLine[i];
                if (ci.Calls(outOfRangeMethod)) ilOutOfRange = i;
                if (ci.LoadsField(reqLosField)) ilReqLos = i;
                if (ilOutOfRange >= 0 && ilReqLos < 0)
                {
                    if (ci.Calls(getCellMethod)) cellsBeforeReqLos++;
                    if (ci.Calls(resolveTargetRef)) resolvesBeforeReqLos++;
                }
                else if (ilReqLos >= 0 && ci.Calls(resolveTargetRef))
                {
                    resolvesAfterReqLos++;
                }
            }
            Assert(cellsBeforeReqLos == 1 && resolvesBeforeReqLos == 0 && resolvesAfterReqLos == 1,
                $"Verb_TryFindShootLineFromTo_Transpiler must preserve OutOfRange get_Cell (#3) and patch !requireLOS get_Cell (#4); got before=(cell:{cellsBeforeReqLos},res:{resolvesBeforeReqLos}), after=(res:{resolvesAfterReqLos})");

            // 6. [M5-P0-1 & M5-P1-2] WorldObject_Giant terrain difficulty (3.5f impassable), hybrid flight speed multiplier & biological transit stabilization
            var hybridFlightDef = new GiantFlightDef { flightMode = GiantFlightMode.TakeoffAndLanding, flightSpeedMultiplier = 2.25f };
            var hybridFlightRt = new GiantFlightRuntime(rathRigDef, hybridFlightDef);
            hybridFlightRt.ResetForSpawn(999104);
            AssertNear(hybridFlightRt.WorldFlightSpeedMultiplier, 2.25f, 0.001f,
                "Grounded TakeoffAndLanding flyer must expose full flightSpeedMultiplier via WorldFlightSpeedMultiplier");
            MethodInfo worldTick = typeof(WorldObject_Giant).GetMethod("Tick", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            MethodInfo worldSpeedProp = typeof(GiantFlightRuntime).GetProperty(nameof(GiantFlightRuntime.WorldFlightSpeedMultiplier))?.GetGetMethod();
            Assert(worldTick != null && worldSpeedProp != null, "WorldObject_Giant.Tick and WorldFlightSpeedMultiplier getter must exist");
            var worldTickInstrs = PatchProcessor.GetOriginalInstructions(worldTick!);
            Assert(worldTickInstrs.Any(ci => ci.Calls(worldSpeedProp!)),
                "WorldObject_Giant.Tick must read GiantFlightRuntime.WorldFlightSpeedMultiplier");
            Assert(worldTickInstrs.Any(ci => ci.operand is float f && MathF.Abs(f - 3.5f) < 0.001f),
                "WorldObject_Giant.Tick must apply 3.5f difficulty penalty on impassable non-flying tiles instead of 1.0f");
            Assert(typeof(WorldObject_Giant).GetMethod(nameof(WorldObject_Giant.ForceAbandonAndDestroy), BindingFlags.Instance | BindingFlags.Public) != null,
                "WorldObject_Giant.ForceAbandonAndDestroy must exist for dead/empty world remains cleanup");

            // 7. [M2-P1-4] GiantDestructionUtility wild/manhunter wall breach & same-faction protection
            MethodInfo isProtectedMethod = typeof(GiantDestructionUtility).GetMethod("IsProtectedAlliedThing", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)!;
            var wildGiant = (Pawn)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Pawn));
            var alliedGiant = (Pawn)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Pawn));
            var wallThing = (Thing)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Thing));
            var facA = (RimWorld.Faction)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(RimWorld.Faction));
            FieldInfo factionIntField = typeof(Thing).GetField("factionInt", BindingFlags.Instance | BindingFlags.NonPublic)!;
            factionIntField.SetValue(wallThing, facA);
            factionIntField.SetValue(alliedGiant, facA);
            Assert(!(bool)isProtectedMethod.Invoke(null, new object[] { wildGiant, wallThing })!,
                "Wild/manhunter giant (Faction == null) must NOT treat player walls as protected allied things");
            Assert((bool)isProtectedMethod.Invoke(null, new object[] { alliedGiant, wallThing })!,
                "Non-aggro same-faction giant must still protect allied faction walls");

            // 8. [M1-P1-1, M3-P1-10, M5-P2-5, M6-P1-8] Phase raw-downed guard, ThermalBeam minRange, MechScorpion Biotech ThinkTree, DropShadow discard
            FieldInfo rawDownedField = typeof(CompGiantPhaseTransform).GetField("IsEvaluatingRawDowned", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
            Assert(rawDownedField != null, "CompGiantPhaseTransform.IsEvaluatingRawDowned must exist to prevent ShouldBeDowned_Postfix recursion deadlock");

            XDocument colAbilDoc = XDocument.Load(ResolveMod17Path("Defs", "AbilityDefs", "Abilities_MechColossus.xml"));
            XElement beamEl = colAbilDoc.Root!.Elements("AbilityDef").FirstOrDefault(e => e.Element("defName")?.Value == "GCF_Ability_MechThermalBeamSweep");
            Assert(beamEl != null && ParseFloat(beamEl.Element("verbProperties")?.Element("minRange")?.Value, 0f) >= 5.0f,
                "GCF_Ability_MechThermalBeamSweep must declare <minRange> >= 5.0 to prevent 180-deg point-blank beam flip");

            XDocument scorpTtDoc = XDocument.Load(ResolveMod17Path("Defs", "ThinkTreeDefs", "ThinkTrees_MechScorpion.xml"));
            string scorpTtXml = scorpTtDoc.ToString();
            Assert(scorpTtXml.Contains("ThinkNode_ConditionalLowEnergy", StringComparison.Ordinal)
                && scorpTtXml.Contains("ThinkNode_ConditionalPlayerControlledMech", StringComparison.Ordinal)
                && scorpTtXml.Contains("JobGiver_GetEnergy_Charger", StringComparison.Ordinal)
                && scorpTtXml.Contains("JobGiver_SelfShutdown", StringComparison.Ordinal),
                "ThinkTrees_MechScorpion.xml must contain Biotech LowEnergy & PlayerControlledMech work/charge/shutdown branches");

            string shadowShaderSrc = File.ReadAllText(ResolveMod17Path("Shaders", "GCF_GiantDropShadow.frag.glsl"));
            Assert(shadowShaderSrc.Contains("outColor.a < 0.02", StringComparison.Ordinal) && shadowShaderSrc.Contains("discard", StringComparison.Ordinal),
                "GCF_GiantDropShadow.frag.glsl must discard fragments with alpha < 0.02 to prevent stencil holes");

            Console.WriteLine("       -> Verified M1-P0-1 (64b stage rebuild), M2-P0-2 (cost cap 4500), M4-P0-2/P1-5 (ThingOwner<Thing>, PrePreTraded, LowSkim vs HighAirborne), M3-P1-1/7/9 (Valstrax VFX+Comet, ShootLine #4), M5-P0-1/P1-2 (World flight/terrain), M2-P1-4 (wild breach), M1-P1-1/M3-P1-10/M5-P2-5/M6-P1-8");
        }

        private static void TestGiantVsGiantCloseContactHullRetractionAndZeroAirSwing()
        {
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valsRig, valsMasks, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            var (panzerRig, _, _) = LoadRigFromXml("GiantRigDefs_PanzerIV.xml", "GiantAnimDefs_PanzerIV.xml", "GCF_Rig_PanzerIV");
            var (scorpRig, _, _) = LoadMechScorpionFromXml();

            // 1. Verify mid/distal neck, skull & elevated tail segments have contributesToCollision=false while preserving contributesToHitbox=true,
            //    and core torso + pelvis + proximal neck collar retain contributesToCollision=true.
            void VerifyCollisionFlags(GiantRigDef rig, string[] mustCollide, string[] mustNotCollideButHitbox)
            {
                foreach (string id in mustCollide)
                {
                    Assert(rig.TryGetNodeIndex(id, out int idx) && rig.SortedNodes[idx].contributesToCollision && rig.SortedNodes[idx].contributesToHitbox,
                        $"{rig.defName}.{id} must have contributesToCollision=true and contributesToHitbox=true");
                }
                foreach (string id in mustNotCollideButHitbox)
                {
                    Assert(rig.TryGetNodeIndex(id, out int idx) && !rig.SortedNodes[idx].contributesToCollision && rig.SortedNodes[idx].contributesToHitbox,
                        $"{rig.defName}.{id} must have contributesToCollision=false and contributesToHitbox=true");
                }
            }

            VerifyCollisionFlags(
                rathRig,
                new[] { "thorax_core", "neck_base", "thorax_rear", "lumbar", "pelvis" },
                new[] { "neck_mid", "neck_upper", "skull", "sacrum", "tail_seg1", "tail_seg2" });
            VerifyCollisionFlags(
                valsRig,
                new[] { "thorax_core", "neck_base", "thorax_rear", "lumbar", "pelvis" },
                new[] { "neck_mid", "neck_upper", "skull", "sacrum", "tail_seg1", "tail_seg2" });


            // 2. Rasterize head-on North (0 deg) vs South (180 deg) footprints and verify solid collision hull retracts to chest collar
            //    so two giants close to <= 6 cells center-to-center (zero empty air cells, minGapSq == 1) while overlapping head/neck hitCells!
            GiantFootprintData BuildFootprint(GiantRigDef rig, TextureAlphaMask[] masks, IntVec3 cell, float headingDeg, out BoneWorldPose[] worldPoses)
            {
                int count = rig.SortedNodes.Length;
                var local = new BoneLocalPose[count];
                Array.Fill(local, BoneLocalPose.Identity);
                worldPoses = new BoneWorldPose[count];
                SkeletalKinematics.SolveWorldPoses(rig, new Vector2(cell.x + 0.5f, cell.z + 0.5f), headingDeg, local, new bool[count], worldPoses);
                var fp = new GiantFootprintData();
                fp.Rebuild(rig, worldPoses, masks, cell);
                return fp;
            }

            IntVec3 originA = new IntVec3(60, 0, 60);
            GiantFootprintData rathFpNorth = BuildFootprint(rathRig, rathMasks, originA, 0f, out BoneWorldPose[] rathPoses);
            GiantFootprintData valsFpNorth = BuildFootprint(valsRig, valsMasks, originA, 0f, out BoneWorldPose[] valsPoses);

            int rathFrontSolidZ = rathFpNorth.collisionCells.Max(c => c.z) - originA.z;
            int valsFrontSolidZ = valsFpNorth.collisionCells.Max(c => c.z) - originA.z;
            int rathFrontHitZ = rathFpNorth.hitCells.Max(h => h.cell.z) - originA.z;
            int valsFrontHitZ = valsFpNorth.hitCells.Max(h => h.cell.z) - originA.z;

            Assert(rathFrontSolidZ <= 3 && rathFrontHitZ >= rathFrontSolidZ + 3, $"Rathalos front solid Z must retract <= +3 while hit Z protrudes >= +3 cells ahead, got solid=+{rathFrontSolidZ}, hit=+{rathFrontHitZ}");
            Assert(valsFrontSolidZ <= 3 && valsFrontHitZ >= valsFrontSolidZ + 3, $"Valstrax front solid Z must retract <= +3 while hit Z protrudes >= +3 cells ahead, got solid=+{valsFrontSolidZ}, hit=+{valsFrontHitZ}");

            // Head-on Rathalos (North at z=60) vs Valstrax (South at z=bestZ):
            int closestHeadOnZ = -1;
            int headOnHitOverlap = 0;
            for (int z = 63; z <= 75; z++)
            {
                IntVec3 candB = new IntVec3(60, 0, z);
                GiantFootprintData valsSouth = BuildFootprint(valsRig, valsMasks, candB, 180f, out _);
                int solidOverlap = GiantHullCollisionUtility.CountTranslatedHullOverlap(originA, rathFpNorth.localCollisionOffsets, valsSouth.collisionCellSet);
                if (solidOverlap == 0)
                {
                    closestHeadOnZ = z;
                    headOnHitOverlap = GiantPartCombatRuntime.CountHullOverlapWithForbiddenSet(originA, rathFpNorth.localCollisionOffsets, valsSouth.hitCellSet);
                    // Verify 1-cell cardinal solid hull contact (zero empty air cells between solid hulls)
                    int minSolidDz = valsSouth.collisionCells.Min(bc => rathFpNorth.collisionCells.Where(ac => ac.x == bc.x).Select(ac => bc.z - ac.z).DefaultIfEmpty(99).Min());
                    Assert(minSolidDz == 1, $"Expected exact 1-cell cardinal solid hull contact (0 air cells), got dz={minSolidDz}");
                    break;
                }
            }
            int centerGapCells = closestHeadOnZ - originA.z;
            Assert(closestHeadOnZ > 0 && centerGapCells <= 6,
                $"Head-on Rathalos vs Valstrax chest-to-chest center distance must close to <= 6 cells (was 14-16), got {centerGapCells}");
            Assert(headOnHitOverlap > 0,
                "Head-on close contact must allow protruding non-collision neck/skull/wing hitCells to overhang opponent hull without blocking");

            // 3. Verify TryFindCloseMeleeEngagementCell no longer penalizes spriteOverlapCells on non-collision hitCellSet
            //    and uses tight 1.45f zero-air-gap snugTouchRadius (1.85f for lowSkimTarget).
            string combatSrc = File.ReadAllText(Path.Combine(ModRoot, "Source", "GiantCreatureFramework", "Combat", "GiantPartCombatSystem.cs"));
            Assert(!combatSrc.Contains("spriteOverlapCells", StringComparison.Ordinal),
                "TryFindCloseMeleeEngagementCell must not penalize non-collision hitCellSet overlap (spriteOverlapCells)");
            Assert(!combatSrc.Contains("string.IsNullOrEmpty(atk.rangeOriginBoneId))", StringComparison.Ordinal),
                "CanPartAttackReachAndSeeTarget must enforce anatomical/strikePixel reach even when rangeOriginBoneId is set");
            Assert(combatSrc.Contains("float snugTouchRadius = lowSkimTarget ? 1.85f : 1.45f;", StringComparison.Ordinal),
                "TryFindCloseMeleeEngagementCell must enforce snugTouchRadius = 1.45f (zero-air-gap 8-way hull contact) for ground targets");

            // 4. Verify live GiantPartCombatRuntime anatomical spans (coronal-flap invariant) & close-contact reach vs open-air rejection
            void VerifyRigMeleeEnvelope(GiantRigDef rig, BoneWorldPose[] worldPoses, int frontSolidZ)
            {
                var comp = new CompGiantRig();
                comp.Initialize(new CompProperties_GiantRig { rigDef = rig });
                var rt = new GiantPartCombatRuntime(comp);
                FieldInfo scratchField = typeof(GiantPartCombatRuntime).GetField("livePoseScratch", BindingFlags.Instance | BindingFlags.NonPublic)!;
                Array.Copy(worldPoses, (BoneWorldPose[])scratchField.GetValue(rt)!, worldPoses.Length);

                Vector2 contactEnemySolidXZ = new Vector2(originA.x + 0.5f, originA.z + frontSolidZ + 1 + 0.5f);
                Vector2 openAirEnemySolidXZ = new Vector2(originA.x + 0.5f, originA.z + frontSolidZ + 6 + 0.5f);

                int checkedFrontal = 0;
                foreach (BonePartWeaponGroup grp in rt.Groups)
                {
                    foreach (GiantPartAttackDef atk in grp.Attacks)
                    {
                        if (atk.kind != GiantPartAttackKind.Melee || atk.useSoftWhipTip)
                        {
                            continue;
                        }
                        bool inBezier = rig.bezierChains != null && rig.bezierChains.Any(bc => bc.resolvedBoneIndices != null && Array.IndexOf(bc.resolvedBoneIndices, grp.BoneIndex) >= 0);
                        if (!inBezier && !string.IsNullOrEmpty(atk.rangeOriginBoneId))
                        {
                            float span = rt.ComputeFlatAnatomicalSpanFromAnchor(grp, atk);
                            Assert(span > 1.5f, $"{rig.defName}.{atk.attackId} flat anatomical span must be > 1.5 cells (got {span:F2})");
                            Assert(atk.range <= span + 1.60f,
                                $"{rig.defName}.{atk.attackId} XML range ({atk.range:F2}) must not exceed flatLimbSpan ({span:F2}) + 1.60f");
                        }

                        // Check frontal melee attacks (|sectorCenterDeg| <= 90)
                        if (Mathf.Abs(Mathf.DeltaAngle(0f, atk.sectorCenterDeg)) <= 90f)
                        {
                            checkedFrontal++;
                            Vector2 anchorXZ;
                            if (!string.IsNullOrEmpty(atk.rangeOriginBoneId) && rig.TryGetNodeIndex(atk.rangeOriginBoneId, out int aIdx))
                            {
                                anchorXZ = worldPoses[aIdx].jointWorldXZ;
                            }
                            else
                            {
                                anchorXZ = rt.GetBoneOriginWorldXZ(grp, atk, out _);
                            }

                            float contactDist = Mathf.Max(0f, Vector2.Distance(anchorXZ, contactEnemySolidXZ) - 0.25f);
                            float openAirDist = Mathf.Max(0f, Vector2.Distance(anchorXZ, openAirEnemySolidXZ) - 0.25f);
                            Assert(contactDist <= atk.range,
                                $"{rig.defName}.{atk.attackId} must reach opponent chest at 1-cell solid hull contact (dist={contactDist:F2} > range={atk.range:F2})");
                            Assert(openAirDist > atk.range,
                                $"{rig.defName}.{atk.attackId} must reject open-air target 5 empty cells ahead (dist={openAirDist:F2} <= range={atk.range:F2})");
                        }
                    }
                }
                Assert(checkedFrontal > 0, $"{rig.defName} must have at least one frontal melee attack verified");
            }

            VerifyRigMeleeEnvelope(rathRig, rathPoses, rathFrontSolidZ);
            VerifyRigMeleeEnvelope(valsRig, valsPoses, valsFrontSolidZ);

            // Also verify Vehicle Rigs (PanzerIV & ProtossCarrier) have strictly ZERO melee attacks/anims, and MechScorpion claws remain <= 2.9
            var (carrierCheckRig, _, _) = LoadRigFromXml("GiantRigDefs_ProtossCarrier.xml", "GiantAnimDefs_ProtossCarrier.xml", "GCF_Rig_ProtossCarrier");
            foreach (GiantRigDef vehRig in new[] { panzerRig, carrierCheckRig })
            {
                Assert(vehRig.IsVehicleRig, $"{vehRig.defName} must be recognized as IsVehicleRig");
                Assert(vehRig.meleeAttackAnims == null || vehRig.meleeAttackAnims.Count == 0,
                    $"Vehicle rig {vehRig.defName} must have 0 meleeAttackAnims");
                Assert(!vehRig.SortedNodes.SelectMany(n => n.partAttacks ?? new List<GiantPartAttackDef>())
                    .Any(a => a.kind == GiantPartAttackKind.Melee),
                    $"Vehicle rig {vehRig.defName} must have 0 Melee partAttacks");
            }
            // Verify ConfigErrors rejects melee partAttack or hull offset on ground vehicle rig
            panzerRig.SortedNodes[0].partAttacks.Add(new GiantPartAttackDef
            {
                attackId = "illegal_vehicle_ram",
                label = "ram",
                kind = GiantPartAttackKind.Melee,
                damageDef = new DamageDef { defName = "Blunt" },
                power = 10f,
                range = 2f,
                warmupTime = 0.5f,
                cooldownTime = 1.0f,
                attackAnim = panzerRig.rangedAttackAnim
            });
            Assert(panzerRig.ConfigErrors().Any(e => e.Contains("cannot use <kind>Melee</kind>")),
                "ConfigErrors must reject Melee partAttack on vehicle rig");
            panzerRig.SortedNodes[0].partAttacks.Clear();

            Assert(scorpRig.SortedNodes.SelectMany(n => n.partAttacks ?? new List<GiantPartAttackDef>())
                .Where(a => a.kind == GiantPartAttackKind.Melee).All(a => a.range <= 2.9f),
                "MechScorpion melee ram/claw ranges must be tightened <= 2.9");

            // Verify melee-dominant hybrid positioning rule (MechScorpion closes into claw contact with intact claws, falls back to plasma standoff when both claws severed)
            Assert(GiantPartCombatRuntime.ShouldHybridPreferMeleeCloseAssault(32.17f, 16.97f, rushWhenEnemyFar: true),
                "MechScorpion with intact twin crusher claws must prefer close melee assault over stopping at 25-cell stinger range");
            Assert(GiantPartCombatRuntime.ShouldHybridPreferMeleeCloseAssault(20.47f, 16.97f, rushWhenEnemyFar: true),
                "MechScorpion with one intact crusher claw + carapace must still prefer close melee assault");
            Assert(!GiantPartCombatRuntime.ShouldHybridPreferMeleeCloseAssault(8.77f, 16.97f, rushWhenEnemyFar: true),
                "MechScorpion with both crusher claws destroyed (carapace only vs plasma stinger) must fall back to ranged standoff");
            Assert(!GiantPartCombatRuntime.ShouldHybridPreferMeleeCloseAssault(0f, 24.0f, rushWhenEnemyFar: false),
                "Pure-ranged vehicle (Panzer IV) must never prefer melee close assault");

            Console.WriteLine($"       -> Verified retracted neck/skull/tail solid hulls (head-on center gap={centerGapCells} cells, minSolidDz=1, hitOverlap={headOnHitOverlap}), coronal-invariant flatLimbSpan & zero air-swing envelopes");
        }

        private static void TestVanillaZeroInvasivenessAndWorldPoiLifecycle()
        {
            // 1. World Map POI / Settlement / PeaceTalks / Odyssey Landmark non-destructive lifecycle contracts
            Assert(Enum.IsDefined(typeof(WorldGiantArrivalAction), WorldGiantArrivalAction.VisitSettlement)
                && Enum.IsDefined(typeof(WorldGiantArrivalAction), WorldGiantArrivalAction.TradeWithSettlement)
                && Enum.IsDefined(typeof(WorldGiantArrivalAction), WorldGiantArrivalAction.OfferGiftsToSettlement)
                && Enum.IsDefined(typeof(WorldGiantArrivalAction), WorldGiantArrivalAction.VisitPeaceTalks),
                "WorldGiantArrivalAction must expose VisitSettlement, TradeWithSettlement, OfferGiftsToSettlement, and VisitPeaceTalks");

            Type traderAdapterType = typeof(WorldObject_Giant).Assembly.GetType("GiantCreatureFramework.WorldGiantSettlementTraderAdapter");
            Assert(traderAdapterType != null && typeof(RimWorld.ITrader).IsAssignableFrom(traderAdapterType),
                "WorldGiantSettlementTraderAdapter must exist and implement RimWorld.ITrader for cockpit-negotiator trading & gifting");

            MethodInfo setTileMethod = typeof(WorldObject_Giant).GetMethod("SetTileAndNotifyLandmarks", BindingFlags.Instance | BindingFlags.NonPublic);
            Assert(setTileMethod != null, "WorldObject_Giant.SetTileAndNotifyLandmarks must exist");
            var setTileCalls = PatchProcessor.GetOriginalInstructions(setTileMethod!)
                .Where(ci => ci.operand is MethodBase)
                .Select(ci => ((MethodBase)ci.operand).Name)
                .ToList();
            Assert(setTileCalls.Contains(nameof(RimWorld.Planet.ExpandableLandmarksUtility.Notify_WorldObjectsChanged)),
                "SetTileAndNotifyLandmarks must invoke ExpandableLandmarksUtility.Notify_WorldObjectsChanged on tile transitions");

            MethodInfo landmarksPostfix = typeof(HarmonyPatches_GiantWorld).GetMethod("LandmarksToShow_WorldGiant_Postfix", BindingFlags.Static | BindingFlags.Public);
            Assert(landmarksPostfix != null, "HarmonyPatches_GiantWorld.LandmarksToShow_WorldGiant_Postfix must exist so Odyssey landmarks do not vanish under WorldObject_Giant");

            MethodInfo exitMapPrefix = typeof(HarmonyPatches_GiantWorld).GetMethod("ExitMap_Prefix", BindingFlags.Static | BindingFlags.Public);
            Assert(exitMapPrefix != null, "HarmonyPatches_GiantWorld.ExitMap_Prefix must exist");
            var exitCalls = PatchProcessor.GetOriginalInstructions(exitMapPrefix!)
                .Where(ci => ci.operand is MethodBase)
                .Select(ci => ((MethodBase)ci.operand).Name)
                .ToList();
            Assert(exitCalls.Contains(nameof(GiantWorldUtility.WouldLeavingTriggerMapOrWorldObjectRemoval))
                && exitCalls.Contains(nameof(GiantWorldUtility.ShowNonColonyDepartureConfirmation)),
                "ExitMap_Prefix must check WouldLeavingTriggerMapOrWorldObjectRemoval and prompt ShowNonColonyDepartureConfirmation before destroying non-colony POIs on edge exit");

            // 2. Non-giant unarmed humanlike/modded pawns (with Pawn_EquipmentTracker where Primary == null) must NEVER be intercepted
            GiantFastLookup.BuildDefShortHashTable();
            var vanillaPawnDef = new ThingDef { defName = "Human", shortHash = 54321, race = new RaceProperties { intelligence = Intelligence.Humanlike } };
            var vanillaWeaponlessPawn = new Pawn { thingIDNumber = 999801, def = vanillaPawnDef };
            vanillaWeaponlessPawn.equipment = new Pawn_EquipmentTracker(vanillaWeaponlessPawn);
            Assert(vanillaWeaponlessPawn.equipment.Primary == null, "Test pawn Primary weapon must be null");
            bool useRangedRes = true;
            bool runOriginalUseRanged = HarmonyPatches_CombatAndHitbox.FloatMenuUtility_UseRangedAttack_Prefix(vanillaWeaponlessPawn, ref useRangedRes);
            Assert(runOriginalUseRanged && useRangedRes,
                "FloatMenuUtility_UseRangedAttack_Prefix must pass through (return true) untouched for non-giant unarmed pawns with Primary == null");

            string failStr = "sentinel";
            Action rangedAct = () => { };
            bool runOriginalGetRanged = HarmonyPatches_CombatAndHitbox.FloatMenuUtility_GetRangedAttackAction_Prefix(
                vanillaWeaponlessPawn,
                LocalTargetInfo.Invalid,
                ref failStr,
                ref rangedAct);
            Assert(runOriginalGetRanged && failStr == "sentinel" && rangedAct != null,
                "FloatMenuUtility_GetRangedAttackAction_Prefix must pass through untouched for non-giant unarmed pawns with Primary == null");

            // 3. Non-giant pawns with canMeleeAttack == false must NOT be intercepted by GCF melee prefixes
            var nonGiantNoMeleeKind = new PawnKindDef { defName = "VanillaCustomNonMeleeKind", canMeleeAttack = false };
            vanillaWeaponlessPawn.kindDef = nonGiantNoMeleeKind;
            bool shouldUseMeleeGizmo = true;
            bool runOrigMeleeGizmo = HarmonyPatches_CombatAndHitbox.PawnAttackGizmoUtility_ShouldUseMeleeAttackGizmo_Prefix(vanillaWeaponlessPawn, ref shouldUseMeleeGizmo);
            Assert(runOrigMeleeGizmo && shouldUseMeleeGizmo,
                "ShouldUseMeleeAttackGizmo_Prefix must pass through for non-giant pawns even when canMeleeAttack == false");

            // 4. Non-giant pawns without SilhouetteGraphic / BodyGraphic must NOT be intercepted by GCF silhouette prefixes
            bool silRes = true;
            bool runOrigSil = HarmonyPatches_Rendering.SilhouetteUtility_ShouldDrawSilhouette_Prefix(vanillaWeaponlessPawn, ref silRes);
            Assert(runOrigSil && silRes,
                "SilhouetteUtility_ShouldDrawSilhouette_Prefix must pass through for non-giant pawns");

            // 5. Zero-giant map must NOT mutate Burst ConnectivitySource or fall back to DefDatabase in AnyRigSupportsCrushing / AnyRigSupportsAerialFlight
            var emptyMap = (Map)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Map));
            Assert(!GiantDestructionUtility.AnyRigSupportsCrushing(emptyMap, out bool ab, out bool ar, out bool at) && !ab && !ar && !at,
                "AnyRigSupportsCrushing(nonNullEmptyMap) must return false without falling back to global DefDatabase");
            Assert(!GiantFlightUtility.IsCellPassableForAnyAerialRig(emptyMap, new IntVec3(5, 0, 5)),
                "IsCellPassableForAnyAerialRig(nonNullEmptyMap) must return false when map has 0 giants");

            // 6. StorytellerComp_Triggered prefix must ignore non-StrangerInBlackJoin incidents
            var customIncident = new RimWorld.IncidentDef { defName = "ModdedCustomTriggeredIncident" };
            var customTriggeredProps = new RimWorld.StorytellerCompProperties_Triggered { incident = customIncident };
            var customTriggeredComp = new RimWorld.StorytellerComp_Triggered { props = customTriggeredProps };
            Assert(HarmonyPatches_VehicleAndTurrets.StorytellerComp_Triggered_NotifyPawnEvent_Prefix(customTriggeredComp, vanillaWeaponlessPawn),
                "StorytellerComp_Triggered_NotifyPawnEvent_Prefix must pass through for any incident other than StrangerInBlackJoin");

            // 7. HarmonyPatches_GiantArena must have ZERO [HarmonyPatch] startup attributes (dynamic patch-on-demand only)
            Type arenaPatchType = typeof(GiantArenaService).Assembly.GetType("GiantCreatureFramework.HarmonyPatches_GiantArena");
            Assert(arenaPatchType != null, "HarmonyPatches_GiantArena type must exist");
            Assert(arenaPatchType!.GetCustomAttributes(typeof(HarmonyPatch), inherit: false).Length == 0,
                "HarmonyPatches_GiantArena class must NOT carry [HarmonyPatch] startup attribute");
            Assert(!arenaPatchType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static)
                .Any(m => m.GetCustomAttributes(typeof(HarmonyPatch), inherit: false).Length > 0),
                "HarmonyPatches_GiantArena methods must NOT carry [HarmonyPatch] startup attributes");
            PropertyInfo isPatchedProp = arenaPatchType.GetProperty("IsPatched", BindingFlags.Public | BindingFlags.Static);
            Assert(isPatchedProp != null && !(bool)isPatchedProp.GetValue(null)!,
                "HarmonyPatches_GiantArena.IsPatched must be false when Arena is idle");

            // 8. ModSettings debug/terminal switches (all default OFF; progression toggles removed) + global trade/loot pool isolation across framework + all 5 sub-mods
            var s = new GiantCreatureFrameworkSettings();
            Assert(!s.drawCollisionCells && !s.drawHitCells && !s.drawSkeleton && !s.enableDebugPanel && !s.enableAuthoringTerminal,
                "All ModSettings debug/terminal switches must initialize to false (default OFF)");
            Assert(typeof(GiantCreatureFrameworkMod).Assembly.GetType("GiantCreatureFramework.GiantProgressionConfigDef") == null,
                "Legacy GiantProgressionConfigDef must be removed (sub-mod loading controls activation)");
            Assert(!AllMod17Roots().Any(r => File.Exists(Path.Combine(r, "Defs", "Misc", "ProgressionConfig.xml"))),
                "Legacy ProgressionConfig.xml must not exist in framework or sub-mods");

            string[] allItemXmlFiles = EnumerateAllMod17Files(Path.Combine("Defs", "ThingDefs_Items"), "*.xml");
            Assert(allItemXmlFiles.Length == 3, $"Expected 3 item XML files across sub-mods (Rathalos, Valstrax, MechColossus), got {allItemXmlFiles.Length}");
            foreach (string itemXmlFile in allItemXmlFiles)
            {
                XDocument itemDoc = XDocument.Load(itemXmlFile);
                foreach (XElement td in itemDoc.Root!.Elements("ThingDef"))
                {
                    string itemDefName = td.Element("defName")?.Value ?? "<unnamed>";
                    Assert(td.Element("tradeability")?.Value == "None", $"{itemDefName} must set <tradeability>None</tradeability>");
                    Assert(td.Element("tradeTags") == null, $"{itemDefName} must not declare any <tradeTags>");
                    Assert(td.Element("genericMarketSellable")?.Value == "false", $"{itemDefName} must set <genericMarketSellable>false</genericMarketSellable>");
                    Assert(td.Element("preventSpawningInResourcePod")?.Value == "true", $"{itemDefName} must set <preventSpawningInResourcePod>true</preventSpawningInResourcePod>");
                    Assert(td.Element("thingSetMakerTags")?.Elements("li").Any(e => e.Value == "NonStandardReward") == true,
                        $"{itemDefName} must carry NonStandardReward thingSetMakerTag");
                }
            }

            Assert(typeof(GiantCreatureFrameworkMod).Assembly.GetType("GiantCreatureFramework.GiantItemPoolIsolation") == null,
                "Redundant GiantItemPoolIsolation must be removed in favor of vanilla XML item tags");
            Assert(typeof(GiantCreatureFrameworkMod).Assembly.GetType("GiantCreatureFramework.HarmonyPatches_ItemPoolIsolation") == null,
                "Redundant HarmonyPatches_ItemPoolIsolation must be removed in favor of vanilla XML item tags");

            foreach (string raceXmlFile in EnumerateAllMod17Files(Path.Combine("Defs", "ThingDefs_Races"), "*.xml"))
            {
                XDocument raceDoc = XDocument.Load(raceXmlFile);
                foreach (XElement td in raceDoc.Root!.Elements("ThingDef"))
                {
                    if (td.Element("race") == null) continue;
                    string raceDefName = td.Element("defName")?.Value ?? "<unnamed>";
                    Assert(td.Element("tradeability")?.Value == "None", $"Race {raceDefName} must set <tradeability>None</tradeability>");
                    Assert(td.Element("tradeTags") == null, $"Race {raceDefName} must not declare any <tradeTags>");
                }
            }

            Console.WriteLine("       -> Verified zero-invasiveness non-giant guards, zero-giant map connectivity isolation, dynamic Arena patching, ModSettings toggles & peaceful World Settlement/Trade/PeaceTalks/Landmark lifecycle");
        }

        private static void TestThreeTierFootprintExteriorPerimeterAndMeleeContactLunge()
        {
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valsRig, valsMasks, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            var (scorpRig, scorpMasks, _) = LoadMechScorpionFromXml();

            // 1. BoneCollisionRole resolution (Auto vs explicit overrides)
            Assert(rathRig.TryGetNodeIndex("thorax_core", out int thoraxIdx)
                && rathRig.SortedNodes[thoraxIdx].resolvedCollisionRole == BoneCollisionRole.CoreHull,
                "Auto BoneCollisionRole on contributesToCollision=true bone must resolve to CoreHull");
            Assert(rathRig.TryGetNodeIndex("skull", out int skullIdx)
                && rathRig.SortedNodes[skullIdx].resolvedCollisionRole == BoneCollisionRole.Canopy,
                "Auto BoneCollisionRole on non-collision hitbox bone (skull) must resolve to Canopy");

            // 2. Three-tier subset invariant (collisionCells <= pawnExclusionCells <= hitCells) across headings
            GiantFootprintData RasterizeAt(GiantRigDef rig, TextureAlphaMask[] masks, IntVec3 origin, float headingDeg)
            {
                int n = rig.SortedNodes.Length;
                var local = new BoneLocalPose[n];
                Array.Fill(local, BoneLocalPose.Identity);
                var world = new BoneWorldPose[n];
                SkeletalKinematics.SolveWorldPoses(rig, new Vector2(origin.x + 0.5f, origin.z + 0.5f), headingDeg, local, new bool[n], world);
                var fp = new GiantFootprintData();
                fp.Rebuild(rig, world, masks, origin);
                return fp;
            }

            IntVec3 center = new IntVec3(80, 0, 80);
            foreach (var (rig, masks, expectCanopyWider) in new[]
            {
                (rathRig, rathMasks, true),
                (valsRig, valsMasks, true),
                (scorpRig, scorpMasks, false)
            })
            {
                foreach (float heading in new[] { 0f, 45f, 90f, 180f })
                {
                    GiantFootprintData fp = RasterizeAt(rig, masks, center, heading);
                    Assert(fp.collisionCells.Count > 0 && fp.pawnExclusionCells.Count >= fp.collisionCells.Count && fp.hitCells.Count >= fp.pawnExclusionCells.Count,
                        $"{rig.defName}@{heading} tier counts violated: col={fp.collisionCells.Count}, canopy={fp.pawnExclusionCells.Count}, hit={fp.hitCells.Count}");
                    foreach (IntVec3 cc in fp.collisionCells)
                    {
                        Assert(fp.pawnExclusionCellSet.Contains(cc) && fp.hitCellSet.Contains(cc),
                            $"{rig.defName}@{heading} CoreHull cell {cc} must belong to VisualCanopy and HitCells");
                    }
                    foreach (IntVec3 pc in fp.pawnExclusionCells)
                    {
                        Assert(fp.hitCellSet.Contains(pc),
                            $"{rig.defName}@{heading} VisualCanopy cell {pc} must belong to HitCells");
                    }
                    if (expectCanopyWider)
                    {
                        Assert(fp.pawnExclusionCells.Count >= fp.collisionCells.Count + 6,
                            $"{rig.defName}@{heading} VisualCanopy ({fp.pawnExclusionCells.Count}) must cover overhanging skull/wings/tail beyond CoreHull ({fp.collisionCells.Count})");
                    }
                }
            }

            // Verify airborne ClearCollisionVolume clears both CoreHull and VisualCanopy while keeping HitCells
            GiantFootprintData airCheck = RasterizeAt(rathRig, rathMasks, center, 0f);
            int preHits = airCheck.hitCells.Count;
            airCheck.ClearCollisionVolume();
            Assert(airCheck.collisionCells.Count == 0 && airCheck.collisionCellSet.Count == 0
                && airCheck.pawnExclusionCells.Count == 0 && airCheck.pawnExclusionCellSet.Count == 0
                && airCheck.hitCells.Count == preHits,
                "ClearCollisionVolume must empty both CoreHull and VisualCanopy while preserving aerial HitCells");

            // 3. Small-pawn Exterior Perimeter (Tier A / Tier B) guarantees 0 interior canopy cells selected
            GiantFootprintData rathFp = RasterizeAt(rathRig, rathMasks, center, 0f);
            foreach (IntVec3 pc in rathFp.pawnExclusionCells)
            {
                Assert(!rathFp.IsCellStrictExteriorTouch(pc) && !rathFp.IsCellCanopySafeTouch(pc),
                    $"Interior VisualCanopy cell {pc} must never pass Tier-A or Tier-B exterior touch checks");
            }
            int strictExteriorCount = 0;
            foreach (IntVec3 c in rathFp.tightHitBounds.ExpandedBy(1))
            {
                if (rathFp.IsCellStrictExteriorTouch(c))
                {
                    strictExteriorCount++;
                    Assert(!rathFp.hitCellSet.Contains(c) && !rathFp.pawnExclusionCellSet.Contains(c) && !rathFp.collisionCellSet.Contains(c),
                        $"Strict exterior cell {c} must lie outside all rendered HitCells");
                }
            }
            Assert(strictExteriorCount >= 24, $"Grounded Rathalos must expose >= 24 strict exterior perimeter melee slots for small pawns, got {strictExteriorCount}");

            // 4. MeleeStrikeImpactProfile precomputation + cardinal vs 45-deg diagonal visual-flesh scoring
            foreach (GiantRigDef rig in new[] { rathRig, valsRig, scorpRig })
            {
                var comp = new CompGiantRig();
                comp.Initialize(new CompProperties_GiantRig { rigDef = rig });
                var rt = new GiantPartCombatRuntime(comp);
                Assert(rt.TryGetPrimaryMeleeStrikeProfile(out MeleeStrikeImpactProfile primary) && primary.Valid,
                    $"{rig.defName} must precompute a valid primary MeleeStrikeImpactProfile");
                Assert(primary.ImpactReachFromRoot > 1.8f && primary.ImpactSpanFromAnchor > 0.8f,
                    $"{rig.defName} primary strike profile must have positive anatomical reach (root={primary.ImpactReachFromRoot:F2}, span={primary.ImpactSpanFromAnchor:F2})");
            }

            // Compare cardinal head-on contact vs 45-deg rear-corner air gap on MechScorpion vs MechScorpion,
            // plus verify rotated CoreHull octant buckets via reflection on GiantPartCombatSystem
            var scorpComp = new CompGiantRig();
            scorpComp.Initialize(new CompProperties_GiantRig { rigDef = scorpRig });
            var scorpRt = new GiantPartCombatRuntime(scorpComp);
            scorpRt.TryGetPrimaryMeleeStrikeProfile(out MeleeStrikeImpactProfile scorpPrimary);

            var scorpTargetComp = new CompGiantRig();
            scorpTargetComp.Initialize(new CompProperties_GiantRig { rigDef = scorpRig });
            FieldInfo fpField = typeof(CompGiantRig).GetField("footprint", BindingFlags.Instance | BindingFlags.NonPublic)!;
            GiantFootprintData scorpTargetFp = RasterizeAt(scorpRig, scorpMasks, center, 0f);
            fpField.SetValue(scorpTargetComp, scorpTargetFp);

            int minSolidZ = scorpTargetFp.collisionCells.Min(c => c.z);
            int minSolidX = scorpTargetFp.collisionCells.Min(c => c.x);
            int scorpFrontExt = scorpTargetFp.collisionCells.Max(c => c.z) - center.z;
            Vector2 cardinalRootXZ = new Vector2(center.x + 0.5f, minSolidZ - scorpFrontExt - 1 + 0.5f);
            Vector2 cardinalStrikeXZ = cardinalRootXZ + GiantPartCombatRuntime.RotateLocalToHeadingXZ(scorpPrimary.ImpactLocalXZ, 0f);
            float cardinalFleshGap = GiantPartCombatRuntime.MeasurePointDistanceToTargetVisualFlesh(cardinalStrikeXZ, null, scorpTargetComp);

            // 45-deg diagonal corner where unrotated/diagonal CoreHull corners sit (scorpFrontExt + 1) cells away on both X and Z
            Vector2 diagRootXZ = new Vector2(minSolidX - scorpFrontExt - 1 + 0.5f, minSolidZ - scorpFrontExt - 1 + 0.5f);
            float diagHeading = SkeletalKinematics.NormalizeAngle360(Mathf.Atan2(center.x + 0.5f - diagRootXZ.x, center.z + 0.5f - diagRootXZ.y) * Mathf.Rad2Deg - scorpPrimary.ImpactBearingDeg);
            Vector2 diagStrikeXZ = diagRootXZ + GiantPartCombatRuntime.RotateLocalToHeadingXZ(scorpPrimary.ImpactLocalXZ, diagHeading);
            float diagFleshGap = GiantPartCombatRuntime.MeasurePointDistanceToTargetVisualFlesh(diagStrikeXZ, null, scorpTargetComp);

            Assert(cardinalFleshGap <= 0.65f && diagFleshGap > cardinalFleshGap + 0.60f,
                $"Cardinal contact flesh gap ({cardinalFleshGap:F2}) must be tightly in lunge contact and strictly closer than 45-deg corner ({diagFleshGap:F2})");

            // 5. Dynamic Root Contact Micro-Lunge C1 bell-curve & strict pure pin-pivot invariant (zero child offsets, unit scale)
            AssertNear(BonePartWeaponGroup.ComputeContactLungeBell(0f, 12f, 28f), 0f, 1e-5f, "Lunge bell must start at 0");
            AssertNear(BonePartWeaponGroup.ComputeContactLungeBell(12f, 12f, 28f), 1f, 1e-5f, "Lunge bell must peak at 1 on impactTick");
            AssertNear(BonePartWeaponGroup.ComputeContactLungeBell(28f, 12f, 28f), 0f, 1e-5f, "Lunge bell must return to 0 at durationTicks");

            BonePartWeaponGroup meleeGrp = scorpRt.Groups.First(g => g.Attacks.Any(a => a.kind == GiantPartAttackKind.Melee));
            GiantPartAttackDef meleeAtk = meleeGrp.Attacks.First(a => a.kind == GiantPartAttackKind.Melee && a.attackAnim != null);
            meleeGrp.Phase = PartWeaponPhase.WarmingUp;
            meleeGrp.ActiveAttack = meleeAtk;
            meleeGrp.ActiveAttackIndex = Array.IndexOf(meleeGrp.Attacks, meleeAtk);
            meleeGrp.AnimDurationTicks = meleeAtk.attackAnim.durationTicks;
            meleeGrp.AnimImpactTick = meleeAtk.attackAnim.ResolveImpactTick();
            meleeGrp.AnimSampleTick = meleeGrp.AnimImpactTick;

            int scorpNodes = scorpRig.SortedNodes.Length;
            var posesNoLunge = new BoneLocalPose[scorpNodes];
            var posesWithLunge = new BoneLocalPose[scorpNodes];
            for (int i = 0; i < scorpNodes; i++)
            {
                posesNoLunge[i] = BoneLocalPose.Identity;
                posesWithLunge[i] = BoneLocalPose.Identity;
            }

            meleeGrp.ContactLungePeakLocalXZ = Vector2.zero;
            scorpRt.ApplyLayeredPartAnimations(scorpRig, isLocomoting: false, posesNoLunge);

            meleeGrp.ContactLungePeakLocalXZ = new Vector2(0f, 0.65f);
            scorpRt.ApplyLayeredPartAnimations(scorpRig, isLocomoting: false, posesWithLunge);

            AssertNear(posesWithLunge[0].offset.y - posesNoLunge[0].offset.y, 0.65f, 1e-4f,
                "Dynamic contact micro-lunge must advance root node local forward offset by exact peak lunge at impactTick");
            for (int i = 1; i < scorpNodes; i++)
            {
                Assert(posesWithLunge[i].offset == Vector2.zero && posesWithLunge[i].scale == Vector2.one,
                    $"Child bone {scorpRig.SortedNodes[i].nodeId} must retain strict zero offset and unit scale during root micro-lunge");
            }

            Console.WriteLine($"       -> Verified 3-tier footprint (CoreHull/VisualCanopy/HitCells), {strictExteriorCount} strict exterior small-pawn slots, impactTick strike profiles (cardinal gap={cardinalFleshGap:F2} vs diag={diagFleshGap:F2}) & pure root micro-lunge");
        }

        private static void TestSmallPawnCanopyPerimeterMeleeStandoffAndAntiBulldozerReach()
        {
            var (valsRig, valsMasks, _) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (scorpRig, scorpMasks, _) = LoadMechScorpionFromXml();

            GiantFootprintData BuildAt(GiantRigDef rig, TextureAlphaMask[] masks, IntVec3 anchor, float headingDeg)
            {
                int n = rig.SortedNodes.Length;
                var local = new BoneLocalPose[n];
                Array.Fill(local, BoneLocalPose.Identity);
                var world = new BoneWorldPose[n];
                SkeletalKinematics.SolveWorldPoses(rig, new Vector2(anchor.x + 0.5f, anchor.z + 0.5f), headingDeg, local, new bool[n], world);
                var fp = new GiantFootprintData();
                fp.Rebuild(rig, world, masks, anchor);
                return fp;
            }

            // 1. Verify zero-gap overlap bug fix: when offset[0] is 1 cell away (dSq == 1) and offset[1] overlaps targetRect (dSq == 0),
            //    both ComputeMinTranslatedHullGapToRectSq and ComputeGroupHullGapToRectSq MUST return exact 0f (not early-return 1f).
            IntVec3 testAnchor = new IntVec3(50, 0, 50);
            var syntheticOffsets = new List<IntVec3> { IntVec3.Zero, new IntVec3(0, 0, 1) };
            CellRect oneByOneAhead = CellRect.SingleCell(new IntVec3(50, 0, 51));
            AssertNear(GiantPartCombatUtility.ComputeMinTranslatedHullGapToRectSq(testAnchor, syntheticOffsets, oneByOneAhead), 0f, 1e-5f,
                "ComputeMinTranslatedHullGapToRectSq must report 0f when a later canopy offset overlaps targetRect");
            AssertNear(GiantPartCombatRuntime.ComputeGroupHullGapToRectSq(testAnchor, syntheticOffsets, oneByOneAhead), 0f, 1e-5f,
                "ComputeGroupHullGapToRectSq must report 0f when a later canopy offset overlaps targetRect");

            // 2. Verify localPawnExclusionOffsets synchronization and ShouldUseVisualCanopyPerimeterForTarget routing
            IntVec3 origin = new IntVec3(60, 0, 60);
            FieldInfo fpField = typeof(CompGiantRig).GetField("footprint", BindingFlags.Instance | BindingFlags.NonPublic)!;
            FieldInfo posField = typeof(Thing).GetField("positionInt", BindingFlags.Instance | BindingFlags.NonPublic)!;

            var smallPawnDef = new ThingDef { defName = "TestSmallColonist", category = ThingCategory.Pawn, size = IntVec2.One };
            var smallPawn = (Pawn)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Pawn));
            smallPawn.def = smallPawnDef;

            var wallDef = new ThingDef { defName = "TestWall", category = ThingCategory.Building, size = IntVec2.One };
            var wallThing = (Thing)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Thing));
            wallThing.def = wallDef;

            (GiantRigDef rig, TextureAlphaMask[] masks)[] meleeSuite =
            {
                (valsRig, valsMasks),
                (rathRig, rathMasks),
                (scorpRig, scorpMasks)
            };

            foreach (var (rig, masks) in meleeSuite)
            {
                foreach (float heading in new[] { 0f, 45f, 90f, 180f })
                {
                    GiantFootprintData fp = BuildAt(rig, masks, origin, heading);
                    Assert(fp.localPawnExclusionOffsets.Count == fp.pawnExclusionCells.Count && fp.localPawnExclusionOffsets.Count > 0,
                        $"{rig.defName}@{heading} localPawnExclusionOffsets count must equal pawnExclusionCells count");
                    for (int i = 0; i < fp.pawnExclusionCells.Count; i++)
                    {
                        Assert(origin + fp.localPawnExclusionOffsets[i] == fp.pawnExclusionCells[i],
                            $"{rig.defName}@{heading} localPawnExclusionOffsets[{i}] mismatch");
                    }
                }

                GiantFootprintData fpNorth = BuildAt(rig, masks, origin, 0f);
                var attackerComp = new CompGiantRig();
                attackerComp.Initialize(new CompProperties_GiantRig { rigDef = rig });
                fpField.SetValue(attackerComp, fpNorth);

                var otherGiantComp = new CompGiantRig();
                otherGiantComp.Initialize(new CompProperties_GiantRig { rigDef = rig });

                Assert(GiantPartCombatRuntime.ShouldUseVisualCanopyPerimeterForTarget(attackerComp, smallPawn, targetRig: null),
                    $"{rig.defName} grounded vs non-giant Pawn must use VisualCanopy perimeter");
                Assert(!GiantPartCombatRuntime.ShouldUseVisualCanopyPerimeterForTarget(attackerComp, smallPawn, targetRig: otherGiantComp),
                    $"{rig.defName} vs Giant targetRig must retain CoreHull close contact (not VisualCanopy)");
                Assert(!GiantPartCombatRuntime.ShouldUseVisualCanopyPerimeterForTarget(attackerComp, wallThing, targetRig: null),
                    $"{rig.defName} vs non-Pawn Building must retain CoreHull contact");

                // Place small 1x1 pawn 1 cell strictly ahead of VisualCanopy frontmost cell (zero canopy overlap!)
                IntVec3 frontMostExcl = fpNorth.pawnExclusionCells
                    .OrderByDescending(c => c.z)
                    .ThenBy(c => Mathf.Abs(c.x - origin.x))
                    .First();
                IntVec3 frontColonistCell = new IntVec3(frontMostExcl.x, 0, frontMostExcl.z + 1);
                Assert(!fpNorth.pawnExclusionCellSet.Contains(frontColonistCell),
                    $"{rig.defName} front colonist cell {frontColonistCell} must lie outside VisualCanopy");
                AssertNear(
                    GiantPartCombatUtility.ComputeMinTranslatedHullGapToRectSq(origin, fpNorth.localPawnExclusionOffsets, CellRect.SingleCell(frontColonistCell)),
                    1f,
                    1e-5f,
                    $"{rig.defName} front colonist cell must have exact 1-cell canopy clearance (minGapSq == 1)");

                posField.SetValue(smallPawn, frontColonistCell);
                var rt = new GiantPartCombatRuntime(attackerComp);
                float maxLungeGap = (rig.enableDynamicMeleeContactLunge ? Mathf.Clamp(rig.maxDynamicMeleeContactLungeCells, 0f, 2.0f) : 0.15f) + 0.42f;
                Vector2 rootXZ = new Vector2(origin.x + 0.5f, origin.z + 0.5f);
                Vector2 targXZ = new Vector2(frontColonistCell.x + 0.5f, frontColonistCell.z + 0.5f);
                float bearingToFront = SkeletalKinematics.NormalizeAngle360(Mathf.Atan2(targXZ.x - rootXZ.x, targXZ.y - rootXZ.y) * Mathf.Rad2Deg);
                bool canStrikeFront = rt.EvaluateCanopyPerimeterMeleeAtCell(
                    rootXZ,
                    targXZ,
                    bearingToFront,
                    smallPawn,
                    maxLungeGap,
                    out float bestHeading,
                    out float bestFleshGap,
                    out float bestDps);
                Assert(canStrikeFront && bestDps > 5f && bestFleshGap <= maxLungeGap,
                    $"{rig.defName} must reach 1x1 small pawn 1 cell ahead of VisualCanopy (z={frontColonistCell.z}, dz=+{frontColonistCell.z - origin.z}) without pushing: got canStrike={canStrikeFront}, dps={bestDps:F2}, fleshGap={bestFleshGap:F2}, limit={maxLungeGap:F2}");
            }

            // 3. Valstrax-specific checks: primary strike profile selects falcon-beak lunge bite (not tucked foreclaw),
            //    and front-quarter shoulder pockets allow simultaneous bite + foreclaw slash outside VisualCanopy!
            GiantFootprintData valsFp = BuildAt(valsRig, valsMasks, origin, 0f);
            var valsComp = new CompGiantRig();
            valsComp.Initialize(new CompProperties_GiantRig { rigDef = valsRig });
            fpField.SetValue(valsComp, valsFp);
            var valsRt = new GiantPartCombatRuntime(valsComp);

            Assert(valsRt.TryGetPrimaryMeleeStrikeProfile(out MeleeStrikeImpactProfile valsPrimary) && valsPrimary.Valid,
                "Valstrax must expose a valid primary melee strike profile");
            Assert(Mathf.Abs(Mathf.DeltaAngle(0f, valsPrimary.ImpactBearingDeg)) <= 12f && valsPrimary.ImpactReachFromRoot >= 4.8f,
                $"Valstrax primary standoff strike profile must be forward falcon-beak bite (reach >= 4.8, |bearing| <= 12), got reach={valsPrimary.ImpactReachFromRoot:F2}, bearing={valsPrimary.ImpactBearingDeg:F1}");

            float valsMaxLungeGap = Mathf.Clamp(valsRig.maxDynamicMeleeContactLungeCells, 0f, 2.0f) + 0.42f;
            bool foundDualBiteAndClawPocket = false;
            for (int dx = -4; dx <= -1; dx++)
            {
                for (int dz = 2; dz <= 5; dz++)
                {
                    IntVec3 pocketCell = new IntVec3(origin.x + dx, 0, origin.z + dz);
                    if (valsFp.pawnExclusionCellSet.Contains(pocketCell))
                    {
                        continue;
                    }
                    posField.SetValue(smallPawn, pocketCell);
                    Vector2 pXZ = new Vector2(pocketCell.x + 0.5f, pocketCell.z + 0.5f);
                    Vector2 rXZ = new Vector2(origin.x + 0.5f, origin.z + 0.5f);
                    float bearing = SkeletalKinematics.NormalizeAngle360(Mathf.Atan2(pXZ.x - rXZ.x, pXZ.y - rXZ.y) * Mathf.Rad2Deg);
                    if (valsRt.EvaluateCanopyPerimeterMeleeAtCell(rXZ, pXZ, bearing, smallPawn, valsMaxLungeGap, out _, out _, out float pocketDps)
                        && pocketDps >= 22f)
                    {
                        foundDualBiteAndClawPocket = true;
                        break;
                    }
                }
                if (foundDualBiteAndClawPocket) break;
            }
            Assert(foundDualBiteAndClawPocket,
                "Valstrax must have non-overlapping front-shoulder canopy exterior cells where both falcon-beak bite and foreclaw slash engage together");

            // 4. Verify transient melee strike canopy deferral helper (HasActiveMeleeStrikeOverlayEngaging)
            posField.SetValue(smallPawn, new IntVec3(origin.x, 0, valsFp.pawnExclusionCells.Max(c => c.z) + 1));
            Assert(!valsRt.HasActiveMeleeStrikeOverlayEngaging(smallPawn),
                "Idle Valstrax must not defer canopy push-out");
            BonePartWeaponGroup skullGrp = valsRt.Groups.First(g => g.Bone.nodeId == "skull");
            skullGrp.Phase = PartWeaponPhase.WarmingUp;
            skullGrp.ActiveAttack = skullGrp.Attacks[0];
            skullGrp.CurrentTarget = new LocalTargetInfo(smallPawn);
            Assert(valsRt.HasActiveMeleeStrikeOverlayEngaging(smallPawn),
                "Stationary Valstrax mid-bite must defer non-core canopy push-out on its engaged target pawn");
            skullGrp.Phase = PartWeaponPhase.CooldownIdle;
            skullGrp.ActiveAttack = null;
            Assert(!valsRt.HasActiveMeleeStrikeOverlayEngaging(smallPawn),
                "Completed Valstrax bite must immediately restore normal canopy push-out");

            // 5. Verify updated manuals document three-tier canopy vs melee reach alignment
            string mainManual = File.ReadAllText(Path.Combine(ModRoot, "Docs", "GiantCreatureFramework_Manual.md"));
            string capManual = File.ReadAllText(ResolveMod17Path("AgentSkills", "manuals", "framework_capabilities_and_fields.md"));
            string rigManual = File.ReadAllText(ResolveMod17Path("AgentSkills", "manuals", "rig_body_and_anim_xml.md"));
            Assert(mainManual.Contains("pawnExclusionCells", StringComparison.Ordinal) && mainManual.Contains("maxDynamicMeleeContactLungeCells", StringComparison.Ordinal),
                "Main manual must document pawnExclusionCells visual canopy standoff and maxDynamicMeleeContactLungeCells");
            Assert(capManual.Contains("maxDynamicMeleeContactLungeCells", StringComparison.Ordinal) && capManual.Contains("pawnExclusionCells", StringComparison.Ordinal),
                "Capabilities manual must document pawnExclusionCells canopy standoff and melee reach envelope");
            Assert(rigManual.Contains("contributesToCollision", StringComparison.Ordinal) && rigManual.Contains("maxDynamicMeleeContactLungeCells", StringComparison.Ordinal),
                "Rig XML manual must document contributesToCollision canopy role and melee reach validation");

            Console.WriteLine("       -> Verified 0-gap overlap fix, VisualCanopy perimeter melee reach across Valstrax/Rathalos/AbyssalDragonBeast/MechScorpion, mid-strike canopy deferral & updated manuals");
        }

        private static void TestOuterShellOrganCleaveGuardAndArenaPostKoPolish()
        {
            // 1. Verify enclosing Outside armor shell resolution across single-step and nested Inside anatomy chains
            var thoraxShell = new BodyPartRecord
            {
                def = new BodyPartDef { defName = "GCF_Part_Valstrax_Thorax", hitPoints = 220 },
                depth = BodyPartDepth.Outside,
                coverageAbs = 0.35f
            };
            var skullShell = new BodyPartRecord
            {
                def = new BodyPartDef { defName = "GCF_Part_Valstrax_Skull", hitPoints = 140 },
                depth = BodyPartDepth.Outside,
                parent = thoraxShell,
                coverageAbs = 0.12f
            };
            var brainOrgan = new BodyPartRecord
            {
                def = new BodyPartDef { defName = "GCF_Part_Valstrax_Brain", hitPoints = 95 },
                depth = BodyPartDepth.Inside,
                parent = skullShell,
                coverageAbs = 0.08f
            };
            var innerCavity = new BodyPartRecord
            {
                def = new BodyPartDef { defName = "InnerThoracicCavity", hitPoints = 100 },
                depth = BodyPartDepth.Inside,
                parent = thoraxShell,
                coverageAbs = 0.10f
            };
            var heartOrgan = new BodyPartRecord
            {
                def = new BodyPartDef { defName = "GCF_Part_Valstrax_Heart", hitPoints = 100 },
                depth = BodyPartDepth.Inside,
                parent = innerCavity,
                coverageAbs = 0.05f
            };
            thoraxShell.parts = new List<BodyPartRecord> { skullShell, innerCavity };
            skullShell.parts = new List<BodyPartRecord> { brainOrgan };
            innerCavity.parts = new List<BodyPartRecord> { heartOrgan };

            Assert(GiantCombatMechanicsUtility.FindEnclosingOutsideShellPart(brainOrgan) == skullShell,
                "Brain Inside part must resolve directly to enclosing Outside skullShell");
            Assert(GiantCombatMechanicsUtility.FindEnclosingOutsideShellPart(heartOrgan) == thoraxShell,
                "Nested Heart Inside part must walk parent chain to enclosing Outside thoraxShell");
            Assert(GiantCombatMechanicsUtility.FindEnclosingOutsideShellPart(skullShell) == null,
                "Outside shell part must return null from FindEnclosingOutsideShellPart");

            // 2. Verify pure helper blocks Cut cleave & Stab internal splash while preserving explicit internal / chest-burst damage
            var rigDef = new GiantRigDef { defName = "TestRig_ShellGuard", enableLimbPartDamageRouting = true };
            var attackerPawn = (Pawn)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Pawn));
            var cutDef = new DamageDef { defName = "Cut", workerClass = typeof(DamageWorker_Cut), harmsHealth = true };
            var stabDef = new DamageDef { defName = "Stab", workerClass = typeof(DamageWorker_Stab), harmsHealth = true, harmAllLayersUntilOutside = true };
            var bombDef = new DamageDef { defName = "Bomb", harmsHealth = true, isExplosive = true };

            // DamageWorker_Cut.ApplySpecialEffectsToPart clones dinfo and calls dinfo3.SetHitPart(brainOrgan) before FinalizeAndAddInjury
            var cutCleaveDinfo = new DamageInfo(cutDef, 48f, armorPenetration: 0.95f, angle: 90f, instigator: attackerPawn, hitPart: brainOrgan);
            Assert(GiantCombatMechanicsUtility.ShouldRedirectInternalOrganInjuryToOuterShell(
                    null, rigDef, brainOrgan, skullShell, shellPartIsMissing: false, shellHpPct: 0.95f, in cutCleaveDinfo),
                "External Cut cleave onto Brain must redirect to intact Outside skullShell (95% HP)");
            Assert(GiantCombatMechanicsUtility.ShouldRedirectInternalOrganInjuryToOuterShell(
                    null, rigDef, brainOrgan, skullShell, shellPartIsMissing: false, shellHpPct: 0.20f, in cutCleaveDinfo),
                "External Cut cleave onto Brain must still redirect even when skullShell is battered (20% HP, breachRoll01=1f)");

            var stabSplashDinfo = new DamageInfo(stabDef, 42f, armorPenetration: 1.25f, angle: 90f, instigator: attackerPawn, hitPart: heartOrgan);
            Assert(GiantCombatMechanicsUtility.ShouldRedirectInternalOrganInjuryToOuterShell(
                    null, rigDef, heartOrgan, thoraxShell, shellPartIsMissing: false, shellHpPct: 0.85f, in stabSplashDinfo),
                "External Stab internal splash onto Heart must redirect to intact Outside thoraxShell");

            Assert(!GiantCombatMechanicsUtility.ShouldRedirectInternalOrganInjuryToOuterShell(
                    null, rigDef, brainOrgan, skullShell, shellPartIsMissing: true, shellHpPct: 0f, in cutCleaveDinfo),
                "Missing Outside shell must not redirect injury onto a destroyed part");

            // CompValstraxDragonEnergy chest backfire: Bomb, instigator == null, SetAllowDamagePropagation(false)
            var chestBurstDinfo = new DamageInfo(bombDef, 55f, armorPenetration: 0.85f, angle: -1f, instigator: null, hitPart: heartOrgan);
            chestBurstDinfo.SetAllowDamagePropagation(false);
            Assert(GiantCombatMechanicsUtility.IsExplicitInternalOrSelfBurstDamage(null, heartOrgan, in chestBurstDinfo),
                "Valstrax chest-burst internal Bomb self-damage must be recognized as explicit internal damage");
            Assert(!GiantCombatMechanicsUtility.ShouldRedirectInternalOrganInjuryToOuterShell(
                    null, rigDef, heartOrgan, thoraxShell, shellPartIsMissing: false, shellHpPct: 1.0f, in chestBurstDinfo),
                "Valstrax chest-burst internal damage must NOT be blocked by outer-shell cleave guard");

            // Explicit Depth == BodyPartDepth.Inside (surgical or ResolveHitBodyPartForBone compromised-shell breach)
            var explicitInsideDinfo = new DamageInfo(cutDef, 35f, armorPenetration: 0.95f, angle: 0f, instigator: attackerPawn, hitPart: brainOrgan);
            explicitInsideDinfo.SetBodyRegion(BodyPartHeight.Undefined, BodyPartDepth.Inside);
            Assert(!GiantCombatMechanicsUtility.ShouldRedirectInternalOrganInjuryToOuterShell(
                    null, rigDef, brainOrgan, skullShell, shellPartIsMissing: false, shellHpPct: 0.20f, in explicitInsideDinfo),
                "Explicit Depth == Inside hit must NOT be redirected by outer-shell cleave guard");

            // 3. End-to-end Harmony prefix test on DamageWorker_AddInjury.FinalizeAndAddInjury
            MethodInfo finalizeInjuryTarget = AccessTools.Method(
                typeof(DamageWorker_AddInjury),
                "FinalizeAndAddInjury",
                new[] { typeof(Pawn), typeof(Hediff_Injury), typeof(DamageInfo), typeof(DamageWorker.DamageResult) });
            Assert(finalizeInjuryTarget != null,
                "DamageWorker_AddInjury.FinalizeAndAddInjury(Pawn, Hediff_Injury, DamageInfo, DamageResult) must exist in RimWorld 1.7");

            var bodyDef = new BodyDef { defName = "TestBody_ShellGuard", corePart = thoraxShell };
            FieldInfo cachedAllPartsField = AccessTools.Field(typeof(BodyDef), "cachedAllParts");
            cachedAllPartsField?.SetValue(bodyDef, new List<BodyPartRecord> { thoraxShell, skullShell, brainOrgan, innerCavity, heartOrgan });

            var testRaceDef = new ThingDef
            {
                defName = "TestGiant_ShellGuard",
                shortHash = 61234,
                race = new RaceProperties { body = bodyDef, baseHealthScale = 17.5f, intelligence = Intelligence.Animal }
            };
            var giantPawn = new Pawn { thingIDNumber = 999876, def = testRaceDef };
            giantPawn.health = new Pawn_HealthTracker(giantPawn);
            var giantComp = new CompGiantRig { parent = giantPawn };
            giantComp.Initialize(new CompProperties_GiantRig { rigDef = rigDef });
            giantPawn.AllComps.Add(giantComp);

            var nonGiantPawn = new Pawn { thingIDNumber = 999877, def = testRaceDef };
            nonGiantPawn.health = new Pawn_HealthTracker(nonGiantPawn);

            GiantFastLookup.Register(giantPawn, giantComp);
            try
            {
                var cleaveInjury = new Hediff_Injury { pawn = giantPawn, def = new HediffDef { defName = "Cut" } };
                cleaveInjury.Part = brainOrgan;
                DamageInfo liveCleaveDinfo = cutCleaveDinfo;
                HarmonyPatches_CombatAndHitbox.DamageWorker_AddInjury_FinalizeAndAddInjury_Prefix(
                    giantPawn,
                    cleaveInjury,
                    ref liveCleaveDinfo);
                Assert(cleaveInjury.Part == skullShell && liveCleaveDinfo.HitPart == skullShell,
                    "FinalizeAndAddInjury_Prefix must redirect Brain cleave injury and dinfo.HitPart onto enclosing Outside skullShell");

                var burstInjury = new Hediff_Injury { pawn = giantPawn, def = new HediffDef { defName = "Shredded" } };
                burstInjury.Part = heartOrgan;
                DamageInfo liveBurstDinfo = chestBurstDinfo;
                HarmonyPatches_CombatAndHitbox.DamageWorker_AddInjury_FinalizeAndAddInjury_Prefix(
                    giantPawn,
                    burstInjury,
                    ref liveBurstDinfo);
                Assert(burstInjury.Part == heartOrgan && liveBurstDinfo.HitPart == heartOrgan,
                    "FinalizeAndAddInjury_Prefix must preserve explicit internal chest-burst injury on Heart");

                var vanillaInjury = new Hediff_Injury { pawn = nonGiantPawn, def = new HediffDef { defName = "Cut" } };
                vanillaInjury.Part = brainOrgan;
                DamageInfo vanillaCleaveDinfo = cutCleaveDinfo;
                HarmonyPatches_CombatAndHitbox.DamageWorker_AddInjury_FinalizeAndAddInjury_Prefix(
                    nonGiantPawn,
                    vanillaInjury,
                    ref vanillaCleaveDinfo);
                Assert(vanillaInjury.Part == brainOrgan,
                    "FinalizeAndAddInjury_Prefix must pass through untouched for non-giant pawns");
            }
            finally
            {
                GiantFastLookup.Unregister(giantPawn);
            }

            // 4. Verify Giant Arena fighter label rich-text stripping, post-KO job classification & RimWorld 1.7 dynamic patch targets
            Assert(GiantArenaFighterSnapshot.SanitizeLabel("卡罗莱娜<color=#999999FF>, 勇者</color>") == "卡罗莱娜, 勇者",
                "SanitizeLabel must strip <color=#999999FF> tags cleanly");
            Assert(GiantArenaFighterSnapshot.SanitizeLabel("(*Name)卡罗莱娜(/Name)<color=#999999FF>, 勇者</color>") == "卡罗莱娜, 勇者",
                "SanitizeLabel must strip both (*Tag) and <color> rich-text markup");
            Assert(GiantArenaFighterSnapshot.SanitizeLabel(null) == string.Empty && GiantArenaFighterSnapshot.SanitizeLabel("   ") == string.Empty,
                "SanitizeLabel must normalize null/whitespace to empty string");

            Assert(GiantArenaService.IsHostileOrNonCalmPostMatchJob(new Verse.AI.Job { def = new JobDef { defName = "AttackMelee" } }),
                "AttackMelee must be classified as non-calm post-KO job");
            Assert(GiantArenaService.IsHostileOrNonCalmPostMatchJob(new Verse.AI.Job { def = new JobDef { defName = "CastAbilityOnThing", abilityCasting = true } }),
                "CastAbilityOnThing must be classified as non-calm post-KO job");
            Assert(GiantArenaService.IsHostileOrNonCalmPostMatchJob(new Verse.AI.Job { def = new JobDef { defName = "Wait_Combat" } }),
                "Wait_Combat must be classified as non-calm post-KO job");
            Assert(!GiantArenaService.IsHostileOrNonCalmPostMatchJob(new Verse.AI.Job { def = new JobDef { defName = "Wait" } }),
                "Calm standing Wait must NOT be interrupted repeatedly during post-KO hold");
            Assert(!GiantArenaService.IsHostileOrNonCalmPostMatchJob(new Verse.AI.Job { def = new JobDef { defName = "Wait_Downed" } }),
                "Wait_Downed must NOT be classified as hostile post-KO job");

            Assert(AccessTools.Method(typeof(RimWorld.MoteMaker), nameof(RimWorld.MoteMaker.MakeInteractionBubble)) != null
                && AccessTools.Method(typeof(RimWorld.MoteMaker), nameof(RimWorld.MoteMaker.MakeSpeechBubble)) != null
                && AccessTools.Method(typeof(RimWorld.MoteMaker), nameof(RimWorld.MoteMaker.MakeMoodThoughtBubble)) != null,
                "RimWorld 1.7 MoteMaker bubble targets must exist for CleanVideoMode suppression");
            Assert(AccessTools.Method(typeof(Pawn), nameof(Pawn.TryStartAttack)) != null
                && AccessTools.Method(typeof(RimWorld.Pawn_MeleeVerbs), nameof(RimWorld.Pawn_MeleeVerbs.TryMeleeAttack)) != null
                && AccessTools.Method(typeof(Verb), nameof(Verb.TryStartCastOn),
                    new[] { typeof(LocalTargetInfo), typeof(LocalTargetInfo), typeof(bool), typeof(bool), typeof(bool), typeof(bool) }) != null
                && AccessTools.Method(typeof(RimWorld.Verb_MeleeAttack), "TryCastShot") != null
                && AccessTools.Method(typeof(Verb_LaunchProjectile), "TryCastShot") != null
                && AccessTools.Method(typeof(RimWorld.Ability), nameof(RimWorld.Ability.Activate), new[] { typeof(LocalTargetInfo), typeof(LocalTargetInfo) }) != null
                && AccessTools.Method(typeof(RimWorld.Ability), nameof(RimWorld.Ability.QueueCastingJob), new[] { typeof(LocalTargetInfo), typeof(LocalTargetInfo) }) != null
                && AccessTools.Method(typeof(RimWorld.JobGiver_AIFightEnemy), "TryGiveJob") != null
                && AccessTools.Method(typeof(RimWorld.JobGiver_ReactToCloseMeleeThreat), "TryGiveJob") != null
                && AccessTools.Method(typeof(RimWorld.JobGiver_Manhunter), "TryGiveJob") != null
                && AccessTools.Method(typeof(RimWorld.JobGiver_Berserk), "TryGiveJob") != null,
                "All RimWorld 1.7 Arena post-KO combat/ability lock targets must resolve cleanly");

            Console.WriteLine("       -> Verified Outer-Shell Cut/Stab organ guard, Valstrax chest-burst exemption, <color> label sanitizer, post-KO job calm hold & RimWorld 1.7 Arena patch targets");
        }

        private static void TestGiantPivotTurnBeforeMoveAndCanopyStandoff()
        {
            const float tankPivotRate = 1.80f;
            const float tankMovingRate = 1.10f;

            var (scorpRig, _, scorpAnims) = LoadMechScorpionFromXml();
            var (rathRig, rathMasks, rathAnims) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (valsRig, valsMasks, valsAnims) = LoadRigFromXml("GiantRigDefs_Valstrax.xml", "GiantAnimDefs_Valstrax.xml", "GCF_Rig_Valstrax");
            var (colS1, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage1");
            var (colS2, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage2");
            var (colS3, _, _) = LoadRigFromXml("GiantRigDefs_MechColossus.xml", "GiantAnimDefs_MechColossus.xml", "GCF_Rig_MechColossus_Stage3");

            // Resolve MechScorpion turnLeftAnim / turnRightAnim from XML
            XElement scorpEl = XDocument.Load(ResolveMod17Path("Defs", "GiantRigDefs", "GiantRigDefs_MechScorpion.xml"))
                .Root!.Element("GiantCreatureFramework.GiantRigDef")!;
            string scorpTurnL = scorpEl.Element("turnLeftAnim")?.Value ?? string.Empty;
            string scorpTurnR = scorpEl.Element("turnRightAnim")?.Value ?? string.Empty;
            bool okL = scorpAnims.TryGetValue(scorpTurnL, out GiantAnimDef scorpTurnLDef);
            bool okR = scorpAnims.TryGetValue(scorpTurnR, out GiantAnimDef scorpTurnRDef);
            Assert(okL && okR,
                $"MechScorpion must wire valid turnLeftAnim ({scorpTurnL}) and turnRightAnim ({scorpTurnR})");
            scorpRig.turnLeftAnim = scorpTurnLDef;
            scorpRig.turnRightAnim = scorpTurnRDef;

            XElement rathEl = XDocument.Load(ResolveMod17Path("Defs", "GiantRigDefs", "GiantRigDefs_Rathalos.xml"))
                .Root!.Element("GiantCreatureFramework.GiantRigDef")!;
            rathRig.turnLeftAnim = rathAnims[rathEl.Element("turnLeftAnim")!.Value];
            rathRig.turnRightAnim = rathAnims[rathEl.Element("turnRightAnim")!.Value];

            XElement valsEl = XDocument.Load(ResolveMod17Path("Defs", "GiantRigDefs", "GiantRigDefs_Valstrax.xml"))
                .Root!.Element("GiantCreatureFramework.GiantRigDef")!;
            valsRig.turnLeftAnim = valsAnims[valsEl.Element("turnLeftAnim")!.Value];
            valsRig.turnRightAnim = valsAnims[valsEl.Element("turnRightAnim")!.Value];

            // 1. Verify all non-vehicle Giants have turn speeds strictly slightly faster than PanzerIV (1.80 pivot / 1.10 moving) with zero hidden combat multiplier
            GiantRigDef[] nonVehicleRigs = { colS1, colS2, colS3, scorpRig, rathRig, valsRig };
            foreach (GiantRigDef r in nonVehicleRigs)
            {
                Assert(r.enablePivotTurnBeforeMove, $"{r.defName} must enable pivot-turn-before-move by default");
                float pivotRate = CompGiantRig.ComputeEffectiveBodyTurnSpeed(
                    r.turnSpeedDegPerTick,
                    r.movingTurnSpeedFactor,
                    isMovingAlongGroundPath: false,
                    isPivotTurningInPlace: true,
                    hasActiveLinearDashDir: false);
                float movingRate = CompGiantRig.ComputeEffectiveBodyTurnSpeed(
                    r.turnSpeedDegPerTick,
                    r.movingTurnSpeedFactor,
                    isMovingAlongGroundPath: true,
                    isPivotTurningInPlace: false,
                    hasActiveLinearDashDir: false);

                Assert(pivotRate > tankPivotRate && pivotRate <= 2.55f,
                    $"{r.defName} pivot turn speed ({pivotRate:F2} deg/t) must be slightly faster than PanzerIV ({tankPivotRate:F2}) and <= 2.55 deg/t");
                Assert(movingRate > tankMovingRate && movingRate <= 1.75f,
                    $"{r.defName} moving turn speed ({movingRate:F2} deg/t) must be slightly faster than PanzerIV ({tankMovingRate:F2}) and <= 1.75 deg/t");
                AssertNear(pivotRate, r.turnSpeedDegPerTick, 1e-5f,
                    $"{r.defName} stationary/pivot combat turn must have zero hidden speed multiplier");
            }

            // 2. Verify Pivot-Before-Move hysteresis gate, TurnInPlace anti-pedal latch & legged Giant TurnLeft / TurnRight animation validity
            Assert(!CompGiantRig.StepPivotTurnHysteresis(false, 28f, 32f, 9f), "28 deg below 32 deg enter threshold must not trigger pivot");
            Assert(CompGiantRig.StepPivotTurnHysteresis(false, 35f, 32f, 9f), "35 deg above 32 deg enter threshold must trigger in-place pivot");
            Assert(CompGiantRig.StepPivotTurnHysteresis(true, 16f, 32f, 9f), "Latched pivot must remain active at 16 deg until <= 9 deg exit");
            Assert(!CompGiantRig.StepPivotTurnHysteresis(true, 8.5f, 32f, 9f), "Latched pivot must release cleanly once aligned within 9 deg");

            Assert(!CompGiantRig.StepTurnInPlaceAnimLatch(false, false, 12f, 2.0f),
                "Small <= 12 deg combat tracking must NOT trigger full-leg TurnInPlace pedaling");
            Assert(CompGiantRig.StepTurnInPlaceAnimLatch(false, true, 12f, 0f),
                "Active PivotTurnBeforeMove must latch TurnInPlace immediately");
            Assert(CompGiantRig.StepTurnInPlaceAnimLatch(false, false, 28f, 2.0f),
                ">= 22 deg stationary body reorientation must latch TurnInPlace");
            Assert(CompGiantRig.StepTurnInPlaceAnimLatch(true, false, 10f, 1.8f),
                "Latched TurnInPlace must continue smoothly at 10 deg remaining");
            Assert(!CompGiantRig.StepTurnInPlaceAnimLatch(true, false, 3.0f, 0.2f),
                "Latched TurnInPlace must settle back to planted Idle once <= 4.5 deg");

            var expiryRig = new CompGiantRig();
            expiryRig.Initialize(new CompProperties_GiantRig { rigDef = rathRig });
            typeof(CompGiantRig).GetField("currentHeadingDeg", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(expiryRig, 0f);
            typeof(CompGiantRig).GetField("headingInitialized", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(expiryRig, true);
            int alignedExpiry = GiantPartCombatUtility.ComputePivotAwareGotoExpiryTicks(expiryRig, new IntVec3(50, 0, 50), new IntVec3(50, 0, 58), 50);
            int oppositeExpiry = GiantPartCombatUtility.ComputePivotAwareGotoExpiryTicks(expiryRig, new IntVec3(50, 0, 50), new IntVec3(50, 0, 42), 50);
            AssertNear(alignedExpiry, 50f, 1e-4f, "Aligned forward Goto must keep base 50-tick expiry");
            Assert(oppositeExpiry >= 135, $"180-deg pivot Goto must expand expiry >= 135 ticks so pivot finishes before Goto expires (got {oppositeExpiry})");

            foreach (GiantRigDef legged in new[] { scorpRig, rathRig, valsRig })
            {
                Assert(legged.turnLeftAnim != null && legged.turnLeftAnim.loop && legged.turnRightAnim != null && legged.turnRightAnim.loop,
                    $"{legged.defName} must provide looping turnLeftAnim & turnRightAnim");
                Assert(!legged.ValidateExtraClipRigidAndChildOffsets(legged.turnLeftAnim, "turnLeftAnim").Any(),
                    $"{legged.defName} turnLeftAnim failed child-offset/rigid validation");
                Assert(!legged.ValidateExtraClipRigidAndChildOffsets(legged.turnRightAnim, "turnRightAnim").Any(),
                    $"{legged.defName} turnRightAnim failed child-offset/rigid validation");
            }

            // 3. Verify non-rear melee sectors never fire astern, while rear tail-sweep overlays engage 180 deg behind immediately
            foreach (GiantRigDef bioRig in new[] { rathRig, valsRig, scorpRig })
            {
                int frontCount = 0;
                int rearCount = 0;
                foreach (BoneNodeDef node in bioRig.SortedNodes)
                {
                    if (node.partAttacks == null) continue;
                    foreach (GiantPartAttackDef atk in node.partAttacks)
                    {
                        if (atk.kind != GiantPartAttackKind.Melee) continue;
                        if (GiantPartCombatRuntime.IsRearSectorMeleeAttack(atk))
                        {
                            rearCount++;
                            Assert(atk.independentOverlay, $"{bioRig.defName}.{atk.attackId} rear counterattack must use independentOverlay=true");
                            float errAt180 = Mathf.Abs(Mathf.DeltaAngle(atk.sectorCenterDeg, 180f));
                            Assert(errAt180 <= atk.sectorHalfAngleDeg, $"{bioRig.defName}.{atk.attackId} must cover 180 deg rear sector");
                        }
                        else
                        {
                            frontCount++;
                            float maxReachOffBow = Mathf.Abs(Mathf.DeltaAngle(0f, atk.sectorCenterDeg)) + atk.sectorHalfAngleDeg;
                            Assert(maxReachOffBow <= 115f,
                                $"{bioRig.defName}.{atk.attackId} non-rear melee reach ({maxReachOffBow:F1} deg off-bow) must be <= 115 deg so giant turns before striking");
                        }
                    }
                }
                Assert(frontCount > 0, $"{bioRig.defName} must have frontal/flank melee attacks");
                if (bioRig != scorpRig)
                {
                    Assert(rearCount > 0, $"{bioRig.defName} must preserve rear tail-sweep counterattack");
                }
            }

            // 4. Verify Small-Pawn MakeDestination Canopy Standoff rejects overlapping cells and preserves clean exterior perimeter cells
            var fp = new GiantFootprintData();
            int vn = valsRig.SortedNodes.Length;
            var localP = new BoneLocalPose[vn];
            Array.Fill(localP, BoneLocalPose.Identity);
            var missM = new bool[vn];
            var worldP = new BoneWorldPose[vn];
            SkeletalKinematics.SolveWorldPoses(valsRig, new Vector2(100.5f, 100.5f), 0f, localP, missM, worldP);
            fp.Rebuild(valsRig, worldP, valsMasks, new IntVec3(100, 0, 100));
            Assert(fp.localPawnExclusionOffsets.Count > fp.localCollisionOffsets.Count,
                "Valstrax visual canopy must be broader than core collision hull");

            GiantPartCombatUtility.PopulateRotatedHullBuckets(fp.localPawnExclusionOffsets);
            CellRect smallPawnRect = CellRect.SingleCell(new IntVec3(100, 0, 100));
            HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallPawnCanopyStandoff(
                new IntVec3(100, 0, 100),
                fp.localPawnExclusionOffsets,
                valsRig.meleeTouchRadius,
                smallPawnRect,
                out _,
                out bool centerOverlaps);
            Assert(centerOverlaps, "Placing giant center directly on small pawn cell (100,100) must be flagged as canopy overlap");

            int cleanPerimeterCount = 0;
            for (int dz = -12; dz <= 12; dz++)
            {
                for (int dx = -12; dx <= 12; dx++)
                {
                    IntVec3 cand = new IntVec3(100 + dx, 0, 100 + dz);
                    Vector2 toSmall = new Vector2(-dx, -dz);
                    float brg = toSmall.sqrMagnitude > 0.01f
                        ? SkeletalKinematics.NormalizeAngle360(Mathf.Atan2(toSmall.x, toSmall.y) * Mathf.Rad2Deg)
                        : 0f;
                    int oct = ((Mathf.RoundToInt(Mathf.DeltaAngle(0f, brg) / 45f) % 8) + 8) % 8;
                    IReadOnlyList<IntVec3> aligned = GiantPartCombatUtility.GetRotatedHullOffsetsBucket(fp.localPawnExclusionOffsets, oct);
                    HarmonyPatches_CombatAndHitbox.EvaluateGiantSmallPawnCanopyStandoff(
                        cand,
                        aligned,
                        2.0f,
                        smallPawnRect,
                        out bool inTouch,
                        out bool ovAligned);
                    bool ovCur = GiantPartCombatUtility.ComputeMinTranslatedHullGapToRectSq(cand, fp.localPawnExclusionOffsets, smallPawnRect) <= 0.01f;
                    if (inTouch && !ovAligned && !ovCur)
                    {
                        cleanPerimeterCount++;
                    }
                }
            }
            Assert(cleanPerimeterCount >= 16,
                $"Expected >= 16 clean non-overlapping canopy perimeter cells around 1x1 pawn, got {cleanPerimeterCount}");

            Console.WriteLine($"       -> Turn rates verified (>PanzerIV {tankPivotRate:F2} deg/t, Valstrax={valsRig.turnSpeedDegPerTick:F2} deg/t), Pivot-Before-Move hysteresis + 3 legged TurnLeft/TurnRight clips + sector checks + {cleanPerimeterCount} clean canopy standoff cells verified");
        }

        private static void TestModularSubmodSplitAndFrameworkPurity()
        {
            // 1. Framework purity: ONLY GCF_MechScorpion remains in GiantCreatureFramework, 0 AssetBundles, 0 sub-mod creature C# types
            string[] fwRaceXmls = Directory.GetFiles(Path.Combine(ModRoot, "1.7", "Defs", "ThingDefs_Races"), "*.xml");
            Assert(fwRaceXmls.Length == 1 && Path.GetFileName(fwRaceXmls[0]) == "Races_MechScorpion.xml",
                $"GiantCreatureFramework must contain ONLY Races_MechScorpion.xml in 1.7/Defs/ThingDefs_Races, got [{string.Join(", ", fwRaceXmls.Select(Path.GetFileName))}]");
            string[] fwRigXmls = Directory.GetFiles(Path.Combine(ModRoot, "1.7", "Defs", "GiantRigDefs"), "*.xml");
            Assert(fwRigXmls.Length == 1 && Path.GetFileName(fwRigXmls[0]) == "GiantRigDefs_MechScorpion.xml",
                "GiantCreatureFramework must contain ONLY GiantRigDefs_MechScorpion.xml in 1.7/Defs/GiantRigDefs");
            Assert(!Directory.Exists(Path.Combine(ModRoot, "1.7", "AssetBundles"))
                   || Directory.GetFiles(Path.Combine(ModRoot, "1.7", "AssetBundles")).Length == 0,
                "GiantCreatureFramework must not retain any creature-specific AssetBundles");

            foreach (Type fwType in typeof(GiantCreatureFrameworkMod).Assembly.GetTypes())
            {
                string tn = fwType.FullName ?? string.Empty;
                Assert(!tn.Contains("Rathalos", StringComparison.OrdinalIgnoreCase)
                       && !tn.Contains("Valstrax", StringComparison.OrdinalIgnoreCase)
                       && !tn.Contains("MechColossus", StringComparison.OrdinalIgnoreCase)
                       && !tn.Contains("AbyssalDragonBeast", StringComparison.OrdinalIgnoreCase),
                    $"GiantCreatureFramework.dll must not contain creature-specific type '{tn}'");
            }

            // 2. Verify all 5 [GCF]* sub-mods in workspace AND deployed Steam Mods directory
            (string folder, string expectedName, string expectedPkgId, string expectedDll)[] subSpecs =
            {
                ("[GCF]Rathalos", "[GCF]Rathalos", "sanguo.giantcreatureframework.rathalos", "GCF.Rathalos.dll"),
                ("[GCF]Valstrax", "[GCF]Valstrax", "sanguo.giantcreatureframework.valstrax", "GCF.Valstrax.dll"),
                ("[GCF]Mech Colossus", "[GCF]Mech Colossus", "sanguo.giantcreatureframework.mechcolossus", "GCF.MechColossus.dll"),
                ("[GCF]Panzer IV", "[GCF]Panzer IV", "sanguo.giantcreatureframework.panzeriv", "GCF.PanzerIV.dll"),
                ("[GCF]Protoss Carrier", "[GCF]Protoss Carrier", "sanguo.giantcreatureframework.protosscarrier", "GCF.ProtossCarrier.dll")
            };

            string steamModsRoot = @"D:\Steam\steamapps\common\RimWorld\Mods";
            foreach (var sp in subSpecs)
            {
                string wsDir = Path.Combine(ModsParentDir, sp.folder);
                Assert(Directory.Exists(wsDir), $"Missing workspace sub-mod directory: {wsDir}");

                XDocument aboutDoc = XDocument.Load(Path.Combine(wsDir, "About", "About.xml"));
                Assert(aboutDoc.Root?.Element("name")?.Value == sp.expectedName,
                    $"{sp.folder} About.xml <name> must equal '{sp.expectedName}'");
                Assert(aboutDoc.Root?.Element("packageId")?.Value == sp.expectedPkgId,
                    $"{sp.folder} About.xml <packageId> must equal '{sp.expectedPkgId}'");
                Assert(aboutDoc.Descendants("packageId").Any(e => e.Value == "sanguo.giantcreatureframework"),
                    $"{sp.folder} About.xml must declare modDependency on sanguo.giantcreatureframework");
                Assert(File.Exists(Path.Combine(wsDir, "LoadFolders.xml")), $"{sp.folder} missing LoadFolders.xml");

                string[] dlls = Directory.GetFiles(Path.Combine(wsDir, "1.7", "Assemblies"), "*.dll");
                Assert(dlls.Length == 1 && Path.GetFileName(dlls[0]) == sp.expectedDll,
                    $"{sp.folder}/1.7/Assemblies must contain ONLY {sp.expectedDll} (never duplicate GiantCreatureFramework.dll/Harmony), got [{string.Join(", ", dlls.Select(Path.GetFileName))}]");

                if (Directory.Exists(steamModsRoot))
                {
                    string depDir = Path.Combine(steamModsRoot, sp.folder);
                    Assert(Directory.Exists(depDir) && File.Exists(Path.Combine(depDir, "1.7", "Assemblies", sp.expectedDll)),
                        $"Sub-mod {sp.folder} must be synced to Steam RimWorld Mods directory ({depDir})");
                }
            }

            if (Directory.Exists(steamModsRoot))
            {
                string depFw = Path.Combine(steamModsRoot, "GiantCreatureFramework");
                Assert(Directory.Exists(depFw) && !Directory.Exists(Path.Combine(depFw, "1.7", "Anomaly")),
                    "Deployed GiantCreatureFramework in Steam Mods must also be synced cleanly without 1.7/Anomaly");
            }

            Console.WriteLine("       -> Verified lean GiantCreatureFramework (MechScorpion only, 0 creature types/AssetBundles), 100% Abyssal purge, & 5 standalone [GCF]* sub-mods synced to Steam Mods");
        }

        private static void TestGiantWoundBloodOverlaysAndAnatomicalGroundFilth()
        {
            // 1. Verify all 11 wound/bloodstain/scar/bandage textures exist on disk, decode cleanly, and keep alpha=0 outer border
            string woundsDir = Path.Combine(ModRoot, "1.7", "Textures", "Things", "Pawn", "GiantCreature", "Wounds");
            string[] expectedPngs =
            {
                "BloodSlashA.png", "BloodSlashB.png", "BloodSlashC.png",
                "BloodStainA.png", "BloodStainB.png", "BloodStainC.png",
                "MechScarA.png", "MechScarB.png", "MechScarC.png",
                "BandageWrapA.png", "BandageWrapB.png"
            };
            foreach (string fn in expectedPngs)
            {
                string full = Path.Combine(woundsDir, fn);
                Assert(File.Exists(full), $"Missing GCF wound overlay texture: {full}");
                Color32[] px = TextureAlphaMask.DecodePngRgbaBottomUpFromFile(full, out int w, out int h);
                Assert(w == 256 && h == 256 && px.Length == 65536, $"{fn} must be 256x256 RGBA");
                Assert(px[0].a == 0 && px[255].a == 0 && px[65535].a == 0, $"{fn} outer corners must be alpha=0 to prevent Clamp streaking");
                bool anyCoreOpaque = px.Any(c => c.a >= 180);
                Assert(anyCoreOpaque, $"{fn} must contain crisp opaque core pixels");
            }

            // 2. Verify Harmony DropBloodFilth prefix target resolves cleanly in RimWorld 1.7
            Assert(AccessTools.Method(typeof(Pawn_HealthTracker), "DropBloodFilth") != null
                   && AccessTools.Method(typeof(HarmonyPatches_CombatAndHitbox), nameof(HarmonyPatches_CombatAndHitbox.Pawn_HealthTracker_DropBloodFilth_Prefix)) != null,
                "Pawn_HealthTracker.DropBloodFilth Harmony prefix must resolve cleanly");

            // 3. Load Rathalos (skinned organic) & MechScorpion (rigid non-organic mechanoid) rigs + real PNG alpha masks
            var (rathRig, rathMasks, _) = LoadRigFromXml("GiantRigDefs_Rathalos.xml", "GiantAnimDefs_Rathalos.xml", "GCF_Rig_Rathalos");
            var (scorpRig, scorpMasks, _) = LoadRigFromXml("GiantRigDefs_MechScorpion.xml", "GiantAnimDefs_MechScorpion.xml", "GCF_Rig_MechScorpion");
            BodyDef rathBody = LoadBodyDefFromXml("Bodies_Rathalos.xml", "GCF_Body_Rathalos");
            BodyDef scorpBody = LoadBodyDefFromXml("Bodies_MechScorpion.xml", "GCF_Body_MechScorpion");
            static void PopulateCachedAllParts(BodyDef bDef)
            {
                var list = new List<BodyPartRecord>();
                static void WalkParts(BodyPartRecord r, List<BodyPartRecord> dst)
                {
                    if (r == null) return;
                    dst.Add(r);
                    if (r.parts == null) return;
                    for (int i = 0; i < r.parts.Count; i++) WalkParts(r.parts[i], dst);
                }
                WalkParts(bDef.corePart, list);
                AccessTools.Field(typeof(BodyDef), "cachedAllParts")!.SetValue(bDef, list);
            }
            PopulateCachedAllParts(rathBody);
            PopulateCachedAllParts(scorpBody);

            for (int i = 0; i < rathRig.SortedNodes.Length && i < rathMasks.Length; i++)
            {
                if (rathMasks[i] != null && !string.IsNullOrEmpty(rathRig.SortedNodes[i].texPath))
                {
                    GiantAlphaMaskCache.RegisterMask(rathRig.SortedNodes[i].texPath, rathRig.SortedNodes[i].alphaThreshold, rathMasks[i]);
                }
            }
            for (int i = 0; i < scorpRig.SortedNodes.Length && i < scorpMasks.Length; i++)
            {
                if (scorpMasks[i] != null && !string.IsNullOrEmpty(scorpRig.SortedNodes[i].texPath))
                {
                    GiantAlphaMaskCache.RegisterMask(scorpRig.SortedNodes[i].texPath, scorpRig.SortedNodes[i].alphaThreshold, scorpMasks[i]);
                }
            }

            // Verify skinned-mesh surface layer resolution on Rathalos wing membrane (2.1 > raw bone 1.6)
            Assert(rathRig.TryGetNodeIndex("wing_inner_fan_left", out int wingFanIdx), "wing_inner_fan_left must exist");
            BoneNodeDef wingFanDef = rathRig.SortedNodes[wingFanIdx];
            Assert(wingFanDef.isRenderedBySkinnedMesh, "wing_inner_fan_left must be marked isRenderedBySkinnedMesh");
            AssertNear(wingFanDef.GetRenderedSurfaceLayerOffset(GiantBoneViewSector.Dorsal), 2.1f, 1e-4f,
                "Skinned member bone must resolve rendered surface layerOffset from owning GiantSkinnedMeshDef (2.1f)");

            var bloodFilthDef = new ThingDef
            {
                defName = "Filth_Blood",
                graphicData = new GraphicData { color = new Color32(131, 34, 34, 180) }
            };
            var organicFlesh = new RimWorld.FleshTypeDef { defName = "Normal", isOrganic = true };
            var mechFlesh = new RimWorld.FleshTypeDef { defName = "Mechanoid", isOrganic = false };
            FieldInfo fleshTypeFi = AccessTools.Field(typeof(RaceProperties), "fleshType")!;
            FieldInfo bloodDefFi = AccessTools.Field(typeof(RaceProperties), "bloodDef")!;

            var rathRace = new RaceProperties
            {
                body = rathBody,
                intelligence = Intelligence.Animal,
                baseBodySize = 6.8f,
                baseHealthScale = 7.2f,
                lifeStageAges = new List<LifeStageAge>
                {
                    new LifeStageAge { minAge = 0f, def = new RimWorld.LifeStageDef { defName = "AnimalAdult", healthScaleFactor = 1f, bodySizeFactor = 1f } }
                }
            };
            fleshTypeFi.SetValue(rathRace, organicFlesh);
            bloodDefFi.SetValue(rathRace, bloodFilthDef);

            var rathPawn = new Pawn
            {
                thingIDNumber = 909101,
                def = new ThingDef
                {
                    defName = "GCF_Rathalos",
                    race = rathRace
                },
                kindDef = new PawnKindDef { defName = "GCF_Rathalos" }
            };
            rathPawn.ageTracker = new Pawn_AgeTracker(rathPawn);
            typeof(Pawn_AgeTracker).GetField("cachedLifeStageIndex", BindingFlags.Instance | BindingFlags.NonPublic)?.SetValue(rathPawn.ageTracker, 0);
            rathPawn.health = new Pawn_HealthTracker(rathPawn);
            var rathComp = new CompGiantRig { parent = rathPawn };
            rathComp.Initialize(new CompProperties_GiantRig { rigDef = rathRig });
            rathComp.ResolveBodyPartLinks();
            GiantFastLookup.Register(rathPawn, rathComp);

            var scorpRace = new RaceProperties
            {
                body = scorpBody,
                baseBodySize = 4.2f,
                baseHealthScale = 4.0f,
                lifeStageAges = new List<LifeStageAge>
                {
                    new LifeStageAge { minAge = 0f, def = new RimWorld.LifeStageDef { defName = "MechanoidFullyFormed", healthScaleFactor = 1f, bodySizeFactor = 1f } }
                }
            };
            fleshTypeFi.SetValue(scorpRace, mechFlesh);

            var scorpPawn = new Pawn
            {
                thingIDNumber = 909102,
                def = new ThingDef
                {
                    defName = "GCF_MechScorpion",
                    race = scorpRace
                },
                kindDef = new PawnKindDef { defName = "GCF_MechScorpion" }
            };
            scorpPawn.ageTracker = new Pawn_AgeTracker(scorpPawn);
            typeof(Pawn_AgeTracker).GetField("cachedLifeStageIndex", BindingFlags.Instance | BindingFlags.NonPublic)?.SetValue(scorpPawn.ageTracker, 0);
            scorpPawn.health = new Pawn_HealthTracker(scorpPawn);
            var scorpComp = new CompGiantRig { parent = scorpPawn };
            scorpComp.Initialize(new CompProperties_GiantRig { rigDef = scorpRig });
            scorpComp.ResolveBodyPartLinks();
            GiantFastLookup.Register(scorpPawn, scorpComp);

            try
            {
                // Verify render subtree includes PawnRenderNode_GiantWoundOverlay & TryComputeGiantNodeMatrix marks it giant-owned
                List<PawnRenderNode> rathSubtree = rathComp.CompRenderNodes();
                var woundOverlayNode = rathSubtree.OfType<PawnRenderNode_GiantWoundOverlay>().SingleOrDefault();
                Assert(woundOverlayNode != null, "CompRenderNodes must include exactly one PawnRenderNode_GiantWoundOverlay");
                MethodInfo tryComputeMatMi = AccessTools.Method(typeof(HarmonyPatches_Rendering), "TryComputeGiantNodeMatrix")!;
                object[] matArgs =
                {
                    woundOverlayNode,
                    new PawnDrawParms { pawn = rathPawn, matrix = Matrix4x4.TRS(new Vector3(50f, 10f, 60f), Quaternion.Euler(0f, 45f, 0f), Vector3.one * 2f) },
                    Matrix4x4.identity,
                    false
                };
                bool okMat = (bool)tryComputeMatMi.Invoke(null, matArgs)!;
                Matrix4x4 cleanOverlayMat = (Matrix4x4)matArgs[2];
                bool isOwned = (bool)matArgs[3];
                Assert(okMat && isOwned && Mathf.Approximately(cleanOverlayMat.GetColumn(3).x, 50f),
                    "TryComputeGiantNodeMatrix must sanitize and claim PawnRenderNode_GiantWoundOverlay");

                // Uninjured Rathalos must yield 0 decals
                Assert(rathComp.GetOrRefreshWoundDecalSpecs().Count == 0, "Healthy giant must produce 0 wound decals");

                // Add bleeding cut on wing_inner_fan_left, burn on skull, and severed tail_tip
                BodyPartRecord wingPart = rathComp.GetLinkedBodyPartRaw(wingFanIdx);
                Assert(wingPart != null, "wing_inner_fan_left must resolve linked BodyPartRecord");
                bool hasSkull = rathRig.TryGetNodeIndex("skull", out int skullIdx);
                bool hasTailTip = rathRig.TryGetNodeIndex("tail_tip_spike", out int tailTipIdx);
                Assert(hasSkull && hasTailTip, "Rathalos skull and tail_tip_spike must exist");
                BodyPartRecord skullPart = rathComp.GetLinkedBodyPartRaw(skullIdx);
                BodyPartRecord tailTipPart = rathComp.GetLinkedBodyPartRaw(tailTipIdx);

                var cutDef = new HediffDef
                {
                    defName = "Cut",
                    isBad = true,
                    displayWound = true,
                    injuryProps = new InjuryProps { bleedRate = 0.06f }
                };
                var burnDef = new HediffDef
                {
                    defName = "Burn",
                    isBad = true,
                    displayWound = true,
                    injuryProps = new InjuryProps { bleedRate = 0f }
                };

                var wingCut = new Hediff_Injury { pawn = rathPawn, def = cutDef, Part = wingPart, loadID = 5001, Severity = 16f };
                var skullBurn = new Hediff_Injury { pawn = rathPawn, def = burnDef, Part = skullPart, loadID = 5002, Severity = 11f };
                var tailSever = new Hediff_MissingPart { pawn = rathPawn, def = RimWorld.HediffDefOf.MissingBodyPart ?? new HediffDef { defName = "MissingBodyPart", isBad = true }, Part = tailTipPart, loadID = 5003, IsFresh = true };
                rathPawn.health.hediffSet.hediffs.Add(wingCut);
                rathPawn.health.hediffSet.hediffs.Add(skullBurn);
                rathPawn.health.hediffSet.hediffs.Add(tailSever);
                AccessTools.Method(typeof(CompGiantRig), "RefreshMissingPartsAfterDamageOrDeath")!.Invoke(rathComp, null);

                IReadOnlyList<GiantWoundDecalSpec> rathDecals = rathComp.GetOrRefreshWoundDecalSpecs(forceRefresh: true);
                Assert(rathDecals.Count >= 4, $"Expected >= 4 decals (wing soak+slash, skull burn, tail stump), got {rathDecals.Count}");
                Assert(rathDecals.Any(d => d.boneIndex == wingFanIdx && d.kind == GiantWoundVisualKind.OrganicBloodSoak && d.tintColor.r > 0.45f && d.tintColor.r > d.tintColor.g * 5f),
                    "Heavy/bleeding organic wing cut must emit crimson OrganicBloodSoak decal");
                Assert(rathDecals.Any(d => d.boneIndex == wingFanIdx && d.kind == GiantWoundVisualKind.OrganicBloodSlash),
                    "Organic wing cut must emit crisp OrganicBloodSlash decal");
                Assert(rathDecals.Any(d => d.boneIndex == skullIdx && d.kind == GiantWoundVisualKind.OrganicBurnScorch),
                    "Thermal Burn injury must emit OrganicBurnScorch decal");
                int tailParentIdx = rathRig.SortedNodes[tailTipIdx].parentRuntimeIndex;
                Assert(rathDecals.Any(d => d.boneIndex == tailParentIdx && d.priorityScore >= 1000f && d.kind == GiantWoundVisualKind.OrganicBloodSoak),
                    "Severed tail_tip must emit high-priority arterial stump stain on intact parent tail bone");

                // Every decal's UV must lie strictly inside its bone's opaque interior pixels!
                foreach (GiantWoundDecalSpec spec in rathDecals)
                {
                    TextureAlphaMask bMask = rathMasks[spec.boneIndex];
                    Assert(bMask != null && bMask.IsOpaqueUV(spec.uvDorsal.x, spec.uvDorsal.y),
                        $"Decal on bone '{rathRig.SortedNodes[spec.boneIndex].nodeId}' at UV {spec.uvDorsal} must lie inside opaque sprite interior");
                }

                // Tending wingCut must swap it to OrganicBandaged
                wingCut.comps = new List<HediffComp>
                {
                    new HediffComp_TendDuration
                    {
                        parent = wingCut,
                        props = new HediffCompProperties_TendDuration(),
                        tendTicksLeft = 5000,
                        tendQuality = 0.8f
                    }
                };
                ProgramState prevProgState = Current.ProgramState;
                try
                {
                    Current.ProgramState = ProgramState.Playing;
                    IReadOnlyList<GiantWoundDecalSpec> tendedDecals = rathComp.GetOrRefreshWoundDecalSpecs();
                    Assert(tendedDecals.Any(d => d.boneIndex == wingFanIdx && d.kind == GiantWoundVisualKind.OrganicBandaged),
                        "Tended non-permanent organic injury must switch to OrganicBandaged decal");
                }
                finally
                {
                    Current.ProgramState = prevProgState;
                }

                // Non-organic MechScorpion must emit ONLY MechanoidBattleScar (zero red organic blood!)
                BodyPartRecord scorpPart = scorpComp.GetLinkedBodyPartRaw(0);
                scorpPawn.health.hediffSet.hediffs.Add(new Hediff_Injury { pawn = scorpPawn, def = cutDef, Part = scorpPart, loadID = 6001, Severity = 22f });
                IReadOnlyList<GiantWoundDecalSpec> mechDecals = scorpComp.GetOrRefreshWoundDecalSpecs(forceRefresh: true);
                Assert(mechDecals.Count >= 1 && mechDecals.All(d => d.kind == GiantWoundVisualKind.MechanoidBattleScar),
                    "Mechanoid giant must emit ONLY MechanoidBattleScar decals and zero organic bloodstains");

                // Verify BuildSubQuadRenderMatrix preserves exact 3D coronal foreshortening & altitude Y
                var testPoses = new BoneWorldPose[rathRig.SortedNodes.Length];
                var flapLocals = new BoneLocalPose[rathRig.SortedNodes.Length];
                for (int i = 0; i < flapLocals.Length; i++) flapLocals[i] = BoneLocalPose.Identity;
                if (rathRig.TryGetNodeIndex("wing_shoulder_left", out int wShIdx))
                {
                    flapLocals[wShIdx] = new BoneLocalPose(Vector2.zero, 0f, Vector2.one, 0f, 35f);
                }
                SkeletalKinematics.SolveWorldPoses(rathRig, new Vector2(100f, 100f), 42f, flapLocals, ReadOnlySpan<bool>.Empty, testPoses, 1f);
                ref readonly BoneWorldPose fanPose = ref testPoses[wingFanIdx];
                Vector2 expectedWorldXZ = fanPose.UVToWorldXZ(0.52f, 0.48f);
                Matrix4x4 subMat = fanPose.BuildSubQuadRenderMatrix(0.52f, 0.48f, 25f, new Vector2(0.9f, 0.8f), 9.9123f);
                Vector3 mappedOrigin = subMat.MultiplyPoint3x4(Vector3.zero);
                AssertNear(mappedOrigin.x, expectedWorldXZ.x, 1e-4f, "SubQuad X must match UVToWorldXZ under 3D coronal flap");
                AssertNear(mappedOrigin.z, expectedWorldXZ.y, 1e-4f, "SubQuad Z must match UVToWorldXZ under 3D coronal flap");
                AssertNear(mappedOrigin.y, 9.9123f, 1e-5f, "SubQuad Y altitude must remain untouched by XZ shear/foreshortening");
            }
            finally
            {
                GiantFastLookup.Unregister(rathPawn);
                GiantFastLookup.Unregister(scorpPawn);
            }

            Console.WriteLine("       -> Verified 11 crisp RGBA wound textures, skinned surface layering, interior-opaque UV placement, stump stains, bandages, mech isolation & 3D flap matrix");
        }

        private static void TestAquaticGiantsAndNavalVesselsSystem()
        {
            // 1. Default inertness & ConfigErrors validation
            var inertDef = new GiantAquaticDef();
            Assert(!inertDef.IsActive, "Default GiantAquaticDef must be strictly inert (aquaticMode == None)");
            Assert(!inertDef.ConfigErrors("TestInert").Any(), "Inert GiantAquaticDef must emit zero ConfigErrors");

            var badAllOff = new GiantAquaticDef
            {
                aquaticMode = GiantAquaticMode.WaterOnly,
                canTraverseShallowWater = false,
                canTraverseChestDeepWater = false,
                canTraverseDeepWater = false,
                canTraverseMarsh = false
            };
            Assert(badAllOff.ConfigErrors("BadAllOff").Any(e => e.Contains("disables all water tiers")),
                "WaterOnly disabling all water tiers must emit ConfigError");

            var badDeepReq = new GiantAquaticDef
            {
                aquaticMode = GiantAquaticMode.WaterOnly,
                requireDeepWater = true,
                canTraverseChestDeepWater = false,
                canTraverseDeepWater = false
            };
            Assert(badDeepReq.ConfigErrors("BadDeepReq").Any(e => e.Contains("requireDeepWater")),
                "requireDeepWater=true without chest-deep or deep water must emit ConfigError");

            var nonLoopSwim = new GiantAnimDef { defName = "BadSwimNonLoop", durationTicks = 40f, loop = false };
            var badSwimAnimDef = new GiantAquaticDef
            {
                aquaticMode = GiantAquaticMode.Amphibious,
                swimAnim = nonLoopSwim
            };
            Assert(badSwimAnimDef.ConfigErrors("BadSwim").Any(e => e.Contains("swimAnim") && e.Contains("<loop>true</loop>")),
                "Non-looping swimAnim must be caught by ConfigErrors");

            // 2. Terrain classification & WaterOnly vs Amphibious passability/cost matrix
            var soil = new TerrainDef { defName = "Soil", passability = Traversability.Standable, pathCost = 2, tags = new List<string> { "Soil" } };
            var shallow = new TerrainDef { defName = "WaterShallow", passability = Traversability.Standable, pathCost = 30, tags = new List<string> { "Water" } };
            var chestRiver = new TerrainDef { defName = "WaterMovingChestDeep", passability = Traversability.Standable, pathCost = 114, tags = new List<string> { "Water", "River" } };
            var oceanDeep = new TerrainDef { defName = "WaterOceanDeep", passability = Traversability.Impassable, pathCost = 300, waterBodyType = WaterBodyType.Saltwater, tags = new List<string> { "Water", "Ocean" } };
            var toxicDeep = new TerrainDef { defName = "ToxicWaterDeep", passability = Traversability.Impassable, pathCost = 300, toxicBuildupFactor = 0.5f, tags = new List<string> { "Water" } };
            var marsh = new TerrainDef { defName = "Marsh", passability = Traversability.Standable, pathCost = 42, tags = new List<string> { "Water", "WaterMarshy" } };
            var bridge = new TerrainDef { defName = "Bridge", passability = Traversability.Standable, pathCost = 0, bridge = true, tags = new List<string> { "Floor" } };

            var waterOnlyShip = new GiantAquaticDef
            {
                aquaticMode = GiantAquaticMode.WaterOnly,
                waterDirectPathCost = 10,
                canTraverseMarsh = false,
                blockedByBridges = true
            };
            ushort shipFlags = GiantAquaticUtility.PackCapabilityFlags(waterOnlyShip);

            int soilShipCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, shipFlags, 10, 0, GiantAquaticUtility.ClassifyTerrain(soil), out bool soilWater);
            Assert(!soilWater && soilShipCost >= GiantDestructionUtility.ImpassablePathCost,
                "WaterOnly vessel must treat dry Soil as strictly impassable (10000)");

            int marshShipCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, shipFlags, 10, 0, GiantAquaticUtility.ClassifyTerrain(marsh), out bool marshWater);
            Assert(!marshWater && marshShipCost >= GiantDestructionUtility.ImpassablePathCost,
                "WaterOnly vessel with canTraverseMarsh=false must block inland Marsh");

            int oceanShipCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, shipFlags, 10, 0, GiantAquaticUtility.ClassifyTerrain(oceanDeep), out bool oceanWater);
            Assert(oceanWater && oceanShipCost == 10,
                "WaterOnly vessel must treat WaterOceanDeep as passable with clean waterDirectPathCost=10");

            int bridgeBlockedCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, shipFlags, 10, 0, GiantAquaticUtility.ClassifyTerrain(bridge, oceanDeep), out bool bridgeBlockedWater);
            Assert(!bridgeBlockedWater && bridgeBlockedCost >= GiantDestructionUtility.ImpassablePathCost,
                "WaterOnly vessel with blockedByBridges=true must be blocked by bridges over water");

            waterOnlyShip.blockedByBridges = false;
            int bridgeOpenCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, GiantAquaticUtility.PackCapabilityFlags(waterOnlyShip), 10, 0, GiantAquaticUtility.ClassifyTerrain(bridge, oceanDeep), out bool bridgeOpenWater);
            Assert(bridgeOpenWater && bridgeOpenCost == 10,
                "WaterOnly unit with blockedByBridges=false must pass bridges over eligible water");

            waterOnlyShip.requireDeepWater = true;
            int shallowDeepDraftCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, GiantAquaticUtility.PackCapabilityFlags(waterOnlyShip), 10, 0, GiantAquaticUtility.ClassifyTerrain(shallow), out _);
            int riverChestDeepDraftCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.WaterOnly, GiantAquaticUtility.PackCapabilityFlags(waterOnlyShip), 10, 0, GiantAquaticUtility.ClassifyTerrain(chestRiver), out _);
            Assert(shallowDeepDraftCost >= GiantDestructionUtility.ImpassablePathCost && riverChestDeepDraftCost == 10,
                "requireDeepWater=true must reject WaterShallow while accepting chest-deep / deep water");

            var amphibBeast = new GiantAquaticDef
            {
                aquaticMode = GiantAquaticMode.Amphibious,
                waterDirectPathCost = 8,
                landExtraPathCost = 35,
                canTraverseToxicWater = false
            };
            ushort amphibFlags = GiantAquaticUtility.PackCapabilityFlags(amphibBeast);
            int amphibOceanCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.Amphibious, amphibFlags, 8, 35, GiantAquaticUtility.ClassifyTerrain(oceanDeep), out bool amphibOceanElig);
            int amphibSoilCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.Amphibious, amphibFlags, 8, 35, GiantAquaticUtility.ClassifyTerrain(soil), out bool amphibSoilElig);
            int amphibMarshCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.Amphibious, amphibFlags, 8, 35, GiantAquaticUtility.ClassifyTerrain(marsh), out bool amphibMarshElig);
            int amphibToxicCost = GiantAquaticUtility.EvaluateBaseTerrainCost(
                GiantAquaticMode.Amphibious, amphibFlags, 8, 35, GiantAquaticUtility.ClassifyTerrain(toxicDeep), out _);
            Assert(amphibOceanElig && amphibOceanCost == 8, "Amphibious creature must swim across WaterOceanDeep with cost 8");
            Assert(!amphibSoilElig && amphibSoilCost == 2 + 35, "Amphibious creature must walk on Soil with vanillaCost + landExtraPathCost");
            Assert(!amphibMarshElig && amphibMarshCost == 42 + 35, "Amphibious creature with canTraverseMarsh=false still walks across standable Marsh as land");
            Assert(amphibToxicCost >= GiantDestructionUtility.ImpassablePathCost, "canTraverseToxicWater=false must block impassable ToxicWaterDeep");

            // 3. GiantAquaticRuntime propulsion anatomy linkage & Naval VehicleLocomotionRuntime rudder arc steering
            var navalRig = new GiantRigDef
            {
                defName = "Test_NavalCruiser_Rig",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "hull", texPath = "Dummy/Hull", drawSize = new Vector2(6f, 14f), layerOffset = 0f },
                    new BoneNodeDef { nodeId = "screw_port", parentId = "hull", texPath = "Dummy/Screw", drawSize = Vector2.one, layerOffset = -1f, isAquaticPropulsionPart = true, locomotionSideSign = -1f },
                    new BoneNodeDef { nodeId = "screw_stbd", parentId = "hull", texPath = "Dummy/Screw", drawSize = Vector2.one, layerOffset = -1f, isAquaticPropulsionPart = true, locomotionSideSign = 1f },
                    new BoneNodeDef { nodeId = "main_turret", parentId = "hull", texPath = "Dummy/Turret", drawSize = new Vector2(2.5f, 3.5f), layerOffset = 2f, isTurret = true, maxTurretAimAngleDeg = 180f }
                },
                aquaticLocomotion = new GiantAquaticDef
                {
                    aquaticMode = GiantAquaticMode.WaterOnly,
                    waterSpeedMultiplier = 1.2f,
                    deepWaterSpeedMultiplier = 1.4f,
                    damagedPropulsionMinSpeedFactor = 0.30f,
                    immobilizeInWaterWhenPropulsionDestroyed = true,
                    buoyancyBobAmplitude = 0.06f,
                    buoyancyBobPeriodTicks = 80f
                },
                vehicleLocomotion = new VehicleLocomotionDef
                {
                    chassisType = VehicleChassisType.Naval,
                    allowPivotTurnInPlace = false,
                    minTurnRadiusCells = 4.5f,
                    movingTurnRateDegPerTick = 0.9f,
                    accelerationCellsPerSec2 = 1.6f,
                    brakingCellsPerSec2 = 2.4f,
                    allowReverse = true,
                    maxSlipAngleDeg = 0f
                }
            };
            navalRig.BuildTopology();
            Assert(navalRig.IsVehicleRig, "Naval chassisType must mark GiantRigDef.IsVehicleRig == true");
            Assert(navalRig.vehicleLocomotion.resolvedDriveBones.Length == 2,
                "Naval VehicleLocomotionDef must automatically bind isAquaticPropulsionPart bones as drive bones");

            var aqRuntime = new GiantAquaticRuntime(navalRig, navalRig.aquaticLocomotion);
            aqRuntime.ResetForSpawn(null);
            Assert(aqRuntime.IsCurrentlyInWater && aqRuntime.IsInDeepWater, "Unspawned WaterOnly runtime defaults to deep-water state");
            AssertNear(aqRuntime.ComputeEffectiveSurfaceSpeedMultiplier(), 1.4f, 1e-4f, "Intact Naval propulsion in deep water must yield deepWaterSpeedMultiplier=1.4");

            // Sever one screw -> reduced speed; sever both screws -> immobilized in water
            bool[] oneMissing = { false, true, false, false };
            float[] fullHp = { 1f, 0f, 1f, 1f };
            aqRuntime.RefreshEnvironmentAndPropulsion(null, oneMissing, fullHp);
            float halfPropMult = aqRuntime.ComputeEffectiveSurfaceSpeedMultiplier();
            Assert(halfPropMult > 0.4f && halfPropMult < 1.4f, $"Half propulsion must degrade speed smoothly (got {halfPropMult:F3})");

            bool[] bothMissing = { false, true, true, false };
            aqRuntime.RefreshEnvironmentAndPropulsion(null, bothMissing, fullHp);
            Assert(aqRuntime.IsPropulsionImmobilized && aqRuntime.ComputeEffectiveSurfaceSpeedMultiplier() <= 0.01f,
                "Destroying all screws with immobilizeInWaterWhenPropulsionDestroyed=true must immobilize vessel in water");

            // Step Naval rudder arc headless along a 90-degree turn: zero lateral crab-slide & non-zero forward travel
            var navalVeh = new VehicleLocomotionRuntime(navalRig, navalRig.vehicleLocomotion);
            navalVeh.Reset(0f, new Vector2(20f, 20f));
            Vector2[] seaWaypoints = { new Vector2(20f, 20f), new Vector2(20f, 30f), new Vector2(36f, 30f) };
            bool[] intactMask = { false, false, false, false };
            float[] intactHp = { 1f, 1f, 1f, 1f };
            float maxAbsLateralDrift = 0f;
            for (int t = 0; t < 220; t++)
            {
                navalVeh.StepHeadlessAlongPath(seaWaypoints, 4.2f, intactMask, intactHp);
                maxAbsLateralDrift = Mathf.Max(maxAbsLateralDrift, Mathf.Abs(navalVeh.LastStepLateralDriftCells));
            }
            Assert(maxAbsLateralDrift < 1e-5f, $"Naval hull with maxSlipAngleDeg=0 must have 0 crab-slide (got {maxAbsLateralDrift})");
            Assert(navalVeh.HullHeadingDeg > 35f && navalVeh.HullHeadingDeg < 130f,
                $"Rudder-steered Naval hull must arc smoothly toward East leg (heading={navalVeh.HullHeadingDeg:F1})");

            // 4. World globe tile eligibility
            Assert(GiantAquaticUtility.IsWorldTilePassableForAquatic(waterOnlyShip, isWaterCovered: true, isImpassableHilliness: false, isCoastal: false, hasRiver: false),
                "WaterOnly ship must pass ocean/lake world tiles");
            Assert(GiantAquaticUtility.IsWorldTilePassableForAquatic(waterOnlyShip, isWaterCovered: false, isImpassableHilliness: false, isCoastal: true, hasRiver: false),
                "WaterOnly ship must pass coastal world tiles when allowCoastalWorldTiles=true");
            Assert(GiantAquaticUtility.IsWorldTilePassableForAquatic(waterOnlyShip, isWaterCovered: false, isImpassableHilliness: false, isCoastal: false, hasRiver: true),
                "WaterOnly ship must pass river world tiles when allowRiverWorldTiles=true");
            Assert(!GiantAquaticUtility.IsWorldTilePassableForAquatic(waterOnlyShip, isWaterCovered: false, isImpassableHilliness: false, isCoastal: false, hasRiver: false),
                "WaterOnly ship must reject landlocked inland dry world tiles");
            Assert(GiantAquaticUtility.IsWorldTilePassableForAquatic(amphibBeast, isWaterCovered: true, isImpassableHilliness: false, isCoastal: false, hasRiver: false)
                && GiantAquaticUtility.IsWorldTilePassableForAquatic(amphibBeast, isWaterCovered: false, isImpassableHilliness: false, isCoastal: false, hasRiver: false),
                "Amphibious giant must pass both ocean and inland world tiles");

            // 5. Four-language localization parity for all GCF_Aquatic* keys
            string[] aqKeys =
            {
                "GCF_AquaticMode_WaterOnly",
                "GCF_AquaticMode_Amphibious",
                "GCF_AquaticState_DeepWater",
                "GCF_AquaticState_ShallowWater",
                "GCF_AquaticState_Ashore",
                "GCF_AquaticInspectLine",
                "GCF_AquaticInspectLineWithPropulsion",
                "GCF_AquaticWorldFail_InvalidDestination",
                "GCF_AquaticWorldFail_NoWaterRoute",
                "GCF_AquaticFail_NoWaterOnMap"
            };
            foreach (string lang in new[] { "ChineseSimplified", "English", "Japanese", "Russian" })
            {
                var keyed = LoadMergedKeyedMap(lang);
                foreach (string k in aqKeys)
                {
                    Assert(keyed.TryGetValue(k, out string val) && !string.IsNullOrWhiteSpace(val),
                        $"Language '{lang}' missing or empty keyed string '{k}'");
                }
            }

            Console.WriteLine("       -> Verified GiantAquaticDef validation, WaterOnly/Amphibious terrain & bridge/marsh/draft matrix, propulsion severing, Naval rudder arc kinematics, world ocean/coastal rules & 4-language keys");
        }

        private static void TestAnimalGiantHitReactionDynamicsAndSafety()
        {
            var rig = new GiantRigDef
            {
                defName = "Test_AnimalHitReactionRig",
                nodes = new List<BoneNodeDef>
                {
                    new BoneNodeDef { nodeId = "torso", drawSize = new Vector2(3f, 4f) },
                    new BoneNodeDef { nodeId = "neck", parentId = "torso", drawSize = new Vector2(1.4f, 1.8f), parentSocketUV = new Vector2(0.5f, 0.85f), sagittalDropCells = 0.6f },
                    new BoneNodeDef { nodeId = "head", parentId = "neck", drawSize = new Vector2(1.3f, 1.5f), parentSocketUV = new Vector2(0.5f, 0.85f), sagittalDropCells = 0.5f },
                    new BoneNodeDef { nodeId = "horn_rigid", parentId = "head", drawSize = new Vector2(0.5f, 0.5f), isRigid = true },
                    new BoneNodeDef { nodeId = "wing_left", parentId = "torso", drawSize = new Vector2(3.0f, 2.2f), parentSocketUV = new Vector2(0.2f, 0.65f), isCoronalFlapHinge = true },
                    new BoneNodeDef { nodeId = "wing_right", parentId = "torso", drawSize = new Vector2(3.0f, 2.2f), parentSocketUV = new Vector2(0.8f, 0.65f), isCoronalFlapHinge = true },
                    new BoneNodeDef { nodeId = "leg_front_left", parentId = "torso", drawSize = new Vector2(1.0f, 1.4f), parentSocketUV = new Vector2(0.25f, 0.72f), sagittalDropCells = 0.9f },
                    new BoneNodeDef { nodeId = "tail_base", parentId = "torso", drawSize = new Vector2(1.0f, 2.0f), parentSocketUV = new Vector2(0.5f, 0.12f) },
                    new BoneNodeDef { nodeId = "tail_tip", parentId = "tail_base", drawSize = new Vector2(0.8f, 1.8f), parentSocketUV = new Vector2(0.5f, 0.10f) }
                }
            };
            rig.BuildTopology();

            int n = rig.SortedNodes.Length;
            int headIdx = rig.TryGetNodeIndex("head", out int hIdx) ? hIdx : 2;
            int hornIdx = rig.TryGetNodeIndex("horn_rigid", out int rIdx) ? rIdx : 3;
            int wingLIdx = rig.TryGetNodeIndex("wing_left", out int wlIdx) ? wlIdx : 4;
            int legIdx = rig.TryGetNodeIndex("leg_front_left", out int lIdx) ? lIdx : 6;
            bool[] intact = new bool[n];
            var poses = new BoneLocalPose[n];
            for (int i = 0; i < n; i++) poses[i] = BoneLocalPose.Identity;

            var runtime = new GiantHitReactionRuntime(n);
            Assert(!runtime.IsActive, "Hit reaction runtime must start idle (zero per-tick cost)");

            // 1. Directional check: heading North (0 deg), blow pushing East (+X, hit came from West/Left) on head
            var leftBlow = new GiantHitImpulseInput
            {
                HitBoneIndex = headIdx,
                HitSoftWhipIndex = -1,
                WorldPushDirXZ = Vector2.right,
                BodyHeadingDeg = 0f,
                DamageAmount = 22f,
                HitPartMaxHp = 200f,
                TotalBodyMaxHp = 1200f,
                PawnBodySize = 6f,
                DamageCategory = GiantHitDamageCategory.SharpOrBallistic,
                GameTick = 100
            };
            GiantHitChainImpulseOutput outLeft = runtime.TriggerHit(rig, in leftBlow, intact);
            Assert(outLeft.Tier == GiantHitReactionTier.LocalFlinch, $"Expected LocalFlinch, got {outLeft.Tier}");
            Assert(runtime.IsActive, "Runtime must activate upon hit");

            for (int i = 0; i < n; i++) poses[i] = BoneLocalPose.Identity;
            runtime.StepAndApply(rig, 2f, poses, intact, isFullBodyAttacking: false, isDowned: false);
            Assert(poses[0].offset.x > 0.01f, $"Eastward push must shift root offset +X (got {poses[0].offset.x:F4})");
            Assert(poses[headIdx].angle > 1.0f, $"Eastward blow on anterior head must twist head clockwise +angle (got {poses[headIdx].angle:F3})");
            AssertNear(poses[hornIdx].angle, 0f, 1e-5f, "isRigid child bone must strictly retain 0 deg angle");
            AssertNear(poses[hornIdx].offset.magnitude, 0f, 1e-5f, "isRigid child bone must strictly retain 0 offset");
            for (int i = 0; i < n; i++)
            {
                AssertNear(poses[i].scale.x, 1f, 1e-5f, $"Bone {i} scale.x must remain untouched");
                AssertNear(poses[i].scale.y, 1f, 1e-5f, $"Bone {i} scale.y must remain untouched");
            }

            // 2. Opposite direction check: blow pushing West (-X) flips root X and head angle sign
            runtime.Reset();
            var rightBlow = leftBlow;
            rightBlow.WorldPushDirXZ = Vector2.left;
            rightBlow.GameTick = 200;
            runtime.TriggerHit(rig, in rightBlow, intact);
            for (int i = 0; i < n; i++) poses[i] = BoneLocalPose.Identity;
            runtime.StepAndApply(rig, 2f, poses, intact, isFullBodyAttacking: false, isDowned: false);
            Assert(poses[0].offset.x < -0.01f, $"Westward push must shift root offset -X (got {poses[0].offset.x:F4})");
            Assert(poses[headIdx].angle < -1.0f, $"Westward blow on anterior head must twist head counter-clockwise -angle (got {poses[headIdx].angle:F3})");

            // 3. Tier classification: Micro vs Heavy (single blunt hit) vs Poise-Break vs PartBreakStagger
            runtime.Reset();
            var microHit = leftBlow;
            microHit.DamageAmount = 1.5f;
            microHit.GameTick = 300;
            Assert(runtime.TriggerHit(rig, in microHit, intact).Tier == GiantHitReactionTier.Micro, "Tiny chip damage must classify as Micro");

            runtime.Reset();
            var heavyHit = leftBlow;
            heavyHit.DamageAmount = 60f;
            heavyHit.DamageCategory = GiantHitDamageCategory.BluntOrExplosive;
            heavyHit.GameTick = 400;
            GiantHitChainImpulseOutput outHeavy = runtime.TriggerHit(rig, in heavyHit, intact);
            Assert(outHeavy.Tier == GiantHitReactionTier.HeavyFlinch, $"Heavy blunt blow must trigger HeavyFlinch (got {outHeavy.Tier})");
            for (int i = 0; i < n; i++) poses[i] = BoneLocalPose.Identity;
            runtime.StepAndApply(rig, 2.5f, poses, intact, isFullBodyAttacking: false, isDowned: false);
            Assert(Mathf.Abs(poses[wingLIdx].coronalFlap) > 1.0f, $"Heavy hit must trigger coronal wing flare on hinge bone (got {poses[wingLIdx].coronalFlap:F3})");
            Assert(Mathf.Abs(poses[legIdx].sagittalPitch) > 0.5f, $"Heavy hit must trigger sagittal leg brace (got {poses[legIdx].sagittalPitch:F3})");

            // 4. Rapid-fire stability (25 consecutive hits) + attack attenuation + damped full settling
            runtime.Reset();
            float peakOff = 0f;
            float peakBoneAng = 0f;
            for (int t = 0; t < 25; t++)
            {
                var rapid = leftBlow;
                rapid.GameTick = 600 + t;
                rapid.DamageAmount = 14f;
                runtime.TriggerHit(rig, in rapid, intact);
                for (int i = 0; i < n; i++) poses[i] = BoneLocalPose.Identity;
                runtime.StepAndApply(rig, 1f, poses, intact, isFullBodyAttacking: false, isDowned: false);
                Assert(!float.IsNaN(poses[0].offset.x) && !float.IsInfinity(poses[0].offset.x), "Root offset must never become NaN/Inf");
                peakOff = Mathf.Max(peakOff, poses[0].offset.magnitude);
                peakBoneAng = Mathf.Max(peakBoneAng, Mathf.Abs(poses[headIdx].angle));
            }
            Assert(runtime.CurrentRapidHitHeat > 0.5f, "Rapid hits must build rapidHitHeat suppression");
            Assert(peakOff <= 0.53f, $"Root offset must stay tightly clamped under rapid fire (got {peakOff:F3})");
            Assert(peakBoneAng <= 34.1f, $"Bone angle must stay clamped under rapid fire (got {peakBoneAng:F2})");

            // Step until settled back to zero
            for (int t = 0; t < 160; t++)
            {
                for (int i = 0; i < n; i++) poses[i] = BoneLocalPose.Identity;
                runtime.StepAndApply(rig, 1f, poses, intact, isFullBodyAttacking: false, isDowned: false);
            }
            Assert(!runtime.IsActive, "Spring solver must damp cleanly back to inactive zero-cost state");
            AssertNear(runtime.CurrentRootOffsetLocal.magnitude, 0f, 1e-4f, "Settled root offset must return to 0");
            AssertNear(runtime.CurrentRootAngleDeg, 0f, 1e-4f, "Settled root angle must return to 0");

            // 5. Missing bone strict zeroing + attack attenuation
            runtime.Reset();
            var breakHit = leftBlow;
            breakHit.GameTick = 900;
            breakHit.ForceTierOverride = true;
            breakHit.ForcedTier = GiantHitReactionTier.PartBreakStagger;
            bool[] missingHead = new bool[n];
            missingHead[headIdx] = true;
            runtime.TriggerHit(rig, in breakHit, missingHead);
            var idlePoses = new BoneLocalPose[n];
            var atkPoses = new BoneLocalPose[n];
            for (int i = 0; i < n; i++) { idlePoses[i] = BoneLocalPose.Identity; atkPoses[i] = BoneLocalPose.Identity; }
            runtime.StepAndApply(rig, 2f, idlePoses, missingHead, isFullBodyAttacking: false, isDowned: false);
            runtime.StepAndApply(rig, 0f, atkPoses, missingHead, isFullBodyAttacking: true, isDowned: false);
            AssertNear(idlePoses[headIdx].angle, 0f, 1e-5f, "Missing bone must not receive hit reaction offsets");
            Assert(Mathf.Abs(atkPoses[wingLIdx].coronalFlap) < Mathf.Abs(idlePoses[wingLIdx].coronalFlap),
                "Full-body attacking state must attenuate flinch amplitude");

            Console.WriteLine("       -> Verified 4-tier animal hit reaction spring-damper, directional torque, rigid/scale invariance, rapid-fire clamping, full settling & attack attenuation");
        }

        private sealed class TestFreshMissingPartHediff : Hediff_MissingPart
        {
            public float MockPainOffset;
            public override float PainOffset => MockPainOffset;
        }
    }
}

